import difflib
import hashlib
import json
import math
import os
from pathlib import Path
import re
import shutil
import statistics
import subprocess
import sys
import tempfile
import uuid
import time
import urllib.error
import urllib.parse
import urllib.request

VIDEO_EXT = {'.mp4', '.mov', '.mkv', '.webm', '.avi', '.m4v', '.ts'}
DOC_EXT = {'.txt', '.md', '.pdf', '.docx', '.rtf', '.json'}
IMAGE_EXT = {'.jpg', '.jpeg', '.png', '.webp', '.heic'}
ROOT = Path(__file__).resolve().parent.parent
SCHEMA = 'static-youtube-longform-v1'
DEFAULT_MIN_LONGFORM = 480
# Reference analysis samples two frames per second (state.json analysis_fps, set when the run is made), each frame
# picked by and kept with its own source timestamp (analysis_sampler). A run keeps the rate and the sampler its
# references were analysed with, so its references and its own export are measured on one yardstick; a run whose
# state predates these settings was analysed at 5 fps with nominal slot times. The generated video's frame rate
# (format.fps), the CapCut timeline and the export are separate and unchanged.
ANALYSIS_FPS = 2.0
LEGACY_ANALYSIS_FPS = 5.0
ANALYSIS_SAMPLER = 'pts-v1'     # = av_tools.SAMPLER
LEGACY_SAMPLER = 'nominal'      # frames numbered at a fixed rate, their times read from the numbers


def run_analysis_fps(st):
    return float(st.get('analysis_fps') or LEGACY_ANALYSIS_FPS)


def run_analysis_sampler(st):
    return str(st.get('analysis_sampler') or LEGACY_SAMPLER)


def parse_clock(s):
    """Seconds from 75, '75.5', '01:15', '01:15.5' or '1:01:15'; None when it is none of these."""
    if s is None or isinstance(s, bool):
        return None
    if isinstance(s, (int, float)):
        return float(s)
    s = str(s).strip()
    m = re.fullmatch(r'(?:(\d+):)?(\d{1,3}):(\d{1,2}(?:\.\d+)?)', s)
    if m:
        return int(m.group(1) or 0) * 3600 + int(m.group(2)) * 60 + float(m.group(3))
    try:
        return float(s)
    except ValueError:
        return None


def parse_span(s):
    """(start_s, end_s) of 'mm:ss-mm:ss', of {'from', 'to'}, or of one time (t, t); (None, None) when unreadable."""
    if isinstance(s, dict):
        a, b = parse_clock(s.get('from')), parse_clock(s.get('to'))
    else:
        parts = [x.strip() for x in str(s or '').split('-') if x.strip()]
        if len(parts) == 1:
            a = b = parse_clock(parts[0])
        elif len(parts) == 2:
            a, b = parse_clock(parts[0]), parse_clock(parts[1])
        else:
            a = b = None
    if a is None or b is None or b < a:
        return None, None
    return a, b


def emit(data, code=0):
    print(json.dumps(data, ensure_ascii=False, indent=2, default=str))
    if code:
        sys.exit(code)


def error(message, details=None):
    emit({'ok': False, 'error': message, 'details': details}, 2)


def read_json(path, required=False):
    """A JSON record as a dict; {} when the file is not there (or holds something other than an object). A file that
    IS there and cannot be parsed stops the command and is named: an empty answer would let the check that reads it
    pass, or start over what was already done (2026-11-26: a damaged narration manifest read as "nothing recorded
    yet" would have re-sent, and billed, every part; a damaged lock or budget register would have let a second paid
    job through). A byte-order mark is not damage."""
    try:
        raw = Path(path).read_text(encoding='utf-8-sig')
    except UnicodeDecodeError as exc:
        raw, bad = None, str(exc)
    except OSError as exc:
        if required:
            error('Cannot read JSON', {'file': str(path), 'reason': str(exc)})
        return {}
    if raw is not None:
        try:
            obj = json.loads(raw)
        except ValueError as exc:
            obj, bad = None, str(exc)
        else:
            if isinstance(obj, dict):
                return obj
            if required:
                error('Cannot read JSON', {'file': str(path), 'reason': 'expected JSON object'})
            return {}
    error('A record cannot be read: the file is there but is not valid JSON (damaged, or half-written). Nothing was '
          'changed. Restore it (its .bak, its history, or the step that writes it), or remove it if it should not exist.',
          {'file': str(path), 'reason': bad[:200]})


def write_json(path, obj):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name('.' + path.name + '.tmp')
    temp.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    temp.replace(path)


def now():
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec='seconds')


def elevenlabs_key():
    # PC adapter: this PC's pipelines keep the ElevenLabs key in ELEVEN_API_KEY; the package's own name is still read first.
    return os.environ.get('ELEVENLABS_API_KEY') or os.environ.get('ELEVEN_API_KEY') or ''


def run_cmd(cmd, timeout=None):
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, check=False,
                                encoding='utf-8', errors='replace')
    except (FileNotFoundError, subprocess.TimeoutExpired) as exc:
        raise RuntimeError(f'{cmd[0]} execution failed: {exc}') from exc
    if result.returncode:
        raise RuntimeError((result.stderr or result.stdout or f'{cmd[0]} error')[-1000:])
    return result.stdout


def probe(path):
    j = json.loads(run_cmd(['ffprobe', '-v', 'error', '-show_format', '-show_streams',
                            '-of', 'json', str(path)], timeout=35))
    streams = j.get('streams', [])
    v = next((s for s in streams if s.get('codec_type') == 'video'), None)
    a = next((s for s in streams if s.get('codec_type') == 'audio'), None)
    fmt = j.get('format', {})
    dur = float(fmt.get('duration') or (v or a or {}).get('duration') or 0)
    fps = (v or {}).get('avg_frame_rate', '0/0')
    try:
        numer, denom = [int(x) for x in fps.split('/')]
        fps = round(numer / denom, 3) if denom else None
    except (ValueError, AttributeError):
        fps = None
    return {'duration_s': round(dur, 3), 'has_video': v is not None,
            'has_audio': a is not None, 'width': (v or {}).get('width'),
            'height': (v or {}).get('height'), 'fps': fps,
            'video_codec': (v or {}).get('codec_name'), 'audio_codec': (a or {}).get('codec_name')}


def run_folder(args):
    rd = Path(args.run).expanduser().resolve()
    st = read_json(rd / 'state.json', required=True)
    if st.get('schema') != SCHEMA:
        error('Not a Static Studio run; do not overwrite a legacy run', str(rd))
    return rd, st


def quick_fingerprint(path):
    h = hashlib.sha256()
    size = path.stat().st_size
    with path.open('rb') as f:
        h.update(f.read(256 * 1024))
        if size > 512 * 1024:
            f.seek(max(0, size - 256 * 1024))
            h.update(f.read(256 * 1024))
    return h.hexdigest()[:20] + ':' + str(size)


def file_sha256(path):
    """The whole file's content hash: what ties a cut to the exact approved narration (a quick fingerprint reads only
    the ends of a file)."""
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda: f.read(1 << 20), b''):
            h.update(block)
    return h.hexdigest()


def cmd_doctor(args):
    checks = {'python': sys.version.split()[0], 'python_executable': sys.executable,
              'ffmpeg': shutil.which('ffmpeg') is not None,
              'ffprobe': shutil.which('ffprobe') is not None,
              'elevenlabs_api_key_set': bool(elevenlabs_key())}
    try:
        import faster_whisper  # noqa
        checks['faster_whisper'] = True
    except ImportError:
        checks['faster_whisper'] = False
    try:
        from PIL import Image  # noqa
        checks['pillow'] = True
    except ImportError:
        checks['pillow'] = False
    for mod, name in (('numpy', 'numpy'), ('cv2', 'opencv'), ('librosa', 'librosa'), ('soundfile', 'soundfile')):
        try:
            __import__(mod)
            checks[name] = True
        except ImportError:
            checks[name] = False
    checks['av_profile_ready'] = all(checks.get(k) for k in ('numpy', 'opencv', 'librosa', 'soundfile', 'pillow'))
    dirs = cuda_dll_dirs()
    checks['cuda_dll_dirs'] = dirs
    # a fresh terminal (opened after the user PATH got these folders) has them; an older process gets them in-process
    checks['cuda_dirs_on_this_process_path'] = len(_on_path(dirs)) == len(dirs) and bool(dirs)
    try:
        import ctranslate2
        checks['ctranslate2'] = ctranslate2.__version__
        checks['cuda_devices'] = ctranslate2.get_cuda_device_count()
    except ImportError:
        checks['ctranslate2'] = None
    ok = checks['ffmpeg'] and checks['ffprobe']
    if args.whisper:
        model, eng = whisper_model('medium', WHISPER_DEVICE, WHISPER_COMPUTE)   # a failure stops here, with its cause
        checks['whisper'] = {k: v for k, v in eng.items() if k != 'cuda_dll_dirs'}
        if args.file:
            import tempfile
            src = Path(args.file).expanduser().resolve()
            if not src.is_file():
                error('File not found', str(src))
            with tempfile.TemporaryDirectory() as tmp:
                out = Path(tmp) / 'probe.json'
                transcribe(src, out, 'medium', WHISPER_DEVICE, WHISPER_COMPUTE)
                tj = read_json(out)
            words = transcript_words(tj)
            checks['whisper_file'] = {'file': str(src), 'duration_s': tj.get('duration_s'), 'language': tj.get('language'),
                                      'segments': len(tj.get('segments') or []), 'words': len(words),
                                      'elapsed_s': tj.get('elapsed_s'), 'realtime_x': tj.get('realtime_x'),
                                      'device': (tj.get('engine') or {}).get('device'),
                                      'first_words': ' '.join(w['text'].strip() for w in words[:24])}
        ok = ok and checks['whisper']['device'] == 'cuda'
    emit({'ok': ok, 'checks': checks,
          'note': 'Whisper medium runs on the GPU for every transcription (doctor --whisper loads it and runs it once; '
                  '--file also transcribes that file). av-profile (watch sheets, delivery measurements) needs numpy, '
                  'opencv, librosa, soundfile and pillow; image/CapCut/TTS tools are checked separately.'})


def cmd_init(args):
    ref = Path(args.references).expanduser().resolve()
    if not ref.is_dir():
        error('References directory missing', str(ref))
    root = Path(args.workspace).expanduser().resolve() if args.workspace else ROOT / 'runs'
    if ref == root or ref in root.parents or root in ref.parents:
        error('The run folder must be separate from source references; sources remain read-only.')
    slug = re.sub(r'[^a-z0-9-]+', '-', args.slug.lower()).strip('-')[:45] or 'narrative'
    stamp = dt.datetime.now(dt.timezone.utc).strftime('%Y%m%d-%H%M%S')
    rd = root / (stamp + '-' + slug)
    index = 2
    while rd.exists():
        rd = root / (stamp + '-' + slug + '-' + str(index))
        index += 1
    for d in ['00-inventory', '10-media', '20-analysis/cards', '20-analysis/cohorts',
              '30-research', '40-plans', '50-audio', '60-visuals', '70-edit', '80-deliverables', 'logs']:
        (rd / d).mkdir(parents=True, exist_ok=True)
    st = {'schema': SCHEMA, 'run_id': rd.name, 'created_at': now(), 'source_references': str(ref),
          'stage': 'intake', 'selected_niche': None, 'video_count': 0,
          'format': {'platform': 'YouTube long-form', 'aspect': '16:9', 'width': 1920, 'height': 1080, 'fps': 30},
          'analysis_fps': args.fps, 'analysis_sampler': ANALYSIS_SAMPLER, 'min_longform_s': args.min_longform,
          'niche_discovery': NICHE_DISCOVERY,
          'notes': 'Static only. Agents invent new subjects within the chosen niche; references teach form, not copied content.'}
    write_json(rd / 'state.json', st)
    (rd / 'todo.md').write_text('# Static Studio run\n\n- [ ] Inventory and prepare references (av-profile: watch them as films)\n- [ ] Split the analysis by reading work (analysis-plan); analyse every reference (card, notes, content review)\n- [ ] Discover the niches (niche-evidence, niche-map.json, niche-synthesis.md, niche-check); the user picks; niche-lock\n- [ ] Lock comparable long-form length (a cohort of the locked niche, or own minutes)\n- [ ] Research the story; creative direction: approaches, treatments, blind read, direction-lock (before the script)\n- [ ] Beat directions and script; cold read with every finding answered; plan-check\n- [ ] Record complete narration (calibration part first: pace and delivery per beat)\n- [ ] Design and assemble image-led edit (shot-check, retime-shots)\n- [ ] Export; final watch review answered; release-check\n', encoding='utf-8')
    emit({'ok': True, 'run': str(rd), 'next': 'scan --run "' + str(rd) + '"'})


def cmd_clone(args):
    src, previous = run_folder(argparse.Namespace(run=args.from_run))
    import tempfile
    tmp = argparse.Namespace(references=previous['source_references'], workspace=args.workspace,
                            slug=args.slug, fps=ANALYSIS_FPS,
                            min_longform=previous.get('min_longform_s', DEFAULT_MIN_LONGFORM))
    # Make a new independent Static run; do not share mutable audio or output files.
    ref = Path(tmp.references)
    if not ref.is_dir():
        error('Source references no longer exist; cannot safely clone analysis.', str(ref))
    root = Path(tmp.workspace).expanduser().resolve() if tmp.workspace else ROOT / 'runs'
    slug = re.sub(r'[^a-z0-9-]+', '-', tmp.slug.lower()).strip('-')[:45] or 'clone'
    stamp = dt.datetime.now(dt.timezone.utc).strftime('%Y%m%d-%H%M%S')
    rd = root / (stamp + '-' + slug)
    idx = 2
    while rd.exists():
        rd = root / (stamp + '-' + slug + '-' + str(idx)); idx += 1
    for d in ['00-inventory', '10-media', '20-analysis/cards', '20-analysis/cohorts',
              '30-research', '40-plans', '50-audio', '60-visuals', '70-edit', '80-deliverables', 'logs']:
        (rd / d).mkdir(parents=True, exist_ok=True)
    st = {k:v for k,v in previous.items() if k not in ('selected_niche','selected_niche_id','video_count','stage',
                                                      'created_at','run_id')}
    st.update({'selected_niche': None, 'video_count': 0, 'stage': 'reference_analysis_complete',
               'niche_discovery': NICHE_DISCOVERY,
               'run_id': rd.name, 'created_at': now(), 'cloned_from': str(src),
               # frames are not cloned: the clone's references are prepared again, at the current analysis rate
               'analysis_fps': ANALYSIS_FPS, 'analysis_sampler': ANALYSIS_SAMPLER})
    write_json(rd/'state.json', st)
    # the niches the source run discovered are about the same references (the pick is not: the clone picks again)
    for oldrel in ['00-inventory/references.json', '20-analysis/cohorts/index.json', '20-analysis/niche-map.json',
                   '20-analysis/niche-evidence.json', '20-analysis/niche-evidence.md']:
        old = src/oldrel
        if old.is_file():
            target = rd/oldrel; target.parent.mkdir(parents=True, exist_ok=True); shutil.copy2(old, target)
    for card in (src/'20-analysis/cards').glob('V*.json'):
        shutil.copy2(card, rd/'20-analysis/cards'/card.name)
    for plan in (src/'20-analysis/agents').glob('plan-r*.json'):
        (rd/'20-analysis/agents').mkdir(parents=True, exist_ok=True)
        shutil.copy2(plan, rd/'20-analysis/agents'/plan.name)
    # The content reviews are analysis too (their times are the source's, whatever the sampling rate), with the
    # records of their closer looks (index.json only: frames of a closer look are never copied).
    for review in (src/'20-analysis/content').glob('V*.json'):
        (rd/'20-analysis/content').mkdir(parents=True, exist_ok=True)
        shutil.copy2(review, rd/'20-analysis/content'/review.name)
    for idx in (src/'20-analysis/inspect').glob('*/*/index.json'):
        target = rd/idx.relative_to(src)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(idx, target)
    (rd/'todo.md').write_text('# Cloned Static analysis\n\n- [ ] prepare + av-profile the references again (frames and transcripts are not cloned)\n- [ ] niche-evidence and niche-check on the copied niche map (revise it if the analyses changed); the user picks; niche-lock; a new video length\n- [ ] Creative direction and lock before the script; cold read; then produce (create-video.md D-G)\n', encoding='utf-8')
    emit({'ok': True, 'run': str(rd), 'source_run': str(src), 'note': 'Only analyses are reused. Source media is read-only; production assets remain independent.'})


def cmd_scan(args):
    rd, st = run_folder(args)
    ref = Path(st['source_references'])
    old = read_json(rd / '00-inventory/references.json')
    prev_by_path = {x['relative_path']: x for x in old.get('items', [])}
    items = []
    counters = {'video': max([int(x['id'][1:]) for x in old.get('items', []) if x['id'].startswith('V')] or [0]),
                'image': max([int(x['id'][1:]) for x in old.get('items', []) if x['id'].startswith('I')] or [0]),
                'document': max([int(x['id'][1:]) for x in old.get('items', []) if x['id'].startswith('D')] or [0])}
    seen = {}
    errors = []
    for path in sorted(ref.rglob('*')):
        if not path.is_file() or path.name.startswith('.'):
            continue
        suffix = path.suffix.lower()
        kind = ('video' if suffix in VIDEO_EXT else 'image' if suffix in IMAGE_EXT else
                'document' if suffix in DOC_EXT else None)
        if not kind:
            continue
        rel = path.relative_to(ref).as_posix()
        oldrow = prev_by_path.get(rel)
        if oldrow and oldrow.get('kind') == kind:
            ident = oldrow['id']
        else:
            counters[kind] += 1
            ident = {'video': 'V', 'image': 'I', 'document': 'D'}[kind] + f'{counters[kind]:03d}'
        row = {'id': ident, 'relative_path': rel, 'kind': kind, 'source_path': str(path),
               'size_bytes': path.stat().st_size, 'fingerprint': quick_fingerprint(path)}
        if kind == 'video':
            try:
                row.update(probe(path))
                if row['duration_s'] <= 0 or not row['has_video']:
                    errors.append({'id': ident, 'error': 'video has no valid duration/stream'})
            except (RuntimeError, ValueError) as exc:
                errors.append({'id': ident, 'error': str(exc)[:240]})
        dedup_key = (kind, row['fingerprint'])
        if dedup_key in seen:
            row['duplicate_of'] = seen[dedup_key]
        else:
            seen[dedup_key] = ident
        items.append(row)
    inv = {'schema': SCHEMA, 'references_dir': str(ref), 'scanned_at': now(), 'items': items, 'errors': errors}
    write_json(rd / '00-inventory/references.json', inv)
    emit({'ok': not errors, 'run': str(rd), 'counts': {k: sum(x['kind'] == k for x in items)
          for k in counters}, 'duplicates': sum('duplicate_of' in x for x in items), 'errors': errors,
          'source_read_only': True}, 2 if errors else 0)


# Whisper is medium (the user's rule for all audio) and runs on the GPU: CTranslate2 (faster-whisper) with the CUDA 12
# runtime pip installed for this interpreter (nvidia-cublas-cu12, nvidia-cudnn-cu12, nvidia-cuda-nvrtc-cu12). The CPU
# is used only on the user's explicit yes (--device cpu --cpu-approved "..."), never as a silent fallback: a GPU that
# cannot run stops the command with what is missing. One model per process, loaded once for every file it hears.
WHISPER_MODELS = ('medium',)
WHISPER_DEVICE, WHISPER_COMPUTE = 'cuda', 'float16'
_WHISPER = {}
_DLL_DIRS = []
_CPU_APPROVAL = None
# The GPU lease of a Whisper job (gpu_lease.py, beside this file): medium in float16 holds about 2.2 GB. Before the model
# loads, the job waits as long as whoever holds the card warrants (gpu_lease.py: an earlier GPU job until it ends,
# a recorder while it lets its Whisper go, another program only briefly), said on stderr, then it goes ahead
# on the GPU: the lease never changes the device, the model or the precision, and there is none on the CPU. It says how
# long it expects to hold the card: WHISPER_LOAD_S to load, a file's length over WHISPER_SPEED to transcribe it.
WHISPER_GPU_NEED_MB, WHISPER_LOAD_S, WHISPER_SPEED = 2200, 60.0, 6.0


def whisper_gpu_lease(model_name, device, compute_type, doing, seconds=None):
    """The GPU lease of one Whisper job, a gpu_lease.Lease (a context manager; release() lets it go, and so does the end
    of the process): it waits only while the model is not loaded yet. On the CPU it holds nothing."""
    here = str(Path(__file__).resolve().parent)
    if here not in sys.path:
        sys.path.insert(0, here)
    import gpu_lease
    if device != 'cuda':
        return gpu_lease.unheld('Whisper on the CPU (--cpu-approved)')
    loaded = (model_name, device, compute_type) in _WHISPER
    expected = WHISPER_LOAD_S + (float(seconds) / WHISPER_SPEED if seconds else 0.0)
    return gpu_lease.acquire('whisper', need_mb=WHISPER_GPU_NEED_MB, wait_s=0 if loaded else None,
                             note=f'Whisper {model_name} {compute_type}: {doing}', expected_s=round(expected, 1))


def cuda_dll_dirs():
    """The NVIDIA runtime folders pip installed for this interpreter (site-packages/nvidia/*/bin)."""
    roots = []
    try:
        import nvidia
        roots = [str(r) for r in getattr(nvidia, '__path__', [])]
    except ImportError:
        pass
    if not roots:
        import site
        roots = [str(Path(sp) / 'nvidia') for sp in site.getsitepackages() if (Path(sp) / 'nvidia').is_dir()]
    out = []
    for r in roots:
        out += [str(x) for x in sorted(Path(r).glob('*/bin')) if x.is_dir()]
    return list(dict.fromkeys(out))


def _on_path(dirs):
    have = {os.path.normcase(os.path.normpath(x)) for x in os.environ.get('PATH', '').split(os.pathsep) if x}
    return [d for d in dirs if os.path.normcase(os.path.normpath(d)) in have]


def cuda_runtime_setup():
    """Make those folders findable by CTranslate2 in THIS process (first on its PATH, and in its DLL search list).
    A terminal opened after they were added to the user's PATH has them already; a process started before (an agent
    session) does not. Nothing outside this process changes."""
    dirs = cuda_dll_dirs()
    if os.name == 'nt' and dirs:
        add = [d for d in dirs if d not in _on_path(dirs)]
        if add:
            os.environ['PATH'] = os.pathsep.join(add + [os.environ.get('PATH', '')])
        for d in dirs:
            if d not in _DLL_DIRS:
                try:
                    os.add_dll_directory(d)
                    _DLL_DIRS.append(d)
                except OSError:
                    pass
    return dirs


def _gpu_name():
    try:
        p = subprocess.run(['nvidia-smi', '--query-gpu=name,driver_version', '--format=csv,noheader'],
                           capture_output=True, text=True, timeout=15)
        return (p.stdout or '').strip().splitlines()[0] if p.returncode == 0 and p.stdout.strip() else None
    except (OSError, subprocess.TimeoutExpired):
        return None


def whisper_model(model_name, device, compute_type):
    """(model, engine facts) loaded once per process. On the GPU it runs one second of silence through the encoder
    and decoder at once, so a missing CUDA library fails here, by name, before any real audio; the facts are what
    the inference engine itself reports (device, index, compute type), not the settings asked for."""
    key = (model_name, device, compute_type)
    if key in _WHISPER:
        return _WHISPER[key]
    if model_name not in WHISPER_MODELS:
        raise RuntimeError(f'Whisper {model_name} is not used here: every transcription is Whisper medium.')
    try:
        import ctranslate2
        import faster_whisper
        from faster_whisper import WhisperModel
    except ImportError as exc:
        raise RuntimeError(f'faster-whisper is not importable in {sys.executable}: {exc}')
    facts = {'python': sys.executable, 'faster_whisper': getattr(faster_whisper, '__version__', None),
             'ctranslate2': getattr(ctranslate2, '__version__', None), 'model': model_name}
    if device == 'cuda':
        facts['cuda_dll_dirs'] = cuda_runtime_setup()
        facts['cuda_devices'] = ctranslate2.get_cuda_device_count()
        if facts['cuda_devices'] < 1:
            raise RuntimeError('Whisper runs on the GPU here, and CTranslate2 sees no CUDA device. Check the NVIDIA '
                               'driver (nvidia-smi), that CUDA_VISIBLE_DEVICES does not hide the card, and that '
                               f'{sys.executable} has the CUDA build of ctranslate2. Nothing was transcribed; the CPU is '
                               'used only on the user\'s explicit yes (--device cpu --cpu-approved "...").')
        facts['gpu'] = _gpu_name()
    elif device == 'cpu':
        facts['cpu_approved'] = _CPU_APPROVAL
    lease = whisper_gpu_lease(model_name, device, compute_type, 'loading the model')   # held while it loads and warms up
    t0 = time.time()
    try:
        model = WhisperModel(model_name, device=device, compute_type=compute_type)
        facts['load_s'] = round(time.time() - t0, 2)
        import numpy as np
        t1 = time.time()
        segs, _ = model.transcribe(np.zeros(16000, dtype=np.float32), beam_size=1, vad_filter=False,
                                   without_timestamps=True, language='en')
        list(segs)
        facts['warmup_s'] = round(time.time() - t1, 2)
    except Exception as exc:   # noqa: BLE001 - CTranslate2 raises plain RuntimeErrors and OSErrors for missing DLLs
        raise RuntimeError(f'Whisper {model_name} could not run on {device} ({compute_type}): {exc}. Python: '
                           f'{sys.executable}. NVIDIA runtime folders found for it: '
                           f'{facts.get("cuda_dll_dirs") or "none"} (cuBLAS 12, cuDNN 9, NVRTC from the nvidia-*-cu12 '
                           'packages; nvidia-smi shows the driver). Nothing was transcribed; no CPU fallback.')
    finally:
        lease.release()
    eng = model.model
    facts.update({'device': eng.device, 'device_index': eng.device_index, 'compute_type': eng.compute_type})
    if device == 'cuda' and eng.device != 'cuda':
        raise RuntimeError(f'Whisper was asked for the GPU but the engine reports {eng.device}; nothing transcribed.')
    _WHISPER[key] = (model, facts)
    return model, facts


def whisper_settings(args):
    """Checked once per command, before any work: Whisper medium on the GPU (cuda, float16). --device cpu needs
    --cpu-approved with the user's own words; nothing ever switches to the CPU by itself."""
    global _CPU_APPROVAL
    if getattr(args, 'whisper_model', 'medium') not in WHISPER_MODELS:
        error('Every transcription here is Whisper medium.', {'asked': args.whisper_model})
    dev = getattr(args, 'device', None) or WHISPER_DEVICE
    if dev == 'cpu':
        said = (getattr(args, 'cpu_approved', None) or '').strip()
        if n_words(said) < 3:
            error('Whisper runs on the GPU here. The CPU is used only when the user explicitly says so: pass '
                  '--cpu-approved "<what the user said>" with --device cpu. Nothing ran.')
        _CPU_APPROVAL = said
    args.device = dev
    if not getattr(args, 'compute_type', None):
        args.compute_type = WHISPER_COMPUTE if dev == 'cuda' else 'int8'


def add_whisper_args(p):
    p.add_argument('--whisper-model', default='medium', choices=list(WHISPER_MODELS))
    p.add_argument('--device', default=WHISPER_DEVICE, choices=['cuda', 'cpu'],
                   help='cuda: the GPU, always; cpu only with --cpu-approved')
    p.add_argument('--compute-type', default=None, help='float16 on the GPU (the default)')
    p.add_argument('--cpu-approved', help='the user\'s own words allowing Whisper on the CPU this time (--device cpu)')


def transcribe(path, outpath, model_name, device, compute_type):
    model, eng = whisper_model(model_name, device, compute_type)   # loaded under its own lease, once per process
    try:
        secs = probe(path)['duration_s']
    except Exception:  # noqa: BLE001 - the length only sizes the lease
        secs = None
    with whisper_gpu_lease(model_name, device, compute_type, f'transcribing {Path(path).name}', secs):
        t0 = time.time()
        segs, info = model.transcribe(str(path), beam_size=5, word_timestamps=True, vad_filter=True,
                                      condition_on_previous_text=False)
        rows = []
        for s in segs:              # faster-whisper decodes while the segments are read: this loop is the GPU's work
            rows.append({'start_s': round(s.start, 3), 'end_s': round(s.end, 3), 'text': s.text.strip(),
                         'words': [{'start_s': round(w.start, 3), 'end_s': round(w.end, 3), 'text': w.word}
                                   for w in s.words or []]})
        elapsed = time.time() - t0
    result = {'status': 'transcribed', 'source': str(path), 'model': model_name,
              'language': info.language, 'duration_s': round(info.duration, 2),
              'engine': {k: eng.get(k) for k in ('device', 'device_index', 'compute_type', 'gpu', 'faster_whisper',
                                                 'ctranslate2', 'python', 'cpu_approved') if eng.get(k) is not None},
              'elapsed_s': round(elapsed, 2), 'realtime_x': round(info.duration / elapsed, 1) if elapsed > 0 else None,
              'segments': rows, 'warning': 'Whisper is fallible: verify names, numbers and hard-to-hear claims by listening.'}
    write_json(outpath, result)
    outpath.with_suffix('.txt').write_text('\n'.join(f"[{s['start_s']:.1f}-{s['end_s']:.1f}] {s['text']}" for s in rows), encoding='utf-8')
    return len(rows)


def cmd_prepare(args):
    rd, st = run_folder(args)
    inv = read_json(rd / '00-inventory/references.json', required=True)
    ids = set(args.ids.split(',')) if args.ids else None
    chosen = [v for v in inv['items'] if v.get('kind') == 'video' and not v.get('duplicate_of')
              and (ids is None or v['id'] in ids)]
    if not chosen:
        error('No matching unique reference videos. Run scan first.')
    fps = run_analysis_fps(st)
    sampler = run_analysis_sampler(st)
    if args.fps and abs(float(args.fps) - fps) > 1e-9:
        error(f'This run analyses its references at {fps:g} fps (state.json analysis_fps): every reference of a run is '
              'sampled at one rate, so they and the run\'s own export compare on one yardstick. Clone the run to '
              'analyse at another rate (a clone prepares its references again at the current rate).',
              {'run_fps': fps, 'requested_fps': args.fps})
    if not 0 < fps <= 60:
        error('FPS must be between 0 and 60')
    estimate = sum(v.get('duration_s') or 0 for v in chosen) * fps
    if args.dry_run:
        emit({'ok': True, 'videos': len(chosen), 'fps': fps, 'sampler': sampler,
              'estimated_sample_frames': int(estimate), 'per_video': {x['id']: x['duration_s'] for x in chosen},
              'note': f'{fps:g} fps is this run\'s analysis rate (a frame every {1 / fps:g} s'
                      + (', each at its own timestamp' if sampler == ANALYSIS_SAMPLER else ', nominal slot times')
                      + '); for a brief stretch the samples cannot settle, inspect-window looks closer.'})
        return
    results = []
    failures = []
    for v in chosen:
        dest = rd / '10-media' / v['id']
        dest.mkdir(parents=True, exist_ok=True)
        src = Path(v['source_path'])
        target = dest / ('all-frames' if args.full_fps else 'sampled-frames')
        target.mkdir(exist_ok=True)
        manifest = dest / 'preparation.json'
        pold = read_json(manifest)
        signature = {'fingerprint': v['fingerprint'], 'fps': 'original' if args.full_fps else fps,
                     'width': args.width, 'whisper_model': args.whisper_model}
        # The frames and the transcript are cached apart: a new sampling rate, sampler or width re-makes the
        # frames only, never the transcript (the audio did not change), and frames made another way are never
        # reused. An older manifest held one signature for both, for nominal-slot frames.
        pts_mode = bool(args.full_fps) or sampler == ANALYSIS_SAMPLER
        frames_sig = {'fingerprint': v['fingerprint'], 'fps': signature['fps'], 'width': args.width,
                      'sampler': ANALYSIS_SAMPLER if pts_mode else LEGACY_SAMPLER}
        words_sig = {k: signature[k] for k in ('fingerprint', 'whisper_model')}
        sig_key = 'full_frames_signature' if args.full_fps else 'frames_signature'
        old_sig = pold.get('signature') or {}
        old_frames = dict(pold.get(sig_key) or ({} if args.full_fps else
                                                {k: old_sig.get(k) for k in ('fingerprint', 'fps', 'width')}))
        old_frames.setdefault('sampler', LEGACY_SAMPLER)
        old_words = pold.get('transcript_signature') or {k: old_sig.get(k) for k in words_sig}
        index_path = dest / ('all-frames-index.json' if args.full_fps else 'frame-index.json')
        details = {k: x for k, x in pold.items() if k in ('frames_signature', 'full_frames_signature', 'frame_index',
                                                         'all_frames_index', 'sampler', 'sampled_frames', 'sample_fps')}
        details.update({'id': v['id'], 'source': str(src), 'signature': signature, sig_key: frames_sig,
                        'transcript_signature': words_sig, 'updated_at': now()})
        try:
            if not (old_frames == frames_sig and list(target.glob('*.jpg')) and (index_path.is_file() or not pts_mode)):
                if pts_mode:
                    frames, origin = _av().sample_frames(src, target, fps=fps, width=args.width, native=bool(args.full_fps))
                    gaps = [y['t_s'] - x['t_s'] for x, y in zip(frames, frames[1:])]
                    write_json(index_path, {
                        'source_id': v['id'], 'mode': 'source_pts', 'sampler': ANALYSIS_SAMPLER,
                        'fps': 'original' if args.full_fps else fps,
                        'interval_s': None if args.full_fps else round(1 / fps, 4),
                        'clock': 'transcript: each frame\'s source timestamp minus the audio stream\'s start, the '
                                 'clock of every word time and speech segment',
                        'clock_origin_s': round(origin, 4), 'max_gap_s': round(max(gaps), 4) if gaps else None,
                        'note': 'Each frame shows the picture at its t_s exactly; anything between two samples is '
                                'unseen (inspect-window looks closer at a brief stretch).',
                        'frames': [{**f, 'approx_s': f['t_s']} for f in frames]})
                else:   # a run made before: frames numbered at a fixed rate, as it was analysed
                    for existing in target.glob('*.jpg'):
                        existing.unlink()
                    run_cmd(['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', '-i', str(src), '-vf',
                             f"fps={fps},scale={args.width}:-2", '-q:v', '5', str(target / '%07d.jpg')], timeout=None)
            if not args.full_fps:
                details['sampled_frames'] = len(list(target.glob('*.jpg')))
                details['sample_fps'] = fps
                details['sampler'] = frames_sig['sampler']
            else:
                details['all_frames'] = len(list(target.glob('*.jpg')))
            details['full_frame_extraction'] = bool(args.full_fps)
            details['all_frames_index' if args.full_fps else 'frame_index'] = str(index_path)
            # A run made before keeps its NOMINAL sample slots (re-derived from the file names), not exact PTS.
            sample_rate = fps
            if not args.full_fps and not pts_mode:
                frame_index_path = dest / 'frame-index.json'
                frame_names = sorted(x.name for x in target.glob('*.jpg'))
                frame_index = {'source_id': v['id'], 'mode': 'nominal_sample_time',
                               'warning': 'Approximate sample time from output slot; not source-native PTS.',
                               'fps': sample_rate, 'interval_s': round(1 / sample_rate, 4),
                               'tolerance_s': round(0.5 / sample_rate, 4),
                               'frames': [{'file': name, 'approx_s': round(i/sample_rate, 3)}
                                          for i, name in enumerate(frame_names)]}
                write_json(frame_index_path, frame_index)
                details['frame_index'] = str(frame_index_path)
            if args.skip_whisper and n_words(getattr(args, 'reason', '')) < 4 and v.get('has_audio'):
                error('--skip-whisper leaves a reference without its words (pace, pauses, what is said where): say why '
                      '(--reason).')
            if not args.skip_whisper and v.get('has_audio'):
                tp = dest / 'transcript.json'
                if not (old_words == words_sig and read_json(tp).get('status') == 'transcribed'):
                    details['transcript_segments'] = transcribe(src, tp, args.whisper_model, args.device, args.compute_type)
                else:
                    details['transcript_segments'] = len(read_json(tp).get('segments', []))
            else:
                details['transcript_status'] = 'skipped_by_user' if args.skip_whisper else 'no_audio_stream'
            write_json(manifest, details)
            results.append(details)
        except (RuntimeError, ValueError, OSError) as exc:
            failures.append({'id': v['id'], 'error': str(exc)[:450]})
    emit({'ok': not failures, 'processed': results, 'failed': failures}, 2 if failures else 0)


def cards_inventory(rd):
    inv = read_json(rd / '00-inventory/references.json', required=True)
    vids = {x['id']: x for x in inv.get('items', []) if x.get('kind') == 'video' and not x.get('duplicate_of')}
    return vids


def card_set(rd):
    vids = cards_inventory(rd)
    cards = {}
    issues = []
    for ident, v in vids.items():
        path = rd / '20-analysis/cards' / f'{ident}.json'
        c = read_json(path)
        if not c:
            issues.append(ident + ': missing analytical card')
            continue
        if c.get('reference_id') != ident:
            issues.append(ident + ': card/reference ID mismatch')
        if not c.get('niches') or not isinstance(c.get('niches'), list):
            issues.append(ident + ': missing niches list')
        if not c.get('story_form'):
            issues.append(ident + ': missing story_form')
        if not c.get('viewer_experience') or not isinstance(c.get('viewer_experience'), list):
            issues.append(ident + ': missing timed viewer_experience moments')
        cards[ident] = c
    return vids, cards, issues


def cmd_cohorts(args):
    rd, st = run_folder(args)
    vids, cards, issues = card_set(rd)
    groups = {}
    for vid, card in cards.items():
        duration = vids[vid].get('duration_s')
        if not duration:
            continue
        cid = str(card.get('cohort_id') or '').strip().lower()
        if cid:
            groups.setdefault(('__cohort__:' + cid, ''), []).append((vid, duration))
        for niche in card.get('niches') or []:
            family = (str(niche).strip().lower(), str(card.get('story_form') or '').strip().lower())
            groups.setdefault(family, []).append((vid, duration))
    summaries = []
    for (key, form), members in sorted(groups.items()):
        vals = sorted(t for _, t in members)
        med = statistics.median(vals)
        entry = {'references': [ident for ident, _ in members],
                 'n': len(vals), 'min_s': round(vals[0], 1), 'median_s': round(med, 1),
                 'mean_s': round(statistics.mean(vals), 1), 'max_s': round(vals[-1], 1),
                 'spread_ratio': round(vals[-1] / vals[0], 2),
                 'longform_refs': [id for id, t in members if t >= st['min_longform_s']],
                 'warning': ('MIXED_RUNTIME_FAMILIES_SELECT_COMPARABLE_IDS' if vals[-1]/vals[0] > 1.8 else None)}
        if key.startswith('__cohort__:'):
            entry['cohort_id'] = key[len('__cohort__:'):]
        else:
            entry['niche'] = key
            entry['story_form'] = form
        summaries.append(entry)
    write_json(rd / '20-analysis/cohorts/index.json', {'groups': summaries, 'unresolved': issues, 'at': now()})
    emit({'ok': not issues, 'groups': summaries, 'missing_cards_or_fields': issues,
          'warning': 'Patterns and duration must be selected from comparable references, not averaged across unrelated niches.'}, 2 if issues else 0)


# ---------------------------------------------------------------- the analysis work, then the niches it discovers
# 2026-11-24 (the user's brief on dynamic niche discovery). References are analysed one by one, and the work is split
# between analysis agents by how much there is to read, never by what the videos seem to be about: a batch is a share
# of the reading, not a group, a cohort or a niche, and nothing downstream reads it except niche-check, which reports
# how the discovered niches fall across the batches (a fact for the director, never a verdict). The niches come
# afterwards, from the finished cards: niche-evidence lays every reference out with each dimension apart (subject,
# format, viewer reward, look, narration, runtime and pace, content), in reference order and with no batch, cohort or
# earlier grouping in sight; the director writes 20-analysis/niche-map.json with as many niches as the evidence holds
# (one or many, overlapping where a reference belongs to two, outliers kept apart) and the comparable cohorts inside
# each; niche-check checks its form and traceability only and gathers the facts a presentation needs; niche-lock
# records the user's pick, which the length, the direction's evidence family and the subject's scope then read.
NICHE_DISCOVERY = 'niche-map-v1'
# The reading-work estimate that splits the analysis (config.json -> analysis_batching overrides any of these): each
# image an agent opens counts one (watch sheets, shot sheets); a transcript counts one per words_per_image words; a
# closer-look candidate of the av-profile counts inspect_candidate_weight; each reference adds per_reference_overhead
# (its measurements, its card, its notes and its content review). Sized on the first 38-reference run of 2026-11-24
# (about 150 images and 7-9 references per agent). They balance work; they say nothing about any video.
BATCHING_DEFAULTS = {'max_agents': 5, 'per_agent_budget': 260, 'per_reference_overhead': 12,
                     'words_per_image': 1000, 'inspect_candidate_weight': 0.2}
NICHE_ROLES = ('core', 'overlap')
ANALYSIS_BRIEF_TEMPLATE = ROOT / 'reference' / 'templates' / 'analysis-agent-brief.md'


def studio_config():
    return read_json(ROOT / 'config.json')


def batching_settings():
    cfg = studio_config().get('analysis_batching') or {}
    out = dict(BATCHING_DEFAULTS)
    for k in out:
        v = cfg.get(k)
        if isinstance(v, (int, float)) and not isinstance(v, bool) and v > 0:
            out[k] = v
    out['max_agents'] = int(out['max_agents'])
    return out


def niche_flow(st):
    """A run made with niche discovery (init or clone since 2026-11-24): its niche is the user's pick from the niche
    map, locked with niche-lock before any length. A run made before keeps its label-matched niche."""
    return str((st or {}).get('niche_discovery') or '') == NICHE_DISCOVERY


def niche_lock_path(rd):
    return rd / '20-analysis' / 'niche-lock.json'


def niche_map_path(rd):
    return rd / '20-analysis' / 'niche-map.json'


def niche_evidence_path(rd):
    return rd / '20-analysis' / 'niche-evidence.json'


def ref_analysis_state(rd, vid):
    """What exists of one reference's analysis: its card (with the fields every later step reads), its notes, its
    content review."""
    c = read_json(rd / '20-analysis/cards' / f'{vid}.json')
    card_ok = bool(c and c.get('reference_id') == vid and isinstance(c.get('niches'), list) and c.get('niches')
                   and c.get('story_form') and isinstance(c.get('viewer_experience'), list)
                   and c.get('viewer_experience'))
    return {'card': card_ok, 'notes': (rd / '20-analysis' / f'{vid}-notes.md').is_file(),
            'content_review': (rd / '20-analysis/content' / f'{vid}.json').is_file()}


def transcript_word_count(rd, vid):
    """A reference's transcript size in words. (Named apart from transcript_words(tjson), the word list further down:
    the two shared one name until 2026-11-26, the later one won, and this count raised a TypeError when it was needed.)"""
    t = read_json(rd / '10-media' / vid / 'transcript.json')
    return sum(n_words(s.get('text')) for s in t.get('segments') or [] if isinstance(s, dict))


def ref_work(rd, vid, row, cfg):
    """How much an analysis agent reads and writes for one reference, from what is on disk; a part that is not
    measured yet is estimated from the duration and named in `estimated`."""
    dur = float(row.get('duration_s') or 0)
    av = read_json(ref_av_path(rd, vid))
    estimated = []
    watch = len(av.get('sheets') or []) or len(list((rd / '20-analysis/av' / vid).glob('sheet-*.jpg')))
    if not watch:
        watch = max(1, math.ceil(dur / 60)) if dur else 1
        estimated.append('watch_sheets')
    ix = read_json(rd / '20-analysis/content' / f'{vid}-shots' / 'index.json')
    shot_sheets = ix.get('sheets')
    if isinstance(shot_sheets, list):
        shot_sheets = len(shot_sheets)
    if not isinstance(shot_sheets, int) or isinstance(shot_sheets, bool) or shot_sheets <= 0:
        shot_sheets = len(list((rd / '20-analysis/content' / f'{vid}-shots').glob('sheet-*.jpg')))
    if not shot_sheets:
        shots = len(av.get('shots') or [])
        shot_sheets = math.ceil(shots / SHOTS_PER_SHEET) if shots else watch
        estimated.append('shot_sheets')
    words = ((av.get('summary') or {}).get('narration') or {}).get('words')
    if not isinstance(words, int):
        words = transcript_word_count(rd, vid)
        if not words and row.get('has_audio'):
            estimated.append('transcript_words')
    cands = len(av.get('inspect_candidates') or [])
    load = (watch + shot_sheets + words / cfg['words_per_image'] + cands * cfg['inspect_candidate_weight']
            + cfg['per_reference_overhead'])
    return {'ref': vid, 'duration_s': round(dur, 1), 'watch_sheets': watch, 'shot_sheets': shot_sheets,
            'transcript_words': words, 'inspect_candidates': cands, 'load': round(load, 1),
            **({'estimated': estimated} if estimated else {})}


def analysis_plans(rd):
    """The analysis plans of this run, oldest first: [(round, plan)]."""
    out = []
    for p in (rd / '20-analysis' / 'agents').glob('plan-r*.json'):
        m = re.fullmatch(r'plan-r(\d+)\.json', p.name)
        if m:
            out.append((int(m.group(1)), read_json(p)))
    return sorted(out, key=lambda x: x[0])


def split_work(work, n):
    """Longest first, each reference to the least-loaded agent (ties: the lower reference number, the first agent).
    The split depends on the work alone: the same references give the same batches whatever they are about."""
    loads, batches = [0.0] * n, [[] for _ in range(n)]
    for v in sorted(work, key=lambda v: (-work[v]['load'], v)):
        k = min(range(n), key=lambda i: (loads[i], i))
        batches[k].append(v)
        loads[k] += work[v]['load']
    return [sorted(b) for b in batches], [round(x, 1) for x in loads]


def fill_template(text, values):
    for k, v in values.items():
        text = text.replace('{{' + k + '}}', str(v))
    left = sorted(set(re.findall(r'\{\{([A-Z_]+)\}\}', text)))
    if left:
        error('The analysis brief template has placeholders this tool does not fill', left)
    return text


def cmd_analysis_plan(args):
    rd, st = run_folder(args)
    vids = cards_inventory(rd)
    cfg = batching_settings()
    if args.ids:
        want = normalize_refs(args.ids)
        unknown = [v for v in want if v not in vids]
        if unknown:
            error('Unknown reference IDs', unknown)
    elif args.all:
        want = sorted(vids)
    else:
        want = [v for v in sorted(vids) if not all(ref_analysis_state(rd, v).values())]
    if not want:
        emit({'ok': True, 'planned': [], 'note': 'Every reference already has its card, notes and content review: '
              'nothing to split (--all or --ids plans again).'})
        return
    plans = analysis_plans(rd)
    rnd = (plans[-1][0] + 1) if plans else 1
    if plans and not args.dry_run:
        busy = [r['ref'] for b in plans[-1][1].get('batches') or [] for r in b.get('refs') or []
                if r.get('ref') in want and not all(ref_analysis_state(rd, r['ref']).values())]
        if busy and n_words(args.replace_why) < 4:
            error('The latest analysis plan still has these references in analysis: let its agents finish (their '
                  'to-do files say where they are), or plan them again with --replace-why "why".',
                  {'plan': f'plan-r{plans[-1][0]}.json', 'references': busy})
    work = {v: ref_work(rd, v, vids[v], cfg) for v in want}
    total = round(sum(w['load'] for w in work.values()), 1)
    if args.agents is not None:
        if args.agents < 1:
            error('--agents must be 1 or more')
        n = args.agents
    else:
        n = max(1, min(cfg['max_agents'], math.ceil(total / cfg['per_agent_budget'])))
    n = min(n, len(want))
    batches, loads = split_work(work, n)
    template = ANALYSIS_BRIEF_TEMPLATE.read_text(encoding='utf-8') if ANALYSIS_BRIEF_TEMPLATE.is_file() else None
    if template is None:
        error('The analysis brief template is missing', str(ANALYSIS_BRIEF_TEMPLATE))
    agents_dir = rd / '20-analysis' / 'agents'
    rows = []
    for k, refs in enumerate(batches, 1):
        name = f'r{rnd}-a{k}'
        brief, todo = agents_dir / f'{name}-brief.md', agents_dir / f'{name}-todo.md'
        listing = '\n'.join(f'- {v} · {round(work[v]["duration_s"] / 60, 1)} min · {vids[v].get("relative_path")}'
                            for v in refs)
        rows.append({'agent': name, 'refs': [work[v] for v in refs], 'load': loads[k - 1],
                     'minutes': round(sum(work[v]['duration_s'] for v in refs) / 60, 1),
                     'brief': str(brief), 'todo': str(todo),
                     'spawn_prompt': f'Read your brief and follow it exactly: {brief}'})
        if not args.dry_run:
            brief.parent.mkdir(parents=True, exist_ok=True)
            brief.write_text(fill_template(template, {
                'RUN': rd, 'STUDIO': ROOT, 'AGENT': name, 'AGENTS': n, 'REFERENCES': listing, 'TODO': todo,
                'COUNT': len(refs)}), encoding='utf-8')
            if not todo.exists():
                todo.write_text(f'# {name}: analysis to-do (read first when resumed)\n\n'
                                + ''.join(f'- [ ] {v}: card, notes, content review\n' for v in refs), encoding='utf-8')
    plan = {'schema': 'analysis-plan-v1', 'round': rnd, 'basis': 'reading work only', 'agents': n,
            'settings': cfg, 'total_load': total, 'batches': rows,
            'balance': {'max_load': max(loads), 'min_load': min(loads),
                        'largest_single_reference_load': max(w['load'] for w in work.values())},
            'not_measured_yet': sorted(v for v, w in work.items() if w.get('estimated')),
            'meaning': 'A batch is a share of the reading work. It is not a group, a cohort or a niche: its references '
                       'were put together by their workload alone, and no later step treats them as related.',
            **({'replace_why': args.replace_why} if args.replace_why else {}), 'made_at': now()}
    if not args.dry_run:
        write_json(agents_dir / f'plan-r{rnd}.json', plan)
    emit({'ok': True, 'dry_run': bool(args.dry_run), 'plan': None if args.dry_run else str(agents_dir / f'plan-r{rnd}.json'),
          **{k: plan[k] for k in ('round', 'agents', 'total_load', 'balance', 'not_measured_yet', 'meaning')},
          'batches': [{'agent': r['agent'], 'refs': [x['ref'] for x in r['refs']], 'load': r['load'],
                       'minutes': r['minutes'], 'spawn_prompt': r['spawn_prompt']} for r in rows],
          'next': 'Spawn one analysis agent per batch, all at once, each with its spawn_prompt only. When every '
                  'reference is analysed: niche-evidence, then the niche map (manual 01).'})


def _short(s, n=60):
    w = str(s or '').split()
    return ' '.join(w[:n]) + (' ...' if len(w) > n else '')


def ref_evidence_row(rd, st, vid, row, card, av, review):
    """One reference, each dimension apart, from its own card, measurements and content review. Nothing here comes
    from an analysis batch, a cohort label or an earlier grouping."""
    s = av.get('summary') or {}
    nar, pic = s.get('narration') or {}, s.get('picture') or {}
    pp = nar.get('pause_profile') or {}
    segs = [x for x in review.get('segments') or [] if isinstance(x, dict)]
    dur = float(row.get('duration_s') or 0)
    reward = card.get('viewer_reward')
    if isinstance(reward, str):
        reward = [reward]
    reward_from = 'viewer_reward'
    if not reward:
        reward = [str(d.get('what')) for d in card.get('delight') or [] if isinstance(d, dict) and d.get('what')]
        reward_from = 'delight'
    swe = review.get('story_without_exclusions')
    return {
        'ref': vid, 'file': row.get('relative_path'), 'card': f'20-analysis/cards/{vid}.json',
        'language': card.get('language'),
        'subject': {'niches': card.get('niches'), 'editorial_summary': card.get('editorial_summary'),
                    'title_promise': card.get('title_promise')},
        'format': {'story_form': card.get('story_form'), 'hook': (card.get('hook') or {}).get('promise')
                   if isinstance(card.get('hook'), dict) else card.get('hook')},
        'viewer_reward': {'reward': reward, 'from': reward_from},
        'visual_style': {'visual_medium': card.get('visual_medium'), 'cuts_per_min': pic.get('cuts_per_min'),
                         'shot_median_s': (pic.get('shot_length_s') or {}).get('median'),
                         'moving_time_share': pic.get('moving_time_share')},
        'narration': {'narrator_character': card.get('narrator_character'),
                      'speech_rate_wpm': nar.get('speech_rate_wpm'),
                      'pitch_range_st': (nar.get('pitch_range_st') or {}).get('median'),
                      'longest_pause_s': pp.get('longest_pause_s'),
                      'pauses_0_8s_plus_per_min': pp.get('pauses_0_8s_plus_per_min'),
                      'silence_share': pp.get('silence_share'),
                      'gap_level_db': (nar.get('gap_level_rel_speech_db') or {}).get('median')},
        'runtime_and_pacing': {'duration_s': round(dur, 1), 'minutes': round(dur / 60, 1),
                               'longform': dur >= float(st.get('min_longform_s') or DEFAULT_MIN_LONGFORM),
                               'words': nar.get('words'),
                               'rate_p10_p90_wpm': [(nar.get('rate_across_windows_wpm') or {}).get('p10'),
                                                    (nar.get('rate_across_windows_wpm') or {}).get('p90')]},
        'content': {'excluded': sorted({str(x.get('kind')) for x in segs if x.get('action') == 'exclude'}),
                    'excluded_n': sum(1 for x in segs if x.get('action') == 'exclude'),
                    'restricted_n': sum(1 for x in segs if x.get('action') == 'restrict_visuals'),
                    'story_without_exclusions': swe.get('status') if isinstance(swe, dict) else swe,
                    'reviewed': bool(review)},
        'measured': bool(s)}


def evidence_markdown(rows, missing):
    def num(v, unit=''):
        return '?' if v is None else f'{v}{unit}'
    out = ['# Niche evidence', '',
           'One reference per section, in reference order, each dimension on its own line, from the reference\'s own '
           'card, measurements and content review. No analysis batch, cohort label or earlier grouping is shown: '
           'niches are discovered from this evidence (manual 01, "Discovering the niches"). Open a card for its '
           'timestamps, moments and devices.', '']
    if missing:
        out += ['**Not complete yet:** ' + '; '.join(f'{k}: {", ".join(v)}' for k, v in missing.items() if v), '']
    for r in rows:
        sub, fmt, rew = r['subject'], r['format'], r['viewer_reward']
        vis, nar, rt, ct = r['visual_style'], r['narration'], r['runtime_and_pacing'], r['content']
        out += [f'## {r["ref"]} · {rt["minutes"]} min · {r["file"]}', '',
                f'- **Subject:** {", ".join(map(str, sub.get("niches") or []))}. {_short(sub.get("editorial_summary"))}',
                f'- **Title promise:** {_short(sub.get("title_promise"), 45)}',
                f'- **Format:** {_short(fmt.get("story_form"))}',
                f'- **Viewer reward** ({rew["from"]}): ' + ' | '.join(_short(x, 30) for x in rew.get('reward') or []),
                f'- **Visual style:** {_short(vis.get("visual_medium"), 30)} · {num(vis.get("cuts_per_min"))} cuts/min · '
                f'median shot {num(vis.get("shot_median_s"), " s")} · moving {num(vis.get("moving_time_share"))}',
                f'- **Narration:** {_short(nar.get("narrator_character"), 30)} · {num(nar.get("speech_rate_wpm"))} wpm '
                f'while speaking · pitch range {num(nar.get("pitch_range_st"), " st")} · longest pause '
                f'{num(nar.get("longest_pause_s"), " s")} · pauses of 0.8 s+ {num(nar.get("pauses_0_8s_plus_per_min"))}'
                f'/min · level in the gaps {num(nar.get("gap_level_db"), " dB")}',
                f'- **Runtime and pace:** {rt["duration_s"]} s ({"long-form" if rt["longform"] else "under the long-form floor"})'
                f' · {num(rt.get("words"))} words · rate p10-p90 {num(rt["rate_p10_p90_wpm"][0])}-'
                f'{num(rt["rate_p10_p90_wpm"][1])} wpm',
                f'- **Content:** {ct["excluded_n"]} excluded ({", ".join(ct["excluded"]) or "none"}), '
                f'{ct["restricted_n"]} restricted · story without exclusions: {ct.get("story_without_exclusions") or "n/a"}'
                + ('' if ct['reviewed'] else ' · NO CONTENT REVIEW YET'),
                f'- **Language:** {r.get("language") or "?"} · card: `{r["card"]}`', '']
    return '\n'.join(out)


def niche_evidence_facts(rd, st):
    vids = cards_inventory(rd)
    rows, missing = [], {'card': [], 'measurements': [], 'content_review': []}
    shas = {}
    for vid in sorted(vids):
        cp = rd / '20-analysis/cards' / f'{vid}.json'
        card = read_json(cp)
        if not ref_analysis_state(rd, vid)['card']:
            missing['card'].append(vid)
            continue
        shas[vid] = file_sha256(cp)
        av = read_json(ref_av_path(rd, vid))
        review = read_json(rd / '20-analysis/content' / f'{vid}.json')
        if not av:
            missing['measurements'].append(vid)
        if not review:
            missing['content_review'].append(vid)
        rows.append(ref_evidence_row(rd, st, vid, vids[vid], card, av, review))
    return rows, {k: v for k, v in missing.items() if v}, shas


def cmd_niche_evidence(args):
    rd, st = run_folder(args)
    rows, missing, shas = niche_evidence_facts(rd, st)
    if not rows:
        error('No analysed reference yet: every reference needs its card first', missing)
    # a pure function of the analyses (no time, no batch): the same cards give the same evidence, byte for byte
    ev = {'schema': 'niche-evidence-v1', 'references': rows, 'cards_sha256': shas, 'not_complete': missing,
          'dimensions': ['subject', 'format', 'viewer_reward', 'visual_style', 'narration', 'runtime_and_pacing',
                         'content'],
          'reading': 'Evidence, not groups: each dimension is listed apart. A niche is what the audience comes for; '
                     'a format, a look or a voice that several references share is not a niche by itself.'}
    write_json(niche_evidence_path(rd), ev)
    md = rd / '20-analysis' / 'niche-evidence.md'
    md.write_text(evidence_markdown(rows, missing) + '\n', encoding='utf-8')
    emit({'ok': not missing, 'evidence': str(niche_evidence_path(rd)), 'markdown': str(md),
          'references': len(rows), 'evidence_sha256': canonical_sha(ev), 'not_complete': missing,
          'next': 'Read the markdown, open the cards you need, write 20-analysis/niche-map.json (manual 01 and 07), '
                  'then niche-check.'}, 0 if not missing else 2)


def batch_of(rd):
    """{ref: 'r1-a2'} from this run's analysis plans (the latest plan of a reference wins)."""
    out = {}
    for _rnd, plan in analysis_plans(rd):
        for b in plan.get('batches') or []:
            for r in b.get('refs') or []:
                ref = r.get('ref') if isinstance(r, dict) else r
                if ref:
                    out[str(ref)] = str(b.get('agent'))
    return out


def cohort_facts(rd, st, cohort, cards, vids):
    """The numbers a Standard length from this cohort would rest on, and which of length's own rules they meet."""
    refs = [r for r in cohort.get('refs') or [] if r in vids]
    durs = {r: float(vids[r].get('duration_s') or 0) for r in refs}
    vals = sorted(v for v in durs.values() if v)
    minimum = float(st.get('min_longform_s') or DEFAULT_MIN_LONGFORM)
    paces = {}
    for r in refs:
        w = ((read_json(ref_av_path(rd, r)).get('summary') or {}).get('narration') or {}).get('speech_rate_wpm')
        if isinstance(w, (int, float)) and w:
            paces[r] = w
    forms = sorted({str((cards.get(r) or {}).get('story_form') or '').strip().lower() for r in refs} - {''})
    langs = sorted({str((cards.get(r) or {}).get('language') or '').strip().lower()[:2] for r in refs} - {''})
    refusals = []
    if len(refs) < 2:
        refusals.append('fewer than two references')
    if vals and min(vals) < minimum:
        refusals.append('a reference under the long-form floor: ' + ','.join(r for r, d in durs.items() if d < minimum))
    if vals and max(vals) / min(vals) > 1.8:
        refusals.append('lengths span more than 1.8x')
    if len(paces) >= 2 and max(paces.values()) / min(paces.values()) > PACE_SPREAD_MAX:
        refusals.append('paces differ by more than 20% (the pace then needs --pace-wpm with its reason)')
    if len(langs) > 1:
        refusals.append('references in different languages')
    med = statistics.median(vals) if vals else None
    return {'id': cohort.get('id'), 'refs': refs, 'durations_s': {r: round(d, 1) for r, d in durs.items()},
            'median_s': round(med, 1) if med else None, 'standard_s': round(med / 5) * 5 if med else None,
            'standard_min': round(round(med / 5) * 5 / 60, 2) if med else None,
            'spread_ratio': round(max(vals) / min(vals), 2) if vals else None,
            'speech_rate_wpm': paces, 'story_forms': len(forms), 'languages': langs,
            'length_would_refuse': refusals}


def niche_check_facts(rd, st, m=None):
    """Issues (form and traceability), warnings and facts for 20-analysis/niche-map.json. Nothing here judges whether
    a niche is a good one or how many there should be."""
    m = read_json(niche_map_path(rd)) if m is None else m
    vids, cards, _card_issues = card_set(rd)
    iss, warn = [], []
    if not m:
        return ['niche_map_missing:write_20-analysis/niche-map.json'], warn, {}
    ev = read_json(niche_evidence_path(rd))
    if not ev:
        iss.append('niche_evidence_missing:run_niche-evidence_and_read_it_before_the_map')
    else:
        stale = sorted(v for v, h in (ev.get('cards_sha256') or {}).items()
                       if (rd / '20-analysis/cards' / f'{v}.json').is_file()
                       and file_sha256(rd / '20-analysis/cards' / f'{v}.json') != h)
        new = sorted(v for v in cards if v not in (ev.get('cards_sha256') or {}))
        if stale or new:
            iss.append('niche_evidence_outdated:run_niche-evidence_again:' + ','.join(stale + new))
        if ev.get('not_complete'):
            warn.append('the evidence was laid out before every analysis was finished: '
                        + '; '.join(f'{k}: {",".join(v)}' for k, v in (ev.get('not_complete') or {}).items()))
    niches = [x for x in m.get('niches') or [] if isinstance(x, dict)]
    if not niches:
        iss.append('niche_map_needs_at_least_one_niche')
    ids = [str(x.get('id') or '').strip() for x in niches]
    if '' in ids or len(set(i.lower() for i in ids)) != len(ids):
        iss.append('niche_ids_must_be_present_and_distinct')
    names = [str(x.get('name') or '').strip().lower() for x in niches]
    if len(set(names)) != len(names):
        iss.append('niche_names_must_be_distinct')
    where, cohort_ids, cohorts_out = {}, set(), {}
    for n in niches:
        nid = str(n.get('id') or '').strip() or '?'
        if n_words(n.get('name')) < 1:
            iss.append(f'niche_{nid}_needs_a_name')
        for k in ('identity', 'boundary', 'viewer_reward'):
            if n_words(n.get(k)) < MIN_FIELD_WORDS:
                iss.append(f'niche_{nid}_needs_{k}')
        mem = [x for x in n.get('members') or [] if isinstance(x, dict)]
        if not mem:
            iss.append(f'niche_{nid}_has_no_members')
        refs_here = set()
        for x in mem:
            r = str(x.get('ref') or '').strip().upper()
            if r not in vids:
                iss.append(f'niche_{nid}_member_is_not_a_reference_of_this_run:{r}')
                continue
            if r not in cards:
                iss.append(f'niche_{nid}_member_has_no_card:{r}')
            if str(x.get('role') or '').strip().lower() not in NICHE_ROLES:
                iss.append(f'niche_{nid}_member_{r}_role_must_be:' + '/'.join(NICHE_ROLES))
            if n_words(x.get('why')) < 4:
                iss.append(f'niche_{nid}_member_{r}_needs_why_from_its_own_evidence')
            if r in refs_here:
                iss.append(f'niche_{nid}_lists_{r}_twice')
            refs_here.add(r)
            where.setdefault(r, []).append((nid, str(x.get('role') or '').strip().lower()))
        if mem and not any(str(x.get('role') or '').strip().lower() == 'core' for x in mem):
            iss.append(f'niche_{nid}_needs_a_core_member')
        fmts = [f for f in n.get('formats') or [] if isinstance(f, dict)]
        if not fmts:
            iss.append(f'niche_{nid}_needs_its_formats:how_its_members_tell_their_subject')
        in_fmt = set()
        for i, f in enumerate(fmts, 1):
            if n_words(f.get('form')) < 2:
                iss.append(f'niche_{nid}_format_{i}_needs_the_form_in_words')
            fr = {str(r).strip().upper() for r in f.get('refs') or []}
            if not fr:
                iss.append(f'niche_{nid}_format_{i}_names_no_references')
            if fr - refs_here:
                iss.append(f'niche_{nid}_format_{i}_names_non_members:' + ','.join(sorted(fr - refs_here)))
            in_fmt |= fr
        if fmts and refs_here - in_fmt:
            iss.append(f'niche_{nid}_members_without_a_format:' + ','.join(sorted(refs_here - in_fmt)))
        obs = [o for o in n.get('evidence') or [] if isinstance(o, dict)]
        if not obs:
            iss.append(f'niche_{nid}_needs_timed_evidence_for_what_makes_it_engaging')
        for i, o in enumerate(obs, 1):
            r = str(o.get('ref') or '').strip().upper()
            if r not in refs_here:
                iss.append(f'niche_{nid}_evidence_{i}_cites_a_non_member:{r}')
            if parse_span(o.get('at'))[0] is None:
                iss.append(f'niche_{nid}_evidence_{i}_needs_a_time:at')
            if n_words(o.get('observed')) < 4:
                iss.append(f'niche_{nid}_evidence_{i}_needs_what_is_observed')
        for c in [c for c in n.get('comparable_cohorts') or [] if isinstance(c, dict)]:
            cid = str(c.get('id') or '').strip().lower()
            if not cid or cid in cohort_ids:
                iss.append(f'niche_{nid}_cohort_ids_must_be_present_and_distinct_across_the_map:{cid or "?"}')
            cohort_ids.add(cid)
            cr = [str(r).strip().upper() for r in c.get('refs') or []]
            if len(set(cr)) < 2:
                iss.append(f'niche_{nid}_cohort_{cid}_needs_two_references_or_more')
            if set(cr) - refs_here:
                iss.append(f'niche_{nid}_cohort_{cid}_names_non_members:' + ','.join(sorted(set(cr) - refs_here)))
            if n_words(c.get('why_comparable')) < MIN_NOTE_WORDS:
                iss.append(f'niche_{nid}_cohort_{cid}_needs_why_comparable')
            cohorts_out[cid] = {**cohort_facts(rd, st, {'id': cid, 'refs': cr}, cards, vids), 'niche': nid}
            if cohorts_out[cid]['length_would_refuse']:
                warn.append(f'cohort {cid} of niche {nid} gives no Standard length as it stands ('
                            + '; '.join(cohorts_out[cid]['length_would_refuse']) + '): present it that way, or choose '
                            'members whose lengths compare')
    outl = [o for o in m.get('outliers') or [] if isinstance(o, dict)]
    for o in outl:
        r = str(o.get('ref') or '').strip().upper()
        if r not in vids:
            iss.append(f'outlier_is_not_a_reference_of_this_run:{r}')
        if n_words(o.get('why')) < 4:
            iss.append(f'outlier_{r}_needs_why')
        where.setdefault(r, []).append(('outlier', ''))
    unaccounted = sorted(v for v in vids if v not in where)
    if unaccounted:
        iss.append('references_not_in_any_niche_or_outliers:' + ','.join(unaccounted))
    for s_ in [x for x in m.get('shared_across_niches') or [] if isinstance(x, dict)]:
        if n_words(s_.get('what')) < 2 or not s_.get('refs'):
            iss.append('shared_across_niches_entries_need_what_and_refs')
        unknown = {str(r).strip().upper() for r in s_.get('refs') or []} - set(vids)
        if unknown:
            iss.append('shared_across_niches_names_unknown_references:' + ','.join(sorted(unknown)))
    # Where cards already carry a cohort_id, it agrees with the map's cohorts (one source for length).
    for v, c in cards.items():
        cid = str(c.get('cohort_id') or '').strip().lower()
        if cid and cid in cohorts_out and v not in cohorts_out[cid]['refs']:
            iss.append(f'card_{v}_cohort_id_{cid}_disagrees_with_the_niche_map')
    # How the niches fall across the analysis batches: batches carry no meaning, so a niche that is exactly one batch
    # is worth a second look (a fact for the director, never a verdict).
    bo = batch_of(rd)
    align = {}
    for n in niches:
        nid = str(n.get('id') or '').strip()
        mem = {str(x.get('ref') or '').strip().upper() for x in n.get('members') or [] if isinstance(x, dict)}
        counts = {}
        for r in mem:
            counts[bo.get(r, 'no plan on record')] = counts.get(bo.get(r, 'no plan on record'), 0) + 1
        align[nid] = counts
        batch_refs = {}
        for r, b in bo.items():
            batch_refs.setdefault(b, set()).add(r)
        same = [b for b, rs in batch_refs.items() if len(mem) > 1 and rs == mem]
        if same:
            warn.append(f'niche {nid} is exactly the references of analysis batch {same[0]}: batches are a split of the '
                        'reading work, so make sure this niche stands on its members\' own evidence')
        elif len(mem) > 2 and len(counts) == 1 and 'no plan on record' not in counts:
            warn.append(f'every member of niche {nid} was analysed in batch {next(iter(counts))}: make sure the niche '
                        'stands on its members\' own evidence, not on how the work was split')
    facts = {'niches': len(niches), 'references': len(vids), 'outliers': [str(o.get('ref')) for o in outl],
             'in_several_niches': {r: [f'{a}:{b}' for a, b in w] for r, w in where.items()
                                   if len([a for a, _ in w if a != 'outlier']) > 1},
             'members': {str(n.get('id')): {'core': sorted(str(x.get('ref')).upper() for x in n.get('members') or []
                                                          if isinstance(x, dict) and x.get('role') == 'core'),
                                            'overlap': sorted(str(x.get('ref')).upper() for x in n.get('members') or []
                                                             if isinstance(x, dict) and x.get('role') == 'overlap')}
                         for n in niches},
             'cohorts': cohorts_out, 'batches_per_niche': align}
    return iss, warn, facts


def cmd_niche_check(args):
    rd, st = run_folder(args)
    m = read_json(niche_map_path(rd))
    iss, warn, facts = niche_check_facts(rd, st, m)
    rec = {'ok': not iss, 'map_sha256': canonical_sha(m) if m else None,
           'evidence_sha256': (canonical_sha(read_json(niche_evidence_path(rd)))
                               if niche_evidence_path(rd).is_file() else None),
           'issues': iss, 'warnings': warn, 'facts': facts, 'checked_at': now()}
    write_json(rd / '20-analysis' / 'niche-check.json', rec)
    emit({**rec, 'next': ('Present the niches to the user (what each is about, what makes it engaging with its '
                          'evidence, its formats, its Standard lengths from facts.cohorts), then niche-lock their pick.')
          if not iss else 'Fix the map and check again.'}, 0 if not iss else 2)


def cmd_niche_lock(args):
    rd, st = run_folder(args)
    m = read_json(niche_map_path(rd))
    iss, _warn, facts = niche_check_facts(rd, st, m)
    if iss:
        error('The niche map does not pass niche-check: fix it before locking a niche', iss)
    want = str(args.niche or '').strip().lower()
    n = next((x for x in m.get('niches') or [] if isinstance(x, dict) and want in
              {str(x.get('id') or '').strip().lower(), str(x.get('name') or '').strip().lower()}), None)
    if n is None:
        error('No niche with that id or name in the niche map',
              {'asked': args.niche, 'niches': {str(x.get('id')): x.get('name') for x in m.get('niches') or []
                                               if isinstance(x, dict)}})
    old = read_json(niche_lock_path(rd))
    if not old and n_words(args.user_words) < 1:
        error('Record the user\'s own words for their pick (--user-words), or theirs delegating it')
    if not old and args.decided_by == 'director' and n_words(args.why) < MIN_NOTE_WORDS:
        error('A niche the director picks on the user\'s delegation says why (--why)')
    if old:
        if str(old.get('niche_id')).lower() != str(n.get('id')).lower():
            error('This run is one niche only. Use clone for a different niche.',
                  {'locked': old.get('name'), 'requested': n.get('name')})
        if not args.refresh:
            emit({'ok': True, 'unchanged': True, 'lock': str(niche_lock_path(rd)), 'niche': old.get('name')})
            return
        # the same niche, its members brought up to a revised map (new references on 'more'): a reference a locked
        # length rests on stays a member
        if n_words(args.why) < MIN_NOTE_WORDS:
            error('A refreshed niche lock says why the map changed (--why)')
        keep = {str(x.get('ref') or '').strip().upper() for x in n.get('members') or [] if isinstance(x, dict)}
        cited = {r for lp in rd.glob('40-plans/video-*/length-lock.json') for r in read_json(lp).get('reference_ids') or []}
        if cited - keep:
            error('A locked length rests on references the revised map leaves out of this niche', sorted(cited - keep))
    legacy = {str(read_json(p).get('niche') or '') for p in rd.glob('40-plans/video-*/length-lock.json')} - {''}
    if legacy and {x.lower() for x in legacy} != {str(n.get('name')).strip().lower()}:
        error('A length is already locked on another niche in this run', sorted(legacy))
    nid = str(n.get('id')).strip()
    members = [{'ref': str(x.get('ref')).strip().upper(), 'role': str(x.get('role')).strip().lower(),
                'why': x.get('why')} for x in n.get('members') or [] if isinstance(x, dict)]
    cohorts = [{**c, 'why_comparable': next((cc.get('why_comparable') for cc in n.get('comparable_cohorts') or []
                                             if str(cc.get('id') or '').strip().lower() == cid), None)}
               for cid, c in (facts.get('cohorts') or {}).items() if c.get('niche') == nid]
    lock = {'schema': 'niche-lock-v1', 'niche_id': nid, 'name': str(n.get('name')).strip(),
            'identity': n.get('identity'), 'boundary': n.get('boundary'), 'viewer_reward': n.get('viewer_reward'),
            'members': members, 'formats': n.get('formats'), 'comparable_cohorts': cohorts,
            'map_sha256': canonical_sha(m), 'evidence_sha256': canonical_sha(read_json(niche_evidence_path(rd))),
            'user_words': old.get('user_words') if old else args.user_words,
            'decided_by': old.get('decided_by') if old else args.decided_by,
            **({'why': old.get('why')} if old and old.get('why') else {'why': args.why} if args.why and not old else {}),
            'locked_at': old.get('locked_at') if old else now(),
            **({'refreshed': (old.get('refreshed') or []) + [{'at': now(), 'why': args.why,
                                                            'members_before': [m.get('ref') for m in old.get('members') or []]}]}
               if old else {}),
            'rule': 'One niche per run: a different niche is a clone. Its members are the evidence family every '
                    'video of this run draws on; a reference outside them is borrowed (its technique, not its subject).'}
    write_json(niche_lock_path(rd), lock)
    st['selected_niche'] = lock['name']
    st['selected_niche_id'] = nid
    st['niche_discovery'] = NICHE_DISCOVERY
    write_json(rd / 'state.json', st)
    advance_stage(rd, 'reference_analysis_complete')
    emit({'ok': True, 'lock': str(niche_lock_path(rd)), 'niche': lock['name'], 'niche_id': nid,
          'members': members, 'comparable_cohorts': [{k: c.get(k) for k in ('id', 'refs', 'standard_min',
                                                                              'length_would_refuse')} for c in cohorts],
          'next': 'length: Standard from one of these cohorts (--cohort-id), or own minutes; refs from this niche.'})


def video_dir(rd, video):
    n = int(video)
    if n < 1:
        error('video number must be >=1')
    return rd / '40-plans' / f'video-{n:02d}'


def normalize_refs(s):
    return [x.strip().upper() for x in (s or '').split(',') if x.strip()]


def length_intent_path(vd):
    return vd / 'length-intent.json'


STORY_LENGTH_RULE = ('The story set this length. Before narration is recorded the director re-locks it to the story\'s '
                     'real size, with the reason (kept in history); once narration exists, a new length is the user\'s '
                     'decision.')


def story_size_of(rd, video):
    """What the story itself says about its length, from direction.json: the chosen treatment's movements added up,
    the chosen subject's own range, and the narrators the decision's pacing calls relevant. None until a treatment
    with movements is chosen."""
    d = read_json(video_dir(rd, video) / 'direction.json')
    t = chosen_treatment_of(d) if d else {}
    mv = treatment_movements(t)
    if not mv or any(m['minutes'] <= 0 for m in mv):
        return None
    subj = d.get('subject') if isinstance(d.get('subject'), dict) else {}
    sel = subj.get('selection') if isinstance(subj.get('selection'), dict) else {}
    ch = next((c for c in subj.get('candidates') or [] if isinstance(c, dict)
               and str(c.get('id')) == str(sel.get('candidate'))), {})
    dec = d.get('decision') if isinstance(d.get('decision'), dict) else {}
    pac = dec.get('pacing') if isinstance(dec.get('pacing'), dict) else {}
    nat = natural_minutes(ch.get('runtime'))
    return {'treatment': str(t.get('id')), 'movements_minutes': round(sum(m['minutes'] for m in mv), 2),
            'candidate': str(sel.get('candidate') or '') or None, 'natural_minutes': list(nat) if nat else None,
            'pace_references': [str(r.get('ref') or '').strip().upper() for r in pac.get('references') or []
                                if isinstance(r, dict) and r.get('relevant') is True and str(r.get('ref') or '').strip()]}


def cmd_length(args):
    rd, st = run_folder(args)
    outdir = video_dir(rd, args.video)
    lockfile = outdir / 'length-lock.json'
    prev_lock = read_json(lockfile) if lockfile.exists() else None
    revise, approved = (getattr(args, 'revise', '') or '').strip(), (getattr(args, 'user_approved', '') or '').strip()
    story = args.mode == 'story'
    # A length the story set itself is the director's to re-lock while nothing is recorded: the user chose to let the
    # story decide, and its real size is known once it is written. Every other change of a locked length is the
    # user's decision, in their words.
    own_relock = bool(story and prev_lock and prev_lock.get('mode') == 'story'
                      and not media_present(rd, args.video, 'narration'))
    if prev_lock and not revise:
        error('Length already locked. Do not silently revise runtime.', {'file': str(lockfile),
              'action': ('The story set this length and nothing is recorded yet: re-lock it to the story\'s real size '
                         'with length --mode story --minutes N --revise "why" (the old lock is kept in history).'
                         if own_relock else
                         'A new length is the user\'s decision: once they have approved it, length --revise "why" '
                         '--user-approved "<their own words>" with the new --mode and its options (the old lock is '
                         'kept in the new one\'s history); or a new video ID.')})
    if prev_lock:
        if n_words(revise) < MIN_NOTE_WORDS:
            error('Say why the length changes (--revise "...", five words or more).')
        if n_words(approved) < 2 and not own_relock:
            error('A length revision needs the user\'s own approval, in their words (--user-approved "..."). Only a '
                  'length the story set itself (--mode story) is the director\'s to re-lock, and only before narration '
                  'is recorded.')
    elif revise or approved:
        error('Nothing to revise: no length is locked for this video yet.')
    vids, cards, issues = card_set(rd)
    if issues:
        error('Analyze all reference videos before choosing length', issues)
    cohort_id = (getattr(args, 'cohort_id', None) or '').strip().lower()
    niche_arg = (args.niche or '').strip().lower()
    form_arg = (args.story_form or '').strip().lower()
    forms_why = str(getattr(args, 'forms_why', '') or '')
    # The niche is the user's pick from the niche map (niche-lock): the comparable references come from inside it,
    # from one of its comparable cohorts or one of its formats; a run made before niche discovery keeps its
    # label-matched niche below.
    nl = read_json(niche_lock_path(rd))
    if niche_flow(st) and not nl:
        error("Lock the user's niche first: niche-evidence, the niche map, niche-check, then niche-lock with their "
              "pick (manual 01). The length's comparable references come from inside that niche.")
    size = story_size_of(rd, args.video) if story else None
    if story and size is None:
        if prev_lock:
            error('The chosen treatment has no movements to take a length from (direction.json).')
        # The user's choice, on record before the subject is known: the story sets the length. The lock is made by
        # this same command once a treatment is chosen.
        write_json(length_intent_path(outdir), {'schema': SCHEMA, 'video': f'{int(args.video):02d}', 'mode': 'story',
                                                'language': args.language, 'chosen_at': now()})
        st['video_count'] = max(st.get('video_count', 0), int(args.video))
        st['stage'] = 'planning'
        write_json(rd / 'state.json', st)
        emit({'ok': True, 'locked': False, 'mode': 'story', 'intent_file': str(length_intent_path(outdir)),
              'next': 'Recorded: the story sets this video\'s length. Find the subject and state its own size '
                      '(runtime.natural_minutes), write the treatments with their movements, have them read blind '
                      'and decide; then run this command again and it locks the chosen treatment\'s own length. '
                      'Tell the user the figure before any paid narration.'})
        return
    if nl:
        members = [str(m.get('ref')) for m in nl.get('members') or [] if isinstance(m, dict) and m.get('ref') in vids]
        names = {str(nl.get('name') or '').strip().lower(), str(nl.get('niche_id') or '').strip().lower()}
        if niche_arg and niche_arg not in names:
            error('This run is one niche only. Use clone for a different niche.',
                  {'locked_niche': nl.get('name'), 'requested': niche_arg})
        map_cohort = next((c for c in nl.get('comparable_cohorts') or []
                           if str(c.get('id') or '').strip().lower() == cohort_id), None) if cohort_id else None
        if map_cohort:
            family = {i: vids[i] for i in map_cohort.get('refs') or [] if i in vids}
            if not forms_why:
                forms_why = str(map_cohort.get('why_comparable') or '')
        elif cohort_id:
            family = {i: vids[i] for i in members
                      if str((cards.get(i) or {}).get('cohort_id') or '').strip().lower() == cohort_id}
            if not family:
                error('No comparable cohort with that id in the locked niche',
                      {'cohort_id': cohort_id, 'niche': nl.get('name'),
                       'cohorts': [c.get('id') for c in nl.get('comparable_cohorts') or []]})
        elif form_arg:
            family = {i: vids[i] for i in members
                      if str((cards.get(i) or {}).get('story_form') or '').strip().lower() == form_arg}
            if not family:
                error('No reference of that story form in the locked niche', {'form': form_arg, 'niche': nl.get('name')})
        else:
            family = {i: vids[i] for i in members}
        effective_niche = str(nl.get('name') or '').strip()
        effective_form = form_arg
    else:
        if not cohort_id and not (niche_arg and form_arg):
            error('Provide either --cohort-id or both --niche and --story-form')
        if cohort_id:
            family = {i: vids[i] for i, c in cards.items()
                      if str(c.get('cohort_id', '')).strip().lower() == cohort_id}
            if not family:
                error('No references with that cohort_id in their cards', {'cohort_id': cohort_id})
            effective_niche = '__cohort__:' + cohort_id
            effective_form = ''
        else:
            family = {i: vids[i] for i, c in cards.items()
                      if niche_arg in [str(x).lower() for x in c.get('niches') or []]
                      and str(c.get('story_form', '')).lower() == form_arg}
            if not family:
                error('No references in selected niche and story form', {'niche': niche_arg, 'form': form_arg})
            effective_niche = niche_arg
            effective_form = form_arg
    if st.get('selected_niche') and str(st['selected_niche']).strip().lower() != effective_niche.lower():
        error('This run is one niche/channel only. Use clone for a different niche.',
              {'locked_niche': st['selected_niche'], 'requested': effective_niche})
    refs = normalize_refs(args.refs)
    if args.mode == 'standard':
        if len(refs) < 2:
            error('Standard requires >=2 explicitly selected comparable reference IDs (no mixed-folder averages).')
        if any(x not in family for x in refs):
            error('A selected reference is not in the selected group', {'refs': refs, 'group': sorted(family)})
        durations = [family[i]['duration_s'] for i in refs]
        # A cohort is the user's own group: its references may be of different story forms, whose lengths are made for
        # different kinds of video (a tutorial's and a documentary's median is neither's length).
        forms = sorted({str(cards[i].get('story_form') or '').strip().lower() for i in refs} - {''})
        if (cohort_id or nl) and len(forms) > 1 and n_words(forms_why) < MIN_NOTE_WORDS:
            error('This cohort mixes story forms: a Standard length from their median mixes lengths made for different '
                  'kinds of video. Choose references of one form, or say why these lengths compare (--forms-why).',
                  {'forms': forms, 'references': refs})
        if min(durations) < st['min_longform_s']:
            error('Standard cohort contains short-form; select long-form references only.', durations)
        if max(durations) / min(durations) > 1.8:
            error('Standard cohort spans incompatible runtime families; select a narrower group.', durations)
        target = round(statistics.median(durations)/5)*5
    elif story:
        # The story's own length: the chosen treatment's movements, added up; a re-lock (the written script showed
        # another size) names its minutes. The pace still comes from measured narration: the narrators the decision's
        # pacing calls relevant, or the ones named here, from anywhere in the analysed references (a narrator's pace
        # is a borrowed technique, weighed in decision.pacing).
        if args.minutes is not None and not prev_lock:
            error('The story\'s length comes from the chosen treatment\'s movements: give no --minutes on the first '
                  'lock. (--minutes belongs to a re-lock, with --revise, once the written script shows its real size.)')
        if args.minutes is not None and args.minutes <= 0:
            error('--minutes must be more than zero.')
        target = round((float(args.minutes) if args.minutes is not None else size['movements_minutes']) * 60 / 5) * 5
        if not refs:
            refs = [r for r in size['pace_references'] if r in vids]
        if not refs:
            error('The story sets the length; the pace still comes from measured narration. Name the narrators this '
                  'narration follows (--refs), or mark them relevant in decision.pacing.')
        if any(x not in vids for x in refs):
            error('A pace reference must be an analysed reference of this run.', {'refs': refs})
        family = {**family, **{r: vids[r] for r in refs}}
        story_why = (getattr(args, 'why', '') or '').strip()
        nat = size['natural_minutes']
        if nat and not nat[0] <= target / 60 <= nat[1] and n_words(story_why) < MIN_NOTE_WORDS:
            error('This length is outside the subject\'s own size as the direction judged it. One of the two is '
                  'wrong: revise that one, or say why this length is right (--why "...").',
                  {'length_minutes': round(target / 60, 2), 'natural_minutes': nat, 'treatment': size['treatment'],
                   'movements_minutes': size['movements_minutes']})
    else:
        if args.minutes is None or args.minutes <= 0:
            error('Own length requires --minutes N')
        target = round(args.minutes * 60)
        if not refs:
            refs = list(family)
        if any(x not in family for x in refs):
            error('An own-length reference must still match the selected group.', refs)
    if target < st['min_longform_s']:
        error('Target is shorter than long-form minimum configured for this run',
              {'target_s': target, 'minimum_s': st['min_longform_s'],
               **({'action': 'This story\'s own size is under the run\'s long-form minimum: choose another candidate '
                             'or angle that carries a long-form video, or take the shorter film to the user. Never '
                             'pad.'} if story else {})})
    computed_wpm, per_ref_wpm = compute_ref_wpm(rd, refs, family)
    if args.pace_wpm is not None and n_words(getattr(args, 'pace_why', '')) < 4:
        error('An explicit pace is a decision: say why this pace fits this narrator, niche and treatment (--pace-why).')
    spread = [float(x) for x in (per_ref_wpm or {}).values() if x]
    if args.pace_wpm is None and len(spread) >= 2 and max(spread) / min(spread) > PACE_SPREAD_MAX:
        # narrators this different are not averaged into a pace nobody has (2026-11-24 audit)
        error('The references speak at very different paces: their average is no narrator\'s pace. Choose references '
              'whose narration this video follows, or give the pace with its reason (--pace-wpm, --pace-why).',
              {'per_reference_wpm': per_ref_wpm})
    want_lang = str(args.language or '').strip().lower()[:2]
    other_lang = {r: str(read_json(rd / '10-media' / r / 'transcript.json').get('language') or '').lower()[:2]
                  for r in refs}
    other_lang = {r: l for r, l in other_lang.items() if l and want_lang and l != want_lang}
    if other_lang and args.pace_wpm is None:
        error('A reference narrated in another language cannot set this video\'s pace (words per minute differ by '
              'language): choose references in the run\'s language, or give the pace yourself (--pace-wpm).',
              {'run_language': want_lang, 'references': other_lang})
    if args.pace_wpm is not None:
        pace_wpm = args.pace_wpm
        pace_wpm_source = 'explicit'
    elif computed_wpm is not None:
        pace_wpm = computed_wpm
        pace_wpm_source = 'computed_from_refs'
    else:
        error('Cannot determine pace_wpm: no transcripts found in 10-media/ for the selected refs. '
              'Run prepare first, or pass --pace-wpm explicitly.')
    # The word budget comes from how many words a minute of the comparable narration really holds, pauses included
    # (overall_wpm), never from the speaking rate alone (active_wpm, which leaves every pause out: on 2026-11-19 that
    # overstated the budget by about 11%). An explicit --pace-wpm scales the references' overall rate by the same ratio.
    stats = {vid: ref_pace_stats(rd, vid, family[vid].get('duration_s')) for vid in refs}
    stats = {k: v for k, v in stats.items() if v}
    def mean_of(key):
        vals = [s[key] for s in stats.values() if s.get(key)]
        return round(statistics.mean(vals)) if vals else None
    active_refs, overall_refs = mean_of('active_wpm'), mean_of('overall_wpm')
    speech_only_words = round(target * pace_wpm / 60)
    if overall_refs and active_refs:
        target_words = round(target * overall_refs * (pace_wpm / active_refs) / 60)
    else:
        target_words = speech_only_words
    pace_profile = {'active_wpm': pace_wpm, 'overall_wpm': round(overall_refs * pace_wpm / active_refs)
                    if overall_refs and active_refs else None, 'runtime_wpm': mean_of('runtime_wpm'),
                    'references': stats, 'definitions': PACE_DEFINITIONS}
    lock = {'schema': SCHEMA, 'video': f'{int(args.video):02d}', 'mode': args.mode,
            'target_length_s': target, 'tolerance_audio_pct': 0.04, 'tolerance_export_pct': 0.025,
            'niche': effective_niche, 'story_form': effective_form, 'reference_ids': refs,
            'reference_durations_s': {i: family[i]['duration_s'] for i in refs},
            'language': args.language, 'pace_wpm': pace_wpm, 'pace_wpm_source': pace_wpm_source,
            **({'pace_why': args.pace_why} if getattr(args, 'pace_why', '') else {}),
            'per_ref_wpm': per_ref_wpm, 'pace_profile': pace_profile,
            'target_words': target_words, 'target_words_speech_only': speech_only_words,
            # How the comparable narrators pause (same yardstick narration-measure uses on the generated voice):
            # the evidence the script stage reads before deciding any pause, hold or tag.
            'reference_pause_profiles': ref_pause_profiles(rd, refs),
            'locked_at': now(), 'rule': 'Immutable unless user explicitly approves a revised length.'}
    if nl:
        lock.update({'niche_id': nl.get('niche_id'), 'niche_lock_sha256': canonical_sha(nl),
                     **({'cohort_id': cohort_id} if cohort_id else {})})
    if cohort_id or nl:
        lock['story_forms'] = sorted({str(cards[i].get('story_form') or '').strip().lower() for i in refs} - {''})
        if forms_why:
            lock['forms_why'] = forms_why
    if prev_lock:
        # the earlier lock stays on record, whole; the beat map, script and every later gate follow the new one
        lock.update({'revised_because': revise, 'approved_by_user': approved,
                     'history': (prev_lock.get('history') or []) + [{k: v for k, v in prev_lock.items()
                                                                     if k != 'history'}]})
        if own_relock and not approved:
            lock['revised_by'] = 'the director: the story sets this length and nothing was recorded yet'
    if story:
        # what the length was taken from, beside it: the treatment and its movements, the subject's own range, and on
        # a re-lock the script it was measured from
        words_now = sum(count_words(x.get('text', '')) for x in read_json(outdir / 'script.json').get('lines') or []
                        if isinstance(x, dict))
        lock['story_size'] = {k: size[k] for k in ('treatment', 'movements_minutes', 'candidate', 'natural_minutes')}
        if story_why:
            lock['story_size']['why'] = story_why
        if prev_lock and words_now:
            lock['story_size']['script_words'] = words_now
        lock['rule'] = STORY_LENGTH_RULE
    write_json(lockfile, lock)
    st['selected_niche'] = effective_niche
    st['video_count'] = max(st.get('video_count', 0), int(args.video))
    st['stage'] = 'planning'
    write_json(rd / 'state.json', st)
    wpm_note = (f'pace_wpm={pace_wpm} (computed from refs: {per_ref_wpm})'
                if pace_wpm_source == 'computed_from_refs'
                else f'pace_wpm={pace_wpm} (explicit override)')
    words_note = (f'Write the script to about {target_words} words: the comparable narration holds '
                  f'{pace_profile["overall_wpm"]} words a minute with its own pauses ({pace_wpm} while speaking). '
                  if pace_profile['overall_wpm'] else
                  f'Write the script to under {speech_only_words} words (speech alone, no pauses counted: the '
                  'references have no word timings here). ')
    emit({'ok': True, 'lock_file': str(lockfile), 'locked_target_s': target, 'minutes': round(target/60, 2),
          'niche': effective_niche, 'story_form': effective_form, 'references': refs,
          'pace_wpm': pace_wpm, 'pace_wpm_source': pace_wpm_source, 'per_ref_wpm': per_ref_wpm,
          'pace_profile': pace_profile, 'target_words': target_words, 'target_words_speech_only': speech_only_words,
          **({'story_size': lock['story_size']} if story else {}),
          'guidance': (f'Script, beat map, narration, timeline and export must respect this exact locked target. '
                       f'{wpm_note}. {words_note}plan-check forecasts the real length from the voice\'s own measured '
                       'pace and gaps once its first part is measured.'
                       + (' The story set this length: when the first whole draft shows another size, re-lock to it '
                          'before narration (length --mode story --minutes N --revise "why"); never pad or squeeze '
                          'to keep a number. Tell the user the figure before any paid narration.' if story else ''))})


TAG_RE = re.compile(r'\[([^\[\]]{1,160})\]')
TAGS_FILE = ROOT / 'data' / 'elevenlabs-audio-tags.json'
TTS_MODELS = ('eleven_v4', 'eleven_v4_turbo')   # the user's standing rule: these two models only
# The older pause form (`pause_after_s`): up to this long it was taken as the voice's own gap (nothing realised);
# longer, it was silence ADDED ON TOP of that gap. Kept so older scripts read as they were written and reviewed.
NATURAL_PAUSE_MAX_S = 1.0
# Natural gap per script line before this run's voice is measured (eleven_v4 here, 2026-11-19: 0.36-0.42 s).
DEFAULT_LINE_OVERHEAD_S = 0.4
# The silence after one line before this voice is measured, for a planned pause's estimate only (one eleven_v4
# narrator, 2026-11-21, from the audio: median 0.61 s, 0.19-0.79 s line to line). Once recorded, each line's own gap
# is used.
DEFAULT_NATURAL_GAP_S = 0.6
# What a planned pause has to say besides its length (03): what it is for, what the viewer sees while it lasts, what
# the sound does. Required of every planned pause, read by the cold reader, and carried into the edit.
PAUSE_TEXT_FIELDS = (('pause_purpose', 'needs_its_story_purpose'), ('pause_picture', 'needs_its_picture'),
                     ('pause_sound', 'needs_its_sound'))
# A planned silence is part of a performance (05 "Narration as a performance"): how the line before it should land and
# how the next line should start again are planned with it, before anything is recorded (pause_total_s form).
PAUSE_PERFORMANCE_FIELDS = (('pause_landing', 'needs_how_the_line_lands'),
                            ('pause_resume', 'needs_how_the_next_line_starts'))
# Seconds a cue may add, as a band, when this voice has not been measured with it (05): a catalogue value was measured
# on another voice (x0.5-1.5), a pause wording without one 1-3 s, a delivery cue may slow or quicken its own line a
# little. Assumptions, labelled as such, replaced by this voice's own observations once a take exists.
TAG_BAND_CATALOGUE = (0.5, 1.5)
TAG_BAND_PAUSE_UNKNOWN_S = (1.0, 3.0)
TAG_BAND_DELIVERY_S = (-0.3, 0.6)


def strip_tags(text):
    """The spoken words of a line: inline [audio tags] are sent to ElevenLabs but never spoken."""
    return re.sub(r'[ \t]{2,}', ' ', TAG_RE.sub(' ', str(text))).strip()


def count_words(text):
    return len(re.findall(r"\b[\w]+(?:[-'][\w]+)*\b", strip_tags(text), flags=re.UNICODE))


_TAG_CATALOGUE = None


def tag_catalogue():
    global _TAG_CATALOGUE
    if _TAG_CATALOGUE is None:
        data = read_json(TAGS_FILE)
        _TAG_CATALOGUE = {' '.join(str(t['tag']).lower().split()): t for t in data.get('tags') or []}
    return _TAG_CATALOGUE


def classify_tag(inner):
    """The catalogue entry of one tag (its text inside the brackets). The vocabulary is open: a tag the
    catalogue doesn't list is 'custom', allowed, and judged on the calibration part (its measured delivery)."""
    key = '[' + ' '.join(str(inner).lower().split()) + ']'
    entry = tag_catalogue().get(key)
    if entry:
        return entry
    if 'accent' in key:
        return {'tag': key, 'category': 'accent_character', 'pipeline_status': 'not_for_narration'}
    return {'tag': key, 'category': 'pause' if 'pause' in key else 'custom', 'pipeline_status': 'custom'}


def tag_cost_s(tag, measured_costs=None):
    """Seconds a tag adds: this voice's measured value (narration-measure) first, else the catalogue's
    approximate one, else 2 s for any pause wording and 0 for a delivery tag."""
    if measured_costs and tag in measured_costs:
        return float(measured_costs[tag])
    entry = tag_catalogue().get(tag) or {}
    if entry.get('approx_cost_s') is not None:
        return float(entry['approx_cost_s'])
    return 2.0 if 'pause' in tag else 0.0


SEAM_FALL_RATIO, SEAM_RESET_RATIO = 1.5, 1.6


def seam_boundary_effects(last_cad, usual):
    """How a join between two recorded parts may have changed the delivery (05): the last line of a part falling much
    harder than this voice usually lands a line (it can sound like an ending), and the next part starting much higher
    than its usual restart (a fresh beginning). Facts to listen for, never a verdict: at a chapter turn a fresh start
    belongs; inside a scene it is the recording boundary showing."""
    out = []
    if not last_cad or not usual:
        return out
    f, uf = last_cad.get('last_vowel_fall_st'), usual.get('last_vowel_fall_st')
    if isinstance(f, (int, float)) and isinstance(uf, (int, float)) and uf < 0 and f <= uf * SEAM_FALL_RATIO:
        out.append(f'the part ends with a harder fall than usual ({f:+.1f} st against {uf:+.1f}): it may sound like an ending')
    r, ur = last_cad.get('next_reset_st'), usual.get('next_reset_st')
    if isinstance(r, (int, float)) and isinstance(ur, (int, float)) and ur > 0 and r >= ur * SEAM_RESET_RATIO:
        out.append(f'the next part starts higher than usual ({r:+.1f} st against {ur:+.1f}): it may sound like a fresh '
                   'beginning')
    return out


def tag_estimate(tag, category, measured=None):
    """What one cue may add to the narration, as a band (05): this voice setup's own observations when a take has
    measured it (the silence a pause cue left beyond the usual gap; the time a delivery cue added to its line), else
    a labelled assumption. Never a universal number, and never assumed to add up exactly across a passage."""
    obs = [o for o in ((measured or {}).get('cue_observations') or []) if o.get('tag') == tag]
    key = 'excess_s' if category == 'pause' else 'line_extra_s'
    xs = [float(o[key]) for o in obs if isinstance(o.get(key), (int, float))]
    if xs:
        return {'tag': tag, 'low_s': round(min(xs), 2), 'high_s': round(max(xs), 2), 'n': len(xs),
                'basis': f'measured on this voice setup ({len(xs)} occurrence{"s" if len(xs) != 1 else ""})'}
    entry = tag_catalogue().get(tag) or {}
    if category == 'pause':
        if entry.get('approx_cost_s') is not None:
            a = float(entry['approx_cost_s'])
            return {'tag': tag, 'low_s': round(a * TAG_BAND_CATALOGUE[0], 2), 'high_s': round(a * TAG_BAND_CATALOGUE[1], 2),
                    'n': 0, 'basis': 'catalogue value measured on another voice: a band until this voice is measured'}
        return {'tag': tag, 'low_s': TAG_BAND_PAUSE_UNKNOWN_S[0], 'high_s': TAG_BAND_PAUSE_UNKNOWN_S[1], 'n': 0,
                'basis': 'pause wording not measured anywhere: an assumed band'}
    return {'tag': tag, 'low_s': TAG_BAND_DELIVERY_S[0], 'high_s': TAG_BAND_DELIVERY_S[1], 'n': 0,
            'basis': 'delivery cue not measured on this voice: may slow or quicken its line a little (assumed band)'}


def script_tags(lines):
    """Every inline tag in the script, with its catalogue status. Refuses only what a pipeline rule excludes
    (not_for_narration) and broken brackets; which tags fit the story is the agents' decision (05)."""
    found, issues = [], []
    for i, row in enumerate(lines):
        text = str(row.get('text') or '')
        lid = str(row.get('id') or f'L{i+1:03d}')
        if text.count('[') != text.count(']') or re.search(r'\[[^\]]*\[', text) or re.search(r'\][^\[]*\]', text):
            issues.append(f'audio_tag_malformed_brackets:{lid}')
        for m in TAG_RE.finditer(text):
            entry = classify_tag(m.group(1))
            found.append({'line': lid, 'index': i + 1, 'tag': entry['tag'], 'category': entry.get('category'),
                          'status': entry.get('pipeline_status'), 'at_line_start': not text[:m.start()].strip(),
                          'at_line_end': not text[m.end():].strip(), 'words_before': count_words(text[:m.start()])})
            if entry.get('pipeline_status') == 'not_for_narration':
                issues.append(f'audio_tag_not_for_narration:{lid}:{entry["tag"]}')
        if text.strip() and not strip_tags(text):
            issues.append(f'line_has_only_tags:{lid}')
    return found, issues


def is_pause_tag(inner):
    return classify_tag(inner).get('category') == 'pause'


def _pause_tags_around(lines, i):
    """The pause tags at line i's end and at the next line's start: where a performed pause sits."""
    here = str(lines[i].get('text') or '').rstrip()
    after = str(lines[i + 1].get('text') or '').lstrip() if i + 1 < len(lines) else ''
    ends = [m.group(1) for m in (re.search(r'\[([^\[\]]+)\]\s*$', here), re.match(r'\s*\[([^\[\]]+)\]', after)) if m]
    return [x for x in ends if is_pause_tag(x)]


def script_pause_plan(lines):
    """Each planned pause, how it is realised and what it is for. A pause is a proposal until the voice is measured
    (hold-decide), so the script says the experience it wants, never a length to insert mechanically:
    - `pause_total_s`: the WHOLE silence the viewer hears after the line, the voice's own gap included. The edit adds
      only the difference between it and the gap the voice really left there (measured), never the whole of it.
    - `pause_via`: 'edit' (a hold the edit adds: exact, free, adjustable) or 'tag' (a pause tag at this line's end or
      the next line's start, performed by the voice: costs its measured time inside the narration).
    - `pause_purpose`, `pause_picture`, `pause_sound`: what it is for, what the viewer sees while it lasts (what changes
      on screen, or why one frame holds), what the sound does (the bed goes on, drops out, one story-world sound).
    The older form, `pause_after_s`, is read as it was written and reviewed: over 1 s, silence ADDED ON TOP of the
    voice's own gap; up to 1 s, nothing to realise (`form` 'added')."""
    plan, issues = [], []
    for i, row in enumerate(lines):
        lid = str(row.get('id') or f'L{i+1:03d}')
        via = str(row.get('pause_via') or '').strip().lower()
        if via and via not in ('natural', 'tag', 'edit'):
            issues.append(f'pause_via_invalid:{lid}')
            continue
        has_total = row.get('pause_total_s') not in (None, '')
        try:
            total = float(row['pause_total_s']) if has_total else None
            after = float(row.get('pause_after_s') or 0)
        except (TypeError, ValueError):
            issues.append(f'pause_seconds_invalid:{lid}')
            continue
        if has_total and after:
            issues.append(f'pause_{lid}_has_both_pause_total_s_and_pause_after_s:write_only_pause_total_s')
            continue
        if has_total:
            if total <= 0:
                issues.append(f'pause_total_s_invalid:{lid}')
                continue
            if via not in ('tag', 'edit'):
                issues.append(f'pause_{lid}_needs_pause_via_edit_or_tag')
                continue
            form, seconds = 'total', total
        else:
            if after <= NATURAL_PAUSE_MAX_S and via in ('', 'natural'):
                continue
            if via in ('', 'natural'):
                issues.append(f'pause_{lid}_over_{NATURAL_PAUSE_MAX_S:g}s_needs_pause_via_tag_or_edit')
                continue
            form, seconds = 'added', after
        tags_here = _pause_tags_around(lines, i)
        if via == 'tag' and not tags_here:
            issues.append(f'pause_{lid}_via_tag_but_no_pause_tag_at_this_line_end_or_next_line_start')
        residual = False
        if via == 'edit' and tags_here:
            if form == 'total':
                # One silence, decided as a whole: the voice performs part of it with its pause cue, and the edit adds
                # only what that measured pause leaves (hold-decide measures the gap the take really has). A residual,
                # never a second pause on top.
                residual = True
            else:
                # The older added-on-top form would put a full hold on top of the cue's pause: that stacks.
                issues.append(f'pause_{lid}_is_an_edit_hold_and_a_pause_tag_at_once:choose_one')
        # A silence the story wants says what it is for, what is on screen while it lasts and what the sound does. A
        # written reason is not an approval: the length is decided against the recorded voice and the picture.
        for field, issue in PAUSE_TEXT_FIELDS:
            if n_words(row.get(field)) < MIN_NOTE_WORDS:
                issues.append(f'pause_{lid}_{issue}')
        if form == 'total':
            for field, issue in PAUSE_PERFORMANCE_FIELDS:
                if n_words(row.get(field)) < MIN_NOTE_WORDS:
                    issues.append(f'pause_{lid}_{issue}')
        plan.append({'line': lid, 'index': i + 1, 'via': via, 'form': form, 'seconds': seconds,
                     'residual_of_tag': residual,
                     'total_s': seconds if form == 'total' else None,
                     'added_s': seconds if form == 'added' else None,
                     'purpose': str(row.get('pause_purpose') or '').strip() or None,
                     'picture': str(row.get('pause_picture') or '').strip() or None,
                     'sound': str(row.get('pause_sound') or '').strip() or None,
                     'landing': str(row.get('pause_landing') or '').strip() or None,
                     'resume': str(row.get('pause_resume') or '').strip() or None})
    return plan, issues


def hold_snapshot(lines):
    """Every planned pause as the script's cold reader is shown it: {line: [seconds, via]} (seconds as written:
    the whole silence for pause_total_s, the added silence for the older pause_after_s)."""
    return {p['line']: [round(p['seconds'], 2), p['via']] for p in script_pause_plan(lines)[0]}


def planned_added_s(p, gap_s=None):
    """The silence the edit adds for one planned pause before it is decided: the older form as written; the whole-
    silence form less the voice's gap there (measured, else the voice's usual gap, else DEFAULT_NATURAL_GAP_S). A
    performed pause (via tag) adds nothing in the edit."""
    if p['via'] != 'edit':
        return 0.0
    if p['form'] == 'added':
        return float(p['added_s'])
    return max(0.0, float(p['total_s']) - float(DEFAULT_NATURAL_GAP_S if gap_s is None else gap_s))


def edit_holds_s(lines, gaps=None):
    """The silence the planned edit holds add, before any is decided (gaps: {line index: the voice's gap there})."""
    plan, _ = script_pause_plan(lines)
    return round(sum(planned_added_s(p, (gaps or {}).get(p['index'])) for p in plan), 2)


# ---------------------------------------------------------------- held silences: proposed, measured, decided
# A planned pause is a proposal. Its length is decided twice, each time on evidence the script stage could not have:
# after the narration is recorded (`hold-decide --stage narration`: the gap the voice really left at that line, the
# voice's own rhythm around it, a listening preview) and once the pictures exist (`--stage picture`: the shot on screen
# while it lasts). Each decision names the whole silence wanted (or no hold) and why; the edit adds only the difference
# with the measured gap. Decisions live in 40-plans/video-NN/holds.json (every earlier one kept in its history), apart
# from the reviewed script, so a measured adjustment never re-opens the script read; the final watch review sees the
# silences as they are in the cut. Code gathers and checks the process; which length serves the moment is the
# director's call, never a formula's.
HOLD_STAGES = ('narration', 'picture')
HOLD_VERIFY_TOL_S = 0.06       # an inserted silence measured in the edit's narration lands this close to the decision
# The transition into and out of a held silence, decided with it, never applied by default. 'clean' keeps the voice
# exactly as recorded: its own ending, its own breath, an immediate stop (often the right one for a joke or a reveal).
# 'fade' works ONLY on the voice's own quiet inside the silence (its room tone), never on a syllable, a release or a
# breath, and only when that quiet is audible and long enough: it smooths room tone into and out of the added silence.
# The bed (music, ambience) is the bigger lever and is carried to the edit with exact times: it goes on, enters,
# stops, dips or swells around the silence, or there is none.
TRANSITION_INTO = ('clean', 'fade')
TRANSITION_OUT = ('clean', 'fade')
BED_MOVES = ('continues', 'enters', 'stops', 'dips', 'swells', 'none')
BED_KINDS = ('music', 'ambience', 'bed')        # timeline.json audio_tracks kinds that make the bed
FADE_MIN_S, FADE_MAX_S, FADE_MARGIN_S = 0.08, 0.3, 0.02


def fade_windows(gap, into='clean', out_of='clean', last_line=False):
    """Where a transition fade may act inside one silence (gap: measured_gap or line_gaps' facts, on the narration's
    clock): only on the quiet stretch the added silence goes into, from FADE_MARGIN_S inside its edges to the splice,
    at most FADE_MAX_S long. Returns ({'into': [a, b] | None, 'out_of': [a, b] | None}, problems): a problem means
    the fade cannot be done without touching the voice or without changing nothing at all."""
    res, problems = {'into': None, 'out_of': None}, []
    if into == 'clean' and out_of == 'clean':
        return res, problems
    sub, at = gap.get('subrun_s'), gap.get('insert_at_s')
    if gap.get('basis') != 'audio' or not sub or at is None:
        return res, ['no measured quiet stretch here to fade: the silence was not read from the audio']
    floor = gap.get('floor_under_speech_db')
    audible = float(_av().AUDIBLE_FLOOR_UNDER_DB)
    if floor is None or float(floor) > audible:
        problems.append(f'the voice\'s own silence here is {floor} dB under its speech (audible room tone starts within '
                        f'{audible:g} dB): it is silence already, a fade would change nothing anyone can hear')
    if into == 'fade':
        a, b = float(sub[0]) + FADE_MARGIN_S, float(at)
        if b - a < FADE_MIN_S:
            problems.append(f'only {max(0.0, b - a):.2f} s of quiet before the splice: too little to fade without '
                            'reaching the end of the line')
        else:
            res['into'] = [round(max(a, b - FADE_MAX_S), 3), round(b, 3)]
    if out_of == 'fade':
        if last_line:
            problems.append('nothing follows the last line: there is no way out of this silence to fade')
        else:
            a, b = float(at), float(sub[1]) - FADE_MARGIN_S
            if b - a < FADE_MIN_S:
                problems.append(f'only {max(0.0, b - a):.2f} s of quiet after the splice: too little to fade without '
                                'reaching the next line')
            else:
                res['out_of'] = [round(a, 3), round(min(b, a + FADE_MAX_S), 3)]
    return res, problems


def line_ending_mark(text):
    """The punctuation a line ends on (the writer's cadence the voice follows): '.', '?', '!', ',', ':', ';', '...',
    a dash, or '' when it ends on a word."""
    t = strip_tags(str(text or '')).rstrip().rstrip('"\'”’)')
    for mark in ('...', '…', '—', '--', '-', '.', '?', '!', ',', ':', ';'):
        if t.endswith(mark):
            return {'…': '...', '—': 'dash', '--': 'dash', '-': 'dash'}.get(mark, mark)
    return ''


def holds_path(rd, video):
    return video_dir(rd, video) / 'holds.json'


def hold_decisions(rd, video):
    d = read_json(holds_path(rd, video))
    return {'decisions': d.get('decisions') or {}, 'history': d.get('history') or []}


def line_times_state(rd, video):
    """line-times.json, whether it still describes the recorded parts, and each part's current fingerprint."""
    n = int(video)
    folder = rd / '50-audio' / f'video-{n:02d}'
    lt = read_json(folder / 'line-times.json')
    manifest = read_json(folder / 'manifest.json')
    prints = {int(c['id']): quick_fingerprint(folder / c['file']) for c in manifest.get('chunks') or []
              if c.get('id') is not None and (folder / c.get('file', '__missing__')).is_file()}
    current = bool(lt.get('parts')) and all(p.get('fingerprint') == prints.get(int(p.get('id'))) for p in lt['parts'])
    return lt, current, prints


def measured_gap(rows, index, nlines):
    """The silence the voice left after one line, as narration-measure read it from the audio (Whisper's gap on an
    older measurement). rows: {line index: line-times row}. None when the line is not recorded yet; natural_gap_s None
    when the next line is not (the silence after a line exists only once both sides are recorded)."""
    r = rows.get(index)
    if not r:
        return None
    nx = rows.get(index + 1)
    parts = {str(r.get('part')): None}
    if nx:
        parts[str(nx.get('part'))] = None
    if 'gap_after_s' in r:
        return {'natural_gap_s': r.get('gap_after_s'), 'basis': r.get('gap_basis') or 'audio',
                'span_s': r.get('gap_span_s'), 'parts': parts, 'subrun_s': r.get('gap_subrun_s'),
                'insert_at_s': r.get('gap_insert_at_s'), 'floor_under_speech_db': r.get('gap_floor_under_speech_db'),
                'other_material_s': r.get('gap_other_material_s'), 'cadence': r.get('cadence')}
    if nx and nx.get('start_s') is not None and r.get('end_s') is not None:
        return {'natural_gap_s': round(max(0.0, nx['start_s'] - r['end_s']), 3), 'basis': 'whisper',
                'span_s': [r['end_s'], nx['start_s']], 'parts': parts}
    return {'natural_gap_s': None, 'basis': 'unknown', 'span_s': None, 'parts': parts}


def voice_gap_profile(lt):
    """How long this voice pauses between lines, from the audio: the yardstick a held silence is set against."""
    gs = [float(r['gap_after_s']) for r in lt.get('lines') or []
          if r.get('gap_basis') == 'audio' and r.get('gap_after_s') is not None and not r.get('gap_is_tail')]
    if not gs:
        return {}
    q = sorted(gs)
    pick = lambda f: q[min(len(q) - 1, max(0, int(round(f * (len(q) - 1)))))]
    return {'lines': len(gs), 'median_s': round(statistics.median(gs), 2), 'p10_s': round(pick(.1), 2),
            'p90_s': round(pick(.9), 2), 'shortest_s': round(q[0], 2), 'longest_s': round(q[-1], 2)}


def _line_beats(vd):
    out = {}
    for b in read_json(vd / 'beat-map.json').get('beats') or []:
        try:
            for k in range(int(b['line_start']), int(b['line_end']) + 1):
                out[k] = str(b.get('id'))
        except (KeyError, TypeError, ValueError):
            continue
    return out


def hold_shot(rd, video, index):
    """The shot on screen while the silence after line `index` lasts (a hold belongs to the shot before the cut), the
    shot after it when the cut falls there, and the still each one shows now (callbacks show the shot they reuse)."""
    n = int(video)
    shots = read_json(artifact_path(rd, n, 'shot-plan')).get('shots') or []
    lines = read_json(video_dir(rd, n) / 'script.json').get('lines') or []
    pos = {str(r.get('id') or f'L{i + 1:03d}'): i + 1 for i, r in enumerate(lines)}
    prov = read_json(artifact_path(rd, n, 'stills')).get('images') or {}
    latest = {}
    for path, rec in prov.items():
        sid = str(rec.get('shot_id'))
        if Path(path).is_file() and str(rec.get('made_at') or '') >= str((latest.get(sid) or ('', None))[0]):
            latest[sid] = (str(rec.get('made_at') or ''), path)
    by_id = {str(s.get('id')): s for s in shots}

    def still_of(s):
        src = str(s.get('reuses') or s.get('id'))
        hit = latest.get(src)
        return ({'still': hit[1], 'still_fingerprint': quick_fingerprint(Path(hit[1]))} if hit else
                {'still': None, 'still_fingerprint': None})
    # the LAST shot over the line: a line can hold a cut on a word (start_word), and the silence after the line
    # belongs to the shot that ends it
    for k in range(len(shots) - 1, -1, -1):
        s = shots[k]
        a, b = pos.get(str(s.get('line_start'))), pos.get(str(s.get('line_end')))
        if a is None or b is None or not a <= index <= b:
            continue
        out = {'shot_id': str(s.get('id')), 'new_thing': s.get('new_thing'), **still_of(s)}
        if index == b and k + 1 < len(shots):
            nxt = shots[k + 1]
            out['next_shot'] = {'shot_id': str(nxt.get('id')), **still_of(by_id.get(str(nxt.get('id'))) or nxt)}
        return out
    return None


def hold_facts(rd, video, lines=None):
    """Every planned pause (script.json) and every decided hold (holds.json): the proposal, the gap the voice really
    left there (once both sides are recorded), the decision in force and whether it still stands (the part it was
    decided on unchanged), and the silence the edit adds: decided, or estimated while provisional. Gathers and
    calculates; it never judges a hold."""
    n = int(video)
    vd = video_dir(rd, n)
    if lines is None:
        lines = read_json(vd / 'script.json').get('lines') or []
    plan, _ = script_pause_plan(lines)
    by_line = {p['line']: p for p in plan}
    index = {str(r.get('id') or f'L{i + 1:03d}'): i + 1 for i, r in enumerate(lines)}
    lt, current, prints = line_times_state(rd, n)
    rows = {int(r['index']): r for r in lt.get('lines') or []} if current else {}
    prof = voice_gap_profile(lt) if current else {}
    usual = prof.get('median_s') or (voice_measurement(rd, n) or {}).get('natural_gap_s')
    decs = hold_decisions(rd, n)['decisions']
    beats = _line_beats(vd)
    cue_costs = (voice_measurement(rd, n) or {}).get('tag_costs_s')
    out = []
    for lid in sorted(set(by_line) | set(decs), key=lambda x: (index.get(x) or 10 ** 6, x)):
        i, p, d = index.get(lid), by_line.get(lid), decs.get(lid)
        if i is None:
            out.append({'line': lid, 'status': 'line_not_in_script', 'added_s': 0.0, 'decision': d})
            continue
        g = measured_gap(rows, i, len(lines))
        text = strip_tags(lines[i - 1].get('text') or '')
        after = strip_tags(lines[i].get('text') or '') if i < len(lines) else ''
        row = {'line': lid, 'index': i, 'beat': beats.get(i), 'words_before': text[-90:], 'words_after': after[:70],
               'proposal': ({k: p[k] for k in ('form', 'seconds', 'via', 'purpose', 'picture', 'sound')} if p else None),
               'natural_gap_s': g.get('natural_gap_s') if g else None, 'gap_basis': g.get('basis') if g else 'not_recorded',
               'status': 'provisional', 'decision': None,
               # How the line before it ends and the next begins (narration-measure, from the audio; the punctuation
               # from the script), and what the silence itself holds: what a transition is decided on.
               'ending': {'punctuation': line_ending_mark(lines[i - 1].get('text')), **((g or {}).get('cadence') or {})},
               'inside_silence': ({k: g.get(k) for k in ('insert_at_s', 'subrun_s', 'floor_under_speech_db',
                                                         'other_material_s')} if g else None)}
        # A silence planned through a pause cue: what the cue gave, judged with a tolerance (close is a success, the
        # model's timing can't be steered to the millisecond): achieved is kept as performed, nothing added.
        if p and p.get('via') == 'tag' and p.get('form') == 'total' and row['natural_gap_s'] is not None:
            row['cue_result'] = pause_cue_outcome(p.get('seconds'), row['natural_gap_s'])
        if d:
            fresh = bool(d.get('parts')) and all(prints.get(int(k)) == v for k, v in (d.get('parts') or {}).items())
            if fresh:
                row.update({'status': f'decided_{d.get("stage")}', 'decision': d, 'added_s': float(d.get('added_s') or 0),
                            'added_is_estimate': False, 'total_s': d.get('total_s'),
                            'natural_gap_s': d.get('natural_gap_s')})
            else:
                row.update({'status': 'stale', 'decision': d,
                            'why_stale': 'the part this line sits in was re-recorded after the decision'})
        if row['status'] in ('provisional', 'stale'):
            gap = row['natural_gap_s'] if row['natural_gap_s'] is not None else usual
            # A pause cue that performs part of a whole silence (a residual) is never free: until the line is measured
            # with it, the edit is planned to add only what the cue's expected pause leaves. The cue's time is counted
            # once, in the narration's tag time; once measured, the gap already holds it.
            cue_s = 0.0
            if p and p.get('residual_of_tag') and row['natural_gap_s'] is None:
                cue_s = sum(tag_cost_s(f'[{t}]', cue_costs) for t in _pause_tags_around(lines, i - 1))
            row['added_s'] = round(max(0.0, planned_added_s(p, gap) - cue_s), 2) if p else 0.0
            row['added_is_estimate'] = True
            row['estimate_from'] = ('this line\'s measured gap' if row['natural_gap_s'] is not None else
                                    'the voice\'s usual gap' if usual else f'{DEFAULT_NATURAL_GAP_S:g} s before any voice')
            if cue_s:
                row['estimate_from'] += f', less the pause cue\'s expected {cue_s:.2f} s (it performs part of this silence)'
                row['cue_expected_s'] = round(cue_s, 2)
            if p and p['form'] == 'added':
                row['estimate_from'] = 'the older pause_after_s: added on top of the voice\'s gap, as written'
            if (row.get('cue_result') or {}).get('outcome') == 'achieved':
                row['added_s'] = 0.0
                row['estimate_from'] = ('the performed pause is within tolerance of the whole silence planned: kept as '
                                        'performed')
        out.append(row)
    return {'holds': out, 'voice_gaps': prof, 'line_times_current': current,
            'endings_usual': (lt.get('cadence_usual') or {}) if current else {},
            'added_s': round(sum(h.get('added_s') or 0 for h in out), 2),
            'undecided': [h['line'] for h in out if h['status'] in ('provisional', 'stale')],
            'decided_narration': [h['line'] for h in out if h['status'] == 'decided_narration'],
            'decided_picture': [h['line'] for h in out if h['status'] == 'decided_picture']}


def hold_decisions_sha(rd, video):
    """What the edit plan was timed from: the silence decided at every line (whole and added) and its transition (the
    fades the edit's narration carries, what the bed does). A confirmation with the picture that keeps all of these
    changes nothing in the edit, so it asks for no new retime."""
    decs = hold_decisions(rd, video)['decisions']
    def tr(v):
        t = v.get('transition') or {}
        return [t.get('into') or 'clean', t.get('out_of') or 'clean', t.get('bed')]
    return canonical_sha({k: [v.get('total_s'), v.get('added_s')] + (tr(v) if v.get('transition') else [])
                          for k, v in sorted(decs.items())})


def hold_signals(plan):
    """Facts about the planned pauses as a set, for the director to read (never a verdict): lengths that step up or
    down in film order, or are all alike, can mean the length came from a pattern or a position instead of the moment."""
    secs = [round(float(p['seconds']), 2) for p in plan]
    out = []
    if len(secs) >= 3:
        if all(b > a for a, b in zip(secs, secs[1:])) or all(b < a for a, b in zip(secs, secs[1:])):
            out.append('the planned pauses ' + ('grow' if secs[-1] > secs[0] else 'shrink') + ' steadily through the film ('
                       + ', '.join(f'{s:g}' for s in secs) + ' s): check that each length comes from its own moment, '
                       'not from its place in the film')
        elif len(set(secs)) == 1:
            out.append(f'every planned pause is {secs[0]:g} s: check that each length comes from its own moment')
    return out


# Words that may break 02's content rules. A hit is not a verdict (a word can be plain, unavoidable fact): it
# must be answered, line by line, under a "Content flags" heading in editorial-review.md (rewritten, or why kept).
CONTENT_FLAGS = [
    ('holiday_religion_superstition', re.compile(
        r"\b(christmas|xmas|thanksgiving|easter|hanukkah|ramadan|diwali|halloween|new year's|holiday|holidays|feast|"
        r"church|chapel|chaplain|pray|prayed|praying|prayer|prayers|god|gods|heaven|miracle|miraculous|blessed|"
        r"blessing|omen|omens|luck|lucky|luckily|curse|cursed|ghost|ghosts|haunted|astrology|superstition)\b", re.I)),
    ('indecency', re.compile(
        r"\b(nude|nudes|nudity|naked|topless|undressed|unclothed|lingerie|underwear|bikini|bare-breasted)\b", re.I)),
    ('injury_gore_distress', re.compile(
        # "wound" as in "the road wound through the valley" is not a wound
        r"\b(blood|bloody|bled|bleed|bleeding|wound(?!\s+(?:through|around|round|along|up|down|its|their|back|into|over|past|"
        r"between|tightly|away))|wounds|gore|gory|corpse|corpses|severed|amputated|amputation|"
        r"limb|limbs|agony|scream|screamed|screaming|sobbing|terror|terrified|panic|panicked|despair|suicide|"
        r"vomit|vomited|needle|syringe|inject|injected)\b", re.I)),
    ('swearing', re.compile(r"\b(hell|damn|damned|goddamn|bastard|crap|shit|fuck)\b", re.I)),
]


def content_flags(lines, review_text, themes=()):
    m = re.search(r'^#+[^\n]*content flags?[^\n]*\n(.*?)(?=^#|\Z)', review_text or '', flags=re.I | re.M | re.S)
    section = m.group(1) if m else ''
    flags, issues = [], []
    for i, row in enumerate(lines):
        lid = str(row.get('id') or f'L{i+1:03d}')
        spoken = strip_tags(row.get('text') or '')
        found = [(kind, sorted({h.lower() for h in rx.findall(spoken)})) for kind, rx in CONTENT_FLAGS]
        # an excluded segment's theme (its review's "avoid") brought back in the words: rewritten, or why it isn't
        found += [(label, [ph]) for label, ph in theme_hits(spoken, themes)]
        for kind, hits in found:
            if hits:
                reviewed = bool(re.search(r'\b' + re.escape(lid) + r'\b', section))
                flags.append({'line': lid, 'kind': kind, 'terms': hits, 'reviewed': reviewed})
                if not reviewed:
                    issues.append(f'content_flag_unreviewed:{lid}:{kind}')
    return flags, issues


# ---------------------------------------------------------------- content: what a reference may lend, and to what
# Every reference gets a content review from the agent who watched it (01): its problem segments, each with its
# timestamps, what it is, what it does in the story, the evidence, how sure, and what is done with it. Two different
# things are recorded apart and never mixed: content safety (gore, distress, self-harm, ...: what must not be shown
# or reproduced) and the user's creative exclusions (religious or superstitious material, holidays: not harmful,
# just never used as a creative device here). Code checks the record's shape, that the closer looks it relies on
# were really taken, and that nothing excluded is cited or brought back downstream; the judgement is the agent's.
CONTENT_KINDS = ('safety', 'religion_superstition', 'holiday')
SAFETY_CATEGORIES = ('graphic_injury', 'distressing', 'self_harm', 'dangerous_acts', 'sexual_violence_exploitation',
                     'sexual_content_minors', 'hate_extremism', 'nudity_indecency', 'other')
CREATIVE_CATEGORIES = {'religion_superstition': ('religious', 'superstition'), 'holiday': ('holiday',)}
CONTENT_ACTIONS = {'safety': ('exclude', 'restrict_visuals', 'keep'),
                   'religion_superstition': ('exclude', 'keep'), 'holiday': ('exclude', 'keep')}
STORY_STATUS = ('coherent', 'bridged', 'too_dependent')
_THEME_STOP = {'the', 'and', 'with', 'from', 'that', 'this', 'into', 'onto', 'their', 'there', 'about', 'over',
               'under', 'his', 'her', 'its', 'for', 'was', 'were', 'are', 'any', 'all', 'one', 'who', 'what'}


def content_review_path(rd, ref):
    return rd / '20-analysis' / 'content' / f'{str(ref).strip().upper()}.json'


def shot_sheets_dir(rd, ref):
    return rd / '20-analysis' / 'content' / f'{str(ref).strip().upper()}-shots'


SHOTS_PER_SHEET = 36


def make_shot_sheets(rd, ref):
    """One frame of every shot (the sample nearest its middle), 36 to a sheet, each tile labelled with its frame's
    time: the content review's picture coverage. The watch sheets show a frame every 5 s, so a shot of a second or
    two between two tiles is seen only here. Shots come from the av-profile when it was made from these frames,
    else they are measured from the frames (no audio work)."""
    av = _av()
    fi = read_json(rd / '10-media' / ref / 'frame-index.json')
    rows = [(f['t_s'] if f.get('t_s') is not None else f['approx_s'], rd / '10-media' / ref / 'sampled-frames' / f['file'])
            for f in fi.get('frames') or []]
    if not rows:
        error('No sampled frames for this reference: run prepare first.', ref)
    prof = read_json(ref_av_path(rd, ref))
    sig = prof.get('signature') or {}
    if prof.get('shots') and sig.get('frames') == len(rows) and sig.get('sampler', LEGACY_SAMPLER) == (fi.get('sampler') or LEGACY_SAMPLER):
        shots = prof['shots']
    else:
        shots = av.segment_shots(av.frame_features(rows))[0]
    out = shot_sheets_dir(rd, ref)
    picked, sheets = render_shot_sheets(av, rows, shots, out, ref)
    write_json(out / 'index.json', {'reference_id': ref, 'shots': picked, 'sheets': sheets, 'frames': len(rows),
                                    'sampler': fi.get('sampler') or LEGACY_SAMPLER, 'made_at': now()})
    return {'shots': len(picked), 'sheets': sheets}


def render_shot_sheets(av, rows, shots, out, label):
    """rows [(t_s, frame path)], shots from segment_shots: the sample nearest each shot's middle, 36 to a sheet."""
    times = [t for t, _ in rows]
    picked = []
    for k, s in enumerate(shots, 1):
        mid = (float(s['start_s']) + float(s['end_s'])) / 2
        j = min(range(len(times)), key=lambda q: abs(times[q] - mid))
        picked.append({'n': k, 'start_s': s['start_s'], 'end_s': s['end_s'], 'frame_s': times[j], 'file': Path(rows[j][1]).name,
                       '_path': rows[j][1]})
    out.mkdir(parents=True, exist_ok=True)
    for old in out.glob('sheet-*.jpg'):
        old.unlink()
    sheets = []
    for i in range(0, len(picked), SHOTS_PER_SHEET):
        part = picked[i:i + SHOTS_PER_SHEET]
        sheets.append(av.window_sheet([(x['frame_s'], x['_path']) for x in part],
                                      out / f'sheet-{i // SHOTS_PER_SHEET + 1:03d}.jpg',
                                      f'{label}  shots {part[0]["n"]}-{part[-1]["n"]} of {len(picked)}: one frame of every shot'))
    for x in picked:
        x.pop('_path')
    return picked, sheets


def picture_looks_path(rd, video):
    return rd / '60-visuals' / f'video-{int(video):02d}' / 'content-looks.json'


# A look's own issue categories beyond the content reviews': a person the picture's prompt does not ask for.
LOOK_CATEGORIES = ('excluded_theme', 'people_not_asked_for')
NOBODY_SEEN = re.compile(r'(?i)\s*(none|no one|nobody|no people|no person|no-one)\b[\s\S]*')


def still_provenance_by_file(rd, video):
    """The stills' provenance records of a video, by file key (_pkey), as record_media keeps them."""
    return read_json(artifact_path(rd, int(video), 'stills')).get('images') or {}


def closer_looks(rd, ref, a=None, b=None):
    """The closer looks (inspect-window) taken at a reference, overlapping [a, b] when given."""
    out = []
    for idx in sorted((rd / '20-analysis' / 'inspect' / str(ref).upper()).glob('*/index.json')):
        d = read_json(idx)
        lo, hi = d.get('from_s'), d.get('to_s')
        if lo is None or hi is None or not d.get('frames'):
            continue    # a look that took no frames (a window outside the video) was not a look
        if a is None or (lo <= b and hi >= a):
            out.append({'from_s': lo, 'to_s': hi, 'rate': d.get('rate'), 'frames': len(d.get('frames') or []),
                        'why': d.get('why'), 'frames_removed': bool(d.get('frames_removed_at'))})
    return out


def content_review_issues(rd, ref, doc, row):
    """Shape and process of one reference's content review: (issues, segments read as numbers)."""
    iss, segs = [], []
    if not isinstance(doc, dict):
        return ['content_review_must_be_a_json_object'], segs
    media = rd / '10-media' / ref
    if not (media / 'frame-index.json').is_file():
        iss.append('reference_not_prepared_run_prepare_first')
    elif read_json(shot_sheets_dir(rd, ref) / 'index.json').get('frames') != len(read_json(media / 'frame-index.json').get('frames') or []):
        # the review sees every shot: one frame of each (the watch sheets' frame every 5 s can step over a short shot)
        iss.append('shot_sheets_missing_run_content-review_--shot-sheets_and_open_every_one')
    if row.get('has_audio') and read_json(media / 'transcript.json').get('status') != 'transcribed':
        iss.append('reference_words_not_transcribed_run_prepare_with_whisper_first')
    if n_words(doc.get('looked_at')) < 4:
        iss.append('looked_at_must_say_what_was_watched_and_heard')
    dur = float(row.get('duration_s') or 0)
    raw = doc.get('segments')
    if not isinstance(raw, list):
        iss.append('segments_must_be_a_list_(empty_when_nothing_was_found)')
        raw = []
    ids = set()
    for k, s in enumerate(raw, 1):
        if not isinstance(s, dict):
            iss.append(f'segment_{k}_must_be_an_object')
            continue
        sid = str(s.get('id') or '').strip()
        if not re.fullmatch(r'[A-Za-z0-9_]+', sid) or sid in ids:
            iss.append(f'segment_{k}_needs_a_unique_id_(letters_digits)')
            sid = sid or f'#{k}'
        ids.add(sid)
        a, b_ = parse_clock(s.get('from')), parse_clock(s.get('to'))
        if a is None or b_ is None or b_ <= a or a < 0 or (dur and b_ > dur + 1):
            iss.append(f'segment_{sid}_from_to_must_be_times_inside_the_video')
            a = b_ = None
        kind = str(s.get('kind') or '')
        cat = str(s.get('category') or '')
        action = str(s.get('action') or '')
        if kind not in CONTENT_KINDS:
            iss.append(f'segment_{sid}_kind_must_be:' + '/'.join(CONTENT_KINDS))
        elif kind == 'safety':
            if cat in ('religious', 'superstition', 'holiday'):
                iss.append(f'segment_{sid}_religious_superstitious_or_holiday_material_is_not_a_safety_category:'
                           'record it as kind religion_superstition or holiday')
            elif cat == 'minors':
                iss.append(f'segment_{sid}_minors_is_not_a_category:sexual_content_involving_a_minor_is_'
                           'sexual_content_minors;_a_child_in_an_ordinary_scene_is_not_harm_by_itself_(our_own_pictures_'
                           'show_adults,_02)')
            elif cat not in SAFETY_CATEGORIES:
                iss.append(f'segment_{sid}_safety_category_must_be:' + '/'.join(SAFETY_CATEGORIES))
            sev = str(s.get('severity') or '')
            if sev not in ('low', 'medium', 'high'):
                iss.append(f'segment_{sid}_safety_needs_a_severity:low/medium/high')
            if cat == 'sexual_content_minors' and action != 'exclude':
                iss.append(f'segment_{sid}_sexual_content_minors_is_always_excluded')
            if sev == 'high' and action == 'keep':
                iss.append(f'segment_{sid}_high_severity_cannot_be_kept_as_it_is')
            # proportionate: what is low in severity is told within 02 (restricted) or kept, never cut out
            if sev == 'low' and action == 'exclude' and cat != 'sexual_content_minors':
                iss.append(f'segment_{sid}_low_severity_is_restricted_or_kept_never_excluded')
        else:
            if cat not in CREATIVE_CATEGORIES[kind]:
                iss.append(f'segment_{sid}_category_must_be:' + '/'.join(CREATIVE_CATEGORIES[kind]))
            if s.get('severity') not in (None, ''):
                iss.append(f'segment_{sid}_severity_is_for_safety_only:{kind}_is_a_creative_exclusion_not_harm')
        if kind in CONTENT_ACTIONS and action not in CONTENT_ACTIONS[kind]:
            iss.append(f'segment_{sid}_action_must_be:' + '/'.join(CONTENT_ACTIONS[kind]))
        if n_words(s.get('what')) < 4:
            iss.append(f'segment_{sid}_what_must_say_what_it_is_(neutrally,_no_graphic_detail)')
        if n_words(s.get('role')) < 3:
            iss.append(f'segment_{sid}_role_must_say_what_it_does_in_the_story')
        if n_words(s.get('evidence')) < 3:
            iss.append(f'segment_{sid}_evidence_must_say_what_shows_it')
        elif not re.search(r'\d{1,2}:\d{2}', str(s.get('evidence'))):
            iss.append(f'segment_{sid}_evidence_must_cite_the_times_it_was_seen_or_heard_(mm:ss)')
        if str(s.get('confidence') or '') not in ('sure', 'unsure'):
            iss.append(f'segment_{sid}_confidence_must_be_sure_or_unsure')
        if action == 'exclude' and n_words(s.get('why')) < 6:
            # the lighter actions were considered: why the moment cannot be told with what is shown restricted
            # (safety), or why it is a story device and not a plain fact (the creative exclusions)
            iss.append(f'segment_{sid}_exclude_must_say_why_' + ('restricting_what_is_shown_is_not_enough' if kind == 'safety'
                                                                 else 'it_is_a_story_device_not_a_plain_fact'))
        elif action in ('keep', 'restrict_visuals') and n_words(s.get('why')) < 4:
            iss.append(f'segment_{sid}_{action}_must_say_why')
        avoid = [str(x).strip() for x in s.get('avoid') or [] if str(x).strip()]
        if action == 'exclude' and not avoid:
            iss.append(f'segment_{sid}_exclude_must_name_what_to_avoid_bringing_back')
        deps = []
        for j, d in enumerate(s.get('depends') or [], 1):
            da, db = parse_clock((d or {}).get('from')), parse_clock((d or {}).get('to'))
            if da is None or db is None or db <= da or (dur and db > dur + 1):
                iss.append(f'segment_{sid}_depends_{j}_from_to_must_be_times_inside_the_video')
            elif n_words((d or {}).get('why')) < 3:
                iss.append(f'segment_{sid}_depends_{j}_must_say_what_it_depends_on')
            else:
                deps.append((da, db))
        looks = closer_looks(rd, ref, a, b_) if a is not None else []
        if str(s.get('confidence')) == 'unsure' and a is not None and not looks:
            # whatever is decided (cut, restricted or kept), a doubt is settled on what is there, not on a cue
            iss.append(f'segment_{sid}_unsure_needs_a_closer_look_first_(inspect-window)')
        segs.append({'id': sid, 'from_s': a, 'to_s': b_, 'kind': kind, 'category': cat, 'action': action,
                     'depends_s': deps, 'avoid': avoid, 'closer_looks': looks})
    if any(x['action'] == 'exclude' for x in segs):
        story = doc.get('story_without_exclusions') or {}
        if not isinstance(story, dict) or story.get('status') not in STORY_STATUS or n_words(story.get('note')) < 6:
            iss.append('story_without_exclusions_needs_status_(' + '/'.join(STORY_STATUS) + ')_and_a_note')
    if n_words(doc.get('usable')) < 3:
        iss.append('usable_must_say_what_stays_useful_(or_that_nothing_does)')
    return iss, segs


def content_archive_dir(rd, ref, rev):
    return rd / '20-analysis' / 'content-archive' / f'{str(ref).upper()}-r{int(rev)}'


def archived_revision(rd, ref):
    revs = [int(m.group(1)) for p in (rd / '20-analysis' / 'content-archive').glob(f'{str(ref).upper()}-r*')
            if (m := re.fullmatch(rf'{str(ref).upper()}-r(\d+)', p.name))]
    return max(revs, default=0)


def archive_content_review(rd, ref):
    """Move a reference's review, its drafts in the content folder and its closer looks (frames and records) out of
    every path the tools and the next reviewer read, into 20-analysis/content-archive/V###-r<revision>/. The source
    evidence stays: frames, transcript, watch sheets, shot sheets, measurements. Nothing is deleted."""
    ref = str(ref).upper()
    cur = read_json(content_review_path(rd, ref))
    rev = int(cur.get('revision') or 0) or archived_revision(rd, ref) + 1
    dest = content_archive_dir(rd, ref, rev)
    while dest.exists():
        rev += 1
        dest = content_archive_dir(rd, ref, rev)
    moved = []
    for src in [content_review_path(rd, ref)] + sorted((rd / '20-analysis' / 'content').glob(f'{ref}-draft*')):
        if src.is_file():
            dest.mkdir(parents=True, exist_ok=True)
            shutil.move(str(src), str(dest / src.name))
            moved.append(src.name)
    looks = rd / '20-analysis' / 'inspect' / ref
    if looks.is_dir() and any(looks.iterdir()):
        dest.mkdir(parents=True, exist_ok=True)
        shutil.move(str(looks), str(dest / 'inspect'))
        moved.append('inspect/')
    return {'archived_to': str(dest) if moved else None, 'moved': moved, 'revision': rev}


def content_exclusions(rd, ref):
    """[(from_s, to_s, segment id, kind, action)] of a reference's reviewed content: an excluded segment with the
    moments that depend on it, and a segment whose visuals are restricted."""
    doc = read_json(content_review_path(rd, ref))
    out = []
    for s in doc.get('segments') or []:
        if s.get('action') not in ('exclude', 'restrict_visuals'):
            continue
        a, b_ = parse_clock(s.get('from')), parse_clock(s.get('to'))
        if a is None or b_ is None:
            continue
        out.append((a, b_, str(s.get('id')), str(s.get('kind')), str(s.get('action'))))
        if s.get('action') == 'exclude':
            for d in s.get('depends') or []:
                da, db = parse_clock(d.get('from')), parse_clock(d.get('to'))
                if da is not None and db is not None:
                    out.append((da, db, str(s.get('id')), str(s.get('kind')), 'exclude'))
    return out


def excluded_themes(rd, video):
    """What a video must not bring back: the excluded segments of the references its direction cites, and what a
    restricted segment's `avoid` says must never be shown (its subject may still be told)."""
    d = read_json(video_dir(rd, video) / 'direction.json')
    ev = d.get('evidence') if isinstance(d.get('evidence'), dict) else {}
    out = []
    for ref in dict.fromkeys(str(x).strip().upper() for x in ev.get('references') or []):
        for s in read_json(content_review_path(rd, ref)).get('segments') or []:
            avoid = [str(x) for x in s.get('avoid') or [] if str(x).strip()]
            if s.get('action') == 'exclude' or (s.get('action') == 'restrict_visuals' and avoid):
                out.append({'theme': f'{ref}/{s.get("id")}', 'kind': s.get('kind'), 'what': s.get('what'),
                            'avoid': avoid, 'label': 'excluded_theme' if s.get('action') == 'exclude' else 'restricted_theme'})
    return out


def _theme_tokens(phrase):
    return [w for w in re.findall(r"[a-z0-9']+", str(phrase).lower()) if len(w) > 2 and w not in _THEME_STOP]


def theme_hits(text, themes):
    """[(theme, phrase)]: an avoid phrase whose every content word is in the text (any order, a plural too). A net
    for plain re-use only: a disguised version in other words is the editorial stage's to catch, and every picture is
    looked at against the list (content-review --pictures); blind readers are not told what was cut (2026-11-24)."""
    words = set(re.findall(r"[a-z0-9']+", strip_tags(str(text or '')).lower()))
    out = []
    for th in themes:
        for ph in th.get('avoid') or []:
            toks = _theme_tokens(ph)
            if toks and all(w in words or w + 's' in words or w + 'es' in words or
                            (w.endswith('s') and w[:-1] in words) for w in toks):
                out.append((f"{th.get('label') or 'excluded_theme'}:{th['theme']}", ph))
    return out


def prompt_flags(text, themes=()):
    """The content flags of a picture prompt: 02's words (swearing aside), an excluded theme brought back, and a child
    in the picture (every person in a picture is an adult: never answered by a note)."""
    plain = strip_tags(str(text or ''))
    kinds = [kind for kind, rx in CONTENT_FLAGS if kind != 'swearing' and rx.search(plain)]
    kinds += [label for label, _ in theme_hits(plain, themes)]
    if _affirmed(CAPTION_MINORS, plain):
        kinds.append('minor_in_the_picture')
    return list(dict.fromkeys(kinds))


def content_context_for(doc, where, label):
    """A recorded reason a mention of an excluded theme is not that material: doc's content_context entries
    [{where, theme, context}] for this place ("treatment T1", "beat B03") and theme, six words or more."""
    for x in (doc or {}).get('content_context') or []:
        if not isinstance(x, dict):
            continue
        if str(x.get('where') or '').strip().lower() == where.lower() and str(x.get('theme') or '').strip() in \
                (label, label.split(':', 1)[-1]) and n_words(x.get('context')) >= MIN_FIELD_WORDS:
            return x
    return None


def prompt_flag_issues(prefix, kinds, note):
    """Issues for one picture prompt's flags. What a cited reference's content review rules out (excluded, or never
    shown) is rewritten out of the prompt: a note cannot answer it. 02's words can be plain (a blood-orange sky): a
    note of six words or more saying why it is not that content answers them, or the prompt is rewritten."""
    ruled_out = [k for k in kinds if k.startswith(('excluded_theme:', 'restricted_theme:'))]
    words = [k for k in kinds if k not in ruled_out and k != 'minor_in_the_picture']
    out = []
    if ruled_out:
        out.append(f'{prefix}_shows_what_a_content_review_rules_out_rewrite_it:' + '+'.join(ruled_out))
    if 'minor_in_the_picture' in kinds:
        out.append(f'{prefix}_shows_a_child:every_person_in_a_picture_is_an_adult_rewrite_it')
    if words and n_words(note) < 6:
        out.append(f'{prefix}_content_flag_unanswered:' + '+'.join(words))
    return out


def content_signals(rd, ref, row):
    """Where to look closer (gathered, never judged): stretches whose words touch 02's subjects, and the picture
    stretches the samples cannot settle (the av-profile's inspect_candidates)."""
    tj = read_json(rd / '10-media' / ref / 'transcript.json')
    hits = []
    for s in tj.get('segments') or []:
        for kind, rx in CONTENT_FLAGS:
            if kind == 'swearing':
                continue
            found = sorted({h.lower() for h in rx.findall(s.get('text') or '')})
            if found:
                hits.append({'from': _mmss(s.get('start_s')), 'to': _mmss(s.get('end_s')), 'kind': kind,
                             'words': found, 'said': str(s.get('text') or '')[:160]})
    prof = read_json(ref_av_path(rd, ref))
    fi = read_json(rd / '10-media' / ref / 'frame-index.json')
    return {'reference': ref, 'duration_s': row.get('duration_s'),
            'frames': {'count': len(fi.get('frames') or []), 'fps': fi.get('fps'), 'sampler': fi.get('sampler') or LEGACY_SAMPLER},
            'transcribed': tj.get('status') == 'transcribed', 'word_hits': hits[:120],
            'picture_candidates': prof.get('inspect_candidates') if prof else None,
            # which stretches were looked at closer, not why: a fresh or second review is not steered by the first
            'closer_looks_taken': [{k: x[k] for k in ('from_s', 'to_s', 'rate', 'frames')} for x in closer_looks(rd, ref)],
            'shot_sheets': (read_json(shot_sheets_dir(rd, ref) / 'index.json').get('sheets')
                            or 'not made yet: content-review --shot-sheets (one frame of every shot)'),
            'note': 'Places to look, not verdicts: a word can be plain fact, and something can be shown without a word '
                    'said. The review is your judgement of the whole video in context.'
                    + ('' if prof else ' Run av-profile for the picture candidates.')}


def cmd_content_review(args):
    """The content record: a reference's review (--ref with --file; --signals shows where to look first), the look at
    every picture a video's edit shows (--video with --pictures --file), or the run's state (--status)."""
    rd, st = run_folder(args)
    inv = read_json(rd / '00-inventory/references.json')
    rows = {x['id']: x for x in inv.get('items') or [] if x.get('kind') == 'video' and not x.get('duplicate_of')}
    if args.status:
        refs = {}
        for ref in rows:
            d = read_json(content_review_path(rd, ref))
            if not d:
                refs[ref] = 'not reviewed'
                continue
            segs = d.get('segments') or []
            refs[ref] = {'segments': len(segs),
                         **{k: sum(1 for s in segs if s.get('kind') == k) for k in CONTENT_KINDS},
                         'excluded': sum(1 for s in segs if s.get('action') == 'exclude'),
                         'restricted': sum(1 for s in segs if s.get('action') == 'restrict_visuals'),
                         'unsure': sum(1 for s in segs if s.get('confidence') == 'unsure'),
                         'story': (d.get('story_without_exclusions') or {}).get('status')}
        emit({'ok': True, 'reviewed': sum(1 for v in refs.values() if v != 'not reviewed'), 'references': len(rows),
              'by_reference': refs})
        return
    if args.video and args.pictures:
        if not args.file:
            error('Give the looks file: --file looks.json ({"looks": [{"file", "result": "clean"|"issue", "note"}]})')
        given = read_json(Path(args.file).expanduser().resolve(), required=True)
        looks = given.get('looks')
        if not isinstance(looks, list) or not looks:
            error('The looks file needs a "looks" list, one entry per picture looked at')
        ruled_out = excluded_themes(rd, args.video)
        if ruled_out and given.get('never_show_checked') is not True:
            error('Check every picture against what the cited references\' content reviews rule out, then confirm '
                  'with "never_show_checked": true in the looks file; a picture showing any of it is an issue.',
                  [f"{th['theme']}: {th['what']} (never: {', '.join(th['avoid'])})" for th in ruled_out])
        path = picture_looks_path(rd, args.video)
        data = read_json(path) or {'video': int(args.video), 'looks': {}}
        problems, saved = [], 0
        prov_ = still_provenance_by_file(rd, args.video)
        for k, lk in enumerate(looks, 1):
            f = _run_file(rd, (lk or {}).get('file'))
            if not f.is_file():
                problems.append(f'look_{k}_file_not_found:{f}')
                continue
            res = str(lk.get('result') or '')
            if res not in ('clean', 'issue'):
                problems.append(f'look_{k}_result_must_be_clean_or_issue')
            if n_words(lk.get('note')) < 3:
                problems.append(f'look_{k}_note_must_say_what_the_picture_shows')
            if res == 'issue' and str(lk.get('category') or '') not in SAFETY_CATEGORIES + CONTENT_KINDS[1:] + LOOK_CATEGORIES:
                problems.append(f'look_{k}_an_issue_needs_its_category')
            pq = (prov_.get(_pkey(f)) or {}).get('people_question')
            ppl = str(lk.get('people') or '').strip()
            if pq and not ppl:
                problems.append(f'look_{k}_must_say_whether_anyone_appears_(people:"none"_or_who):its_prompt_'
                                + ('rules_people_out' if pq.get('prompt_excludes_people') else 'asks_for_no_one')
                                + (':look_at:' + ','.join(pq.get('hints') or []) if pq.get('hints') else ''))
            elif pq and not NOBODY_SEEN.fullmatch(ppl) and (res != 'issue' or lk.get('category') != 'people_not_asked_for'):
                problems.append(f'look_{k}_someone_appears_that_its_prompt_does_not_ask_for:result_issue,_category_'
                                'people_not_asked_for_(the_still_is_remade,_never_patched)')
            if not problems:
                data['looks'][_pkey(f)] = {'file': str(f), 'sha256': file_sha256(f), 'result': res,
                                           'note': lk.get('note'), 'category': lk.get('category'), 'looked_at': now(),
                                           'never_show_checked': bool(ruled_out),
                                           'themes_sha256': canonical_sha(ruled_out),
                                           **({'people': ppl, 'people_question': pq} if pq else {})}
                saved += 1
        if problems:
            error('The looks file does not follow the format; nothing was recorded.', problems)
        write_json(path, data)
        emit({'ok': True, 'recorded': saved, 'file': str(path),
              'issues_open': sum(1 for x in data['looks'].values() if x.get('result') == 'issue')})
        return
    if not args.ref:
        error('Name a reference (--ref V###), or --video N --pictures, or --status')
    ref = args.ref.strip().upper()
    row = rows.get(ref)
    if not row:
        error('No such reference video in this run', ref)
    if args.signals:
        emit({'ok': True, **content_signals(rd, ref, row)})
        return
    if args.archive:
        moved = archive_content_review(rd, ref)
        emit({'ok': True, 'reference': ref, **moved,
              'note': 'A blind review now starts from the source evidence only (frames, transcript, watch and shot '
                      'sheets, measurements). Its brief never names the archive.'})
        return
    if args.shot_sheets:
        made = make_shot_sheets(rd, ref)
        emit({'ok': True, 'reference': ref, **made,
              'note': 'Open every sheet: each shot of the video once, at its frame\'s time (the watch sheets show a '
                      'frame every 5 s and can step over a short shot).'})
        return
    if not args.file:
        error('Give the review: --file review.json (see 07 for its fields), or --signals for where to look first')
    doc = read_json(Path(args.file).expanduser().resolve(), required=True)
    issues, segs = content_review_issues(rd, ref, doc, row)
    if issues:
        error('The content review is not complete; nothing was saved.', issues)
    target = content_review_path(rd, ref)
    old = read_json(target)
    fi = read_json(rd / '10-media' / ref / 'frame-index.json')
    saved = {**doc, 'reference_id': ref, 'revision': max(int(old.get('revision') or 0), archived_revision(rd, ref)) + 1,
             'made_at': now(),
             'frames_seen': {'fps': fi.get('fps'), 'sampler': fi.get('sampler') or LEGACY_SAMPLER,
                             'count': len(fi.get('frames') or [])},
             'closer_looks': closer_looks(rd, ref),
             'shot_sheets': len(read_json(shot_sheets_dir(rd, ref) / 'index.json').get('sheets') or [])}
    saved['review_sha256'] = canonical_sha({k: v for k, v in saved.items() if k not in ('made_at', 'review_sha256')})
    write_json(target, saved)
    emit({'ok': True, 'file': str(target), 'revision': saved['revision'], 'segments': len(segs),
          'excluded': sum(1 for s in segs if s['action'] == 'exclude'),
          'restricted': sum(1 for s in segs if s['action'] == 'restrict_visuals'),
          'kinds': {k: sum(1 for s in segs if s['kind'] == k) for k in CONTENT_KINDS}})


def script_hash(lines):
    return hashlib.sha256('\n'.join(str(r.get('text') or '').strip() for r in lines).encode('utf-8')).hexdigest()


# ---------------------------------------------------------------- what the voice is sent, and what it never is
# A script holds four different things, each in its own place:
#   1. the canonical narration: a line's `text`, exactly the words the viewer hears (captions come from it);
#   2. delivery tags: [bracketed] directions inline in `text`, sent to ElevenLabs, never spoken;
#   3. pronunciation: 40-plans/video-NN/pronunciation.json, applied only to what is sent, never to `text`;
#   4. editorial notes: a line's `note` field, never sent.
# Anything else that reaches the voice as markup (SSML, which Eleven v4 does not support; {braces}; *asterisks*; a stage
# direction in parentheses; a note in brackets) is read aloud or ignored, so plan-check refuses it.
SSML_RX = re.compile(r'<\s*/?\s*[A-Za-z][^<>]*>')
CURLY_RX = re.compile(r'\{[^{}]*\}')
ASTERISK_RX = re.compile(r'\*{1,2}[^*\s][^*]*\*{1,2}')
PAREN_RX = re.compile(r'\(([^()]{1,60})\)')
NOTE_TAG_RX = re.compile(r'^\s*(?:\d+|notes?|todo|tk|fixme|sources?|refs?|cite|citation|check|fact[- ]?check|'
                         r'placeholder|xx+|editor)\b', re.I)
IPA_SYMBOLS = set('ˈˌːəɪʊʃʒθðŋɑɔæɛʌɒɜɐɚɝɨʉɯɲɳɴɸβçʝɣχʁħʕɦɬɮɹɻʎʟɾɽʀʙʋɥʍʔ')
IPA_RX = re.compile(r'/[^/\s][^/]*/')
_CONTRAST = None


def contrast_axes():
    """The catalogue's opposite poles of delivery (volume, energy, tempo): asked for together on the same words, they
    contradict each other (ElevenLabs: contrasting tags on the same words blur the performance)."""
    global _CONTRAST
    if _CONTRAST is None:
        _CONTRAST = read_json(TAGS_FILE).get('contrast_axes') or {}
    return _CONTRAST


def tag_qualities(inner):
    """The qualities one tag asks for: '[tense, cautious]' -> ['tense', 'cautious']."""
    return [q.strip().lower() for q in str(inner).split(',') if q.strip()]


CUE_PAUSE_TOLERANCE = (0.3, 0.25)
CUE_MOVES = {'volume': ('speech_level_db', 1.0, 'dB'), 'tempo': ('speech_rate_wpm', 0.05, 'share'),
             'energy': ('pitch_range_st', 1.0, 'st')}


def cue_poles(inner):
    """The delivery axes a cue asks to move, and which way: '[quietly, slowly]' -> {'volume': 'low', 'tempo': 'slow'}."""
    text = ' ' + ' '.join(tag_qualities(inner)) + ' '
    words = set(re.findall(r"[a-z']+", text))
    out = {}
    for axis, poles in contrast_axes().items():
        hit = [pole for pole, terms in poles.items()
               if any((' ' + t + ' ' in text) if ' ' in t else (t in words) for t in terms)]
        if len(hit) == 1:
            out[axis] = hit[0]
    return out


def pause_cue_outcome(planned_s, measured_s):
    """A performed pause is judged on its length, never on where it falls in time: achieved within max(0.3 s, 25 %) of
    the whole silence planned. The model's timing can't be steered to the millisecond; close is a success."""
    if planned_s is None or measured_s is None:
        return None
    tol = max(CUE_PAUSE_TOLERANCE[0], CUE_PAUSE_TOLERANCE[1] * float(planned_s))
    d = float(measured_s) - float(planned_s)
    return {'planned_s': round(float(planned_s), 2), 'measured_s': round(float(measured_s), 2),
            'tolerance_s': round(tol, 2), 'outcome': 'achieved' if abs(d) <= tol else 'short' if d < 0 else 'long'}


def delivery_cue_outcome(inner, line_stats, usual):
    """Whether a delivery cue moved its line the way it asked, against this take's usual line: volume by the speech
    level, tempo by the speaking rate, energy by the pitch range. Under the step it is no clear change, the wrong way it
    is opposite. A cue on none of these axes ([curious], [deadpan] aside) is listened to, not judged here."""
    poles = cue_poles(inner)
    if not poles:
        return {'outcome': 'not_measured', 'note': 'a cue on no measured axis (volume, energy, tempo): listen'}
    rows = []
    for axis, pole in poles.items():
        key, step, kind = CUE_MOVES[axis]
        v, u = (line_stats or {}).get(key), (usual or {}).get(key)
        if v is None or u is None:
            rows.append({'axis': axis, 'asked': pole, 'outcome': 'not_measured', 'note': 'too short to measure'})
            continue
        need = step * u if kind == 'share' else step
        moved = (u - v) if pole in ('low', 'slow') else (v - u)
        rows.append({'axis': axis, 'asked': pole, 'measure': key, 'line': v, 'usual': round(u, 2),
                     'change': round(v - u, 2), 'step': round(need, 2),
                     'outcome': 'as_asked' if moved >= need else 'opposite' if moved <= -need else 'no_clear_change'})
    outs = {r['outcome'] for r in rows}
    overall = ('as_asked' if outs == {'as_asked'} else 'opposite' if 'opposite' in outs else
               'not_measured' if outs == {'not_measured'} else 'no_clear_change' if 'no_clear_change' in outs
               else 'partly')
    return {'outcome': overall, 'axes': rows}


def contradictions(qualities):
    """The delivery axes on which these qualities ask for both poles at once ([whispering, shouting])."""
    text = ' ' + ' '.join(qualities) + ' '
    words = set(re.findall(r"[a-z']+", text))
    out = []
    for axis, poles in contrast_axes().items():
        hit = [pole for pole, terms in poles.items()
               if any((' ' + t + ' ' in text) if ' ' in t else (t in words) for t in terms)]
        if len(hit) > 1:
            out.append(axis)
    return out


def script_markup(lines):
    """Markup the voice can't take and delivery directions that fight each other (issues); tags stacked on the same
    words (a warning: several qualities go in one bracket, [a, b])."""
    issues, warnings = [], []
    for i, row in enumerate(lines):
        lid = str(row.get('id') or f'L{i+1:03d}')
        text = str(row.get('text') or '')
        if SSML_RX.search(text):
            issues.append(f'ssml_markup_not_supported_by_eleven_v4:{lid}')
        if CURLY_RX.search(text):
            issues.append(f'curly_brace_markup:{lid}')
        if ASTERISK_RX.search(text):
            issues.append(f'asterisk_markup:{lid}')
        for m in PAREN_RX.finditer(text):
            inner = ' '.join(m.group(1).lower().split())
            if '[' + inner + ']' in tag_catalogue() or is_pause_tag(inner) or inner in ('beat', 'silence', 'breath'):
                issues.append(f'stage_direction_in_parentheses:{lid}:({inner})')
        if any(set(x) & IPA_SYMBOLS for x in IPA_RX.findall(strip_tags(text))):
            issues.append(f'pronunciation_markup_in_script_text:{lid}')
        tags = list(TAG_RE.finditer(text))
        for m in tags:
            if NOTE_TAG_RX.match(m.group(1)):
                issues.append(f'editorial_note_in_spoken_text:{lid}:[{m.group(1).strip()}]')
        groups = []
        for k, m in enumerate(tags):
            if groups and not text[tags[k - 1].end():m.start()].strip():
                groups[-1].append(m)
            else:
                groups.append([m])
        for g in groups:
            shown = ''.join(m.group(0) for m in g)
            for axis in contradictions([q for m in g for q in tag_qualities(m.group(1))]):
                issues.append(f'contradictory_delivery:{lid}:{axis}:{shown}')
            if len(g) > 1:
                warnings.append(f'{lid}: tags stacked on the same words ({shown}); several qualities go in one bracket')
    return issues, warnings


def delivery_review_lines(review_text):
    """The line ids named under a "Delivery and tags" heading of editorial-review.md (where each kept tag says why)."""
    m = re.search(r'^#+[^\n]*delivery and tags[^\n]*\n(.*?)(?=^#|\Z)', review_text or '', flags=re.I | re.M | re.S)
    return set(re.findall(r'\bL\d{3,4}\b', m.group(1))) if m else set()


PRONUNCIATION_HOW = ('ipa', 'respell')
PRONUNCIATION_CONFIDENCE = ('confirmed', 'likely', 'uncertain')


def pronunciation_path(rd, video):
    return video_dir(rd, video) / 'pronunciation.json'


def term_rx(term):
    return re.compile(r'(?<![\w-])' + re.escape(term) + r'(?![\w-])')


def pronunciation_facts(rd, video, lines, data=None):
    """The episode's pronunciation list (40-plans/video-NN/pronunciation.json, or `data` given directly, as a trial
    plan carries its own): the names and terms this voice may say wrong, each in a form Eleven v4 documents (IPA
    between slashes, or a respelling), where that pronunciation comes from and how sure it is. Only what is sent
    changes: the script and the captions keep the canonical spelling. An uncertain entry is flagged for listening,
    never treated as settled."""
    p = pronunciation_path(rd, video)
    out = {'file': str(p) if data is None else '(given)', 'issues': [], 'warnings': [], 'terms': [], 'uses': {}}
    if data is None:
        if not p.is_file():
            return out
        d = read_json(p)
        if not d:
            out['issues'].append('pronunciation_file_unreadable')
            return out
    else:
        d = data if isinstance(data, dict) else {}
    seen = set()
    for k, t in enumerate(d.get('terms') or [], 1):
        t = t if isinstance(t, dict) else {}
        term, say = str(t.get('term') or '').strip(), str(t.get('say') or '').strip()
        how, conf = str(t.get('how') or '').strip().lower(), str(t.get('confidence') or '').strip().lower()
        name = term or f'entry_{k}'
        if not term or not say:
            out['issues'].append(f'pronunciation_{name}_needs_term_and_say')
            continue
        if term in seen:
            out['issues'].append(f'pronunciation_{name}_listed_twice')
        seen.add(term)
        if how not in PRONUNCIATION_HOW:
            out['issues'].append(f'pronunciation_{name}_how_must_be:' + '/'.join(PRONUNCIATION_HOW))
        elif how == 'ipa' and not IPA_RX.fullmatch(say):
            out['issues'].append(f'pronunciation_{name}_ipa_goes_between_slashes')
        elif how == 'respell' and re.search(r'[/\[\]<>{}"]', say):
            out['issues'].append(f'pronunciation_{name}_respelling_is_plain_letters')
        if conf not in PRONUNCIATION_CONFIDENCE:
            out['issues'].append(f'pronunciation_{name}_confidence_must_be:' + '/'.join(PRONUNCIATION_CONFIDENCE))
        elif conf != 'uncertain' and n_words(t.get('source')) < 3:
            out['issues'].append(f'pronunciation_{name}_needs_its_source')
        elif conf == 'uncertain':
            out['warnings'].append(f'the pronunciation of "{term}" is uncertain ({say}): hear it on a short probe or '
                                   'trial before the parts that say it are recorded, and let the user listen')
        rx = term_rx(term)
        uses = [str(r.get('id') or f'L{i + 1:03d}') for i, r in enumerate(lines)
                if rx.search(strip_tags(r.get('text') or ''))]
        if not uses:
            out['warnings'].append(f'pronunciation entry "{term}" is not in the script')
        out['uses'][term] = uses
        out['terms'].append({'term': term, 'say': say, 'how': how, 'confidence': conf, 'rx': rx,
                             'source': str(t.get('source') or '').strip() or None})
    return out


def tts_text(text, terms):
    """What ElevenLabs is sent for one line: its canonical text with its tags in place, every listed term in the
    form v4 pronounces: IPA between slashes inside double quotes (as ElevenLabs' own examples write it), or a
    respelling."""
    out = str(text).strip()
    for t in terms or []:
        if t.get('how') in PRONUNCIATION_HOW:
            form = f'"{t["say"]}"' if t['how'] == 'ipa' else t['say']
            out = t['rx'].sub(lambda m, f=form: f, out)
    return out


# ---------------------------------------------------------------- creative direction, reviews, writing signals
# The code enforces the PROCESS: what has to exist, in what order, for which version, and that every reviewer
# finding is answered. It never judges the work: whether a treatment, a script or a cut is good is decided by the
# agents and the independent reviewers (10-creative-direction.md, 06). A passed gate means the process happened.
APPROACH_AXES = ('perspective', 'scale', 'structure', 'voice', 'visualization')
STRATEGY_KEYS = ('why_this_idea', 'viewer_experience', 'progression', 'fits_and_forced', 'facts_as_experience',
                 'picture_contribution', 'sound_and_breath', 'distinct_from_references')
TREATMENT_KEYS = ('narrator', 'writing_voice', 'structure_and_pace', 'visual_language', 'sound',
                  'audiovisual_relationship', 'emotional_course', 'evidence_used', 'departures', 'risks')
TREATMENT_SHOWN_TO_REVIEWER = ('narrator', 'writing_voice', 'structure_and_pace', 'visual_language', 'sound',
                               'audiovisual_relationship', 'emotional_course')
SAMPLE_MOMENTS = ('opening', 'quiet_middle', 'turning_point')
# The third sample is where this video's value lands hardest: its turn when it has one, otherwise its best
# demonstration, its clearest moment of understanding, its biggest laugh. A direction may name it "strongest_moment",
# so nobody is pushed to invent a turn the subject doesn't have (2026-11-24); "turning_point" stays valid.
SAMPLE_ALIASES = {'turning_point': ('turning_point', 'strongest_moment')}
BEAT_DIRECTION_KEYS = ('experience', 'narration_direction', 'visual_intent', 'sound_direction', 'pace')
# A major finding asks for a fresh read of the revised version until this round; after it the director decides
# and records why (no endless loops). More rounds are always allowed, never required.
REVIEW_MAX_ROUNDS = {'treatment': 1, 'script': 2, 'final': 2}
REVIEW_ACTIONS = ('revised', 'kept', 'disputed')
MIN_FIELD_WORDS, MIN_SAMPLE_WORDS, MIN_PICTURE_WORDS, MIN_NOTE_WORDS = 6, 50, 10, 5
# Edits after the last read that no finding asked for: a few lines (a length trim) pass with a warning; more need
# a fresh read, because the approval no longer describes the script.
SMALL_EDIT_LINES, SMALL_EDIT_SHARE = 10, 0.03


def n_words(s):
    return len(re.findall(r'\w+', str(s or ''), flags=re.UNICODE))


def canonical_sha(obj):
    return hashlib.sha256(json.dumps(obj, sort_keys=True, ensure_ascii=False).encode('utf-8')).hexdigest()


def ref_av_path(rd, vid):
    return rd / '20-analysis' / 'av' / f'{vid}.json'


def _content_tokens(text):
    return {t for t in re.findall(r"[a-z0-9']+", strip_tags(text).lower()) if len(t) > 3}


def _jaccard(a, b):
    return len(a & b) / len(a | b) if (a | b) else 0.0


# ---------------------------------------------------------------- the subject, before the approaches
# Topic discovery (2026-11-24, revised the same day): what the user's scope leaves open, which subjects (or angles of
# the user's own topic) were researched, what each could give this audience and on what evidence, whether its material
# can carry the locked length as a progression (the director's verdict and its reasons, never a share of minutes),
# which was chosen over which and why, and the researched value the film must carry (02 "Finding the subject"). The
# code checks that this reasoning exists, is specific to each candidate, rests on the claims and sources it names
# (claims.json, the sources ledger and what the ledger says was actually read), keeps the user's scope, and reaches
# the beat map, the script and the pictures. Whether a subject is worth a viewer's time, and whether a source deserves
# trust, stays the director's judgement: never a score, and never decided by looking at a URL.
SUBJECT_SCOPES = ('niche', 'subject', 'topic', 'story')
# How sure the film may be of a researched item. established: a fact, on claims whose sources were read; reasoned: a
# consequence derived from established items by stated reasoning; contested: credible sources disagree or the evidence
# leaves it open (said with its hedge); speculative: a possibility beyond the evidence (said as one); assumed: an
# explicit premise of a hypothetical (said as an assumption); invented: only where the subject is not factual.
CERTAINTIES = ('established', 'reasoned', 'contested', 'speculative', 'assumed', 'invented')
CERTAINTY_STRENGTH = {'established': 4, 'reasoned': 3, 'contested': 2, 'speculative': 1, 'assumed': 1, 'invented': 0}
HEDGED_CERTAINTIES = ('contested', 'speculative', 'assumed')
SIGNIFICANCE_CERTAINTIES = ('established', 'reasoned', 'contested', 'speculative', 'invented')
# claims.json confidence (02): confirmed = a primary record, or two or more independent credible sources, read;
# likely = one credible source; disputed = credible sources disagree; legend = popular, unverified.
CLAIM_CONFIDENCE = ('confirmed', 'likely', 'disputed', 'legend')
SUBJECT_TEXT_KEYS = ('subject', 'value_form', 'what_happens', 'why_it_matters', 'reward')
CHOSEN_CORE_KEYS = ('subject', 'angle', 'value_form', 'factual', 'what_happens', 'why_it_matters', 'reward')
RUNTIME_VERDICTS = ('sustains', 'short', 'uncertain')
VALUE_KEY = 'subject.value_to_carry.'


def source_ids(text):
    return set(re.findall(r'\bS\d+\b', str(text or '')))


def sources_path(rd, video):
    return rd / '30-research' / f'video-{int(video):02d}' / 'sources.md'


def claims_path(rd, video):
    return rd / '30-research' / f'video-{int(video):02d}' / 'claims.json'


def _ids(xs):
    if isinstance(xs, str):
        xs = [xs]
    return [str(x).strip() for x in (xs or []) if str(x).strip()]


def is_key_moment(b):
    km = (b or {}).get('key_moment')
    return km is not None and km is not False and bool(str(km).strip())


def ledger_entries(text):
    """The sources ledger (30-research/video-NN/sources.md) entry by entry: '### S1. title' starts one, and its
    '- Access:' line says how much of the source was actually read (read: the text itself, or the part that matters;
    indirect: only through another source; snippet: only a search summary). {id: {'access', 'sha256'}}. What the ledger
    says about a source's standing stays the researcher's judgement; this only reads what it records."""
    found, cur = {}, None
    for line in str(text or '').splitlines():
        m = re.match(r'\s*#{2,4}\s*\**\s*(S\d+)\b', line)
        if m:
            cur = m.group(1)
            found[cur] = {'access': 'unknown', 'lines': [line]}
            continue
        if cur is None:
            continue
        found[cur]['lines'].append(line)
        a = re.match(r'\s*[-*]?\s*\**access\**\s*:\s*\**\s*(.*)', line, re.I)
        if a:
            v = a.group(1).strip().lower()
            found[cur]['access'] = ('snippet' if v.startswith(('snippet', 'search')) else
                                    'indirect' if v.startswith('indirect') else
                                    'read' if v.startswith('read') else 'unknown')
    return {k: {'access': v['access'],
                'sha256': hashlib.sha256(' '.join(' '.join(v['lines']).split()).encode('utf-8')).hexdigest()}
            for k, v in found.items()}


def claims_index(claims):
    return {str(c.get('id')).strip(): c for c in (claims or {}).get('claims') or []
            if isinstance(c, dict) and str(c.get('id') or '').strip()}


def sample_of(samples, m):
    """A treatment's sample for one of SAMPLE_MOMENTS, under its own name or an alias (SAMPLE_ALIASES)."""
    samples = samples if isinstance(samples, dict) else {}
    for k in SAMPLE_ALIASES.get(m, (m,)):
        if isinstance(samples.get(k), dict):
            return samples[k]
    return {}


def sample_label(samples, m):
    samples = samples if isinstance(samples, dict) else {}
    for k in SAMPLE_ALIASES.get(m, (m,)):
        if isinstance(samples.get(k), dict):
            return k.replace('_', ' ')
    return m.replace('_', ' ')


def _reason_key(text, own):
    """A reason with the candidate's own subject words taken out: two candidates left with the same words were given
    the same reason, and a reason that fits every candidate explains none of them."""
    return ' '.join(t for t in re.findall(r"[a-z0-9']+", strip_tags(str(text or '')).lower()) if t not in own)


def candidate_read_sources(c, cidx, ledger):
    """The sources behind a candidate's strongest material that the ledger says were read."""
    srcs = set()
    for m in (c or {}).get('strongest_material') or []:
        if isinstance(m, dict):
            srcs |= set(_ids(m.get('sources')))
            for x in _ids(m.get('claims')):
                srcs |= set(_ids((cidx.get(x) or {}).get('sources')))
    return sorted(x for x in srcs if (ledger.get(x) or {}).get('access') == 'read')


def coverage_issues(cov):
    """The chosen subject's outward look (selection.coverage): where the director looked for what already exists on
    it, what was found (or why nothing was), and what this film gives a viewer that those do not. The reader of the
    record is the director choosing and the user approving; no count, score or share decides anything here."""
    if not isinstance(cov, dict):
        return ['subject_selection_needs_coverage:what_already_exists_on_this_subject_where_you_looked_and_what_this_'
                'film_adds']
    out = []
    if not [x for x in cov.get('looked') or [] if isinstance(x, dict) and n_words(x.get('where')) >= 1
            and n_words(x.get('for')) >= 2]:
        out.append('subject_selection_coverage_needs_where_it_looked:looked[{where,for}]')
    rows = [x for x in cov.get('exists') or [] if isinstance(x, dict)] if isinstance(cov.get('exists'), list) else []
    if not rows and n_words(cov.get('none_found')) < MIN_FIELD_WORDS:
        out.append('subject_selection_coverage_needs_what_exists_or_why_nothing_was_found:exists[{what,by,'
                   'how_it_tells_it}]_or_none_found')
    for i, x in enumerate(rows, 1):
        if n_words(x.get('what')) < 2 or n_words(x.get('how_it_tells_it')) < 4:
            out.append(f'subject_selection_coverage_entry_{i}_needs_what_it_is_and_how_it_tells_it')
    if n_words(cov.get('this_film_adds')) < MIN_FIELD_WORDS:
        out.append('subject_selection_coverage_missing_what_this_film_adds')
    return out


def selection_promise_issues(pr):
    """What the film will be clicked for (selection.promise), in words: a working title, the picture a thumbnail would
    show, and what a viewer who clicks expects to get. A working promise, revised freely; it gives the treatments, the
    opening and the readers something to be held to."""
    if not isinstance(pr, dict):
        return ['subject_selection_needs_its_promise:working_title_thumbnail_idea_and_what_the_viewer_expects']
    out = []
    if n_words(pr.get('working_title')) < 2:
        out.append('subject_selection_promise_missing_working_title')
    if n_words(pr.get('thumbnail_idea')) < 4:
        out.append('subject_selection_promise_missing_thumbnail_idea')
    if n_words(pr.get('viewer_expects')) < MIN_FIELD_WORDS:
        out.append('subject_selection_promise_missing_what_the_viewer_expects')
    return out


def selection_promise(direction):
    """The chosen subject's working promise ({} when none): working_title, thumbnail_idea, viewer_expects."""
    subj = (direction or {}).get('subject')
    sel = subj.get('selection') if isinstance(subj, dict) and isinstance(subj.get('selection'), dict) else {}
    return sel.get('promise') if isinstance(sel.get('promise'), dict) else {}


def key_moment_evidence_signals(direction, beats, claims):
    """A key moment is where the viewer's trust is made or lost. One that carries a value said as established (or as a
    consequence reasoned from it) on claims that each rest on a single source ('likely', none confirmed) is named, so
    the film corroborates it or says whose finding it is ('in one experiment', 'one team found'). A signal, not a
    gate: a single good source can carry a moment, said as what it is."""
    subj = (direction or {}).get('subject')
    if not isinstance(subj, dict):
        return []
    sel = subj.get('selection') if isinstance(subj.get('selection'), dict) else {}
    ch = next((c for c in subj.get('candidates') or [] if isinstance(c, dict)
               and str(c.get('id')) == str(sel.get('candidate'))), {})
    mats = {str(m.get('id')).strip(): m for m in ch.get('strongest_material') or [] if isinstance(m, dict)}
    vals = {str(v.get('id')): v for v in subj.get('value_to_carry') or [] if isinstance(v, dict)}
    cidx = claims_index(claims)

    def claims_of(mid, depth=0):
        m = mats.get(mid) or {}
        out = set(_ids(m.get('claims')))
        if depth < 3:
            for f in _ids(m.get('from')):
                out |= claims_of(f, depth + 1)
        return out
    out = []
    for b in beats or []:
        if not is_key_moment(b):
            continue
        for r in (str(x).strip() for x in b.get('carries') or []):
            v = vals.get(r)
            if not v or str(v.get('certainty') or '').lower() not in ('established', 'reasoned'):
                continue
            cs = sorted(c for mid in _ids(v.get('rests_on')) for c in claims_of(mid) if c in cidx)
            confs = {str(cidx[c].get('confidence') or '').lower() for c in cs}
            if cs and 'confirmed' not in confs and confs <= {'likely'}:
                out.append(f'key moment {b.get("id")} carries {r} on single-source claims only ({",".join(cs)}): '
                           'corroborate them, or let the script say whose finding it is')
    return out


def material_issues(prefix, items, known, factual, claims=None, ledger=None, strict=False):
    """Each researched item says what it is and how sure the film may be of it (CERTAINTIES), tied to what supports it.
    established: claims in claims.json (strict, the chosen subject's material; recorded sources are enough for a
    candidate only considered), never a disputed or legend claim, and each claim with at least one source the ledger
    says was read; contested: how the film keeps it honest (hedge), and its claims when strict; reasoned: the
    established items of the same candidate it follows from, and how (from, reasoning); speculative or assumed: how the
    film frames it (framed_as); invented: only where the subject is not factual. A recorded link is not evidence: the
    reading of the source is."""
    out = []
    claims, ledger = claims or {}, ledger or {}
    by_id = {str(m.get('id')).strip(): m for m in items if str(m.get('id') or '').strip()}
    for i, m in enumerate(items, 1):
        ident = str(m.get('id') or '').strip()
        tag = f'{prefix}_{ident or i}'
        if strict and not ident:
            out.append(f'{tag}_needs_an_id:id')
        if n_words(m.get('what')) < 3:
            out.append(f'{tag}_missing_what')
        cert = str(m.get('certainty') or '').strip().lower()
        if cert not in CERTAINTIES:
            out.append(f'{tag}_certainty_must_be:' + '/'.join(CERTAINTIES))
            continue
        srcs, cids = set(_ids(m.get('sources'))), _ids(m.get('claims'))
        if srcs and not known:
            out.append(f'{tag}_cites_sources_but_the_ledger_is_empty:30-research/video-NN/sources.md')
        elif srcs - known:
            out.append(f'{tag}_cites_sources_not_in_the_ledger:' + ','.join(sorted(srcs - known)))
        if [c for c in cids if c not in claims]:
            out.append(f'{tag}_cites_claims_not_in_claims_json:' + ','.join(c for c in cids if c not in claims))
        if cert == 'established':
            if strict and not cids:
                out.append(f'{tag}_established_needs_its_claims:claims')
            elif not cids and not srcs:
                out.append(f'{tag}_established_needs_a_source')
            for c in cids:
                cl = claims.get(c)
                if not cl:
                    continue
                conf = str(cl.get('confidence') or '').strip().lower()
                if conf in ('disputed', 'legend'):
                    out.append(f'{tag}_said_as_established_but_claim_{c}_is_{conf}:say_it_as_contested_or_leave_it_out')
                elif conf not in CLAIM_CONFIDENCE:
                    out.append(f'{tag}_claim_{c}_confidence_must_be:' + '/'.join(CLAIM_CONFIDENCE))
                csrc = set(_ids(cl.get('sources')))
                if csrc - known:
                    out.append(f'{tag}_claim_{c}_cites_sources_not_in_the_ledger:' + ','.join(sorted(csrc - known)))
                if not any((ledger.get(s) or {}).get('access') == 'read' for s in csrc):
                    out.append(f'{tag}_claim_{c}_rests_on_no_source_that_was_read:read_one_and_record_its_Access')
        elif cert == 'contested':
            if n_words(m.get('hedge')) < 4:
                out.append(f'{tag}_contested_needs_how_it_is_kept_honest:hedge')
            if strict and not cids:
                out.append(f'{tag}_contested_needs_its_claims:claims')
        elif cert == 'reasoned':
            frm = _ids(m.get('from'))
            if n_words(m.get('reasoning')) < 4:
                out.append(f'{tag}_reasoned_needs_its_reasoning:reasoning')
            if not frm:
                out.append(f'{tag}_reasoned_needs_what_it_follows_from:from')
            elif [f for f in frm if str((by_id.get(f) or {}).get('certainty') or '').lower() != 'established']:
                out.append(f'{tag}_reasoned_from_items_not_established_here:' + ','.join(
                    f for f in frm if str((by_id.get(f) or {}).get('certainty') or '').lower() != 'established'))
        elif cert in ('speculative', 'assumed') and n_words(m.get('framed_as')) < 4:
            out.append(f'{tag}_{cert}_needs_how_it_is_framed:framed_as')
        elif cert == 'invented' and factual is not False:
            out.append(f'{tag}_invented_material_only_in_a_subject_that_is_not_factual')
    return out


def natural_minutes(rt):
    """A subject's own size, as the director judges it from its progression: (low, high) minutes it runs when it is
    told well, neither stretched nor squeezed (runtime.natural_minutes). None when it is not two numbers in order. The
    length follows this; nothing is ever written to reach a length."""
    v = rt.get('natural_minutes') if isinstance(rt, dict) else None
    if not isinstance(v, (list, tuple)) or len(v) != 2:
        return None
    try:
        lo, hi = float(v[0]), float(v[1])
    except (TypeError, ValueError):
        return None
    return (lo, hi) if 0 < lo <= hi else None


def runtime_issues(cid, c):
    """Whether a candidate's material can carry a long-form video, and how long, as the director judges it: the
    progression of what the viewer newly gets, each step resting on researched material, a verdict with its reasons,
    and the story's own size as a range (natural_minutes). Never a share of minutes: six minutes of notes can hold ten
    when each step opens the next, fifteen may not when they repeat. (issues, signals)."""
    out, sig = [], []
    rt = c.get('runtime') if isinstance(c.get('runtime'), dict) else {}
    tag = f'subject_candidate_{cid}_runtime'
    mids = {str(m.get('id')).strip() for m in c.get('strongest_material') or [] if isinstance(m, dict)
            and str(m.get('id') or '').strip()}
    steps = [s for s in rt.get('progression') or [] if isinstance(s, dict)]
    if not steps:
        out.append(f'{tag}_needs_its_progression:what_the_viewer_newly_gets_step_by_step')
    seen, used = set(), set()
    for i, s in enumerate(steps, 1):
        if n_words(s.get('adds')) < 4:
            out.append(f'{tag}_step_{i}_missing_adds')
        key = _norm(s.get('adds'))
        if key and key in seen:
            out.append(f'{tag}_step_{i}_repeats_an_earlier_step')
        seen.add(key)
        mm = set(_ids(s.get('material')))
        if not mm:
            out.append(f'{tag}_step_{i}_rests_on_no_material:material')
        elif mm - mids:
            out.append(f'{tag}_step_{i}_names_material_this_candidate_lacks:' + ','.join(sorted(mm - mids)))
        elif i > 1 and mm <= used:
            sig.append(f'{tag}_step_{i}_uses_only_material_earlier_steps_used:is_it_new_for_the_viewer')
        used |= mm
    verdict = str(rt.get('verdict') or '').strip().lower()
    if verdict not in RUNTIME_VERDICTS:
        out.append(f'{tag}_verdict_must_be:' + '/'.join(RUNTIME_VERDICTS))
    if n_words(rt.get('why')) < MIN_FIELD_WORDS:
        out.append(f'{tag}_needs_why_the_verdict')
    if verdict in ('short', 'uncertain') and n_words(rt.get('shortfall')) < 4:
        out.append(f'{tag}_{verdict}_needs_what_is_missing:shortfall')
    if natural_minutes(rt) is None:
        # the story's own size (planning rules 6): the length follows it, whoever sets the length
        out.append(f'{tag}_needs_its_natural_size:natural_minutes_[low,high]_how_long_this_material_runs_when_told_well')
    return out, sig


def value_issues(vals, chosen):
    """value_to_carry: what the film must deliver, each with why it matters, how sure the film may be of it and, in a
    factual subject, the chosen subject's material it rests on (never said more surely than that material allows); what
    the viewer must hold first (needs_first) names other values."""
    iss = []
    ch = chosen or {}
    factual = ch.get('factual')
    mats = {str(m.get('id')).strip(): m for m in ch.get('strongest_material') or [] if isinstance(m, dict)
            and str(m.get('id') or '').strip()}
    vids = [str(v.get('id') or '').strip() for v in vals]
    if not vals or len(set(vids)) != len(vids) or '' in vids:
        iss.append('subject_needs_value_to_carry_with_distinct_ids')
    for v in vals:
        rid = str(v.get('id') or '').strip()
        tag = f'subject_value_{rid}'
        if n_words(v.get('what')) < 3:
            iss.append(f'{tag}_missing_what')
        if n_words(v.get('why_it_matters')) < 4:
            iss.append(f'{tag}_missing_why_it_matters')
        cert = str(v.get('certainty') or '').strip().lower()
        if cert not in CERTAINTIES:
            iss.append(f'{tag}_certainty_must_be:' + '/'.join(CERTAINTIES))
            continue
        if cert == 'contested' and n_words(v.get('hedge')) < 4:
            iss.append(f'{tag}_contested_needs_how_it_is_kept_honest:hedge')
        if cert in ('speculative', 'assumed') and n_words(v.get('framed_as')) < 4:
            iss.append(f'{tag}_{cert}_needs_how_it_is_framed:framed_as')
        if cert == 'invented' and factual is not False:
            iss.append(f'{tag}_invented_value_only_in_a_subject_that_is_not_factual')
        ro = _ids(v.get('rests_on'))
        if factual is not False:
            if not ro:
                iss.append(f'{tag}_needs_the_material_it_rests_on:rests_on')
            if [x for x in ro if x not in mats]:
                iss.append(f'{tag}_rests_on_material_the_chosen_subject_lacks:' + ','.join(x for x in ro if x not in mats))
            weaker = [x for x in ro if x in mats and CERTAINTY_STRENGTH.get(
                str(mats[x].get('certainty') or '').strip().lower(), 0) < CERTAINTY_STRENGTH[cert]]
            if weaker:
                iss.append(f'{tag}_said_as_{cert}_but_rests_on_weaker_material:' + ','.join(weaker))
        for u in _ids(v.get('needs_first')):
            if u == rid or u not in vids:
                iss.append(f'{tag}_needs_first_names_no_other_value:{u}')
    return iss


PAYOFF_SHAPES = ('builds_to', 'several', 'progressive')


def payoff_issues(tag, p, mids, factual):
    """A candidate's payoff, assessed before the choice (2026-11-24): its shape (one payoff the film builds to,
    several along the way, or value delivered progressively with no climax), the candidate's own material it rests on,
    why it is substantial for this audience, what the viewer must hold first for it to land, and whether it is worth
    the time it takes to build (for a progressive one: whether the value along the way holds the length). Magnitude is
    the strength of the value this content gives, never drama for its own sake."""
    if not isinstance(p, dict):
        return [f'{tag}_needs_its_payoff_assessed:payoff{{shape,rests_on,why_substantial,needs_first,worth_the_buildup}}']
    out = []
    if str(p.get('shape') or '').strip().lower() not in PAYOFF_SHAPES:
        out.append(f'{tag}_payoff_shape_must_be:' + '/'.join(PAYOFF_SHAPES))
    for k in ('why_substantial', 'worth_the_buildup'):
        if n_words(p.get(k)) < MIN_FIELD_WORDS:
            out.append(f'{tag}_payoff_needs_{k}')
    if n_words(p.get('needs_first')) < 3:
        out.append(f'{tag}_payoff_needs_what_the_viewer_must_hold_first:needs_first')
    ro = _ids(p.get('rests_on'))
    if factual is not False:
        if not ro:
            out.append(f'{tag}_payoff_needs_the_material_it_rests_on:rests_on')
        missing = [x for x in ro if x not in mids]
        if missing:
            out.append(f'{tag}_payoff_rests_on_material_the_candidate_lacks:' + ','.join(missing))
    return out


def payoff_value_issues(vals, chosen):
    """The chosen payoff becomes the value the film carries: value_to_carry marks it (payoff: true), resting on the
    payoff's own material in a factual subject."""
    pay = (chosen or {}).get('payoff')
    if not isinstance(pay, dict):
        return []
    pv = [v for v in vals if v.get('payoff') is True]
    if not pv:
        return ['subject_value_to_carry_names_no_payoff_value:mark_the_value_the_payoff_delivers_with_payoff_true']
    iss, pro = [], set(_ids(pay.get('rests_on')))
    if (chosen or {}).get('factual') is not False and pro:
        for v in pv:
            if not set(_ids(v.get('rests_on'))) & pro:
                iss.append(f'subject_value_{v.get("id")}_is_the_payoff_but_rests_on_none_of_its_material:'
                           + ','.join(sorted(pro)))
    return iss


def locked_niche_names(rd, lock):
    """The names the run's locked niche goes by: the user's pick from the niche map (niche-lock: its name and id); in
    a run made before niche discovery, the niche itself, or, for a cohort the user grouped, its id and the niches its
    references' cards name (never the internal '__cohort__:' label)."""
    nl = read_json(niche_lock_path(rd))
    if nl.get('niche_id'):
        return {str(nl.get('name') or '').strip().lower(), str(nl.get('niche_id') or '').strip().lower()} - {''}
    niche = str((lock or {}).get('niche') or '').strip().lower()
    if not niche.startswith('__cohort__:'):
        return {niche} if niche else set()
    names = {niche[len('__cohort__:'):]}
    _vids, cards, _issues = card_set(rd)
    for i in (lock or {}).get('reference_ids') or []:
        names |= {str(x).strip().lower() for x in (cards.get(i) or {}).get('niches') or [] if str(x).strip()}
    return names


def niche_family_refs(rd, lock):
    """The references in the locked niche: the niche map's members of the user's pick (niche-lock: core and overlap,
    whatever their format); in a run made before niche discovery, the references whose cards name it (a cohort: the
    cohort's own cards)."""
    nl = read_json(niche_lock_path(rd))
    if nl.get('niche_id'):
        return {str(m.get('ref')).strip().upper() for m in nl.get('members') or [] if isinstance(m, dict) and m.get('ref')}
    niche = str((lock or {}).get('niche') or '').strip().lower()
    if not niche:
        return set()
    _vids, cards, _issues = card_set(rd)
    if niche.startswith('__cohort__:'):
        cid = niche[len('__cohort__:'):]
        return {i for i, c in cards.items() if str(c.get('cohort_id') or '').strip().lower() == cid}
    return {i for i, c in cards.items() if niche in [str(x).strip().lower() for x in c.get('niches') or []]}


def subject_issues(subj, sources_text='', locked_s=None, refs=(), locked_niche=None, claims=None):
    """(issues, warnings) for direction.json -> subject. Presence, specificity, links and scope only: the chosen
    candidate's research must hold; the others were considered, so their gaps are warnings."""
    iss, warn = [], []
    if not isinstance(subj, dict):
        return ['direction_needs_subject_research:subject'], warn
    ledger = ledger_entries(sources_text)
    known = set(ledger) or source_ids(sources_text)
    cidx = claims_index(claims)
    sc = subj.get('scope') if isinstance(subj.get('scope'), dict) else {}
    kind = str(sc.get('kind') or '').strip().lower()
    if kind not in SUBJECT_SCOPES:
        iss.append('subject_scope_kind_must_be:' + '/'.join(SUBJECT_SCOPES))
    if n_words(sc.get('user_words')) < 1:
        iss.append('subject_scope_needs_the_users_own_words:user_words')
    allowed = ({str(x).strip().lower() for x in locked_niche if str(x).strip()}
               if isinstance(locked_niche, (set, list, tuple)) else
               ({str(locked_niche).strip().lower()} if locked_niche else set()))
    if allowed and str(sc.get('niche') or '').strip().lower() not in allowed:
        iss.append('subject_scope_niche_must_be_the_locked_niche:' + '/'.join(sorted(allowed)))
    if kind == 'niche':
        # what the locked niche is taken to be and where a subject would stop being it: the line a subject, a treatment
        # and its reader are held to (a technique borrowed from another niche is fine; its subject assumptions are not)
        for k in ('understood_as', 'boundary'):
            if n_words(sc.get(k)) < MIN_FIELD_WORDS:
                iss.append(f'subject_niche_scope_needs_{k}')
    if kind in ('subject', 'topic', 'story'):
        # What the user asked for, in the director's words, and where it would stop being that: what the choice is
        # read against. Word overlap can't tell whether a subject is still the user's; for an exact topic or story the
        # blind treatment reader is asked too (review-packet --kind treatment), and its answer is a finding.
        for k in ('understood_as', 'boundary'):
            if n_words(sc.get(k)) < MIN_FIELD_WORDS:
                iss.append(f'subject_{kind}_scope_needs_{k}')
    if n_words(subj.get('audience_value')) < MIN_FIELD_WORDS:
        iss.append('subject_missing_audience_value')
    # what the processed references show about how this audience is rewarded: observed apart from interpreted
    fr = [x for x in subj.get('from_references') or [] if isinstance(x, dict)]
    refset = {str(r).strip().upper() for r in refs or []}
    if refset and not fr:
        iss.append('subject_needs_from_references:what_the_references_show_about_this_audiences_rewards')
    for i, x in enumerate(fr, 1):
        v = str(x.get('ref') or '').strip().upper()
        if refset and v not in refset:
            iss.append(f'subject_from_references_{i}_names_a_reference_not_in_the_evidence:{v}')
        if parse_span(x.get('at'))[0] is None:
            iss.append(f'subject_from_references_{i}_needs_a_time:at')
        if n_words(x.get('observed')) < 4:
            iss.append(f'subject_from_references_{i}_needs_what_is_observed')
        if n_words(x.get('interpretation')) < 4:
            iss.append(f'subject_from_references_{i}_needs_its_interpretation_apart')
    cands = [c for c in subj.get('candidates') or [] if isinstance(c, dict)]
    ids = [str(c.get('id') or '').strip() for c in cands]
    if not cands or len(set(ids)) != len(ids) or '' in ids:
        iss.append('subject_needs_researched_candidates_with_distinct_ids')
    elif kind in ('niche', 'subject', 'topic') and len(cands) < 2:
        # a choice with nothing to choose from is the first idea that came up (an exact topic compares its angles)
        iss.append(f'subject_{kind}_scope_needs_a_researched_alternative')
    elif kind in ('niche', 'subject', 'topic'):
        # An alternative ruled out on search summaries alone was never compared: the five exercises of 2026-11-24 read
        # 3-5 sources for the subject they had in mind and 0-1 for the others, which then lost for being unread.
        sel_ = subj.get('selection') if isinstance(subj.get('selection'), dict) else {}
        chosen_id = str(sel_.get('candidate') or '').strip()
        unread = [str(c.get('id')) for c in cands if str(c.get('id')) != chosen_id
                  and not candidate_read_sources(c, claims_index(claims), ledger)]
        alts_n = len([c for c in cands if str(c.get('id')) != chosen_id])
        if alts_n and len(unread) == alts_n:
            iss.append(f'subject_{kind}_scope_needs_an_alternative_whose_source_was_read:alternatives_seen_only_in_'
                       'search_summaries_were_never_compared')
        for a in unread:
            warn.append(f'subject_alternative_{a}_ruled_out_on_search_summaries_alone:read_its_strongest_source_or_'
                        'say_plainly_the_comparison_was_uneven')
    sel = subj.get('selection') if isinstance(subj.get('selection'), dict) else {}
    chosen = str(sel.get('candidate') or '').strip()
    if chosen not in ids:
        iss.append('subject_selection_must_name_a_listed_candidate')
    if n_words(sel.get('why')) < MIN_FIELD_WORDS:
        iss.append('subject_selection_missing_why')
    ch = next((c for c in cands if str(c.get('id')) == chosen), None)
    mats_ch = {str(m.get('id')).strip(): m for m in (ch or {}).get('strongest_material') or []
               if isinstance(m, dict) and str(m.get('id') or '').strip()}
    if ch is not None:
        # the choice rests on evidence it names: what in the chosen subject's research makes it the one
        dm = _ids(sel.get('decisive_material'))
        if not dm:
            iss.append('subject_selection_needs_decisive_material:the_chosen_subjects_material_the_choice_rests_on')
        for x in dm:
            m = mats_ch.get(x)
            if m is None:
                iss.append(f'subject_selection_decisive_material_not_in_the_chosen_subject:{x}')
            elif str(m.get('certainty') or '').strip().lower() == 'established':
                weak = [c for c in _ids(m.get('claims'))
                        if str((cidx.get(c) or {}).get('confidence') or '').strip().lower() != 'confirmed']
                if weak:
                    iss.append(f'subject_choice_rests_on_{x}_whose_claims_are_not_confirmed:' + ','.join(weak) +
                               ':corroborate_them_or_rest_the_choice_on_stronger_material')
    # every alternative is answered on its own terms, and differently from the others
    alts = [i for i in ids if i and i != chosen]
    oa = sel.get('over_alternatives')
    answered = {str(x.get('candidate') or '').strip(): x for x in (oa if isinstance(oa, list) else [])
                if isinstance(x, dict)}
    if alts and not isinstance(oa, list):
        iss.append('subject_selection_over_alternatives_must_answer_each_alternative:[{candidate,why_not}]')
    why_nots, id_toks = {}, {i.lower() for i in ids if i}
    for a in alts:
        x = answered.get(a) or {}
        if n_words(x.get('why_not')) < MIN_FIELD_WORDS:
            iss.append(f'subject_selection_does_not_say_why_not_{a}:over_alternatives')
        ca = next((c for c in cands if str(c.get('id')) == a), {})
        key = _reason_key(x.get('why_not'), id_toks | set(re.findall(
            r"[a-z0-9']+", f"{ca.get('subject') or ''} {ca.get('angle') or ''}".lower())))
        if n_words(key) >= 3:
            why_nots.setdefault(key, []).append(a)
    for key, who in why_nots.items():
        if len(who) > 1:
            iss.append(f'subject_selection_gives_{"_and_".join(who)}_the_same_why_not:say_what_is_weaker_in_each')
    if kind in ('topic', 'story') and sel.get('keeps_user_scope') is not True:
        # an exact topic or story is developed, never replaced (the user's direction)
        iss.append(f'subject_exact_{kind}_must_be_kept:selection.keeps_user_scope')
    if kind in ('subject', 'topic', 'story') and n_words(sel.get('how_scope_kept')) < MIN_FIELD_WORDS:
        iss.append(f'subject_{kind}_scope_needs_how_scope_kept:selection.how_scope_kept')
    # The outward look and the promise (planning rules 5): what already exists on the chosen subject and what this
    # film gives that those do not; and what the film will be clicked for, chosen with the subject so the opening has
    # a contract to keep. Presence only: whether the subject is worth making stays the director's judgement.
    iss += coverage_issues(sel.get('coverage')) + selection_promise_issues(sel.get('promise'))
    reasons = {}
    for c in cands:
        cid = str(c.get('id'))
        strict = cid == chosen
        mine = iss if strict else warn
        for k in SUBJECT_TEXT_KEYS:
            if n_words(c.get(k)) < (2 if k in ('subject', 'value_form') else 4):
                mine.append(f'subject_candidate_{cid}_missing_{k}')
        if not isinstance(c.get('factual'), bool):
            mine.append(f'subject_candidate_{cid}_must_say_factual_true_or_false')
        mats = [m for m in c.get('strongest_material') or [] if isinstance(m, dict)]
        if not mats:
            mine.append(f'subject_candidate_{cid}_names_no_strongest_material')
        mids = [str(m.get('id') or '').strip() for m in mats if str(m.get('id') or '').strip()]
        if len(set(mids)) != len(mids):
            mine.append(f'subject_candidate_{cid}_material_ids_must_be_distinct')
        mine += material_issues(f'subject_candidate_{cid}_material', mats, known, c.get('factual'), claims=cidx,
                                ledger=ledger, strict=strict)
        r_iss, r_sig = runtime_issues(cid, c)
        mine += r_iss
        warn += r_sig
        if n_words(c.get('feasibility')) < 4:
            mine.append(f'subject_candidate_{cid}_missing_feasibility')
        mine += payoff_issues(f'subject_candidate_{cid}', c.get('payoff'), set(mids), c.get('factual'))
        own = set(re.findall(r"[a-z0-9']+", f"{c.get('subject') or ''} {c.get('angle') or ''}".lower()))
        for k in ('what_happens', 'why_it_matters', 'reward'):
            key = _reason_key(c.get(k), own)
            if n_words(key) >= 3:
                reasons.setdefault((k, key), []).append(cid)
    for (k, _), who in reasons.items():
        if len(set(who)) > 1:
            (iss if chosen in who else warn).append(
                f'subject_candidates_{"_and_".join(sorted(set(who)))}_share_the_same_{k}:'
                'a_reason_that_fits_any_candidate_explains_none')
    if ch is not None:
        # the chosen material carries the locked length, or the shortfall went to the user: re-selection (another
        # candidate or angle) or the user's own decision, never padding
        rt = ch.get('runtime') if isinstance(ch.get('runtime'), dict) else {}
        verdict = str(rt.get('verdict') or '').strip().lower()
        dec = subj.get('runtime_decision') if isinstance(subj.get('runtime_decision'), dict) else {}
        decided = (str(dec.get('decided_by') or '').strip().lower() == 'user' and n_words(dec.get('user_words')) >= 2
                   and n_words(dec.get('decision')) >= 4)
        if verdict in ('short', 'uncertain') and not decided:
            iss.append(f'subject_material_judged_{verdict}_for_the_locked_length:choose_another_candidate_or_angle_or_'
                       'record_the_users_decision_in_runtime_decision:never_pad')
        # A length the user asked for (Standard, or their own minutes) beside the story's own size: outside the range
        # the director gave, the mismatch is the user's to settle before a script is written to it (planning rules 6).
        # A length the story set itself (length --mode story) is answered where it is locked, so none is passed here.
        nat = natural_minutes(rt)
        if nat and locked_s and not decided and not nat[0] * 60 <= float(locked_s) <= nat[1] * 60:
            iss.append(f'subject_natural_size_{nat[0]:g}-{nat[1]:g}_min_is_not_the_locked_'
                       f'{round(float(locked_s) / 60, 1):g}_min:choose_another_candidate_or_angle_or_record_the_users_'
                       'decision_in_runtime_decision:never_pad_never_squeeze')
    vals = [v for v in subj.get('value_to_carry') or [] if isinstance(v, dict)]
    iss += value_issues(vals, ch)
    iss += payoff_value_issues(vals, ch)
    return iss, warn


def card_moment_issues(card, ident):
    """How a reference makes its developments matter, from its card: timed, observed apart from interpreted (01)."""
    ms = [m for m in (card or {}).get('moments_that_matter') or [] if isinstance(m, dict)]
    if not ms:
        return [f'reference_{ident}_card_has_no_moments_that_matter']
    return [f'reference_{ident}_moment_{i}_needs_at_observed_and_interpretation' for i, m in enumerate(ms, 1)
            if parse_span(m.get('at'))[0] is None or n_words(m.get('observed')) < 4
            or n_words(m.get('interpretation')) < 4]


def subject_handoff_issues(direction, beats):
    """The researched value reaches the film: each value_to_carry item is carried by a beat (`carries`) or dropped with
    a reason, and not before what it needs first (needs_first); a key moment that carries one keeps its certainty (a
    contested value stays contested, a speculative or assumed one is said as speculative). Key moments are the
    director's call where the video turns or pays off; a video whose value builds up step by step needs none, and no
    milestone is invented to have one (2026-11-24)."""
    subj = (direction or {}).get('subject')
    if not isinstance(subj, dict):
        return []
    vals = {str(v.get('id')): v for v in subj.get('value_to_carry') or [] if isinstance(v, dict)}
    dropped = {str(x.get('id')) for x in subj.get('dropped') or [] if isinstance(x, dict) and n_words(x.get('why')) >= 4}
    carried, first, iss = {}, {}, []
    for k, b in enumerate(beats or []):
        for r in b.get('carries') or []:
            r = str(r).strip()
            if r not in vals:
                iss.append(f'beat_{b.get("id")}_carries_unknown_value:{r}')
                continue
            carried.setdefault(r, []).append(b)
            first.setdefault(r, k)
    for rid, v in vals.items():
        if rid not in carried and rid not in dropped:
            iss.append(f'researched_value_{rid}_reaches_no_beat:carry_it_or_drop_it_with_the_reason_in_subject.dropped')
        cert = str(v.get('certainty') or '').strip().lower()
        for b in carried.get(rid, []):
            if not is_key_moment(b):
                continue
            said = str((b.get('significance') or {}).get('certainty') or 'established').strip().lower()
            if cert == 'contested' and said != 'contested':
                iss.append(f'beat_{b.get("id")}_carries_contested_{rid}_but_states_it_as_{said}')
            elif cert in ('speculative', 'assumed') and said != 'speculative':
                iss.append(f'beat_{b.get("id")}_carries_{cert}_{rid}_but_states_it_as_{said}')
        for u in _ids(v.get('needs_first')):
            if u not in vals or rid not in first:
                continue
            if u not in first:
                iss.append(f'researched_value_{rid}_needs_{u}_first_but_{u}_reaches_no_beat')
            elif first[u] > first[rid]:
                iss.append(f'researched_value_{rid}_lands_before_{u}_which_it_needs_first')
    # The payoff the subject was chosen for: where it builds to a payoff (or several), it lands at a key moment that
    # says what it means; delivered progressively, it is delivered along the way, by more than one beat.
    sel = subj.get('selection') if isinstance(subj.get('selection'), dict) else {}
    ch = next((c for c in subj.get('candidates') or [] if isinstance(c, dict)
               and str(c.get('id')) == str(sel.get('candidate'))), {})
    pay = ch.get('payoff') if isinstance(ch.get('payoff'), dict) else None
    if pay:
        shape = str(pay.get('shape') or '').strip().lower()
        for rid, v in vals.items():
            if v.get('payoff') is not True:
                continue
            bs = carried.get(rid, [])
            if rid in dropped:
                iss.append(f'payoff_value_{rid}_is_dropped:the_subject_was_chosen_for_it:reassess_the_payoff_or_the_choice')
            elif shape in ('builds_to', 'several') and bs and not any(is_key_moment(b) for b in bs):
                iss.append(f'payoff_value_{rid}_reaches_no_key_moment:mark_where_it_lands_(key_moment_with_significance)'
                           '_or_reassess_the_payoff_shape')
            elif shape == 'progressive' and len(bs) == 1:
                iss.append(f'progressive_payoff_value_{rid}_is_carried_by_one_beat:a_progressive_reward_is_delivered_'
                           'along_the_way_or_its_shape_is_another')
    return iss


def value_script_issues(direction, beats, lines, claims):
    """The researched value is said, and said as surely as it is known: a factual value carried by a beat has one of
    its claims tied (claims.json line_refs) to a line of that beat; a contested, speculative or assumed value carried
    by an ordinary beat names the line that keeps it honest (beat `hedges`: {value: line}), at the beat or after it
    (a key moment keeps its own: significance.hedge)."""
    subj = (direction or {}).get('subject')
    if not isinstance(subj, dict) or not lines:
        return []
    sel = subj.get('selection') if isinstance(subj.get('selection'), dict) else {}
    ch = next((c for c in subj.get('candidates') or [] if isinstance(c, dict)
               and str(c.get('id')) == str(sel.get('candidate'))), {})
    mats = {str(m.get('id')).strip(): m for m in ch.get('strongest_material') or [] if isinstance(m, dict)}
    vals = {str(v.get('id')): v for v in subj.get('value_to_carry') or [] if isinstance(v, dict)}
    cidx = claims_index(claims)
    order = [str((l or {}).get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)]
    pos = {lid: i + 1 for i, lid in enumerate(order)}

    def beat_lines(b):
        try:
            return order[int(b['line_start']) - 1:int(b['line_end'])]
        except (KeyError, TypeError, ValueError):
            return []

    def claims_of(mid, depth=0):
        m = mats.get(mid) or {}
        out = set(_ids(m.get('claims')))
        if depth < 3:
            for f in _ids(m.get('from')):
                out |= claims_of(f, depth + 1)
        return out
    by_val, iss = {}, []
    for b in beats or []:
        for r in b.get('carries') or []:
            by_val.setdefault(str(r).strip(), []).append(b)
    for rid, bs in by_val.items():
        v = vals.get(rid)
        if not v:
            continue
        cert = str(v.get('certainty') or '').strip().lower()
        if ch.get('factual') is not False:
            cs = {c for mid in _ids(v.get('rests_on')) for c in claims_of(mid) if c in cidx}
            if cs:
                said = {str(x) for c in cs for x in cidx[c].get('line_refs') or []}
                if not said & {l for b in bs for l in beat_lines(b)}:
                    iss.append(f'researched_value_{rid}_carried_by_{"_".join(str(b.get("id")) for b in bs)}_but_no_line_'
                               'there_is_tied_to_its_claims:' + ','.join(sorted(cs)))
        if cert in HEDGED_CERTAINTIES:
            for b in bs:
                if is_key_moment(b):
                    continue
                h = str((b.get('hedges') or {}).get(rid) or '') if isinstance(b.get('hedges'), dict) else ''
                if h not in pos:
                    iss.append(f'beat_{b.get("id")}_carries_{cert}_{rid}_without_the_line_that_says_so:hedges.{rid}')
                else:
                    try:
                        if pos[h] < int(b.get('line_start')):
                            iss.append(f'beat_{b.get("id")}_hedge_for_{rid}_comes_before_the_beat')
                    except (TypeError, ValueError):
                        pass
    return iss


# An assumed value is a thought experiment's premise: pictured as the premise, framed by the whole film (the real
# exercises' premise beats would otherwise need a note on every shot); contested and speculative research is not
UNSURE_CERTAINTIES = ('contested', 'speculative')


def uncertain_shot_issues(direction, beats, shots):
    """A picture never states as fact what the research leaves open: each shot of a beat that carries a contested,
    speculative value, or is a key moment stated as contested or speculative, says how its picture keeps
    that so (uncertainty_shown: a reconstruction shown as one, a question left visibly open, a picture that asserts
    nothing about it). Fiction and invented premises are not uncertain."""
    subj = (direction or {}).get('subject')
    vals = ({str(v.get('id')): v for v in subj.get('value_to_carry') or [] if isinstance(v, dict)}
            if isinstance(subj, dict) else {})
    unsure = {}
    for b in beats or []:
        why = [f'{r}_{str(vals[r].get("certainty")).lower()}' for r in (str(x) for x in b.get('carries') or [])
               if r in vals and str(vals[r].get('certainty') or '').strip().lower() in UNSURE_CERTAINTIES]
        sig = str((b.get('significance') or {}).get('certainty') or '').strip().lower() if is_key_moment(b) else ''
        if sig in ('contested', 'speculative'):
            why.append(f'significance_{sig}')
        if why:
            unsure[str(b.get('id'))] = why
    return [f'shot_{s.get("id")}_of_beat_{s.get("beat_id")}_needs_uncertainty_shown:' + ','.join(unsure[str(s.get('beat_id'))])
            for s in shots or [] if str(s.get('beat_id')) in unsure and not s.get('reuses')
            and n_words(s.get('uncertainty_shown')) < 4]


def key_moment_shot_issues(direction, beats, shots):
    """Each key moment's significance reaches the picture: at least one of its shots says how the picture carries it
    (a face, a contrast, a map, a held still; never a forced diagram)."""
    if not isinstance((direction or {}).get('subject'), dict):
        return []
    out = []
    for b in beats or []:
        if not is_key_moment(b):
            continue
        mine = [s for s in shots or [] if str(s.get('beat_id')) == str(b.get('id'))]
        if mine and not any(n_words(s.get('carries_significance')) >= 4 for s in mine):
            out.append(f'key_moment_{b.get("id")}_no_shot_says_how_the_picture_carries_it:carries_significance')
    return out


def music_beat_direction(b):
    """What a music caption is written from, per beat: its sound, experience and pace, and at a key moment what the
    moment means (the bed serves the moment; it never invents one)."""
    out = {k: (b or {}).get(k) for k in ('sound_direction', 'experience', 'pace')}
    if is_key_moment(b):
        out.update({'key_moment': b.get('key_moment'), 'matters_because': (b.get('significance') or {}).get('matters_because')})
    return out


def direction_facts(rd, video):
    """Structure of 40-plans/video-NN/direction.json (10-creative-direction.md): evidence read from measured
    references, at least two approaches that differ in how the story is told (with the range considered), the episode
    strategy, two to four audiovisual treatments with sample moments, and the decision. Presence and shape only."""
    vd = video_dir(rd, video)
    d = read_json(vd / 'direction.json')
    out = {'issues': [], 'warnings': [], 'direction_sha256': None, 'treatments_sha256': None,
           'chosen_treatment': None}
    iss, warn = out['issues'], out['warnings']
    if not d:
        iss.append('direction_missing')
        return out
    out['direction_sha256'] = canonical_sha(d)
    ev = d.get('evidence') if isinstance(d.get('evidence'), dict) else {}
    refs = [str(x).strip().upper() for x in ev.get('references') or []]
    if not refs:
        iss.append('direction_evidence_names_no_references')
    for v in refs:
        if not ref_av_path(rd, v).is_file():
            iss.append(f'direction_evidence_without_av_profile:{v}')
        cr = read_json(content_review_path(rd, v))
        if not cr:
            iss.append(f'direction_evidence_reference_without_content_review:{v}')
        elif (cr.get('story_without_exclusions') or {}).get('status') == 'too_dependent':
            warn.append(f'{v}: its story depends on material excluded from use (content review): cite how it is told '
                        '(pace, hooks, structure, picture), never its story')
    cut = {v: content_exclusions(rd, v) for v in refs}
    for o in ev.get('observations') or []:
        if not isinstance(o, dict):
            continue
        v = str(o.get('ref') or '').strip().upper()
        a, b_ = parse_span(o.get('at'))
        if a is None:
            continue
        for lo, hi, sid, kind, action in cut.get(v) or content_exclusions(rd, v):
            if a <= hi and b_ >= lo:
                if action == 'exclude' and n_words(o.get('borrows_only')) >= 6:
                    warn.append(f'{v}@{o.get("at")} is inside excluded {sid}, cited only for: {o.get("borrows_only")} '
                                '(never the excluded material itself)')
                elif action == 'exclude':
                    iss.append(f'direction_cites_excluded_material:{v}@{o.get("at")}:{sid}({kind})')
                else:
                    warn.append(f'{v}@{o.get("at")} is inside {sid}, whose visuals are restricted: borrow how it is '
                                'told, never what it shows')
    fam = niche_family_refs(rd, read_json(vd / 'length-lock.json'))
    if fam:
        borrowed = {str(x.get('ref') or '').strip().upper(): x for x in ev.get('borrowed') or [] if isinstance(x, dict)}
        for v in refs:
            if v in fam:
                continue
            b = borrowed.get(v) or {}
            if n_words(b.get('technique')) < 4 or n_words(b.get('not_taken')) < 4:
                iss.append(f'direction_evidence_{v}_is_outside_the_locked_niche:say_the_technique_borrowed_and_the_subject_'
                           'assumptions_not_taken(evidence.borrowed[{ref,technique,not_taken}])')
    obs = [o for o in ev.get('observations') or [] if isinstance(o, dict) and str(o.get('ref') or '').strip()
           and str(o.get('at') or '').strip() and n_words(o.get('what')) >= 4]
    if len(obs) < 3:
        iss.append('direction_evidence_needs_3_timed_observations')
    if not ev.get('unknowns'):
        iss.append('direction_evidence_lists_no_unknowns')
    # The subject (topic discovery): required for a direction not locked yet; a direction locked before it existed
    # keeps working, with a warning.
    lock_now = read_json(vd / 'direction-lock.json')
    ll = read_json(vd / 'length-lock.json')
    if 'subject' in d or not lock_now:
        src_p = sources_path(rd, video)
        s_iss, s_warn = subject_issues(d.get('subject'), src_p.read_text(encoding='utf-8', errors='replace')
                                       if src_p.is_file() else '',
                                       None if ll.get('mode') == 'story' else ll.get('target_length_s'), refs,
                                       locked_niche_names(rd, ll) or None,
                                       read_json(claims_path(rd, video)))
        iss += s_iss
        warn += s_warn
        for v in refs:
            iss += card_moment_issues(read_json(rd / '20-analysis' / 'cards' / f'{v}.json'), v)
    else:
        warn.append('this direction was locked before topic discovery existed (no subject research on record)')
    apps = [a for a in d.get('approaches') or [] if isinstance(a, dict)]
    ids = [str(a.get('id') or '').strip() for a in apps]
    # As many approaches as the subject genuinely allows, two at least, differing between them on three axes or more;
    # the director says what range was considered (a fixed five pushed padding, 2026-11-24 audit)
    if len(apps) < 2 or len(set(ids)) != len(ids) or '' in ids:
        iss.append('direction_needs_at_least_2_distinct_approaches')
    axes = set()
    for a in apps:
        aid = a.get('id')
        changes = [str(x).strip().lower() for x in a.get('changes') or []]
        if not changes or any(x not in APPROACH_AXES for x in changes):
            iss.append(f'approach_{aid}_changes_must_name:' + '/'.join(APPROACH_AXES))
        axes |= set(changes) & set(APPROACH_AXES)
        for k in ('pitch', 'strongest_case', 'long_form_risk'):
            if n_words(a.get(k)) < MIN_FIELD_WORDS:
                iss.append(f'approach_{aid}_missing_{k}')
    if apps and len(axes) < 3:
        iss.append('approaches_differ_on_fewer_than_3_axes')
    if apps and not any(a.get('challenges_reference_formula') is True for a in apps):
        iss.append('no_approach_challenges_the_reference_formula')
    ca = d.get('chosen_approach') if isinstance(d.get('chosen_approach'), dict) else {}
    if ca.get('id') not in ids or ca.get('runner_up') not in ids or ca.get('runner_up') == ca.get('id'):
        iss.append('chosen_approach_and_runner_up_must_be_two_listed_approaches')
    for k in ('why', 'why_not_runner_up', 'exploration'):
        if n_words(ca.get(k)) < MIN_FIELD_WORDS:
            iss.append(f'chosen_approach_missing_{k}' + (':the_range_of_ways_to_tell_it_considered_and_why_these_cover_it'
                                                         if k == 'exploration' else ''))
    strat = d.get('strategy') if isinstance(d.get('strategy'), dict) else {}
    for k in STRATEGY_KEYS:
        if n_words(strat.get(k)) < MIN_FIELD_WORDS:
            iss.append(f'strategy_missing_{k}')
    trs = [t for t in d.get('treatments') or [] if isinstance(t, dict)]
    tids = [str(t.get('id') or '').strip() for t in trs]
    out['treatments_sha256'] = canonical_sha(d.get('treatments') or [])
    if not 2 <= len(trs) <= 4 or len(set(tids)) != len(tids) or '' in tids:
        iss.append('direction_needs_2_to_4_distinct_treatments')
    themes_now = excluded_themes(rd, video)
    for t in trs:
        tid = t.get('id')
        for k in TREATMENT_KEYS:
            if n_words(t.get(k)) < MIN_FIELD_WORDS:
                iss.append(f'treatment_{tid}_missing_{k}')
        # a treatment that names what the cited references' content reviews cut is rewritten, or says why the mention
        # is not that material (content_context): never silently carried into the beat map and the pictures
        for label, ph in theme_hits(treatment_text(t), themes_now):
            if not content_context_for(d, f'treatment {tid}', label):
                iss.append(f'treatment_{tid}_names_what_a_content_review_rules_out:{label}({ph}):rewrite_it_or_'
                           'record_why_it_is_not_that(content_context)')
        samples = t.get('samples') if isinstance(t.get('samples'), dict) else {}
        for m in SAMPLE_MOMENTS:
            s = sample_of(samples, m)
            if n_words(strip_tags(s.get('narration') or '')) < MIN_SAMPLE_WORDS:
                iss.append(f'treatment_{tid}_sample_{m}_narration_under_{MIN_SAMPLE_WORDS}_words')
            if n_words(s.get('picture')) < MIN_PICTURE_WORDS:
                iss.append(f'treatment_{tid}_sample_{m}_picture_missing')
    for i in range(len(trs)):
        for j in range(i + 1, len(trs)):
            def toks(t):
                s = t.get('samples') if isinstance(t.get('samples'), dict) else {}
                return _content_tokens(' '.join(str(sample_of(s, m).get('narration') or '') for m in SAMPLE_MOMENTS))
            sim = _jaccard(toks(trs[i]), toks(trs[j]))
            if sim >= 0.6:
                warn.append(f'treatments {tids[i]} and {tids[j]} share {sim:.0%} of their sample vocabulary: '
                            'are they really different treatments, or one treatment at two intensities?')
    dec = d.get('decision') if isinstance(d.get('decision'), dict) else {}
    out['chosen_treatment'] = dec.get('treatment')
    if dec.get('treatment') not in tids:
        iss.append('decision_must_name_a_listed_treatment')
    for k in ('why', 'taken_from_others'):
        if n_words(dec.get(k)) < MIN_FIELD_WORDS:
            iss.append(f'decision_missing_{k}')
    # The value the subject was chosen for reaches the treatments: each says, in its own terms, how it delivers the
    # payoff value(s), and the decision says how the chosen one makes the payoff land (research shapes the treatments,
    # it is not copied into them).
    subj_ = d.get('subject') if isinstance(d.get('subject'), dict) else {}
    allv = {str(v.get('id')) for v in subj_.get('value_to_carry') or [] if isinstance(v, dict)}
    payv = [str(v.get('id')) for v in subj_.get('value_to_carry') or [] if isinstance(v, dict) and v.get('payoff') is True]
    if payv:
        for t in trs:
            cv = {str(x.get('value') or '').strip(): x for x in t.get('carries_values') or [] if isinstance(x, dict)}
            unknown = [k for k in cv if k not in allv]
            if unknown:
                iss.append(f'treatment_{t.get("id")}_carries_unknown_values:' + ','.join(unknown))
            missing = [p for p in payv if n_words((cv.get(p) or {}).get('how')) < 4]
            if missing:
                iss.append(f'treatment_{t.get("id")}_does_not_say_how_it_delivers_the_payoff:' + ','.join(missing)
                           + ':carries_values[{value,how}]')
        if n_words(dec.get('carries_payoff')) < MIN_FIELD_WORDS:
            iss.append('decision_missing_carries_payoff:how_the_chosen_treatment_makes_the_payoff_land')
    # How each treatment unfolds over the whole video (the samples are its best moments, not the video): its movements,
    # each with what the viewer gets and roughly how long, and where it first delivers what the opening promises. The
    # facts (minutes before that, what the viewer gets meanwhile) are the director's to weigh: productive anticipation
    # or a wait; no time limit is set, and a long build that rewards the viewer is a choice (storytelling brief).
    ll = read_json(video_dir(rd, int(video)) / 'length-lock.json')
    target_min = float(ll.get('target_length_s') or 0) / 60
    out['promise_timing'] = {}
    sizes = {}
    for t in trs:
        tid = t.get('id')
        mv = treatment_movements(t)
        if len(mv) < 2 or any(n_words(m['what']) < MIN_FIELD_WORDS or m['minutes'] <= 0 for m in mv):
            iss.append(f'treatment_{tid}_needs_movements:how_the_whole_video_unfolds[{{what,minutes,promise}}]')
            continue
        if not any(m['promise'] for m in mv):
            iss.append(f'treatment_{tid}_never_marks_where_its_promise_is_delivered:movements[].promise')
        out['promise_timing'][str(tid)] = promise_timing(t)
        total = sum(m['minutes'] for m in mv)
        sizes[str(tid)] = round(total, 2)
        if target_min and abs(total - target_min) > 0.2 * target_min:
            warn.append(f'treatment {tid}: its movements add up to {total:g} min for a {target_min:.1f}-min video: '
                        'is this how it unfolds over the locked length?')
    # The story's own size (planning rules 6): the chosen subject's range, each treatment's own total and the length
    # once it is locked, side by side. Facts for the director: where the chosen treatment runs outside the range, one
    # of the two statements is wrong, and the decision says which (length_fit).
    sel_ = subj_.get('selection') if isinstance(subj_.get('selection'), dict) else {}
    ch_ = next((c for c in subj_.get('candidates') or [] if isinstance(c, dict)
                and str(c.get('id')) == str(sel_.get('candidate'))), {})
    nat = natural_minutes(ch_.get('runtime'))
    out['story_size'] = {'natural_minutes': list(nat) if nat else None, 'treatments_minutes': sizes,
                         'locked_minutes': round(target_min, 2) if target_min else None,
                         'length_mode': ll.get('mode') or ('story, not locked yet' if read_json(
                             length_intent_path(vd)).get('mode') == 'story' else None)}
    mine = sizes.get(str(dec.get('treatment')))
    if nat and mine and not nat[0] <= mine <= nat[1]:
        warn.append(f'the chosen treatment runs about {mine:g} min and the subject\'s own size was judged '
                    f'{nat[0]:g}-{nat[1]:g} min: one of the two is wrong; say which, and why, in decision.length_fit')
    # The chosen treatment keeps the opening's promise (how, and what the viewer gets while waiting for it), and its
    # telling is weighed against the references the length and the pace came from: a cohort shares a niche, not
    # necessarily this video's format, density or narration (storytelling brief, 2026-11-24).
    out['length_cohort'] = {k: ll.get(k) for k in ('cohort_id', 'forms_why', 'target_length_s', 'pace_wpm',
                                                   'pace_wpm_source')} if ll else None
    for k in ('promise_and_delivery', 'length_fit'):
        if n_words(dec.get(k)) < MIN_FIELD_WORDS:
            iss.append(f'decision_missing_{k}')
    iss += pacing_decision_issues(rd, video, dec, ll)
    # What the pacing comparison leaves out, as facts beside the decision (advisory, the user 2026-11-25): a measured
    # narrator of the niche it never names, and a relevant one its range cannot include for want of a measurement.
    if isinstance(dec.get('pacing'), dict) and dec['pacing']:
        left = pacing_left_out(rd, dec)
        out['pacing_left_out'] = {'not_weighed': [{k: x.get(k) for k in ('ref', 'story_form', 'narrator', 'language',
                                                                          'active_wpm', 'overall_wpm')}
                                                  for x in left['not_weighed']],
                                  'relevant_unmeasured': left['relevant_unmeasured']}
        if left['not_weighed']:
            warn.append('pacing: measured narrators of the locked niche that decision.pacing does not mention: '
                        + '; '.join(f"{x['ref']} ({str(x.get('story_form') or 'no story form on its card')[:70]}; "
                                    f"{x.get('active_wpm')} wpm while speaking, {x.get('overall_wpm')} overall"
                                    + (f"; {x['language']}" if x.get('language') else '') + ')'
                                    for x in left['not_weighed'])
                        + '. Weigh any that genuinely matches this narration (narrator and delivery, format, density, '
                          'pauses) with its reason; advisory, no count is asked for')
        if left['relevant_unmeasured']:
            warn.append('pacing: named relevant but with no measured narration (no transcript), so the range leaves '
                        'them out: ' + ','.join(left['relevant_unmeasured']))
    older_plan_advisory(rd, video, iss, warn)
    return out


def pacing_decision_issues(rd, video, dec, length_lock):
    """The narrators this narration follows, weighed (decision.pacing, PLANNING_RULES 4): each reference named with
    whether it is relevant and why (its narration and delivery, format, density and terminology, sentences, emotional
    course, natural variation, active against overall pace, pauses and comprehension); where in the relevant range this
    narration belongs (range); and, when only one reference is relevant, what that leaves uncertain. Where the niche has
    several measured narrators, more than one is weighed, and the references the locked pace came from are among them:
    a single convenient reference is a conclusion, never a default. Presence and reasons only: which reference is
    right is the director's judgement (the user, 2026-11-25)."""
    pac = dec.get('pacing') if isinstance(dec.get('pacing'), dict) else None
    if not pac:
        return ['decision_missing_pacing:the_reference_narrators_this_narration_follows_each_with_its_relevance_and_why']
    known = inventory_videos(rd)
    rows = [r for r in pac.get('references') or [] if isinstance(r, dict)]
    named = [str(r.get('ref') or '').strip().upper() for r in rows]
    out = []
    unknown = sorted({v for v in named if v not in known})
    if unknown:
        out.append('decision_pacing_reference_not_analysed:' + ','.join(unknown))
    thin = [v for v, r in zip(named, rows) if n_words(r.get('why')) < MIN_FIELD_WORDS]
    if thin:
        out.append('decision_pacing_reference_needs_why:' + ','.join(thin) + ':narration_format_density_terminology_'
                   'sentences_emotion_variation_active_and_overall_pace_pauses_comprehension')
    relevant = [v for v, r in zip(named, rows) if r.get('relevant') is True and v in known]
    if not relevant:
        out.append('decision_pacing_names_no_relevant_reference')
    elif len(relevant) == 1 and n_words(pac.get('uncertainty')) < MIN_FIELD_WORDS:
        out.append(f'decision_pacing_rests_on_one_reference_without_its_uncertainty:{relevant[0]}')
    if n_words(pac.get('range')) < MIN_FIELD_WORDS:
        out.append('decision_pacing_missing_range:where_in_the_relevant_narrators_range_this_narration_belongs_and_why')
    measured = pacing_pool(rd, known)
    if len(measured) >= 2 and len(set(named) & set(known)) < 2:
        out.append('decision_pacing_weighs_one_reference_of_several:weigh_the_other_measured_narrators_too')
    locked = [str(x).upper() for x in (length_lock or {}).get('reference_ids') or []]
    missing = [v for v in locked if v not in named]
    if locked and (length_lock or {}).get('pace_wpm_source') == 'computed_from_refs' and missing:
        out.append('decision_pacing_does_not_weigh_the_locked_pace_references:' + ','.join(missing))
    return out


# ---------------------------------------------------------------- what a direction change touches
# The direction lock carries a production revision. A change that alters what production must do (another treatment
# chosen, the chosen treatment's narrator, visual language, sound..., the strategy's progression, another approach)
# raises the revision and marks the artifacts that field feeds (FIELD_EFFECTS). Each marked artifact must then be
# really updated (its content changes and its own checks apply: a script edit beyond a trim still gets a fresh read)
# or explicitly reapproved (`direction-reapprove`, with a reason, on record) before a stage that uses it continues.
# Evidence, alternatives, reasons and samples feed nothing: no new revision, nothing to redo, no new read.
TRACKED_FILES = ('beat-map', 'script', 'shot-plan', 'style-bible')
# 'voice' is the episode's narrator choice (60-voice/video-NN/voice-lock.json): a narrator change asks whether the
# chosen voice and its settings still fit, exactly as it asks of the recorded parts.
MEDIA_ARTIFACTS = ('voice', 'narration', 'stills', 'music', 'edit')
ALL_ARTIFACTS = TRACKED_FILES + MEDIA_ARTIFACTS
FIELD_EFFECTS = {
    'decision.treatment': ALL_ARTIFACTS,
    'chosen_approach.id': ('beat-map', 'script', 'shot-plan', 'edit'),
    'strategy.viewer_experience': ('beat-map', 'script'),
    'strategy.progression': ('beat-map', 'script', 'shot-plan', 'edit'),
    'strategy.facts_as_experience': ('beat-map', 'script'),
    'strategy.picture_contribution': ('shot-plan', 'style-bible', 'stills'),
    'strategy.sound_and_breath': ('beat-map', 'music', 'edit'),
    'treatment.narrator': ('beat-map', 'script', 'voice', 'narration'),
    'treatment.writing_voice': ('script',),
    'treatment.structure_and_pace': ('beat-map', 'script', 'shot-plan', 'edit'),
    'treatment.visual_language': ('shot-plan', 'style-bible', 'stills', 'edit'),
    'treatment.sound': ('beat-map', 'music', 'edit'),
    'treatment.audiovisual_relationship': ('beat-map', 'shot-plan', 'edit'),
    'treatment.emotional_course': ('beat-map', 'script'),
    'treatment.carries_values': ('beat-map', 'script'),     # how the chosen treatment delivers the payoff
    'treatment.movements': ('beat-map', 'script', 'shot-plan'),   # how the whole video unfolds: its structure
    # Another subject is another film. A new angle on the same subject (the chosen candidate's own description) is
    # another story: the plan files follow it, and the media follow the plan (a still its shot's changed prompt, a
    # recorded part its changed lines). A researched value that changes reaches only the beats that carry it, their
    # lines and their shots (VALUE_KEY, scoped by direction-lock: value_change_scope). The research behind the choice,
    # the other candidates and the reasons feed nothing; a corrected source or claim is re-checked where it is used
    # (research_changes), never rebuilt.
    'subject.selection.candidate': ALL_ARTIFACTS,
    'subject.chosen': ('beat-map', 'script', 'shot-plan'),
    'subject.value_to_carry': ('beat-map', 'script', 'shot-plan'),   # a lock from before values were hashed one by one
}
NO_EFFECT = ('evidence', 'approaches', 'other_treatments', 'decision.reasons', 'chosen_approach.why',
             'chosen_approach.runner_up', 'chosen_approach.why_not_runner_up', 'chosen_approach.exploration',
             'strategy.why_this_idea',
             'strategy.fits_and_forced', 'strategy.distinct_from_references', 'treatment.name',
             'treatment.evidence_used', 'treatment.departures', 'treatment.risks', 'treatment.samples',
             'subject.scope', 'subject.audience_value', 'subject.from_references', 'subject.candidates',
             'subject.chosen.research', 'subject.other_candidates', 'subject.selection.reasons',
             'subject.runtime_decision', 'subject.dropped')
TREATMENT_REREAD_BELOW = 0.7   # under this share of its blind read's vocabulary, the chosen treatment is a new one


def field_effects(key):
    """The artifacts a change to this part of direction.json must be followed by; a part this table doesn't know is
    assumed to matter for all of them."""
    if key.startswith(VALUE_KEY):
        return ('beat-map', 'script', 'shot-plan')        # scoped to the parts that carry it (direction-lock)
    if key in FIELD_EFFECTS:
        return FIELD_EFFECTS[key]
    if key in NO_EFFECT or key.startswith('other.'):
        return ()
    return ALL_ARTIFACTS


def artifact_path(rd, video, name):
    n = int(video)
    vis, edit = rd / '60-visuals' / f'video-{n:02d}', rd / '70-edit' / f'video-{n:02d}'
    return {'beat-map': video_dir(rd, n) / 'beat-map.json', 'script': video_dir(rd, n) / 'script.json',
            'shot-plan': vis / 'shot-plan.json', 'style-bible': vis / 'style-bible.md',
            'voice': rd / '60-voice' / f'video-{n:02d}' / 'voice-lock.json',
            'narration': rd / '50-audio' / f'video-{n:02d}' / 'manifest.json',
            'stills': vis / 'stills-provenance.json', 'music': edit / 'music-provenance.json',
            'edit': edit / 'edit-plan.json'}[name]


def artifact_sha(rd, video, name):
    """Content version of a tracked file: JSON by its canonical content, text by its words, so re-saving or
    reformatting without changing anything is not an update. None when the file doesn't exist."""
    p = artifact_path(rd, video, name)
    if not p.is_file():
        return None
    if p.suffix == '.json':
        d = read_json(p)
        return canonical_sha(d) if d else None
    return hashlib.sha256(' '.join(p.read_text(encoding='utf-8', errors='replace').split()).encode('utf-8')).hexdigest()


def direction_sections(d):
    """One hash per part of direction.json (each field of the chosen approach, the strategy and the chosen
    treatment on its own), so a revision can tell exactly what changed."""
    trs = {str(t.get('id')): t for t in d.get('treatments') or [] if isinstance(t, dict)}
    dec = d.get('decision') if isinstance(d.get('decision'), dict) else {}
    chosen = str(dec.get('treatment'))
    out = {'evidence': canonical_sha(d.get('evidence')), 'approaches': canonical_sha(d.get('approaches')),
           'other_treatments': canonical_sha({k: v for k, v in trs.items() if k != chosen}),
           'decision.treatment': canonical_sha(chosen),
           'decision.reasons': canonical_sha({k: v for k, v in dec.items() if k != 'treatment'})}
    for group, part in (('chosen_approach', d.get('chosen_approach')), ('strategy', d.get('strategy')),
                        ('treatment', trs.get(chosen))):
        for k, v in (part if isinstance(part, dict) else {}).items():
            if not (group == 'treatment' and k == 'id'):
                out[f'{group}.{k}'] = canonical_sha(v)
    subj = d.get('subject') if isinstance(d.get('subject'), dict) else None
    if subj is not None:
        sel = subj.get('selection') if isinstance(subj.get('selection'), dict) else {}
        out['subject.selection.candidate'] = canonical_sha(sel.get('candidate'))
        out['subject.selection.reasons'] = canonical_sha({k: v for k, v in sel.items() if k != 'candidate'})
        cands = {str(c.get('id')): c for c in subj.get('candidates') or [] if isinstance(c, dict)}
        ch = cands.get(str(sel.get('candidate'))) or {}
        out['subject.chosen'] = canonical_sha({k: ch.get(k) for k in CHOSEN_CORE_KEYS})
        out['subject.chosen.research'] = canonical_sha({k: v for k, v in ch.items() if k not in CHOSEN_CORE_KEYS})
        out['subject.other_candidates'] = canonical_sha({k: v for k, v in cands.items() if k != str(sel.get('candidate'))})
        for v in subj.get('value_to_carry') or []:
            if isinstance(v, dict):
                out[VALUE_KEY + str(v.get('id'))] = canonical_sha(v)
        for k, v in subj.items():
            if k not in ('selection', 'candidates', 'value_to_carry'):
                out['subject.' + k] = canonical_sha(v)
    for k, v in d.items():
        if k not in ('evidence', 'approaches', 'treatments', 'decision', 'chosen_approach', 'strategy', 'subject'):
            out['other.' + k] = canonical_sha(v)
    return out


def treatment_text(t):
    """A treatment's words, as a reader of it sees them: its fields and its sample moments."""
    t = t if isinstance(t, dict) else {}
    s = t.get('samples') if isinstance(t.get('samples'), dict) else {}
    return ' '.join([str(t.get(k) or '') for k in TREATMENT_KEYS] +
                    [str(sample_of(s, m).get(x) or '') for m in SAMPLE_MOMENTS for x in ('narration', 'picture')] +
                    [str(m.get('what') or '') for m in treatment_movements(t)])


def treatment_movements(t):
    """A treatment's movements, in order: [{what, minutes, promise}] (what the viewer gets in each, roughly how long,
    and whether it delivers what the opening promises). Malformed entries are dropped; the check names them."""
    out = []
    for m in (t or {}).get('movements') or []:
        if not isinstance(m, dict):
            continue
        try:
            mins = float(m.get('minutes'))
        except (TypeError, ValueError):
            mins = 0.0
        out.append({'what': str(m.get('what') or '').strip(), 'minutes': mins, 'promise': m.get('promise') is True})
    return out


def promise_timing(t):
    """Facts for the director, never a verdict: how long a treatment's movements run before the first one that
    delivers what the opening promises, and what the viewer gets in the movements before it."""
    mv = treatment_movements(t)
    total = sum(m['minutes'] for m in mv)
    before, mins = [], 0.0
    for m in mv:
        if m['promise']:
            return {'minutes_before': round(mins, 1), 'share_before': round(mins / total, 2) if total else None,
                    'total_minutes': round(total, 1), 'before': before}
        before.append(m['what'])
        mins += m['minutes']
    return {'minutes_before': None, 'share_before': None, 'total_minutes': round(total, 1), 'before': before}


def chosen_treatment_of(d):
    dec = d.get('decision') if isinstance(d.get('decision'), dict) else {}
    return next((t for t in d.get('treatments') or [] if isinstance(t, dict)
                 and str(t.get('id')) == str(dec.get('treatment'))), {})


def media_present(rd, video, name):
    p = artifact_path(rd, video, name)
    return p.is_file() and bool(read_json(p))


def _pkey(path):
    """One spelling per file, whichever tool wrote the path (CapCut writes C:/..., Python C:\\...)."""
    return os.path.normcase(str(Path(str(path)).expanduser().resolve()))


def required_rev(lock, artifact):
    """The production revision that last affected this artifact (None: no direction change has touched it)."""
    return ((lock.get('required') or {}).get(artifact) or {}).get('rev')


def reapproved_for(lock, artifact):
    """The explicit reapproval of this artifact that still applies: given for the revision that last touched it, or,
    for an artifact no change has touched (user-supplied stills, say), until one does."""
    ra = (lock.get('reapproved') or {}).get(artifact) or {}
    if not ra:
        return None
    req = required_rev(lock, artifact)
    return ra if req is None or ra.get('rev') == req else None


def media_current(lock, artifact, made_rev):
    """Media made under production revision made_rev still stands: no direction change has touched this kind of
    artifact since, or it was explicitly reapproved for the revision that did."""
    req = required_rev(lock, artifact)
    if not req or reapproved_for(lock, artifact):
        return True
    try:
        return int(made_rev or 0) >= req
    except (TypeError, ValueError):
        return False


def stale_files(rd, video, names=TRACKED_FILES):
    """Tracked files a meaningful direction change affected that are still exactly as they were at that change, with
    no reapproval for it: {name: issue}."""
    lock = read_json(video_dir(rd, video) / 'direction-lock.json')
    out = {}
    for name in names:
        req = (lock.get('required') or {}).get(name)
        if not req:
            continue
        cur = artifact_sha(rd, video, name)
        if isinstance(req.get('parts'), dict):
            # a change scoped to some parts (a researched value: the beats that carry it, their lines, their shots):
            # only those parts left exactly as they were are waiting; the rest of the file is free
            waiting = parts_still_waiting(rd, video, name, req['parts']) if cur is not None else []
            ra = reapproved_for(lock, name)
            if waiting and not (ra and ra.get('sha256') == cur):
                out[name] = f"{name.replace('-', '_')}_made_for_an_earlier_direction:" + ','.join(waiting)
            continue
        if cur is None or cur != req.get('baseline'):
            continue                         # absent, or changed since the direction did: its own checks apply
        ra = reapproved_for(lock, name)
        if ra and ra.get('sha256') == cur:
            continue
        out[name] = f"{name.replace('-', '_')}_made_for_an_earlier_direction"
    return out


PART_TIMING_KEYS = ('start_s', 'end_s', 'duration_s')
# Where a part sits, not what it is: a line added early renumbers every later line and shifts every later beat's line
# span without changing them (2026-11-25).
PART_PLACE_KEYS = ('id', 'line_start', 'line_end')


def part_sha(obj):
    """One beat, line or shot as content: its timing (retime-shots rewrites it) and its place (its number, the lines a
    beat spans) are not what a revision asks about. A beat's own words are compared through its lines."""
    return canonical_sha({k: v for k, v in (obj or {}).items() if k not in PART_TIMING_KEYS
                          and k not in PART_PLACE_KEYS and not str(k).startswith('planned_')})


def part_sha_v1(obj):
    """part_sha as records made before 2026-11-25 stored it (its place included): such a record is still compared as it
    was made, never read as a change."""
    return canonical_sha({k: v for k, v in (obj or {}).items()
                          if k not in PART_TIMING_KEYS and not str(k).startswith('planned_')})


def part_unchanged(stored, obj, now_sha=None):
    """A part recorded earlier is exactly as it was: its stored hash is the current part's, in either form."""
    return bool(stored) and stored in ((now_sha or part_sha(obj)), part_sha_v1(obj))


def beat_lines_text(b, lines):
    """The words of one beat's lines, in order: the beat's own content wherever its lines now sit."""
    try:
        return [str((l or {}).get('text') or '') for l in lines[int(b['line_start']) - 1:int(b['line_end'])]]
    except (KeyError, TypeError, ValueError):
        return []


def beat_content_sha(b, lines):
    """A beat as its shots were planned for: its direction and its words, not the numbers of its lines."""
    return canonical_sha({'beat': part_sha(b), 'lines': beat_lines_text(b, lines)})


def artifact_part_rows(rd, video, name):
    """A plan file part by part ({id: part}): the beats of the beat map, the lines of the script, the shots of the shot
    plan."""
    data = read_json(artifact_path(rd, video, name))
    if name == 'script':
        return {str(r.get('id') or f'L{i + 1:03d}'): r for i, r in enumerate(data.get('lines') or [])
                if isinstance(r, dict)}
    key = {'beat-map': 'beats', 'shot-plan': 'shots'}.get(name)
    return {str(r.get('id')): r for r in data.get(key) or [] if isinstance(r, dict)} if key else {}


def artifact_parts(rd, video, name):
    """A plan file part by part ({id: sha})."""
    return {k: part_sha(r) for k, r in artifact_part_rows(rd, video, name).items()}


def parts_still_waiting(rd, video, name, stored):
    """Which recorded parts ({part: sha}) are still exactly as they were: a script line by its words wherever it now
    sits (a line added above it renumbers it, it does not revise it); a beat or a shot under its own id, its place
    left out. [part ids]"""
    rows = artifact_part_rows(rd, video, name)
    if name == 'script':
        anywhere = {part_sha(r) for r in rows.values()}
        return [p for p, sha in stored.items() if sha in anywhere or (p in rows and part_sha_v1(rows[p]) == sha)]
    return [p for p, sha in stored.items() if p in rows and part_unchanged(sha, rows[p])]


def value_change_scope(rd, video, vids):
    """What a change to these researched values reaches: the beats that carry them, the lines of those beats and the
    shots of those beats, each at its current content ({artifact: {part: sha}}). Nothing else is touched."""
    vids = {str(v) for v in vids or []}
    if not vids:
        return {}
    beats = read_json(artifact_path(rd, video, 'beat-map')).get('beats') or []
    hit = [b for b in beats if isinstance(b, dict) and vids & {str(x).strip() for x in b.get('carries') or []}]
    if not hit:
        return {}
    out = {'beat-map': {str(b.get('id')): part_sha(b) for b in hit}}
    lines = read_json(artifact_path(rd, video, 'script')).get('lines') or []
    order = [str((l or {}).get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)]
    lp = artifact_parts(rd, video, 'script')
    sel = {}
    for b in hit:
        try:
            for lid in order[int(b['line_start']) - 1:int(b['line_end'])]:
                sel[lid] = lp.get(lid)
        except (KeyError, TypeError, ValueError):
            pass
    if sel:
        out['script'] = sel
    bids = {str(b.get('id')) for b in hit}
    shots = read_json(artifact_path(rd, video, 'shot-plan')).get('shots') or []
    sp = {str(s.get('id')): part_sha(s) for s in shots if isinstance(s, dict) and str(s.get('beat_id')) in bids}
    if sp:
        out['shot-plan'] = sp
    return out


def research_hashes(rd, video):
    """The research as the direction was locked on it: each ledger entry and each claim (its links to script lines
    left out: writing them is not a change of research)."""
    sp = sources_path(rd, video)
    led = ledger_entries(sp.read_text(encoding='utf-8', errors='replace') if sp.is_file() else '')
    cl = claims_index(read_json(claims_path(rd, video)))
    return {'sources': {k: v['sha256'] for k, v in led.items()},
            'claims': {k: canonical_sha({x: y for x, y in c.items() if x != 'line_refs'}) for k, c in cl.items()}}


def research_changes(rd, video, lock):
    """Sources and claims that changed or went away since the direction was locked (or last re-checked), and what
    rests on them: the claims citing a changed source, the script lines those claims are tied to, the chosen subject's
    material and the values that rest on them. A correction is re-checked where it is used, never rebuilt: only a value
    that itself changes needs a direction revision. {} when nothing changed, None for a lock made before this record."""
    was = (lock or {}).get('research')
    if not isinstance(was, dict):
        return None
    cur = research_hashes(rd, video)
    ch_s = sorted(k for k, v in (was.get('sources') or {}).items() if cur['sources'].get(k) != v)
    ch_c = sorted(k for k, v in (was.get('claims') or {}).items() if cur['claims'].get(k) != v)
    if not ch_s and not ch_c:
        return {}
    cl = claims_index(read_json(claims_path(rd, video)))
    recheck = sorted(set(ch_c) | {cid for cid, c in cl.items() if set(_ids(c.get('sources'))) & set(ch_s)})
    lines = sorted({str(r) for cid in recheck for r in (cl.get(cid) or {}).get('line_refs') or []})
    subj = read_json(video_dir(rd, video) / 'direction.json').get('subject')
    mats, vals = [], []
    if isinstance(subj, dict):
        sel = subj.get('selection') if isinstance(subj.get('selection'), dict) else {}
        ch = next((c for c in subj.get('candidates') or [] if isinstance(c, dict)
                   and str(c.get('id')) == str(sel.get('candidate'))), {})
        mats = [str(m.get('id')) for m in ch.get('strongest_material') or [] if isinstance(m, dict)
                and (set(_ids(m.get('claims'))) & set(recheck) or set(_ids(m.get('sources'))) & set(ch_s))]
        vals = [str(v.get('id')) for v in subj.get('value_to_carry') or [] if isinstance(v, dict)
                and set(_ids(v.get('rests_on'))) & set(mats)]
    return {'sources': ch_s, 'claims': ch_c, 'claims_to_recheck': recheck, 'lines': lines, 'material': mats,
            'values': vals}


def research_note(rc):
    parts = [f'sources {",".join(rc["sources"])}' if rc.get('sources') else '',
             f'claims {",".join(rc["claims"])}' if rc.get('claims') else '']
    reach = [f'claims to re-check {",".join(rc["claims_to_recheck"])}' if rc.get('claims_to_recheck') else '',
             f'their lines {",".join(rc["lines"])}' if rc.get('lines') else '',
             f'material {",".join(rc["material"])} and values {",".join(rc["values"]) or "none"}' if rc.get('material') else '']
    return ('research changed since the direction was locked (' + '; '.join(p for p in parts if p) + '): re-check ' +
            ('; '.join(r for r in reach if r) or 'where they are used') + '. Nothing is rebuilt for a correction; a '
            'value that changes is a direction revision. Then: direction-lock --research-rechecked "what you checked"')


def narration_outdated_parts(lock, manifest):
    """Recorded parts made before the latest direction change that touched the narrator (a part recorded before
    parts carried their revision counts as made before any), unless the narration was reapproved for it."""
    req = required_rev(lock, 'narration')
    if not req or reapproved_for(lock, 'narration'):
        return []
    revs = manifest.get('part_revs') or {}
    out = []
    for x in manifest.get('finished_parts') or []:
        try:
            if int(revs.get(str(x)) or 0) < req:
                out.append(x)
        except (TypeError, ValueError):
            out.append(x)
    return out


def outdated_artifacts(rd, video):
    """Every artifact the latest meaningful direction change left behind (made for an earlier direction, neither
    updated since nor reapproved): the plan files and the media made from them."""
    n = int(video)
    lock = read_json(video_dir(rd, n) / 'direction-lock.json')
    names = set(stale_files(rd, n))
    vl = read_json(artifact_path(rd, n, 'voice'))
    if vl and not media_current(lock, 'voice', vl.get('production_rev')):
        names.add('voice')
    if narration_outdated_parts(lock, read_json(artifact_path(rd, n, 'narration'))):
        names.add('narration')
    for kind, key in (('stills', 'images'), ('music', 'tracks')):
        recs = (read_json(artifact_path(rd, n, kind)).get(key) or {}).values()
        if any(not media_current(lock, kind, r.get('production_rev')) for r in recs):
            names.add(kind)
    plan = read_json(artifact_path(rd, n, 'edit'))
    if plan and not media_current(lock, 'edit', (plan.get('direction') or {}).get('production_rev')):
        names.add('edit')
    return [a for a in ALL_ARTIFACTS if a in names]


def direction_gate(rd, video):
    """The locked direction as production uses it: complete, locked, and unchanged since its lock."""
    df = direction_facts(rd, video)
    issues = list(df['issues'])
    lock = read_json(video_dir(rd, video) / 'direction-lock.json')
    if not lock:
        issues.append('direction_lock_missing')
    elif df.get('direction_sha256') and lock.get('direction_sha256') != df['direction_sha256']:
        issues.append('direction_changed_since_lock')
    return issues, lock, df


def beat_map_facts(rd, video, lines=None, target=None):
    """The beat map covers the locked length and every script line once, and every beat carries its direction:
    what the viewer should experience, and how narration, picture, sound and pace serve it (10-creative-direction.md).
    Presence only; the treatment evolves beat by beat."""
    vd = video_dir(rd, video)
    if lines is None:
        lines = read_json(vd / 'script.json').get('lines') or []
    if target is None:
        target = read_json(vd / 'length-lock.json').get('target_length_s')
    beats = read_json(vd / 'beat-map.json')
    issues = []
    themes_bm = excluded_themes(rd, video)
    if beats.get('target_length_s') != target:
        issues.append('beat_map_target_differs_from_locked_length')
    timing = beats.get('beats') or []
    if not timing:
        issues.append('beat_map_missing_beats')
    cursor_s, cursor_line = 0.0, 0
    for n, beat in enumerate(timing, 1):
        try:
            start, end = float(beat['start_s']), float(beat['end_s'])
            lstart, lend = int(beat['line_start']), int(beat['line_end'])
            if abs(start - cursor_s) > 0.5 or end <= start:
                issues.append(f'beat_{n}_time_gap_overlap_or_negative')
            if lstart != cursor_line + 1 or lend < lstart or lend > len(lines):
                issues.append(f'beat_{n}_line_coverage_gap_or_overlap')
            for key in ('narrative_job',) + BEAT_DIRECTION_KEYS:
                if not str(beat.get(key) or '').strip():
                    issues.append(f'beat_{n}_missing_{key}')
            btxt = ' '.join(str(beat.get(k) or '') for k in ('narrative_job', 'key_moment') + BEAT_DIRECTION_KEYS)
            btxt += ' ' + ' '.join(str(v) for v in (beat.get('significance') or {}).values() if isinstance(v, str))
            for label, ph in theme_hits(btxt, themes_bm):
                if not content_context_for(beats, f'beat {beat.get("id")}', label):
                    issues.append(f'beat_{beat.get("id")}_names_what_a_content_review_rules_out:{label}({ph}):rewrite_'
                                  'it_or_record_why_it_is_not_that(content_context)')
            cursor_s, cursor_line = end, lend
        except (TypeError, ValueError, KeyError):
            issues.append(f'beat_{n}_bad_structure')
    if timing and target is not None and (abs(cursor_s - target) > 1 or cursor_line != len(lines)):
        issues.append('beats_do_not_cover_all_time_and_lines')
    issues += beat_dependency_issues(timing, lines)
    issues += beat_significance_issues(timing, lines)
    return issues


def beat_dependency_issues(beats, lines):
    """`depends_on` on a beat: what the viewer must already know for it to work, each {"what", "from"} where `from`
    is an earlier beat id or line id. A beat that leans on a later one asks the viewer to understand something not
    given yet, unless it is deliberately held back: {"what", "withheld": "why the uncertainty serves the story",
    "revealed_in": a later beat or line}. Optional; checked only where written."""
    order = {str(b.get('id')): k for k, b in enumerate(beats)}
    line_beat = {}
    for k, b in enumerate(beats):
        try:
            for i in range(int(b['line_start']), int(b['line_end']) + 1):
                line_beat[str((lines[i - 1] or {}).get('id') or f'L{i:03d}') if i <= len(lines) else f'L{i:03d}'] = k
        except (KeyError, TypeError, ValueError):
            continue
    issues = []
    for k, b in enumerate(beats):
        for dep in b.get('depends_on') or []:
            if not isinstance(dep, dict) or n_words(dep.get('what')) < 2:
                issues.append(f'beat_{b.get("id")}_depends_on_needs_what')
                continue
            if dep.get('withheld'):
                if n_words(dep.get('withheld')) < 4:
                    issues.append(f'beat_{b.get("id")}_withheld_needs_why')
                rv = str(dep.get('revealed_in') or '')
                at = order.get(rv, line_beat.get(rv))
                if rv and (at is None or at < k):
                    issues.append(f'beat_{b.get("id")}_withheld_revealed_in_{rv or "nowhere"}_is_not_later')
                continue
            src = str(dep.get('from') or '')
            at = order.get(src, line_beat.get(src))
            if at is None:
                issues.append(f'beat_{b.get("id")}_depends_on_unknown_{src or "source"}')
            elif at > k:
                issues.append(f'beat_{b.get("id")}_depends_on_later_{src}:give_it_first_or_mark_it_withheld')
    return issues


def beat_significance_issues(beats, lines):
    """A key moment (`key_moment`) says what it means for the viewer inside this video, decided before the script:
    `significance` = {"matters_because": why it matters here, in the viewer's terms (what is at risk or gained, what
    question it answers, what setup it pays, what the viewer can now do or see), "reward": what the viewer gets at that
    moment}, and what the viewer must already know for it to land: its `depends_on` (given earlier, or withheld on
    purpose) or `significance.self_contained` (why it needs nothing earlier). A consequence the evidence leaves open
    stays open: "certainty": "contested" names the line that keeps it honest ("hedge"). Following what happens is not
    feeling why it matters (10 §4); significance is whatever this video's viewer came for, never manufactured stakes."""
    ids = {str((l or {}).get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)}
    issues = []
    for b in beats:
        km = b.get('key_moment')
        if km is None or km is False or not str(km).strip():
            continue
        bid = b.get('id')
        sg = b.get('significance')
        if not isinstance(sg, dict) or n_words(sg.get('matters_because')) < 5:
            issues.append(f'beat_{bid}_key_moment_needs_what_it_means:significance.matters_because')
            continue
        if n_words(sg.get('reward')) < 2:
            issues.append(f'beat_{bid}_key_moment_needs_its_reward:significance.reward')
        if not (b.get('depends_on') or []) and n_words(sg.get('self_contained')) < 4:
            issues.append(f'beat_{bid}_key_moment_needs_what_the_viewer_must_know_first:depends_on_or_self_contained')
        cert = str(sg.get('certainty') or 'established').strip().lower()
        if cert not in SIGNIFICANCE_CERTAINTIES:
            issues.append(f'beat_{bid}_significance_certainty_must_be:' + '/'.join(SIGNIFICANCE_CERTAINTIES))
        elif cert in ('contested', 'speculative') and str(sg.get('hedge') or '') not in ids:
            issues.append(f'beat_{bid}_{cert}_significance_needs_the_line_that_hedges_it:significance.hedge')
        elif cert in ('contested', 'speculative'):
            # the hedge qualifies the claim where the viewer meets it: at the moment or after it, never before it
            pos = {str((l or {}).get('id') or f'L{i + 1:03d}'): i + 1 for i, l in enumerate(lines)}
            try:
                if pos[str(sg.get('hedge'))] < int(b.get('line_start')):
                    issues.append(f'beat_{bid}_hedge_comes_before_the_moment_it_qualifies:significance.hedge')
            except (TypeError, ValueError, KeyError):
                pass
    return issues


CAPITALISED_LANGUAGES = ('en', 'fr', 'es', 'it', 'pt', 'nl', 'sv', 'no', 'da', 'pl', 'ro', 'hr', 'sq')
CALENDAR_WORDS_EN = {'january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october',
                     'november', 'december', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'}
NAME_JOINERS = {'de', 'la', 'del', 'von', 'van', 'of', 'the', 'da', 'di', 'le'}


def _sentences(text):
    return [x for x in re.split(r'(?<=[.!?:;])\s+', strip_tags(str(text or ''))) if x.strip()]


NAME_TOKEN_RX = re.compile(r"[\w'\u2019]+(?:-[\w'\u2019]+)*")
NAME_BREAK_RX = re.compile(r'[,;:()"\u201c\u201d\u2014\u2013]|\s-\s')


def _tokens(sent):
    """A sentence's words with whether punctuation separates each from the word before it."""
    out, prev = [], None
    for m in NAME_TOKEN_RX.finditer(sent):
        brk = prev is not None and bool(NAME_BREAK_RX.search(sent[prev:m.start()]))
        out.append((re.sub(r"(['\u2019]s)$", '', m.group(0)), brk))
        prev = m.end()
    return out


def script_names(lines, language='en'):
    """Each line's names as a listener meets them: runs of capitalised words (people, places, organisations, titles)
    not broken by punctuation, a sentence's first word only when the script writes that word capitalised elsewhere
    too. [(line id, [names])]."""
    mid = set()
    for row in lines:
        for sent in _sentences(row.get('text')):
            for k, (w, _) in enumerate(_tokens(sent)):
                if k and w[:1].isupper():
                    mid.add(w)
    skip = CALENDAR_WORDS_EN if str(language or 'en').lower().startswith('en') else set()
    out = []
    for row in lines:
        found = []
        for sent in _sentences(row.get('text')):
            toks = _tokens(sent)
            cur = []

            def flush():
                while cur and cur[-1].lower() in NAME_JOINERS:
                    cur.pop()
                if cur:
                    found.append(' '.join(cur))
                cur.clear()
            for k, (w, brk) in enumerate(toks):
                if brk:
                    flush()
                cap = w[:1].isupper() and (k > 0 or w in mid) and w.lower() not in skip
                joiner = (cur and w.lower() in NAME_JOINERS and k + 1 < len(toks) and not toks[k + 1][1]
                          and toks[k + 1][0][:1].isupper())
                if cap or joiner:
                    cur.append(w)
                else:
                    flush()
            flush()
        out.append((str(row.get('id') or ''), found))
    return out


COMPREHENSION_KINDS = ('necessary_complexity', 'intentional_mystery', 'accidental_confusion', 'poor_sequencing',
                       'redundancy', 'missing_context')


def comprehension_signal_facts(sgl):
    """(first line id, names) of one comprehension signal: the names held at once, or the name that returns."""
    m = re.match(r'(L\d+)', str(sgl or ''))
    names = set()
    if ' names to hold arrive' in str(sgl):
        g = re.search(r'\(([^)]*)\)', sgl)
        names = {x.strip().lower() for x in (g.group(1).split(',') if g else []) if x.strip()}
    else:
        g = re.search(r'"([^"]+)" returns', str(sgl))
        names = {g.group(1).lower()} if g else set()
    return (m.group(1) if m else None), names


def comprehension_kinds(section_text):
    """{line id: kind} from the editorial review's Comprehension lines (the first kind a line names)."""
    kinds = re.compile(r'\b(' + '|'.join(COMPREHENSION_KINDS) + r')\b')
    out = {}
    for ln in str(section_text or '').splitlines():
        m = kinds.search(ln)
        if m:
            for lid in re.findall(r'\bL\d+\b', ln):
                out.setdefault(lid, m.group(1))
    return out


def key_moment_dependency_issues(signals, section_text, beats, ids):
    """A name returning after a long absence inside a key moment's lines, classified as intentional_mystery while the
    beat withholds nothing on purpose (no depends_on entry with "withheld")."""
    kinds = comprehension_kinds(section_text)
    pos = {lid: i + 1 for i, lid in enumerate(ids)}
    out = []
    for sgl in signals:
        if 'returns after' not in str(sgl):
            continue
        lid, names = comprehension_signal_facts(sgl)
        if not lid or kinds.get(lid) != 'intentional_mystery':
            continue
        for b in beats:
            if not is_key_moment(b):
                continue
            try:
                inside = int(b['line_start']) <= pos.get(lid, 0) <= int(b['line_end'])
            except (KeyError, TypeError, ValueError):
                inside = False
            if inside and not any(isinstance(d, dict) and d.get('withheld') for d in b.get('depends_on') or []):
                out.append(f'key_moment_dependency_called_a_mystery:{lid}:{",".join(sorted(names))}:'
                           f'{b.get("id")}_withholds_nothing:make_it_available_where_it_is_needed_or_mark_it_withheld')
    return out


def comprehension_unclassified(signals, section_text, line_beat):
    """(unclassified ids, grouped-without-a-cause ids) of the signals against the editorial review's Comprehension
    section. A line classifies the signals it names when it gives a kind and a reason; one line may answer several
    when they share a root: a name in common, or one beat (the user, 2026-11-24: related signals together, never a
    blanket line over unrelated ones). Signals a line groups with nothing they share are returned apart, to be answered
    each on its own line."""
    facts = {}
    for s in signals:
        lid, names = comprehension_signal_facts(s)
        if lid:
            facts.setdefault(lid, set()).update(names)

    def related(a, b):
        return bool(facts[a] & facts[b]) or (line_beat.get(a) is not None and line_beat.get(a) == line_beat.get(b))

    done, apart = set(), set()
    kinds = re.compile(r'\b(' + '|'.join(COMPREHENSION_KINDS) + r')\b')
    for ln in str(section_text or '').splitlines():
        if n_words(ln) < MIN_NOTE_WORDS or not kinds.search(ln):
            continue
        ids = [x for x in dict.fromkeys(re.findall(r'\bL\d+\b', ln)) if x in facts]
        if not ids:
            continue
        group, grew = {ids[0]}, True
        while grew:
            grew = False
            for x in ids:
                if x not in group and any(related(x, g) for g in group):
                    group.add(x)
                    grew = True
        done |= group
        apart |= set(ids) - group
    apart -= done
    return [x for x in facts if x not in done and x not in apart], sorted(apart)


def comprehension_signals(lines, beats=None, pace_wpm=150, language='en', window_s=30.0, dense_at=4, return_after_s=180.0):
    """Facts for the agent, never a gate (manual 03). Names the viewer is asked to hold (heard more than once in the
    film) arriving several at a time within about window_s of planned narration, and a name coming back after a long
    absence when it was heard only once or twice before. Whether the viewer can hold them, needs a reminder, a picture
    or another order, or whether the density is the point, is the agent's call. Languages that capitalise every noun,
    or have no capitals, are left alone."""
    if str(language or 'en').lower()[:2] not in CAPITALISED_LANGUAGES or not lines:
        return []
    pace = float(pace_wpm or 150)
    named = script_names(lines, language)
    total = {}
    for _, names in named:
        for nm in names:
            total[nm.lower()] = total.get(nm.lower(), 0) + 1
    t, first, last, count, news, returns = 0.0, set(), {}, {}, [], []
    for row, (lid, names) in zip(lines, named):
        for nm in names:
            key = nm.lower()
            if key not in first:
                first.add(key)
                if total[key] > 1:
                    news.append((t, lid, nm))
            elif t - last[key] > return_after_s and count[key] <= 2:
                returns.append((lid, nm, round((t - last[key]) / 60, 1)))
            last[key] = t
            count[key] = count.get(key, 0) + 1
        t += len(strip_tags(str(row.get('text') or '')).split()) * 60.0 / pace + 0.6
    out, i = [], 0
    while i < len(news):
        j = i
        while j + 1 < len(news) and news[j + 1][0] - news[i][0] <= window_s:
            j += 1
        if j - i + 1 >= dense_at:
            out.append(f'{news[i][1]}-{news[j][1]}: {j - i + 1} names to hold arrive in about {window_s:g} s '
                       f'({", ".join(e[2] for e in news[i:j + 1])}). Can a first-time viewer hold them, and does each '
                       'matter yet? A picture, a reminder or another order can help; keep it when the density is the point.')
            i = j + 1
        else:
            i += 1
    out += [f'{lid}: "{nm}" returns after about {mins} min, heard only once or twice before. Does the viewer still know '
            'who or what it is?' for lid, nm, mins in returns]
    return out


def _norm(text):
    return ' '.join(strip_tags(str(text or '')).lower().split())


STILL_PURPOSES = ('shots', 'treatment_preview', 'thumbnail')


def media_gate(job, kind, engine=None):
    """What every generation worker runs before it makes anything (stills: image_worker.py, openai_images_worker.py;
    music: music_worker.py), and `media-check` runs by hand. A job names its run and video. Stills for the film
    (purpose "shots", the default) each name a shot of the checked shot plan, and the prompt carries that shot's
    approved frame_prompt word for word (style words may be added around it); a music track names the beats it
    scores. Refused while the direction, the beat map or the shot plan fails its check or was made for an earlier
    direction. Two other purposes for stills: "treatment_preview" (before the lock: each item names a treatment and
    a sample moment and carries that sample's picture) and "thumbnail" (the locked, current direction only).
    Returns the records to keep and, for the agent writing the prompts or captions, the direction each item
    carries out: the beat's intent and the locked treatment's visual language or sound."""
    out = {'ok': False, 'issues': [], 'warnings': [], 'records': [], 'run': None, 'video': None,
           'untracked': False, 'direction': {}}
    iss = out['issues']
    run, video = job.get('run'), job.get('video')
    if not run or not video:
        iss.append('job_must_name_its_run_and_video')
        return out
    rd = Path(str(run)).expanduser().resolve()
    if read_json(rd / 'state.json').get('schema') != SCHEMA:
        iss.append('job_run_is_not_a_static_studio_run')
        return out
    try:
        n = int(video)
        if n < 1:
            raise ValueError
    except (TypeError, ValueError):
        iss.append('job_video_must_be_a_positive_number')
        return out
    out.update(run=str(rd), video=n)
    if kind == 'stills' and engine is not None:
        fam = engine_family(engine)
        if fam != 'flux-klein' and fam != run_image_engine(rd):
            iss.append(f'image_engine_not_chosen_for_this_run:{fam}:FLUX_3_Image_Klein_int8_is_the_default;'
                       'another_engine_needs_the_users_choice_on_record(image-engine)')
    items = job.get('images' if kind == 'stills' else 'tracks') or []
    if not items:
        iss.append('job_has_nothing_to_make')
    purpose = str(job.get('purpose') or 'shots') if kind == 'stills' else 'music'
    if kind == 'stills' and purpose not in STILL_PURPOSES:
        iss.append('job_purpose_must_be:' + '/'.join(STILL_PURPOSES))
        return out
    if purpose == 'treatment_preview':
        out['untracked'] = True
        d = read_json(video_dir(rd, n) / 'direction.json')
        iss += [x for x in direction_facts(rd, n)['issues']
                if x.startswith(('treatment_', 'direction_needs_2', 'direction_missing'))]
        trs = {str(t.get('id')): t for t in d.get('treatments') or [] if isinstance(t, dict)}
        for i, it in enumerate(items, 1):
            t, m = trs.get(str(it.get('treatment'))), str(it.get('moment') or '')
            m = next((k for k, al in SAMPLE_ALIASES.items() if m in al), m)
            if not t or m not in SAMPLE_MOMENTS:
                iss.append(f'item_{i}_must_name_a_treatment_and_a_sample_moment')
                continue
            pic = sample_of(t.get('samples'), m).get('picture')
            if not _norm(pic) or _norm(pic) not in _norm(it.get('prompt')):
                iss.append(f'item_{i}_prompt_does_not_carry_its_sample_picture')
            iss += prompt_flag_issues(f'item_{i}_prompt', prompt_flags(it.get('prompt'), excluded_themes(rd, n)),
                                      it.get('content_note'))
            out['records'].append({'purpose': 'treatment_preview', 'treatment': str(it.get('treatment')), 'moment': m})
        out['ok'] = not iss
        return out
    gate, lock, _ = direction_gate(rd, n)
    iss += gate
    rev, treatment = lock.get('production_rev', 1), lock.get('treatment')
    chosen = chosen_treatment_of(read_json(video_dir(rd, n) / 'direction.json'))
    if purpose == 'thumbnail':
        out['untracked'] = True
        themes = excluded_themes(rd, n)
        slock, s_iss = style_lock_state(rd, n)
        iss += s_iss
        for i, it in enumerate(items, 1):
            if n_words(it.get('prompt')) < 8:
                iss.append(f'item_{i}_missing_prompt')
            if slock:
                iss += style_identity_issues(f'item_{i}_thumbnail', slock, it)
            iss += prompt_flag_issues(f'item_{i}_prompt', prompt_flags(it.get('prompt'), themes), it.get('content_note'))
        out['direction'] = {'treatment': treatment, 'visual_language': chosen.get('visual_language')}
        older_plan_advisory(rd, n, iss, out['warnings'])
        out['ok'] = not iss
        return out
    iss += beat_map_facts(rd, n)
    iss += list(stale_files(rd, n, ('beat-map',)).values())
    beats = {str(b.get('id')): b for b in read_json(video_dir(rd, n) / 'beat-map.json').get('beats') or []}
    if kind == 'stills':
        sf = shot_facts(rd, n)
        # a shot of a beat that changed since the shot plan's last check waits for it; the other shots go ahead
        waiting = {sid: bid for bid, sids in (sf.get('changed_beats') or {}).items() for sid in sids}
        iss += [x for x in sf['issues'] if not (x.startswith('beat_') and '_changed_since_its_shots_were_checked:' in x)]
        out['warnings'] += sf['warnings']
        shots = {str(s.get('id')): s for s in read_json(artifact_path(rd, n, 'shot-plan')).get('shots') or []}
        out['direction'] = {'treatment': treatment, 'visual_language': chosen.get('visual_language'), 'items': []}
        themes_now = excluded_themes(rd, n)
        slock, s_iss = style_lock_state(rd, n)
        iss += s_iss
        out['direction']['style_prompt'] = slock.get('style_prompt')
        dsub = read_json(video_dir(rd, n) / 'direction.json').get('subject')
        vals = ({str(v.get('id')): v for v in dsub.get('value_to_carry') or [] if isinstance(v, dict)}
                if isinstance(dsub, dict) else {})
        for i, it in enumerate(items, 1):
            s = shots.get(str(it.get('shot_id') or it.get('id') or ''))
            if not s:
                iss.append(f'item_{i}_must_name_a_shot_of_the_shot_plan')
                continue
            if str(s.get('id')) in waiting:
                iss.append(f'item_{i}_shot_{s.get("id")}_waits:its_beat_{waiting[str(s.get("id"))]}_changed_since_the_'
                           'shot_plan_was_checked')
                continue
            if s.get('reuses'):
                iss.append(f'item_{i}_shot_{s.get("id")}_is_a_callback_of_{s.get("reuses")}_nothing_to_generate')
                continue
            fp = _norm(s.get('frame_prompt') or s.get('prompt'))
            if not fp or fp not in _norm(it.get('prompt')):
                iss.append(f'item_{i}_prompt_does_not_carry_shot_{s.get("id")}_frame_prompt')
            elif slock:
                # the locked look as an identity: its words (or a note on how this wording keeps it), additions with
                # their reason, and what the lock names as another look only as a relock or a stated departure
                iss += style_identity_issues(f'item_{i}', slock, it, fp)
            # reference images steer the picture like words: the run's own material or the style lock's references
            iss += reference_issues(f'item_{i}', rd, slock, it.get('refs'))
            # style words added around the approved frame prompt may not bring in what the prompt itself doesn't
            extra = [k for k in prompt_flags(it.get('prompt'), themes_now)
                     if k not in prompt_flags(s.get('frame_prompt') or s.get('prompt'), themes_now)]
            iss += prompt_flag_issues(f'item_{i}_style_words', extra, it.get('content_note'))
            b = beats.get(str(s.get('beat_id'))) or {}
            item = {'shot_id': str(s.get('id')), 'beat_id': str(s.get('beat_id')), 'new_thing': s.get('new_thing'),
                    'visual_intent': b.get('visual_intent'), 'experience': b.get('experience')}
            if b.get('key_moment') not in (None, False) and str(b.get('key_moment')).strip():
                item.update({'key_moment': b.get('key_moment'),
                             'matters_because': (b.get('significance') or {}).get('matters_because'),
                             'carries_significance': s.get('carries_significance')})
            carried = [vals[r] for r in (str(x).strip() for x in b.get('carries') or []) if r in vals]
            if carried:
                # the research this beat delivers, as surely as it is known: a speculative or contested value is not
                # pictured as a documented fact, an assumption not as an observation
                item['carries_values'] = [{'id': v.get('id'), 'what': v.get('what'),
                                           'why_it_matters': v.get('why_it_matters'), 'certainty': v.get('certainty'),
                                           **({'framing': v.get('hedge') or v.get('framed_as')}
                                              if v.get('hedge') or v.get('framed_as') else {})} for v in carried]
                if s.get('carries_significance') and 'carries_significance' not in item:
                    item['carries_significance'] = s.get('carries_significance')
            if s.get('uncertainty_shown'):
                item['uncertainty_shown'] = s.get('uncertainty_shown')
            out['direction']['items'].append(item)
            out['records'].append({'shot_id': str(s.get('id')), 'beat_id': str(s.get('beat_id')),
                                   **({'uncertainty_shown': s.get('uncertainty_shown')} if s.get('uncertainty_shown') else {}),
                                   **{k: it.get(k) for k in ('style_note', 'style_departure') if it.get(k)},
                                   **({'style_lock_rev': slock.get('rev')} if slock else {}),
                                   'frame_prompt_sha256': hashlib.sha256(fp.encode('utf-8')).hexdigest(),
                                   'production_rev': rev, 'treatment': treatment})
    else:
        out['direction'] = {'treatment': treatment, 'sound': chosen.get('sound'), 'items': []}
        for i, it in enumerate(items, 1):
            bs = [str(x) for x in it.get('beats') or []]
            if not bs or any(b not in beats for b in bs):
                iss.append(f'track_{i}_must_name_beats_of_the_beat_map')
            if str(it.get('video', n)) != str(n):
                iss.append(f'track_{i}_is_for_another_video')
            if n_words(it.get('caption')) < 3:
                iss.append(f'track_{i}_missing_caption')
            elif len(str(it.get('caption') or '')) > MUSIC_CAPTION_MAX:
                # the worker sends the first MUSIC_CAPTION_MAX characters: a longer caption would not be what is played
                iss.append(f'track_{i}_caption_longer_than_the_music_model_reads:{len(str(it.get("caption")))}_of_'
                           f'{MUSIC_CAPTION_MAX}_characters')
            if n_words(it.get('serves')) < MIN_FIELD_WORDS:
                # the bed carries out its beats' sound direction (and at a key moment, what the moment means): the
                # agent says how the caption does it, and that goes on record with the direction it answered
                iss.append(f'track_{i}_needs_serves:how_its_caption_carries_out_the_sound_direction_of_its_beats')
            bdir = {b: music_beat_direction(beats.get(b) or {}) for b in bs}
            out['direction']['items'].append({'beats': bdir, 'serves': it.get('serves')})
            out['records'].append({'beats': bs, 'caption_sha256': hashlib.sha256(_norm(it.get('caption')).encode('utf-8')).hexdigest(),
                                   'production_rev': rev, 'treatment': treatment, 'serves': it.get('serves'),
                                   'direction': {'sound': chosen.get('sound'), 'beats': bdir}})
    older_plan_advisory(rd, n, iss, out['warnings'])
    out['ok'] = not iss
    return out


# ---------------------------------------------------------------- the image engine and the upsampler's caption
# FLUX 3 Image Klein int8 on this PC (image_worker.py) is the run's image engine: the default and the primary one. Another
# engine (OpenAI Images) is used only on the user's explicit choice on record (image-engine); it is never a fallback when
# FLUX fails: the failure is reported and the job stops.
IMAGE_ENGINES = ('flux-klein', 'openai')
MUSIC_CAPTION_MAX = 500      # music_worker.py sends at most this many characters of a track's caption to ACE-Step


def style_lock_path(rd, video):
    return rd / '60-visuals' / f'video-{int(video):02d}' / 'style-lock.json'


def _style_words(text):
    return ' '.join(re.findall(r"[a-z0-9']+", str(text or '').lower()))


def reference_issues(tag, rd, slock, refs):
    """A still's reference images, held like its words: each is the run's own material (an earlier still, a user asset
    copied into the run) or a reference the style lock fixed, so its path and sha256 stay on the run's record."""
    iss = []
    locked = {_pkey(r.get('file')) for r in (slock or {}).get('refs') or [] if r.get('file')}
    root = _pkey(rd)
    for r in refs or []:
        p = Path(str(r)).expanduser()
        p = p if p.is_absolute() else rd / p
        k = _pkey(p)
        if not (k == root or k.startswith(root + os.sep)) and k not in locked:
            iss.append(f'{tag}_reference_outside_the_run:{p.name}:copy_it_into_the_run_or_lock_it_as_a_style_reference')
    return iss


def _phrase_in(phrase, text):
    """A phrase's words, in order, as whole words of the text."""
    p = _style_words(phrase)
    return bool(p) and f' {p} ' in f' {_style_words(text)} '


def departs_when_of(slock):
    """The phrases the director named, at lock time, as another look than the locked one."""
    d = (slock or {}).get('departs_when') or []
    return [x.strip() for x in (d if isinstance(d, list) else str(d).split(',')) if str(x).strip()]


def style_identity_issues(tag, slock, item, approved=None):
    """The locked look kept as an identity, not as identical wording (the user, 2026-11-24). The prompt carries the
    locked style words in any order, or says in style_note how its own wording keeps that look. Words added around the
    approved frame prompt (a shot's own light, framing, atmosphere or rendering) are allowed with their reason
    (style_note). What the lock names as another look (departs_when) in those added words is a style change: relock
    (style-lock --why), or say why this one picture departs on purpose (style_departure). A thumbnail (approved None)
    has no approved prompt: its whole prompt is checked for the look and for a departure."""
    iss = []
    prompt = _norm(item.get('prompt'))
    added = prompt.replace(approved, ' ', 1) if approved else prompt
    style = _style_words(slock.get('style_prompt'))
    sw = {w for w in style.split() if w not in _CAPTION_STOP}
    pw = set(_style_words(prompt).split())
    note = n_words(item.get('style_note')) >= MIN_NOTE_WORDS
    departure = n_words(item.get('style_departure')) >= MIN_FIELD_WORDS
    if sw and not sw <= pw and not note and not departure:
        iss.append(f'{tag}_does_not_carry_the_locked_style:"{style[:60]}":its_words,_or_how_this_wording_keeps_the_'
                   'look_(style_note)')
    if approved is not None:
        extra = [w for w in _style_words(added).split() if w not in sw and w not in _CAPTION_STOP]
        if extra and not note and not departure:
            iss.append(f'{tag}_adds_words_beyond_the_approved_prompt_and_the_style:"{" ".join(extra)[:60]}":say_why_'
                       '(style_note)')
    hit = [d for d in departs_when_of(slock) if _phrase_in(d, added)]
    if hit and not departure:
        iss.append(f'{tag}_reaches_for_another_look:{",".join(hit)[:80]}:relock_the_style_(style-lock_--why)_or_say_'
                   'why_this_picture_departs_(style_departure)')
    return iss


def style_lock_state(rd, video):
    """(lock, issues): the video's style lock and what makes it unusable now: missing, or locked against another
    visual language of the chosen treatment, another style bible, or style references since changed."""
    n = int(video)
    lock = read_json(style_lock_path(rd, n))
    if not lock:
        return {}, ['style_lock_missing:run_style-lock_(the_words_every_still_carries_in_the_locked_look)']
    iss = []
    vl = chosen_treatment_of(read_json(video_dir(rd, n) / 'direction.json')).get('visual_language')
    if lock.get('visual_language_sha256') != canonical_sha(vl):
        iss.append('style_lock_outdated:the_chosen_treatments_visual_language_changed:relock_with_--why')
    if lock.get('style_bible_sha256') != artifact_sha(rd, n, 'style-bible'):
        iss.append('style_lock_outdated:the_style_bible_changed:relock_with_--why')
    for r in lock.get('refs') or []:
        f = Path(str(r.get('file') or ''))
        if not f.is_file() or file_sha256(f) != r.get('sha256'):
            iss.append(f'style_lock_reference_changed_or_missing:{f.name}')
    return lock, iss


def cmd_style_lock(args):
    """The look every still of the video is made in, fixed once the direction is locked: the style words each prompt
    carries after its approved frame prompt, a palette, and style references. A change is a new revision with its
    reason, kept in history; stills made before it stay on record under the revision they were made in."""
    rd, st = run_folder(args)
    n = int(args.video)
    if not read_json(video_dir(rd, n) / 'direction-lock.json'):
        error('Lock the creative direction first: the style comes from the chosen treatment\'s visual language.')
    if n_words(args.style_prompt) < 1:
        error('Give the style words every still carries (--style-prompt), e.g. "gouache illustration, warm muted palette".')
    departs = [x.strip() for x in str(args.departs_when or '').split(',') if x.strip()]
    if not departs:
        error('Name what would be ANOTHER look than this one (--departs-when "photorealistic, flat vector, neon"): a still '
              'whose added words reach for it is a style change (a relock, or a departure said on purpose); light, '
              'framing and atmosphere of a shot stay free.')
    old = read_json(style_lock_path(rd, n))
    if old and n_words(args.why) < 4:
        error('The style is already locked: a change needs its reason (--why), and is kept as a new revision.')
    refs = []
    for x in args.ref or []:
        f = Path(x).expanduser().resolve()
        if not f.is_file():
            error('Style reference not found', str(f))
        refs.append({'file': str(f), 'sha256': file_sha256(f)})
    pal = [p.strip() for p in str(args.palette or '').split(',') if p.strip()]
    bad = [p for p in pal if not re.fullmatch(r'#?[0-9a-fA-F]{6}', p)]
    if bad:
        error('Palette colours are hex: #RRGGBB', bad)
    vl = chosen_treatment_of(read_json(video_dir(rd, n) / 'direction.json')).get('visual_language')
    rec = {'video': n, 'rev': int(old.get('rev') or 0) + 1, 'style_prompt': args.style_prompt.strip(),
           'palette': ['#' + p.lstrip('#').upper() for p in pal], 'refs': refs, 'departs_when': departs,
           'visual_language_sha256': canonical_sha(vl), 'style_bible_sha256': artifact_sha(rd, n, 'style-bible'),
           'locked_at': now(), 'why': args.why or 'first lock',
           'history': (old.get('history') or []) + ([{k: old.get(k) for k in ('rev', 'style_prompt', 'palette', 'departs_when',
                                                                               'locked_at', 'why')}]
                                                    if old else [])}
    write_json(style_lock_path(rd, n), rec)
    emit({'ok': True, 'file': str(style_lock_path(rd, n)), 'rev': rec['rev'], 'style_prompt': rec['style_prompt'],
          'departs_when': departs,
          'next': 'every stills job prompt: the shot\'s approved frame_prompt, then these style words (another wording '
                  'that keeps the look, or added words for the shot, with their reason in style_note)'})


def engine_family(engine):
    e = str(engine or '').lower()
    if e.startswith(('flux3-image-klein', 'flux-klein')):
        return 'flux-klein'
    return 'openai' if e.startswith('openai') else e


def run_image_engine(rd):
    """The engine this run's stills are made with: FLUX 3 Image Klein int8 unless the user chose another."""
    return str(read_json(rd / 'state.json').get('image_engine') or 'flux-klein')


# FLUX's prompt upsampler rewrites the approved prompt into the caption the image model draws. Measured on 16 captions of
# one run (2026-11-24): they keep 70-83% of the approved prompt's words, and nearly every person or text word they add
# stands in a negation ("no other people", "include no writing, lettering, labels"). So the caption is checked for what it
# ADDS that the approved prompt does not ask for, never for how it rephrases.
CAPTION_PEOPLE = re.compile(r"\b(man|men|woman|women|person|persons|people|crowd|crowds|soldier|soldiers|human|humans|"
                            r"someone|somebody|adult|adults|worker|workers|farmer|farmers|traveler|travelers|traveller|"
                            r"travellers|villager|villagers|pedestrian|pedestrians|passerby|passersby|onlooker|onlookers|"
                            r"spectator|spectators|merchant|merchants|sailor|sailors|"
                            # role nouns: a prompt naming riders or guards asks for people (S094, 2026-11-25);
                            # words that are often adjectives or name someone absent ("official seal", "the
                            # king's seal", "Mother's letter") are left out
                            r"rider|riders|horseman|horsemen|guard|guards|guardsman|guardsmen|officials|officer|"
                            r"officers|scribe|scribes|clerk|clerks|labourer|labourers|laborer|laborers|townspeople|"
                            r"townsfolk|conscript|conscripts|convict|convicts|recruit|recruits|warrior|warriors|"
                            r"archer|archers|spearman|spearmen|peasant|peasants|servant|servants|messenger|"
                            r"messengers|porter|porters|monk|monks|priest|priests)\b", re.I)
# Words that name a person in one of their senses only. A real FLUX caption (2026-11-24) of a scene "with no people"
# described "weathered plank faces" and hills as "overlapping blue-green silhouettes": not people. Near a person cue
# ("a lone figure standing", "her face") they are; without one they are noted for the look every still gets when it lands.
CAPTION_PEOPLE_AMBIGUOUS = re.compile(r"\b(figure|figures|silhouette|silhouettes|face|faces)\b", re.I)
# Only cues that mean a person (a lighthouse stands, boats sit, a mast leans: a second real FLUX caption, 2026-11-24).
# They only decide whether the caption is stopped for a decision before drawing; whether a person is IN the picture is
# answered by the look at the still (people question), never by a word list.
CAPTION_PERSON_CUES = re.compile(r"\b(walk|walks|walking|wear|wears|wearing|dressed|cloaked|hooded|waving|smiling|staring|"
                                 r"gazing|peering|eyes|hair|shoulders|human|humans|his|her)\b", re.I)
CAPTION_NOBODY = re.compile(r"\b(nobody|no one|no-one|unpeopled|uninhabited|deserted|empty of people)\b", re.I)
CAPTION_MINORS = re.compile(r"\b(child|children|boy|boys|girl|girls|kid|kids|baby|babies|infant|infants|toddler|"
                            r"toddlers|teen|teens|teenager|teenagers)\b", re.I)
CAPTION_TEXT = re.compile(r"\b(text|lettering|inscription|inscriptions|typography|caption|captions|headline|headlines|"
                          r"logo|logos|subtitle|subtitles)\b", re.I)
CAPTION_QUOTED = re.compile('["\u201c\u201d]([^"\u201c\u201d\n]{2,80})["\u201c\u201d]')
CAPTION_NEGATION = re.compile(r"\b(no|not|without|never|nor|none|avoid|avoiding|absent|exclude|excluding|free of)\b", re.I)
# "remove all people" in an edit caption written from a reference image rules people out (a real FLUX caption, 2026-11-24),
# but only for what closely follows the verb: "remove the fog to reveal two soldiers" still asks for soldiers
CAPTION_REMOVAL = re.compile(r"\b(remove|removed|removing|omit|omitted|omitting)\W+(?:\w+\W+){0,2}$", re.I)


def _negated(before):
    """The words before a match rule it out: a negation anywhere earlier in its clause, or a removal verb just before."""
    return bool(CAPTION_NEGATION.search(before) or CAPTION_REMOVAL.search(before))
CAPTION_KEEP_MIN = 0.5
_CAPTION_STOP = set('a an the and or of in on at to with by for from as is are was were be its it his her their this that '
                    'these those into over under near while one two three very'.split())


def _affirmed(rx, text):
    """The words of rx the text asks for: one inside a negated clause ("no other people") is not asked for."""
    found = set()
    for clause in re.split(r'[.;:!?\n]', str(text or '')):
        for m in rx.finditer(clause):
            if not _negated(clause[:m.start()]):
                found.add(m.group(0).lower())
    return found


def _ambiguous_people(text):
    """(likely-person words, unsure words) among the ambiguous ones, outside negated clauses: a person cue within five
    words makes one likely a person; without one it is unsure. Neither is a verdict: a likely one stops the caption for a
    decision (accept_caption), and both put a people question on the still for its look."""
    sure, unsure = set(), set()
    for clause in re.split(r'[.;:!?\n]', str(text or '')):
        for m in CAPTION_PEOPLE_AMBIGUOUS.finditer(clause):
            if _negated(clause[:m.start()]):
                continue
            near = ' '.join(clause[:m.start()].split()[-5:] + clause[m.end():].split()[:5])
            (sure if CAPTION_PERSON_CUES.search(near) else unsure).add(m.group(0).lower())
    return sure, unsure


def people_excluded(text):
    """The text rules people out ("no people", "nobody", "without figures"): a word that may name a person inside a
    negated clause, or a word that itself means nobody."""
    for clause in re.split(r'[.;:!?\n]', str(text or '')):
        if CAPTION_NOBODY.search(clause):
            return True
        for rx in (CAPTION_PEOPLE, CAPTION_PEOPLE_AMBIGUOUS, CAPTION_MINORS):
            if any(_negated(clause[:m.start()]) for m in rx.finditer(clause)):
                return True
    return False


def people_question(request, review):
    """The question a still's content look must answer, or None: whether anyone appears in a picture whose approved
    prompt asks for no one, and which caption words to look at (hints). Asked when the prompt rules people out, or
    when the caption has words that may name a person the prompt does not ask for."""
    hints = sorted(set((review or {}).get('people_hints') or []))
    excl = people_excluded(request)
    if not hints and not excl:
        return None
    return {'prompt_excludes_people': excl, 'hints': hints}


def _caption_words(text):
    return {w for w in re.findall(r"[a-z][a-z'-]+", str(text or '').lower()) if len(w) > 2 and w not in _CAPTION_STOP}


def caption_review_with(themes, request, caption, content_note=None, style=None, departs=()):
    """What a caption adds to the approved prompt it was written from. issues (the caption is not drawn unless it is
    accepted for exactly this caption with a reason, accept_caption; an added child never): an excluded or restricted
    theme or a content flag (a plain one answered by the item's content note), a child, likely people where the prompt
    has none, written text where the prompt has none, a caption keeping under half of the prompt's words (another
    picture), the locked style dropped, or what the style lock names as another look. notes (drawn, and recorded): a word
    that may name a person in a picture meant to have none. people_hints: every caption word that may name a person the
    prompt does not ask for, for the look the still gets (people_question)."""
    req, cap = strip_tags(str(request or '')), strip_tags(str(caption or ''))
    iss, notes = prompt_flag_issues('caption', [k for k in prompt_flags(cap, themes) if k not in prompt_flags(req, themes)
                                                and k != 'minor_in_the_picture'], content_note), []
    hints = set()
    kids = _affirmed(CAPTION_MINORS, cap) - _affirmed(CAPTION_MINORS, req)
    if kids:
        iss.append('caption_adds_a_child:' + ','.join(sorted(kids)))
    req_sure, req_unsure = _ambiguous_people(req)
    if not _affirmed(CAPTION_PEOPLE, req) and not _affirmed(CAPTION_MINORS, req) and not req_sure:
        sure, unsure = _ambiguous_people(cap)
        ppl = _affirmed(CAPTION_PEOPLE, cap) | (sure - req_unsure)
        hints |= ppl | (unsure - req_unsure)
        if ppl:
            iss.append('caption_adds_people_the_prompt_does_not_have:' + ','.join(sorted(ppl)))
        if unsure - req_unsure:
            notes.append('caption_says_' + ','.join(sorted(unsure - req_unsure)) +
                         ':words_that_may_name_people:look_for_people_in_the_still_when_it_lands')
    if not _affirmed(CAPTION_TEXT, req):
        txt = _affirmed(CAPTION_TEXT, cap)
        if txt:
            iss.append('caption_adds_written_text:' + ','.join(sorted(txt)))
    # words in quotation marks are what the image model writes into the picture: the ones the approved prompt does not
    # give were invented by the upsampler (a real caption, 2026-11-24: "a ledger of handwritten names" became eight
    # legible invented names)
    quoted = [q.strip() for q in CAPTION_QUOTED.findall(cap)]
    new_words = [q for q in dict.fromkeys(quoted) if q and q.lower() not in req.lower()]
    if new_words:
        iss.append('caption_adds_words_to_draw:' + '|'.join(new_words[:6])[:120])
    rw, cw = _caption_words(req), _caption_words(cap)
    keep = len(rw & cw) / len(rw) if rw else 1.0
    if rw and keep < CAPTION_KEEP_MIN:
        iss.append(f'caption_keeps_{round(keep * 100)}pct_of_the_approved_prompt:another_picture')
    sw = _caption_words(style)
    if sw and _style_words(style) in _style_words(req) and len(sw & cw) / len(sw) < CAPTION_KEEP_MIN:
        iss.append('caption_drops_the_locked_style:' + ','.join(sorted(sw - cw))[:80])
    gone = [d for d in departs or () if _phrase_in(d, cap) and not _phrase_in(d, req)]
    if gone:
        iss.append('caption_reaches_for_another_look:' + ','.join(gone)[:80])
    return {'issues': iss, 'notes': notes, 'people_hints': sorted(hints)}


CAPTION_NEVER_ACCEPTED = ('caption_adds_a_child',)


def caption_acceptance(accept, caption, issues):
    """(accepted, why not) for an item's accept_caption {"sha256", "why"}: the director read THIS caption (its sha256)
    and says why what the check stopped is not what it looks like (a soldier's helmet, a hill's silhouette). Never for
    an added child."""
    if not issues:
        return True, None
    if not isinstance(accept, dict) or not accept:
        return False, 'not accepted'
    never = [x for x in issues if str(x).startswith(CAPTION_NEVER_ACCEPTED)]
    if never:
        return False, 'never accepted: ' + '; '.join(never)
    if str(accept.get('sha256') or '').lower() != hashlib.sha256(str(caption or '').encode('utf-8')).hexdigest():
        return False, 'accept_caption.sha256 is not this caption\'s (the acceptance holds for exactly the caption read)'
    if n_words(accept.get('why')) < MIN_NOTE_WORDS:
        return False, 'accept_caption.why must say what the stopped words mean in this caption'
    return True, None


def caption_issues_with(themes, request, caption, content_note=None):
    """The issues of caption_review_with: what stops a caption from being drawn."""
    return caption_review_with(themes, request, caption, content_note)['issues']


def caption_review(run, video, request, caption, content_note=None):
    """caption_review_with the themes this video's content reviews rule out and its style lock."""
    rd = Path(str(run)).expanduser().resolve()
    slock = read_json(style_lock_path(rd, int(video)))
    return caption_review_with(excluded_themes(rd, int(video)), request, caption, content_note,
                               slock.get('style_prompt'), departs_when_of(slock))


def caption_issues(run, video, request, caption, content_note=None):
    """caption_issues_with the themes this video's content reviews rule out."""
    return caption_review(run, video, request, caption, content_note)['issues']


def cmd_image_engine(args):
    """The run's image engine. FLUX 3 Image Klein int8 on this PC is the default (nothing to record); another engine only
    on the user's explicit choice, in their words, and back to FLUX the same way."""
    rd, st = run_folder(args)
    if args.engine != 'flux-klein' and n_words(args.why) < 4:
        error('An engine other than FLUX 3 Image Klein int8 is the user\'s explicit choice: give their words (--why).')
    hist = list(st.get('image_engine_history') or [])
    if st.get('image_engine'):
        hist.append({'engine': st['image_engine'], 'why': st.get('image_engine_why'), 'until': now()})
    st.update({'image_engine': args.engine, 'image_engine_why': (args.why or '').strip() or 'the default',
               'image_engine_history': hist})
    write_json(rd / 'state.json', st)
    emit({'ok': True, 'image_engine': args.engine, 'why': st['image_engine_why'],
          'note': 'FLUX 3 Image Klein int8 (image_worker.py) is the default; a failure there is reported, never answered '
                  'by another engine.'})


def record_media(run, video, kind, entries):
    """After a worker made its files: which shot (stills) or beats (music) each one belongs to, made under which
    direction revision. Read by timeline-check and release-check."""
    rd, n = Path(str(run)).expanduser().resolve(), int(video)
    p = artifact_path(rd, n, kind)
    key = 'images' if kind == 'stills' else 'tracks'
    data = read_json(p) or {'video': n}
    data.setdefault(key, {})
    for e in entries:
        rec = {**{k: v for k, v in e.items() if k != 'out'}, 'made_at': now()}
        if kind in ('stills', 'music') and Path(str(e['out'])).is_file():
            # the file exactly as the generator wrote it: a still changed afterwards (blurred, erased or painted over
            # by anything but a recorded mark) is refused by stills_facts (the user, 2026-11-23: never blur); a music
            # file replaced at the same path no longer matches its record
            rec['file_sha256'] = file_sha256(Path(str(e['out'])))
        data[key][_pkey(e['out'])] = rec
    write_json(p, data)
    return str(p)


def stills_facts(rd, video):
    """Every shot has a still made through the gate, from its current approved prompt, under the current direction
    (or the director explicitly reapproved the stills for this revision, e.g. user-supplied or drawn pictures). A
    shot that `reuses` an earlier shot (a deliberate callback) shows that shot's still."""
    n = int(video)
    lock = read_json(video_dir(rd, n) / 'direction-lock.json')
    shots = read_json(artifact_path(rd, n, 'shot-plan')).get('shots') or []
    by_id = {str(s.get('id')): s for s in shots}
    prov = read_json(artifact_path(rd, n, 'stills')).get('images') or {}
    by_shot = {}
    for path, rec in prov.items():
        if Path(path).is_file():
            by_shot.setdefault(str(rec.get('shot_id')), []).append((str(rec.get('made_at') or ''), rec, path))
    # Nothing in a still is blurred, erased or covered (the user, 2026-11-23): a blur or an erase still in force in the
    # touch-up log, or a file changed since the generator made it, is refused, and no reapproval accepts it.
    post = read_json(artifact_path(rd, n, 'shot-plan').parent / 'stills-postprocess.json').get('edits') or []
    made_last = {sid: max((x[0] for x in v), default='') for sid, v in by_shot.items()}

    def _when(t):
        try:
            return dt.datetime.fromisoformat(str(t).replace('Z', '+00:00'))
        except ValueError:
            return None

    def _in_force(e):
        # a touch-up stops applying when the generator made the still again after it: the file it changed is gone
        if not isinstance(e, dict) or e.get('superseded_at'):
            return False
        if not any((r or {}).get('mode') in ('erase', 'soften') for r in e.get('regions') or []):
            return False
        made, at = _when(made_last.get(str(e.get('shot_id')), '')), _when(e.get('at') or '')
        try:
            return not (made and at and made > at)
        except TypeError:
            return True
    blurred_src = {str(e.get('shot_id')) for e in post if _in_force(e)}
    missing, changed, older, touched, blurred, foreign = [], [], [], [], [], []
    engine_now = run_image_engine(rd)
    for s in shots:
        sid = str(s.get('id'))
        src = by_id.get(str(s.get('reuses') or sid)) or s
        recs = sorted(by_shot.get(str(src.get('id'))) or [], key=lambda x: x[0])
        if not recs:
            missing.append(sid)
            continue
        rec, rec_path = recs[-1][1], recs[-1][2]
        if rec.get('file_sha256') and file_sha256(Path(rec_path)) != rec['file_sha256']:
            touched.append(sid)
        if rec.get('engine') and engine_family(rec['engine']) not in ('flux-klein', engine_now):
            foreign.append(sid)
        if str(src.get('id')) in blurred_src:
            blurred.append(sid)
        fp = hashlib.sha256(_norm(src.get('frame_prompt') or src.get('prompt')).encode('utf-8')).hexdigest()
        if rec.get('frame_prompt_sha256') != fp:
            changed.append(sid)
        if not media_current(lock, 'stills', rec.get('production_rev')):
            older.append(sid)
    ra = reapproved_for(lock, 'stills')
    out = {'issues': [], 'warnings': [], 'shots': len(shots), 'traced': len(shots) - len(missing)}
    found = [('stills_missing_or_untraced', missing), ('stills_show_an_older_shot_prompt', changed),
             ('stills_made_for_an_earlier_direction', older)]
    if ra:
        if missing or changed or older:
            out['warnings'].append('stills accepted as they are by explicit reapproval: ' + str(ra.get('reason')))
    else:
        out['issues'] += [f'{name}:' + ','.join(ids[:15]) + ('...' if len(ids) > 15 else '') for name, ids in found if ids]
    never = [('stills_changed_after_the_generator_made_them', touched), ('stills_carry_a_blur_or_erase_touchup', blurred),
             ('stills_made_with_an_engine_the_run_did_not_choose', foreign)]
    out['issues'] += [f'{name}:' + ','.join(ids[:15]) + ('...' if len(ids) > 15 else '') for name, ids in never if ids]
    return out


def review_records(vd, kind):
    """Recorded rounds of one review kind, oldest first: (record, answers) with record['_round']."""
    out = []
    folder = vd / 'reviews'
    if not folder.is_dir():
        return out
    for p in folder.glob(f'{kind}-r*.json'):
        m = re.fullmatch(re.escape(kind) + r'-r(\d+)\.json', p.name)
        if not m:
            continue
        rec = read_json(p)
        if not rec:
            continue
        rec['_round'] = int(m.group(1))
        doc = read_json(p.with_name(f'{kind}-r{m.group(1)}-answers.json'))
        ans = doc.get('answers') or {}
        rec['_reconcile'] = doc.get('reconcile') if isinstance(doc.get('reconcile'), dict) else {}
        rec['_revision_notes'] = doc.get('revision_notes') if isinstance(doc.get('revision_notes'), dict) else {}
        out.append((rec, ans if isinstance(ans, dict) else {}))
    return sorted(out, key=lambda x: x[0]['_round'])


def expand_lines(spec, order):
    """'L005', 'L005-L009' or a list of them -> line ids in script order; None when a line is unknown."""
    out = []
    for item in (spec if isinstance(spec, list) else [spec]):
        s = str(item).strip()
        m = re.fullmatch(r'(L\d+)\s*[-–]\s*(L\d+)', s)
        if m and m.group(1) in order and m.group(2) in order:
            i, j = order.index(m.group(1)), order.index(m.group(2))
            out += order[min(i, j):max(i, j) + 1]
        elif s in order:
            out.append(s)
        else:
            return None
    return out


ANSWER_RULES = 4       # 2 (2026-11-24): a revised significance finding names its cause; 3 (2026-11-24, storytelling
                       # brief): a major finding of a later round says whether it recurs and, if so, its root cause;
                       # 4 (2026-11-26): a recurring major that is disputed carries the decision that closes it;
                       # rounds recorded before keep their rules
RECURRENCE_SCOPES = ('wording', 'order', 'structure', 'treatment', 'material', 'duration', 'dispute')
# What can stand in the way of the strongest cure of a recurring major. The last three are locks only the user can
# lift: the approved length, narration already recorded and paid for, the budget. A cure they block is the user's
# decision, put to them with the options and recorded in their own words; the work on that finding stops until then
# (2026-11-26: a slow stretch eight reads had found was closed "disputed" three times because the cut that would cure
# it fell under the length window, "a length decision the user makes", and no decision was ever asked for).
DECISION_BLOCKS = ('nothing', 'length', 'recorded_narration', 'budget', 'other')
OWNER_BLOCKS = ('length', 'recorded_narration', 'budget')


def _decision_block(dec):
    return str((dec if isinstance(dec, dict) else {}).get('blocked_by') or '').strip().lower().split(':')[0].strip()


def owner_lock_pending(ans):
    """The user's lock that stands in the way of a disputed recurring major's cure while their decision is not on
    record ('length', 'recorded_narration' or 'budget'), or None."""
    dec = (ans or {}).get('decision') if isinstance((ans or {}).get('decision'), dict) else {}
    head = _decision_block(dec)
    if head not in OWNER_BLOCKS:
        return None
    decided = str(dec.get('decided_by') or '').strip().lower() == 'user' and n_words(dec.get('user_words')) >= 3
    return None if decided else head


def decision_problem(dec):
    """Why the decision that closes a recurring major is not yet one, or None. A problem two readers found is closed by
    a decision, never by the word "disputed" alone: the cures that were weighed (two at least, each with what it would
    do and what it costs; leaving the passage as it is may be one), which was taken, what stands in the way of the
    strongest, and who decided. Whether the choice is right stays the director's or the user's judgement: this only
    makes the choice explicit and gives the user theirs."""
    dec = dec if isinstance(dec, dict) else {}
    opts = [o for o in dec.get('options') or [] if isinstance(o, dict)
            and n_words(o.get('cure')) >= 3 and n_words(o.get('cost')) >= 3]
    if len(opts) < 2:
        return ('a recurring major problem is closed by a decision: decision.options lists the cures weighed (two at '
                'least, each {"cure": what it would do, "cost": what it costs}; leaving it as it is may be one)')
    if not str(dec.get('chosen') or '').strip():
        return 'decision.chosen says which of the options was taken'
    head = _decision_block(dec)
    if head not in DECISION_BLOCKS:
        return ('decision.blocked_by says what stands in the way of the strongest cure: '
                + ' | '.join(DECISION_BLOCKS) + ' (other: say what)')
    if head == 'other' and n_words(dec.get('blocked_by')) < 3:
        return 'decision.blocked_by "other" needs to say what'
    by = str(dec.get('decided_by') or '').strip().lower()
    if by not in ('director', 'user'):
        return 'decision.decided_by is "director" or "user"'
    if head in OWNER_BLOCKS and by != 'user':
        return (f'the strongest cure is blocked by {head.replace("_", " ")}, which only the user can lift: put the '
                'options to them, stop work on this finding until they answer, and record decision.decided_by "user" '
                'with their own words (decision.user_words)')
    if by == 'user' and n_words(dec.get('user_words')) < 3:
        return 'decision.user_words carries what the user said, in their own words'
    return None


# The planning rules added on 2026-11-24 (PLANNING_RULES 2): what a NEW direction must plan. A direction approved before
# them (its lock carries no planning_rules) keeps the plan it was approved with: these checks are shown to it as
# advisories, never as re-planning (the user, 2026-11-24). Safety and content, money, asset integrity and release
# validation are never in this list: they hold for every run.
PLANNING_RULES = 6
NEW_PLANNING_RULES = re.compile(
    r'(direction_evidence_\w+?_is_outside_the_locked_niche'
    r'|chosen_approach_missing_exploration'
    r'|comprehension_signals_(not_classified|grouped_without_a_shared_cause)'
    r'|blueprint_missing_audience_knows'
    r'|subject_niche_scope_needs_'
    r'|subject_candidate_\w+?_(needs_its_payoff_assessed|payoff_)'
    r'|subject_value_to_carry_names_no_payoff_value'
    r'|subject_value_\w+?_is_the_payoff_but'
    r'|(progressive_)?payoff_value_\w+?_(is_dropped|reaches_no_key_moment|is_carried_by_one_beat)'
    r'|treatment_\w+?_does_not_say_how_it_delivers_the_payoff'
    r'|decision_missing_carries_payoff'
    r'|shot_\w+?_of_beat_\w+?_needs_uncertainty_shown'
    r'|track_\d+_needs_serves'
    r'|style_lock_missing'
    r'|pace_signals_not_examined'
    r'|\w+?_review_r\d+_key_moments_not_reconciled'
    r'|script_revised_where_it_matters)')
# The planning rules of the storytelling brief (PLANNING_RULES 3, 2026-11-24): each treatment says how the whole video
# unfolds and where it delivers what the opening promises; the decision says how the chosen one keeps that promise
# and how its telling fits the references the length and pace were taken from; a key moment's dependency is not
# called a mystery unless it is withheld on purpose. Older directions see them as advisories, except where a revision
# reaches.
PLANNING_RULES_V3 = re.compile(
    r'(treatment_\w+?_needs_movements'
    r'|treatment_\w+?_never_marks_where_its_promise_is_delivered'
    r'|decision_missing_(promise_and_delivery|length_fit)'
    r'|key_moment_dependency_called_a_mystery)')
# The pacing rules (PLANNING_RULES 4, 2026-11-25): the decision names the reference narrators this narration follows,
# each weighed with its reason (narration and delivery, format, density, terminology, sentences, emotional course,
# natural variation, active against overall pace, pauses and comprehension), says where in their range this narration
# belongs, and states its uncertainty when only one reference matches. Older directions see them as advisories.
PLANNING_RULES_V4 = re.compile(r'(decision_missing_pacing|decision_pacing_)')
# The outward look and the accountable wording (PLANNING_RULES 5, 2026-11-26, after the audit of a finished film): the
# chosen subject says what already exists on it and what this film adds, and carries the promise it will be clicked
# for (a working title and a thumbnail idea); a script that grew well past its first complete draft says what the
# added lines carry; a key moment's line that rests on a claim the research did not confirm says how its words carry
# that. Presence and accountable answers only. Older directions see them as advisories.
PLANNING_RULES_V5 = re.compile(
    r'(subject_selection_needs_coverage'
    r'|subject_selection_coverage_'
    r'|subject_selection_needs_its_promise'
    r'|subject_selection_promise_'
    r'|script_grew_\d+pct_since_its_first_complete_draft'
    r'|key_lines_on_unconfirmed_claims_need_their_wording_answered)')
# The creative pass (PLANNING_RULES 6, 2026-11-26): the chosen subject states its own size and a length the user
# asked for is weighed against it; the opening is chosen among several by fresh readers; where the picture plan or the
# mix departs from the measured habits of the film's models, the departure has its reason. Accountable answers only:
# none of them is a score or a threshold. Older directions see them as advisories.
PLANNING_RULES_V6 = re.compile(
    r'(subject_candidate_\w+?_runtime_needs_its_natural_size'
    r'|subject_natural_size_'
    r'|opening_contest_'
    r'|craft_choice_)')
PLANNING_RULES_ADDED = ((2, NEW_PLANNING_RULES), (3, PLANNING_RULES_V3), (4, PLANNING_RULES_V4), (5, PLANNING_RULES_V5),
                        (6, PLANNING_RULES_V6))


def planning_rules_of(rd, video):
    """The planning rules a video's direction is held to: its lock's stamp (1 for a lock made before the stamp
    existed), or today's for a direction not locked yet."""
    lock = read_json(video_dir(rd, int(video)) / 'direction-lock.json')
    if not lock:
        return PLANNING_RULES
    try:
        return int(lock.get('planning_rules') or 1)
    except (TypeError, ValueError):
        return 1


def migrated_rule(issue, migration, chosen_treatment=None, chosen_candidate=None):
    """The planning rule of 2026-11-24 behind this issue reaches what the older direction's substantive revisions
    changed (planning_migration): the part of direction.json it checks was revised (re-approved), or the artifact it
    checks was sent back to work (re-made). A rule about one treatment, candidate or value applies when that one was
    revised or the subject changed, never because another one was."""
    s = str(issue).split(':')[0]
    secs = {str(x) for x in (migration or {}).get('sections') or []}
    arts = {str(a) for a in (migration or {}).get('artifacts') or []}

    def sec(*keys, prefix=()):
        return any(x in keys or x.startswith(prefix) for x in secs)

    def remade(*names):
        return bool(arts & set(names))
    new_subject = sec('subject.selection.candidate')
    # the pacing rules (4) reach an older direction whose decision was revised after they existed
    if PLANNING_RULES_V4.match(s):
        return int((migration or {}).get('to') or 0) >= 4 and sec('decision.treatment', 'decision.reasons')
    # the rules of 2026-11-26 (5) reach an older direction whose subject was chosen again, or whose script was sent
    # back to work, after they existed
    if PLANNING_RULES_V5.match(s):
        if int((migration or {}).get('to') or 0) < 5:
            return False
        return bool(new_subject or sec(prefix=('subject.selection',))) if s.startswith('subject_selection_') \
            else remade('script')
    # the creative pass (6) reaches an older direction whose subject was chosen again (its own size), whose script
    # was sent back to work (its opening), or whose pictures or sound were made again (their craft choices)
    if PLANNING_RULES_V6.match(s):
        if int((migration or {}).get('to') or 0) < 6:
            return False
        if s.startswith('subject_'):
            return bool(new_subject or sec(prefix=('subject.selection', 'subject.chosen')))
        if s.startswith('opening_contest_'):
            return remade('script')
        return remade('shot-plan', 'stills', 'music', 'edit')
    # the storytelling rules (3) reach what a revision of an older direction touched
    if int((migration or {}).get('to') or 0) >= 3:
        m3 = re.match(r'treatment_(\w+?)_(?:needs_movements|never_marks_where_its_promise_is_delivered)', s)
        if m3:
            return sec('decision.treatment') or (sec(prefix=('treatment.',)) if m3.group(1) == str(chosen_treatment)
                                                 else sec('other_treatments'))
        if s.startswith('decision_missing_promise_and_delivery') or s.startswith('decision_missing_length_fit'):
            return sec('decision.treatment', 'decision.reasons')
        if s.startswith('key_moment_dependency_called_a_mystery'):
            return remade('beat-map', 'script')
    elif re.match(r'(treatment_\w+?_(needs_movements|never_marks_where)|decision_missing_(promise_and_delivery|length_fit)'
                  r'|key_moment_dependency_called_a_mystery)', s):
        return False
    m = re.fullmatch(r'(\w+?)_review_r\d+_key_moments_not_reconciled_with_the_readers_account', s)
    if m:
        return {'script': remade('script'), 'final': remade('edit')}.get(
            m.group(1), sec('decision.treatment', 'other_treatments', prefix=('treatment.',)))
    m = re.fullmatch(r'treatment_(\w+?)_does_not_say_how_it_delivers_the_payoff', s)
    if m:
        # a new choice of treatment compares them all again
        return sec('decision.treatment') or (sec(prefix=('treatment.',)) if m.group(1) == str(chosen_treatment)
                                             else sec('other_treatments'))
    m = re.match(r'subject_candidate_(\w+?)_(?:needs_its_payoff_assessed|payoff_)', s)
    if m:
        # a new choice of subject compares the candidates again
        return new_subject or (sec(prefix=('subject.chosen',)) if m.group(1) == str(chosen_candidate)
                               else sec('subject.other_candidates'))
    if s.startswith('subject_value_to_carry_names_no_payoff_value'):
        return new_subject or sec('subject.value_to_carry', prefix=(VALUE_KEY,))
    m = re.match(r'subject_value_(\w+?)_is_the_payoff_but', s)
    if m:
        return new_subject or sec('subject.value_to_carry', VALUE_KEY + m.group(1))
    m = re.match(r'(?:progressive_)?payoff_value_(\w+?)_(is_dropped|reaches_no_key_moment|is_carried_by_one_beat)', s)
    if m:
        return (new_subject or sec('subject.value_to_carry', VALUE_KEY + m.group(1))
                or (m.group(2) != 'is_dropped' and remade('beat-map', 'script')))
    for prefix, applies in (
            ('direction_evidence_', lambda: sec('evidence')),
            ('chosen_approach_missing_exploration', lambda: sec('approaches', prefix=('chosen_approach.',))),
            ('decision_missing_carries_payoff', lambda: sec(prefix=('decision.',))),
            ('subject_niche_scope_needs_', lambda: new_subject or sec('subject.scope')),
            ('blueprint_missing_audience_knows', lambda: remade('script')),
            ('comprehension_signals_', lambda: remade('script')),
            ('script_revised_where_it_matters', lambda: remade('script')),
            ('shot_', lambda: remade('shot-plan')),
            ('track_', lambda: remade('music')),
            ('style_lock_missing', lambda: remade('stills')),
            ('pace_signals_not_examined', lambda: remade('narration'))):
        if s.startswith(prefix):
            return bool(applies())
    return False


def older_plan_advisory(rd, video, issues, warnings):
    """In place: for a direction approved before PLANNING_RULES, the planning checks added since move from issues to
    warnings, said as advisories, except where a substantive revision of that direction reaches (planning_migration):
    there the current rules apply. Returns what moved."""
    have = planning_rules_of(rd, video)
    if have >= PLANNING_RULES:
        return []
    vd = video_dir(rd, int(video))
    mig = read_json(vd / 'direction-lock.json').get('planning_migration') or {}
    d = read_json(vd / 'direction.json') if mig else {}
    dec = d.get('decision') if isinstance(d.get('decision'), dict) else {}
    subj = d.get('subject') if isinstance(d.get('subject'), dict) else {}
    sel = subj.get('selection') if isinstance(subj.get('selection'), dict) else {}
    moved = []
    for version, rx in PLANNING_RULES_ADDED:
        if have >= version:
            continue          # rules the direction was approved under hold in full
        moved += [x for x in issues if rx.match(str(x)) and x not in moved
                  and not migrated_rule(x, mig, dec.get('treatment'), sel.get('candidate'))]
    if moved:
        issues[:] = [x for x in issues if x not in moved]
        warnings.extend(f'advisory (this direction was approved before planning rules it need not follow): {x}'
                        for x in moved)
    return moved



def answer_problem(kind, finding, ans, rules=ANSWER_RULES):
    """Why an answer to a finding is not yet an answer, or None. rules: the answer rules the round was recorded under."""
    ans = ans if isinstance(ans, dict) else {}
    act = str(ans.get('action') or '').strip().lower()
    if act not in REVIEW_ACTIONS:
        return 'no action (revised, kept or disputed)'
    if finding.get('severity') == 'major' and act == 'kept':
        return 'a major finding is revised or disputed, never simply kept'
    if act in ('kept', 'disputed') and n_words(ans.get('note')) < MIN_NOTE_WORDS:
        return 'needs a note saying why'
    if act == 'revised' and kind == 'script' and not ans.get('lines'):
        return 'revised needs the lines that changed'
    if act == 'revised' and kind != 'script' and n_words(ans.get('note')) < MIN_NOTE_WORDS:
        return 'revised needs a note saying what changed'
    if act == 'revised' and int(rules or 1) >= 2 and _significance_finding(finding):
        cause = str(ans.get('cause') or '').strip().lower()
        if cause.split(':')[0].strip() not in SIGNIFICANCE_CAUSES:
            return 'revised needs the cause it fixes (cause: ' + ' | '.join(SIGNIFICANCE_CAUSES) + ')'
        if cause.startswith('other') and n_words(cause) < 3:
            return 'cause "other" needs to say which cause'
    if int(rules or 1) >= 3 and finding.get('needs_recurrence'):
        rc = ans.get('recurrence') if isinstance(ans.get('recurrence'), dict) else {}
        of = str(rc.get('recurs_of') or '').strip().lower()
        if not of:
            return ('say whether this major problem recurs from an earlier round (recurrence.recurs_of: "none", or '
                    'the earlier finding, e.g. "r1:F1")')
        if of != 'none':
            if not re.fullmatch(r'r\d+:[a-z]+\d*[a-z]*', of):
                return 'recurrence.recurs_of names an earlier finding as r<round>:<id> (e.g. "r1:F1"), or "none"'
            if n_words(rc.get('root_cause')) < MIN_NOTE_WORDS:
                return 'a recurring major problem needs its root cause: what the earlier revision missed'
            scope = str(rc.get('scope') or '').strip().lower()
            if scope not in RECURRENCE_SCOPES:
                return 'recurrence.scope must be one of: ' + ' | '.join(RECURRENCE_SCOPES)
            if scope == 'wording' and act != 'disputed':
                return ('a major problem an earlier reader also found is not fixed by rewording: name the order, '
                        'structure, treatment, material or duration cause it fixes, or dispute it with the reason')
            if int(rules or 1) >= 4 and (act == 'disputed' or scope == 'dispute'):
                return decision_problem(ans.get('decision'))
    return None


def _significance_finding(finding):
    """A finding derived from a reader's account of what a development means or pays (S) or of a key moment it
    did not name (K)."""
    df = finding.get('derived_from') if isinstance(finding, dict) else None
    return isinstance(df, dict) and ('development' in df or 'key_moment' in df)


def reconcile_problems(rec, fids):
    """Key moments of a recorded read the director has not reconciled with the reader's account, or whose gap is
    not answered."""
    rc = rec.get('_reconcile') or {}
    bad = []
    for bid in rec.get('reconcile_moments') or []:
        r = rc.get(bid) if isinstance(rc.get(bid), dict) else {}
        v = str(r.get('verdict') or '').strip().lower()
        if v not in RECONCILE_VERDICTS or n_words(r.get('note')) < MIN_NOTE_WORDS:
            bad.append(bid)
        elif v == 'gap':
            cause = str(r.get('cause') or '').strip().lower()
            answered = str(r.get('answered_by') or '').strip() in fids or n_words(r.get('revision')) >= MIN_NOTE_WORDS
            if cause.split(':')[0].strip() not in SIGNIFICANCE_CAUSES or not answered:
                bad.append(bid)
    return bad


def reconcile_gaps(rec):
    rc = rec.get('_reconcile') or {}
    return [bid for bid in rec.get('reconcile_moments') or []
            if isinstance(rc.get(bid), dict) and str(rc[bid].get('verdict') or '').strip().lower() == 'gap']


HOLDS_SMALL_CHANGE = (2, 5.0, 0.005)   # lines, seconds, share of the runtime: a hold tweak after a read, not a new film
COMPREHENSION_GAP_KINDS = ('accidental_confusion', 'poor_sequencing', 'missing_context')


def script_dependencies(vd):
    """{line id: [what it carries]} for the lines a reader's verdict rests on: a key moment's lines, what it depends on
    (depends_on.from, a withheld fact's revealed_in), the line that hedges it, the lines of a beat that carries a
    researched value (the payoff marked), the lines a claim is tied to (claims.json line_refs), and the lines the
    editorial review's Comprehension section named as a gap (accidental_confusion, poor_sequencing, missing_context).
    A change there can turn what a reader understood, however few its words."""
    lines = read_json(vd / 'script.json').get('lines') or []
    ids = [str((l or {}).get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)]
    beats = read_json(vd / 'beat-map.json').get('beats') or []
    by_beat = {str(b.get('id')): b for b in beats if isinstance(b, dict)}
    out = {}

    def lines_of(b):
        try:
            return ids[int(b['line_start']) - 1:int(b['line_end'])]
        except (KeyError, TypeError, ValueError):
            return []

    def add(ls, why):
        for x in ls:
            if why not in out.setdefault(x, []):
                out[x].append(why)

    d = read_json(vd / 'direction.json')
    subj = d.get('subject') if isinstance(d.get('subject'), dict) else {}
    payoff = {str(v.get('id')) for v in subj.get('value_to_carry') or [] if isinstance(v, dict) and v.get('payoff') is True}
    for b in by_beat.values():
        bid = str(b.get('id'))
        km = b.get('key_moment')
        if km not in (None, False) and str(km).strip():
            add(lines_of(b), f'key_moment:{bid}')
            sg = b.get('significance') if isinstance(b.get('significance'), dict) else {}
            if str(sg.get('hedge') or '') in ids:
                add([str(sg['hedge'])], f'hedge_of:{bid}')
            for dep in b.get('depends_on') or []:
                for src in ((dep.get('from'), dep.get('revealed_in')) if isinstance(dep, dict) else ()):
                    s = str(src or '')
                    add(lines_of(by_beat[s]) if s in by_beat else ([s] if s in ids else []), f'setup_of:{bid}')
        for v in b.get('carries') or []:
            add(lines_of(b), f'payoff:{v}' if str(v) in payoff else f'value:{v}')
    try:
        n = int(re.sub(r'\D', '', vd.name))
    except ValueError:
        n = 0
    claims = read_json(vd.parent.parent / '30-research' / f'video-{n:02d}' / 'claims.json')
    for c in (claims.get('claims') or []) if isinstance(claims, dict) else []:
        if isinstance(c, dict):
            add([str(x) for x in c.get('line_refs') or [] if str(x) in ids], f'claim:{c.get("id")}')
    ed = vd / 'editorial-review.md'
    comp = editorial_section(ed.read_text(encoding='utf-8', errors='replace') if ed.is_file() else '', 'comprehension')
    for ln in comp.splitlines():
        if re.search(r'\b(' + '|'.join(COMPREHENSION_GAP_KINDS) + r')\b', ln):
            add([x for x in re.findall(r'\bL\d+\b', ln) if x in ids], 'comprehension_gap')
    return out


def script_revised_share(old, new):
    """The share of a script's words that changed between two snapshots ({line: text}), word by word in order."""
    import difflib
    a = [w for t in (old or {}).values() for w in strip_tags(str(t)).lower().split()]
    b = [w for t in (new or {}).values() for w in strip_tags(str(t)).lower().split()]
    if not a and not b:
        return 0.0
    same = sum(m.size for m in difflib.SequenceMatcher(None, a, b, autojunk=False).get_matching_blocks())
    return round(1.0 - same / max(len(a), len(b)), 4)


LINE_MATCHING = 2      # 2026-11-25: a script read's lines are matched to later versions by their words (a record made
                       # before keeps the number-by-number reading its answers were written under)


def align_script_lines(old, new, by=None):
    """How one version of a script became the next ({line id: text} each, in script order), its lines matched by their
    words as well as by their numbers: a line added or removed renumbers every later line without rewriting it
    (2026-11-25: a comparison by number alone made every later line look rewritten, so drafts were edited in place to
    keep the numbers). Two readings are made, line by line under the same numbers and line by line by their words;
    the one that explains the edit with fewer changed lines is kept (on a tie, the numbers, as before; by='id' asks
    for the numbers alone). A kept line with new words is 'reworded'; one whose exact words left one place and came
    back in another is 'moved' (the order is part of what a reader understood); a new one 'added'. {'by': 'id' or
    'words', 'map': {old id: new id} for every line kept, 'changed': {new id: how}, 'removed': [old ids]}."""
    import difflib
    old, new = dict(old or {}), dict(new or {})
    by_id = {'by': 'id', 'map': {k: k for k in old if k in new},
             'changed': {k: ('reworded' if k in old else 'added') for k in new if old.get(k) != new[k]},
             'removed': [k for k in old if k not in new]}
    if by == 'id':
        return by_id
    oi, ni = list(old), list(new)
    ot, nt = [' '.join(str(old[k] or '').split()) for k in oi], [' '.join(str(new[k] or '').split()) for k in ni]
    wmap, changed, gone, added = {}, {}, [], []

    def similar(a, b):
        return difflib.SequenceMatcher(None, a.lower().split(), b.lower().split(), autojunk=False).ratio()

    for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(None, ot, nt, autojunk=False).get_opcodes():
        if tag == 'equal':
            wmap.update({oi[i]: ni[j] for i, j in zip(range(i1, i2), range(j1, j2))})
            continue
        olds, news = list(range(i1, i2)), list(range(j1, j2))
        if tag == 'replace' and len(olds) == len(news):
            for i, j in zip(olds, news):                      # rewritten line for line
                wmap[oi[i]], changed[ni[j]] = ni[j], 'reworded'
            continue
        if tag == 'replace':                                  # rewritten and resized: each line to its closest successor
            last = j1 - 1
            for i in olds:
                score, j = max(((similar(ot[i], nt[j]), j) for j in news if j > last), default=(0.0, None))
                if j is not None and score >= 0.5:
                    wmap[oi[i]], changed[ni[j]], last = ni[j], 'reworded', j
        gone += [i for i in olds if oi[i] not in wmap]
        added += [j for j in news if ni[j] not in changed]
    for i in list(gone):                                      # the same words, another place: moved, not rewritten
        j = next((j for j in added if nt[j] == ot[i]), None)
        if j is not None:
            wmap[oi[i]], changed[ni[j]] = ni[j], 'moved'
            gone.remove(i)
            added.remove(j)
    changed.update({ni[j]: 'added' for j in added})
    by_words = {'by': 'words', 'map': wmap, 'changed': {k: changed[k] for k in ni if k in changed},
                'removed': [oi[i] for i in sorted(gone)]}
    cost = lambda r: len(r['changed']) + len(r['removed'])
    return by_words if cost(by_words) < cost(by_id) else by_id


def holds_changed(seen, now_holds):
    """Realised pauses changed since the last script read, counted against what that reader was shown, so a run of
    small edits adds up instead of each passing on its own: (lines added, removed, realised another way or moved by
    half a second or more; seconds moved in all, every change counted however small)."""
    changed, moved = [], 0.0
    for lid in dict.fromkeys(list(seen) + list(now_holds)):
        a, b = seen.get(lid), now_holds.get(lid)
        sa, sb = (float(a[0]) if a else 0.0), (float(b[0]) if b else 0.0)
        moved += abs(sa - sb)
        if (a is None) != (b is None) or abs(sa - sb) >= 0.5 or (a and b and a[1] != b[1]):
            changed.append(lid)
    return changed, round(moved, 2)


def key_moment_lines(vd, line_ids):
    """The changed lines that sit in a beat where a held silence shapes the film whatever its size: the opening (the
    first beat: the hook), the ending (the last beat) and any beat the beat map marks `key_moment` (a reveal, the
    climax, an emotional turn: the agents' own mark). {line: why}."""
    lines = read_json(vd / 'script.json').get('lines') or []
    index = {str(r.get('id') or f'L{i + 1:03d}'): i + 1 for i, r in enumerate(lines)}
    beats = read_json(vd / 'beat-map.json').get('beats') or []
    out = {}
    for lid in line_ids:
        k = index.get(lid)
        for bi, b in enumerate(beats):
            try:
                lo, hi = int(b['line_start']), int(b['line_end'])
            except (KeyError, TypeError, ValueError):
                continue
            if k is None or not lo <= k <= hi:
                continue
            why = ('the opening' if bi == 0 else 'the ending' if bi == len(beats) - 1 else
                   f'a key moment ({str(b.get("key_moment")).strip()})' if str(b.get('key_moment') or '').strip()
                   and b.get('key_moment') is not False else None)
            if why:
                out[lid] = f'{b.get("id") or "beat " + str(bi + 1)}: {why}'
            break
    return out


def review_state(vd, kind, current_sha, snapshot=None, holds=None):
    """Where one review kind stands for the current version: every round's findings sealed and answered,
    'revised' answers backed by real changes, a fresh read after major findings (until the round cap), and the
    last read still describing what exists now (for a script, its held silences too). Issues block; warnings are
    shown and kept for the release sheet."""
    recs = review_records(vd, kind)
    st = {'kind': kind, 'rounds': len(recs), 'issues': [], 'warnings': [], 'majors_closed_by_decision': [],
          'answers_needed': {}}
    if not recs:
        st['issues'].append(f'{kind}_review_missing')
        return st
    if kind == 'script' and holds is not None:
        seen = recs[-1][0].get('holds_snapshot')
        if seen is None:
            if holds:
                st['warnings'].append('the last script read was made before holds were shown to readers: it did not '
                                      'see the held silences')
        else:
            if snapshot is not None:
                # each hold follows its line wherever the line now sits; a hold on a removed line is a hold removed
                al = align_script_lines(recs[-1][0].get('subject_snapshot') or {}, snapshot)
                seen = {al['map'].get(k, f'{k}(removed)'): v for k, v in seen.items()}
            ch, moved = holds_changed(seen, holds)
            lim_lines, lim_s, lim_share = HOLDS_SMALL_CHANGE
            target = read_json(vd / 'length-lock.json').get('target_length_s') or 0
            keys = key_moment_lines(vd, ch)
            small = len(ch) <= lim_lines and moved <= max(lim_s, lim_share * target)
            if keys:
                # The hook, the ending and a marked key moment are read again after any real hold change there.
                st['issues'].append('holds_changed_in_a_key_moment_after_the_script_read:' + ','.join(
                    f'{lid} ({why})' for lid, why in list(keys.items())[:8]) + ('...' if len(keys) > 8 else ''))
            if (ch or moved > 0) and not small:
                st['issues'].append(f'holds_changed_after_the_script_read:{moved:g}s:' + ','.join(ch[:12])
                                    + ('...' if len(ch) > 12 else ''))
            elif moved > 0 and not keys:
                st['warnings'].append(f'held silences changed after the last read on {len(ch)} line(s), '
                                      f'{moved:g} s in all since that read (small enough to pass): '
                                      + (','.join(ch) or 'changes under half a second'))
    max_r = REVIEW_MAX_ROUNDS[kind]
    for i, (rec, ans) in enumerate(recs):
        rnd, fs = rec['_round'], rec.get('findings') or []
        if rec.get('findings_outside_reader_folder'):
            st['warnings'].append(f'{kind} review r{rnd}: its findings were recorded from a file outside the reader\'s '
                                  f'own folder ({rec.get("findings_from")}): say where they came from')
        if rec.get('reader_confined') is False:
            st['warnings'].append(f'{kind} review r{rnd} was read by {rec.get("reader_route")} (review-read confines '
                                  'the reader to its own folder)')
        if canonical_sha(fs) != rec.get('findings_sha256'):
            st['issues'].append(f'{kind}_review_r{rnd}_findings_altered')
        later = recs[i + 1][0].get('subject_snapshot') if i + 1 < len(recs) else snapshot
        old = rec.get('subject_snapshot') or {}
        # a line's planned silence is part of what was read: changing it (a finding about a silence) is a revision
        held_then = rec.get('holds_snapshot') or {}
        held_later = (recs[i + 1][0].get('holds_snapshot') if i + 1 < len(recs) else holds) or {}
        # a round read before lines were matched by their words keeps the number-by-number reading it was answered under
        al = (align_script_lines(old, later, by=None if int(rec.get('line_matching') or 1) >= LINE_MATCHING else 'id')
              if kind == 'script' and later is not None else None)
        back = {v: k for k, v in al['map'].items()} if al else {}

        def same_line(x):
            """A line a revised answer names is still as it was, its words and its hold, read both by its number in the
            revised script and by the number it had when read (an answer may use either): unchanged only when every
            reading finds it so."""
            views = []
            if x in later:
                views.append(x not in al['changed'] and back.get(x) is not None
                             and held_then.get(back[x]) == held_later.get(x))
            if x in old:
                nx = al['map'].get(x)
                views.append(nx is not None and nx not in al['changed'] and held_then.get(x) == held_later.get(nx))
            return bool(views) and all(views)
        open_ids = []
        for f in fs:
            fid = str(f.get('id'))
            a = ans.get(fid) or {}
            why_open = answer_problem(kind, f, a, rec.get('answer_rules', 1))
            if why_open:
                open_ids.append(fid)
                st['answers_needed'][f'r{rnd}:{fid}'] = why_open
                # a cure only the user can unlock is said as what it is: a stop, not one more open answer
                lock = owner_lock_pending(a) if int(rec.get('answer_rules') or 1) >= 4 else None
                if lock:
                    st['issues'].append(f'{kind}_review_r{rnd}_{fid}_waits_for_the_users_decision:'
                                        f'its_cure_is_blocked_by_{lock}')
                continue
            if kind == 'script' and str(a.get('action')).strip().lower() == 'revised' and later is not None:
                ls = expand_lines(a.get('lines'), list(dict.fromkeys(list(old) + list(later))))
                if not ls:
                    open_ids.append(fid)
                elif all(same_line(x) for x in ls):
                    st['issues'].append(f'{kind}_review_r{rnd}_revised_but_unchanged:{fid}')
        if open_ids:
            st['issues'].append(f'{kind}_review_r{rnd}_unanswered:' + ','.join(open_ids))
        # A recurring major problem whose root cause is the structure or the treatment is answered by re-planning
        # (direction-lock --revise after this read); one whose cause is the length, by a length decision the user
        # approved (length re-locked after this read). Rewording alone was refused by answer_problem.
        for fid, a in ans.items():
            rc = a.get('recurrence') if isinstance(a, dict) and isinstance(a.get('recurrence'), dict) else {}
            if str(rc.get('recurs_of') or '').strip().lower() in ('', 'none'):
                continue
            scope = str(rc.get('scope') or '').strip().lower()
            when = str(rec.get('recorded_at') or '')
            if scope in ('structure', 'treatment'):
                if str(read_json(vd / 'direction-lock.json').get('locked_at') or '') < when:
                    st['issues'].append(f'{kind}_review_r{rnd}_{fid}_recurs_with_a_{scope}_cause_but_the_direction_'
                                        'was_not_revised_after_this_read:direction-lock_--revise')
            elif scope == 'duration':
                if str(read_json(vd / 'length-lock.json').get('locked_at') or '') < when:
                    st['issues'].append(f'{kind}_review_r{rnd}_{fid}_recurs_with_a_duration_cause_but_the_length_was_'
                                        'not_decided_again_after_this_read:the_user_approves_a_length_change')
        unrec = reconcile_problems(rec, {str(f.get('id')) for f in fs})
        if unrec:
            st['issues'].append(f'{kind}_review_r{rnd}_key_moments_not_reconciled_with_the_readers_account:'
                                + ','.join(unrec))
    rec, ans = recs[-1]
    rnd = rec['_round']
    majors = ([str(f.get('id')) for f in rec.get('findings') or [] if f.get('severity') == 'major']
              + [f'reconcile:{b}' for b in reconcile_gaps(rec)])
    if majors and rnd < max_r:
        st['issues'].append(f'{kind}_review_round_{rnd + 1}_required')
    elif majors:
        st['majors_closed_by_decision'] = majors
        by_user = [m for m in majors if str((((ans.get(m) or {}) if isinstance(ans.get(m), dict) else {}).get('decision')
                                             or {}).get('decided_by') or '').strip().lower() == 'user']
        st['warnings'].append(f'{kind} review: round {rnd} still found major problems ({", ".join(majors)}); '
                              'the director closed them with the reasons in the answers'
                              + (f' (decided by the user: {", ".join(by_user)})' if by_user else ''))
    if rec.get('subject_sha256') != current_sha:
        if kind == 'script' and snapshot is not None:
            old = rec.get('subject_snapshot') or {}
            # The lines as they changed, matched by their words: a line added above another renumbers it, it does not
            # rewrite it (2026-11-25). A changed line goes by its current number, a removed one by the number it had.
            al = align_script_lines(old, snapshot)
            changed, removed = list(al['changed']), list(al['removed'])
            # A fresh read follows a revision that touches what the reader's verdict rested on, however few its
            # words; many words reworded elsewhere do not force one (the user, 2026-11-24). A line's revision note in
            # the answers file (revision_notes: {"L012": "why its meaning is unchanged"}) says the change is wording.
            notes = {k for k, v in (rec.get('_revision_notes') or {}).items() if n_words(v) >= MIN_NOTE_WORDS}
            deps = script_dependencies(vd)
            order_old = list(old)
            gone = {}                                       # a removed line: what its kept neighbours carry now
            for k in removed:
                i = order_old.index(k)
                near = [al['map'][x] for x in order_old[max(0, i - 1):i + 2] if x != k and deps.get(al['map'].get(x))]
                if near:
                    gone[k] = f'removed_beside:{near[0]}({deps[near[0]][0]})'
            weighty = ([f'{k}({deps[k][0]})' for k in changed if deps.get(k) and k not in notes]
                       + [f'{k}({gone[k]})' for k in removed if gone.get(k) and k not in notes])
            if weighty:
                st['issues'].append('script_revised_where_it_matters_since_its_last_read:'
                                    + ','.join(weighty[:8]) + ('...' if len(weighty) > 8 else '')
                                    + ':a_fresh_read_follows,_or_a_revision_note_per_line_says_its_meaning_is_unchanged')
            if changed or removed:
                share = script_revised_share(old, snapshot)
                carried = [k for k in changed if deps.get(k)] + [k for k in removed if gone.get(k)]
                kinds = [how for how in al['changed'].values() if how != 'reworded'] + ['removed'] * len(removed)
                st['warnings'].append(f'script revised since its last read: {round(100 * share)}% of its words on '
                                      f'{len(changed) + len(removed)} line(s)'
                                      + (' (matched by their words: ' + ', '.join(f'{kinds.count(x)} {x}' for x in
                                                                                  ('added', 'removed', 'moved')
                                                                                  if x in kinds) + ')'
                                         if al['by'] == 'words' else '') + '; '
                                      + (f'{len(carried)} of them carry what the reader\'s verdict rested on' if carried
                                         else 'none carries a key moment, its setup or hedge, a value, a claim or a '
                                              'comprehension gap'))
            asked = set()
            for a in ans.values():
                if isinstance(a, dict) and str(a.get('action')).strip().lower() == 'revised':
                    named = expand_lines(a.get('lines'), list(dict.fromkeys(list(old) + list(snapshot)))) or []
                    # by the revised script's numbers or by the ones the reader saw
                    asked |= set(named) | {al['map'][x] for x in named if x in al['map']}
            loose = ([(k, snapshot.get(k)) for k in changed if k not in asked and k not in notes]
                     + [(k, old.get(k)) for k in removed if k not in asked and k not in notes])
            if loose:
                total = sum(n_words(strip_tags(t)) for t in snapshot.values()) or 1
                moved = sum(n_words(strip_tags(t or '')) for _, t in loose)
                if len(loose) <= SMALL_EDIT_LINES and moved <= SMALL_EDIT_SHARE * total:
                    st['warnings'].append(f'script edited after its last read on {len(loose)} line(s) no finding '
                                          'asked about (small enough to pass): ' + ','.join(k for k, _ in loose))
                else:
                    st['issues'].append('script_changed_after_review:' + ','.join(k for k, _ in loose[:15])
                                        + ('...' if len(loose) > 15 else ''))
        else:
            # a new file gets its own read, whatever the round (command step F): after the round cap only majors are
            # closed by decision, never a file no reader has seen (audit 2026-11-23)
            st['issues'].append(f'{kind}_review_outdated')
    return st


EN_FUNCTION_WORDS = set((
    'a an the and but or so if then than that this these those it its is are was were be been being not no nor to '
    'of in on at by for with from as into onto over under about after before through you your yours we our they '
    'them their he him his she her i me my what which who whom whose when where why how there here do does did '
    'have has had will would can could may might must should just only also very all every each some any more '
    'most other such own same too now still even').split())
NUMBER_WORDS = re.compile(r"\d[\d,.]*|\b(two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|twenty|thirty|"
                          r"forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|million|billion)\b", re.I)


def writing_signals(lines, language='en'):
    """Counts the writer reads during revision (never a verdict, never shown to a cold reader): phrases repeated
    across lines, sentence shapes used again and again, runs of very short fragments, sentences too long to follow
    by ear, lines stacked with numbers, words echoing in neighbouring lines, and how sentence length varies."""
    sents = []
    for i, row in enumerate(lines):
        lid = str(row.get('id') or f'L{i + 1:03d}')
        for s in re.split(r'(?<=[.!?…])\s+', strip_tags(row.get('text') or '')):
            toks = re.findall(r"[\w']+", s.lower())
            if toks:
                sents.append((lid, s.strip(), toks))
    lengths = [len(t) for _, _, t in sents]
    out = {'sentences': len(sents),
           'sentence_words': {'mean': round(statistics.mean(lengths), 1) if lengths else None,
                              'spread': round(statistics.pstdev(lengths), 1) if lengths else None,
                              'share_under_5_words': round(sum(1 for x in lengths if x < 5) / len(lengths), 3)
                              if lengths else None},
           'questions': sum(1 for _, s, _ in sents if s.endswith('?'))}
    out['long_sentences'] = [{'line': lid, 'words': len(t)} for lid, _, t in sents if len(t) > 32][:20]
    runs, cur = [], []
    for lid, _, t in sents:
        if len(t) <= 4:
            cur.append(lid)
        else:
            if len(cur) >= 3:
                runs.append(cur)
            cur = []
    if len(cur) >= 3:
        runs.append(cur)
    out['fragment_runs'] = [{'from': r[0], 'to': r[-1], 'fragments': len(r)} for r in runs][:20]
    english = str(language or '').lower().startswith('en')
    grams = {}
    for i, row in enumerate(lines):
        lid = str(row.get('id') or f'L{i + 1:03d}')
        toks = re.findall(r"[\w']+", strip_tags(row.get('text') or '').lower())
        for n in (3, 4, 5):
            for k in range(len(toks) - n + 1):
                g = tuple(toks[k:k + n])
                if english and all(w in EN_FUNCTION_WORDS for w in g):
                    continue
                grams.setdefault(g, set()).add(lid)
    rep = sorted(((g, ls) for g, ls in grams.items() if len(ls) >= 3), key=lambda x: (-len(x[1]), -len(x[0])))
    kept = []
    for g, ls in rep:
        if any(len(k) > len(g) and ls <= kl and ' '.join(g) in ' '.join(k) for k, kl in kept):
            continue
        kept.append((g, ls))
        if len(kept) >= 15:
            break
    out['repeated_phrases'] = [{'phrase': ' '.join(g), 'lines': len(ls), 'examples': sorted(ls)[:6]} for g, ls in kept]
    if english:
        def skel(tokens):
            # Function words kept (articles aside), every run of content words one "_": the shape a listener hears.
            out_ = []
            for w in tokens:
                x = w if (w in EN_FUNCTION_WORDS and w not in ('a', 'an', 'the')) else '_'
                if not (x == '_' and out_ and out_[-1] == '_'):
                    out_.append(x)
            return ' '.join(out_)
        shapes = {}
        for lid, _, t in sents:
            if 2 <= len(t) <= 10:
                sk = skel(t)
                if sk.replace('_', '').strip():
                    shapes.setdefault(sk, []).append(lid)
        for (l1, _, t1), (l2, _, t2) in zip(sents, sents[1:]):   # two sentences used as one figure: their openings
            s1, s2 = skel(t1[:4]), skel(t2[:3])
            if s1.replace('_', '').strip() and s2.replace('_', '').strip():
                shapes.setdefault(s1 + ' | ' + s2, []).append(l1)
        out['repeated_sentence_shapes'] = [{'shape': k, 'times': len(v), 'examples': v[:6]} for k, v in
                                           sorted(shapes.items(), key=lambda x: -len(x[1])) if len(v) >= 3][:12]
        openings = {}
        for lid, _, t in sents:
            if len(t) >= 3:
                openings.setdefault(' '.join(t[:2]), []).append(lid)
        out['repeated_openings'] = [{'opening': k, 'times': len(v), 'examples': v[:6]} for k, v in
                                    sorted(openings.items(), key=lambda x: -len(x[1])) if len(v) >= 5][:12]
    out['number_dense_lines'] = [str(r.get('id') or f'L{i + 1:03d}') for i, r in enumerate(lines)
                                 if len(NUMBER_WORDS.findall(strip_tags(r.get('text') or ''))) >= 3][:30]
    echoes, ids = {}, [str(r.get('id') or f'L{i + 1:03d}') for i, r in enumerate(lines)]
    toks_by = [set(t for t in re.findall(r"[\w']+", strip_tags(r.get('text') or '').lower())
                   if len(t) >= 5 and (not english or t not in EN_FUNCTION_WORDS)) for r in lines]
    for i in range(len(lines)):
        window = toks_by[i:i + 4]
        for w in toks_by[i]:
            hits = [ids[i + k] for k, s in enumerate(window) if w in s]
            if len(hits) >= 3 and w not in echoes:
                echoes[w] = hits
    out['word_echoes'] = [{'word': w, 'lines': v} for w, v in list(echoes.items())[:15]]
    # Delivery devices a listener counts without meaning to: questions in a row, exclamations, words in capitals
    # (read as emphasis), and how often the text directs the voice. Information only: the treatment decides.
    qruns, cur = [], []
    for lid, s, _ in sents:
        if s.endswith('?'):
            cur.append(lid)
        else:
            if len(cur) >= 2:
                qruns.append(cur)
            cur = []
    if len(cur) >= 2:
        qruns.append(cur)
    out['question_runs'] = [{'from': r[0], 'to': r[-1], 'questions': len(r)} for r in qruns][:12]
    out['exclamations'] = sum(1 for _, s, _ in sents if s.endswith('!'))
    caps = [(str(r.get('id') or f'L{i + 1:03d}'), w) for i, r in enumerate(lines)
            for w in re.findall(r'\b[A-Z]{4,}\b', strip_tags(r.get('text') or ''))]
    out['capitalised_words'] = {'count': len(caps), 'examples': [f'{a}:{b}' for a, b in caps[:8]]}
    tag_lines = [(str(r.get('id') or f'L{i + 1:03d}'), m.group(0)) for i, r in enumerate(lines)
                 for m in TAG_RE.finditer(str(r.get('text') or ''))]
    spoken = sum(len(t) for _, _, t in sents) or 1
    out['delivery_tags'] = {'count': len(tag_lines), 'per_1000_words': round(1000 * len(tag_lines) / spoken, 1),
                            'pause_tags': sum(1 for _, t in tag_lines if is_pause_tag(t[1:-1])),
                            'examples': [f'{a} {b}' for a, b in tag_lines[:10]]}
    out['note'] = ('Signals for the writer, not verdicts: a repeated shape can be a deliberate refrain. Count what '
                   'the listener will hear: a device used once is style, used eight times it is a template.')
    return out


# ---------------------------------------------------------------- the film beside its models
# The audit of 2026-11-26: the finished film cut 7.5 times a minute where its five models cut 9.8 to 21.4, showed a
# picture again in 30% of its shots where they do in 0 to 6%, and kept the sound between its words within 10 dB where
# theirs moves 18 to 38. Every one of those numbers was in the run; none was ever set beside the others, so none was a
# decision. This sets them side by side while each can still be changed: the picture plan before a still is made, the
# mix before the export, the export before its release. Measurements, never verdicts: a film may differ from every
# model it has, and where it does on a habit a viewer feels, the director says why (craft-choices.json).
MODEL_MEASURES = (
    # key, what it is, digits shown, asked for its reason when the film lies outside every model
    ('pictures_per_min', 'cuts a minute (a new picture, or a return to one)', 1, True),
    ('picture_stands_s', 'how long a picture stands, median (s)', 1, False),
    ('longest_picture_s', 'the longest a picture stands (s)', 1, False),
    ('seen_again_share', 'shots that show a picture seen before (share of the shots)', 2, True),
    ('moving_time_share', 'time the picture is moving (share)', 2, False),
    ('pauses_per_min', 'pauses a minute (0.3 s or more)', 1, False),
    ('long_pauses_per_min', 'pauses of 0.8 s or more a minute', 2, False),
    ('longest_pause_s', 'the longest pause (s)', 1, False),
    ('sound_under_voice_db', 'the sound between the words: dB under the voice (median)', 0, True),
    ('sound_moves_db', 'how far that sound moves through the film (its quiet tenth to its loud tenth, dB)', 0, True))
PICTURE_MEASURES = ('pictures_per_min', 'picture_stands_s', 'longest_picture_s', 'seen_again_share', 'moving_time_share')
MIN_CRAFT_WORDS = 12          # a craft choice's reason is a sentence, as an opening that stands alone has one
# a shot that sets two things side by side: its composition says so, or its prompt names both halves
TWO_SIDED = re.compile(r'split[- ]screen|\bdiptych\b', re.I)


def model_measures(summary):
    """One measured film (an av-profile summary) as the MODEL_MEASURES it holds."""
    pic = summary.get('picture') if isinstance(summary.get('picture'), dict) else {}
    nar = summary.get('narration') if isinstance(summary.get('narration'), dict) else {}
    pp = nar.get('pause_profile') if isinstance(nar.get('pause_profile'), dict) else {}
    gap = nar.get('gap_level_rel_speech_db') if isinstance(nar.get('gap_level_rel_speech_db'), dict) else {}
    shots = pic.get('shots') or 0
    return {'pictures_per_min': pic.get('cuts_per_min'),
            'picture_stands_s': (pic.get('shot_length_s') or {}).get('median'),
            'longest_picture_s': pic.get('longest_shot_s'),
            'seen_again_share': (pic.get('same_picture_again') or 0) / shots if shots else None,
            'moving_time_share': pic.get('moving_time_share'),
            'pauses_per_min': nar.get('pauses_per_min'),
            'long_pauses_per_min': pp.get('pauses_0_8s_plus_per_min'),
            'longest_pause_s': pp.get('longest_pause_s'),
            'sound_under_voice_db': -gap['median'] if gap.get('median') is not None else None,
            'sound_moves_db': (gap['p90'] - gap['p10'] if gap.get('p10') is not None and gap.get('p90') is not None
                               else None)}


def model_refs(rd, video):
    """(the film's models, notes): the measured references its direction studied (direction.json evidence.references),
    or the ones evidence.models names among them when the director holds only some of them as models for how the film
    looks and sounds."""
    d = read_json(video_dir(rd, video) / 'direction.json')
    ev = d.get('evidence') if isinstance(d.get('evidence'), dict) else {}
    refs = list(dict.fromkeys(str(x).strip().upper() for x in ev.get('references') or [] if str(x).strip()))
    named = [str(x).strip().upper() for x in ev.get('models') or [] if str(x).strip()] \
        if isinstance(ev.get('models'), list) else []
    notes = [f'{x} is named as a model but is not among the direction\'s evidence references' for x in named
             if x not in refs]
    if named and any(x in refs for x in named):
        refs = [r for r in refs if r in named]
    return refs, notes


def craft_choices_path(rd, video):
    return video_dir(rd, video) / 'craft-choices.json'


def craft_choices(rd, video):
    """{measure: why} for every craft choice on record with a real reason (craft-choices.json
    choices[{measure, why}])."""
    out = {}
    for c in read_json(craft_choices_path(rd, video)).get('choices') or []:
        if isinstance(c, dict) and n_words(c.get('why')) >= MIN_CRAFT_WORDS:
            out[str(c.get('measure') or '').strip()] = str(c['why']).strip()
    return out


def picture_plan_facts(rd, video):
    """The picture plan in time, from the shot plan on the film's clock (film_clock): how many pictures and stills, how
    long each stands, which return and for how long, the still shown most, the beats that open on a picture already
    seen, the shots that set two things side by side with nothing drawn on them; and under `measures` what that makes
    of the measures a finished film is read by. {} until a script and a shot plan exist. Facts only."""
    n = int(video)
    vd = video_dir(rd, n)
    script = read_json(vd / 'script.json')
    lines = [l for l in script.get('lines') or [] if isinstance(l, dict)]
    shots = [s for s in read_json(rd / '60-visuals' / f'video-{n:02d}' / 'shot-plan.json').get('shots') or []
             if isinstance(s, dict)]
    if not lines or not shots:
        return {}
    ids = [str(l.get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)]
    pace = float(script.get('pace_wpm') or read_json(vd / 'length-lock.json').get('pace_wpm') or 0) or 150.0
    clock, basis, _ = film_clock(rd, n, lines, pace)
    starts = []
    for s in shots:
        lid = str(s.get('line_start'))
        if lid not in clock:
            starts.append(None)
            continue
        a, z = clock[lid]
        sw = s.get('start_word')
        if isinstance(sw, int) and not isinstance(sw, bool) and sw > 1:      # a cut on a word inside the line
            a += (z - a) * min(1.0, (sw - 1) / max(1, count_words(lines[ids.index(lid)].get('text', ''))))
        starts.append(a)
    end = clock[ids[-1]][1]
    rows = []
    for k, (s, a) in enumerate(zip(shots, starts)):
        if a is not None:
            rows.append((s, a, max(0.0, next((x for x in starts[k + 1:] if x is not None), end) - a)))
    total = end - rows[0][1] if rows else 0.0
    if not rows or total <= 0:
        return {}
    by_id = {str(s.get('id')): s for s in shots}

    def still_of(s):                         # the still a shot shows: its own, or the one it returns to
        seen = set()
        while s.get('reuses') and str(s['reuses']) in by_id and str(s.get('id')) not in seen:
            seen.add(str(s.get('id')))
            s = by_id[str(s['reuses'])]
        return str(s.get('id'))
    use, first_of_beat = {}, {}
    for s, a, d in rows:
        u = use.setdefault(still_of(s), {'times': 0, 'seconds': 0.0})
        u['times'] += 1
        u['seconds'] += d
        first_of_beat.setdefault(str(s.get('beat_id')), s)
    again = [r for r in rows if r[0].get('reuses')]
    top = max(use.items(), key=lambda kv: kv[1]['seconds'])
    longest = max(rows, key=lambda r: r[2])
    lengths = sorted(d for _, _, d in rows)

    def two_sided(s):
        prompt = str(s.get('frame_prompt') or s.get('prompt') or '')
        return ('split' in str(s.get('composition') or '').lower() or bool(TWO_SIDED.search(prompt))
                or ('left half' in prompt.lower() and 'right half' in prompt.lower()))
    bare = [str(s.get('id')) for s in shots if two_sided(s)
            and str(s.get('diagram_or_overlay') or 'none').strip().lower() in ('', 'none', 'false', '0')]
    return {'basis': basis, 'shots': len(rows), 'stills': len(use), 'seconds': round(total, 1),
            'seen_again': {'shots': len(again), 'share_of_shots': round(len(again) / len(rows), 2),
                           'share_of_time': round(sum(r[2] for r in again) / total, 2)},
            'most_shown': {'still': top[0], 'times': top[1]['times'], 'seconds': round(top[1]['seconds'], 1),
                           'share_of_time': round(top[1]['seconds'] / total, 2)},
            'longest': {'shot': str(longest[0].get('id')), 'seconds': round(longest[2], 1), 'from_s': round(longest[1], 1)},
            'beats_opening_on_a_seen_picture': [b for b, s in first_of_beat.items() if s.get('reuses')],
            'two_sided_with_nothing_drawn': bare,
            'measures': {'pictures_per_min': (len(rows) - 1) / (total / 60),
                         'picture_stands_s': statistics.median(lengths), 'longest_picture_s': lengths[-1],
                         'seen_again_share': len(again) / len(rows)}}


def picture_plan_words(pf):
    """picture_plan_facts as the one or two sentences a check shows."""
    sa, ms, lg = pf['seen_again'], pf['most_shown'], pf['longest']
    out = [f'pictures: {pf["stills"]} still(s) in {pf["shots"]} shot(s) over {_mmss(pf["seconds"])} on {pf["basis"]}'
           + (f'; {sa["shots"]} shot(s) show a picture seen before ({sa["share_of_shots"]:.0%} of the shots, '
              f'{sa["share_of_time"]:.0%} of the time)' if sa['shots'] else '; no picture returns')
           + (f'; the still shown most is {ms["still"]}: {ms["times"]} times, {_mmss(ms["seconds"])} in all '
              f'({ms["share_of_time"]:.0%} of the film)' if ms['times'] > 1 else '')
           + f'; the longest a picture stands is {lg["seconds"]:g} s ({lg["shot"]}, from {_mmss(lg["from_s"])})']
    if pf['beats_opening_on_a_seen_picture']:
        out.append('pictures: ' + ', '.join(pf['beats_opening_on_a_seen_picture'][:12]) + ' open(s) on a picture the '
                   'viewer has already seen: a return they will feel, or the start of a part with nothing new to show?')
    if pf['two_sided_with_nothing_drawn']:
        out.append('pictures: ' + ', '.join(pf['two_sided_with_nothing_drawn'][:12]) + ' set(s) two things side by side '
                   'with nothing drawn on them: will a viewer know which side is which without a word on each?')
    return out


def export_measures(rd, video, export_file):
    """A finished file's own measurements (its av-profile), read the way a model's are; {} when it has none yet."""
    target = export_av_path(rd, int(video), quick_fingerprint(Path(export_file).expanduser().resolve()))
    s = dict(read_json(target).get('summary') or {})
    if not s:
        return {}
    nar = dict(s.get('narration') or {})
    if nar and not nar.get('pause_profile'):
        words = transcript_words(read_json(target.with_name(target.stem + '-whisper.json')))
        if words:
            s['narration'] = {**nar, 'pause_profile': pause_profile(words)}
    return model_measures(s)


def models_beside_facts(rd, video, export_file=None, sound=None):
    """{models, rows, departures, notes}: every MODEL_MEASURES row with each model's value, their range, and this film's
    value before its export (the picture plan on the film's clock; the recorded narration; the mix by the project's own
    files, from the current sound review or `sound`) and in the export when one is given and measured. A row's
    `outside` says on which side of every model the film lies ('under', 'over'), read on the export when there is one,
    else on the value before it; a range needs two measured models. departures: [{measure, said, issue}], the issue
    set where a reason is asked for and none is on record."""
    n = int(video)
    refs, notes = model_refs(rd, n)
    models, rates = {}, set()
    for v in refs:
        prof = read_json(ref_av_path(rd, v))
        if prof.get('summary'):
            models[v] = model_measures(prof['summary'])
            rates.add(prof.get('sampled_fps'))
    if len(rates - {None}) > 1:
        notes.append('the models\' frames were sampled at different rates: compare their cuts a minute with care')
    plan = picture_plan_facts(rd, n)
    before = dict(plan.get('measures') or {})
    basis = {k: 'planned: the shot plan on ' + plan['basis'] for k in before}
    nar = read_json(rd / '50-audio' / f'video-{n:02d}' / 'delivery.json').get('summary') or {}
    if nar.get('pauses_per_min') is not None:
        before['pauses_per_min'] = nar['pauses_per_min']
        basis['pauses_per_min'] = 'the recorded narration, before the edit\'s holds'
    if sound is None:
        sr = read_json(sound_review_path(rd, n))
        sound = sr.get('between_words') if sr and sr.get('tracks_digest') == sound_tracks_digest(rd, n) else None
    gap = (sound or {}).get('gap_level_rel_speech_db')
    if isinstance(gap, dict) and gap.get('median') is not None:
        before['sound_under_voice_db'], before['sound_moves_db'] = -gap['median'], gap['p90'] - gap['p10']
        basis['sound_under_voice_db'] = basis['sound_moves_db'] = \
            'the mix by the project\'s own files: a forecast of the export'
    exp = export_measures(rd, n, export_file) if export_file else {}
    if export_file and not exp:
        notes.append('this file has no measurements of its own yet (av-profile --video NN --file): read on the values '
                     'before the export')
    answers = craft_choices(rd, n)
    out = {'models': list(models), 'rows': [], 'departures': [], 'notes': notes}
    if len(models) < 2:
        notes.append(('no model of this film is measured' if not models else 'one measured model only')
                     + ': a range needs two, so nothing is read as inside or outside')
    for key, what, nd, asked in MODEL_MEASURES:
        mv = {v: round(float(m[key]), nd) for v, m in models.items() if m.get(key) is not None}
        rng = [min(mv.values()), max(mv.values())] if len(mv) >= 2 else None
        b = round(float(before[key]), nd) if before.get(key) is not None else None
        e = round(float(exp[key]), nd) if exp.get(key) is not None else None
        ours, on = (e, 'export') if e is not None else (b, 'before') if b is not None else (None, None)
        outside = ('under' if ours < rng[0] else 'over' if ours > rng[1] else None) if rng and ours is not None else None
        out['rows'].append({'measure': key, 'what': what, 'models': mv, 'range': rng, 'before_export': b,
                            'before_basis': basis.get(key), 'export': e, 'read_on': on, 'outside': outside,
                            'asked': asked, 'why': answers.get(key)})
        if not outside:
            continue
        where = 'in the export' if on == 'export' else basis.get(key) or 'before the export'
        said = (f'{what}: {ours:g} here ({where}); every model is {"higher" if outside == "under" else "lower"} '
                f'({rng[0]:g} to {rng[1]:g}: ' + ', '.join(f'{k} {v:g}' for k, v in mv.items()) + ')')
        issue = None
        if answers.get(key):
            said = f'craft choice: {said}. The reason on record: {answers[key]}'
        elif asked:
            issue = (f'craft_choice_{key}:{ours:g}_here_every_model_is_{"higher" if outside == "under" else "lower"}'
                     f'_({rng[0]:g}_to_{rng[1]:g}):change_it_or_say_why_in_craft-choices.json')
            said += ': a choice, or something nobody chose? (craft-choices.json holds the answer)'
        out['departures'].append({'measure': key, 'said': said, 'issue': issue})
    return out


def models_beside_markdown(facts, title=''):
    """The comparison as a page a person reads in a minute."""
    refs = facts.get('models') or []

    def cell(v):
        return '' if v is None else f'{v:g}'
    head = ('| measure | ' + ' | '.join(refs + ['the models', 'this film before its export', 'this film\'s export'])
            + ' |\n' + '|---' * (len(refs) + 4) + '|\n')
    body = ''
    for r in facts.get('rows') or []:
        def ours(v, on):
            return cell(v) + (' **(outside)**' if v is not None and r['outside'] and r['read_on'] == on else '')
        body += ('| ' + ' | '.join([r['what']] + [cell(r['models'].get(v)) for v in refs]
                                   + [f'{r["range"][0]:g} to {r["range"][1]:g}' if r['range'] else '',
                                      ours(r['before_export'], 'before'), ours(r['export'], 'export')]) + ' |\n')
    return (f'# The film beside its models{": " + title if title else ""}\n\n'
            'Measured the same way in every film. A difference is a fact, never a fault: where this film lies outside '
            'every model on a habit a viewer feels, the reason is on record or still to give.\n\n' + head + body
            + '\n## Where this film lies outside every model\n\n'
            + ('\n'.join('- ' + d['said'] for d in facts.get('departures') or []) or '- nowhere') + '\n'
            + ('\n## Notes\n\n' + '\n'.join('- ' + x for x in facts['notes']) + '\n' if facts.get('notes') else ''))


def cmd_beside_models(args):
    """The film beside its models (models_beside_facts): pictures, pauses and sound, measured the same way. --file adds
    a finished file's own measurements; --out FILE.md also writes the page there. Reads only."""
    rd, st = run_folder(args)
    n = int(args.video)
    f = Path(args.file).expanduser().resolve() if getattr(args, 'file', None) else None
    if f and not f.is_file():
        error('That file is not there.', {'file': str(f)})
    facts = models_beside_facts(rd, n, f)
    vd = video_dir(rd, n)
    title = read_json(vd / 'blueprint.json').get('title') or \
        selection_promise(read_json(vd / 'direction.json')).get('working_title') or ''
    page = models_beside_markdown(facts, str(title))
    out = Path(args.out).expanduser().resolve() if getattr(args, 'out', None) else None
    if out:
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(page, encoding='utf-8')
    emit({'ok': True, 'video': n, **facts, 'pictures': {k: v for k, v in picture_plan_facts(rd, n).items()
                                                        if k != 'measures'} or None,
          'craft_choices_file': str(craft_choices_path(rd, n)), 'page': str(out) if out else None,
          **({} if out else {'page_text': page}),
          'reading': 'Each number is a habit of a finished film, measured the same way in all of them. A film may '
                     'differ from every model it has: what matters is that the difference was chosen. Where a reason '
                     'is asked for, change the plan or the mix, or write the reason (craft-choices.json: '
                     '{"choices": [{"measure": "...", "why": "..."}]}).'})


def shot_check_path(rd, video):
    return rd / '60-visuals' / f'video-{int(video):02d}' / 'shot-check.json'


def shot_facts(rd, video, keep=''):
    """The shot plan as a visual argument (04): every shot belongs to a beat and says what NEW thing its picture
    gives the viewer; every beat has a picture; lines run contiguously. Plus repetition signals: shots whose
    prompts are nearly the same, and long runs of one composition family."""
    n = int(video)
    plan = read_json(rd / '60-visuals' / f'video-{n:02d}' / 'shot-plan.json')
    out = {'ready': False, 'issues': [], 'warnings': [], 'shots': 0, 'content_flags': []}
    if not plan:
        out['issues'].append('shot_plan_missing')
        return out
    themes = excluded_themes(rd, n)
    beat_rows = read_json(video_dir(rd, n) / 'beat-map.json').get('beats') or []
    beats = [str(b.get('id')) for b in beat_rows]
    spans = {}
    for b in beat_rows:
        try:
            spans[str(b.get('id'))] = (int(b['line_start']), int(b['line_end']))
        except (KeyError, TypeError, ValueError):
            pass
    lines = read_json(video_dir(rd, n) / 'script.json').get('lines') or []
    order = [str(r.get('id') or f'L{i + 1:03d}') for i, r in enumerate(lines)]
    shots = plan.get('shots') or []
    out['shots'] = len(shots)
    used, cursor, earlier, prev_a, prev_sw = set(), 0, set(), None, None
    for s in shots:
        sid = s.get('id')
        if str(s.get('beat_id')) not in beats:
            out['issues'].append(f'shot_{sid}_beat_not_in_beat_map')
        else:
            used.add(str(s.get('beat_id')))
        if n_words(s.get('new_thing')) < 4:
            out['issues'].append(f'shot_{sid}_missing_new_thing')
        if s.get('reuses') and str(s.get('reuses')) not in earlier:
            out['issues'].append(f'shot_{sid}_reuses_no_earlier_shot')   # a callback shows an earlier shot's still
        elif n_words(s.get('frame_prompt') or s.get('prompt')) < 8 and not s.get('reuses'):
            out['issues'].append(f'shot_{sid}_missing_frame_prompt')
        if not s.get('reuses'):
            kinds = prompt_flags(s.get('frame_prompt') or s.get('prompt'), themes)
            if kinds:
                found = prompt_flag_issues(f'shot_{sid}_prompt', kinds, s.get('content_note'))
                out['content_flags'].append({'shot': sid, 'kinds': kinds, 'open': found})
                out['issues'] += found
        earlier.add(str(sid))
        a = order.index(str(s.get('line_start'))) + 1 if str(s.get('line_start')) in order else None
        b = order.index(str(s.get('line_end'))) + 1 if str(s.get('line_end')) in order else None
        sw = s.get('start_word')
        if sw is not None:
            # a cut on a word inside a line (04): the shot starts at that word of line_start, which the previous shot
            # ends on; words counted as the captions show them
            words_n = len(_captions().display_words(lines[a - 1].get('text') or '', strip_tags)) if a else 0
            if not (isinstance(sw, int) and not isinstance(sw, bool) and 2 <= sw <= words_n):
                out['issues'].append(f'shot_{sid}_start_word_not_in_line')
            elif prev_a == a and prev_sw and sw <= prev_sw:
                out['issues'].append(f'shot_{sid}_start_word_not_after_previous_shot')
        if a != (cursor if sw is not None else cursor + 1) or b is None or b < a:
            out['issues'].append(f'shot_{sid}_lines_not_contiguous')
        prev_a, prev_sw = a, sw
        span = spans.get(str(s.get('beat_id')))
        if span and a and b and (a < span[0] or b > span[1]):
            # The picture would play over another beat's words while following this beat's direction.
            out['issues'].append(f'shot_{sid}_lines_outside_beat_{s.get("beat_id")}')
        cursor = b or cursor
    # Made for an earlier direction (or before there was one): updated for real, or explicitly reapproved.
    out['issues'] += list(stale_files(rd, n, ('shot-plan', 'style-bible')).values())
    if order and cursor != len(order):
        out['issues'].append('shots_do_not_cover_every_line')
    for b in beats:
        if b not in used:
            out['issues'].append(f'beat_{b}_has_no_shot')
    toks = [(s.get('id'), _content_tokens(s.get('frame_prompt') or s.get('prompt') or '')) for s in shots]
    close = []
    for i in range(len(toks)):
        for j in range(i + 1, len(toks)):
            sim = _jaccard(toks[i][1], toks[j][1])
            if sim >= 0.7:
                close.append(f'{toks[i][0]}~{toks[j][0]} ({sim:.0%})')
    if close:
        out['warnings'].append('prompts nearly the same (a callback, or the same picture twice?): ' + ', '.join(close[:12]))
    run, prev = [], None
    for s in shots + [{}]:
        fam = str(s.get('composition') or '')
        if fam and fam == prev:
            run.append(s.get('id'))
        else:
            if len(run) >= 4:
                out['warnings'].append(f'{len(run)} shots in a row of the same composition "{prev}": {run[0]}-{run[-1]}')
            run = [s.get('id')] if fam else []
        prev = fam
    out['issues'] += key_moment_shot_issues(read_json(video_dir(rd, n) / 'direction.json'), beat_rows, shots)
    out['issues'] += uncertain_shot_issues(read_json(video_dir(rd, n) / 'direction.json'), beat_rows, shots)
    # A beat changed since the shot plan last passed this check: its shots were planned for the beat as it was. The
    # ones left exactly as they were are named (update them, or shot-check --keep "why they still fit"); the shots of
    # the other beats and their stills are untouched (2026-11-24: precise, never wholesale).
    snap = read_json(shot_check_path(rd, n))
    out['changed_beats'] = {}
    if isinstance(snap.get('beats'), dict):
        # a beat is its direction and its words: a line added in an earlier beat shifts this one's line numbers
        # without changing it (2026-11-25); a check recorded before that is compared as it was made
        script_rows = read_json(video_dir(rd, n) / 'script.json').get('lines') or []
        now_b = {str(b.get('id')): b for b in beat_rows if isinstance(b, dict)}
        for bid, sha in snap['beats'].items():
            if bid in now_b and not part_unchanged(sha, now_b[bid], beat_content_sha(now_b[bid], script_rows)):
                left = [str(s.get('id')) for s in shots if str(s.get('beat_id')) == bid
                        and part_unchanged((snap.get('shots') or {}).get(str(s.get('id'))), s)]
                if left:
                    out['changed_beats'][bid] = left
        for bid, left in out['changed_beats'].items():
            msg = f'beat_{bid}_changed_since_its_shots_were_checked:{",".join(left)}'
            if keep:
                out['warnings'].append(f'{msg} (kept: {keep})')
            else:
                out['issues'].append(msg + ':update_them_or_shot-check_--keep_why_they_still_fit')
    out['overlays'] = sum(1 for s in shots if str(s.get('diagram_or_overlay')).lower() not in ('', 'false', 'none', '0'))
    # The picture plan in time, and beside the film's models: where it lies outside every one of them on a habit a
    # viewer feels (how often the picture changes, how often one returns), the reason is asked for before a still is
    # made (craft-choices.json). Facts and one accountable answer: nothing is scored, and no number is right.
    pf = picture_plan_facts(rd, n)
    out['pictures'] = {k: v for k, v in pf.items() if k != 'measures'} or None
    if pf:
        out['warnings'] += picture_plan_words(pf)
        beside = models_beside_facts(rd, n)
        out['beside_the_models'] = {'models': beside['models'], 'notes': beside['notes'],
                                    'rows': [r for r in beside['rows'] if r['measure'] in PICTURE_MEASURES]}
        for dp in beside['departures']:
            if dp['measure'] in PICTURE_MEASURES:
                (out['issues'] if dp['issue'] else out['warnings']).append(dp['issue'] or dp['said'])
    older_plan_advisory(rd, n, out['issues'], out['warnings'])
    out['ready'] = not out['issues']
    return out


# ---------------------------------------------------------------- the episode's narrator (voice lock)
# Each video chooses its own narrator for its locked treatment (voice-pick writes 60-voice/video-NN/voice-lock.json);
# videos of a series may share one voice on purpose. Every recording of the video follows its lock: voice, model and
# settings. A video recorded before episodes had their own lock keeps the run's older one (60-voice/voice-lock.json).
VOICE_SETTING_KEYS = ('stability', 'similarity_boost')


def voice_lock_path(rd, video):
    return rd / '60-voice' / f'video-{int(video):02d}' / 'voice-lock.json'


def voice_lock(rd, video):
    """(lock, legacy): this video's own voice lock, or the run's older one for a video recorded before."""
    own = read_json(voice_lock_path(rd, video))
    if own:
        return own, False
    old = read_json(rd / '60-voice' / 'voice-lock.json')
    return old, bool(old)


def narrator_sha(direction):
    t = chosen_treatment_of(direction)
    return canonical_sha({k: t.get(k) for k in ('narrator', 'writing_voice')}) if t else None


def voice_settings_issues(settings):
    """Eleven v4 / v4 Turbo apply exactly two voice settings, stability and similarity (ElevenLabs' v4 docs: no style,
    no speed, no SSML); both are chosen, never left to the account default."""
    if not isinstance(settings, dict) or not settings:
        return ['voice_settings_missing']
    out = [f'voice_setting_not_applied_by_eleven_v4:{k}' for k in settings if k not in VOICE_SETTING_KEYS]
    for k in VOICE_SETTING_KEYS:
        v = settings.get(k)
        if v is None:
            out.append(f'voice_setting_missing:{k}')
        elif isinstance(v, bool) or not isinstance(v, (int, float)) or not 0 <= float(v) <= 1:
            out.append(f'voice_setting_out_of_range:{k}')
    return out


def voice_facts(rd, video, voice_id=None, model_id=None, settings=None):
    """What this video's recording must use: its voice lock, current for the locked direction. A voice, model or
    settings given on a command line must be exactly the locked ones (conflicts); a change is a deliberate revision
    (voice-pick --replace with a reason), never an override."""
    vl, legacy = voice_lock(rd, video)
    out = {'issues': [], 'warnings': [], 'conflicts': [], 'legacy': legacy, 'lock': vl,
           'voice_id': vl.get('voice_id'), 'model_id': vl.get('model_id') or 'eleven_v4',
           'settings': vl.get('settings') or {}, 'voice_rev': vl.get('voice_rev', 1) if vl else None}
    if not vl:
        out['issues'].append('voice_lock_missing')
        return out
    if voice_id and voice_id != out['voice_id']:
        out['conflicts'].append('voice_id_differs_from_the_episode_voice_lock')
    if model_id and model_id != out['model_id']:
        out['conflicts'].append('model_differs_from_the_episode_voice_lock')
    if settings is not None and settings != out['settings']:
        out['conflicts'].append('voice_settings_differ_from_the_episode_voice_lock')
    out['issues'] += voice_settings_issues(out['settings'])
    if out['model_id'] not in TTS_MODELS:
        out['issues'].append('voice_lock_model_not_allowed')
    if legacy:
        out['warnings'].append('this video records with the run\'s older voice lock (made before each video chose its '
                               'own narrator); choosing a narrator for it now goes through voice-pick')
    else:
        dlock = read_json(video_dir(rd, video) / 'direction-lock.json')
        if dlock and not media_current(dlock, 'voice', vl.get('production_rev')):
            out['issues'].append('voice_made_for_an_earlier_direction')
        if n_words(vl.get('reason')) < MIN_NOTE_WORDS:
            out['issues'].append('voice_lock_without_its_reason')
    return out


def _measured_matches(m, voice_id, model_id, settings):
    return bool(m and m.get('wpm') and m.get('per_line_overhead_s') is not None and (m.get('words') or 0) >= 300
                and m.get('voice_id') == voice_id and (m.get('model_id') or 'eleven_v4') == (model_id or 'eleven_v4')
                and (m.get('settings') or {}) == (settings or {}))


def voice_measurement(rd, video=None):
    """The real measured pace and natural per-line gap of the voice this video records with (narration-measure writes
    it): from this video's voice lock, else from another episode of the run locked to the same voice, model and settings
    (a series voice keeps its calibration), else from the run's older lock. Empty until a real part of 300+ words of
    that exact voice setup has been measured."""
    if video is None:
        vl, legacy = read_json(rd / '60-voice' / 'voice-lock.json'), True
    else:
        vl, legacy = voice_lock(rd, video)
    want = (vl.get('voice_id'), vl.get('model_id') or 'eleven_v4', vl.get('settings') or {})
    m = vl.get('measured') or {}
    if _measured_matches(m, *want):
        return m
    if vl and not legacy:
        for other in sorted((rd / '60-voice').glob('video-*/voice-lock.json')):
            om = read_json(other).get('measured') or {}
            if other != voice_lock_path(rd, video) and _measured_matches(om, *want):
                return {**om, 'source': f'measured on {other.parent.name}: same voice, model and settings'}
        om = read_json(rd / '60-voice' / 'voice-lock.json').get('measured') or {}
        if _measured_matches(om, *want):
            return {**om, 'source': 'measured under the run\'s older voice lock: same voice, model and settings'}
    if legacy and vl.get('measured_wpm') and vl.get('measured_overhead_s') and vl.get('measured_overhead_lines'):
        return {'wpm': vl['measured_wpm'], 'per_line_overhead_s': vl['measured_overhead_s'] / vl['measured_overhead_lines'],
                'voice_id': vl.get('voice_id'), 'settings': vl.get('settings') or {}, 'source': 'hand-recorded (older run)'}
    return {}


def strip_transcript_timestamps(raw):
    """Remove [start-end] timestamp prefixes (e.g. [0.0-2.4]) from transcript lines."""
    lines = []
    for line in raw.splitlines():
        cleaned = re.sub(r'^\s*\[[\d.]+\s*[-–]\s*[\d.]+\]\s*', '', line)
        if cleaned.strip():
            lines.append(cleaned)
    return ' '.join(lines)


def transcript_speech(raw):
    """(spoken words, speech seconds) of a [start-end] text transcript: the sum of the spoken segments'
    durations, so silence between segments is excluded. One yardstick for references and generated narration."""
    narr_s = sum(float(m.group(2)) - float(m.group(1))
                 for m in re.finditer(r'\[([\d.]+)-([\d.]+)\]', raw))
    return count_words(strip_transcript_timestamps(raw)), narr_s


def wpm_from_transcript_raw(raw):
    """Pure-narration WPM from a [start-end] text transcript: spoken words (timestamps
    stripped from the count) over the sum of spoken-chunk durations (silence excluded).
    This is the narrator's actual speaking rate, not a video-duration-diluted figure.
    Returns None if the transcript has no parseable [start-end] chunks."""
    wc, narr_s = transcript_speech(raw)
    if narr_s <= 0:
        return None
    return round(wc / (narr_s / 60))


def transcript_words(tjson):
    """Word timestamps of a transcript.json written by transcribe(), in time order."""
    out = []
    for seg in tjson.get('segments') or []:
        for w in seg.get('words') or []:
            if w.get('start_s') is not None and w.get('end_s') is not None and str(w.get('text') or '').strip():
                out.append({'start_s': float(w['start_s']), 'end_s': float(w['end_s']), 'text': str(w['text'])})
    return out


def pause_profile(words):
    """How a narrator pauses, from Whisper word timestamps: the silence between consecutive words. Computed the
    same way for the references and for this run's narration, so the two can be compared directly."""
    if len(words) < 2:
        return {}
    gaps = [max(0.0, b['start_s'] - a['end_s']) for a, b in zip(words, words[1:])]
    span = words[-1]['end_s'] - words[0]['start_s']
    mins = span / 60 if span > 0 else 0
    real = sorted(g for g in gaps if g >= 0.3)

    def per_min(th):
        return round(sum(1 for g in gaps if g >= th) / mins, 2) if mins else None

    def pct(q):
        return round(real[min(len(real) - 1, int(q * len(real)))], 2) if real else None
    return {'speech_span_s': round(span, 1), 'pauses_0_3s_plus_per_min': per_min(0.3),
            'pauses_0_8s_plus_per_min': per_min(0.8), 'pauses_1_5s_plus_per_min': per_min(1.5),
            'pauses_3s_plus_per_min': per_min(3.0), 'pause_median_s': pct(.5), 'pause_p90_s': pct(.9),
            'longest_pause_s': round(max(gaps), 2), 'silence_share': round(sum(gaps) / span, 3) if span > 0 else None}


def ref_pause_profiles(rd, refs):
    out = {}
    for vid in refs:
        t = read_json(rd / '10-media' / vid / 'transcript.json')
        if t:
            out[vid] = pause_profile(transcript_words(t))
    return out


# ---------------------------------------------------------------- the narrators this narration follows (pacing)
# 2026-11-25 (the user): the intended pace emerges from the reference narrators who match this film (its narrator and
# delivery, its format, its density and terminology, its sentences, its emotional course, their natural variation,
# active against overall pace, pauses and what the audience must catch), from the chosen voice and from comprehension,
# never from one convenient reference, the length cohort or an earlier production. The director weighs them
# (direction.json decision.pacing); the code gathers their measured profiles, the script's own density, their range
# and how the forecast moves across it. It averages nothing and scores nothing.
PACING_NAME_LANGUAGES = ('en',)     # names are read from capitals inside a sentence: languages that capitalise names only


def inventory_videos(rd):
    """The run's reference videos ({id: row}) as cards_inventory reads them, or {} when the run has no inventory: the
    pacing facts and checks are facts, and a missing inventory never stops the command that asked for them."""
    inv = read_json(rd / '00-inventory/references.json')
    return {x['id']: x for x in inv.get('items') or [] if isinstance(x, dict) and x.get('id')
            and x.get('kind') == 'video' and not x.get('duplicate_of')}


def pacing_pool(rd, known):
    """The measured narrators a pacing decision is weighed against: the locked niche's members (the run's references
    when no niche is locked) that have a transcript, in the niche lock's order."""
    nl = read_json(niche_lock_path(rd))
    pool = [str(m.get('ref')) for m in nl.get('members') or [] if isinstance(m, dict)] if nl else list(known)
    return [v for v in pool if (rd / '10-media' / v / 'transcript.json').is_file()]


def pacing_left_out(rd, dec, known=None):
    """What a pacing decision leaves out of its comparison, as facts (the user, 2026-11-25): the locked niche's measured
    narrators it never names (`not_weighed`, each as measured, so a genuinely relevant one is not silently skipped),
    and the narrators it calls relevant that have no measured narration, which its range therefore cannot include
    (`relevant_unmeasured`). Advisory: no count is asked for and nothing is scored; whether one of them matches this
    narration is the director's judgement, written in decision.pacing with its reason."""
    known = inventory_videos(rd) if known is None else known
    pac = dec.get('pacing') if isinstance((dec or {}).get('pacing'), dict) else {}
    rows = [r for r in pac.get('references') or [] if isinstance(r, dict)]
    named = {str(r.get('ref') or '').strip().upper() for r in rows}
    not_weighed = [reference_pace_profile(rd, v, (known.get(v) or {}).get('duration_s'))
                   for v in pacing_pool(rd, known) if v in known and v not in named]
    unmeasured = []
    for r in rows:
        v = str(r.get('ref') or '').strip().upper()
        if r.get('relevant') is True and v in known and not ref_pace_stats(rd, v).get('active_wpm'):
            unmeasured.append(v)
    return {'not_weighed': not_weighed, 'relevant_unmeasured': unmeasured}


def text_density(text, language='en'):
    """What a listener has to catch by ear, from plain words: numbers and proper names per 100 words, and sentence
    length. Names are counted only where capitals mark them (PACING_NAME_LANGUAGES); numbers as digits, and as number
    words in English."""
    text = text or ''
    lang = str(language or 'en').lower()[:2]
    sents = [s for s in re.split(r'(?<=[.!?…])\s+', text) if re.search(r'[^\W_]', s)]
    words = re.findall(r"[^\W_][\w'’-]*", text)
    nums = len(NUMBER_WORDS.findall(text)) if lang == 'en' else len(re.findall(r'\d[\d,.]*', text))
    names = None
    if lang in PACING_NAME_LANGUAGES:
        names = 0
        for s in sents:
            toks = re.findall(r"[A-Za-z][A-Za-z'’-]*", s)
            names += sum(1 for t in toks[1:] if t[0].isupper() and t not in ('I', "I'm", "I'll", "I've", "I'd"))
    lens = sorted(len(re.findall(r"[^\W_][\w'’]*", s)) for s in sents)
    n = max(1, len(words))
    return {'words': len(words), 'numbers_per_100_words': round(100 * nums / n, 2),
            'names_per_100_words': round(100 * names / n, 2) if names is not None else None,
            'sentence_words_median': statistics.median(lens) if lens else None,
            'sentence_words_p90': lens[int(0.9 * (len(lens) - 1))] if lens else None}


def reference_pace_profile(rd, vid, duration_s=None):
    """One reference narrator as measured: pace while speaking and overall, how it swings across the film, its pauses,
    its delivery and the density of its words, with its story form and narrator as the card describes them. Facts for
    the director's judgement, never a verdict."""
    stats = ref_pace_stats(rd, vid, duration_s) or {}
    av = read_json(ref_av_path(rd, vid)).get('summary') or {}
    av = av.get('narration') if isinstance(av.get('narration'), dict) else av

    def median(k):
        v = av.get(k)
        return v.get('median') if isinstance(v, dict) else v
    t = read_json(rd / '10-media' / vid / 'transcript.json')
    text = ' '.join(str(s.get('text') or '').strip() for s in t.get('segments') or [])
    pauses = pause_profile(transcript_words(t)) if t else {}
    card = read_json(rd / '20-analysis' / 'cards' / f'{vid}.json')
    return {'ref': vid, 'story_form': card.get('story_form'),
            'narrator': str(card.get('narrator_character') or '')[:300] or None,
            # a pace is comparable within one language: another language's words a minute are another yardstick
            'language': t.get('language') or None,
            'active_wpm': stats.get('active_wpm'), 'overall_wpm': stats.get('overall_wpm'),
            'pause_share': stats.get('pause_share'), 'swing_wpm': av.get('rate_across_windows_wpm'),
            'pauses_0_8s_plus_per_min': pauses.get('pauses_0_8s_plus_per_min'),
            'pauses_1_5s_plus_per_min': pauses.get('pauses_1_5s_plus_per_min'),
            'longest_pause_s': pauses.get('longest_pause_s'), 'pitch_range_st': median('pitch_range_st'),
            'pitch_movement_st': median('pitch_movement_st'), 'loudness_contrast_db': median('loudness_contrast_db'),
            'density': text_density(text, t.get('language') or 'en') if text else None}


def pacing_facts(rd, video, lines, words, overhead_s, target, band, planning_wpm, language='en'):
    """The references direction.json decision.pacing weighs, as measured; the relevant ones' range (active and overall
    pace, and how far they swing); the script's own density beside theirs; and how the forecast moves across the range
    (the forecast's own arithmetic: the words at a pace, plus the per-line gap, the tags and the holds in overhead_s).
    With the export band: the voice pace that would land the locked length, a forecast and never a target for the
    delivery. Beside them, what the comparison leaves out (pacing_left_out): the niche's measured narrators it never
    names, each as measured with the forecast at its pace, and any relevant one without a measurement. Nothing here
    chooses a pace."""
    d = read_json(video_dir(rd, video) / 'direction.json')
    dec = d.get('decision') if isinstance(d.get('decision'), dict) else {}
    pac = dec.get('pacing') if isinstance(dec.get('pacing'), dict) else {}
    known = inventory_videos(rd)
    profiles = []
    for r in pac.get('references') or []:
        vid = str((r or {}).get('ref') or '').strip().upper() if isinstance(r, dict) else ''
        if vid in known:
            profiles.append({**reference_pace_profile(rd, vid, known[vid].get('duration_s')),
                             'relevant': r.get('relevant') is True})
    out = {'references': profiles,
           'script_density': text_density(' '.join(strip_tags(l.get('text') or '') for l in lines), language),
           'planning_wpm': planning_wpm, 'line_gap_assumed_s': DEFAULT_LINE_OVERHEAD_S}

    def at(p):
        s = round(words * 60 / p + overhead_s, 1)
        return {'wpm': p, 'forecast_s': s, 'minutes': f'{int(s) // 60}:{int(s) % 60:02d}'}
    left = pacing_left_out(rd, dec, known)
    out['not_weighed'] = [{**x, **({'forecast_at_its_pace': at(x['active_wpm'])} if words and x.get('active_wpm') else {})}
                          for x in left['not_weighed']]
    out['relevant_unmeasured'] = left['relevant_unmeasured']
    rel = [p for p in profiles if p['relevant'] and p.get('active_wpm')]
    if rel:
        act = [p['active_wpm'] for p in rel]
        ovr = [p['overall_wpm'] for p in rel if p.get('overall_wpm')]
        sw = [p['swing_wpm'] for p in rel if isinstance(p.get('swing_wpm'), dict)]
        out['range'] = {'relevant': [p['ref'] for p in rel], 'active_wpm': [min(act), max(act)],
                        'overall_wpm': [min(ovr), max(ovr)] if ovr else None,
                        'swing_wpm': ([min(w['p10'] for w in sw if w.get('p10')), max(w['p90'] for w in sw if w.get('p90'))]
                                      if any(w.get('p10') for w in sw) else None)}
        if words:
            pts = sorted({*act, *([planning_wpm] if planning_wpm else [])})
            out['sensitivity'] = [{**at(p), 'from': ','.join(x['ref'] for x in rel if x['active_wpm'] == p)
                                   or 'the locked planning pace'} for p in pts]
            out['range']['forecast'] = {'at_fastest': at(max(act)), 'at_slowest': at(min(act))}
    if words and target and target - band > overhead_s:
        out['voice_pace_that_fits_the_lock_wpm'] = [round(words * 60 / (target + band - overhead_s), 1),
                                                    round(words * 60 / (target - band - overhead_s), 1)]
    return out


def compute_ref_wpm(rd, refs, family):
    """Average WPM from the reference transcripts for the selected refs.
    Uses the sum of spoken-chunk durations (pure narration time) so the result
    matches the narrator's actual speaking rate — the pace ElevenLabs will generate at.
    Returns (rounded_wpm, per_ref_dict) or (None, {}) if no transcripts found."""
    per_ref = {}
    for vid in refs:
        tfile = rd / '10-media' / vid / 'transcript.txt'
        if not tfile.exists():
            continue
        wpm = wpm_from_transcript_raw(tfile.read_text(encoding='utf-8', errors='replace'))
        if wpm is not None:
            per_ref[vid] = wpm
    if not per_ref:
        return None, {}
    return round(statistics.mean(per_ref.values())), per_ref


PACE_DEFINITIONS = {
    'active_wpm': 'words over the time Whisper marks as speech (pauses between its speech segments left out): how fast '
                  'the narrator talks while talking. The voice is measured the same way (narration-measure).',
    'overall_wpm': 'words over the time from the first word to the last, every pause included: how many words a '
                   'minute of the narration really holds. The script\'s word budget comes from this one.',
    'runtime_wpm': 'words over the whole video, intro and outro included.',
    'pause_share': 'the share of the speaking span that is silence between words.'}


def sentence_cadence(texts):
    """Words per sentence (median, 90th percentile) and sentences, from transcript or script text."""
    sents = [len(re.findall(r"[\w']+", s)) for t in texts for s in re.split(r'(?<=[.!?…])\s+', strip_tags(t))]
    sents = sorted(x for x in sents if x)
    if not sents:
        return {}
    return {'sentences': len(sents), 'sentence_words_median': sents[len(sents) // 2],
            'sentence_words_p90': sents[min(len(sents) - 1, int(0.9 * len(sents)))]}


def ref_pace_stats(rd, vid, duration_s=None):
    """One reference narrator on the pipeline's yardsticks (PACE_DEFINITIONS): the same transcribe() output the
    references and this run's narration are both measured from."""
    media = rd / '10-media' / vid
    tfile = media / 'transcript.txt'
    if not tfile.exists():
        return {}
    raw = tfile.read_text(encoding='utf-8', errors='replace')
    words, speech = transcript_speech(raw)
    tj = read_json(media / 'transcript.json')
    ws = transcript_words(tj)
    span = (ws[-1]['end_s'] - ws[0]['start_s']) if len(ws) > 1 else 0.0
    out = {'words': words, 'speech_s': round(speech, 1), 'span_s': round(span, 1),
           'active_wpm': round(words / (speech / 60)) if speech else None,
           'overall_wpm': round(words / (span / 60)) if span else None,
           'pause_share': round(max(0.0, 1 - speech / span), 3) if span and speech else None,
           **sentence_cadence([s.get('text') or '' for s in tj.get('segments') or []])}
    if duration_s:
        out['duration_s'] = round(float(duration_s), 1)
        out['runtime_wpm'] = round(words / (float(duration_s) / 60))
    return out


# ---------------------------------------------------------------- story size, the opening, the wording of uncertain facts
# Planning rules 5 (2026-11-26). Each gathers evidence and asks for an accountable answer where a look is due; none
# decides whether the film is good, and no number here is a target.
SCRIPT_GROWTH_LOOK = 0.15     # a script this much larger than its first complete draft is looked at: what grew, and why


def script_size_path(vd):
    return vd / 'script-size.json'


def script_is_whole(lines, beats):
    """Every line has a beat and every beat its lines: a whole draft, not a part of one."""
    try:
        spans = sorted((int(b['line_start']), int(b['line_end'])) for b in beats if isinstance(b, dict))
    except (KeyError, TypeError, ValueError):
        return False
    return bool(lines) and bool(spans) and spans[0][0] == 1 and spans[-1][1] == len(lines)


def script_size_facts(vd, words):
    """The script beside its own first complete draft (plan-check records that draft once): how much it has grown,
    and whether the growth was accounted for. A story's first whole draft is the nearest thing to its natural size; a
    script that grows far past it while the length stays locked may be filling the length (2026-11-26: a film was
    filled to its first lock, and the filled stretch became its slow middle). (facts, issue or None)."""
    sz = read_json(script_size_path(vd))
    first = sz.get('first_complete_draft') if isinstance(sz.get('first_complete_draft'), dict) else {}
    out = {'first_complete_draft': first or None, 'now_words': words}
    if not first.get('words') or not words:
        return out, None
    grew = (words - int(first['words'])) / int(first['words'])
    covered = max((int(a['words']) for a in sz.get('growth_answers') or [] if isinstance(a, dict) and a.get('words')
                   and n_words(a.get('why')) >= MIN_NOTE_WORDS), default=0)
    out.update({'grew_pct': round(100 * grew, 1), 'growth_answered_up_to_words': covered or None})
    if grew > SCRIPT_GROWTH_LOOK and words > covered * 1.05:
        return out, (f'script_grew_{round(100 * grew)}pct_since_its_first_complete_draft:say_what_the_added_lines_carry:'
                     'plan-check_--grew-for')
    return out, None


def record_script_size(rd, video, words, forecast_s, grew_for=''):
    """plan-check's own record of the script's size: its first complete draft, once, and each answer to "why did it
    grow" with the size it was given for. True when something was written."""
    vd = video_dir(rd, video)
    sz = read_json(script_size_path(vd))
    changed = False
    if not isinstance(sz.get('first_complete_draft'), dict) and words and script_is_whole(
            read_json(vd / 'script.json').get('lines') or [], read_json(vd / 'beat-map.json').get('beats') or []):
        sz['first_complete_draft'] = {'at': now(), 'words': words, 'forecast_s': forecast_s,
                                      'locked_s': read_json(vd / 'length-lock.json').get('target_length_s')}
        changed = True
    if grew_for:
        sz.setdefault('growth_answers', []).append({'at': now(), 'words': words, 'why': grew_for.strip()})
        changed = True
    if changed:
        write_json(script_size_path(vd), sz)
    return changed


def line_clock(lines, pace_wpm, overhead_s=DEFAULT_LINE_OVERHEAD_S):
    """About when each line starts and ends at the planning pace: {id: (start_s, end_s)}. A forecast, as the pace is;
    holds are left out (it is read for the opening minutes)."""
    t, out = 0.0, {}
    for i, l in enumerate(lines):
        d = count_words(l.get('text', '')) * 60 / float(pace_wpm)
        out[str(l.get('id') or f'L{i + 1:03d}')] = (round(t, 1), round(t + d, 1))
        t += d + overhead_s
    return out


def opening_facts(rd, video, lines, pace):
    """When the latest cold reader knew what the video offers (promise.clear_at) and when they first got it
    (first_delivered), in seconds at the planning pace, beside the title's promise and the hooks of the references this
    direction cites (their cards' hook.end_s). Facts for the director; one sentence when the film takes longer to say
    what it offers than every one of those references: a look, never a rule. (facts, sentence or None)."""
    vd = video_dir(rd, video)
    recs = review_records(vd, 'script')
    pr = recs[-1][0].get('promise') if recs else None
    if not isinstance(pr, dict) or not pace or not lines:
        return {}, None
    clock = line_clock(lines, pace)
    ids = list(clock)

    def lines_of(spec):
        s = str(spec or '').strip()
        return (expand_lines(_line_specs(s), ids) or []) if s and s.lower() != 'never' else []
    clear, got = lines_of(pr.get('clear_at')), lines_of(pr.get('first_delivered'))
    d = read_json(vd / 'direction.json')
    hooks = {}
    for r in _ids((d.get('evidence') or {}).get('references') if isinstance(d.get('evidence'), dict) else []):
        h = read_json(rd / '20-analysis/cards' / f'{r.upper()}.json').get('hook')
        if isinstance(h, dict) and isinstance(h.get('end_s'), (int, float)) and not isinstance(h['end_s'], bool) \
                and h['end_s'] > 0:
            hooks[r.upper()] = float(h['end_s'])
    sp = selection_promise(d)
    out = {'reader_round': recs[-1][0].get('_round'), 'reader_was_promised': pr.get('promised'),
           'clear_at_line': clear[-1] if clear else None, 'clear_at_s': clock[clear[-1]][1] if clear else None,
           'first_delivered_line': got[0] if got else None, 'first_delivered_s': clock[got[0]][0] if got else None,
           'working_title': sp.get('working_title'), 'title_promises': sp.get('viewer_expects'),
           'reference_hooks_end_s': hooks, 'basis': 'the planning pace, without holds: a forecast'}
    said = None
    if out['clear_at_s'] is not None and hooks and out['clear_at_s'] > max(hooks.values()):
        said = (f'opening: the latest reader knew what the video offers by {out["clear_at_line"]}, about '
                f'{_mmss(out["clear_at_s"])} in at the planning pace; the references this direction cites have made '
                f'their promise by {_mmss(max(hooks.values()))} at the latest ('
                + ', '.join(f'{k} {_mmss(v)}' for k, v in sorted(hooks.items())) + '). Look at what a viewer gets '
                'before that line: an opening may take longer when every stretch of it rewards, and the reader\'s '
                '"waiting" says whether it did')
    return out, said


def film_clock(rd, video, lines, pace):
    """({line id: (start_s, end_s)}, what those times are, measured): the recorded narration's own times in the edit
    (with its holds) once every line is measured, else a forecast at the planning pace."""
    n = int(video)
    ids = [str(l.get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)]
    marks = edit_landmarks(rd, n)
    if ids and all((marks.get(i) or {}).get('start') is not None for i in ids):
        held = bool(read_json(rd / '70-edit' / f'video-{n:02d}' / 'edit-plan.json').get('holds'))
        return ({i: (float(marks[i]['start']), float(marks[i]['end'])) for i in ids},
                'the recorded narration' + (' with the edit\'s holds' if held else ''), True)
    return line_clock(lines, pace), f'the planning pace ({pace:g} wpm), without holds: a forecast', False


# ---------------------------------------------------------------- the run sheet: the film on one page
# The audit of 2026-11-26 found a slow middle of three and a half minutes that fourteen checks and thirteen reads had
# passed: each looked at one thing, none at the film's course. The run sheet puts that course on one page, from what
# the plan already holds: for every beat its time, how much the ear has to catch, what the viewer is waiting for, what
# the beat gives, how many pictures carry it and what is heard. Under it, the few places worth a look. Facts only:
# nothing is scored, no length of a stretch is right or wrong, and a quiet passage can be exactly what the film needs.
def run_sheet_facts(rd, video):
    """{basis, rows, look_at, totals} for one video; empty rows until a script and a beat map exist. Times are the
    recorded narration's (with the edit's holds) once every line is measured, else a forecast at the planning pace."""
    n = int(video)
    vd = video_dir(rd, n)
    lock = read_json(vd / 'length-lock.json')
    script = read_json(vd / 'script.json')
    lines = [l for l in script.get('lines') or [] if isinstance(l, dict)]
    beats = [b for b in read_json(vd / 'beat-map.json').get('beats') or [] if isinstance(b, dict)]
    out = {'basis': None, 'rows': [], 'look_at': [], 'totals': {}}
    if not lines or not beats:
        return out
    ids = [str(l.get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)]
    lang = str(script.get('language') or lock.get('language') or 'en')
    pace = float(script.get('pace_wpm') or lock.get('pace_wpm') or 0) or 150.0
    clock, out['basis'], measured = film_clock(rd, n, lines, pace)
    subj = read_json(vd / 'direction.json').get('subject')
    vals = {str(v.get('id')): v for v in (subj.get('value_to_carry') if isinstance(subj, dict) else None) or []
            if isinstance(v, dict)}
    seen_names, names_by_line, given = set(), dict(script_names(lines, lang)), set()
    shots = [s for s in read_json(rd / '60-visuals' / f'video-{n:02d}' / 'shot-plan.json').get('shots') or []
             if isinstance(s, dict)]
    tracks = [t for t in read_json(rd / '70-edit' / f'video-{n:02d}' / 'timeline.json').get('audio_tracks') or []
              if isinstance(t, dict) and t.get('kind') != 'narration' and t.get('start_s') is not None
              and t.get('end_s') is not None] if measured else []
    spans = []
    for b in beats:
        try:
            mine = ids[int(b['line_start']) - 1:int(b['line_end'])]
        except (KeyError, TypeError, ValueError):
            mine = []
        spans.append(mine)
    rows = []
    for k, (b, mine) in enumerate(zip(beats, spans)):
        if not mine:
            continue
        nxt = next((s for s in spans[k + 1:] if s), None)
        a, z = clock[mine[0]][0], (clock[nxt[0]][0] if nxt else clock[mine[-1]][1])
        text = ' '.join(strip_tags(str(lines[ids.index(i)].get('text') or '')) for i in mine)
        new = []
        for i in mine:
            for nm in names_by_line.get(i) or []:
                if nm.lower() not in seen_names:
                    seen_names.add(nm.lower())
                    new.append(nm)
        nums = len(NUMBER_WORDS.findall(text)) if lang.lower().startswith('en') else len(re.findall(r'\d[\d,.]*', text))
        carried = [str(r).strip() for r in b.get('carries') or [] if str(r).strip() in vals]
        km = str(b.get('key_moment')).strip() if is_key_moment(b) else None
        again = [r for r in carried if r in given]          # a value an earlier beat already gave the viewer
        given.update(carried)
        gives = ([f'KEY MOMENT: {km}'] if km else []) + [('again: ' if r in again else '') + str(vals[r].get('what') or r)
                                                         for r in carried]
        bid = str(b.get('id'))
        mine_shots = [s for s in shots if str(s.get('beat_id')) == bid]
        words = sum(count_words(lines[ids.index(i)].get('text', '')) for i in mine)
        rows.append({'beat': bid, 'from_s': round(a, 1), 'to_s': round(z, 1), 'seconds': round(z - a, 1),
                     'lines': f'{mine[0]}-{mine[-1]}', 'words': words,
                     'words_per_min': round(words / ((z - a) / 60)) if z - a > 1 else None,
                     'new_names': new, 'numbers': nums,
                     'waits_for': str(b.get('viewer_question') or '').strip() or None,
                     'gives': '; '.join(gives) or None, 'key_moment': km, 'carries': carried, 'given_before': again,
                     'job': str(b.get('narrative_job') or '').strip()[:140] or None,
                     'pictures': ({'planned': len(mine_shots),
                                   'seen_before': sum(1 for s in mine_shots if s.get('reuses'))} if shots else None),
                     'sound': (sorted({str(t.get('kind') or 'sound') for t in tracks
                                       if float(t['start_s']) < z and float(t['end_s']) > a}) if measured and tracks
                               else None),
                     'sound_planned': str(b.get('sound_direction') or '').strip()[:100] or None})
    out['rows'] = rows
    if not rows:
        return out
    total = rows[-1]['to_s'] - rows[0]['from_s']
    out['totals'] = {'beats': len(rows), 'seconds': round(total, 1),
                     'key_moments': sum(1 for r in rows if r['key_moment']),
                     'values_carried': len({v for r in rows for v in r['carries']}),
                     'pictures_planned': sum(r['pictures']['planned'] for r in rows) if shots else None,
                     'pictures_per_min': (round(sum(r['pictures']['planned'] for r in rows) / (total / 60), 1)
                                          if shots and total > 0 else None)}
    look = out['look_at']

    def span_words(first, last):
        return (f'{_mmss(first["from_s"])}-{_mmss(last["to_s"])} ({_mmss(last["to_s"] - first["from_s"])}, '
                + (first['beat'] if first is last else f'{first["beat"]} to {last["beat"]}') + ')')
    # 1. the longest stretch between two key moments, and what the film gives the viewer inside it: a researched value
    #    for the first time, one an earlier beat already gave, or none. (The real film's slow middle was its longest
    #    such stretch: four minutes whose beats each "carried a value", three of them one already given.)
    if any(r['key_moment'] for r in rows):
        runs, cur = [], []
        for r in rows + [None]:
            if r is not None and not r['key_moment']:
                cur.append(r)
                continue
            if cur:
                runs.append(cur)
            cur = []
        # the two longest: a film always has one before its first key moment, and the next is the one inside it
        runs = sorted(runs, key=lambda c: c[-1]['to_s'] - c[0]['from_s'], reverse=True)[:2]

        def inside(run):
            first = [r['beat'] for r in run if len(r['carries']) > len(r['given_before'])]
            old = [r['beat'] for r in run if r['carries'] and len(r['carries']) == len(r['given_before'])]
            none = [r['beat'] for r in run if not r['carries']]
            return '; '.join(x for x in (
                'a researched value for the first time in ' + ', '.join(first) if first else '',
                'one an earlier beat already gave in ' + ', '.join(old) if old else '',
                'none in ' + ', '.join(none) if none and (first or old) else '') if x)
        if len(runs) == 1:
            got = inside(runs[0])
            look.append('run sheet: the longest stretch with no key moment is ' + span_words(runs[0][0], runs[0][-1]) + '. '
                        + (f'In it the viewer is given {got}' if got else 'No beat in it carries a researched value')
                        + ': what keeps them watching through it, and would they miss any of it if it were gone?')
        elif runs:
            look.append('run sheet: the two longest stretches with no key moment are ' + '; and '.join(
                span_words(c[0], c[-1]) + (f', where the viewer is given {inside(c)}' if inside(c)
                                           else ', where no beat carries a researched value') for c in runs)
                        + ': what keeps them watching through each, and would they miss any of it if it were gone?')
    else:
        look.append('run sheet: no beat is marked as a key moment (a turn, a reveal, a payoff): where does this film '
                    'give the viewer what it promised?')
    # 2. what the viewer is waiting for
    noq = [r['beat'] for r in rows if not r['waits_for']]
    if noq and len(noq) == len(rows):
        look.append('run sheet: no beat says what the viewer is waiting for (beat map viewer_question): what do they '
                    'want to know or see next at each point, and when do they get it?')
    elif noq:
        look.append('run sheet: no viewer question for ' + ', '.join(noq[:12]) + (' and more' if len(noq) > 12 else '')
                    + ': what does the viewer want to know or see next there?')
    run, longest = [], []
    for r in rows + [None]:
        if r is not None and r['waits_for'] and run and _same_words(r['waits_for']) == _same_words(run[-1]['waits_for']):
            run.append(r)
            continue
        if len(run) > 1 and (not longest or run[-1]['to_s'] - run[0]['from_s'] > longest[-1]['to_s'] - longest[0]['from_s']):
            longest = run
        run = [r] if r is not None and r['waits_for'] else []
    if longest:
        look.append('run sheet: one question is kept for ' + span_words(longest[0], longest[-1])
                    + f' ("{longest[0]["waits_for"][:90]}"): is it still alive at the end of that stretch, or has the '
                    'viewer stopped asking?')
    # 3. where the ear has most to catch
    def load(r):
        return (r['numbers'] + len(r['new_names'])) / max(r['seconds'] / 60, 0.25)
    dense = [r for r in sorted(rows, key=load, reverse=True) if r['numbers'] + len(r['new_names']) > 0][:2]
    if dense:
        look.append('run sheet: most for the ear to catch in ' + '; '.join(
            f'{r["beat"]} ({r["numbers"]} number(s), {len(r["new_names"])} new name(s) in {_mmss(r["seconds"])})'
            for r in dense) + ': does the picture carry part of it, and does each number matter to the viewer?')
    # 4. where the picture stands longest, and where nothing new is shown
    if shots:
        none = [r['beat'] for r in rows if not r['pictures']['planned']]
        if none:
            look.append('run sheet: no picture planned for ' + ', '.join(none))
        with_p = [r for r in rows if r['pictures']['planned']]
        if with_p:
            slow = max(with_p, key=lambda r: r['seconds'] / r['pictures']['planned'])
            look.append(f'run sheet: the picture stands longest in {slow["beat"]}: {slow["pictures"]["planned"]} '
                        f'picture(s) over {_mmss(slow["seconds"])} (about '
                        f'{round(slow["seconds"] / slow["pictures"]["planned"])} s each): what changes on screen while '
                        'the words go on?')
        stale = [r['beat'] for r in with_p if r['pictures']['seen_before'] == r['pictures']['planned']]
        if stale:
            look.append('run sheet: only pictures seen before in ' + ', '.join(stale)
                        + ': is that a return the viewer will feel, or a film that has run out of pictures?')
    # 5. key moments with nothing to hear but the voice (known once the timeline exists)
    if measured and tracks:
        bare = [r['beat'] for r in rows if r['key_moment'] and not r['sound']]
        if bare:
            look.append('run sheet: no music, ambience or effect over the key moment(s) ' + ', '.join(bare)
                        + ': silence chosen, or sound forgotten?')
    return out


def run_sheet_markdown(facts, title=''):
    """The run sheet as a page a person reads in a minute."""
    def cell(s):
        return str(s if s not in (None, '') else '').replace('|', '/').replace('\n', ' ')
    head = ('| beat | time | length | words/min | new names | numbers | the viewer waits for | the beat gives '
            '| pictures | sound |\n|---|---|---|---|---|---|---|---|---|---|\n')
    body = ''
    for r in facts.get('rows') or []:
        pic = r.get('pictures')
        pics = '' if pic is None else (f'{pic["planned"]}' + (f' ({pic["seen_before"]} seen before)' if pic['seen_before'] else ''))
        snd = ', '.join(r['sound']) if r.get('sound') else ('none' if r.get('sound') == [] else
                                                              (f'planned: {r["sound_planned"]}' if r.get('sound_planned') else ''))
        body += ('| ' + ' | '.join(cell(x) for x in (
            r['beat'], f'{_mmss(r["from_s"])}-{_mmss(r["to_s"])}', _mmss(r['seconds']), r.get('words_per_min'),
            ', '.join(r['new_names'][:6]) + (f' +{len(r["new_names"]) - 6}' if len(r['new_names']) > 6 else ''),
            r['numbers'] or '', r.get('waits_for'), r.get('gives') or (f'({r["job"]})' if r.get('job') else ''),
            pics, snd)) + ' |\n')
    t = facts.get('totals') or {}
    return (f'# Run sheet{": " + title if title else ""}\n\nTimes: {facts.get("basis")}. '
            f'{t.get("beats")} beats, {_mmss(t.get("seconds") or 0)}, {t.get("key_moments")} key moment(s)'
            + (f', {t.get("pictures_planned")} pictures planned ({t.get("pictures_per_min")} a minute)'
               if t.get('pictures_planned') is not None else '') + '.\n\n' + head + body
            + '\n## Places to look (facts, never faults)\n\n'
            + ('\n'.join('- ' + x.replace('run sheet: ', '', 1) for x in facts.get('look_at') or []) or '- none') + '\n')


def cmd_run_sheet(args):
    """The film on one page (run_sheet_facts). Reads only; --out FILE.md also writes the page there."""
    rd, st = run_folder(args)
    n = int(args.video)
    facts = run_sheet_facts(rd, n)
    if not facts['rows']:
        error('No run sheet yet: it is read from the script and the beat map.')
    vd = video_dir(rd, n)
    title = read_json(vd / 'blueprint.json').get('title') or \
        selection_promise(read_json(vd / 'direction.json')).get('working_title') or ''
    page = run_sheet_markdown(facts, str(title))
    out = Path(args.out).expanduser().resolve() if getattr(args, 'out', None) else None
    if out:
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(page, encoding='utf-8')
    emit({'ok': True, 'video': n, 'basis': facts['basis'], 'totals': facts['totals'], 'look_at': facts['look_at'],
          'rows': facts['rows'], 'page': str(out) if out else None, **({} if out else {'page_text': page}),
          'reading': 'Read it as an editor reads a cut list: follow what the viewer is waiting for down the page, and '
                     'what each beat gives them. The places to look are facts, never faults: a long quiet stretch or '
                     'a dense one can be exactly right. What you change, you change for the viewer, not for the sheet.'})


def claim_wording_path(vd):
    return vd / 'claim-wording.json'


CLAIM_WORDING_HOW = ('"how" is "hedged" (with "words": the words of the line that carry the doubt or say whose finding '
                     'it is, quoted exactly; "in_line" when they sit in an earlier line of the same beat) or "plain" '
                     '(with "why": what the line states is the part the research confirms, or why it is safe to say '
                     'without a qualifier). A claim that gets a stronger source needs no answer: raise its confidence.')


def _same_words(s):
    return re.sub(r'\s+', ' ', strip_tags(str(s or ''))).strip().lower()


def key_line_claims(rd, video):
    """The script lines that carry a key moment, the payoff or the ending and are tied (claims.json line_refs) to a
    claim the research did not confirm: {line: {text, beat, carries, claims: [{id, confidence, note}], earlier}}.
    'earlier' lists the lines of the same beat up to and including it, where a hedge for it may sit."""
    vd = video_dir(rd, video)
    lines = read_json(vd / 'script.json').get('lines') or []
    ids = [str((l or {}).get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)]
    text = {i: str((l or {}).get('text') or '') for i, l in zip(ids, lines)}
    beats = [b for b in read_json(vd / 'beat-map.json').get('beats') or [] if isinstance(b, dict)]
    span = {}
    for b in beats:
        try:
            mine = ids[int(b['line_start']) - 1:int(b['line_end'])]
        except (KeyError, TypeError, ValueError):
            continue
        for k, x in enumerate(mine):
            span[x] = (str(b.get('id')), mine[:k + 1])
    last = str(beats[-1].get('id')) if beats else None
    cidx = claims_index(read_json(claims_path(rd, video)))
    out = {}
    for lid, tags in script_dependencies(vd).items():
        if lid not in span:
            continue
        carries = [t for t in tags if t.startswith(('key_moment:', 'payoff:'))]
        if span[lid][0] == last:
            carries.append('ending')
        weak = [{'id': c, 'confidence': str(cidx[c].get('confidence') or '').strip().lower(),
                 'note': str(cidx[c].get('note') or '')[:240]}
                for c in (t.split(':', 1)[1] for t in tags if t.startswith('claim:'))
                if c in cidx and str(cidx[c].get('confidence') or '').strip().lower() != 'confirmed']
        if carries and weak:
            out[lid] = {'text': text[lid], 'beat': span[lid][0], 'carries': carries, 'claims': weak,
                        'earlier': span[lid][1]}
    return out, text


def claim_wording_problem(lid, item, ans, text):
    """Why a key line's answer on its unconfirmed claims is not yet one, or None."""
    a = ans if isinstance(ans, dict) else {}
    how = str(a.get('how') or '').strip().lower()
    if not how:
        return 'not answered'
    if _same_words(a.get('text')) != _same_words(item['text']):
        return 'the line was reworded since this answer: answer for the words it has now'
    had = {(str(c.get('id')), str(c.get('confidence') or '').lower()) for c in a.get('claims') or [] if isinstance(c, dict)}
    if {(c['id'], c['confidence']) for c in item['claims']} - had:
        return 'a claim tied to this line changed since this answer'
    if how == 'hedged':
        where = str(a.get('in_line') or lid).strip()
        if where not in item['earlier']:
            return f'"in_line" must be this line or an earlier line of its beat ({item["earlier"][0]}-{lid})'
        words = _same_words(a.get('words'))
        if not words or words not in _same_words(text.get(where)):
            return f'the words quoted are not in {where} as it is written'
        return None
    if how == 'plain':
        return None if n_words(a.get('why')) >= MIN_NOTE_WORDS else '"plain" needs why it is safe to say without a qualifier'
    return '"how" must be hedged or plain'


def claim_wording_facts(rd, video):
    """Key lines resting on claims the research did not confirm, and which of them still wait for the director's
    answer (claim-wording.json). The code never judges the wording: it shows the line beside what the research held,
    and checks that an answer exists for the words as they are (a quoted hedge is really in the line)."""
    items, text = key_line_claims(rd, video)
    ans = read_json(claim_wording_path(video_dir(rd, video))).get('answers') or {}
    why = {}
    for lid, it in items.items():
        p = claim_wording_problem(lid, it, ans.get(lid), text)
        if p:
            why[lid] = p
    return {'lines': len(items), 'open': sorted(why), 'why': why,
            'file': str(claim_wording_path(video_dir(rd, video))) if items else None}


def merge_claim_wording(rd, video):
    """plan-check's side of claim-wording.json: an entry for every key line that needs an answer, with the line as it
    is written and the claims it rests on; an answered entry whose line or claims changed is kept under 'superseded'
    and asked again. Answers are never written here. True when the file changed."""
    vd = video_dir(rd, video)
    items, _ = key_line_claims(rd, video)
    p = claim_wording_path(vd)
    doc = read_json(p)
    if not items and not doc:
        return False
    ans = doc.get('answers') if isinstance(doc.get('answers'), dict) else {}
    changed = False
    for lid, it in items.items():
        cur = ans.get(lid) if isinstance(ans.get(lid), dict) else None
        fresh = {'text': it['text'], 'beat': it['beat'], 'carries': it['carries'], 'claims': it['claims'],
                 'how': '', 'words': '', 'in_line': '', 'why': ''}
        if cur is None:
            ans[lid], changed = fresh, True
            continue
        had = {(str(c.get('id')), str(c.get('confidence') or '').lower()) for c in cur.get('claims') or []
               if isinstance(c, dict)}
        if _same_words(cur.get('text')) != _same_words(it['text']) or \
                {(c['id'], c['confidence']) for c in it['claims']} - had:
            if str(cur.get('how') or '').strip():
                doc.setdefault('superseded', []).append({'line': lid, 'at': now(), **cur})
            ans[lid], changed = fresh, True
    if changed:
        write_json(p, {'how': CLAIM_WORDING_HOW, **{k: v for k, v in doc.items() if k not in ('how', 'answers')},
                       'answers': ans})
    return changed


def plan_facts(rd, video):
    vd = video_dir(rd, video)
    lock = read_json(vd / 'length-lock.json')
    blue = read_json(vd / 'blueprint.json')
    script = read_json(vd / 'script.json')
    beats = read_json(vd / 'beat-map.json')
    issues = []
    if not lock:
        issues.append('missing_locked_length')
        return {'ready': False, 'issues': issues}
    lines = script.get('lines') or []
    if not isinstance(lines, list) or not all(isinstance(x, dict) and str(x.get('text', '')).strip() for x in lines):
        issues.append('missing_or_invalid_script_lines')
        lines = []
    required_blue = ('audience_promise', 'narrative_approach', 'why_this_length', 'original_angle',
                     'visual_grammar', 'factuality')
    for f in required_blue:
        if not str(blue.get(f, '')).strip():
            issues.append('blueprint_missing_' + f)
    # an ending payoff where the video has one; a video whose value builds up (a tutorial, a tour of a mechanism, a
    # run of jokes) says how instead, in reward_shape (2026-11-24: no conventional ending forced on every format)
    if not str(blue.get('ending_payoff', '')).strip() and n_words(blue.get('reward_shape')) < MIN_FIELD_WORDS:
        issues.append('blueprint_missing_ending_payoff_or_reward_shape')
    if blue.get('factuality') == 'factual' and not blue.get('research_sources'):
        issues.append('factual_video_requires_independent_research_sources')
    if str(script.get('language') or '').lower() != str(lock.get('language') or '').lower():
        issues.append('script_language_differs_from_length_lock')
    issues += beat_map_facts(rd, video, lines, lock['target_length_s'])
    issues += subject_handoff_issues(read_json(vd / 'direction.json'), (beats or {}).get('beats') or [])
    issues += value_script_issues(read_json(vd / 'direction.json'), (beats or {}).get('beats') or [], lines,
                                  read_json(claims_path(rd, video)))
    # Spoken words only: inline [audio tags] are sent to ElevenLabs but never spoken (count_words strips them).
    words = sum(count_words(x.get('text', '')) for x in lines)
    tags, tag_issues = script_tags(lines)
    pause_plan, pause_issues = script_pause_plan(lines)
    issues += tag_issues + pause_issues
    # ElevenLabs v4's expressive controls are part of every narration (05): purposeful delivery or pause cues where
    # the story calls for them, never a quota and never decoration. A script with none at all is an exception the
    # user approves in their own words, never a silent default.
    if lines and not tags:
        exc = script.get('tags_exception') if isinstance(script.get('tags_exception'), dict) else {}
        if n_words(exc.get('reason')) < 12 or n_words(exc.get('approved_by_user')) < 2:
            issues.append('no_expressive_tags:plan_purposeful_delivery_or_pause_cues_or_record_tags_exception_'
                          'with_the_users_approval')
    # What reaches the voice: no markup it can't take, no directions that fight each other, and the pronunciation
    # list in the form v4 documents (it changes only what is sent; the canonical text stays for the captions).
    markup_issues, markup_warnings = script_markup(lines)
    issues += markup_issues
    pron = pronunciation_facts(rd, video, lines)
    issues += pron['issues']
    # The silence the edit holds add: decided ones as decided (whole silence less the voice's measured gap there),
    # provisional ones estimated the same way. Never the proposal's whole length on top of the voice's own gap.
    hf = hold_facts(rd, video, lines) if lines else {'holds': [], 'added_s': 0.0, 'voice_gaps': {}, 'undecided': [],
                                                     'decided_narration': [], 'decided_picture': []}
    holds = hf['added_s']
    review = vd / 'editorial-review.md'
    review_text = review.read_text(encoding='utf-8', errors='replace') if review.exists() else ''
    flags, flag_issues = content_flags(lines, review_text, excluded_themes(rd, video))
    issues += flag_issues
    # Every kept tag says why this moment needs it, under "Delivery and tags" (03, 05): selective, not decorative.
    explained = delivery_review_lines(review_text)
    issues += [f'tag_{lid}_not_explained_under_delivery_and_tags'
               for lid in sorted({t['line'] for t in tags}) if lid not in explained]
    warnings = list(markup_warnings) + pron['warnings']
    # Creative direction first (10): the treatment is chosen and locked before the script is written, and it
    # stays the one that was locked. Then one fresh cold read of the script, every finding answered (06).
    gate, dlock, dfacts = direction_gate(rd, video)
    issues += gate
    warnings += dfacts['warnings']
    rc = research_changes(rd, video, dlock)
    if rc:
        warnings.append(research_note(rc))
    warnings += key_moment_evidence_signals(read_json(vd / 'direction.json'), (beats or {}).get('beats') or [],
                                            read_json(claims_path(rd, video)))
    if dlock.get('late_reason'):
        warnings.append('creative direction was locked after the script existed: ' + str(dlock['late_reason']))
    # Made for an earlier direction (or before there was one): updated for real, or explicitly reapproved.
    issues += list(stale_files(rd, video, ('beat-map', 'script')).values())
    for name in (dlock.get('reapproved') or {}):
        ra = reapproved_for(dlock, name)
        if ra:
            warnings.append(f'{name} reapproved for direction revision {ra.get("rev")}: {ra.get("reason")}')
    seen = (dlock.get('reviewed_treatments') or {}).get(str(dfacts.get('chosen_treatment')))
    if seen is not None:
        now_text = treatment_text(chosen_treatment_of(read_json(vd / 'direction.json')))
        if now_text != seen:
            share = _jaccard(_content_tokens(seen), _content_tokens(now_text))
            warnings.append(f'the chosen treatment was refined after its blind read ({share:.0%} of its vocabulary is '
                            'still what the reader saw)')
    snapshot ={str(r.get('id') or f'L{i + 1:03d}'): str(r.get('text') or '') for i, r in enumerate(lines)}
    script_review = review_state(vd, 'script', script_hash(lines), snapshot, holds=hold_snapshot(lines)) if lines else \
        {'issues': ['script_review_missing'], 'warnings': [], 'rounds': 0}
    issues += script_review['issues']
    warnings += script_review['warnings']
    measured = voice_measurement(rd, video)
    tag_s = round(sum(tag_cost_s(t['tag'], measured.get('tag_costs_s')) for t in tags), 2)
    # Each cue as a band (its own evidence named): the forecast is a range wherever the evidence is limited, and
    # several cues in one passage are not assumed to add up exactly (05).
    tag_bands = [{**tag_estimate(t['tag'], t.get('category'), measured), 'line': t['line']} for t in tags]
    tag_low = round(sum(b['low_s'] for b in tag_bands), 2)
    tag_high = round(sum(b['high_s'] for b in tag_bands), 2)
    # A delivery cue colours the rest of its own line (every script line is sent on its own text line): the line
    # names the words it should colour and where the delivery returns (cue_scope), so a local change stays local.
    by_lid = {str(r.get('id') or f'L{i + 1:03d}'): r for i, r in enumerate(lines)}
    issues += [f'tag_{lid}_needs_its_scope' for lid in
               sorted({t['line'] for t in tags if t.get('category') != 'pause'})
               if n_words((by_lid.get(lid) or {}).get('cue_scope')) < 3]
    # A pause cue goes before the words that follow the silence: ElevenLabs "Place a tag before the words it affects",
    # and their examples put it before the next words or on its own line. At a line's end it is undocumented; one
    # measured there (eleven_v4, 2026-11-22) left about 0.2 s over the voice's usual gap.
    warnings += [f'{lid}: a pause cue at the end of the line; ElevenLabs places a tag before the words it affects: put it '
                 'at the start of the next line, before the words after the silence'
                 for lid in sorted({t['line'] for t in tags if t.get('category') == 'pause' and t.get('at_line_end')})]
    pace = float(script.get('pace_wpm') or lock.get('pace_wpm') or 0)
    if not pace:
        issues.append('script_missing_narration_pace')
    target = lock['target_length_s']
    # Narration = spoken words at a pace + the voice's natural gap after every line + what the tags add.
    # A pause the story wants longer than the voice's own gap there exists only if it is realised (pause_via): a tag
    # (inside the narration) or an edit hold, which adds only the difference between the whole silence wanted and the
    # gap the voice left (`holds`). Planned pauses are never sent to ElevenLabs.
    early_narr = (words * 60 / pace + DEFAULT_LINE_OVERHEAD_S * len(lines) + tag_s) if pace else 0
    forecast = round(early_narr + holds, 2) if pace else 0
    real_narr = real = None
    if measured.get('wpm') and lines:
        pace_real = float(measured.get('forecast_wpm') or measured['wpm'])
        real_narr = round(words * 60 / pace_real + measured['per_line_overhead_s'] * len(lines) + tag_s, 2)
        real = round(real_narr + holds, 2)
        # Once this voice is measured, the forecast has to land where export-check will look.
        if abs(real - target) > max(4, target * lock.get('tolerance_export_pct', .025)):
            issues.append('real_forecast_outside_export_tolerance')
    elif pace and abs(forecast - target) > max(10, .08 * target):
        issues.append('script_forecast_misses_locked_length_by_over_8pct')
    # A script that misses the lock is first a question about the lock, not about the script: the story's own size
    # goes to the user before anything is added to reach a length (2026-11-26). And a script that has grown far past
    # its first complete draft says what the added lines carry.
    length_conflict = None
    est = real if real is not None else (forecast if pace else None)
    if est is not None and lines and {'real_forecast_outside_export_tolerance',
                                      'script_forecast_misses_locked_length_by_over_8pct'} & set(issues):
        mine = lock.get('mode') == 'story' and not media_present(rd, video, 'narration')
        relock = ('re-lock to it (length --mode story --minutes N --revise "why"): the story sets this length and '
                  'nothing is recorded yet, so that is yours to do')
        length_conflict = {
            'story_runs_s': est, 'locked_s': target, 'difference_s': round(est - target, 1),
            'what_to_do_first': (
                'The script as written is the story\'s own size. '
                + (f'Before adding anything, {relock}. ' if mine else
                   'Take that size to the user before adding anything: a shorter length (length --revise '
                   '--user-approved) is the first answer. ')
                + 'Material is added only when the film lacks something the viewer needs, which the direction names; '
                  'never to reach a length.'
                if est < target else
                'The script runs longer than the lock. Cut what a listener would drift through first (the boredom '
                'pass). If what is left still runs long, '
                + (f'{relock}' if mine else 'the longer length is the user\'s decision (length --revise --user-approved)')
                + '; a strong passage is never cut only to fit.')}
    script_size, grew = script_size_facts(vd, words)
    if grew:
        issues.append(grew)
    cw = claim_wording_facts(rd, video) if lines else {'lines': 0, 'open': [], 'why': {}, 'file': None}
    if cw['open']:
        issues.append('key_lines_on_unconfirmed_claims_need_their_wording_answered:' + ','.join(cw['open'])
                      + ':claim-wording.json')
    opening, opening_said = opening_facts(rd, video, lines, pace)
    if opening_said:
        warnings.append(opening_said)
    # the opening was chosen among several by fresh readers, or is the only one possible (planning rules 6)
    contest = opening_state(rd, video, lines)
    issues += contest['issues']
    warnings += contest['warnings']
    # Held silence never stands in for story, and never makes the length. The content is the narration with the voice's
    # own gaps and its delivery tags; the silence is what the edit holds add plus what pause tags perform. When the
    # content alone falls short of the window and the silence is what reaches it, the length is being padded: blocked.
    # The answer is the story (more substance, or an authorised length revision), never longer silences.
    band = max(4, target * lock.get('tolerance_export_pct', .025)) if real is not None else max(10, .08 * target)
    pause_tag_s = round(sum(tag_cost_s(t['tag'], measured.get('tag_costs_s')) for t in tags
                            if t.get('category') == 'pause'), 2)
    narr = real_narr if real_narr is not None else (round(early_narr, 2) if pace else None)
    content_s = round(narr - pause_tag_s, 2) if narr is not None else None
    carried = round(max(0.0, (target - band) - content_s), 1) if content_s is not None else None
    if carried and content_s + pause_tag_s + holds >= target - band:
        issues.append(f'runtime_reached_with_held_silence:{carried:g}s:the_words_alone_fall_short_of_the_length')
    ref_pp = [p for p in (lock.get('reference_pause_profiles') or {}).values() if p]
    edit_holds = [p for p in pause_plan if p['via'] == 'edit']
    holds_info = {'edit_holds': len(edit_holds), 'edit_holds_s': holds,
                  'tag_pauses': sum(1 for p in pause_plan if p['via'] == 'tag'), 'pause_tag_s': pause_tag_s,
                  'share_of_runtime': round(holds / target, 3) if target else None,
                  'content_forecast_s': content_s, 'runtime_carried_by_holds_s': carried,
                  'longest_added_s': max((h.get('added_s') or 0 for h in hf['holds']), default=0),
                  'undecided': hf['undecided'], 'decided_after_narration': hf['decided_narration'],
                  'decided_with_picture': hf['decided_picture'], 'voice_gaps': hf['voice_gaps'],
                  'each': [{k: h.get(k) for k in ('line', 'beat', 'status', 'natural_gap_s', 'added_s',
                                                   'added_is_estimate', 'total_s')} for h in hf['holds']],
                  'references_longest_pause_s': max((p.get('longest_pause_s') or 0 for p in ref_pp), default=None),
                  'references_pauses_1_5s_plus_per_min': round(statistics.mean(
                      [p['pauses_1_5s_plus_per_min'] for p in ref_pp if p.get('pauses_1_5s_plus_per_min') is not None]), 2)
                  if any(p.get('pauses_1_5s_plus_per_min') is not None for p in ref_pp) else None}
    older = [p['line'] for p in pause_plan if p['form'] == 'added']
    if older:
        warnings.append('pauses in the older form (pause_after_s: silence added on top of the voice\'s own gap): '
                        + ','.join(older) + '. Each is decided against the recorded voice (holds, hold-decide) before '
                        'the edit; a new script writes pause_total_s, the whole silence wanted')
    warnings += hold_signals(pause_plan)
    # What a first-time viewer has to hold at once, and names coming back after a long absence (03): facts to reason
    # about, never a gate and never a reason to simplify by default.
    signals = comprehension_signals(lines, beats.get('beats') or [], pace or 150,
                                    script.get('language') or lock.get('language') or 'en')
    warnings += signals
    # Each signal is classified in context (a Comprehension section of editorial-review.md: its line id, one kind and
    # the decision): density can be the point, a mystery held on purpose, or a fix in order, context or picture.
    comp = editorial_section(review_text, 'comprehension')
    ids_ = [str((l or {}).get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)]
    line_beat = {}
    for b in beats.get('beats') or []:
        try:
            for x in ids_[int(b['line_start']) - 1:int(b['line_end'])]:
                line_beat[x] = str(b.get('id'))
        except (KeyError, TypeError, ValueError):
            continue
    loose, apart = comprehension_unclassified(signals, comp, line_beat)
    if loose:
        issues.append('comprehension_signals_not_classified_in_the_editorial_review:' + ','.join(loose[:12])
                      + ':under_a_Comprehension_heading_one_of_' + '/'.join(COMPREHENSION_KINDS)
                      + '_(signals_with_a_shared_name_or_beat_may_share_a_line)')
    if apart:
        issues.append('comprehension_signals_grouped_without_a_shared_cause:' + ','.join(apart[:12])
                      + ':answer_each_on_its_own_line_(a_line_answers_together_only_signals_that_share_a_name_or_a_beat)')
    # A name the viewer last heard long ago, returning inside a key moment, is what that moment's meaning rests on:
    # calling it a mystery is right only when the beat withholds it on purpose (depends_on with "withheld"); otherwise
    # it has to be made available where it is needed (storytelling brief, 2026-11-24: a climax that leaned on two
    # places named once, long before, was classified as a mystery and passed).
    issues += key_moment_dependency_issues(signals, comp, beats.get('beats') or [], ids_)
    if n_words(blue.get('audience_knows')) < MIN_FIELD_WORDS:
        issues.append('blueprint_missing_audience_knows:what_the_intended_viewer_already_knows_(nothing_they_know_is_'
                      'explained,_nothing_they_lack_is_assumed)')
    pp = lock.get('pace_profile') or {}
    density = {'script_words': words, 'words_per_runtime_minute': round(words / (target / 60)) if target else None,
               'references_overall_wpm': pp.get('overall_wpm'), 'references_runtime_wpm': pp.get('runtime_wpm'),
               'target_words': lock.get('target_words')}
    # Research <-> script: a line that states a number (a date, a count, a distance) and is tied to no claim.
    # Not blocking (a count of sides or the narrator's premise needs none); each consequential one gets a claim
    # before its part is recorded, because a wrong number found later costs a re-record.
    claims = read_json(rd / '30-research' / f'video-{int(video):02d}' / 'claims.json')
    covered = {r for c in (claims.get('claims') or []) for r in (c.get('line_refs') or [])}
    number_rx = re.compile(r"\d|\b(two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|"
                           r"fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|"
                           r"eighty|ninety|hundred|thousand|million)\b", re.I)
    numbers_without_claim = [str(x.get('id')) for x in lines
                             if number_rx.search(strip_tags(x.get('text') or '')) and str(x.get('id')) not in covered]
    beat_list = (beats or {}).get('beats') or []
    if (beat_list and n_words(blue.get('reward_shape')) < MIN_FIELD_WORDS
            and not any(b.get('key_moment') not in (None, False) and str(b.get('key_moment')).strip()
                        for b in beat_list)):
        # a video whose value builds up says so in reward_shape and needs no key moment; one that turns or pays off
        # names where (key_moment + significance), so the readers' accounts can be weighed against it
        warnings.append('no beat is marked as a key moment: name the developments this video is built around, what each '
                        'means to its viewer and what it pays (beat map key_moment + significance), or, when its value '
                        'builds up instead, say how in the blueprint\'s reward_shape')
    # The narrators this narration follows (decision.pacing): their measured range and how this script's forecast moves
    # across it, beside the voice pace that would land the locked length. A narrator is chosen on quality; the voice's
    # measured pace on real parts decides; a mismatch is diagnosed (the voice, the script's density, the delivery or the
    # length) before any length change, which is the user's (2026-11-25). Facts and a warning, never a gate.
    export_band = max(4, target * lock.get('tolerance_export_pct', .025)) if target else 0
    pacing = pacing_facts(rd, video, lines, words, DEFAULT_LINE_OVERHEAD_S * len(lines) + tag_s + holds, target,
                          export_band, pace or None, script.get('language') or lock.get('language') or 'en')
    rng, fit = pacing.get('range'), pacing.get('voice_pace_that_fits_the_lock_wpm')
    if rng and pace and not rng['active_wpm'][0] <= pace <= rng['active_wpm'][1]:
        warnings.append(f"pacing: the locked length is planned at {pace:g} wpm, outside the narrators this narration "
                        f"follows ({rng['active_wpm'][0]}-{rng['active_wpm'][1]} wpm while speaking, "
                        f"{','.join(rng['relevant'])}): weigh the voice, the script's density, the delivery and the length "
                        "before any change; a length change is the user's")
    if rng and fit and rng.get('forecast') and (rng['active_wpm'][0] < fit[0] or rng['active_wpm'][1] > fit[1]):
        rf = rng['forecast']
        warnings.append(f"pacing: at the relevant narrators' pace ({rng['active_wpm'][0]}-{rng['active_wpm'][1]} wpm while "
                        f"speaking) this script would run {rf['at_fastest']['minutes']}-{rf['at_slowest']['minutes']}; "
                        f"the locked length fits a voice at about {fit[0]:g}-{fit[1]:g} wpm while speaking (with a "
                        f"{DEFAULT_LINE_OVERHEAD_S:g} s gap a line). A forecast, never a target for the delivery: choose "
                        "the narrator on quality, judge its pace on representative real recordings, and take a real "
                        "conflict with the length to the user with its evidence (voice, density, delivery or length); "
                        "the voice is never forced to fit")
    voice_pace = measured.get('forecast_wpm') or measured.get('wpm')
    if voice_pace and script.get('pace_wpm') and abs(float(script['pace_wpm']) - float(voice_pace)) > 3:
        warnings.append(f"script pace_wpm {script['pace_wpm']} differs from the voice's measured {voice_pace} "
                        "(script words per speech minute); the real forecast uses the measured one: set the script's "
                        "pace_wpm to it so one number is in use")
    if not review.exists():
        issues.append('editorial_review_missing')
    # The film on one page: the few places worth a look before a reader, a voice or a picture is paid for (facts,
    # never faults; `run-sheet` prints the whole page)
    sheet = run_sheet_facts(rd, video) if lines else {'basis': None, 'look_at': [], 'totals': {}}
    warnings += sheet['look_at']
    older_plan_advisory(rd, video, issues, warnings)
    return {'ready': not issues, 'issues': issues, 'warnings': warnings, 'script_lines': len(lines),
            'run_sheet': {'basis': sheet['basis'], 'totals': sheet['totals'], 'look_at': sheet['look_at'],
                          'whole_page': 'run-sheet --run RUN --video NN'},
            'words': words, 'narration_pace_wpm': pace,
            'pace_sources': {'references_wpm': lock.get('pace_wpm'), 'references_overall_wpm': pp.get('overall_wpm'),
                             'script_wpm': script.get('pace_wpm'), 'voice_measured_wpm': measured.get('wpm'),
                             'voice_overall_wpm': measured.get('overall_wpm'),
                             'voice_per_line_gap_s': round(measured['per_line_overhead_s'], 3) if measured else None},
            'audio_tags': tags, 'tag_time_s': tag_s, 'tag_time_range_s': [min(tag_low, tag_s), max(tag_high, tag_s)], 'tag_estimates': tag_bands, 'pause_plan': pause_plan, 'edit_holds_s': holds,
            'holds': holds_info, 'density': density, 'pacing': pacing,
            'pronunciation': {'file': pron['file'], 'terms': [{k: t[k] for k in ('term', 'say', 'how', 'confidence')}
                                                              | {'lines': len(pron['uses'].get(t['term']) or [])}
                                                              for t in pron['terms']]},
            'content_flags': flags, 'numbers_without_claim': numbers_without_claim,
            'creative': {'direction_locked': bool(dlock), 'locked_late': bool(dlock.get('late_reason')),
                         'treatment': dfacts.get('chosen_treatment'), 'production_rev': dlock.get('production_rev'),
                         'outdated': outdated_artifacts(rd, video), 'script_review_rounds': script_review['rounds'],
                         'majors_closed_by_decision': script_review.get('majors_closed_by_decision') or [],
                         # why each open answer is not yet an answer (a finding waiting for the user says so)
                         'answers_needed': script_review.get('answers_needed') or {},
                         # when the reader knew what the video offers, beside the title's promise and the references
                         'opening': opening or None,
                         # the opening contest: who would keep watching which opening, and which was chosen
                         'opening_contest': contest['facts'] or None,
                         # key lines resting on claims the research did not confirm, and which still wait for an answer
                         'claim_wording': cw},
            'script_size': script_size, 'length_conflict': length_conflict,
            'writing_signals': writing_signals(lines, lock.get('language') or script.get('language') or 'en'),
            'forecast_s': forecast, 'real_narration_forecast_s': real_narr, 'real_forecast_s': real,
            # The point uses each cue's measured cost at its place, a delivery cue's band the whole line's change: when
            # the two disagree the range covers both, so it always holds the point it is published with.
            'real_forecast_range_s': ([round(real - max(0.0, tag_s - tag_low), 2), round(real + max(0.0, tag_high - tag_s), 2)]
                                      if real is not None else None),
            'locked_target_s': target,
            'export_window_s': [round(target - max(4, target * lock.get('tolerance_export_pct', .025)), 2),
                                round(target + max(4, target * lock.get('tolerance_export_pct', .025)), 2)],
            'target_words_without_pauses': round(target * pace / 60) if pace else None,
            'target_words_with_reference_pauses': lock.get('target_words')}


def plan_check_path(rd, video):
    return video_dir(rd, video) / 'plan-check.json'


def beat_line_state(vd, with_rows=False):
    """Per beat: its direction's hash (its line numbers left out: a line added earlier shifts them) and its lines' text
    hash. with_rows: the beat itself too, under 'row' (never stored)."""
    lines = read_json(vd / 'script.json').get('lines') or []
    out = {}
    for b in read_json(vd / 'beat-map.json').get('beats') or []:
        if not isinstance(b, dict):
            continue
        out[str(b.get('id'))] = {'sha': part_sha(b), 'lines_sha': canonical_sha(beat_lines_text(b, lines)),
                                 'lines': [b.get('line_start'), b.get('line_end')], **({'row': b} if with_rows else {})}
    return out


def beat_line_issues(rd, video, keep=''):
    """A beat whose direction changed since the last passing plan-check while its lines did not: its lines were written
    for the old beat (2026-11-24 audit: changed beats did not flag their lines). Revise them, or keep them with a reason
    (plan-check --keep)."""
    rec_all = read_json(plan_check_path(rd, video))
    rec = rec_all.get('beats') or {}
    if not rec or keep:
        return []
    # the director's explicit answer for the direction change that moved these beats: the script stands as it is
    ra = reapproved_for(read_json(video_dir(rd, video) / 'direction-lock.json'), 'script')
    if ra and str(ra.get('at') or '') > str(rec_all.get('checked_at') or ''):
        return []
    out = []
    for bid, now_ in beat_line_state(video_dir(rd, video), with_rows=True).items():
        was = rec.get(bid)
        if was and not part_unchanged(was.get('sha'), now_['row'], now_['sha']) \
                and was.get('lines_sha') == now_['lines_sha']:
            out.append(f'beat_{bid}_changed_since_its_lines_were_checked:L{now_["lines"][0]}-L{now_["lines"][1]}:'
                       'revise_them_or_plan-check_--keep_"why_they_still_fit"')
    return out


def cmd_plan_check(args):
    rd, st = run_folder(args)
    keep = getattr(args, 'keep', '') or ''
    if keep and n_words(keep) < MIN_NOTE_WORDS:
        error('Say why the lines of the changed beats still fit (a few words at least).')
    grew_for = getattr(args, 'grew_for', '') or ''
    if grew_for and n_words(grew_for) < MIN_NOTE_WORDS:
        error('--grew-for says what the lines added since the first complete draft carry (which value, development or '
              'viewer need). "To reach the length" is not an answer: that is the user\'s length decision.')
    result = plan_facts(rd, args.video)
    # plan-check's own records, written before the verdict is read: the first complete draft's size (once), an answer
    # to "why did it grow", and the entries of claim-wording.json the director answers
    if any([record_script_size(rd, args.video, result.get('words'), result.get('forecast_s'), grew_for)
            if 'words' in result else False, merge_claim_wording(rd, args.video) if 'words' in result else False]):
        result = plan_facts(rd, args.video)
    bl = beat_line_issues(rd, args.video, keep)
    if bl:
        result['issues'] = result['issues'] + bl
        result['ready'] = False
    if result['ready']:
        prev = read_json(plan_check_path(rd, args.video))
        write_json(plan_check_path(rd, args.video), {
            'checked_at': now(), 'beats': beat_line_state(video_dir(rd, args.video)),
            # the pacing evidence this passing check saw: each weighed narrator as measured, the script's density, the
            # range, the sensitivity, the voice pace that fits, and what the comparison left out
            'pacing': {k: (result.get('pacing') or {}).get(k) for k in (
                'references', 'script_density', 'range', 'sensitivity', 'planning_wpm',
                'voice_pace_that_fits_the_lock_wpm', 'not_weighed', 'relevant_unmeasured')},
            'history': (prev.get('history') or []) + ([{'at': now(), 'kept': keep}] if keep else [])})
        advance_stage(rd, 'script_checked')
    emit({'video': int(args.video), **result}, 0 if result['ready'] else 2)


def chunks_for_lines(lines, maximum):
    chunks = []
    cur, start = [], None
    for i, row in enumerate(lines, 1):
        text = str(row['text']).strip()
        if len(text) > maximum:
            error('One script line exceeds safe TTS request size: split it into complete sentences.', {'line': i, 'chars': len(text)})
        new = '\n'.join(cur + [text])
        if cur and len(new) > maximum:
            chunks.append({'line_start': start, 'line_end': i-1, 'text': '\n'.join(cur)})
            cur, start = [], None
        if start is None:
            start = i
        cur.append(text)
    if cur:
        chunks.append({'line_start': start, 'line_end': len(lines), 'text': '\n'.join(cur)})
    return chunks


def chunks_from_manifest(old_chunks, lines):
    """Keep the recorded parts' line boundaries, so editing one line changes only the part that holds it
    (fresh greedy chunking would shift every later boundary and force a full re-record). None when the
    boundaries no longer cover the script exactly (lines were added or removed)."""
    out, cursor = [], 0
    for c in old_chunks:
        try:
            lo, hi = int(c['line_start']), int(c['line_end'])
        except (KeyError, TypeError, ValueError):
            return None
        if lo != cursor + 1 or hi < lo or hi > len(lines):
            return None
        out.append({'line_start': lo, 'line_end': hi,
                    'text': '\n'.join(str(r['text']).strip() for r in lines[lo - 1:hi])})
        cursor = hi
    return out if cursor == len(lines) else None


def model_limit(model):
    # GET /v1/models, 2026-11-19, and ElevenLabs' v4 migration guide: eleven_v4 and eleven_v4_turbo take 10,000
    # characters per request. model_rates() reads the live maximum_text_length_per_request before any paid request.
    known = {'eleven_v4': 10000, 'eleven_v4_turbo': 10000}
    return known.get(model, 3000)


# ---------------------------------------------------------------- parts that follow the story
PART_TARGET_CHARS = 3500     # an engineering guideline for one request, not a rule
PART_SOFT_MAX = 1.5          # a whole beat may run to this multiple of the target before it is split
# A part that follows the beat map's chapters (beats marked chapter_start) may hold a whole chapter up to this size:
# one request of ~7,000 characters took ~95 s here (measured ~75 characters a second), well inside the 180 s wait.
PART_CHAPTER_MAX = 7000


def _split_long_beat(lines, sizes, lo, hi, target, hard_max):
    """One beat too long for one part, cut between lines into pieces of about `target` characters: at each even
    split, the nearby line end (within a quarter of the target) after which the story already breathes (a planned
    pause), else the nearest line end. Never inside a line, never above hard_max."""
    total = sum(sizes[lo - 1:hi])
    k = max(2, math.ceil(total / target))
    ends, acc = [], 0
    for j in range(lo, hi + 1):
        acc += sizes[j - 1]
        ends.append((j, acc))
    pieces, start = [], lo
    for q in range(1, k):
        goal = total * q / k
        options = [(j, c) for j, c in ends if start <= j < hi]
        if not options:
            break
        near = [x for x in options if abs(x[1] - goal) <= 0.25 * target] or \
            [min(options, key=lambda x: abs(x[1] - goal))]
        pause_len = lambda row: float(row.get('pause_total_s') or row.get('pause_after_s') or 0)   # either form
        j = max(near, key=lambda x: (pause_len(lines[x[0] - 1]) > NATURAL_PAUSE_MAX_S,
                                     pause_len(lines[x[0] - 1]) > 0, -abs(x[1] - goal)))[0]
        pieces.append((start, j))
        start = j + 1
    pieces.append((start, hi))
    out = []
    for a, z in pieces:
        while z > a and sum(sizes[a - 1:z]) > hard_max:
            m, acc = a, sizes[a - 1]
            while m + 1 <= z and acc + sizes[m] <= hard_max:
                acc += sizes[m]
                m += 1
            out.append((a, m))
            a = m + 1
        if a <= z:
            out.append((a, z))
    return out


def chunks_for_beats(lines, beats, target=PART_TARGET_CHARS, hard_max=10000):
    """Parts that follow the story: whole beats, short neighbouring beats together up to about `target` characters, a
    beat longer than PART_SOFT_MAX x target split between lines where it already breathes. A join falls where the
    story turns, re-recording an edited line costs about one beat, and the calibration part is the opening. Never
    inside a line, never above hard_max; plain line packing when the beat map doesn't cover the script."""
    for i, row in enumerate(lines, 1):
        if len(str(row['text']).strip()) > hard_max:
            error('One script line exceeds safe TTS request size: split it into complete sentences.',
                  {'line': i, 'chars': len(str(row['text']).strip())})
    n = len(lines)
    sizes = [len(str(r['text']).strip()) + 1 for r in lines]
    spans, cursor = [], 0
    for b in beats or []:
        try:
            lo, hi = int(b['line_start']), int(b['line_end'])
        except (KeyError, TypeError, ValueError):
            spans = []
            break
        if lo != cursor + 1 or hi < lo or hi > n:
            spans = []
            break
        spans.append((lo, hi, str(b.get('id'))))
        cursor = hi
    if not spans or cursor != n:
        return [{**c, 'beats': []} for c in chunks_for_lines(lines, max([target] + sizes))]
    # The story's own chapters, when the beat map marks them: a recording boundary sits only where the story itself
    # starts again, so the narrator's fresh start (and the previous part's last landing) falls where one belongs (05).
    starts = {str(b.get('id')) for b in beats or [] if b.get('chapter_start')}
    if starts:
        chapters = []
        for lo, hi, bid in spans:
            if not chapters or bid in starts:
                chapters.append([])
            chapters[-1].append((lo, hi, bid))
        out = []
        for ch in chapters:
            lo, hi = ch[0][0], ch[-1][1]
            size = sum(sizes[lo - 1:hi])
            if size <= min(PART_CHAPTER_MAX, hard_max):
                out.append({'line_start': lo, 'line_end': hi, 'beats': [b for _, _, b in ch], 'chapter': True,
                            'text': '\n'.join(str(r['text']).strip() for r in lines[lo - 1:hi])})
            else:          # a chapter too long for one request: split between its beats (flagged, listened to)
                sub = chunks_for_beats(lines[lo - 1:hi], [{'id': b, 'line_start': a - lo + 1, 'line_end': z - lo + 1}
                                                          for a, z, b in ch], target, hard_max)
                for c in sub:
                    out.append({**c, 'line_start': c['line_start'] + lo - 1, 'line_end': c['line_end'] + lo - 1,
                                'chapter': False, 'split_inside_chapter': True})
        return out
    units = []
    for lo, hi, bid in spans:
        if sum(sizes[lo - 1:hi]) > target * PART_SOFT_MAX:
            units += [(a, z, bid) for a, z in _split_long_beat(lines, sizes, lo, hi, target, hard_max)]
        else:
            units.append((lo, hi, bid))
    parts = []
    for a, z, bid in units:
        c = sum(sizes[a - 1:z])
        if parts and parts[-1]['chars'] + c <= min(target * 1.1, hard_max):
            p = parts[-1]
            p['hi'], p['chars'] = z, p['chars'] + c
            if bid not in p['beats']:
                p['beats'].append(bid)
        else:
            parts.append({'lo': a, 'hi': z, 'chars': c, 'beats': [bid]})
    if len(parts) > 1 and parts[-1]['chars'] < 0.35 * target and \
            parts[-2]['chars'] + parts[-1]['chars'] <= min(target * PART_SOFT_MAX, hard_max):
        last = parts.pop()
        parts[-1]['hi'] = last['hi']
        parts[-1]['chars'] += last['chars']
        parts[-1]['beats'] += [b for b in last['beats'] if b not in parts[-1]['beats']]
    return [{'line_start': p['lo'], 'line_end': p['hi'], 'beats': p['beats'],
             'text': '\n'.join(str(r['text']).strip() for r in lines[p['lo'] - 1:p['hi']])} for p in parts]


def context_text(sent_lines, start, step, limit=500):
    """Whole neighbouring lines, spoken words only (their tags removed: those directed the other part), up to about
    `limit` characters, walking from line `start` (1-based) by `step`: -1 for what the previous part ended with, +1
    for what the next one starts with. Sent as previous_text / next_text, which ElevenLabs documents for continuity
    when generations are joined."""
    out, total, i = [], 0, start
    while 1 <= i <= len(sent_lines) and total < limit:
        t = strip_tags(sent_lines[i - 1])
        if t:
            out.append(t)
            total += len(t) + 1
        i += step
    if step < 0:
        out.reverse()
    return '\n'.join(out)


def language_code(language):
    """Eleven v4's language_code: ISO 639-1 for most languages, ISO 639-3 for the few without one ('fil', 'yue')."""
    code = re.split(r'[-_]', str(language or '').strip().lower())[0]
    return code if re.fullmatch(r'[a-z]{2,3}', code) else None


def voice_calibrated(rd, video, voice_id, model_id, settings):
    """True when this exact voice, model and settings has a real measured pace from a part of 300+ words."""
    m = voice_measurement(rd, video)
    if not m:
        return False
    if m.get('source') == 'hand-recorded (older run)':
        return m.get('voice_id') == voice_id and (m.get('settings') or {}) == (settings or {})
    return _measured_matches(m, voice_id, model_id, settings)


def preflight_elevenlabs_balance(key, remaining_characters, safety_factor=1.15):
    """Check the subscription character allowance before ANY billable TTS call.

    Character allowance is not a guaranteed monetary-credit estimate for every
    model, tier or negotiated contract. Require human verification of the actual
    model's price, even when this preliminary guard passes.
    """
    req = urllib.request.Request('https://api.elevenlabs.io/v1/user/subscription',
                                 headers={'xi-api-key': key}, method='GET')
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            data = json.loads(resp.read())
    except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError, ValueError) as exc:
        error('Cannot verify ElevenLabs subscription balance; no paid TTS requests were made.',
              f'{type(exc).__name__}: {str(exc)[:180]}')
    try:
        remaining = int(data['character_limit']) - int(data['character_count'])
    except (KeyError, TypeError, ValueError) as exc:
        error('Subscription API returned no usable character allowance; no paid TTS requests were made.', str(exc))
    needed = math.ceil(remaining_characters * safety_factor)
    if remaining < needed:
        error('Insufficient reported ElevenLabs character allowance for this entire remaining narration.',
              {'available_character_allowance': remaining, 'required_characters': remaining_characters,
               'reserve_adjusted_minimum': needed, 'note': 'Verify actual credit pricing for your model; overage was not assumed.'})
    return {'subscription_status': data.get('status'), 'available_character_allowance': remaining,
            'remaining_script_characters': remaining_characters, 'reserve_adjusted_minimum': needed,
            'warning': 'This check is based on character allowance, not model-specific credit cost; no guarantee against quota or billing limits.'}


def elevenlabs_request(method, path, key, body=None, params=None, timeout=60):
    url = 'https://api.elevenlabs.io' + path
    if params:
        url += '?' + urllib.parse.urlencode(params)
    headers = {'xi-api-key': key}
    data = None
    if body is not None:
        data = json.dumps(body).encode('utf-8')
        headers['Content-Type'] = 'application/json'
    req = urllib.request.Request(url, data=data, method=method, headers=headers)
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read())


# ---------------------------------------------------------------- what ElevenLabs costs, and what it really billed
# ElevenLabs documents a per-model credit multiplier (GET /v1/models: model_rates.character_cost_multiplier, times
# cost_discount_multiplier) and the live allowance (GET /v1/user/subscription: character_limit - character_count, both
# free). It does not document whether tags, spaces, line breaks or previous_text/next_text are billed, so a request's
# characters are counted as its whole `text` (tags and line breaks included, context excluded), and every billed request
# is written to RUN/logs/elevenlabs-ledger.jsonl with the balance just before and just after it: the real cost, measured.
def ledger_path(rd):
    return rd / 'logs' / 'elevenlabs-ledger.jsonl'


def ledger_add(rd, entry):
    p = ledger_path(rd)
    p.parent.mkdir(parents=True, exist_ok=True)
    with p.open('a', encoding='utf-8') as f:
        f.write(json.dumps(entry, ensure_ascii=False) + '\n')


def ledger_rows(rd):
    p = ledger_path(rd)
    rows = []
    if p.is_file():
        for i, line in enumerate(p.read_text(encoding='utf-8', errors='replace').splitlines(), 1):
            if not line.strip():
                continue
            try:
                rows.append(json.loads(line))
            except ValueError:
                # A row that cannot be read may be a request that was sent and billed: skipping it would count the
                # money as unspent (2026-11-26). The ledger is the money record; it is looked at, never guessed past.
                error('The paid ledger has a row that cannot be read. Nothing was sent. Look at that line: complete it '
                      'from ElevenLabs\' history, or remove it if no request was made, then run this again.',
                      {'file': str(p), 'line': i, 'text': line[:160]})
    return rows


def measured_cost_ratio(rd, model_id):
    """Credits this account was really billed per character sent on this model, from the ledger: ElevenLabs'
    character-cost header where the request has one (measured 2026-11-20: it equals the balance drop, which shows
    up only some seconds later), else the balance drop (other use of the account between the two balance reads can
    only push it up): (median, number of requests)."""
    ratios = []
    for r in ledger_rows(rd):
        if r.get('model_id') != model_id or r.get('kind') not in ('tts', 'probe', 'trial') or not r.get('ok') \
                or not r.get('characters') or r.get('phase') == 'pending':
            continue
        c = r.get('character_cost_header')
        if c is None and isinstance(r.get('delta'), (int, float)) and r['delta'] > 0:
            c = r['delta']
        if isinstance(c, (int, float)) and c >= 0:
            ratios.append(c / r['characters'])
    return (round(statistics.median(ratios), 3), len(ratios)) if ratios else (None, 0)


def subscription_balance(key):
    """The live allowance (GET /v1/user/subscription, free): credits left = character_limit - character_count. An
    overage the plan may allow is never counted as available."""
    try:
        data = elevenlabs_request('GET', '/v1/user/subscription', key, timeout=20)
        used, limit = int(data['character_count']), int(data['character_limit'])
    except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError, ValueError, KeyError, TypeError) as exc:
        raise RuntimeError(f'cannot read the ElevenLabs balance (nothing was sent): {type(exc).__name__}: {str(exc)[:160]}')
    return {'available': limit - used, 'used': used, 'limit': limit, 'status': data.get('status'),
            'next_reset_unix': data.get('next_character_count_reset_unix'),
            'overage_possible': bool(data.get('can_extend_character_limit'))}


def model_rates(rd, key, model_id, max_age_h=24):
    """What ElevenLabs reports for this model (GET /v1/models, free): credits per character (character_cost_multiplier
    times cost_discount_multiplier), the longest text one request takes, its setting flags. Cached in RUN/logs for a
    day (max_age_h=0 reads it again now: a trial checks the price before every request). A model the account doesn't
    list, or one without a reported cost, stops everything before a paid call."""
    cache = rd / 'logs' / 'elevenlabs-models.json'
    c = read_json(cache)
    try:
        age = (dt.datetime.now(dt.timezone.utc) - dt.datetime.fromisoformat(c['fetched_at'])).total_seconds()
    except (KeyError, TypeError, ValueError):
        age = None
    if age is None or age > max_age_h * 3600 or max_age_h <= 0 or model_id not in (c.get('models') or {}):
        try:
            data = elevenlabs_request('GET', '/v1/models', key, timeout=30)
        except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError, ValueError) as exc:
            raise RuntimeError(f'cannot read the model list (nothing was sent): {type(exc).__name__}: {str(exc)[:160]}')
        models = {m['model_id']: {k: m.get(k) for k in ('model_rates', 'maximum_text_length_per_request', 'can_use_style',
                                                         'can_use_speaker_boost', 'can_do_text_to_speech')}
                  for m in (data if isinstance(data, list) else []) if isinstance(m, dict) and m.get('model_id')}
        c = {'fetched_at': now(), 'models': models}
        write_json(cache, c)
    m = (c.get('models') or {}).get(model_id)
    if not m:
        raise RuntimeError(f'ElevenLabs does not list {model_id} for this account (nothing was sent)')
    rates = m.get('model_rates') or {}
    if rates.get('character_cost_multiplier') is None:
        raise RuntimeError(f'ElevenLabs reported no character_cost_multiplier for {model_id} (nothing was sent)')
    per_char = float(rates['character_cost_multiplier']) * float(rates.get('cost_discount_multiplier') or 1)
    return {'model_id': model_id, 'credits_per_character': round(per_char, 4),
            'character_cost_multiplier': rates.get('character_cost_multiplier'),
            'cost_discount_multiplier': rates.get('cost_discount_multiplier'),
            'maximum_text_length_per_request': m.get('maximum_text_length_per_request'),
            'can_use_style': m.get('can_use_style'), 'can_use_speaker_boost': m.get('can_use_speaker_boost'),
            'fetched_at': c.get('fetched_at')}


def cached_model_rates(rd, model_id):
    """The last model rates read for this run (no network), for a dry run's estimate."""
    m = (read_json(rd / 'logs' / 'elevenlabs-models.json').get('models') or {}).get(model_id) or {}
    r = m.get('model_rates') or {}
    if r.get('character_cost_multiplier') is None:
        return None
    return round(float(r['character_cost_multiplier']) * float(r.get('cost_discount_multiplier') or 1), 4)


def credit_preflight(rd, key, model_id, characters, safety, assume_ratio=None, keep=0, label='this request'):
    """Before any billed request: what the model costs per character (ElevenLabs' own figure, or an explicit,
    recorded --assume-cost-ratio), what this account was really billed so far (the ledger) and the live balance.
    Refuses, with nothing sent, unless the balance covers the expected credits times the safety factor and still
    leaves --keep-credits."""
    rates = model_rates(rd, key, model_id)
    measured, samples = measured_cost_ratio(rd, model_id)
    ratio = float(assume_ratio) if assume_ratio is not None else rates['credits_per_character']
    expected = math.ceil(characters * ratio)
    bal = subscription_balance(key)
    required = math.ceil(expected * safety) + int(keep or 0)
    out = {'characters': characters, 'credits_per_character': ratio,
           'ratio_source': 'assumed (--assume-cost-ratio)' if assume_ratio is not None else 'ElevenLabs model rates',
           'documented_credits_per_character': rates['credits_per_character'],
           'measured_credits_per_character': measured, 'measured_requests': samples,
           'expected_credits': expected,
           'expected_credits_verified': math.ceil(characters * measured) if measured is not None else None, 'safety_factor': safety, 'keep_credits': int(keep or 0),
           'required_available': required, 'available': bal['available'],
           'left_after_expected': bal['available'] - expected, 'next_reset_unix': bal['next_reset_unix'],
           'max_characters_per_request': rates['maximum_text_length_per_request']}
    if bal['available'] < required:
        error(f'Not enough ElevenLabs credits for {label}: nothing was sent.', out)
    return out


def eleven_paid_post(rd, key, path, body, kind, meta, accept='audio/mpeg', timeout=180, require=0, max_credits=None):
    """One billed ElevenLabs request, on record: the live balance just before and just after (free calls), the
    characters sent (the text, and the context fields apart) and what the account was billed, appended to the ledger
    whether it worked or not. A 'pending' row goes in first, so a request cut off by a crash or a power cut is still
    on record (a trial budget counts it at its largest possible charge). The cost: ElevenLabs' `character-cost` reply
    header (documented under "Tracking generation costs"; measured 2026-11-20 on eleven_v4: it is the credits billed,
    the balance falling by exactly that some seconds later), and the balance drop read just after (often 0, since the
    balance lags). When `meta` names credits_per_character, `credits_billed` is the header, else a balance drop seen,
    else unknown (a trial budget then counts the request at its largest possible charge). When the balance just
    before is under `require`, nothing is sent. Returns (raw bytes or None, error or None, entry)."""
    before = subscription_balance(key)
    chars = len(str(body.get('text') or ''))
    ctx = len(str(body.get('previous_text') or '')) + len(str(body.get('next_text') or ''))
    attempt = hashlib.sha256(f'{now()}|{os.getpid()}|{path}|{chars}|{id(body)}'.encode('utf-8')).hexdigest()[:16]
    entry = {'at': now(), 'kind': kind, **meta, 'characters': chars, 'context_characters': ctx,
             'balance_before': before['available'], 'attempt_id': attempt, 'pid': os.getpid()}
    if max_credits is not None:
        entry['max_credits'] = int(max_credits)
    if before['available'] < require:
        return None, f'not sent: {before["available"]} credits left, this request needs {require}', None
    ledger_add(rd, {**entry, 'phase': 'pending'})
    req = urllib.request.Request('https://api.elevenlabs.io' + path, data=json.dumps(body).encode('utf-8'),
                                 method='POST', headers={'xi-api-key': key, 'Content-Type': 'application/json',
                                                         'Accept': accept})
    raw, err, rid, cost, trace, hist, outcome = None, None, None, None, None, None, None
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read()
            hdrs = getattr(resp, 'headers', None)
            if hdrs is not None:
                rid, trace, hist = hdrs.get('request-id'), hdrs.get('x-trace-id'), hdrs.get('history-item-id')
                cost = hdrs.get('character-cost')
    except urllib.error.HTTPError as exc:
        # A refused request (bad input, no access, too many requests: 4xx) is answered before anything is generated;
        # after a server error (5xx) nobody can say whether the work was done and billed.
        err = f'HTTPError {exc.code}: {str(exc)[:240]}'
        outcome = 'failed' if 400 <= int(exc.code or 0) < 500 else 'uncertain'
    except Exception as exc:  # noqa: BLE001  cut off, timed out or unreadable: billed or not is unknown
        err = f'{type(exc).__name__}: {str(exc)[:240]}'
        outcome = 'uncertain'
    try:
        after = subscription_balance(key)['available']
    except (RuntimeError, OSError, ValueError):
        after = None
    try:
        cost = int(float(cost)) if cost not in (None, '') else None
    except (TypeError, ValueError):
        cost = None
    if outcome is None:
        usable = bool(raw) and (len(raw) >= 1024 or str(accept).startswith('application/json'))
        outcome = 'completed' if usable else ('charged_incomplete' if cost else 'uncertain')
    delta = (before['available'] - after) if after is not None else None
    entry.update({'phase': 'done', 'ok': err is None, 'error': err, 'outcome': outcome, 'request_id': rid,
                  'trace_id': trace, 'history_item_id': hist, 'character_cost_header': cost, 'balance_after': after,
                  'delta': delta})
    if meta.get('credits_per_character') is not None:
        entry['credits_billed'] = cost if cost is not None else (
            delta if isinstance(delta, (int, float)) and delta > 0 else None)
    ledger_add(rd, entry)
    return raw, err, entry


def tags_heard(sent_text, heard_text):
    """Delivery tags whose own words Whisper heard more often than the spoken text holds them: most likely read aloud
    ('[softly] Nobody moved.' heard as 'Softly, nobody moved.')."""
    heard, spoken = tokens_of(heard_text), tokens_of(strip_tags(sent_text))
    out = []
    for m in TAG_RE.finditer(sent_text):
        words = [w for w in tokens_of(m.group(1)) if len(w) > 2 and w not in EN_FUNCTION_WORDS]
        if words and sum(1 for w in words if heard.count(w) > spoken.count(w)) * 2 >= len(words):
            out.append(m.group(0))
    return out


def cmd_voice_candidates(args):
    """Suggest up to --count candidate voices (free, from the account's existing voices,
    and/or billed Voice Design previews), save each candidate's preview audio, transcribe
    it (Whisper) and record its preview_wpm with the references' yardstick. A preview is
    short: its pace does not predict the voice's real pace on a full chunk (measured on one
    run: preview 195 -> real 180; a 209 human sample -> 178). Each preview's delivery is
    measured too (pitch range and movement, loudness contrast), because the agents cannot
    listen: they choose for the treatment's narrator from descriptions, transcripts and these
    measurements; the user may listen and overrule. The real pace comes from the calibration part.
    Voice Design is billed (by the characters of its preview text, three voices a call): without --execute this
    only shows what the designs would cost; with --execute the live balance is checked first and every design call
    goes in the spend ledger. Writes a report; picks nothing itself.
    An earlier round's report is kept as candidates-<time>.json, never overwritten."""
    rd, st = run_folder(args)
    vd = video_dir(rd, args.video)
    outdir = rd / '60-voice' / f'video-{int(args.video):02d}' / 'candidates'
    design_n = max(0, args.design)
    free_n = max(0, args.count - design_n)
    text, plan = None, None
    if design_n:
        if not args.design_description:
            error('--design-description is required when --design > 0 '
                  '(the narrator the locked treatment describes: character, register, age, accent, delivery).')
        text = args.design_text
        if not text:
            script = read_json(vd / 'script.json')
            text = ' '.join(strip_tags(l['text']) for l in (script.get('lines') or [])[:8])[:1000]
        if not (100 <= len(text) <= 1000):
            error('Voice Design sample text must be 100-1000 characters.', {'characters': len(text)})
        calls = math.ceil(design_n / 3)
        plan = {'design_calls': calls, 'preview_characters': len(text), 'expected_credits': calls * len(text),
                'reserve_credits': calls * 3 * len(text),
                'how_billed': 'ElevenLabs: Voice Design is charged by the number of characters in its preview text; '
                              'each call makes three voices. Whether the three are billed once or three times is not '
                              'documented, so the reserve assumes three; the ledger records what was really billed.'}
        if not getattr(args, 'execute', False):
            emit({'ok': True, 'mode': 'dry_run_no_charges', 'voice_design': plan,
                  'design_description': args.design_description, 'preview_text': text,
                  'account_voices_requested': free_n,
                  'next': 'Review the cost, then re-run with --execute (the balance is checked before any design call).'})
            return
    key = elevenlabs_key()
    if not key:
        error('ELEVENLABS_API_KEY (or ELEVEN_API_KEY) is not set; do not store API keys in the command or ZIP.')
    outdir.mkdir(parents=True, exist_ok=True)
    candidates = []

    if free_n:
        try:
            data = elevenlabs_request('GET', '/v1/voices', key)
        except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError, ValueError) as exc:
            error('Cannot list ElevenLabs account voices.', f'{type(exc).__name__}: {str(exc)[:200]}')
        pool = data.get('voices') or []
        needle = (args.search or '').strip().lower()
        if needle:
            def matches(v):
                hay = ' '.join([str(v.get('name') or '')] +
                               [str(x) for x in (v.get('labels') or {}).values()]).lower()
                return needle in hay
            pool = [v for v in pool if matches(v)]
        for v in pool[:free_n]:
            candidates.append({'source': 'account_voice', 'voice_id': v['voice_id'], 'name': v.get('name'),
                                'labels': v.get('labels') or {}, 'preview_url': v.get('preview_url')})
        if len(candidates) < free_n:
            error('Not enough existing account voices matched the search; broaden --search, lower --count, '
                  'or raise --design to fill the rest with newly designed voices.',
                  {'matched': len(candidates), 'requested': free_n})

    if design_n:
        bal = subscription_balance(key)
        need = math.ceil(plan['reserve_credits'] * getattr(args, 'credit_safety_factor', 1.15)) + \
            int(getattr(args, 'keep_credits', 0) or 0)
        if bal['available'] < need:
            error('Not enough ElevenLabs credits for these Voice Design calls: nothing was sent.',
                  {**plan, 'available': bal['available'], 'required_available': need})
        made = 0
        while made < design_n:
            dbody = {'voice_description': args.design_description, 'text': text}
            dsha = paid_request_sha('/v1/text-to-voice/design', dbody)
            # a design call cut off earlier has no history to recover from: its outcome is checked by the user first
            paid_reconcile(rd, key, dsha, dbody, None, args.retry_unreconciled, args.reason, from_history=False)
            raw, err, entry = eleven_paid_post(rd, key, '/v1/text-to-voice/design', dbody, 'voice_design',
                                               {'video': int(args.video), 'model_id': 'voice_design',
                                                'request_sha256': dsha}, accept='application/json', timeout=120)
            if err:
                error('Voice Design call failed (it may have been billed regardless; see the ledger). '
                      'Verify your ElevenLabs account before retrying.', {'error': err, 'ledger': entry})
            try:
                resp = json.loads(raw or b'{}')
            except ValueError:
                resp = {}
            previews = resp.get('previews') or []
            if not previews:
                error('Voice Design returned no previews.', {k: v for k, v in resp.items() if k != 'previews'})
            for prev in previews:
                if made >= design_n:
                    break
                candidates.append({'source': 'voice_design', 'voice_id': prev['generated_voice_id'],
                                    'name': f"design-{prev['generated_voice_id'][:8]}", 'labels': {},
                                    'audio_base_64': prev['audio_base_64']})
                made += 1

    results = []
    for i, c in enumerate(candidates, 1):
        stem = f'candidate-{i:02d}-{c["voice_id"][:10]}'
        fname = outdir / f'{stem}.mp3'
        if c['source'] == 'account_voice':
            if not c.get('preview_url'):
                results.append({**{k: c[k] for k in ('source', 'voice_id', 'name', 'labels')},
                                'file': None, 'preview_wpm': None, 'error': 'voice has no preview_url'})
                continue
            try:
                with urllib.request.urlopen(c['preview_url'], timeout=30) as resp:
                    fname.write_bytes(resp.read())
            except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError) as exc:
                results.append({**{k: c[k] for k in ('source', 'voice_id', 'name', 'labels')},
                                'file': None, 'preview_wpm': None,
                                'error': f'preview download failed: {type(exc).__name__}: {str(exc)[:160]}'})
                continue
        else:
            fname.write_bytes(base64.b64decode(c['audio_base_64']))
        tpath = outdir / f'{stem}.json'
        wpm, heard, voice_delivery = None, None, None
        try:
            transcribe(fname, tpath, args.whisper_model, args.device, args.compute_type)
            raw = tpath.with_suffix('.txt').read_text(encoding='utf-8', errors='replace')
            wpm = wpm_from_transcript_raw(raw)
            heard = strip_transcript_timestamps(raw).strip() or None
        except (RuntimeError, ValueError, OSError) as exc:
            heard = f'transcription failed: {type(exc).__name__}: {str(exc)[:160]}'
        voice_delivery = measure_file_delivery(fname, tpath)
        results.append({'source': c['source'], 'voice_id': c['voice_id'], 'name': c.get('name'),
                        'labels': c.get('labels'), 'file': str(fname), 'preview_wpm': wpm, 'heard_text': heard,
                        'measured_delivery': voice_delivery})
    report = {'video': int(args.video), 'search': args.search, 'design_description': args.design_description,
              'made_at': now(), 'candidates': results}
    report_path = outdir.parent / 'candidates.json'
    if report_path.exists():   # keep every earlier round
        shutil.move(str(report_path), str(report_path.with_name(
            'candidates-' + dt.datetime.now().strftime('%Y%m%d-%H%M%S') + '.json')))
    write_json(report_path, report)
    emit({'ok': True, 'candidates_file': str(report_path), 'count': len(results), 'candidates': results,
          'voice_design': plan,
          'guidance': 'The agents cannot hear these files. Choose for the chosen treatment\'s narrator (direction.json): '
                      'compare each candidate\'s description and labels, what it said, and its measured delivery '
                      '(pitch range and movement, loudness contrast; a short sample, indicative only) with the '
                      'references\' (20-analysis/av). The files are listed for the user, who may listen and overrule. '
                      'preview_wpm does not predict real pace. Lock the pick with voice-pick; the real pace and '
                      'delivery are measured on the first real part (tts --max-parts 1, then narration-measure).'})


def cmd_voice_pick(args):
    """Choose this video's narrator: an editorial decision made for its locked treatment (the narrator it describes,
    the experience the audience should have, how the comparable narrators deliver), recorded with its reason in
    60-voice/video-NN/voice-lock.json. Every recording of the video then follows that lock: the voice, the model and the
    stability and similarity chosen for this narrator (stability trades consistency between generations against
    expressive range; it is never a pace control: Eleven v4 applies no speed setting, and the real pace is measured,
    not steered). Another video may share the voice for a series identity, or choose its own. Changing a video's
    voice or settings is a deliberate revision (--replace, with a reason); parts recorded with the old setup are then
    re-recorded (tts --rerecord-changed, or --archive-existing for another voice).
    A Voice Design candidate's generated_voice_id is saved to the account library first (POST /v1/text-to-voice)."""
    rd, st = run_folder(args)
    n = int(args.video)
    gate, dlock, dfacts = direction_gate(rd, n)
    if gate:
        error('The narrator is chosen for the locked treatment: lock the creative direction first (direction-lock).',
              gate)
    lockfile = voice_lock_path(rd, n)
    old = read_json(lockfile)
    if old and not args.replace:
        error('This video already has its narrator. A change is deliberate: --replace with a --reason.',
              {'file': str(lockfile)})
    if n_words(args.reason) < MIN_NOTE_WORDS:
        error('Say why this voice and these settings fit the treatment\'s narrator (--reason, a real sentence).')
    settings = parse_voice_settings(args.settings, args.model_id)
    bad = voice_settings_issues(settings)
    if bad:
        error('Choose both settings for this narrator: stability (consistency between generations against expressive '
              'range) and similarity_boost (closeness to the voice), each from 0 to 1.', bad)
    preview_wpm, source, design_description = None, None, None
    vdir = rd / '60-voice' / f'video-{n:02d}'
    for cfile in [vdir / 'candidates.json'] + sorted(vdir.glob('candidates-*.json'), reverse=True):
        cdata = read_json(cfile)
        hit = next((c for c in (cdata.get('candidates') or []) if c.get('voice_id') == args.voice_id), None)
        if hit:
            preview_wpm = hit.get('preview_wpm', hit.get('measured_wpm'))
            source, design_description = hit.get('source'), cdata.get('design_description')
            break
    final_voice_id = args.voice_id
    saved_from = None
    key = elevenlabs_key() if source == 'voice_design' else None
    if source == 'voice_design':
        if not key:
            error('ELEVENLABS_API_KEY (or ELEVEN_API_KEY) is not set; do not store API keys in the command or ZIP.')
        try:   # already saved earlier (the save returns 400 the second time): use the library voice as it is
            elevenlabs_request('GET', '/v1/voices/' + urllib.parse.quote(args.voice_id, safe=''), key)
            source = 'account_voice'
        except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError, ValueError):
            pass
    if source == 'voice_design':
        if not args.name:
            error('--name is required to save a Voice Design candidate as a permanent voice '
                  '(ElevenLabs requires voice_name).')
        try:
            resp = elevenlabs_request('POST', '/v1/text-to-voice', key,
                                      body={'voice_name': args.name,
                                            'voice_description': design_description or args.name,
                                            'generated_voice_id': args.voice_id})
        except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError, ValueError) as exc:
            error('Could not save the designed voice to your ElevenLabs library.',
                  f'{type(exc).__name__}: {str(exc)[:200]}')
        if not resp.get('voice_id'):
            error('Save call returned no voice_id.', resp)
        saved_from = args.voice_id
        final_voice_id = resp['voice_id']
    direction = read_json(video_dir(rd, n) / 'direction.json')
    others = sorted(p.parent.name for p in (rd / '60-voice').glob('video-*/voice-lock.json')
                    if p != lockfile and read_json(p).get('voice_id') == final_voice_id)
    lock = {'video': n, 'voice_id': final_voice_id, 'generated_voice_id': saved_from,
            'name': args.name or old.get('name'), 'model_id': args.model_id, 'settings': settings,
            'reason': args.reason.strip(), 'treatment': dlock.get('treatment'),
            'production_rev': dlock.get('production_rev', 1), 'narrator_sha256': narrator_sha(direction),
            'voice_rev': int(old.get('voice_rev') or 0) + 1, 'same_voice_as': others,
            'preview_wpm': preview_wpm, 'design_description': design_description, 'locked_at': now(),
            'rule': 'Every recording of this video uses exactly this voice, model and settings; a change is '
                    'voice-pick --replace with a reason.',
            'pace_note': 'preview_wpm is a short-sample figure and is never used to size the script; the real '
                         'pace is measured (narration-measure) on the first real part.',
            'history': (old.get('history') or []) + ([{k: old.get(k) for k in (
                'voice_id', 'model_id', 'settings', 'reason', 'voice_rev', 'production_rev', 'locked_at')}] if old else [])}
    m = old.get('measured') or {}
    if _measured_matches(m, final_voice_id, args.model_id, settings):
        lock['measured'] = m   # same voice, model and settings: the real measurement still holds
    lockfile.parent.mkdir(parents=True, exist_ok=True)
    write_json(lockfile, lock)
    recorded = read_json(rd / '50-audio' / f'video-{n:02d}' / 'manifest.json').get('finished_parts') or []
    emit({'ok': True, 'lock_file': str(lockfile), 'voice_id': final_voice_id, 'model_id': args.model_id,
          'settings': settings, 'voice_rev': lock['voice_rev'], 'saved_from_generated_voice_id': saved_from,
          'same_voice_as': others, 'calibrated': bool(voice_measurement(rd, n)),
          'guidance': ('Next: tts --run RUN --video N (a dry run: the parts, their beats, characters and credits), '
                       'then the calibration part (tts --max-parts 1 --execute) and narration-measure. Every '
                       'recording takes the voice, model and settings from this lock. '
                       + ('Parts already recorded with another voice setup are re-recorded before the narration is '
                          'complete (tts --rerecord-changed; another voice: --archive-existing).' if recorded and old else ''))})


def cmd_voice_probe(args):
    """Hear a short real passage, sent exactly as the script would send it (inline tags in place, the pronunciation
    list applied unless --no-pronunciation), via one short billed call: how the voice, the tags and the names SOUND,
    before the paid narration. Voice, model and settings default to this video's voice lock (another voice is probed
    while choosing: --voice-id with --settings). Its WPM is reported but a sample under ~300 words does not predict
    real pace (measured here: short samples read up to 199 WPM, the same voice 175-188 on real parts); the real pace
    comes from the calibration part. Separate from tts's parts; touches no script, lock or 50-audio file."""
    rd, st = run_folder(args)
    key = elevenlabs_key()
    if not key:
        error('ELEVENLABS_API_KEY (or ELEVEN_API_KEY) is not set; do not store API keys in the command or ZIP.')
    n = int(args.video)
    vd = video_dir(rd, n)
    lock = read_json(vd / 'length-lock.json', required=True)
    vf = voice_facts(rd, n)
    voice_id = args.voice_id or vf['voice_id']
    if not voice_id:
        error('No voice lock for this video yet: give --voice-id and --settings to probe a candidate.')
    model_id = args.model_id or (vf['model_id'] if vf['lock'] else 'eleven_v4')
    settings = parse_voice_settings(args.settings, model_id) if args.settings else \
        (vf['settings'] if vf['lock'] and voice_id == vf['voice_id'] else {})
    bad = voice_settings_issues(settings)
    if bad:
        error('Probe with explicit settings for this narrator (stability and similarity_boost).', bad)
    script = read_json(vd / 'script.json')
    text = args.text
    if not text:
        buf, total = [], 0
        for l in script.get('lines') or []:
            buf.append(l['text'])
            total += len(l['text']) + 1
            if total >= 450:
                break
        text = ' '.join(buf)
    pron = pronunciation_facts(rd, n, script.get('lines') or [])
    sent_text = text if args.no_pronunciation else tts_text(text, pron['terms'])
    mk, _ = script_markup([{'id': 'probe', 'text': sent_text if args.no_pronunciation else text}])
    if mk:
        error('The probe text holds markup the voice can\'t take.', mk)
    limit = model_limit(model_id)
    if len(sent_text) > limit:
        error('Probe text exceeds the model request limit.', {'characters': len(sent_text), 'limit': limit})
    budget = credit_preflight(rd, key, model_id, len(sent_text), args.credit_safety_factor, None,
                              args.keep_credits, 'this probe')
    body = {'text': sent_text, 'model_id': model_id, 'voice_settings': settings}
    if language_code(lock.get('language')):
        body['language_code'] = language_code(lock.get('language'))
    path = '/v1/text-to-speech/' + urllib.parse.quote(voice_id, safe='') + '?output_format=mp3_44100_128'
    req_sha = paid_request_sha(path, body, voice_id)
    raw, entry = paid_reconcile(rd, key, req_sha, body, voice_id, args.retry_unreconciled, args.reason)
    err = None
    if raw is None:
        raw, err, entry = eleven_paid_post(rd, key, path, body, 'probe',
                                           {'video': n, 'model_id': model_id, 'voice_id': voice_id,
                                            'request_sha256': req_sha}, timeout=120)
    if err:
        error('Probe TTS call failed (it may have been billed regardless; see the ledger). '
              'Verify your ElevenLabs account before retrying.', {'error': err, 'ledger': entry})
    if not raw or len(raw) < 1024:
        error('Audio response too short.', {'bytes': len(raw or b'')})
    outdir = rd / '60-voice' / f'video-{n:02d}' / 'probes'
    outdir.mkdir(parents=True, exist_ok=True)
    k = len(list(outdir.glob('probe-*.mp3'))) + 1
    stem = f'probe-{k:02d}-{voice_id[:10]}'
    fname = outdir / f'{stem}.mp3'
    fname.write_bytes(raw)
    tpath = outdir / f'{stem}.json'
    transcribe(fname, tpath, args.whisper_model, args.device, args.compute_type)
    rawtxt = tpath.with_suffix('.txt').read_text(encoding='utf-8', errors='replace')
    wpm = wpm_from_transcript_raw(rawtxt)
    heard = strip_transcript_timestamps(rawtxt).strip()
    emit({'ok': True, 'file': str(fname), 'voice_id': voice_id, 'model_id': model_id, 'voice_settings': settings,
          'sent_text': sent_text, 'sent_characters': len(sent_text), 'credit_preflight': budget,
          'credits_billed': entry.get('delta'), 'sample_words': count_words(text), 'short_sample_wpm': wpm,
          'references_pace_wpm': lock.get('pace_wpm'),
          'tags_sent': [m.group(0) for m in TAG_RE.finditer(sent_text)],
          'tags_maybe_read_aloud': tags_heard(sent_text, heard), 'heard_text': heard,
          'measured_delivery': measure_file_delivery(fname, tpath),
          'guidance': 'No agent here can hear this file. What stands in: the words heard back (a tag whose words show '
                      'up in heard_text was read aloud; a name heard differently may be mispronounced, or misheard by '
                      'Whisper) and measured_delivery (how the voice moves; a short sample, indicative only), next to '
                      'the treatment\'s narrator and the references. The user may listen to the file. '
                      'short_sample_wpm does not predict the real pace; do not size the script on it.'})


# ---------------------------------------------------------------- controlled calibration trials
TRIAL_VARIABLES = ('passage', 'voice_id', 'model_id', 'stability', 'similarity_boost', 'tags', 'pronunciation',
                   'context')
# What each take's numbers can and cannot carry: written into every take's record and into the answer key.
TRIAL_UNCERTAINTIES = [
    'one take per set-up: Eleven v4 varies from take to take, so a difference between two takes can be the setting or '
    'chance; only a repeat of the same request shows how much one set-up varies by itself',
    'Whisper medium word times are good to about a tenth of a second: so are the pauses and the pace',
    'pace on a passage of 30-70 words moves several words a minute with one pause more or less',
    'pitch is tracked per word (pyin) over a short sample: a range or movement is indicative, and a lower figure can be '
    'the right, quieter delivery for the moment',
    'loudness is each file\'s own (EBU R128); ElevenLabs levels each take by itself, so a level step between takes can '
    'come from that, not from the delivery',
    'none of these numbers says which take sounds better or more human: that is for the listener']
TRIAL_LISTEN_ITEMS = [
    ('natural', 'sounds like a person, not a reading'), ('flow', 'conversational flow'),
    ('charisma', 'vocal charisma: a voice you lean in to'), ('expressive', 'expressiveness'),
    ('fit', 'right for this moment of the story'), ('theatrical', 'too theatrical (which one is MORE)'),
    ('monotone', 'monotonous (which one is MORE)'), ('pauses', 'pauses where a person would pause'),
    ('pronunciation', 'names and words said right'), ('continuity', 'continuous with what comes before and after'),
    ('enjoyment', 'enjoyable to listen to'), ('keep', 'makes you want to keep listening for twenty minutes')]


def trial_plan_facts(plan, vf, lines, pron):
    """A trial plan, checked before anything is priced: passages (script lines of this video, or a short text), each
    with the delivery it is meant to have (`intended_delivery`), the variants (each variable set explicitly or taken
    from the voice lock), the runs pairing them, the questions, and the user's spending cap (`budget`: {id,
    max_credits}). Every run answers a question, and every question compares runs that differ in exactly one
    variable, so each answer can be read: two changes at once can't be told apart."""
    issues = []
    pid = str(plan.get('id') or '')
    if not re.fullmatch(r'[a-z0-9][a-z0-9-]{2,40}', pid):
        issues.append('trial_id_must_be_lowercase_letters_digits_and_dashes')
    budget = plan.get('budget') if isinstance(plan.get('budget'), dict) else {}
    if not re.fullmatch(r'[a-z0-9][a-z0-9-]{2,60}', str(budget.get('id') or '')) or not isinstance(
            budget.get('max_credits'), int) or isinstance(budget.get('max_credits'), bool) or budget['max_credits'] <= 0:
        issues.append('trial_needs_its_budget: {"id": "...", "max_credits": N}, the credits the user authorised for '
                      'these trials (every plan under the same id shares them)')
    index = {str(r.get('id') or f'L{i + 1:03d}'): i for i, r in enumerate(lines)}
    passages = {}
    for p in plan.get('passages') or []:
        k = str((p or {}).get('id') or '')
        if not k or k in passages or '-' in k:
            issues.append(f'passage_{k or "unnamed"}_needs_a_unique_id_without_dashes')
            continue
        text, rng, ids = None, None, None
        if p.get('lines'):
            m = re.fullmatch(r'\s*(L\d+)\s*(?:-\s*(L\d+))?\s*', str(p['lines']))
            if not m or m.group(1) not in index or (m.group(2) and m.group(2) not in index):
                issues.append(f'passage_{k}_names_lines_the_script_does_not_have')
            else:
                lo, hi = index[m.group(1)], index[m.group(2) or m.group(1)]
                if hi < lo:
                    issues.append(f'passage_{k}_lines_run_backwards')
                else:
                    rng = (lo + 1, hi + 1)
                    text = '\n'.join(str(r.get('text') or '').strip() for r in lines[lo:hi + 1])
                    ids = [str(r.get('id') or f'L{lo + j + 1:03d}') for j, r in enumerate(lines[lo:hi + 1])]
        elif p.get('text'):
            text = str(p['text']).strip()
        if not text or len(strip_tags(text)) < 20:
            issues.append(f'passage_{k}_needs_its_lines_or_a_text')
            text = text or ''
        if n_words(p.get('moment')) < 1:
            issues.append(f'passage_{k}_names_its_moment')
        if n_words(p.get('intended_delivery')) < 3:
            issues.append(f'passage_{k}_says_its_intended_delivery')
        issues += script_markup([{'id': f'passage_{k}', 'text': text}])[0]
        passages[k] = {'text': text, 'lines': rng, 'line_ids': ids, 'moment': p.get('moment'), 'why': p.get('why'),
                       'intended_delivery': p.get('intended_delivery'), 'lines_label': p.get('lines')}
    variants = {}
    for v in plan.get('variants') or []:
        k = str((v or {}).get('id') or '')
        if not k or k in variants or '-' in k:
            issues.append(f'variant_{k or "unnamed"}_needs_a_unique_id_without_dashes')
            continue
        voice = str(v.get('voice_id') or 'lock')
        voice_id = vf['voice_id'] if voice == 'lock' else voice
        if not voice_id:
            issues.append(f'variant_{k}_has_no_voice: there is no voice lock to stand for "lock"')
        model = v.get('model_id') or (vf['model_id'] if vf['lock'] else 'eleven_v4')
        if model not in TTS_MODELS:
            issues.append(f'variant_{k}_model_must_be:' + '/'.join(TTS_MODELS))
        settings = {x: v.get(x, (vf['settings'] or {}).get(x)) for x in VOICE_SETTING_KEYS}
        issues += [f'variant_{k}_{x}' for x in voice_settings_issues(settings)]
        tags = str(v.get('tags') or 'as_written')
        if tags not in ('as_written', 'none'):
            issues.append(f'variant_{k}_tags_must_be:as_written/none')
        ctx = str(v.get('context') or 'none')
        if ctx not in ('none', 'neighbours'):
            issues.append(f'variant_{k}_context_must_be:none/neighbours')
        variants[k] = {'voice_id': voice_id, 'model_id': model, **settings, 'tags': tags,
                       'pronunciation': bool(v.get('pronunciation', True)), 'context': ctx}
    runs = []
    for r in plan.get('runs') or []:
        pk, vk = (str(r[0]), str(r[1])) if isinstance(r, (list, tuple)) and len(r) == 2 else (None, None)
        if pk not in passages or vk not in variants:
            issues.append(f'run_{pk}_{vk}_names_an_unknown_passage_or_variant')
        elif (pk, vk) in runs:
            issues.append(f'run_{pk}_{vk}_listed_twice')
        else:
            runs.append((pk, vk))
    asked, questions = set(), []
    for q in plan.get('questions') or []:
        qid = str((q or {}).get('id') or '')
        cmp_ = [(str(x[0]), str(x[1])) for x in q.get('compare') or [] if isinstance(x, (list, tuple)) and len(x) == 2]
        if n_words(q.get('asks')) < MIN_NOTE_WORDS:
            issues.append(f'question_{qid}_must_say_what_it_asks')
        if len(cmp_) < 2 or any(x not in runs for x in cmp_):
            issues.append(f'question_{qid}_compares_runs_not_in_the_plan')
            continue
        def val(run, k):
            return run[0] if k == 'passage' else variants[run[1]][k]
        diffs = sorted({k for a in cmp_ for b in cmp_ for k in TRIAL_VARIABLES if val(a, k) != val(b, k)})
        if q.get('repeat'):
            # The same request twice: how much one set-up varies by itself, the yardstick for every other answer.
            if diffs:
                issues.append(f'question_{qid}_is_a_repeat_but_changes:' + ','.join(diffs))
        elif len(diffs) != 1:
            issues.append(f'question_{qid}_changes_{len(diffs)}_things_at_once:' + (','.join(diffs) or 'nothing'))
        questions.append({'id': qid, 'asks': q.get('asks'), 'compare': cmp_, 'varies': diffs,
                          'listen_for': q.get('listen_for'), 'repeat': bool(q.get('repeat'))})
        asked |= set(cmp_)
    joins = []
    for j in plan.get('joins') or []:
        jid = str((j or {}).get('id') or '')
        parts, cmpv = [str(x) for x in j.get('parts') or []], [str(x) for x in j.get('compare') or []]
        if len(parts) != 2 or len(cmpv) < 2 or any(x not in passages for x in parts) or any(x not in variants for x in cmpv):
            issues.append(f'join_{jid}_needs_two_passages_and_the_variants_it_compares')
            continue
        pa, pb = passages[parts[0]], passages[parts[1]]
        if not (pa['lines'] and pb['lines'] and pa['lines'][1] + 1 == pb['lines'][0]):
            issues.append(f'join_{jid}_passages_must_be_consecutive_script_lines')
        need = [(x, v) for v in cmpv for x in parts]
        missing = [f'{x}-{v}' for x, v in need if (x, v) not in runs]
        if missing:
            issues.append(f'join_{jid}_needs_runs:' + ','.join(missing))
        jd = sorted({k for x in cmpv for y in cmpv for k in TRIAL_VARIABLES if k != 'passage'
                     and variants[x][k] != variants[y][k]})
        if len(jd) != 1:
            issues.append(f'join_{jid}_changes_{len(jd)}_things_at_once:' + (','.join(jd) or 'nothing'))
        if n_words(j.get('asks')) < MIN_NOTE_WORDS:
            issues.append(f'join_{jid}_must_say_what_it_asks')
        joins.append({'id': jid, 'parts': parts, 'compare': cmpv, 'varies': jd, 'asks': j.get('asks'),
                      'listen_for': j.get('listen_for')})
        asked |= set(need)
    issues += [f'run_{a}_{b}_answers_no_question' for a, b in runs if (a, b) not in asked]
    if not runs:
        issues.append('trial_has_no_runs')
    return issues, passages, variants, runs, questions, joins


def trial_request(passages, variants, run, lines, pron):
    """What one trial run sends: the passage as the script would send it under that variant."""
    p, v = passages[run[0]], variants[run[1]]
    text = p['text'] if v['tags'] == 'as_written' else re.sub(r'[ \t]{2,}', ' ', TAG_RE.sub('', p['text'])).strip()
    terms = pron['terms'] if v['pronunciation'] else []
    sent = '\n'.join(tts_text(x, terms) for x in text.split('\n'))
    body = {'text': sent, 'model_id': v['model_id'],
            'voice_settings': {k: v[k] for k in VOICE_SETTING_KEYS}}
    if v['context'] == 'neighbours' and p['lines']:
        all_sent = [tts_text(r.get('text') or '', terms) for r in lines]
        prev, nxt = context_text(all_sent, p['lines'][0] - 1, -1), context_text(all_sent, p['lines'][1] + 1, 1)
        if prev:
            body['previous_text'] = prev
        if nxt:
            body['next_text'] = nxt
    return body


def trial_budgets_path(rd):
    return rd / '60-voice' / 'trial-budgets.json'


def trial_budget_check(rd, budget, plan_id, write=False):
    """The plan's cap against the run's register of trial budgets (RUN/60-voice/trial-budgets.json): the first plan
    naming an id registers it, and every later plan naming the same id must carry the same cap, so a new plan never
    raises it (only the user does, by hand). Returns issues."""
    reg = read_json(trial_budgets_path(rd))
    bid, cap = str(budget.get('id')), int(budget.get('max_credits'))
    have = (reg.get('budgets') or {}).get(bid)
    if have and int(have.get('max_credits') or -1) != cap:
        return [f'trial_budget_{bid}_is_registered_with_{have.get("max_credits")}_credits_not_{cap}']
    if write:
        b = reg.setdefault('budgets', {}).setdefault(bid, {'max_credits': cap, 'registered_at': now(),
                                                            'authorised': budget.get('authorised'), 'plans': []})
        if plan_id not in b.setdefault('plans', []):
            b['plans'].append(plan_id)
            write_json(trial_budgets_path(rd), reg)
    return []


def budget_spent(rd, budget_id):
    """What a trial budget has used so far, from the ledger: every request sent under it, failures, retries and resumed
    sessions included. A request counts its credits_billed (the larger of ElevenLabs' character-cost header and the
    balance drop); when neither is known, and for a request cut off before its outcome was written (a pending row
    with no outcome), its largest possible charge. Returns (credits, the cut-off requests)."""
    rows = [r for r in ledger_rows(rd) if r.get('budget') == budget_id]
    closed = {r.get('attempt_id') for r in rows if r.get('phase') in ('done', 'recovered')}
    spent, open_ = 0, []
    for r in rows:
        if r.get('phase') == 'pending':
            if r.get('attempt_id') not in closed:
                spent += int(r.get('max_credits') or 0)
                open_.append(r)
        elif r.get('phase') in ('done', 'recovered'):
            c = take_credits(r)
            spent += int(c) if c is not None else int(r.get('max_credits') or 0)
    return spent, open_


def take_credits(row):
    """What one request cost, best evidence first: ElevenLabs' character-cost header (exact), else the credits_billed
    on record (a balance drop seen), else None. A recovered request has no header: it counts as on record."""
    if row.get('character_cost_header') is not None and row.get('phase') != 'recovered':
        return row['character_cost_header']
    return row.get('credits_billed')


def _pid_running(pid):
    """True while a process with this id runs (a trial's lock is stale once its process is gone: after a crash or a
    power cut the next run takes over). Unknown counts as running."""
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return False
    if pid == os.getpid():
        return False
    try:
        if os.name == 'nt':
            out = subprocess.run(['tasklist', '/FI', f'PID eq {pid}', '/NH', '/FO', 'CSV'], capture_output=True, text=True,
                                 timeout=20).stdout or ''
            return f'"{pid}"' in out
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except (OSError, subprocess.SubprocessError):
        return True


def eleven_get_bytes(path, key, timeout=120):
    req = urllib.request.Request('https://api.elevenlabs.io' + path, headers={'xi-api-key': key})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read()


def recover_from_history(rd, key, pending, body, voice_id):
    """A request cut off before its answer was saved (a pending ledger row with no outcome): when ElevenLabs finished
    it anyway, its audio is in the account's history (GET /v1/history and an item's audio are free), so the take is
    taken from there instead of being paid for twice. The budget keeps counting that request at its largest possible
    charge (the history's character figures are recorded beside it; ElevenLabs does not document them as credits).
    Returns (audio, ledger row) or (None, None)."""
    try:
        since = int(dt.datetime.fromisoformat(str(pending['at'])).timestamp()) - 120
        data = elevenlabs_request('GET', '/v1/history', key, params={'page_size': 100, 'voice_id': voice_id}, timeout=30)
    except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError, ValueError, KeyError) as exc:
        return None, {'history_lookup_error': f'{type(exc).__name__}: {str(exc)[:160]}'}
    for it in (data.get('history') if isinstance(data, dict) else None) or []:
        if str(it.get('text')) != body['text'] or it.get('model_id') not in (None, body['model_id']):
            continue
        if int(it.get('date_unix') or 0) < since:
            continue
        try:
            audio = eleven_get_bytes('/v1/history/' + urllib.parse.quote(str(it['history_item_id']), safe='') + '/audio', key)
        except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, OSError, KeyError):
            return None, None
        try:
            used = int(it['character_count_change_to']) - int(it['character_count_change_from'])
        except (KeyError, TypeError, ValueError):
            used = None
        row = {**{k: v for k, v in pending.items() if k not in ('phase', 'at')}, 'at': now(), 'phase': 'recovered',
               'ok': True, 'history_item_id': it.get('history_item_id'), 'request_id': it.get('request_id'),
               'history_character_count_change': used, 'credits_billed': pending.get('max_credits'),
               'note': 'audio taken from the account history after the request was cut off; counted at its largest '
                       'possible charge'}
        ledger_add(rd, row)
        return audio, row
    return None, None


# ---------------------------------------------------------------- a paid request is never billed twice
# Every billed ElevenLabs request goes on the ledger before it is sent (a 'pending' row: its process and the request's
# identity) and after (a 'done' row with its outcome: completed; failed, refused before any work and never billed;
# uncertain, cut off, timed out or a server error, billed or not is unknown; charged_incomplete, billed but the answer is
# unusable). Before the same request is sent again, every earlier attempt whose outcome is unknown is settled first: its
# audio from the account history when ElevenLabs finished it (free: never paid twice), else nothing is sent until the user
# has checked the account and allows one new attempt on record (--retry-unreconciled).
PAID_UNSETTLED = ('uncertain', 'charged_incomplete')


def paid_request_sha(path, body, voice_id=None):
    """A billable request's identity: what decides the work and the bill (the endpoint, the text, the model, the voice and
    its settings, the language). The context fields are left out: the same text again is the same work."""
    keep = {k: body.get(k) for k in ('text', 'voice_description', 'model_id', 'voice_settings', 'language_code')}
    ident = {'path': str(path).split('?')[0], 'voice_id': voice_id, **keep}
    return hashlib.sha256(json.dumps(ident, sort_keys=True, ensure_ascii=False).encode('utf-8')).hexdigest()


def paid_unsettled(rd, request_sha):
    """Earlier attempts of this request whose outcome is not established: a 'pending' row nothing closed (still being
    sent while its process runs, else cut off), or a closed one whose outcome is uncertain or charged but unusable, with
    no later 'recovered' or 'reconciled' row."""
    rows = ledger_rows(rd)
    closed = {r.get('attempt_id'): r for r in rows if r.get('phase') == 'done' and r.get('attempt_id')}
    settled = {r.get('attempt_id') for r in rows if r.get('phase') in ('recovered', 'reconciled')}
    out = []
    for r in rows:
        a = r.get('attempt_id')
        if r.get('phase') != 'pending' or not a or a in settled or r.get('request_sha256') != request_sha:
            continue
        d = closed.get(a)
        if d is None:
            out.append({**r, 'state': 'being_sent' if _pid_running(r.get('pid')) else 'cut_off'})
        elif d.get('outcome') in PAID_UNSETTLED:
            out.append({**r, 'state': d['outcome'], 'error': d.get('error')})
    return out


def paid_reconcile(rd, key, request_sha, body, voice_id, retry=None, reason=None, from_history=True):
    """Settle every earlier attempt of this request before it is sent again. Returns (audio, ledger row) when the account
    history holds the take (no new charge); (None, None) when the request may be sent: nothing was unsettled, or the user
    allowed one new attempt for each unsettled one (--retry-unreconciled ID|all --reason), which goes on the ledger.
    Anything else stops with nothing sent."""
    open_ = paid_unsettled(rd, request_sha)
    if not open_:
        return None, None
    busy = [o['attempt_id'] for o in open_ if o['state'] == 'being_sent']
    if busy:
        error('Another process is sending this same paid request right now: nothing was sent. Let it finish.',
              {'attempts': busy})
    looked = None
    if from_history and key:
        for o in open_:
            audio, row = recover_from_history(rd, key, o, body, voice_id)
            if audio:
                return audio, row
            looked = row or looked
    allow = {x.strip() for x in str(retry or '').split(',') if x.strip()}
    left = [o for o in open_ if 'all' not in allow and o['attempt_id'] not in allow]
    if left:
        error('An earlier paid request for exactly this has no known outcome (cut off, timed out, a server error, or '
              'billed with an unusable answer)' + (' and its audio is not in the account history' if from_history else '')
              + '. Sending it again could bill it twice, so nothing was sent. Check the ElevenLabs history and usage; '
              'when it was not billed, or paying again is accepted, re-run with --retry-unreconciled ATTEMPT_ID '
              '--reason "what you checked".',
              {'unsettled': [{k: o.get(k) for k in ('attempt_id', 'at', 'kind', 'state', 'error', 'video', 'part',
                                                     'characters')} for o in left],
               'history_lookup': looked})
    if n_words(reason) < MIN_NOTE_WORDS:
        error('--retry-unreconciled sends a request whose earlier outcome is unknown: say what you checked (--reason).')
    for o in open_:
        ledger_add(rd, {**{k: o.get(k) for k in ('attempt_id', 'kind', 'video', 'part', 'model_id', 'voice_id',
                                                 'request_sha256', 'characters')},
                        'at': now(), 'phase': 'reconciled', 'state_was': o['state'], 'reason': str(reason).strip(),
                        'note': 'outcome unknown; the user allowed one new attempt'})
    return None, None


def billed_credits(entry):
    """What one request was billed, best evidence first: ElevenLabs' character-cost header, else the credits on record,
    else a balance drop seen (it lags: often 0 at the time), else unknown."""
    e = entry or {}
    if e.get('character_cost_header') is not None and e.get('phase') != 'recovered':
        return e['character_cost_header']
    if e.get('credits_billed') is not None:
        return e['credits_billed']
    d = e.get('delta')
    return d if isinstance(d, (int, float)) and d > 0 else None


def hold_process_lock(lockf, label):
    """One process at a time for one paid job: its lock names the process, and a lock whose process is gone (a crash, a
    power cut) is taken over. Released when this process ends, however it ends."""
    held = read_json(lockf) if lockf.is_file() else {}
    if held and _pid_running(held.get('pid')):
        error(f'Another {label} is running for this video ({lockf.name}): one at a time.',
              {'lock': str(lockf), 'held_by': held})
    lockf.parent.mkdir(parents=True, exist_ok=True)
    lockf.write_text(json.dumps({'pid': os.getpid(), 'at': now(), 'what': label}), encoding='utf-8')

    def release():
        try:
            if (read_json(lockf) or {}).get('pid') == os.getpid():
                lockf.unlink()
        except (OSError, ValueError):
            pass
    atexit.register(release)
    return release


def loudness_stats(path):
    """Integrated loudness (LUFS), loudness range (LU) and true peak (dBTP) of one file, by ffmpeg's EBU R128 meter
    (local, free). Never raises: {'error': ...} when it can't be read."""
    try:
        cp = subprocess.run(['ffmpeg', '-hide_banner', '-nostats', '-i', str(path), '-vn', '-af', 'ebur128=peak=true', '-f',
                             'null', '-'], capture_output=True, text=True, encoding='utf-8', errors='replace', timeout=180)
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {'error': f'{type(exc).__name__}: {str(exc)[:120]}'}
    tail = (cp.stderr or '').rsplit('Summary:', 1)[-1]

    def num(rx):
        m = re.search(rx, tail)
        return float(m.group(1)) if m else None
    return {'integrated_lufs': num(r'I:\s*(-?[\d.]+|-inf)\s*LUFS'), 'loudness_range_lu': num(r'LRA:\s*(-?[\d.]+)\s*LU'),
            'true_peak_dbtp': num(r'Peak:\s*(-?[\d.]+|-inf)\s*dBFS')}


def trial_measure(rec, passage, pron_terms, language, args):
    """One take's measurements, from its own audio: Whisper medium (the words heard and their times), the pace while
    speaking and over the whole speaking span, the pauses and where they fall, pitch and loudness, every line heard,
    tags read aloud, names as heard, and what looks wrong. Evidence, never a verdict."""
    f = Path(rec['file'])
    tpath = f.with_suffix('.json')
    if not tpath.is_file():
        transcribe(f, tpath, args.whisper_model, args.device, args.compute_type)
    tj = read_json(tpath)
    words = transcript_words(tj)
    rawtxt = tpath.with_suffix('.txt').read_text(encoding='utf-8', errors='replace')
    plines = passage['text'].split('\n')
    d = align_detail(plines, words, language or 'en')
    dur = probe(f)['duration_s']
    heard = strip_transcript_timestamps(rawtxt).strip()
    spoken = sum(count_words(x) for x in plines)
    span = (words[-1]['end_s'] - words[0]['start_s']) if len(words) > 1 else 0.0
    pauses = [{'after_word': a['text'].strip(), 'at_s': round(a['end_s'], 2), 'pause_s': round(b['start_s'] - a['end_s'], 2)}
              for a, b in zip(words, words[1:]) if b['start_s'] - a['end_s'] >= 0.3]
    names = []
    for t in pron_terms:
        if t['rx'].search(strip_tags(passage['text'])):
            tt = tokens_of(t['term'])
            names.append({'term': t['term'], 'sent_as': t.get('sent_as') or t['term'],
                          'heard_as_written': all(x in d['heard'] for x in tt),
                          'nearest_heard': max(d['heard'], key=lambda h: difflib.SequenceMatcher(None, tt[0], h).ratio(),
                                               default=None)})
    delivery = measure_file_delivery(f, tpath)
    loud = loudness_stats(f)
    lead = round(words[0]['start_s'], 2) if words else None
    trail = round(dur - words[-1]['end_s'], 2) if words else None
    ids = passage.get('line_ids') or [f'line {i + 1}' for i in range(len(plines))]
    not_heard = [ids[i] for i, tt in enumerate(d['tok_time']) if tt and not any(tt)]
    read_aloud = tags_heard(rec['sent']['text'], heard)
    anomalies = []
    if not words:
        anomalies.append('Whisper heard no words')
    if not_heard:
        anomalies.append('lines not heard: ' + ', '.join(not_heard))
    if read_aloud:
        anomalies.append('a tag may have been read aloud: ' + ', '.join(read_aloud))
    if d['ratio'] < 0.9:
        anomalies.append(f'only {d["ratio"]:.0%} of the words matched what was sent (a word dropped, added or misheard)')
    for nm in names:
        if not nm['heard_as_written']:
            anomalies.append(f'{nm["term"]} was heard as "{nm["nearest_heard"]}" (Whisper\'s spelling, not proof of '
                             'how it was said: listen)')
    if lead is not None and lead > 1.0:
        anomalies.append(f'{lead} s of silence before the first word')
    if trail is not None and trail > 1.5:
        anomalies.append(f'{trail} s of silence after the last word')
    if isinstance(loud.get('true_peak_dbtp'), float) and loud['true_peak_dbtp'] > -0.3:
        anomalies.append(f'true peak {loud["true_peak_dbtp"]} dBTP: may clip')
    rec.update({
        'measured': True, 'measured_at': now(), 'duration_s': dur, 'words_spoken': spoken,
        'active_wpm': wpm_from_transcript_raw(rawtxt),
        'overall_wpm': round(spoken / (span / 60)) if span > 0 else None,
        'file_wpm': round(spoken / (dur / 60)) if dur else None,
        'speech_span_s': round(span, 2), 'lead_silence_s': lead, 'trail_silence_s': trail,
        'pause_profile': pause_profile(words), 'pauses': pauses,
        'delivery': delivery, 'loudness': loud,
        'alignment_match_ratio': round(d['ratio'], 3), 'lines_not_heard': not_heard,
        'tags_maybe_read_aloud': read_aloud, 'names': names, 'heard_text': heard[:900],
        'transcript': str(tpath), 'anomalies': anomalies, 'uncertainties': TRIAL_UNCERTAINTIES})
    return rec


def _blind_order(trial_id, qid, runs_):
    """The order a question's takes are labelled A, B, ... in: fixed by the trial and question (so a rebuilt set keeps
    its labels), unrelated to the variants' names."""
    return sorted(runs_, key=lambda r: hashlib.sha256(f'{trial_id}|{qid}|{r[0]}-{r[1]}'.encode('utf-8')).hexdigest())


def _join_audio(a, b, gap_s, out):
    """Two takes as the viewer hears two recorded parts: the first, a gap of the voice's own pause, the second."""
    run_cmd(['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', '-i', str(a), '-f', 'lavfi', '-t',
             f'{gap_s:.3f}', '-i', 'anullsrc=r=44100:cl=mono', '-i', str(b), '-filter_complex',
             '[0:a]aformat=sample_rates=44100:channel_layouts=mono[x];[1:a]aformat=sample_rates=44100:channel_layouts=mono[g];'
             '[2:a]aformat=sample_rates=44100:channel_layouts=mono[y];[x][g][y]concat=n=3:v=0:a=1[o]', '-map', '[o]',
             '-c:a', 'libmp3lame', '-b:a', '128k', str(out)])


def trial_listening_set(outdir, plan, questions, report, passages, variants, joins=()):
    """The blind listening set for the user: listening/ holds each question's takes as <Q>-A.mp3, <Q>-B.mp3 ... (copies;
    the labels say nothing about the settings) and listening-guide.md (the lines, what each moment is meant to feel
    like, what to listen for, a sheet to fill in); answer-key.md / .json, one folder up, say which take is which, with
    every take's settings and measurements. A take used by two questions is copied under each question's own label. A
    join (two passages of consecutive lines, recorded as two requests the way two parts are) is heard as the viewer
    would: the first take, the voice's own pause, the second; the answer key shows the steps in level, pace and
    pitch across the join. Returns what was written."""
    lst = outdir / 'listening'
    lst.mkdir(parents=True, exist_ok=True)
    key, guide = [], [
        f'# Blind listening: {plan["id"]}', '',
        'Each question below has two (or more) takes. In each question one thing differs: a setting, or the passage '
        'itself (one narrator on two moments of the story; some questions send the very same request twice, to hear '
        'how much one set-up varies by itself). The file names say nothing about which set-up is which; the answer key '
        'is one folder up (answer-key.md): open it only after you have written your notes.', '',
        'How to listen: headphones or good speakers, at the volume you would watch a video. Play A then B, then B then A. '
        'Judge the take, not the words (where the words are the same).', '',
        'For each line of the sheet put A, B or "same", and a word or two when you can. What matters most: does it sound '
        'like a person telling you this story, and would you keep listening for twenty minutes?', '']
    done_q = []
    for q in questions:
        runs_ = q['compare']
        if not all((report['runs'].get(f'{a}|{b}') or {}).get('file') for a, b in runs_):
            continue
        p = passages[runs_[0][0]]
        same_p = all(r[0] == runs_[0][0] for r in runs_)
        if same_p:
            guide += [f'## {q["id"]}: {p.get("moment") or ""}' + (f' ({p.get("lines_label")})' if p.get('lines_label') else ''),
                      '', f'Meant to feel: {p.get("intended_delivery")}', '']
        else:
            # one narrator on several moments (a representative calibration): nothing about the set-up is hidden, so
            # each take says which moment it is, what it is meant to feel like and its words
            guide += [f'## {q["id"]}: one narrator, ' + ' / '.join(str(passages[r[0]].get('moment') or r[0]) for r in runs_),
                      '', 'The same voice and set-up on different moments of the story (the words differ): listen to '
                      'how it moves between them.', '']
        guide += [f'Listen for: {q.get("listen_for") or "which take sounds more like a person telling this story"}', '']
        if same_p:
            guide += ['The words: "' + ' '.join(strip_tags(x) for x in p['text'].split('\n')) + '"', '']
        labels = []
        for i, r in enumerate(_blind_order(plan['id'], q['id'], runs_)):
            lab = f'{q["id"]}-{chr(65 + i)}'
            src = Path(report['runs'][f'{r[0]}|{r[1]}']['file'])
            dst = lst / f'{lab}.mp3'
            shutil.copyfile(src, dst)
            labels.append(lab)
            key.append({'question': q['id'], 'label': lab, 'file': str(dst), 'run': f'{r[0]}-{r[1]}', 'source': str(src)})
            if not same_p:
                pp = passages[r[0]]
                guide += [f'{lab}: {pp.get("moment") or r[0]}' + (f' ({pp.get("lines_label")})' if pp.get('lines_label')
                                                                   else '')
                          + f', meant to feel: {pp.get("intended_delivery")}. The words: "'
                          + ' '.join(strip_tags(x) for x in pp['text'].split('\n')) + '"', '']
        guide += ['Files: ' + ', '.join(f'{x}.mp3' for x in labels), '',
                  '| | ' + ' | '.join(x.split('-')[-1] for x in labels) + ' | same | note |',
                  '|---|' + '---|' * len(labels) + '---|---|']
        guide += [f'| {txt} |' + ' |' * len(labels) + ' | |' for _, txt in TRIAL_LISTEN_ITEMS]
        guide += ['', 'Which would you keep, and why (one line):', '', '']
        done_q.append(q['id'])
    join_rows = []
    for j in joins:
        takes = {(x, v): report['runs'].get(f'{x}|{v}') or {} for v in j['compare'] for x in j['parts']}
        if not all(tk.get('file') and tk.get('measured') for tk in takes.values()):
            continue
        pauses = sorted(pp['pause_s'] for tk in takes.values() for pp in tk.get('pauses') or [])
        gap = min(0.8, max(0.3, pauses[len(pauses) // 2] if pauses else 0.45))
        pa, pb = passages[j['parts'][0]], passages[j['parts'][1]]
        guide += [f'## {j["id"]}: the join between two recorded parts ({pa.get("lines_label")} | {pb.get("lines_label")})',
                  '', f'Meant to feel: {pa.get("intended_delivery")} | then: {pb.get("intended_delivery")}', '',
                  f'Listen for: {j.get("listen_for") or "which sounds like one person telling one story across the join"}',
                  '']
        labels = []
        for i, (_, v) in enumerate(_blind_order(plan['id'], j['id'], [(j['parts'][0], v) for v in j['compare']])):
            lab = f'{j["id"]}-{chr(65 + i)}'
            first, second = takes[(j['parts'][0], v)], takes[(j['parts'][1], v)]
            dst = lst / f'{lab}.mp3'
            _join_audio(first['file'], second['file'], gap, dst)
            labels.append(lab)
            lv = [(tk.get('loudness') or {}).get('integrated_lufs') for tk in (first, second)]
            pc = [tk.get('active_wpm') for tk in (first, second)]
            reg = [(tk.get('delivery') or {}).get('register_hz') for tk in (first, second)]
            join_rows.append({'question': j['id'], 'label': lab, 'variant': v, 'gap_s': round(gap, 2),
                              'level_step_lu': round(lv[1] - lv[0], 1) if None not in lv else None,
                              'pace_step_wpm': (pc[1] - pc[0]) if None not in pc else None,
                              'register_step_hz': round(reg[1] - reg[0], 1) if None not in reg else None,
                              'first_trail_silence_s': first.get('trail_silence_s'),
                              'second_lead_silence_s': second.get('lead_silence_s'), 'file': str(dst),
                              'takes': [first['file'], second['file']]})
            key.append({'question': j['id'], 'label': lab, 'file': str(dst),
                        'run': f'{j["parts"][0]}+{j["parts"][1]}-{v}',
                        'source': f'join of {first["file"]} and {second["file"]}'})
        guide += ['Files: ' + ', '.join(f'{x}.mp3' for x in labels), '',
                  '| | ' + ' | '.join(x.split('-')[-1] for x in labels) + ' | same | note |',
                  '|---|' + '---|' * len(labels) + '---|---|']
        guide += [f'| {txt} |' + ' |' * len(labels) + ' | |' for _, txt in TRIAL_LISTEN_ITEMS]
        guide += ['', 'Which would you keep, and why (one line):', '', '']
        done_q.append(j['id'])
    (lst / 'listening-guide.md').write_text('\n'.join(guide) + '\n', encoding='utf-8')
    by_source = {}
    for k in key:
        by_source.setdefault(k['source'], []).append(k['label'])
    md = [f'# Answer key: {plan["id"]}', '', 'Open after listening. Settings and measurements per take. The numbers are '
          'measurements, not verdicts: a narrower pitch range can be the right, quieter delivery, and a faster take is '
          'not a better one.', '']
    for q in questions:
        if q['id'] not in done_q:
            continue
        md += [f'## {q["id"]}: {q["asks"]}', ('Nothing changes: the same request sent twice (how much one set-up varies '
                                                'by itself).' if q.get('repeat') else
                                                f'Only {", ".join(q["varies"])} changes between these takes.'), '',
               '| label | take | stability | tags | pronunciation | context | active / overall wpm | duration s | '
               'longest pause s | pitch range st | loudness LUFS | credits | anomalies |',
               '|---|---|---|---|---|---|---|---|---|---|---|---|---|']
        for k in [x for x in key if x['question'] == q['id']]:
            x = report['runs'][k['run'].replace('-', '|', 1)]
            v = variants[k['run'].split('-', 1)[1]]
            dl = x.get('delivery') or {}
            md.append(f'| {k["label"]} | {k["run"]} | {v["stability"]} | {v["tags"]} | {"on" if v["pronunciation"] else "off"}'
                      f' | {v["context"]} | {x.get("active_wpm")} / {x.get("overall_wpm")} | {x.get("duration_s")} | '
                      f'{(x.get("pause_profile") or {}).get("longest_pause_s")} | {dl.get("pitch_range_st")} | '
                      f'{(x.get("loudness") or {}).get("integrated_lufs")} | {take_credits(x.get("cost") or {})} | '
                      f'{"; ".join(x.get("anomalies") or []) or "none"} |')
        md.append('')
    for j in joins:
        rows_ = [r for r in join_rows if r['question'] == j['id']]
        if not rows_:
            continue
        md += [f'## {j["id"]}: {j["asks"]}', f'Two requests joined with a {rows_[0]["gap_s"]} s pause; only '
               f'{", ".join(j["varies"])} changes between the versions. A step is the second part minus the first.', '',
               '| label | variant | level step LU | pace step wpm (active) | register step Hz | silence at the end of the '
               'first s | silence before the second s |', '|---|---|---|---|---|---|---|']
        for r in rows_:
            setting = ', '.join(f'{k}={variants[r["variant"]][k]}' for k in j['varies'])
            md.append(f'| {r["label"]} | {r["variant"]} ({setting}) | {r["level_step_lu"]} | {r["pace_step_wpm"]} | '
                      f'{r["register_step_hz"]} | {r["first_trail_silence_s"]} | {r["second_lead_silence_s"]} |')
        md.append('')
    twins = [v for v in by_source.values() if len(v) > 1 and not str(v[0]).startswith('join')]
    if twins:
        md += ['Same recording under two labels (a baseline reused by two questions): ' +
               '; '.join(' = '.join(v) for v in twins), '']
    md += ['## What the numbers can and cannot say', ''] + [f'- {u}' for u in TRIAL_UNCERTAINTIES] + ['']
    (outdir / 'answer-key.md').write_text('\n'.join(md) + '\n', encoding='utf-8')
    write_json(outdir / 'answer-key.json', {'trial': plan['id'], 'labels': key, 'same_recording': twins,
                                            'joins': join_rows})
    return {'listening': str(lst), 'guide': str(lst / 'listening-guide.md'), 'answer_key': str(outdir / 'answer-key.md'),
            'questions_ready': done_q}


def cmd_narration_trial(args):
    """A controlled calibration trial before production: a few passages of this video (an opening, an explanation, a
    turn), each under a few voice set-ups, to learn what this voice does with this treatment: stability, tags or no
    tags, pronunciation, the context across a join, another narrator. The plan is checked (each question compares runs
    that differ in exactly one thing) and priced first; nothing is recorded without --execute. Then the takes are
    recorded one at a time, never two at once, each only after the price is read again, the live balance covers it
    and the plan's budget (the credits the user authorised, shared by every plan under its id, counted from the
    ledger with retries and interrupted requests) still covers its largest possible charge, context fields included.
    A take is saved and put on record the moment it arrives, then measured; re-running the same command continues:
    recorded takes are never sent again (each is matched by the fingerprint of its exact request), a take recorded but
    not measured is measured, and a request cut off by a crash is looked up in the account history before anything is
    paid again. listening/ is the blind set for the user's ears; answer-key.md says which take is which. The
    measurements are evidence, never a verdict on which take sounds better: no agent here can hear them."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    lock = read_json(vd / 'length-lock.json')
    script = read_json(vd / 'script.json')
    lines = script.get('lines') or []
    plan = read_json(args.plan, required=True)
    vf = voice_facts(rd, n)
    # A trial may carry its own pronunciation list, to hear a form before the episode adopts it (the episode's list,
    # and so what its recorded parts are compared against, stays as it is).
    pron = pronunciation_facts(rd, n, lines, plan.get('pronunciation')) if plan.get('pronunciation') is not None \
        else pronunciation_facts(rd, n, lines)
    issues, passages, variants, runs, questions, joins = trial_plan_facts(plan, vf, lines, pron)
    issues += pron['issues']
    budget = plan.get('budget') or {}
    if not issues:
        issues += trial_budget_check(rd, budget, plan['id'])
    if issues:
        error('The trial plan is not ready.', issues)
    lang = language_code((lock or {}).get('language'))

    def path_of(v):
        return '/v1/text-to-speech/' + urllib.parse.quote(v['voice_id'], safe='') + '?output_format=mp3_44100_128'
    bodies = {}
    for r in runs:
        b = trial_request(passages, variants, r, lines, pron)
        if lang:
            b['language_code'] = lang
        bodies[r] = b
    fps = {r: hashlib.sha256(json.dumps({'path': path_of(variants[r[1]]), 'body': bodies[r]}, sort_keys=True,
                                        ensure_ascii=False).encode('utf-8')).hexdigest() for r in runs}
    outdir = rd / '60-voice' / f'video-{n:02d}' / 'trials' / plan['id']
    report = read_json(outdir / 'report.json')
    recorded = report.get('runs') or {}

    def rkey(r):
        return f'{r[0]}|{r[1]}'

    def done(r):
        x = recorded.get(rkey(r)) or {}
        return bool(x.get('file')) and Path(x['file']).is_file() and x.get('request_sha256') == fps[r]
    drifted = [f'{a}-{b}' for a, b in runs if (recorded.get(rkey((a, b))) or {}).get('file') and not done((a, b))]
    if drifted:
        error('Recorded takes no longer match this plan (their exact request changed): a changed plan is a new trial '
              'id, so the recorded evidence stays what it was.', drifted)
    wanted = None
    if args.takes:
        names = {f'{a}-{b}': (a, b) for a, b in runs}
        asked = [x.strip() for x in args.takes.split(',') if x.strip()]
        unknown = [x for x in asked if x not in names]
        if unknown:
            error('--takes names runs this plan does not have.', {'unknown': unknown, 'runs': list(names)})
        wanted = [names[x] for x in asked]
    todo = [r for r in runs if not done(r) and (wanted is None or r in wanted)]
    chars = {r: len(bodies[r]['text']) for r in runs}
    ctx = {r: len(bodies[r].get('previous_text') or '') + len(bodies[r].get('next_text') or '') for r in runs}
    by_model = {}
    for r in todo:
        by_model.setdefault(variants[r[1]]['model_id'], [0, 0])
        by_model[variants[r[1]]['model_id']][0] += chars[r]
        by_model[variants[r[1]]['model_id']][1] += chars[r] + ctx[r]
    treatment = read_json(vd / 'direction-lock.json')
    treatment_info = ({'treatment': treatment.get('treatment'), 'production_rev': treatment.get('production_rev')}
                      if treatment else {'treatment': None, 'note': 'this video has no locked creative direction'})
    summary = {'trial': plan['id'], 'budget': {'id': budget['id'], 'max_credits': budget['max_credits']},
               'runs': len(runs), 'runs_to_record': len(todo),
               'characters_to_record': sum(chars[r] for r in todo),
               'context_characters_to_record': sum(ctx[r] for r in todo),
               'runs_detail': [{'run': f'{a}-{b}', 'moment': passages[a]['moment'], 'characters': chars[(a, b)],
                                'context_characters': ctx[(a, b)], 'voice_id': variants[b]['voice_id'],
                                'model_id': variants[b]['model_id'], 'stability': variants[b]['stability'],
                                'similarity_boost': variants[b]['similarity_boost'], 'tags': variants[b]['tags'],
                                'pronunciation': variants[b]['pronunciation'], 'context': variants[b]['context'],
                                'done': done((a, b)), 'this_time': (a, b) in todo} for a, b in runs],
               'questions': [{'id': q['id'], 'asks': q['asks'], 'compares': [f'{a}-{b}' for a, b in q['compare']],
                              'varies': q['varies'] or (['nothing: the same request twice'] if q.get('repeat') else [])}
                             for q in questions],
               'joins': [{'id': j['id'], 'asks': j['asks'], 'parts': j['parts'], 'compares': j['compare'],
                          'varies': j['varies']} for j in joins]}
    spent, open_ = budget_spent(rd, budget['id'])
    key = elevenlabs_key() if (args.execute or args.check_balance) else ''
    if (args.execute or args.check_balance) and not key:
        error('ELEVENLABS_API_KEY (or ELEVEN_API_KEY) is not set; do not store API keys in the command or ZIP.')
    if not args.execute:
        estimate = {}
        for model, (c, cmax) in by_model.items():
            per = model_rates(rd, key, model, max_age_h=0)['credits_per_character'] if args.check_balance else \
                cached_model_rates(rd, model)
            measured, samples = measured_cost_ratio(rd, model)
            estimate[model] = {'characters': c, 'characters_with_context': cmax, 'credits_per_character': per,
                               'expected_credits': math.ceil(c * per) if per is not None else None,
                               'max_credits': math.ceil(cmax * per) if per is not None else None,
                               'measured_credits_per_character': measured, 'measured_requests': samples}
        known = all(e['expected_credits'] is not None for e in estimate.values())
        total = sum(e['expected_credits'] or 0 for e in estimate.values()) if known else None
        total_max = sum(e['max_credits'] or 0 for e in estimate.values()) if known else None
        out = {'ok': True, 'mode': 'dry_run_no_charges', **summary, 'credit_estimate': estimate,
               'expected_credits_total': total, 'max_credits_total': total_max,
               'budget_status': {'spent': spent, 'left': budget['max_credits'] - spent,
                                 'interrupted_requests': len(open_),
                                 'fits': (spent + total_max <= budget['max_credits']) if total_max is not None else None}}
        if args.check_balance:
            bal = subscription_balance(key)
            out['balance'] = {'available': bal['available'], 'left_after_expected': bal['available'] - (total or 0),
                              'left_after_max': bal['available'] - (total_max or 0),
                              'next_reset_unix': bal['next_reset_unix']}
        out['next'] = ('Show the user this plan: each question, the runs it compares, the credits (expected and at most). '
                       'Record only after their approval: narration-trial ... --execute (one take at a time; --takes to '
                       'record some first).')
        emit(out)
        return
    outdir.mkdir(parents=True, exist_ok=True)
    lockf = outdir / 'trial.lock'
    held = read_json(lockf) if lockf.is_file() else {}
    if held and _pid_running(held.get('pid')):
        error('Another narration-trial is recording this trial (trial.lock): trials run one at a time.',
              {'lock': str(lockf), 'held_by': held})
    lockf.write_text(json.dumps({'pid': os.getpid(), 'at': now()}), encoding='utf-8')
    try:
        if not (outdir / 'plan.json').is_file() or read_json(outdir / 'plan.json') != plan:
            write_json(outdir / 'plan.json', plan)
        trial_budget_check(rd, budget, plan['id'], write=True)
        report = {'trial': plan['id'], 'video': n, 'treatment': treatment_info,
                  'voice_lock': {'file': str(rd / '60-voice' / 'voice-lock.json') if vf.get('legacy')
                                 else str(voice_lock_path(rd, n)), 'legacy': vf.get('legacy'),
                                 'voice_id': vf.get('voice_id'), 'model_id': vf.get('model_id'),
                                 'settings': vf.get('settings')},
                  'budget': summary['budget'], 'questions': summary['questions'], 'runs': recorded,
                  'started_at': report.get('started_at') or now(), 'sessions': (report.get('sessions') or []) + [now()]}
        write_json(outdir / 'report.json', report)
        language = lock.get('language') or 'en'
        # A take recorded but not yet measured (a session that stopped between the two) is measured, never re-sent.
        for r in runs:
            x = recorded.get(rkey(r)) or {}
            if done(r) and not x.get('measured'):
                trial_measure(x, passages[r[0]], [{**t, 'sent_as': t['say'] if variants[r[1]]['pronunciation'] else
                                                   t['term']} for t in pron['terms']], language, args)
                write_json(outdir / 'report.json', report)
        stop = None
        for r in todo:
            v = variants[r[1]]
            body = bodies[r]
            rates = model_rates(rd, key, v['model_id'], max_age_h=0)        # the price, read again before each request
            per = rates['credits_per_character']
            max_cr = math.ceil((chars[r] + ctx[r]) * per)
            spent, open_ = budget_spent(rd, budget['id'])
            # an earlier attempt of this take with no known outcome: its audio from the account history, or a stop
            audio, entry = paid_reconcile(rd, key, fps[r], body, v['voice_id'], args.retry_unreconciled, args.reason)
            if audio is None:
                if spent + max_cr > budget['max_credits']:
                    stop = {'run': f'{r[0]}-{r[1]}', 'why': 'budget', 'spent': spent, 'this_request_at_most': max_cr,
                            'max_credits': budget['max_credits']}
                    break
                need = math.ceil(max_cr * args.credit_safety_factor) + int(args.keep_credits or 0)
                raw, err, entry = eleven_paid_post(
                    rd, key, path_of(v), body, 'trial',
                    {'video': n, 'trial': plan['id'], 'run': f'{r[0]}-{r[1]}', 'model_id': v['model_id'],
                     'voice_id': v['voice_id'], 'budget': budget['id'], 'request_sha256': fps[r],
                     'credits_per_character': per}, require=need, max_credits=max_cr)
                if entry is None:
                    stop = {'run': f'{r[0]}-{r[1]}', 'why': 'balance', 'error': err, 'needed': need}
                    break
                if err or not raw or len(raw) < 1024:
                    stop = {'run': f'{r[0]}-{r[1]}', 'why': 'request_failed', 'error': err or 'audio response too short',
                            'ledger': entry}
                    break
                audio = raw
            f = outdir / f'{r[0]}-{r[1]}.mp3'
            f.write_bytes(audio)
            terms = [{**t, 'sent_as': t['say'] if v['pronunciation'] else t['term']} for t in pron['terms']]
            applied = [{k: t.get(k) for k in ('term', 'say', 'how', 'confidence', 'source')} for t in pron['terms']
                       if v['pronunciation'] and t['rx'].search(strip_tags(passages[r[0]]['text']))]
            rec = {'run': f'{r[0]}-{r[1]}', 'file': str(f), 'request_sha256': fps[r],
                   'sent_text_sha256': hashlib.sha256(body['text'].encode('utf-8')).hexdigest(),
                   'sent': {'endpoint': path_of(v), **{k: body.get(k) for k in ('text', 'previous_text', 'next_text',
                                                                                 'model_id', 'voice_settings',
                                                                                 'language_code')}},
                   'tags': [m.group(0) for m in TAG_RE.finditer(body['text'])], 'pronunciation_applied': applied,
                   'variant': v, 'moment': passages[r[0]]['moment'], 'lines': passages[r[0]].get('lines_label'),
                   'intended_delivery': passages[r[0]]['intended_delivery'], 'treatment': treatment_info,
                   'cost': {'max_credits': max_cr, 'credits_per_character': per, 'characters_text': chars[r],
                            'characters_context': ctx[r],
                            'character_cost_header': (entry or {}).get('character_cost_header'),
                            'balance_drop': (entry or {}).get('delta'),
                            'credits_billed': (entry or {}).get('credits_billed'),
                            'recovered_from_history': (entry or {}).get('phase') == 'recovered'},
                   'ledger_attempt': (entry or {}).get('attempt_id'), 'recorded_at': now(), 'measured': False}
            recorded[rkey(r)] = rec
            write_json(outdir / 'report.json', report)
            trial_measure(rec, passages[r[0]], terms, language, args)
            write_json(outdir / 'report.json', report)
        all_done = all(done(r) for r in runs)
        if all_done:
            report['finished_at'] = now()
        write_json(outdir / 'report.json', report)
        listening = trial_listening_set(outdir, plan, questions, report, passages, variants, joins)
    finally:
        try:
            lockf.unlink()
        except OSError:
            pass
    spent, open_ = budget_spent(rd, budget['id'])
    res = {'ok': stop is None, 'mode': 'recorded', **summary, 'report': str(outdir / 'report.json'), **listening,
           'credits_billed_this_trial': sum((take_credits(x.get('cost') or {}) or 0) for x in report['runs'].values()),
           'budget_status': {'spent': spent, 'left': budget['max_credits'] - spent, 'interrupted_requests': len(open_)},
           'all_recorded': all_done, 'stopped': stop,
           'next': 'Give the user listening/ (blind) and, after their notes, answer-key.md; record their impressions '
                   'next to the measurements. Decide the voice lock (voice-pick) from both, never from the numbers alone.'}
    if stop:
        emit({**res, 'error': 'Stopped before ' + stop['run'] + ': ' + stop['why'] + '. Nothing more was sent; the takes '
                              'already recorded are kept (re-run the same command to continue).'}, 2)
    emit(res)


def parse_voice_settings(raw, model_id):
    try:
        voice_settings = json.loads(raw) if raw else {}
    except ValueError as exc:
        error('--settings must be valid JSON (e.g. \'{"stability": 0.7, "similarity_boost": 0.8}\').', str(exc))
    if not isinstance(voice_settings, dict):
        error('--settings must be a JSON object.')
    # ElevenLabs' v4 pages: "Both variants use two voice settings: Stability and Similarity"; "Style and Speed sliders
    # are not available in Eleven v4"; the migration guide: "Eleven v4 doesn't apply voice_settings.speed". The models'
    # own flags (GET /v1/models) agree: can_use_style=false, can_use_speaker_boost=false. Nothing else is sent.
    for k in voice_settings:
        if k not in VOICE_SETTING_KEYS:
            error(f'Model {model_id!r} applies these voice settings only (no speed, style or speaker boost on v4).',
                  {'allowed': list(VOICE_SETTING_KEYS), 'got': k})
    return voice_settings


def part_records_of(manifest):
    """What each finished part was recorded with. A manifest from before parts carried their own record gives its
    top-level voice, model and settings to every finished part, and its canonical text as what was sent."""
    recs = dict(manifest.get('part_records') or {})
    chunks = {str(c.get('id')): c for c in manifest.get('chunks') or []}
    for x in manifest.get('finished_parts') or []:
        k = str(x)
        if k not in recs:
            c = chunks.get(k) or {}
            recs[k] = {'voice_id': manifest.get('voice_id'), 'model_id': manifest.get('model_id'),
                       'settings': manifest.get('voice_settings') or {},
                       'sent_sha256': c.get('sent_sha256') or c.get('text_sha256'), 'legacy': True}
    return recs


def parts_list(raw):
    try:
        return sorted({int(x) for x in str(raw or '').split(',') if x.strip()})
    except ValueError:
        error('--rerecord-parts takes part numbers, e.g. 2 or 2,5.')


# The words a calibration sample needs: narration-measure writes a voice's real pace from 300+ measured words (short
# samples read fast and scatter).
CALIBRATION_MIN_WORDS = 300


def cmd_tts(args):
    """Record this video's narration in parts, following its plan and its voice lock exactly: voice, model and
    settings come from the lock (a different value on the command line is refused; a change is a voice revision).
    Parts follow the beats (about PART_TARGET_CHARS characters, joins where the story already turns). Each part sends
    its lines' canonical text with their tags and the pronunciation list applied, its neighbours' spoken words as
    context. Every finished part records the voice, model, settings, direction revision and the fingerprint of the
    exact text sent; every billed request goes in the spend ledger with the balance before and after. Finished parts
    are never billed again; a part recorded from other text, another pronunciation, another voice setup or an earlier
    direction is re-recorded only with --rerecord-changed, and a part that must be redone after listening only with
    --rerecord-parts N --reason (old takes always kept in superseded/)."""
    rd, st = run_folder(args)
    n = int(args.video)
    chk = plan_facts(rd, n)
    if not chk['ready']:
        error('Plan must pass objective checks before billed audio generation', chk['issues'])
    vd = video_dir(rd, n)
    script = read_json(vd / 'script.json', required=True)
    lines = script['lines']
    lock = read_json(vd / 'length-lock.json', required=True)
    if not (1.0 <= args.credit_safety_factor <= 3.0):
        error('--credit-safety-factor must be from 1.0 to 3.0')
    if args.max_parts is not None and args.max_parts < 1:
        error('--max-parts must be at least 1.')
    if args.assume_cost_ratio is not None and not (0.1 <= args.assume_cost_ratio <= 1.0):
        error('--assume-cost-ratio must be from 0.1 to 1.0: an explicit, recorded override of the credits per '
              'character ElevenLabs reports for the model, for a ratio measured on this account (the ledger).')
    given = parse_voice_settings(args.settings, args.model_id or 'eleven_v4') if args.settings else None
    vf = voice_facts(rd, n, args.voice_id or None, args.model_id or None, given)
    if vf['conflicts']:
        error('The recording follows this video\'s voice lock; another voice, model or settings on the command line is '
              'refused. A deliberate change is a voice revision: voice-pick --replace --reason "...".',
              {'conflicts': vf['conflicts'], 'voice_lock': {k: vf[k] for k in ('voice_id', 'model_id', 'settings')}})
    voice_id = vf['voice_id'] or args.voice_id
    model_id = vf['model_id'] if vf['lock'] else (args.model_id or 'eleven_v4')
    settings = vf['settings'] if vf['lock'] else (given or {})
    pron = pronunciation_facts(rd, n, lines)
    sent_lines = [tts_text(r['text'], pron['terms']) for r in lines]
    hard_max = model_limit(model_id)
    target = args.max_chars or PART_TARGET_CHARS
    narrdir = rd / '50-audio' / f'video-{n:02d}'
    manifest_path = narrdir / 'manifest.json'
    existing = read_json(manifest_path)
    dlock = read_json(vd / 'direction-lock.json')
    beats = read_json(vd / 'beat-map.json').get('beats') or []
    stamp = dt.datetime.now().strftime('%Y%m%d-%H%M%S')
    other_take = bool(existing) and any(existing.get(x) != y for x, y in
                                        (('model_id', model_id), ('voice_id', voice_id), ('language', lock['language'])))
    start_over = other_take or args.rechunk
    if start_over and not args.archive_existing and existing:
        error('The recorded audio uses another voice/model/language, or --rechunk asks for new part boundaries. '
              'Pass --archive-existing to move the whole folder aside (nothing is deleted; every part is re-billed).',
              {'folder': str(narrdir), 'recorded_with': {k: existing.get(k) for k in ('voice_id', 'model_id', 'language')}})
    chunks = None
    if existing.get('chunks') and not start_over:
        chunks = chunks_from_manifest(existing['chunks'], lines)
        if chunks is None:
            error('Lines were added or removed since the parts were recorded, so their boundaries no longer fit. '
                  'Restore the line count, or re-record everything: --rechunk --archive-existing (every part re-billed).')
        for c, old in zip(chunks, existing['chunks']):
            c['beats'] = old.get('beats') or []
    if chunks is None:
        chunks = chunks_for_beats(lines, beats, target, hard_max)
    for c in chunks:
        c['sent'] = '\n'.join(sent_lines[c['line_start'] - 1:c['line_end']])
    for i, c in enumerate(chunks, 1):
        if len(c['sent']) > hard_max:
            error(f'Part {i} is now longer than the model accepts in one request.', {'characters': len(c['sent'])})
    sha = lambda s: hashlib.sha256(s.encode('utf-8')).hexdigest()
    spec = {'model_id': model_id, 'voice_id': voice_id, 'language': lock['language'],
            'chunks': [{'id': i + 1, 'line_start': c['line_start'], 'line_end': c['line_end'],
                        'beats': c.get('beats') or [], 'text_sha256': sha(c['text']), 'sent_sha256': sha(c['sent']),
                        'file': f'part-{i + 1:03d}.mp3', 'characters': len(c['sent'])}
                       for i, c in enumerate(chunks)]}
    old_chunks = {} if start_over else {c.get('id'): c for c in existing.get('chunks') or []}
    finished_before = [] if start_over else list(existing.get('finished_parts') or [])
    records = {} if start_over else part_records_of(existing)
    changed = [s['id'] for s in spec['chunks'] if s['id'] in finished_before
               and old_chunks.get(s['id'], {}).get('text_sha256') != s['text_sha256']]
    pron_changed = [s['id'] for s in spec['chunks'] if s['id'] in finished_before and s['id'] not in changed
                    and (records.get(str(s['id'])) or {}).get('sent_sha256') != s['sent_sha256']]
    setup = (voice_id, model_id, settings)
    other_setup = [x for x in finished_before if x not in changed and
                   tuple((records.get(str(x)) or {}).get(k) or ({} if k == 'settings' else None)
                         for k in ('voice_id', 'model_id', 'settings')) != setup]
    # Parts recorded before the latest direction change that touched the narrator, unless the narration was
    # reapproved for it (direction-reapprove --artifact narration): re-recorded like changed lines.
    outdated = [] if start_over else [x for x in narration_outdated_parts(dlock, existing) if x in finished_before]
    asked = parts_list(args.rerecord_parts)
    if any(x not in finished_before for x in asked):
        error('--rerecord-parts names parts that are not recorded yet.', {'asked': asked, 'recorded': finished_before})
    redo = sorted(set(changed) | set(pron_changed) | set(other_setup) | set(outdated) | set(asked))
    by_beat = {str(b.get('id')): b for b in beats}
    parts_view = [{'part': s['id'], 'lines': [s['line_start'], s['line_end']], 'characters': s['characters'],
                   'beats': [{'id': b, **{k: (by_beat.get(b) or {}).get(k) for k in ('narration_direction', 'pace')}}
                             for b in s['beats']]} for s in spec['chunks']]
    todo = [s for s in spec['chunks'] if s['id'] not in finished_before or s['id'] in redo]
    if not args.execute:
        per_char = cached_model_rates(rd, model_id)
        if per_char is None and getattr(args, 'read_rates', False):
            rk = elevenlabs_key()
            if rk:   # free: GET /v1/models, cached for the run
                per_char = model_rates(rd, rk, model_id)['credits_per_character']
        chars = sum(s['characters'] for s in todo)
        verified, v_n = measured_cost_ratio(rd, model_id)
        emit({'ok': True, 'mode': 'dry_run_no_charges', 'video': n, 'parts': len(chunks),
              'characters_total': sum(s['characters'] for s in spec['chunks']),
              'parts_to_record': [s['id'] for s in todo], 'changed_recorded_parts': changed,
              'pronunciation_changed_parts': pron_changed, 'parts_recorded_with_another_voice_setup': other_setup,
              'parts_made_for_an_earlier_direction': outdated, 'parts_asked_to_rerecord': asked,
              'starts_over': start_over, 'characters_to_record': chars,
              'credit_estimate': {
                  'expected_credits': (math.ceil(chars * verified) if verified is not None else
                                       math.ceil(chars * per_char) if per_char is not None else None),
                  'basis': (f'verified billing on this account: {verified} credits per character sent, median of '
                            f'{v_n} billed request(s) in the ledger (the cost header)' if verified is not None else
                            'the model rates last read for this run (no billed request in the ledger yet)'
                            if per_char is not None else
                            'not read yet: --read-rates reads them (free); --execute reads them and the live '
                            'balance before anything is sent'),
                  'verified_credits_per_character': verified, 'verified_requests': v_n,
                  'documented_credits_per_character': per_char,
                  'upper_bound_at_documented_rate': math.ceil(chars * per_char) if per_char is not None else None,
                  'note': 'characters = the exact text sent (tags and pronunciation forms included); --execute checks '
                          'the live balance against the documented rate times the safety factor'},
              'calibrated': voice_calibrated(rd, n, voice_id, model_id, settings),
              'voice': {'voice_id': voice_id, 'model_id': model_id, 'settings': settings,
                        'voice_rev': vf['voice_rev'], 'older_run_level_lock': vf['legacy']},
              'execute_blockers': vf['issues'], 'voice_warnings': vf['warnings'],
              'pronunciation_terms': [t['term'] for t in pron['terms']],
              'model_limit_per_request': hard_max, 'part_target_chars': target, 'parts_view': parts_view,
              'target_length_s': lock['target_length_s'], 'candidate_manifest': spec,
              'next': 'Review the parts, the voice lock and the credits. Re-run with --execute only after approving cost.'})
        return
    if vf['issues']:
        error('This video has no usable voice lock for recording.', {
            'issues': vf['issues'], 'how': 'voice-pick --run RUN --video N --voice-id ID --settings \'{...}\' --reason '
                                           '"..." (after a direction change: --replace, or direction-reapprove '
                                           '--artifact voice)'})
    key = elevenlabs_key()
    if not key:
        error('ELEVENLABS_API_KEY (or ELEVEN_API_KEY) is not set; do not store API keys in the command or ZIP.')
    hold_process_lock(rd / '50-audio' / f'.tts-video-{n:02d}.lock', 'tts recording')
    flagged = [x for x in redo if x not in asked]
    if flagged and not args.rerecord_changed:
        error('Recorded parts no longer match what this video would record now: their lines changed, the '
              'pronunciation list changed what they send, they were recorded with another voice setup, or before the '
              'latest direction change to the narrator. Re-record only those parts with --rerecord-changed (their old '
              'takes move to superseded/, never deleted), or, when the recorded voice still serves the locked '
              'treatment after a direction change, keep them with direction-reapprove --artifact narration --reason.',
              {'changed_parts': changed, 'pronunciation_changed_parts': pron_changed,
               'parts_recorded_with_another_voice_setup': other_setup, 'parts_made_for_an_earlier_direction': outdated,
               'characters': sum(s['characters'] for s in spec['chunks'] if s['id'] in flagged)})
    if asked and n_words(args.reason) < MIN_NOTE_WORDS:
        error('Say why these parts are recorded again (--reason): what was heard, or what the checks found.')
    kept = [] if start_over else [x for x in finished_before if x not in redo
                                  and (narrdir / f'part-{x:03d}.mp3').is_file()
                                  and (narrdir / f'part-{x:03d}.mp3').stat().st_size > 1024]
    remaining = [s for s in spec['chunks'] if s['id'] not in kept]
    batch = remaining[:args.max_parts] if args.max_parts else remaining
    # Calibrate first: until this exact voice, model and settings has a real measured pace, only the parts it takes to
    # reach a measurable sample are recorded (CALIBRATION_MIN_WORDS, counting parts already recorded with it and not yet
    # measured); then narration-measure. Recording one part at a time does not get round it.
    skipped_calibration = []
    if not voice_calibrated(rd, n, voice_id, model_id, settings):
        def words_of(s):
            return sum(count_words(lines[li - 1].get('text') or '') for li in range(s['line_start'], s['line_end'] + 1))
        same = [x for x in kept if tuple((records.get(str(x)) or {}).get(k) or ({} if k == 'settings' else None)
                                         for k in ('voice_id', 'model_id', 'settings')) == setup]
        have = sum(words_of(s) for s in spec['chunks'] if s['id'] in same)
        allowed = []
        for s in remaining:
            if have >= CALIBRATION_MIN_WORDS:
                break
            allowed.append(s['id'])
            have += words_of(s)
        beyond = [s['id'] for s in batch if s['id'] not in allowed]
        if beyond and not args.skip_calibration:
            error('Calibrate first: this voice, model and settings has no real measured pace yet. Record only the '
                  f'calibration part(s) {allowed or "(none left: they are recorded)"}'
                  + (f' (--max-parts {len(allowed)} --execute)' if allowed else '')
                  + ', run narration-measure on them, check plan-check\'s real_forecast_s, then record the rest.',
                  {'calibration_parts': allowed, 'recorded_not_measured': same,
                   'words_needed': CALIBRATION_MIN_WORDS, 'asked_for': [s['id'] for s in batch]})
        if beyond and n_words(args.reason) < MIN_NOTE_WORDS:
            error('--skip-calibration records parts before this voice is measured: say why on record (--reason).')
        skipped_calibration = beyond
    rates = model_rates(rd, key, model_id)
    req_max = rates.get('maximum_text_length_per_request')
    if req_max and any(s['characters'] > int(req_max) for s in batch):
        error('A part is longer than ElevenLabs now accepts for this model in one request.',
              {'max_characters': req_max, 'parts': [s['id'] for s in batch if s['characters'] > int(req_max)]})
    # The balance is checked before anything on disk moves: a failed preflight leaves the folder as it was.
    budget = credit_preflight(rd, key, model_id, sum(s['characters'] for s in batch), args.credit_safety_factor,
                              args.assume_cost_ratio, args.keep_credits, 'this recording') if batch else {}
    history = list(existing.get('history') or [])
    if start_over and existing:
        archive = narrdir.with_name(f'{narrdir.name}-archive-{stamp}')
        shutil.move(str(narrdir), str(archive))
        history = [{'at': now(), 'archived_previous_take_to': str(archive),
                    'reason': (getattr(args, 'reason', None) or None)}]
        existing = {}
    narrdir.mkdir(parents=True, exist_ok=True)
    if redo:
        sup = narrdir / 'superseded'
        sup.mkdir(exist_ok=True)
        for pid in redo:
            part = narrdir / f'part-{pid:03d}.mp3'
            if part.exists():
                shutil.move(str(part), str(sup / f'part-{pid:03d}-{stamp}.mp3'))
        if (narrdir / 'narration.wav').exists():
            shutil.move(str(narrdir / 'narration.wav'), str(sup / f'narration-{stamp}.wav'))
        history.append({'at': now(), 'rerecorded_parts': redo, 'text_changed': changed,
                        'pronunciation_changed': pron_changed, 'other_voice_setup': other_setup,
                        'earlier_direction': outdated, 'asked': asked, 'reason': args.reason or None,
                        'old_takes': str(sup)})
    if skipped_calibration:
        history.append({'at': now(), 'skip_calibration': skipped_calibration, 'reason': args.reason})
    part_revs = {k: v for k, v in (existing.get('part_revs') or {}).items() if str(k).isdigit() and int(k) in kept}
    part_records = {k: v for k, v in records.items() if str(k).isdigit() and int(k) in kept}
    base = {'voice_id': voice_id, 'model_id': model_id, 'settings': settings, 'voice_rev': vf['voice_rev'],
            'older_run_level_lock': vf['legacy'], 'treatment': dlock.get('treatment'),
            'production_rev': dlock.get('production_rev', 1)}
    manifest = {**spec, 'status': 'partial', 'created_at': existing.get('created_at', now()),
                'credit_preflight': budget, 'voice_settings': settings, 'voice_lock': base,
                'pronunciation_terms': [t['term'] for t in pron['terms']],
                'finished_parts': kept, 'part_revs': part_revs, 'part_records': part_records, 'history': history}
    write_json(manifest_path, manifest)
    per_char = budget.get('credits_per_character') or rates['credits_per_character']
    keep = int(args.keep_credits or 0)
    code = language_code(lock['language'])
    new_parts_done = 0
    for i, (c, s) in enumerate(zip(chunks, spec['chunks'])):
        fname = narrdir / s['file']
        if s['id'] in manifest['finished_parts'] and fname.exists() and fname.stat().st_size > 1024:
            continue
        if args.max_parts and new_parts_done >= args.max_parts:
            break
        body = {'text': c['sent'], 'model_id': model_id, 'voice_settings': settings}
        if code:
            body['language_code'] = code
        prev = context_text(sent_lines, c['line_start'] - 1, -1) if i else ''
        nxt = context_text(sent_lines, c['line_end'] + 1, 1) if i < len(chunks) - 1 else ''
        if prev:
            body['previous_text'] = prev
        if nxt:
            body['next_text'] = nxt
        path = '/v1/text-to-speech/' + urllib.parse.quote(voice_id, safe='') + '?output_format=mp3_44100_128'
        need = math.ceil(s['characters'] * per_char * args.credit_safety_factor) + keep
        req_sha = paid_request_sha(path, body, voice_id)
        raw, entry = paid_reconcile(rd, key, req_sha, body, voice_id, args.retry_unreconciled, args.reason)
        err = None
        if raw is None:
            try:
                raw, err, entry = eleven_paid_post(rd, key, path, body, 'tts',
                                                   {'video': n, 'part': s['id'], 'model_id': model_id,
                                                    'voice_id': voice_id, 'request_sha256': req_sha}, require=need)
            except RuntimeError as exc:
                raw, err, entry = None, str(exc), None
        if not err and (not raw or len(raw) < 1024):
            err = 'audio response too short'
        if not err:
            temp = fname.with_suffix('.download')
            temp.write_bytes(raw)
            try:
                probe(temp)  # ffprobe reads audio, even though temp suffix is generic
                temp.replace(fname)
            except (RuntimeError, ValueError, OSError) as exc:
                err = f'unreadable audio: {str(exc)[:200]}'
        if err:
            manifest['error'] = f'part {s["id"]}: {err}'
            write_json(manifest_path, manifest)
            unsure = (entry or {}).get('outcome') in PAID_UNSETTLED
            error('Partial ElevenLabs recording: BLOCKED (never shorten video to match credits).',
                  {'error': manifest['error'], 'ledger_entry': entry, 'outcome': (entry or {}).get('outcome'),
                   'resume': ('the same command again: it first looks for this part in the account history (free) and '
                              'sends nothing while its outcome is unknown' if unsure else
                              'the same command again: finished parts are kept and never billed again')})
        manifest['finished_parts'].append(s['id'])
        manifest['part_revs'][str(s['id'])] = dlock.get('production_rev', 1)
        manifest['part_records'][str(s['id'])] = {
            **base, 'text_sha256': s['text_sha256'], 'sent_sha256': s['sent_sha256'], 'characters_sent': s['characters'],
            'previous_text_sha256': sha(prev) if prev else None, 'next_text_sha256': sha(nxt) if nxt else None,
            'request_id': (entry or {}).get('request_id'), 'credits_billed': billed_credits(entry),
            'recovered_from_history': (entry or {}).get('phase') == 'recovered',
            'recorded_at': now()}
        manifest.pop('error', None)
        write_json(manifest_path, manifest)
        new_parts_done += 1
    if len(manifest['finished_parts']) < len(chunks):
        emit({'ok': True, 'mode': 'partial_by_design_max_parts', 'new_parts_this_call': new_parts_done,
              'finished_parts': manifest['finished_parts'], 'total_parts': len(chunks),
              'parts_dir': str(narrdir),
              'next': 'Listen to the new part(s), then narration-measure (real pace, natural gap per line, what '
                      'each tag cost, every line heard) and plan-check (real_forecast_s against the export window). '
                      'The planning pace is a forecast, never a target: a real conflict with the locked length is '
                      'diagnosed (voice, density, delivery or length) and taken to the user, never forced (05, step '
                      '3). Then re-run the same tts command (no --max-parts) for the rest -- finished parts are kept, '
                      'never re-billed.'})
        return
    concat = narrdir / 'parts.txt'
    concat.write_text(''.join("file '" + str((narrdir / x['file']).resolve()).replace('\\', '/').replace("'", "'\\''") + "'\n"
                              for x in manifest['chunks']), encoding='utf-8')
    outpath = narrdir / 'narration.wav'
    run_cmd(['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', '-f', 'concat', '-safe', '0',
             '-i', str(concat), '-ar', '44100', '-ac', '2', '-c:a', 'pcm_s16le', str(outpath)])
    manifest['status'] = 'complete'
    manifest['duration_s'] = probe(outpath)['duration_s']
    manifest.pop('error', None)
    write_json(manifest_path, manifest)
    gate = audio_facts(rd, n)
    emit({'ok': gate['ready'], 'audio_file': str(outpath), 'duration_s': manifest['duration_s'],
          'audio_gate': gate, 'next': 'narration-measure: every line heard, tags not read aloud, the joins, the real pace.'},
         0 if gate['ready'] else 2)


def audio_facts(rd, video):
    vd = video_dir(rd, video)
    lock = read_json(vd / 'length-lock.json')
    script = read_json(vd / 'script.json')
    folder = rd / '50-audio' / f'video-{int(video):02d}'
    manifest = read_json(folder / 'manifest.json')
    issues = []
    if not lock:
        issues.append('missing_duration_lock')
    if not manifest:
        issues.append('narration_manifest_missing')
    if manifest.get('status') != 'complete':
        issues.append('audio_is_partial_or_unverified')
    if len(manifest.get('finished_parts', [])) != len(manifest.get('chunks', [])):
        issues.append('not_all_tts_parts_finished')
    cursor = 0
    part_durations = []
    script_lines = script.get('lines') or []
    for chunk in manifest.get('chunks') or []:
        if chunk.get('line_start') != cursor + 1 or chunk.get('line_end', 0) < chunk['line_start']:
            issues.append('audio_line_coverage_gap_overlap')
        cursor = chunk.get('line_end', cursor)
        part = folder / chunk.get('file', '__missing__')
        if not part.is_file():
            issues.append('audio_file_missing:' + chunk.get('file', '?'))
        else:
            try:
                part_durations.append(probe(part)['duration_s'])
            except (RuntimeError, ValueError):
                issues.append('audio_part_unreadable:' + chunk.get('file', '?'))
        lo = chunk.get('line_start', 0)
        hi = chunk.get('line_end', 0)
        text = '\n'.join(str(row.get('text') or '').strip() for row in script_lines[max(0, lo-1):hi])
        if text and hashlib.sha256(text.encode('utf-8')).hexdigest() != chunk.get('text_sha256'):
            issues.append('audio_part_text_hash_mismatch:' + chunk.get('file', '?'))
    if cursor != len(script.get('lines') or []):
        issues.append('some_script_lines_unrecorded')
    fname = folder / 'narration.wav'
    duration = None
    if not fname.is_file():
        issues.append('joined_narration_missing')
    else:
        try:
            duration = probe(fname)['duration_s']
        except (RuntimeError, ValueError) as exc:
            issues.append('narration_duration_unreadable:' + str(exc)[:160])
    target = lock.get('target_length_s')
    if target and duration and abs(target-duration) > max(8, target * lock.get('tolerance_audio_pct', 0.04)):
        issues.append('narration_duration_outside_locked_tolerance')
    if duration and part_durations and abs(sum(part_durations) - duration) > max(3, 0.01*duration):
        issues.append('joined_narration_differs_from_sum_of_parts')
    # Recorded before the latest direction change to the narrator: re-recorded or explicitly reapproved first.
    old_parts = narration_outdated_parts(read_json(vd / 'direction-lock.json'), manifest) if manifest else []
    if old_parts:
        issues.append('narration_parts_made_for_an_earlier_direction:' + ','.join(str(x) for x in old_parts))
    # One narrator throughout: every part recorded with the voice, model and settings of the video's voice lock.
    warnings = []
    vf = voice_facts(rd, video)
    if manifest and vf['lock']:
        recs = part_records_of(manifest)
        setup = (vf['voice_id'], vf['model_id'], vf['settings'])
        other = [x for x in manifest.get('finished_parts') or []
                 if tuple((recs.get(str(x)) or {}).get(k) or ({} if k == 'settings' else None)
                          for k in ('voice_id', 'model_id', 'settings')) != setup]
        if other:
            issues.append('narration_parts_recorded_with_another_voice_setup:' + ','.join(str(x) for x in other))
    # Every line heard, no tag read aloud (narration-measure, on these exact parts).
    lt = read_json(folder / 'line-times.json')
    seam_s = 0.0
    if lt:
        now_prints = {c.get('id'): quick_fingerprint(folder / c['file']) for c in manifest.get('chunks') or []
                      if (folder / c.get('file', '__missing__')).is_file()}
        current = bool(lt.get('parts')) and all(p.get('fingerprint') == now_prints.get(p.get('id'))
                                                for p in lt['parts'])
        if current:
            issues += [f'narration_line_not_heard:{x}' for x in lt.get('unheard_lines') or []]
            issues += [f'narration_tag_read_aloud:{t["line"]}:{t["tag"]}' for t in lt.get('tags_read_aloud') or []]
            issues += [f'narration_words_missing:{m["line"]}:{m["words"]}' for m in lt.get('missing_runs') or []]
            seam_s = sum(float(s.get('seam_hold_s') or 0) for s in lt.get('seams') or [])
            # delivery against intent, answered in context (editorial-review.md, a Pace heading: the beat id and why)
            pace_txt = editorial_section((vd / 'editorial-review.md').read_text(encoding='utf-8', errors='replace')
                                         if (vd / 'editorial-review.md').is_file() else '', 'pace')
            sigs = lt.get('pace_signals') if 'pace_signals' in lt else (lt.get('pace_findings') or [])
            unanswered = [f['beat'] for f in sigs or []
                          if not any(re.search(r'\b' + re.escape(f['beat']) + r'\b', ln) and n_words(ln) >= MIN_NOTE_WORDS
                                     for ln in pace_txt.splitlines())]
            if unanswered:
                issues.append('pace_signals_not_examined_in_the_editorial_review:' + ','.join(unanswered)
                              + ':under_a_Pace_heading_say_what_the_measured_pace_does_there_and_whether_it_stays_'
                                '(beats_with_one_shared_cause_may_share_a_line)')
            for s in lt.get('seams') or []:
                if s.get('level_step_lu') is not None and abs(float(s['level_step_lu'])) >= JOIN_LEVEL_STEP_LU:
                    warnings.append(f'the voice steps {float(s["level_step_lu"]):+g} LU across the join after part '
                                    f'{s.get("after_part")}: listen')
        else:
            # what was heard, timed and joined describes other audio: nothing downstream may lean on it
            issues.append('narration_measurement_describes_an_earlier_recording:run_narration-measure')
    elif manifest.get('status') == 'complete':
        issues.append('narration_not_measured:run_narration-measure_(every_line_heard_and_timed,_its_joins)')
    # The picture can't be shorter than the narration, and export-check holds the export to its own (tighter)
    # window: narration plus the silence the edit holds add must already fit it, or the export can never pass. A hold
    # adds what was decided against the voice's measured gap there (estimated the same way while still provisional);
    # a join that already carries a hold gets no seam hold on top.
    hf = hold_facts(rd, video, script_lines)
    holds = hf['added_s']
    held_lines = {h['line'] for h in hf['holds']}
    if lt and seam_s:
        seam_s = sum(float(s.get('seam_hold_s') or 0) for s in lt.get('seams') or [] if s.get('after_line') not in held_lines)
    window = None
    if target and duration:
        tol_e = max(4, target * lock.get('tolerance_export_pct', .025))
        window = [round(target - tol_e, 2), round(target + tol_e, 2)]
        if duration + holds + seam_s > target + tol_e:
            issues.append('narration_plus_edit_holds_longer_than_export_window')
        elif duration + holds + seam_s < target - tol_e:
            issues.append('narration_plus_edit_holds_shorter_than_export_window')
    older_plan_advisory(rd, video, issues, warnings)
    return {'ready': not issues, 'issues': issues, 'warnings': warnings, 'duration_s': duration,
            'target_length_s': target, 'edit_holds_s': holds, 'seam_holds_s': round(seam_s, 2),
            'expected_edit_s': round(duration + holds + seam_s, 2) if duration else None, 'export_window_s': window,
            'script_lines': len(script.get('lines') or []),
            'recorded_lines': cursor, 'manifest_status': manifest.get('status')}


def cmd_audio_check(args):
    rd, st = run_folder(args)
    result = audio_facts(rd, args.video)
    emit(result, 0 if result['ready'] else 2)


def shot_structure_sha(shots):
    """What the edit's timing depends on: which shots, for which beats, over which lines (prompts can change freely)."""
    return canonical_sha([[str(s.get(k)) for k in ('id', 'beat_id', 'line_start', 'line_end')]
                          + ([str(s.get('start_word'))] if s.get('start_word') else []) for s in shots or []])


def _run_file(rd, f):
    p = Path(str(f or '')).expanduser()
    return (p if p.is_absolute() else rd / p).resolve()


def timeline_facts(rd, video):
    """The CapCut project as recorded in timeline.json (written from CapCut's own read-back), against the plan it
    must follow: every visual segment is a retimed shot of the current edit plan (shot_id), for that shot's beat,
    starting where retime-shots put it, and shows that shot's own still (asset_path traced through the stills record;
    a callback shot may show the shot it reuses); every shot is in the cut; every audio track other than the
    narration names the beats it serves and plays inside them; music comes from the gated worker under the current
    direction; the stills are current (stills_facts); the edit plan describes the current shots, script and
    direction. Plus the length and format checks the timeline always had."""
    n = int(video)
    vd = video_dir(rd, n)
    lock = read_json(vd / 'length-lock.json')
    dlock = read_json(vd / 'direction-lock.json')
    track = read_json(rd / '70-edit' / f'video-{n:02d}' / 'timeline.json')
    sound = audio_facts(rd, n)
    issues = ([] if sound['ready'] else ['audio_gate_failed'])
    warnings = []
    if not lock:
        issues.append('length_lock_missing')
    seq = track.get('visual_segments') or []
    if not seq:
        issues.append('timeline_visual_segments_missing')
    beat_ids = {str(b.get('id')) for b in read_json(vd / 'beat-map.json').get('beats') or []}
    plan = read_json(artifact_path(rd, n, 'edit'))
    plan_shots = {str(s.get('id')): s for s in plan.get('shots') or []}
    cur_shots = read_json(artifact_path(rd, n, 'shot-plan')).get('shots') or []
    reuse_of = {str(s.get('id')): str(s.get('reuses')) for s in cur_shots if s.get('reuses')}
    stills = read_json(artifact_path(rd, n, 'stills')).get('images') or {}
    stills_reapproved = bool(reapproved_for(dlock, 'stills'))
    if not plan:
        issues.append('edit_plan_missing_run_retime_shots')
    else:
        lines = read_json(vd / 'script.json').get('lines') or []
        if plan.get('shot_structure_sha256') != shot_structure_sha(cur_shots) or \
                plan.get('script_sha256') != script_hash(lines):
            issues.append('edit_plan_outdated_rerun_retime_shots')
        if not media_current(dlock, 'edit', (plan.get('direction') or {}).get('production_rev')):
            issues.append('edit_plan_made_for_an_earlier_direction')
        # The held silences: timed from the decisions in force, and each one decided again with its picture (the shot
        # on screen while it lasts, as that shot's still is now). A decision written down before the picture existed
        # is a proposal the picture can overturn.
        hf = hold_facts(rd, n, lines)
        if (plan.get('hold_decisions_sha256') is not None or hf['holds']) and \
                plan.get('hold_decisions_sha256') != hold_decisions_sha(rd, n):
            issues.append('edit_plan_outdated_holds_changed_rerun_retime_shots')
        not_with_picture = [h['line'] for h in hf['holds'] if h.get('index') and h['status'] != 'decided_picture']
        if not_with_picture:
            issues.append('holds_not_decided_with_their_picture:' + ','.join(not_with_picture))
        gone = [h['line'] for h in hf['holds'] if h['status'] == 'line_not_in_script']
        if gone:
            warnings.append('hold decisions for lines the script no longer has (ignored): ' + ','.join(gone))
        for h in hf['holds']:
            if h['status'] == 'decided_picture':
                seen_pic = (h.get('decision') or {}).get('picture') or {}
                now_pic = hold_shot(rd, n, h['index']) or {}
                if (seen_pic.get('shot_id'), seen_pic.get('still_fingerprint')) != \
                        (now_pic.get('shot_id'), now_pic.get('still_fingerprint')):
                    issues.append(f'hold_{h["line"]}_decided_with_another_picture')
        # What the bed does around each held silence, as decided, in the project: it enters, stops, goes on under it,
        # or there is none (from timeline.json's music and ambience tracks). A dip or a swell is a volume move the
        # project's read-back here does not carry: it is listed to listen to, never claimed.
        beds = [t for t in track.get('audio_tracks') or [] if isinstance(t, dict)
                and str(t.get('kind') or '').lower() in BED_KINDS and t.get('start_s') is not None
                and t.get('end_s') is not None]
        for p in plan.get('pauses') or []:
            bed, tm = (p.get('transition') or {}).get('bed'), p.get('times_in_edit') or {}
            if not bed or not tm:
                continue
            a, b = float(tm['silence_from_s']), float(tm['silence_to_s'])
            nxt = float(tm.get('next_line_s') or b)
            spans_ = [(float(t['start_s']), float(t['end_s'])) for t in beds]
            covers = any(s <= a + 0.05 and e >= b - 0.05 for s, e in spans_)
            under = any(s < b - 0.2 and e > a + 0.2 for s, e in spans_)
            ok = {'enters': any(a - 0.5 <= s <= nxt + 0.5 for s, _ in spans_),
                  'stops': any(a - 0.5 <= e <= nxt + 0.5 for _, e in spans_),
                  'continues': covers, 'none': not under, 'dips': covers, 'swells': covers}[bed]
            if not ok:
                issues.append(f'hold_{p["after_line"]}_bed_{bed}_not_in_the_project_at_{_mmss(a)}')
            elif bed in ('dips', 'swells'):
                warnings.append(f'{p["after_line"]}: the bed {bed} at {_mmss(a)}-{_mmss(nxt)}: a volume move the read-back '
                                'does not carry; listen there')
    cursor, seen = 0.0, {}
    for i, clip in enumerate(seq, 1):
        try:
            a, b = float(clip['start_s']), float(clip['end_s'])
            if abs(a-cursor) > .16 or b <= a:
                issues.append(f'visual_gap_overlap_{i}')
            if not str(clip.get('beat_id') or '').strip():
                issues.append(f'visual_{i}_missing_beat_link')
            elif beat_ids and str(clip.get('beat_id')).strip() not in beat_ids:
                issues.append(f'visual_{i}_beat_not_in_beat_map')   # the cut would follow a beat that isn't planned
            if not str(clip.get('purpose') or '').strip():
                issues.append(f'visual_{i}_missing_story_purpose')
            sid = str(clip.get('shot_id') or '').strip()
            if not sid:
                issues.append(f'visual_{i}_missing_shot_id')
            elif plan_shots and sid not in plan_shots:
                issues.append(f'visual_{i}_shot_not_in_edit_plan')
            elif plan_shots:
                if str(plan_shots[sid].get('beat_id')) != str(clip.get('beat_id')):
                    issues.append(f'visual_{i}_beat_differs_from_its_shot')
                seen.setdefault(sid, []).append(a)
            if not str(clip.get('asset_path') or '').strip():
                issues.append(f'visual_{i}_missing_asset_path')
            elif sid:   # the picture CapCut really shows, traced to the shot (and beat) it was made for
                rec = stills.get(_pkey(_run_file(rd, clip['asset_path'])))
                if rec and str(rec.get('shot_id')) not in (sid, reuse_of.get(sid)):
                    issues.append(f'visual_{i}_shows_the_still_of_shot_{rec.get("shot_id")}')
                elif not rec and not stills_reapproved:
                    issues.append(f'visual_{i}_still_without_provenance')
            cursor = b
        except (KeyError, TypeError, ValueError):
            issues.append(f'bad_visual_segment_{i}')
    looks = read_json(picture_looks_path(rd, n)).get('looks') or {}
    prov_people = still_provenance_by_file(rd, n)
    unlooked, flagged = [], []
    themes_sha = canonical_sha(excluded_themes(rd, n))
    for f in dict.fromkeys(_run_file(rd, c.get('asset_path')) for c in seq
                           if isinstance(c, dict) and str(c.get('asset_path') or '').strip()):
        rec = looks.get(_pkey(f))
        pq = (prov_people.get(_pkey(f)) or {}).get('people_question')
        # a look taken before the content reviews changed did not check for what they rule out now; a still with a
        # people question needs a look that answered it
        if not rec or not f.is_file() or rec.get('sha256') != file_sha256(f) or \
                ('themes_sha256' in rec and rec['themes_sha256'] != themes_sha) or (pq and not rec.get('people')):
            unlooked.append(f.name)
        elif rec.get('result') != 'clean':
            flagged.append(f.name)
    if unlooked:
        issues.append(f'pictures_not_content_checked:{len(unlooked)}:' + ','.join(unlooked[:10])
                      + ('...' if len(unlooked) > 10 else ''))
    if flagged:
        issues.append(f'pictures_with_a_content_issue:{len(flagged)}:' + ','.join(flagged[:10]))
    if seq:
        for sid, s in plan_shots.items():
            if sid not in seen:
                issues.append(f'shot_{sid}_missing_from_timeline')
            elif abs(min(seen[sid]) - float(s.get('start_s') or 0)) > 0.5:
                issues.append(f'shot_{sid}_starts_off_its_retimed_time')
    if lock and abs(cursor - lock['target_length_s']) > max(4, lock['target_length_s'] * lock.get('tolerance_export_pct', .025)):
        issues.append('timeline_misses_locked_target')
    if plan.get('edit_duration_s') and seq and abs(cursor - plan['edit_duration_s']) > 0.5:
        issues.append('timeline_end_differs_from_edit_plan')   # the project drifted from the retimed shots
    spans = {str(b.get('id')): (float(b.get('start_s') or 0), float(b.get('end_s') or 0)) for b in plan.get('beats') or []}
    music = read_json(artifact_path(rd, n, 'music')).get('tracks') or {}
    music_used = False
    for j, seg in enumerate(track.get('audio_tracks') or [], 1):
        kind = str(seg.get('kind') or '')
        if kind == 'narration':
            continue
        bs = [str(x) for x in seg.get('beats') or []]
        if not bs or any(x not in beat_ids for x in bs):
            issues.append(f'audio_track_{j}_must_name_beats_of_the_beat_map')
        else:
            try:
                a, b = float(seg['start_s']), float(seg['end_s'])
                if spans and not any(x in spans and a < spans[x][1] and b > spans[x][0] for x in bs):
                    issues.append(f'audio_track_{j}_plays_outside_its_beats')
            except (KeyError, TypeError, ValueError):
                issues.append(f'audio_track_{j}_needs_start_s_and_end_s')
        if kind == 'music':
            music_used = True
            rec = music.get(_pkey(_run_file(rd, seg.get('file')))) if seg.get('file') else None
            if not rec and not reapproved_for(dlock, 'music'):
                issues.append(f'audio_track_{j}_music_without_provenance')
            elif rec and not media_current(dlock, 'music', rec.get('production_rev')):
                issues.append(f'audio_track_{j}_music_made_for_an_earlier_direction')
            elif rec and rec.get('file_sha256') and _run_file(rd, seg.get('file')).is_file() and \
                    file_sha256(_run_file(rd, seg.get('file'))) != rec['file_sha256']:
                # the file at that path is no longer the bed that was made and recorded (replaced, re-rendered)
                issues.append(f'audio_track_{j}_music_file_changed_since_it_was_made:{Path(str(seg.get("file"))).name}')
    if music and not music_used:
        warnings.append('music was made for this video but timeline.json lists no music track: if the bed is in '
                        'the project, record it (audio_tracks: kind "music", its file, start_s, end_s and beats)')
    # The approved narration in the cut, whole: read from the CapCut project itself when timeline.json names it
    # (capcut_draft), else from timeline.json's narration entries.
    expect = plan.get('narration_for_edit') or {}
    nsegs = None
    if track.get('capcut_draft') and expect.get('file'):
        try:
            want = _pkey(_run_file(rd, expect['file']))
            nsegs = [s for s in capcut_audio_segments(track['capcut_draft']) if _pkey(s['file']) == want]
        except (OSError, ValueError, KeyError, TypeError) as exc:
            issues.append('capcut_project_unreadable:' + str(exc)[:120])
    if nsegs is None:
        nsegs = [s for s in track.get('audio_tracks') or [] if str(s.get('kind')) == 'narration']
    issues += narration_track_issues(rd, nsegs, expect)
    # The captions, as the user chose them at the start: read back from the project itself.
    try:
        cissues, cchoice = captions_plan_facts(rd, n)
    except (RuntimeError, ImportError) as exc:
        cissues, cchoice = [f'captions_not_checked:{str(exc)[:120]}'], (None, None)
    if cchoice[0] is None:
        warnings.append('the user has not chosen the captions for this run (captions-choice): none are checked')
    elif cissues:
        issues += cissues
    elif track.get('capcut_draft'):
        try:
            cres = _captions().check_draft(track['capcut_draft'], read_json(captions_plan_path(rd, n)))
            issues += cres['issues']
            warnings += cres['warnings']
        except (OSError, ValueError, KeyError, TypeError) as exc:
            issues.append('captions_unreadable_in_the_project:' + str(exc)[:120])
    else:
        warnings.append('timeline.json names no capcut_draft: the captions were not read back from the project')
    # The checks above read timeline.json: it must still be what the saved project shows (a picture swapped, a clip
    # moved or a sound added in CapCut after timeline-write is a timeline.json that describes another project).
    if track.get('capcut_draft'):
        try:
            live = project_snapshot(rd, n, track['capcut_draft'])
            seen = {'visual': [[str(v.get('shot_id')), _pkey(str(v.get('asset_path') or '')), v.get('start_s'), v.get('end_s')]
                               for v in seq],
                    'overlays': [[str(o.get('track') or ''), _pkey(str(o.get('file') or '')), o.get('start_s'), o.get('end_s')]
                                 for o in track.get('overlays') or []]}
            diff = project_changes(seen, {'visual': live['visual'], 'overlays': live['overlays']})
            if diff:
                issues.append('timeline_json_differs_from_the_saved_project:run_timeline-write:' + '; '.join(diff[:3]))
        except (OSError, ValueError, KeyError, TypeError) as exc:
            issues.append('capcut_project_unreadable:' + str(exc)[:120])
    sf = stills_facts(rd, n)
    issues += sf['issues']
    warnings += sf['warnings']
    d_iss, d_warn = drawing_facts(rd, n)
    issues += d_iss
    warnings += d_warn
    if track.get('canvas') not in ('1920x1080', '2560x1440', '3840x2160'):
        issues.append('canvas_not_youtube_16_9')
    warnings += drawing_readability(track.get('overlays') or [],
                                    str(read_json(rd / 'state.json').get('captions') or 'on') != 'off')
    return {'ready': not issues, 'issues': issues, 'warnings': warnings, 'last_visual_end_s': cursor,
            'target_length_s': lock.get('target_length_s'), 'audio_ready': sound['ready']}


# ---------------------------------------------------------------- captions (the user's pick at the start)
def _captions():
    """The caption builder (captions.py, next to this file), loaded only when a caption command needs it."""
    here = str(Path(__file__).resolve().parent)
    if here not in sys.path:
        sys.path.insert(0, here)
    import captions
    return captions


def captions_plan_path(rd, video):
    return rd / '70-edit' / f'video-{int(video):02d}' / 'captions.json'


def cmd_captions_choice(args):
    """The user's captions choice for this run, asked once at the start and kept in state.json: captions on with a
    style (luckiest-guy: Luckiest Guy word box; montserrat-highlight: Montserrat Bold, the spoken word yellow), or off.
    A typo is refused, and a choice already made changes only with --change and the user's reason."""
    rd, st = run_folder(args)
    cap = _captions()
    want = (args.captions, args.style or None)
    if want[0] == 'on' and want[1] not in cap.CAPTION_STYLES:
        error('With captions on, --style is one of: ' + ', '.join(cap.CAPTION_STYLES))
    if want[0] == 'off' and want[1]:
        error('Captions off take no style.')
    have = cap.caption_choice(st)
    if have[0] and have != want:
        if n_words(args.change) < 3:
            error('This run already has its captions choice; it changes only on the user\'s say (--change "why").',
                  {'captions': have[0], 'caption_style': have[1]})
        st.setdefault('captions_history', []).append({'captions': have[0], 'caption_style': have[1], 'until': now(),
                                                      'changed_because': args.change})
    st['captions'], st['caption_style'] = want
    st['captions_chosen_at'] = st.get('captions_chosen_at') if have == want else now()
    write_json(rd / 'state.json', st)
    emit({'ok': True, 'captions': want[0], 'caption_style': want[1],
          'look': cap.LOOKS[want[1]]['label'] if want[1] else 'no captions'})


def captions_plan_facts(rd, video, plan=None):
    """Whether the caption plan still describes this video: the run's choice, the script, the measured narration and
    the edit plan's holds it was made from."""
    n = int(video)
    cap = _captions()
    st = read_json(rd / 'state.json')
    choice = cap.caption_choice(st)
    plan = plan if plan is not None else read_json(captions_plan_path(rd, n))
    issues = []
    if not choice[0]:
        issues.append('captions_not_chosen: ask the user once (captions-choice)')
        return issues, choice
    if not plan:
        issues.append('captions_plan_missing: run captions-plan')
        return issues, choice
    if (plan.get('captions'), plan.get('style')) != choice:
        issues.append(f'captions_plan_is_for_another_choice:{plan.get("captions")}/{plan.get("style")}')
    if choice[0] == 'on':
        lines = read_json(video_dir(rd, n) / 'script.json').get('lines') or []
        ep = read_json(artifact_path(rd, n, 'edit'))
        if (plan.get('made_from') or {}).get('script_sha256') != script_hash(lines):
            issues.append('captions_plan_made_from_an_earlier_script')
        if (plan.get('made_from') or {}).get('narration_for_edit_sha256') != (ep.get('narration_for_edit') or {}).get('sha256'):
            issues.append('captions_plan_made_for_an_earlier_edit_narration')
    return issues, choice


def cmd_captions_plan(args):
    """The captions' words and times for this video, from the run's choice: the script's canonical words (tags removed;
    the pronunciation list never reaches a caption), each timed by Whisper medium on the recorded narration
    (line-times.json `word_times`, from narration-measure), moved onto the edit's timeline by every hold retime-shots
    inserted (edit-plan.json). Writes 70-edit/video-NN/captions.json. The word box needs its colour, chosen for this
    video's pictures, with the reason (--box-color, --box-color-why)."""
    rd, st = run_folder(args)
    n = int(args.video)
    cap = _captions()
    choice = cap.caption_choice(st)
    if not choice[0]:
        error('The user has not chosen the captions for this run: ask once (captions on or off and, when on, the style) '
              'and record it with captions-choice.')
    out = {'video': n, 'captions': choice[0], 'style': choice[1], 'made_at': now()}
    if choice[0] == 'off':
        write_json(captions_plan_path(rd, n), out)
        emit({'ok': True, 'captions': 'off', 'plan': str(captions_plan_path(rd, n)),
              'next': 'No caption is built; timeline-check confirms the project has no caption track.'})
        return
    vd = video_dir(rd, n)
    lock = read_json(vd / 'length-lock.json')
    lines = read_json(vd / 'script.json', required=True).get('lines') or []
    language = lock.get('language') or 'en'
    folder = rd / '50-audio' / f'video-{n:02d}'
    lt = read_json(folder / 'line-times.json', required=True)
    if not lt.get('complete') or lt.get('script_sha256') != script_hash(lines):
        error('line-times.json does not describe the whole current script: run narration-measure on the finished '
              'narration first.')
    rows = {r['index']: r for r in lt.get('lines') or []}
    if any('word_times' not in r for r in rows.values()):
        error('line-times.json has no word times (it was measured before captions needed them): run narration-measure '
              'again (free, local).')
    ep = read_json(artifact_path(rd, n, 'edit'), required=True)
    holds = sorted(ep.get('holds') or [], key=lambda h: float(h['at_audio_s']))
    if choice[1] == 'luckiest-guy':
        if not re.fullmatch(r'#[0-9A-Fa-f]{6}', args.box_color or '') or n_words(args.box_color_why) < MIN_NOTE_WORDS:
            error('The word box needs its colour for this video: --box-color #RRGGBB (a colour of the video\'s own '
                  'palette that stands out from the pictures behind the caption line) and --box-color-why "...".')
        out.update({'box_color': args.box_color.upper(), 'box_color_why': args.box_color_why})
    words, problems, clamped = [], [], 0
    counts = {'whisper': 0, 'shared': 0, 'between': 0}
    for i, line in enumerate(lines, 1):
        r = rows.get(i) or {}
        # the line's spoken span: from its first timed word to where the audio's own silence after it begins, when Whisper
        # missed its last words (2026-11-22: "Pas de Calais", heard as "Pada Kalei", ended the line at "the" and the three
        # words got no room)
        gap0 = (r.get('gap_span_s') or [None])[0]
        end = max(r.get('end_s'), gap0) if gap0 is not None and r.get('end_s') is not None else r.get('end_s')
        ws, prob = cap.line_words(line.get('text') or '', r.get('word_times'), (r.get('start_s'), end),
                                  tokens_of, strip_tags, language, line_token_map)
        if prob:
            problems.append({'line': line.get('id'), 'problem': prob})
            continue
        # the line's first word never lights before the voice starts it: Whisper often stretches it back over the
        # silence before the line, which the audio measures (2026-11-22: "Just" lit 1.4 s early, inside a held breath)
        onset = ((rows.get(i - 1) or {}).get('gap_span_s') or [None, None])[1] if i > 1 else None
        clamped += clamp_line_onset(ws, onset)
        for w in ws:
            counts[w['timing']] += 1
            words.append({'w': w['w'], 's': cap.edit_time(w['s'], holds), 'e': cap.edit_time(w['e'], holds),
                          'line': line.get('id'), 'timing': w['timing']})
    if problems:
        error('Some lines cannot be captioned from the measured narration.', problems[:10])
    for a, b in zip(words, words[1:]):
        if b['s'] < a['s']:
            b['s'] = a['s']
        if b['e'] < b['s']:
            b['e'] = b['s']
    total = len(words) or 1
    out.update({'language': language, 'fps': int(args.fps), 'words': words,
                'timing_evidence': {**counts, 'words': len(words), 'whisper_share': round(counts['whisper'] / total, 3)},
                'holds_applied': len(holds),
                'made_from': {'line_times_measured_at': lt.get('measured_at'), 'script_sha256': script_hash(lines),
                              'narration_for_edit_sha256': (ep.get('narration_for_edit') or {}).get('sha256'),
                              'edit_plan_made_at': ep.get('made_at')}})
    write_json(captions_plan_path(rd, n), out)
    warn = []
    if clamped:
        warn.append(f'{clamped} lines began before the voice by Whisper\'s times: their first word now lights when the '
                    'audio says the voice starts')
    if counts['between']:
        warn.append(f'{counts["between"]} words had no time of their own from Whisper: each sits between its timed '
                    'neighbours by its length')
    for run in squeezed_runs(words):
        warn.append(f'{run["line"]}: {run["words"]} words in a row lit under {SQUEEZE_S:g} s each '
                    f'({run["from_s"]:.2f}-{run["to_s"]:.2f} s, "{run["text"]}"): too fast to read and not where the '
                    'voice says them; look at the word_times of that line in line-times.json before building')
    emit({'ok': True, 'captions': 'on', 'style': choice[1], 'plan': str(captions_plan_path(rd, n)),
          'words': len(words), 'timing_evidence': out['timing_evidence'], 'warnings': warn,
          'next': 'With CapCut closed: captions-build --draft "<project folder>" (then capcut_tools.py capcut-repair '
                  '--keep-text), then timeline-check reads them back.'})


def clamp_line_onset(ws, onset, tolerance=0.02):
    """A line's first word starts no earlier than the voice: `onset` is where the measured silence before the line
    ends (the previous line's gap_span_s[1], on the narration's clock). Returns 1 when it moved the word, else 0."""
    if not ws or onset is None or ws[0].get('s') is None or ws[0]['s'] >= onset - tolerance:
        return 0
    ws[0]['s'] = round(float(onset), 3)
    if ws[0].get('e') is None or ws[0]['e'] <= ws[0]['s']:
        nxt = ws[1]['s'] if len(ws) > 1 and ws[1].get('s') is not None and ws[1]['s'] > ws[0]['s'] else None
        ws[0]['e'] = round(nxt if nxt is not None else ws[0]['s'] + 0.2, 3)
    return 1


SQUEEZE_S = 0.08


def squeezed_runs(words, min_s=None, min_run=3):
    """Runs of words of one line, each lit shorter than min_s, at least min_run in a row: captions that flash by
    unread, because those words had no time of their own (2026-11-22: L013, ten words in its last 0.4 s). Facts for the
    agent; nothing is decided here."""
    min_s = SQUEEZE_S if min_s is None else min_s
    runs, cur = [], []
    def close():
        if len(cur) >= min_run:
            runs.append({'line': cur[0]['line'], 'words': len(cur), 'from_s': round(cur[0]['s'], 3),
                         'to_s': round(cur[-1]['e'], 3), 'text': ' '.join(str(w['w']) for w in cur)[:80]})
    for w in words:
        short = (w['e'] - w['s']) < min_s - 1e-9
        if short and cur and cur[-1]['line'] == w['line']:
            cur.append(w)
            continue
        close()
        cur = [w] if short else []
    close()
    return runs


def cmd_captions_build(args):
    """Write the planned captions into the CapCut project (CapCut closed): the chosen look's tracks, each text at its
    planned time, then read back from the project and checked against the plan. Then capcut-repair --keep-text."""
    rd, st = run_folder(args)
    n = int(args.video)
    cap = _captions()
    plan = read_json(captions_plan_path(rd, n))
    issues, choice = captions_plan_facts(rd, n, plan)
    if issues:
        error('The captions plan is not ready.', issues)
    try:
        rec = cap.build_draft(args.draft, plan, rd / '70-edit' / f'video-{n:02d}' / 'captions-build', replace=args.replace)
    except RuntimeError as exc:
        error(str(exc))
    rec.update({'draft': str(Path(args.draft)), 'built_at': now()})
    write_json(rd / '70-edit' / f'video-{n:02d}' / 'captions-built.json', rec)
    emit({**rec, 'next': 'capcut_tools.py capcut-repair --draft "<project folder>" --keep-text; name the project in '
                         'timeline.json (capcut_draft): timeline-check reads the captions back from it.'},
         0 if rec.get('ok') else 2)


def cmd_captions_check(args):
    rd, st = run_folder(args)
    n = int(args.video)
    cap = _captions()
    plan = read_json(captions_plan_path(rd, n))
    issues, choice = captions_plan_facts(rd, n, plan)
    res = {'ok': False, 'issues': issues}
    if not issues:
        res = cap.check_draft(args.draft, plan)
    emit(res, 0 if res.get('ok') else 2)


def cmd_captions_preview(args):
    """A few frames of the planned captions as PNGs (PIL, not CapCut's renderer) to look at the look and the timing:
    which word is lit or boxed at each moment, over one of the video's stills when --background is given."""
    rd, st = run_folder(args)
    n = int(args.video)
    cap = _captions()
    plan = read_json(captions_plan_path(rd, n), required=True)
    if plan.get('captions') != 'on':
        error('Captions are off for this run: there is nothing to preview.')
    w, h = (int(x) for x in args.canvas.lower().split('x'))
    files = cap.preview(plan, Path(args.out), w, h, background=args.background, start_s=args.start, frames=args.frames)
    emit({'ok': True, 'files': files, 'note': 'PIL drawing of the layout, font, colours and timing; the outline thickness '
                                              'is approximate. CapCut draws the real captions.'})


def capcut_audio_segments(draft):
    """Every audio segment of a CapCut project, read from its own timeline document (the newest readable one of
    draft_content.json, template-2.tmp and the Timelines/ copies): the file it plays, where it sits (s), the stretch
    of the file it uses, and its speed (a curve speed is flagged)."""
    d = Path(str(draft)).expanduser()
    docs = [p for p in [d / 'draft_content.json', d / 'template-2.tmp'] if p.is_file()] + \
        sorted(d.glob('Timelines/*/draft_content.json'))
    content, doc = None, None
    for p in sorted(docs, key=lambda x: x.stat().st_mtime, reverse=True):
        try:
            c = json.loads(p.read_text(encoding='utf-8'))
        except (OSError, ValueError):
            continue
        if isinstance(c, dict) and c.get('tracks') is not None:
            content, doc = c, p
            break
    if content is None:
        raise OSError(f'no readable timeline document in {d}')
    mats = {m.get('id'): m for m in (content.get('materials') or {}).get('audios') or []}
    speeds = {m.get('id'): m for m in (content.get('materials') or {}).get('speeds') or []}
    out = []
    for tr in content.get('tracks') or []:
        if tr.get('type') != 'audio':
            continue
        for s in tr.get('segments') or []:
            m = mats.get(s.get('material_id'))
            if not m:
                continue
            tg, src = s.get('target_timerange') or {}, s.get('source_timerange') or {}
            sp = next((speeds[r] for r in s.get('extra_material_refs') or [] if r in speeds), {})
            a, la = int(tg.get('start') or 0) / 1e6, int(tg.get('duration') or 0) / 1e6
            sa, ls = int(src.get('start') or 0) / 1e6, int(src.get('duration') or 0) / 1e6
            speed = s.get('speed') if s.get('speed') is not None else sp.get('speed', 1)
            out.append({'file': m.get('path'), 'start_s': round(a, 3), 'end_s': round(a + la, 3),
                        'source_start_s': round(sa, 3), 'source_end_s': round(sa + ls, 3), 'speed': float(speed or 1),
                        'curve_speed': bool(sp.get('curve_speed')) or bool(sp.get('mode')), 'volume': s.get('volume'),
                        'track': tr.get('name') or tr.get('id'), 'read_from': str(doc)})
    return out


def narration_track_issues(rd, segs, expect):
    """The approved narration in the cut, whole: every narration segment plays the edit plan's file (unchanged since
    retime-shots) at speed 1, each where it belongs, and together they cover the file from 0 to its end exactly once.
    A narration sped up, slowed, trimmed, cut or replaced is refused here, even when the export still has the right
    length."""
    if not expect:
        return []                    # no edit plan yet: edit_plan_missing_run_retime_shots says so
    out = []
    f = _run_file(rd, expect['file'])
    if not f.is_file():
        out.append('narration_file_missing')
    elif file_sha256(f) != expect.get('sha256'):
        out.append('narration_file_changed_since_retime_shots')
    if not segs:
        return out + ['narration_track_missing']
    want, dur = _pkey(f), float(expect.get('duration_s') or 0)
    rows = []
    for j, s in enumerate(segs, 1):
        if not s.get('file') or _pkey(_run_file(rd, s['file'])) != want:
            out.append(f'narration_track_{j}_plays_another_file')
            continue
        try:
            a, b = float(s['start_s']), float(s['end_s'])
            sa = float(s.get('source_start_s') or 0)
            sb = float(s['source_end_s']) if s.get('source_end_s') is not None else None
        except (KeyError, TypeError, ValueError):
            out.append(f'narration_track_{j}_needs_start_end_and_source_times')
            continue
        if sb is None:
            out.append(f'narration_track_{j}_source_range_not_recorded')
            sb = sa + (b - a)
        sp = s.get('speed')
        if sp is None:
            out.append(f'narration_track_{j}_speed_not_recorded')
        elif abs(float(sp) - 1.0) > 1e-3 or s.get('curve_speed'):
            out.append(f'narration_track_{j}_speed_{float(sp):g}_not_1')
        if abs((b - a) - (sb - sa)) > 0.05:
            out.append(f'narration_track_{j}_length_differs_from_its_source')
        if abs(a - sa) > 0.05:
            out.append(f'narration_track_{j}_moved_off_its_time')
        rows.append((sa, sb))
    rows.sort()
    if rows:
        cur = 0.0
        for sa, sb in rows:
            if sa - cur > 0.05:
                out.append(f'narration_cut_{round(sa - cur, 1)}s_missing_at_{_mmss(cur)}')
            elif cur - sa > 0.05:
                out.append(f'narration_plays_twice_near_{_mmss(sa)}')
            cur = max(cur, sb)
        if dur and dur - cur > 0.1:
            out.append(f'narration_trimmed_{round(dur - cur, 1)}s_missing_at_the_end')
    return out


def capcut_project_timeline(rd, video, draft, sounds=None):
    """timeline.json written from a saved CapCut project, never from the plan (manual 05): every picture clip on the main
    video track traced to its shot by its start (within one frame: CapCut snaps clips to its frame grid when it saves)
    and its file (a callback shows its source's still),
    every overlay on another video track, every audio clip as the narration, a music bed (its beats from
    music-provenance.json) or a sound named in `sounds` ({file name: {"kind", "beats", "purpose"}}; a file placed more
    than once also lists its "placements", each {"start_s", "end_s", "kind", "beats", "purpose"}, and a clip is the one
    that starts where it does, within one frame). What cannot be traced is listed in `problems`, never guessed."""
    n = int(video)
    d = Path(str(draft)).expanduser()
    content = json.loads((d / 'draft_content.json').read_text(encoding='utf-8'))
    plan = read_json(rd / '70-edit' / f'video-{n:02d}' / 'edit-plan.json')
    sp = {str(s.get('id')): s for s in read_json(artifact_path(rd, n, 'shot-plan')).get('shots') or []}
    music = read_json(artifact_path(rd, n, 'music')).get('tracks') or {}
    sounds = {str(k).lower(): v for k, v in (sounds or {}).items()}
    mats = {}
    for items in (content.get('materials') or {}).values():
        if isinstance(items, list):
            for m in items:
                if isinstance(m, dict) and m.get('id'):
                    mats[m['id']] = m

    def info(seg):
        m = mats.get(seg.get('material_id')) or {}
        tg, src = seg.get('target_timerange') or {}, seg.get('source_timerange') or {}
        a, la = int(tg.get('start') or 0) / 1e6, int(tg.get('duration') or 0) / 1e6
        b, lb = int(src.get('start') or 0) / 1e6, int(src.get('duration') or 0) / 1e6
        return {'start_s': round(a, 3), 'end_s': round(a + la, 3), 'file': str(m.get('path') or '').replace(chr(92), '/'),
                'source_start_s': round(b, 3), 'source_end_s': round(b + lb, 3), 'speed': seg.get('speed', 1),
                'volume': seg.get('volume', 1)}

    def by_start(t):
        return sorted(t.get('segments') or [], key=lambda x: (x.get('target_timerange') or {}).get('start', 0))
    vtracks = [t for t in content.get('tracks') or [] if t.get('type') == 'video']
    frame_tol = 1.05 / max(1.0, float(content.get('fps') or 30))
    problems, visual, overlays, audio = [], [], [], []
    shots = plan.get('shots') or []
    stills_dir = artifact_path(rd, n, 'shot-plan').parent / 'stills'
    if vtracks:
        for seg in by_start(vtracks[0]):
            c = info(seg)
            # CapCut snaps a clip to its frame grid when it saves the project (measured: up to 0.03 s at 30 fps), so a
            # clip is its shot's when it starts within one frame of the planned start
            shot = next((x for x in shots if abs(float(x.get('start_s') or 0) - c['start_s']) <= frame_tol), None)
            if not shot:
                problems.append(f'picture clip at {c["start_s"]} s matches no shot of the edit plan')
                continue
            sid = str(shot.get('id'))
            want = stills_dir / f'{(sp.get(sid) or {}).get("reuses") or sid}.png'
            if _pkey(c['file']) != _pkey(want):
                problems.append(f'{sid}: the clip shows {c["file"]}, its still is {want.as_posix()}')
            visual.append({'start_s': c['start_s'], 'end_s': c['end_s'], 'shot_id': sid, 'asset_path': c['file'],
                           'beat_id': shot.get('beat_id'), 'purpose': (sp.get(sid) or {}).get('new_thing') or ''})
        seen = {v['shot_id'] for v in visual}
        problems += [f'{x.get("id")}: no picture clip in the project' for x in shots if str(x.get('id')) not in seen]
        for t in vtracks[1:]:
            for seg in by_start(t):
                c = info(seg)
                overlays.append({'track': t.get('name'), 'start_s': c['start_s'], 'end_s': c['end_s'], 'file': c['file']})
    narr = _pkey(_run_file(rd, (plan.get('narration_for_edit') or {}).get('file') or ''))
    for t in content.get('tracks') or []:
        if t.get('type') != 'audio':
            continue
        for seg in by_start(t):
            c = info(seg)
            k = _pkey(c['file'])
            if k == narr:
                audio.append({'kind': 'narration', 'file': c['file'], 'start_s': c['start_s'], 'end_s': c['end_s'],
                              'source_start_s': c['source_start_s'], 'source_end_s': c['source_end_s'], 'speed': c['speed'],
                              'volume': c['volume']})
            elif k in music:
                audio.append({'kind': 'music', 'file': c['file'], 'start_s': c['start_s'], 'end_s': c['end_s'],
                              'beats': list((music[k] or {}).get('beats') or []), 'volume': c['volume'], 'track': t.get('name'),
                              'source_start_s': c['source_start_s']})     # where in its file it starts (sound-review)
            elif Path(c['file']).name.lower() in sounds:
                x = sounds[Path(c['file']).name.lower()]
                places = x.get('placements') if isinstance(x.get('placements'), list) else None
                if places:
                    hit = [p for p in places if isinstance(p, dict)
                           and abs(float(p.get('start_s') or 0) - c['start_s']) <= frame_tol]
                    if len(hit) != 1:
                        problems.append(f'audio clip {c["file"]} at {c["start_s"]} s matches '
                                        f'{"none" if not hit else "more than one"} of the placements of its sound')
                        continue
                    x = dict(x, **hit[0])
                audio.append({'kind': str(x.get('kind') or 'sfx'), 'file': c['file'], 'start_s': c['start_s'],
                              'end_s': c['end_s'], 'beats': list(x.get('beats') or []), 'purpose': x.get('purpose', ''),
                              'volume': c['volume'], 'track': t.get('name'), 'source_start_s': c['source_start_s']})
            else:
                problems.append(f'audio clip {c["file"]} at {c["start_s"]} s is not the narration, a recorded music bed '
                                f'or a named sound')
    cc = content.get('canvas_config') or {}
    return {'canvas': f'{cc.get("width")}x{cc.get("height")}', 'fps': content.get('fps', 30),
            'project_file': str(d / 'draft_content.json'), 'capcut_draft': str(d), 'visual_segments': visual,
            'overlays': overlays, 'audio_tracks': audio, 'problems': problems,
            'note': 'Derived from the saved CapCut project (timeline-write). A CapCut project is not an exported file.'}


def timeline_check_path(rd, video):
    return rd / '70-edit' / f'video-{int(video):02d}' / 'timeline-check.json'


def export_provenance_path(rd, video):
    return rd / '80-deliverables' / f'video-{int(video):02d}' / 'export-provenance.json'


def release_path(rd, video):
    """The release record: the one file release-check passed (release-check --record), by its full sha256."""
    return rd / '80-deliverables' / f'video-{int(video):02d}' / 'release.json'


def human_review_path(rd, video):
    """What a person did with an export, in their own words: listened, watched, or said they will not (human-review)."""
    return rd / '80-deliverables' / f'video-{int(video):02d}' / 'human-review.json'


def planned_blanks_path(rd, video):
    return rd / '70-edit' / f'video-{int(video):02d}' / 'planned-blanks.json'


def project_snapshot(rd, video, draft):
    """What a saved CapCut project shows and plays, read from the project itself (capcut_project_timeline, plus its
    texts): every picture clip with its shot and file, every overlay, every sound with its speed and volume, every text
    with a fingerprint of its words, the canvas and frame rate, and a fingerprint of each media file. What an export of
    it must carry. Compared with project_changes, never byte for byte: CapCut's own re-save moves a clip by a frame."""
    tl = capcut_project_timeline(rd, video, draft)
    content = json.loads((Path(str(draft)).expanduser() / 'draft_content.json').read_text(encoding='utf-8'))
    mats = {}
    for items in (content.get('materials') or {}).values():
        if isinstance(items, list):
            for m in items:
                if isinstance(m, dict) and m.get('id'):
                    mats[m['id']] = m
    texts = []
    for t in content.get('tracks') or []:
        if t.get('type') != 'text':
            continue
        for seg in t.get('segments') or []:
            tg = seg.get('target_timerange') or {}
            a = int(tg.get('start') or 0) / 1e6
            words = str((mats.get(seg.get('material_id')) or {}).get('content') or '')
            texts.append([round(a, 3), round(a + int(tg.get('duration') or 0) / 1e6, 3),
                          hashlib.sha256(words.encode('utf-8')).hexdigest()[:16]])
    texts.sort()
    visual = [[str(v['shot_id']), _pkey(v['asset_path']), v['start_s'], v['end_s']] for v in tl['visual_segments']]
    overlays = [[str(o.get('track') or ''), _pkey(o['file']), o['start_s'], o['end_s']] for o in tl['overlays']]
    # every sound clip in the project, named or not (a sound effect the timeline does not name still counts)
    known = {(_pkey(x['file']), round(float(x['start_s']), 2)): str(x['kind']) for x in tl['audio_tracks']}
    audio = []
    for t in content.get('tracks') or []:
        if t.get('type') != 'audio':
            continue
        for seg in t.get('segments') or []:
            m = mats.get(seg.get('material_id')) or {}
            tg = seg.get('target_timerange') or {}
            a0 = round(int(tg.get('start') or 0) / 1e6, 3)
            f = _pkey(str(m.get('path') or '').replace(chr(92), '/'))
            audio.append([known.get((f, round(a0, 2)), 'sound'), f, a0, round(a0 + int(tg.get('duration') or 0) / 1e6, 3),
                          float(seg.get('speed') or 1), float(1 if seg.get('volume') is None else seg['volume'])])
    audio.sort(key=lambda r: (r[2], r[1]))
    files = sorted({r[1] for r in visual} | {r[1] for r in overlays} | {r[1] for r in audio})
    media = {f: (quick_fingerprint(Path(f)) if Path(f).is_file() else None) for f in files}
    ends = [r[3] for r in visual + overlays + audio] + [r[1] for r in texts]
    return {'draft': str(draft), 'canvas': tl['canvas'], 'fps': tl['fps'], 'end_s': round(max(ends or [0.0]), 3),
            'visual': visual, 'overlays': overlays, 'audio': audio, 'texts': texts, 'media': media,
            'problems': tl['problems']}


def project_changes(a, b, tol=0.05):
    """What differs between two snapshots of a project (project_snapshot) beyond CapCut's frame snapping (tol seconds):
    a clip added, removed, moved, swapped or re-timed, a speed or volume, a text's words, the canvas, a media file."""
    out = []
    if str(a.get('canvas')) != str(b.get('canvas')):
        out.append(f'canvas {a.get("canvas")} -> {b.get("canvas")}')
    try:            # CapCut writes 30.0 where the build wrote 30 when it re-saves a project it opened (seen 2026-11-24)
        fps_same = abs(float(a.get('fps')) - float(b.get('fps'))) < 0.01
    except (TypeError, ValueError):
        fps_same = str(a.get('fps')) == str(b.get('fps'))
    if not fps_same:
        out.append(f'fps {a.get("fps")} -> {b.get("fps")}')
    for key, label in (('visual', 'picture clips'), ('overlays', 'overlays'), ('audio', 'sound clips'), ('texts', 'texts')):
        x, y = a.get(key) or [], b.get(key) or []
        if len(x) != len(y):
            out.append(f'{label}: {len(x)} -> {len(y)}')
            continue
        for i, (p, q) in enumerate(zip(x, y), 1):
            for u, v in zip(p, q):
                num = isinstance(u, (int, float)) and isinstance(v, (int, float)) and not isinstance(u, bool)
                if (abs(float(u) - float(v)) > tol) if num else (u != v):
                    out.append(f'{label} {i}: {u} -> {v}')
                    break
    ma, mb = a.get('media') or {}, b.get('media') or {}
    out += [f'media changed: {Path(f).name}' for f in sorted(set(ma) | set(mb)) if ma.get(f) != mb.get(f)]
    return out


def _blank_spans(rows, kind, end_s):
    """[(from_s, to_s)] from ffmpeg's blackdetect or silencedetect lines; a silence still open at the end runs to it."""
    out, start = [], None
    for r in rows or []:
        if kind == 'black':
            m = re.search(r'black_start:\s*([\d.]+)\s+black_end:\s*([\d.]+)', r)
            if m:
                out.append((float(m.group(1)), float(m.group(2))))
            continue
        m = re.search(r'silence_start:\s*(-?[\d.]+)', r)
        if m:
            start = max(0.0, float(m.group(1)))
            continue
        m = re.search(r'silence_end:\s*([\d.]+)', r)
        if m and start is not None:
            out.append((start, float(m.group(1))))
            start = None
    if start is not None:
        out.append((start, float(end_s)))
    return out


def cmd_timeline_write(args):
    rd, st = run_folder(args)
    sounds = read_json(Path(args.sounds)) if args.sounds else {}
    try:
        tl = capcut_project_timeline(rd, args.video, args.draft, sounds)
    except (OSError, ValueError) as exc:
        emit({'ok': False, 'error': f'project unreadable: {exc}'}, 2)
    extra = read_json(Path(args.extra)) if args.extra else {}
    tl.update({k: v for k, v in extra.items() if k not in ('visual_segments', 'audio_tracks', 'capcut_draft', 'problems')})
    out = rd / '70-edit' / f'video-{int(args.video):02d}' / 'timeline.json'
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(tl, ensure_ascii=False, indent=1), encoding='utf-8')
    emit({'ok': not tl['problems'], 'file': str(out), 'visual_segments': len(tl['visual_segments']),
          'overlays': len(tl['overlays']), 'audio_tracks': len(tl['audio_tracks']), 'problems': tl['problems'],
          'next': 'timeline-check --run RUN --video N'}, 0 if not tl['problems'] else 2)


def bed_levels(narration, tracks):
    """The clip volume that puts each bed (or sound) a chosen number of dB under the voice, from measurements: the
    integrated loudness (EBU R128, the same meter as loudness_stats) of the narration and of each file, never a slider
    guessed by ear. tracks: [{"id", "file", "under_speech_db"}]. A volume above 1 would need gain CapCut cannot add here:
    it is capped at 1 and reported."""
    speech = loudness_stats(narration).get('integrated_lufs')
    if speech is None:
        raise ValueError(f'no loudness for the narration {narration}')
    out = []
    for t in tracks:
        lv = loudness_stats(t['file']).get('integrated_lufs')
        if lv is None:
            out.append({'id': t.get('id'), 'file': t['file'], 'error': 'no loudness measured'})
            continue
        want = abs(float(t['under_speech_db']))                 # how far UNDER the voice: 18 means 18 dB quieter than speech
        gain = (speech - want) - lv
        vol = 10 ** (gain / 20)
        row = {'id': t.get('id'), 'file': t['file'], 'file_lufs': lv, 'target_under_speech_db': want,
               'gain_db': round(gain, 2), 'volume': round(min(1.0, vol), 3)}
        if vol > 1.0:
            row['note'] = f'needs {gain:+.1f} dB, more than the file holds: it plays at full volume, {gain:+.1f} dB short'
        if t.get('why'):
            row['why'] = t['why']
        out.append(row)
    return {'speech_lufs': speech, 'tracks': out}


def bake_bed(src, out, gain_db, src_start=0.0, dur=None, fade_in=0.0, fade_out=0.0):
    """The bed as it must play, in the file itself: the stretch [src_start, src_start + dur] of `src`, its gain and its
    fades, written to `out` (same codec, rate and channels). A CapCut project then places it at volume 1, from 0, with no
    fades of its own: CapCut's export was measured playing a clip whose volume was set to 0 at full level (2026-11-22,
    video clips; lower volumes on audio clips are not verified), so the level a bed must have lives in its media."""
    info = probe(src)
    codec = {'pcm_f32le': 'pcm_f32le', 'pcm_s24le': 'pcm_s24le'}.get(str(info.get('audio_codec') or ''), 'pcm_s16le')
    length = float(dur) if dur else max(0.0, float(info['duration_s']) - float(src_start))
    af = [f'volume={float(gain_db):.2f}dB']
    if fade_in:
        af.append(f'afade=t=in:st=0:d={float(fade_in):.3f}')
    if fade_out:
        af.append(f'afade=t=out:st={max(0.0, length - float(fade_out)):.3f}:d={float(fade_out):.3f}')
    Path(out).parent.mkdir(parents=True, exist_ok=True)
    cmd = ['ffmpeg', '-hide_banner', '-loglevel', 'error', '-y', '-ss', f'{float(src_start):.3f}', '-t', f'{length:.3f}',
           '-i', str(src), '-af', ','.join(af), '-c:a', codec, str(out)]
    cp = subprocess.run(cmd, capture_output=True, text=True, encoding='utf-8', errors='replace')
    if cp.returncode != 0:
        raise ValueError(f'ffmpeg could not bake {src}: {cp.stderr[-300:]}')
    return {'file': str(out), 'src_start_s': float(src_start), 'dur_s': round(length, 3), 'gain_db': round(float(gain_db), 2),
            'fade_in_s': float(fade_in or 0.0), 'fade_out_s': float(fade_out or 0.0)}


BED_LEVEL_STUDY = ('One listening study on television documentaries (Torcoli and others, 2019; 22 listeners) '
                   'recommends the commentary at least 10 LU over the music and 15 LU over ambience, and found up to 15 '
                   'LU over music (20 over ambience) still pleasing. Context for a choice, never a rule: a room tone, '
                   'a pulse under a list and a theme that is meant to be heard want different levels.')


def lift_problem(track):
    """Why a track's lift cannot be baked as written (None when it can). A lift raises the bed where it is meant to be
    heard: {"by_db", "why", and "where_voice_is_silent_s" (every pause of the voice this long) and/or "moments"
    ([[from_s, to_s]] on the film's clock), optional "ramp_s"}, on a track that says where it starts in the film
    ("at")."""
    lf = track.get('lift')
    if not isinstance(lf, dict):
        return 'lift is an object: {"by_db", "why", "where_voice_is_silent_s" and/or "moments", "ramp_s"}'
    try:
        if float(lf.get('by_db') or 0) <= 0:
            return 'lift.by_db says how many dB the bed rises (above 0)'
        if track.get('at') is None or float(track['at']) < 0:
            return 'a lifted track says where its baked copy starts on the film\'s clock ("at", in seconds)'
        if lf.get('where_voice_is_silent_s') is not None and float(lf['where_voice_is_silent_s']) <= 0:
            return 'lift.where_voice_is_silent_s is a length in seconds (above 0)'
        moments = lf.get('moments') or []
        if any(float(m[1]) <= float(m[0]) for m in moments):
            return 'each of lift.moments is [from_s, to_s] on the film\'s clock'
    except (TypeError, ValueError, IndexError, KeyError):
        return 'lift.by_db, at, where_voice_is_silent_s and moments are numbers (moments: [[from_s, to_s]])'
    if lf.get('where_voice_is_silent_s') is None and not moments:
        return 'lift says where the bed rises: where_voice_is_silent_s (every pause this long) and/or moments'
    if n_words(lf.get('why')) < MIN_NOTE_WORDS:
        return 'lift.why says what the rise is for (a few words at least)'
    return None


def bed_level_context(rd, video):
    """What a bed's level is chosen against: the film's models as measured (the sound between their words, which is
    not the same yardstick as a loudness difference) and the one published study on the matter. Context, never a
    rule."""
    out = {'published': BED_LEVEL_STUDY}
    if rd and video:
        refs, _ = model_refs(rd, int(video))
        rows = {}
        for v in refs:
            m = model_measures(read_json(ref_av_path(rd, v)).get('summary') or {})
            if m.get('sound_under_voice_db') is not None:
                rows[v] = {'db_under_the_voice': round(m['sound_under_voice_db']),
                           'moves_db': round(m['sound_moves_db']) if m.get('sound_moves_db') is not None else None}
        if rows:
            out['models'] = {'between_their_words': rows,
                             'how_read': 'the level between the words of each finished film against its voice (room '
                                         'tone and effects included), and how far it moves from its quiet tenth to '
                                         'its loud tenth: sound-review reads this film\'s mix the same way'}
    return out


def cmd_bed_levels(args):
    plan = read_json(Path(args.plan), required=True)
    try:
        res = bed_levels(plan['narration'], plan['tracks'])
    except (KeyError, TypeError, ValueError) as exc:
        emit({'ok': False, 'error': str(exc)}, 2)
    lifted = [t for t in plan['tracks'] if isinstance(t, dict) and t.get('lift') not in (None, {}, False)]
    for t in lifted:
        prob = lift_problem(t)
        if prob:
            emit({'ok': False, 'error': f'track {t.get("id") or t.get("file")}: {prob}'}, 2)
    if lifted and not args.bake:
        emit({'ok': False, 'error': 'a lift lives in the baked file (CapCut ignores a clip\'s volume): run with --bake'}, 2)
    voice = None
    if args.bake:
        # each track baked: its stretch, its gain and its fades in the file; a recorded bed's copy carries the bed's record
        rd = Path(args.run).expanduser().resolve() if args.run else None
        prov = read_json(artifact_path(rd, args.video, 'music')).get('tracks') or {} if rd and args.video else {}
        derived = []
        for t, row in zip(plan['tracks'], res['tracks']):
            if 'error' in row:
                continue
            src = Path(t['file'])
            tag = f'{row["gain_db"]:+.1f}dB'.replace('+', 'p').replace('-', 'm')
            # An excerpt carries its stretch in its name: two stretches of one bed at one level stay two files (a later
            # one would overwrite the first, and CapCut and timeline-write tell sounds apart by their file names).
            span = ''
            if t.get('src_start') or t.get('dur'):
                span = f'.from{float(t.get("src_start") or 0.0):g}s' + (f'-{float(t["dur"]):g}s' if t.get('dur') else '')
            # the copy is written as PCM: a source in another container (an .mp3 sound effect) is baked to .wav
            suffix = src.suffix if src.suffix.lower() == '.wav' else '.wav'
            lf = t.get('lift') if t in lifted else None
            # a lifted copy is another file than the same stretch left even
            ltag = f'.lift{float(lf["by_db"]):g}dB' if lf else ''
            out = Path(args.bake) / f'{src.stem}.bed-{tag}{ltag}{span}{suffix}'
            try:
                b = bake_bed(src, out, row['gain_db'], t.get('src_start') or 0.0, t.get('dur'), t.get('fade_in') or 0.0,
                             t.get('fade_out') or 0.0)
            except (OSError, ValueError, KeyError) as exc:
                row['error'] = f'bake: {exc}'
                continue
            row.update({'baked': b, 'volume_in_project': 1.0})
            if lf:
                # The bed rises where it is meant to be heard: in the voice's pauses of the length asked for, inside
                # the stretch this copy plays over, and at the moments named. In the file, as its level is.
                try:
                    ar = _audio_review()
                    voice = voice or ar.voice_profile(plan['narration'])
                    at = float(t['at'])
                    wins = (ar.voice_silences(voice, float(lf['where_voice_is_silent_s']), at, at + b['dur_s'])
                            if lf.get('where_voice_is_silent_s') is not None else [])
                    wins += [(float(m[0]), float(m[1])) for m in lf.get('moments') or []]
                    row['lift'] = {**ar.bake_lift(out, at, wins, float(lf['by_db']),
                                                  float(lf.get('ramp_s') or ar.LIFT_RAMP_S)),
                                   'by_db': float(lf['by_db']), 'at_s': at, 'why': str(lf['why']).strip(),
                                   'under_speech_db_at_its_peak': round(row['target_under_speech_db'] - float(lf['by_db']), 1)}
                    # how much room the voice left: a rise and its way back need a silence of twice the ramp and
                    # the guards (on the real film of 2026-11-26, 64 s of opening music held two pauses of half a
                    # second, and a lift had nothing to rise in)
                    tops = [w[2] for w in row['lift']['windows']]
                    by = float(lf['by_db'])
                    room = ('More room is a planned silence the music carries, music that enters before the words or '
                            'plays on after the last, or a moment named in "moments".')
                    row['lift']['full_rises'] = sum(1 for x in tops if x >= by - 0.05)
                    if not tops:
                        row['lift']['note'] = ('nothing was lifted: no pause of that length, and no moment, inside this '
                                               'stretch. ' + room)
                    elif not row['lift']['full_rises']:
                        need = 2 * (row['lift']['ramp_s'] + ar.LIFT_GUARD_S)
                        row['lift']['note'] = (f'no silence in this stretch is long enough for the whole rise ({by:g} dB '
                                               f'up and back takes {need:g} s with no voice): the bed comes up by '
                                               f'{max(tops):g} dB at most. ' + room)
                except (OSError, ValueError, KeyError, TypeError, ImportError, RuntimeError) as exc:
                    row['error'] = f'lift: {exc}'
                    continue
            rec = prov.get(_pkey(src))
            if rec:
                derived.append({**{k: v for k, v in rec.items() if k != 'made_at'}, 'out': str(out), 'derived_from': str(src),
                                'derivation': {**{k: b[k] for k in ('src_start_s', 'dur_s', 'gain_db', 'fade_in_s', 'fade_out_s')},
                                               **({'lift': {k: row['lift'][k] for k in ('by_db', 'at_s', 'windows', 'ramp_s')}}
                                                  if lf else {})}})
        if derived:
            res['recorded_in'] = record_media(rd, args.video, 'music', derived)
    res['context'] = bed_level_context(Path(args.run).expanduser().resolve() if args.run else None, args.video)
    if args.out:
        Path(args.out).write_text(json.dumps(res, ensure_ascii=False, indent=1), encoding='utf-8')
    emit({'ok': all('error' not in t for t in res['tracks']), **res})


def cmd_timeline_check(args):
    rd, st = run_folder(args)
    res = timeline_facts(rd, args.video)
    draft = read_json(rd / '70-edit' / f'video-{int(args.video):02d}' / 'timeline.json').get('capcut_draft')
    if res['ready'] and draft:
        # What was checked, as the saved project shows it: an export is held to this project (export-check), and a
        # project changed afterwards is a project not checked.
        try:
            snap = project_snapshot(rd, args.video, draft)
            p = timeline_check_path(rd, args.video)
            old = read_json(p)
            sha = canonical_sha(snap)
            hist = (old.get('history') or []) + ([{k: old.get(k) for k in ('checked_at', 'snapshot_sha256')}] if old else [])
            write_json(p, {'video': int(args.video), 'checked_at': now(), 'draft': str(draft), 'snapshot_sha256': sha,
                           'snapshot': snap, 'history': hist[-50:]})
            res['project_snapshot'] = {'file': str(p), 'sha256': sha, 'pictures': len(snap['visual']),
                                       'overlays': len(snap['overlays']), 'sounds': len(snap['audio']),
                                       'texts': len(snap['texts'])}
        except (OSError, ValueError, KeyError, TypeError) as exc:
            res['ready'] = False
            res['issues'].append('capcut_project_unreadable:' + str(exc)[:120])
    emit(res, 0 if res['ready'] else 2)


def _numbers_said(text, language='en'):
    """The figures a stretch of narration says, as digit strings (number words merged: 'twenty-seven' -> '27')."""
    return {t.replace(',', '') for t in tokens_of(str(text or ''), language) if re.fullmatch(r'\d[\d,]*', t)}


DRAW_STALE = ('spec_changed', 'still_changed', 'still_missing', 'mov_changed', 'mov_missing', 'record_for_other_spec',
              'record_for_other_output', 'record_unreadable', 'spec_unreadable')


def drawing_facts(rd, video):
    """(issues, warnings) for the video's rendered drawings (60-visuals/video-NN/drawings/<name>.json + .mov): a render
    no longer of its spec or still is stale (render again); a counter lands on a figure the lines of its shot do not say
    (or says why: counter_note); its words break a content rule like a picture prompt's (content_note answers 02's
    plain words, never what a content review cut); its colours far from the locked palette are noted."""
    n = int(video)
    ddir = rd / '60-visuals' / f'video-{n:02d}' / 'drawings'
    if not ddir.is_dir():
        return [], []
    try:
        dt = _draw_tool()
    except ImportError as exc:
        return [f'drawings_not_checked:{exc}'], []
    iss, warn = [], []
    shots = {str(s.get('id')): s for s in read_json(artifact_path(rd, n, 'shot-plan')).get('shots') or []}
    lines = read_json(video_dir(rd, n) / 'script.json').get('lines') or []
    index = {str(l.get('id') or f'L{i + 1:03d}'): i for i, l in enumerate(lines)}
    language = read_json(video_dir(rd, n) / 'length-lock.json').get('language') or 'en'
    themes = excluded_themes(rd, n)
    palette = [p.lstrip('#') for p in read_json(style_lock_path(rd, n)).get('palette') or []]
    unvouched, counting = [], []
    for sp in sorted(ddir.glob('*.json')):
        spec = read_json(sp)
        if not isinstance(spec, dict) or not spec.get('shot') or not isinstance(spec.get('elements'), list):
            continue
        name, mov = sp.stem, sp.with_suffix('.mov')
        if mov.is_file():
            stt = dt.render_status(sp, mov)
            codes = [r.get('code') for r in stt.get('reasons') or []]
            if [c for c in codes if c in DRAW_STALE]:
                iss.append(f'drawing_{name}_render_is_stale:' + ','.join(c for c in codes if c in DRAW_STALE) + ':render_it_again')
            elif 'no_record' in codes or 'still_not_recorded' in codes:
                unvouched.append(name)
        facts = dt.spec_facts(spec)
        s = shots.get(str(spec.get('shot'))) or {}
        a, b = index.get(str(s.get('line_start'))), index.get(str(s.get('line_end')))
        said = _numbers_said(' '.join(str(l.get('text') or '') for l in lines[a:b + 1]), language) \
            if a is not None and b is not None else set()
        for c in facts.get('counters') or []:
            if c.get('from_text') and c.get('from_text') != c.get('to_text'):
                counting.append(f'{sp.stem} "{c["from_text"]}" to "{c["to_text"]}"')
            to = c.get('to')
            try:
                fig = str(int(round(float(to)))) if float(to) == int(float(to)) else str(to)
            except (TypeError, ValueError):
                continue
            if fig not in said and n_words(spec.get('counter_note')) < MIN_NOTE_WORDS:
                iss.append(f'drawing_{name}_counts_to_{fig}_but_shot_{spec.get("shot")}_says:'
                           + (','.join(sorted(said)) or 'no_figure') + ':match_the_narration_or_say_why(counter_note)')
        words = ' '.join(str(t.get('text') or '') for t in facts.get('texts') or [] if t.get('type') != 'counter')
        if words.strip():
            iss += prompt_flag_issues(f'drawing_{name}_words', [k for k in prompt_flags(words, themes)
                                                                 if k != 'minor_in_the_picture'], spec.get('content_note'))
        if palette:
            def far(hexc):
                try:
                    r, g, bl = (int(hexc[i:i + 2], 16) for i in (0, 2, 4))
                except (ValueError, TypeError):
                    return False
                if max(r, g, bl) - min(r, g, bl) < 24:           # greys, black and white sit with any palette
                    return False
                return min(((r - int(p[0:2], 16)) ** 2 + (g - int(p[2:4], 16)) ** 2 + (bl - int(p[4:6], 16)) ** 2) ** 0.5
                           for p in palette) > 90
            off = sorted({str(x).lstrip('#').upper() for x in facts.get('colors') or [] if far(str(x).lstrip('#')[:6])})
            if off:
                warn.append(f'drawing {name} uses colours away from the locked palette: ' + ', '.join('#' + x for x in off[:6]))
    if unvouched:
        warn.append(f'{len(unvouched)} drawing(s) rendered before render records ({", ".join(unvouched[:8])}): their spec '
                    'and still are not vouched for; render again to record them')
    if counting:
        # 2026-11-26: five counters ran from 0 with their words attached, so the screen read "1 shield = about 0 coins"
        warn.append('counters that first show another figure than the one they land on: ' + '; '.join(counting[:10])
                    + ('' if len(counting) <= 10 else f' and {len(counting) - 10} more') + ': while it counts, the '
                    'screen says the first. True of something (a tally that grows before the viewer), or a statement '
                    'the film does not make? A figure can appear whole (no "in"), or count from where it really starts')
    return iss, warn


READABLE_TEXT = 0.024            # of the frame height: smaller drawn words are hard to read on a phone (04)
CAPTION_BAND = (0.78, 0.95)      # where the captions sit on a 16:9 frame (captions.py LOOKS: y_rel 0.85)


def _draw_tool():
    """The drawing renderer (draw_tool.py, next to this file), loaded only when a drawing's words are read."""
    here = str(Path(__file__).resolve().parent)
    if here not in sys.path:
        sys.path.insert(0, here)
    import draw_tool
    return draw_tool


def _drawn_words(d):
    """Every word a drawing spec shows (text, counters, stamps, card lines), with its size, its middle's height in the
    frame (at the clip's start and end when the drawing follows a moving still) and its time on screen."""
    try:
        return _draw_tool().readable_texts(d)
    except Exception:                       # the renderer cannot be loaded: plain text elements, positions as written
        dur = float(d.get('dur_s') or 0)
        out = []
        for e in d.get('elements') or []:
            if e.get('type') != 'text':
                continue
            end = (e.get('out') or {}).get('start_s')
            out.append({'text': str(e.get('text') or ''), 'size': float(e.get('size') or 0),
                        'y': [float((e.get('at') or [0, 0])[1])], 'start_s': float((e.get('in') or {}).get('start_s') or 0),
                        'end_s': float(end) if end is not None else dur})
        return out


def drawing_readability(overlays, captions_on=True, min_size=READABLE_TEXT):
    """Words drawn on screen that a viewer is meant to read (labels, numbers, names, stamps, counters, card lines): a
    size a phone shows legibly, clear of the caption band, and on screen long enough to read (about 0.3 s a word, never
    under 1.5 s). Read from each overlay's drawing spec (DNN.json beside DNN.mov) through the renderer's own list of
    its words, so a drawing that follows its still's move is read where the edit shows it. Facts for the agent, never
    a gate: a word can be deliberately small (a texture, not a message)."""
    out = []
    for ov in overlays or []:
        spec = Path(str(ov.get('file') or '')).with_suffix('.json')
        d = read_json(spec) if spec.is_file() else {}
        dur = float(d.get('dur_s') or 0)
        for w in _drawn_words(d):
            text, size = str(w.get('text') or ''), float(w.get('size') or 0)
            ys = [float(v) for v in (w.get('y') or [0.0])]
            if 0 < size < min_size:
                out.append(f'{spec.stem}: "{text}" is drawn {size * 100:.1f}% of the frame high (about '
                           f'{size * 1080:.0f} px at 1080p): small to read on a phone')
            if captions_on and any(CAPTION_BAND[0] <= y + size / 2 <= CAPTION_BAND[1] for y in ys):
                out.append(f'{spec.stem}: "{text}" sits in the caption band: the captions may cover it')
            start, end = float(w.get('start_s') or 0), float(w.get('end_s') if w.get('end_s') is not None else dur)
            need = max(1.5, 0.3 * len(text.split()))
            if dur and end - start < need:
                out.append(f'{spec.stem}: "{text}" is on screen {end - start:.1f} s, short for {len(text.split())} '
                           'word(s)')
    return out


def edit_landmarks(rd, video):
    """Where each narration line sits in the edit (the edit's clock): its first word, its last word, and the silence
    after it (a decided hold's own times, else the gap the audio measured, both moved by every hold before them).
    What sounds are placed against, so a re-recording or a new hold moves them with the story (05)."""
    n = int(video)
    ep = read_json(rd / '70-edit' / f'video-{n:02d}' / 'edit-plan.json')
    holds = sorted((float(h['at_audio_s']), float(h.get('hold_s') or 0)) for h in ep.get('holds') or [])

    def edit_t(t):
        return round(float(t) + sum(a for at, a in holds if at <= float(t) + 1e-6), 3)
    words = read_json(captions_plan_path(rd, n)).get('words') or []
    first, last = {}, {}
    for w in words:
        first.setdefault(str(w['line']), float(w['s']))
        last[str(w['line'])] = float(w['e'])
    lt = read_json(rd / '50-audio' / f'video-{n:02d}' / 'line-times.json')
    held = {str(h.get('after_line')): h.get('times_in_edit') or {} for h in ep.get('holds') or []}
    marks = {}
    for r in lt.get('lines') or []:
        lid = str(r.get('id'))
        m = {}
        if lid in first:
            m.update({'start': first[lid], 'end': last[lid]})
        elif r.get('start_s') is not None:
            m.update({'start': edit_t(r['start_s']), 'end': edit_t(r['end_s'])})
        h = held.get(lid) or {}
        g = r.get('gap_span_s')
        if h.get('silence_from_s') is not None:
            m.update({'silence_start': float(h['silence_from_s']), 'silence_end': float(h['silence_to_s'])})
        elif g:
            m.update({'silence_start': edit_t(g[0]), 'silence_end': edit_t(g[1])})
        marks[lid] = m
    return marks


def anchor_for(t, marks):
    """An edit time as an offset from the latest narration landmark at or before it (a line's start or end, or the
    silence after it): {"line", "at", "offset_s"}."""
    best = None
    for lid, m in marks.items():
        for at, v in m.items():
            # on a tie the later landmark wins: the silence after a line over its last word, the next line's
            # first word over the silence before it (what the sound belongs to)
            if v is not None and v <= float(t) + 1e-6 and (best is None or v >= best[2]):
                best = (lid, at, v)
    if best is None:
        return {'line': None, 'at': 'video_start', 'offset_s': round(float(t), 3)}
    return {'line': best[0], 'at': best[1], 'offset_s': round(float(t) - best[2], 3)}


def edit_words(rd, video):
    """Each line's caption words' start times on the edit's clock, in order: {line id: [start_s, ...]} (word N of a
    line is the Nth caption display word, as in a shot's start_word)."""
    words = read_json(captions_plan_path(rd, int(video))).get('words') or []
    out = {}
    for w in words:
        out.setdefault(str(w['line']), []).append(float(w['s']))
    return out


def resolve_anchor(anchor, marks, words=None):
    """An anchor's time on the current edit: a line landmark (start, end, silence_start, silence_end), a word of a line
    ({"at": "word", "word": N}: a sound that belongs to that word), or the video's start; plus its offset (which may be
    negative: a bed whose music must run out just before a word enters that many seconds earlier)."""
    if not isinstance(anchor, dict):
        return None
    if anchor.get('at') == 'video_start':
        return round(float(anchor.get('offset_s') or 0), 3)
    if anchor.get('at') == 'word':
        ws = (words or {}).get(str(anchor.get('line'))) or []
        try:
            k = int(anchor.get('word'))
        except (TypeError, ValueError):
            return None
        return round(ws[k - 1] + float(anchor.get('offset_s') or 0), 3) if 1 <= k <= len(ws) else None
    v = (marks.get(str(anchor.get('line'))) or {}).get(str(anchor.get('at')))
    return None if v is None else round(v + float(anchor.get('offset_s') or 0), 3)


def cmd_sound_anchors(args):
    """Sounds placed by the story, not by the clock (05): --to-anchors writes, for each item's time fields, the
    narration landmark it follows and its offset (`<field>_anchor`); an anchor already written (by hand: a word, or a
    negative offset from a later moment) is kept. --resolve recomputes each field from its anchor against the current
    edit, after a re-recording, a new hold or a retime. The file is any JSON with a list of items (beds, sounds); the
    fields are named with --fields (default at,end). The previous file is kept as .bak."""
    rd, st = run_folder(args)
    n = int(args.video)
    path = Path(args.file)
    data = read_json(path, required=True)
    key = args.list or next((k for k in ('items', 'beds', 'sfx', 'sounds') if isinstance(data.get(k), list)), None)
    if not key:
        error('No list of items in the file (items, beds, sfx or sounds; or name it with --list).')
    marks = edit_landmarks(rd, n)
    if not marks:
        error('No narration landmarks: run captions-plan (or narration-measure and retime-shots) first.')
    fields = [f.strip() for f in (args.fields or 'at,end').split(',') if f.strip()]
    words = edit_words(rd, n)
    changes, missing, kept = [], [], []
    for it in data[key]:
        for f in fields:
            if args.to_anchors and it.get(f) is not None:
                if isinstance(it.get(f + '_anchor'), dict):
                    kept.append(f'{it.get("id")}.{f}')
                else:
                    it[f + '_anchor'] = anchor_for(it[f], marks)
            elif args.resolve and isinstance(it.get(f + '_anchor'), dict):
                v = resolve_anchor(it[f + '_anchor'], marks, words)
                if v is None:
                    missing.append(f'{it.get("id")}.{f}')
                    continue
                if it.get(f) is None or abs(float(it[f]) - v) > 1e-3:
                    changes.append({'id': it.get('id'), 'field': f, 'was': it.get(f), 'now': v})
                it[f] = v
    if missing:
        error('Some anchors name a landmark the current edit does not have.', missing)
    shutil.copyfile(path, path.with_name(path.name + '.bak'))
    write_json(path, data)
    emit({'ok': True, 'file': str(path), 'mode': 'to-anchors' if args.to_anchors else 'resolve', 'items': len(data[key]),
          'changed': changes, 'anchors_kept': kept})


MASTER_SOUND_DB = -40.0     # a 10 ms window of the mastered mix counts as sound above this (dBFS)


def master_chain(gain_db, ceiling_dbtp, sample_rate):
    """One gain, then a 4x oversampled look-ahead peak limiter at the ceiling (its delay compensated), back to the source
    rate. No compressor: the voice and the beds keep the balance they were mixed at."""
    limit = 10 ** (float(ceiling_dbtp) / 20)
    return (f'volume={float(gain_db):.2f}dB,aresample={4 * int(sample_rate)},alimiter=limit={limit:.4f}:attack=5:'
            f'release=80:level=false:asc=1:latency=1,aresample={int(sample_rate)}')


def limiter_activity(src_wav, gain_db, out_wav, sample_rate):
    """How hard the limiter worked: the share of 10 ms windows with sound that it took down by more than 1 dB and by
    more than 3 dB (the gained mix before the limiter against the mix after it, on the same clock). Facts only."""
    import numpy as np

    def load(path, af=None):
        cmd = ['ffmpeg', '-v', 'error', '-i', str(path)] + (['-af', af] if af else []) + \
              ['-ac', '1', '-ar', str(int(sample_rate)), '-f', 'f32le', '-']
        return np.frombuffer(subprocess.run(cmd, capture_output=True).stdout, dtype=np.float32).astype(np.float64)
    pre, post = load(src_wav, f'volume={float(gain_db):.2f}dB'), load(out_wav)
    w = max(1, int(0.01 * sample_rate))
    k = min(len(pre), len(post)) // w
    if not k:
        return {}

    def env(x):
        return np.sqrt((x[:k * w].reshape(k, w) ** 2).mean(1)) + 1e-12
    a, b = env(pre), env(post)
    sound = 20 * np.log10(b) > MASTER_SOUND_DB
    if not sound.any():
        return {}
    gr = 20 * np.log10(a / b)[sound]
    return {'windows_with_sound': int(sound.sum()), 'over_1db_share': round(float((gr > 1).mean()), 4),
            'over_3db_share': round(float((gr > 3).mean()), 4), 'over_6db_share': round(float((gr > 6).mean()), 4)}


def reference_files(rd, ids):
    """The run's reference videos by id (00-inventory/references.json)."""
    inv = read_json(rd / '00-inventory' / 'references.json')
    rows = []
    for v in (inv.values() if isinstance(inv, dict) else []):
        if isinstance(v, list):
            rows += [r for r in v if isinstance(r, dict)]
    base = Path(str(inv.get('references_dir') or '.')) if isinstance(inv, dict) else Path('.')
    by = {}
    for r in rows:
        p = r.get('source_path') or r.get('path') or r.get('file') or (
            str(base / r['relative_path']) if r.get('relative_path') else None)
        by[str(r.get('id'))] = p
    return {i: by.get(i) for i in ids}


def cmd_master_sound(args):
    """The export's sound brought to the loudness the niche's own videos are mastered at (YouTube turns a loud video down
    but never turns a quiet one up). One gain and a peak limiter over the whole mix; the picture is copied untouched and
    the export itself is kept. The agent picks the target from the references measured here (--refs) and says why; this
    measures, applies and records: the mastered MP4 (--out) and 80-deliverables/video-NN/master.json. The mastered file
    is the one export-check, the final watch review and release-check then read."""
    rd, st = run_folder(args)
    n = int(args.video)
    src, out = Path(args.file), Path(args.out)
    target, ceiling = float(args.target_lufs), float(args.true_peak)
    if not src.is_file():
        error(f'No export at {src}.')
    if n_words(args.why) < MIN_NOTE_WORDS:
        error('Say why this loudness (--why "..."): what the references measured, and what the video needs.')
    if not -24.0 <= target <= -9.0:
        error('--target-lufs must be between -24 and -9 LUFS.')
    if ceiling > -0.5:
        error('--true-peak must leave the encoder room: -0.5 dBTP or lower.')
    if out.resolve() == src.resolve():
        error('--out must be a new file: the export itself is kept as it is.')
    pr = json.loads(subprocess.run(['ffprobe', '-v', 'error', '-show_entries', 'stream=codec_type,sample_rate',
                                    '-of', 'json', str(src)], capture_output=True, text=True).stdout or '{}')
    audio = [x for x in pr.get('streams') or [] if x.get('codec_type') == 'audio']
    if not audio:
        error('The export has no sound to master.')
    sr = int(audio[0].get('sample_rate') or 48000)
    refs = {}
    for rid, path in reference_files(rd, [x.strip() for x in (args.refs or '').split(',') if x.strip()]).items():
        refs[rid] = ({'file': path, **loudness_stats(path)} if path and Path(path).is_file() else {'error': 'not found'})
    with tempfile.TemporaryDirectory() as td:
        raw, mixed = Path(td) / 'export.wav', Path(td) / 'mastered.wav'
        subprocess.run(['ffmpeg', '-v', 'error', '-y', '-i', str(src), '-vn', '-c:a', 'pcm_s24le', str(raw)], check=True)
        before = loudness_stats(raw)
        if before.get('integrated_lufs') is None:
            error('The export\'s loudness could not be measured.', before)
        gain, passes = target - before['integrated_lufs'], []
        for _ in range(3):              # the limiter takes a little loudness back: aim again from what it measured
            chain = master_chain(gain, ceiling, sr)
            subprocess.run(['ffmpeg', '-v', 'error', '-y', '-i', str(raw), '-af', chain, '-c:a', 'pcm_s24le', str(mixed)],
                           check=True)
            got = loudness_stats(mixed)
            passes.append({'gain_db': round(gain, 2), **got})
            if got.get('integrated_lufs') is None or abs(got['integrated_lufs'] - target) <= 0.2:
                break
            gain += target - got['integrated_lufs']
        activity = limiter_activity(raw, gain, mixed, sr)
        out.parent.mkdir(parents=True, exist_ok=True)
        part = out.with_name(out.stem + '.part' + out.suffix)
        subprocess.run(['ffmpeg', '-v', 'error', '-y', '-i', str(src), '-map', '0:v:0', '-map', '0:a:0', '-c:v', 'copy',
                        '-af', chain, '-c:a', 'aac', '-b:a', '320k', '-ar', str(sr), '-movflags', '+faststart', str(part)],
                       check=True)
        part.replace(out)
    after = loudness_stats(out)
    rec = {'made_at': now(), 'export': {'file': str(src), 'sha256': file_sha256(src), **before},
           'mastered': {'file': str(out), 'sha256': file_sha256(out), **after},
           'target_lufs': target, 'true_peak_ceiling_dbtp': ceiling, 'chain': chain, 'gain_db': round(gain, 2),
           'passes': passes, 'limiter_activity': activity, 'references': refs, 'why': args.why,
           'what_it_does': 'one gain and a 4x oversampled look-ahead peak limiter over the whole mix; the picture copied '
                           'untouched; the export kept as it is'}
    mpath = rd / '80-deliverables' / f'video-{n:02d}' / 'master.json'
    old = read_json(mpath)
    write_json(mpath, {**rec, 'history': (old.get('history') or []) + ([{k: old[k] for k in ('made_at', 'export', 'mastered',
                                                                                              'target_lufs')}]
                                                                        if old.get('mastered') else [])})
    miss = after.get('integrated_lufs') is None or abs(after['integrated_lufs'] - target) > 0.5 or \
        (after.get('true_peak_dbtp') or 0) > ceiling + 0.5
    emit({'ok': not miss, 'mastered': str(out), 'export': before, 'result': after, 'gain_db': round(gain, 2),
          'limiter_activity': activity, 'references': {k: {x: v.get(x) for x in ('integrated_lufs', 'true_peak_dbtp')}
                                                        for k, v in refs.items()}, 'record': str(mpath),
          'next': 'export-check --deep on the mastered file, then the final watch review of that file and release-check.'},
         1 if miss else 0)


def cmd_export_check(args):
    rd, st = run_folder(args)
    res = export_facts(rd, args.video, args.file, deep=args.deep)
    # The export on record by its full sha256, with the project it was checked against: release-check binds to this.
    f = Path(args.file).expanduser().resolve()
    sha = res['sha256']
    p = export_provenance_path(rd, args.video)
    rec = read_json(p) or {'video': int(args.video), 'exports': {}}
    rec.setdefault('exports', {})[sha] = {
        'file': str(f), 'sha256': sha, 'fingerprint': quick_fingerprint(f), 'size_bytes': f.stat().st_size,
        'checked_at': now(), 'deep': bool(args.deep), 'ready': res['ready'], 'issues': res['issues'],
        'metadata': res['metadata'], 'project': res.get('project'), 'pictures': res.get('pictures'),
        'blank_spans': res.get('blank_spans'), 'narration_in_export': res.get('narration_in_export'),
        'loudness': res.get('loudness'), 'role': res.get('role')}
    write_json(p, rec)
    res['provenance'] = {'file': str(p), 'sha256': sha}
    res.pop('project', None)
    res['manual_review_required'] = ['watch opening/first minute', 'sample each major narrative chapter',
                                     'watch last minute', 'listen to all TTS joins',
                                     'check factual assertions/visual chronology', 'review title-thumbnail promise',
                                     'final watch review: av-profile --file, review-packet --kind final, release-check']
    emit(res, 0 if res['ready'] else 2)


NUM_ONES = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8,
            'nine': 9}
NUM_TEENS = {'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15, 'sixteen': 16,
             'seventeen': 17, 'eighteen': 18, 'nineteen': 19}
NUM_TENS = {'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60, 'seventy': 70, 'eighty': 80,
            'ninety': 90}
NUM_SCALES = {'thousand': 1000, 'million': 10 ** 6, 'billion': 10 ** 9}
NUM_WORDS = set(NUM_ONES) | set(NUM_TEENS) | set(NUM_TENS) | set(NUM_SCALES) | {'hundred'}


def _num_kind(w):
    if w in NUM_ONES:
        return 'ones', NUM_ONES[w]
    if w in NUM_TEENS:
        return 'teen', NUM_TEENS[w]
    if w in NUM_TENS:
        return 'tens', NUM_TENS[w]
    if w == 'hundred':
        return 'hundred', 100
    if w in NUM_SCALES:
        return 'scale', NUM_SCALES[w]
    return None, None


def _merge_numbers(toks):
    """English number words as digits, so a spoken number and Whisper's digits are one token: 'twelve' -> '12',
    'two hundred and forty' -> '240', 'twenty-six' -> '26', 'nineteen fifty' -> '1950' (a year said in pairs).
    Returns [(token, first_index, last_index)] over the input tokens."""
    out, i, n = [], 0, len(toks)
    while i < n:
        kind, val = _num_kind(toks[i])
        if kind is None or kind in ('hundred', 'scale'):
            if toks[i] == 'a' and i + 1 < n and _num_kind(toks[i + 1])[0] in ('hundred', 'scale'):
                kind, val = 'ones', 1
            else:
                out.append((toks[i], i, i))
                i += 1
                continue
        chunks, total, cur, last, j, start = [], 0, val, kind, i + 1, i
        while j < n:
            k2, v2 = _num_kind(toks[j])
            if toks[j] == 'and' and j + 1 < n and last in ('hundred', 'scale') and _num_kind(toks[j + 1])[0] in ('ones', 'teen', 'tens'):
                j += 1
                continue
            if k2 is None:
                break
            ok = (last == 'tens' and k2 == 'ones') or (k2 == 'hundred' and last in ('ones', 'teen', 'tens')) or \
                 (last in ('hundred', 'scale') and k2 in ('ones', 'teen', 'tens')) or k2 == 'scale'
            if not ok:
                chunks.append((total + cur, start, j - 1))
                total, cur, last, start = 0, v2, k2, j
                j += 1
                continue
            if k2 == 'hundred':
                cur *= 100
            elif k2 == 'scale':
                total += cur * v2
                cur = 0
            else:
                cur += v2
            last = k2
            j += 1
        chunks.append((total + cur, start, j - 1))
        if len(chunks) == 2 and 10 <= chunks[0][0] <= 99 and 10 <= chunks[1][0] <= 99:
            out.append((str(chunks[0][0] * 100 + chunks[1][0]), chunks[0][1], chunks[1][2]))   # 'nineteen fifty'
        else:
            out += [(str(v), a, b) for v, a, b in chunks]
        i = j
    return out


def raw_tokens(text, english=True):
    s = strip_tags(text)
    if english:
        s = re.sub(r'(\d)\s*%', r'\1 percent', s)
        s = re.sub(r'\$\s?(\d[\d,.]*)', r'\1 dollars', s)
    s = re.sub(r'(?<=\d),(?=\d{3}\b)', '', s)
    out = []
    for w in re.findall(r"\b[\w]+(?:[-'.][\w]+)*\b", s, flags=re.UNICODE):
        w = w.lower()
        if english and '-' in w and all(p in NUM_WORDS for p in w.split('-')):
            out += w.split('-')
            continue
        t = re.sub(r"[-']", '', w)
        if not re.fullmatch(r'\d+\.\d+', t):
            t = t.replace('.', '')
        if t:
            out.append(t)
    return out


def line_token_map(text, language='en'):
    """A line's raw word tokens and its comparable tokens over them: (raw, [(token, first_raw, last_raw)]), numbers merged in
    English as in tokens_of. Lets a caption word be matched to the tokens it really holds (captions.line_words)."""
    english = str(language or 'en').lower().startswith('en')
    raw = raw_tokens(text, english)
    return raw, (_merge_numbers(raw) if english else [(w, i, i) for i, w in enumerate(raw)])


def tokens_of(text, language='en'):
    """Comparable word tokens: lower case, hyphens and apostrophes dropped ('Yudam-ni' matches 'Yudamni'), and, in
    English, numbers as digits on both sides ('Twelve divisions' matches Whisper's '12 divisions')."""
    english = str(language or 'en').lower().startswith('en')
    toks = raw_tokens(text, english)
    return [t for t, _, _ in _merge_numbers(toks)] if english else toks


def align_detail(line_texts, words, language='en'):
    """Script lines against Whisper's words: difflib on comparable tokens, then, inside each stretch where the two
    disagree, a word Whisper spelt differently (a name: 'Chosin' heard as 'Choson') paired by its letters. Returns
    per-line token times, the share matched, and Whisper's tokens with their times and which were matched."""
    english = str(language or 'en').lower().startswith('en')
    s_tok, owner, pos, tok_time = [], [], [], []
    for li, text in enumerate(line_texts):
        toks = tokens_of(text, language)
        tok_time.append([None] * len(toks))
        for k, t in enumerate(toks):
            s_tok.append(t)
            owner.append(li)
            pos.append(k)
    raw, times = [], []
    for w in words:
        for t in raw_tokens(w['text'], english):
            raw.append(t)
            times.append((w['start_s'], w['end_s']))
    merged = _merge_numbers(raw) if english else [(t, i, i) for i, t in enumerate(raw)]
    h_tok = [t for t, _, _ in merged]
    h_time = [(times[a][0], times[b][1]) for _, a, b in merged]
    used, matched = set(), 0
    for op, i1, i2, j1, j2 in difflib.SequenceMatcher(a=s_tok, b=h_tok, autojunk=False).get_opcodes():
        if op == 'equal':
            for k in range(i2 - i1):
                tok_time[owner[i1 + k]][pos[i1 + k]] = h_time[j1 + k]
                used.add(j1 + k)
                matched += 1
        elif op == 'replace':
            jj = j1
            for ii in range(i1, i2):
                if len(s_tok[ii]) < 4:
                    continue
                for jx in range(jj, j2):
                    if difflib.SequenceMatcher(None, s_tok[ii], h_tok[jx]).ratio() >= 0.75:
                        tok_time[owner[ii]][pos[ii]] = h_time[jx]
                        used.add(jx)
                        matched += 1
                        jj = jx + 1
                        break
    return {'tok_time': tok_time, 'ratio': (matched / len(s_tok)) if s_tok else 0.0,
            'heard': h_tok, 'heard_times': h_time, 'heard_used': used}


def align_lines(line_texts, words, language='en'):
    """Match script lines to Whisper words. Returns, per line, a list of per-token (start, end) times (None where
    Whisper heard something else), and the share of script tokens matched."""
    d = align_detail(line_texts, words, language)
    return d['tok_time'], d['ratio']


def confirmations_path(folder):
    return folder / 'listening-confirmations.json'


def merge_recheck_words(row, rec, offset):
    """A line found on its own second listen keeps the word times that listen heard, where the long pass had none or
    fewer (2026-11-22: L013 "They said no. He tried again. No. He tried a third time. Still no." was heard whole on the
    second listen, but only its start and end were kept: ten of its words had no time and the captions squeezed them
    into its last 0.4 s). Returns how many tokens it gave a time."""
    toks = rec.get('tok_times') or []
    old = row.get('_tok') or []
    if len(toks) != len(old) or sum(1 for x in toks if x) <= sum(1 for x in old if x):
        return 0
    row['_tok'] = [None if x is None else (offset + x[0], offset + x[1]) for x in toks]
    row['matched_words'] = sum(1 for x in toks if x)
    row['words_from_recheck'] = True
    return row['matched_words']


MISSING_RUN_WORDS = 4      # consecutive words of a line not heard: a dropped clause, whatever share of the line was heard
JOIN_LEVEL_STEP_LU = 3.0    # a level step this large across a join between parts is audible: the user listens


def _longest_unheard(toks):
    """(start, end) of the longest run of a line's tokens with no time (end exclusive)."""
    best, cur = (0, 0), None
    for i, t in enumerate(list(toks or []) + [1]):
        if t is None and i < len(toks or []):
            cur = i if cur is None else cur
        else:
            if cur is not None and i - cur > best[1] - best[0]:
                best = (cur, i)
            cur = None
    return best


def _segment_loudness(path, start, secs):
    """Integrated loudness (LUFS) of secs of a recording from start; None when it cannot be measured."""
    import tempfile
    with tempfile.TemporaryDirectory() as td:
        out = Path(td) / 'edge.wav'
        cp = subprocess.run(['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', '-ss', f'{max(0.0, start):.3f}',
                             '-t', f'{max(0.5, secs):.3f}', '-i', str(path), '-ac', '1', str(out)], capture_output=True)
        if cp.returncode != 0 or not out.is_file():
            return None
        try:
            return loudness_stats(out).get('integrated_lufs')
        except (OSError, ValueError, RuntimeError):
            return None


PACE_SPREAD_MAX = 1.2       # references further apart than this in pace are not averaged blindly


def pace_context(rd, video):
    """What a narration's pace is examined against besides itself: the locked planning pace (`target_wpm`: the length
    lock's pace_wpm, a forecast and never a target the delivery is held to), the references' paces while speaking
    (length lock per_ref_wpm) and the narrator's measured norm (the voice lock), when known."""
    vd = video_dir(rd, int(video))
    ll = read_json(vd / 'length-lock.json')
    per = ll.get('per_ref_wpm') or {}
    # the narrator's measured norm: where the voice lock really keeps it (60-voice/video-NN/voice-lock.json,
    # "measured"). Until 2026-11-26 this looked in the plans folder for a key that is no longer written: always empty.
    return {'target_wpm': ll.get('pace_wpm'),
            'reference_wpm': [v for v in (per.values() if isinstance(per, dict) else per) if v],
            'voice_wpm': (voice_measurement(rd, int(video)) or {}).get('wpm')}
PACE_SLOW_WORDS = ('slow', 'slower', 'unhurried', 'reflective', 'measured', 'calm', 'gentle', 'lingering', 'deliberate',
                   'quiet', 'patient', 'breathing', 'hushed')
PACE_FAST_WORDS = ('brisk', 'quick', 'quicker', 'urgent', 'fast', 'faster', 'rapid', 'energetic', 'punchy', 'driving',
                   'pressing', 'tense', 'racing')


def pace_intent(beat):
    """What a beat asked of the voice's pace, relative to the video's own: 'slower', 'faster', or None (the same, or
    not said). An explicit pace_relative wins; otherwise the beat's own pace words."""
    rel = str((beat or {}).get('pace_relative') or '').strip().lower()
    if rel in ('slower', 'faster', 'same'):
        return None if rel == 'same' else rel
    words = set(re.findall(r'[a-z]+', str((beat or {}).get('pace') or '').lower()))
    slow, fast = bool(words & set(PACE_SLOW_WORDS)), bool(words & set(PACE_FAST_WORDS))
    return 'slower' if slow and not fast else ('faster' if fast and not slow else None)


def pace_signals(beat_rows, beats, line_rows=None, context=None):
    """Where the measured delivery may not be what a beat asked for: evidence to examine in context, never a verdict
    (the user, 2026-11-24: no fixed percentage decides that a narration is wrong). Each beat is read against this
    narration's own median pace while speaking and its own natural variation: how far its lines' rates spread anyway
    (their median absolute deviation, from lines of six words or more; from the beats when the lines are too few).
    A signal: a beat that asked to be slower and runs faster than this narration's usual by more than that natural
    variation, one that asked to be faster and runs slower by as much, one of the densest beats in numbers running fast
    by as much (unless it asked for speed), and a whole narration outside the pace of every reference. Each carries
    what the examination needs: the beat's rate and what it asked, the narration's median and variation, its density,
    the locked planning pace, the narrator's measured norm and the references' paces. A beat that asked for speed and
    has it is never a signal: intentional variation stays."""
    ctx = context or {}
    rates = [r['wpm_inside_lines'] for r in beat_rows if r.get('wpm_inside_lines')]
    out = []
    if not rates:
        return out
    norm = statistics.median(rates)
    lr = []
    for x in line_rows or []:
        try:
            dur = float(x['end_s']) - float(x['start_s'])
        except (KeyError, TypeError, ValueError):
            continue
        if int(x.get('words') or 0) >= 6 and dur > 0:
            lr.append(int(x['words']) / dur * 60)
    basis, vals = ('lines', lr) if len(lr) >= 5 else ('beats', rates)
    mid = statistics.median(vals)
    spread = statistics.median([abs(v / mid - 1) for v in vals]) if mid else 0.0
    refs = sorted(float(v) for v in (ctx.get('reference_wpm') or []) if v)
    evidence = {'narration_median_wpm': round(norm), 'natural_variation_pct': round(100 * spread, 1),
                'variation_from': basis, 'target_wpm': ctx.get('target_wpm'), 'narrator_norm_wpm': ctx.get('voice_wpm'),
                'references_wpm': [round(v) for v in refs] or None}
    if refs and not refs[0] <= norm <= refs[-1]:
        out.append({'beat': 'overall', 'kind': 'narration_outside_every_references_pace',
                    'wpm_inside_lines': round(norm), **evidence})
    if len(rates) < 3 or spread <= 0:
        return out            # too little narration, or none of it varies: nothing to tell an unusual beat from a usual one
    dens = sorted((float(r.get('numbers_per_min') or 0) for r in beat_rows if r.get('wpm_inside_lines')), reverse=True)
    densest = dens[max(0, len(dens) // 4 - 1)]
    by_id = {str(b.get('id')): b for b in beats or []}
    for r in beat_rows:
        rate = r.get('wpm_inside_lines')
        if not rate:
            continue
        dev = (rate / norm - 1) / spread
        b = by_id.get(str(r.get('id'))) or {}
        want = pace_intent(b)
        npm = float(r.get('numbers_per_min') or 0)
        row = {'beat': str(r.get('id')), 'wpm_inside_lines': rate, 'ratio': round(rate / norm, 2),
               'natural_variations_from_median': round(dev, 1), 'asked': b.get('pace'), 'asked_relative': want,
               'numbers_per_min': npm, **evidence}
        if want == 'slower' and dev >= 1:
            out.append({**row, 'kind': 'asked_slower_runs_faster_than_usual'})
        elif want == 'faster' and dev <= -1:
            out.append({**row, 'kind': 'asked_faster_runs_slower_than_usual'})
        elif npm > 0 and npm >= densest and dev >= 1 and want != 'faster':
            out.append({**row, 'kind': 'fast_where_densest'})
    return out


def editorial_section(review_text, heading_rx):
    """The text under a heading of editorial-review.md whose title matches heading_rx, up to the next heading."""
    m = re.search(r'^#+[^\n]*(?:' + heading_rx + r')[^\n]*\n(.*?)(?=^#|\Z)', review_text or '', flags=re.I | re.M | re.S)
    return m.group(1) if m else ''


def recheck_line(part_file, a, b, line_text, wdir, lid, args, language):
    """A line the long Whisper pass did not hear, listened to again on its own: Whisper medium on a short window
    of the part around where the line should be. Found, it was a transcription miss; still missing, the line may
    really be absent from the audio."""
    clip, tj_path = wdir / f'recheck-{lid}.wav', wdir / f'recheck-{lid}.json'
    window = [round(a, 2), round(b, 2)]
    cached = read_json(tj_path)
    if not (cached.get('window') == window and tj_path.stat().st_mtime >= Path(part_file).stat().st_mtime
            and cached.get('model') == args.whisper_model):
        run_cmd(['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', '-ss', f'{a:.3f}', '-t',
                 f'{max(0.5, b - a):.3f}', '-i', str(part_file), '-ac', '1', '-ar', '16000', str(clip)])
        transcribe(clip, tj_path, args.whisper_model, args.device, args.compute_type)
        cached = read_json(tj_path)
        cached['window'] = window
        write_json(tj_path, cached)
    words = transcript_words(cached)
    d = align_detail([line_text], words, language)
    got = [x for x in d['tok_time'][0] if x]
    return {'line': lid, 'window_s': window, 'matched': round(d['ratio'], 2), 'found': d['ratio'] >= 0.6,
            'heard': ' '.join(str(w['text']).strip() for w in words)[:300],
            'times': [a + got[0][0], a + max(x[1] for x in got)] if got else None,
            # each of the line's tokens as this listen heard it, on the part's clock (None where it did not)
            'tok_times': [None if x is None else [a + x[0], a + x[1]] for x in d['tok_time'][0]]}


def cmd_narration_measure(args):
    """Measure the real narration with the references' own yardstick (the same transcribe() and
    wpm_from_transcript_raw): real pace (while speaking, and overall with every pause), the natural gap after each
    line, what every inline tag actually cost, how the narration pauses next to the references, when each script line
    is spoken, and the joins between parts. Every line must be heard: a line Whisper's long pass missed is listened to
    again on its own (a short Whisper medium window); one still missing blocks the edit until it is re-recorded or the
    user confirms by listening (--confirm L105 --reason "..."). A tag whose words were heard was read aloud: the same.
    Writes 50-audio/video-NN/line-times.json and, from 300+ words of the locked voice, the voice lock's `measured`
    (what plan-check's real_forecast_s and the tts calibration gate read)."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    script = read_json(vd / 'script.json', required=True)
    lock = read_json(vd / 'length-lock.json', required=True)
    language = lock.get('language') or script.get('language') or 'en'
    lines = script.get('lines') or []
    folder = rd / '50-audio' / f'video-{n:02d}'
    manifest = read_json(folder / 'manifest.json', required=True)
    chunks = manifest.get('chunks') or []
    finished = set(manifest.get('finished_parts') or [])
    use = [c for c in chunks if c['id'] in finished and (folder / c['file']).is_file()]
    if args.parts:
        want = {int(x) for x in args.parts.split(',') if x.strip()}
        use = [c for c in use if c['id'] in want]
    if not use:
        error('No finished narration parts to measure.')
    durations = {c['id']: probe(folder / c['file'])['duration_s'] for c in chunks if (folder / c['file']).is_file()}
    prints = {c['id']: quick_fingerprint(folder / c['file']) for c in chunks if (folder / c['file']).is_file()}
    wdir = folder / 'whisper'
    wdir.mkdir(exist_ok=True)
    conf_path = confirmations_path(folder)
    conf = read_json(conf_path)
    if args.confirm:
        if n_words(args.reason) < MIN_NOTE_WORDS:
            error('A listening confirmation says who listened and what they heard (--reason).')
        line_part = {li: c for c in chunks for li in range(int(c['line_start']), int(c['line_end']) + 1)}
        ids = [x.strip() for x in args.confirm.split(',') if x.strip()]
        index = {str(r.get('id') or f'L{i + 1:03d}'): i + 1 for i, r in enumerate(lines)}
        for lid in ids:
            if lid not in index:
                error('--confirm names a line the script does not have.', lid)
            c = line_part.get(index[lid])
            conf.setdefault('lines', {})[lid] = {'reason': args.reason, 'at': now(),
                                                 'part_fingerprint': prints.get(c['id']) if c else None}
        write_json(conf_path, conf)
    rows, all_words, per_part, all_segments = {}, [], [], []
    heard_tokens = []          # (token, start, end, used) over the whole narration
    rechecks, tot_words, tot_speech, tot_dur = [], 0.0, 0.0, 0.0
    for c in use:
        lo, hi = int(c['line_start']), int(c['line_end'])
        text = '\n'.join(str(r.get('text') or '').strip() for r in lines[lo - 1:hi])
        if hashlib.sha256(text.encode('utf-8')).hexdigest() != c.get('text_sha256'):
            error(f'Part {c["id"]} (lines {lo}-{hi}) was recorded from other text than the script has now. '
                  'Measure only the parts that match (--parts), or re-record this one.')
        part = folder / c['file']
        tpath = wdir / (Path(c['file']).stem + '.json')
        cached = read_json(tpath)
        if not (cached and tpath.stat().st_mtime >= part.stat().st_mtime and cached.get('model') == args.whisper_model):
            transcribe(part, tpath, args.whisper_model, args.device, args.compute_type)
        tj = read_json(tpath)
        wc, speech = transcript_speech(tpath.with_suffix('.txt').read_text(encoding='utf-8', errors='replace'))
        offset = sum(durations.get(x['id'], 0) for x in chunks if x['id'] < c['id'])
        words = transcript_words(tj)
        d = align_detail([str(r.get('text') or '') for r in lines[lo - 1:hi]], words, language)
        for j, tt in enumerate(d['tok_time']):
            # A word Whisper placed with no length (several words at one instant) is a failed alignment, not a time:
            # it counts as unheard, so its line is listened to again and the recheck windows lean on real times only
            # (2026-11-23: "What would a perfect" stacked at one instant 6 s late hid "He would warn them, of course."
            # and put the recheck of that line in the wrong place, although the voice had said every word).
            tt = [x if (x and float(x[1]) - float(x[0]) > 0.005) else None for x in tt]
            d['tok_time'][j] = tt
            got = [x for x in tt if x]
            rows[lo + j] = {'id': lines[lo + j - 1].get('id'), 'index': lo + j, 'part': c['id'],
                            'start_s': round(offset + got[0][0], 3) if got else None,
                            'end_s': round(offset + max(x[1] for x in got), 3) if got else None,
                            'matched_words': len(got), 'words': len(tt),
                            '_tok': [None if x is None else (offset + x[0], offset + x[1]) for x in tt]}
        heard_tokens += [(t, offset + a, offset + b, k in d['heard_used'])
                         for k, (t, (a, b)) in enumerate(zip(d['heard'], d['heard_times']))]
        # A line the long pass did not hear (or barely): listened to again, on its own.
        order_here = list(range(lo, hi + 1))
        for li in order_here:
            r = rows[li]
            short = r['words'] <= 1
            heard_enough = bool(r['matched_words']) if short else r['matched_words'] / r['words'] >= 0.5
            a0, b0 = _longest_unheard(r['_tok'])
            # a run of words not heard is listened to again even when most of the line was (a clause can be dropped)
            gap_run = r['words'] >= 6 and b0 - a0 >= MISSING_RUN_WORDS
            if not r['words'] or (heard_enough and not gap_run):
                continue
            prev_end = next((rows[x]['end_s'] for x in reversed(range(lo, li)) if rows[x]['end_s'] is not None
                             and rows[x]['matched_words']), None)
            next_start = next((rows[x]['start_s'] for x in range(li + 1, hi + 1) if rows[x]['start_s'] is not None
                               and rows[x]['matched_words']), None)
            a = max(0.0, (prev_end - offset - 0.6) if prev_end is not None else 0.0)
            b = min(durations[c['id']], (next_start - offset + 0.6) if next_start is not None else durations[c['id']])
            if b - a > 60:
                b = a + 60
            if args.no_recheck:
                rec = {'line': r['id'], 'window_s': [round(a, 2), round(b, 2)], 'found': False, 'skipped': True}
            else:
                rec = recheck_line(part, a, b, str(lines[li - 1].get('text') or ''), wdir, str(r['id']), args, language)
                if rec['found'] and rec.get('times'):
                    r['start_s'], r['end_s'] = round(offset + rec['times'][0], 3), round(offset + rec['times'][1], 3)
                    r['heard_on_recheck'] = True
                    merge_recheck_words(r, rec, offset)
            rec['part'] = c['id']
            rechecks.append(rec)
        all_words += [{'start_s': w['start_s'] + offset, 'end_s': w['end_s'] + offset, 'text': w['text']} for w in words]
        all_segments += _segments_of(tj, offset)
        per_part.append({'id': c['id'], 'lines': [lo, hi], 'offset_s': round(offset, 3), 'fingerprint': prints[c['id']],
                         'duration_s': durations[c['id']], 'words': wc, 'speech_s': round(speech, 2),
                         'wpm': round(wc / (speech / 60)) if speech else None, 'alignment_match_ratio': round(d['ratio'], 3)})
        tot_words += wc
        tot_speech += speech
        tot_dur += durations[c['id']]
    order = sorted(rows)
    for k, li in enumerate(order):     # a line still without times sits between its neighbours
        r = rows[li]
        if r['start_s'] is None:
            prev_end = next((rows[x]['end_s'] for x in reversed(order[:k]) if rows[x]['end_s'] is not None), None)
            next_start = next((rows[x]['start_s'] for x in order[k + 1:] if rows[x]['start_s'] is not None), None)
            r['start_s'] = prev_end if prev_end is not None else next_start
            r['end_s'] = next_start if next_start is not None else prev_end
            r['interpolated'] = True
    confirmed = conf.get('lines') or {}
    def confirmed_for(lid):
        c = confirmed.get(str(lid))
        li = next((x for x in order if str(rows[x]['id']) == str(lid)), None)
        return bool(c and li is not None and c.get('part_fingerprint') == prints.get(rows[li]['part']))
    unheard = [str(rc['line']) for rc in rechecks if not rc.get('found') and not confirmed_for(rc['line'])]
    # A line heard in most of its words can still have lost a clause: a run of words with no time after its second
    # listen is a gap in the recording, kept apart from whole lines unheard (and confirmed the same way, by listening)
    missing_runs = []
    for li in order:
        r = rows[li]
        if r['words'] < 6 or str(r['id']) in unheard or confirmed_for(r['id']):
            continue
        a0, b0 = _longest_unheard(r.get('_tok') or [])
        if b0 - a0 >= MISSING_RUN_WORDS:
            toks = tokens_of(str(lines[li - 1].get('text') or ''), language)
            missing_runs.append({'line': str(r['id']), 'words': ' '.join(str(t) for t in toks[a0:b0])[:160],
                                 'count': b0 - a0})
    # Every tag: what it cost, and whether its own words were heard (read aloud instead of performed).
    pause_tag_at, tag_rows = set(), []
    for li in order:
        text = str(lines[li - 1].get('text') or '')
        for m in TAG_RE.finditer(text):
            entry = classify_tag(m.group(1))
            at_start, at_end = not text[:m.start()].strip(), not text[m.end():].strip()
            tag_rows.append({'li': li, 'line': rows[li]['id'], 'tag': entry['tag'], 'category': entry.get('category'),
                             'k': len(tokens_of(text[:m.start()], language)), 'at_start': at_start, 'at_end': at_end,
                             'inner': m.group(1)})
            if entry.get('category') == 'pause':
                pause_tag_at.add(li if at_end else li - 1 if at_start else -1)
    gaps = [rows[li + 1]['start_s'] - rows[li]['end_s'] for li in order
            if li + 1 in rows and li not in pause_tag_at and rows[li]['end_s'] is not None
            and rows[li + 1]['start_s'] is not None and rows[li + 1]['part'] == rows[li]['part']]
    natural_gap = statistics.median(gaps) if gaps else 0.0
    measured_tags, read_aloud = [], []
    for t in tag_rows:
        li = t['li']
        tok, k = rows[li]['_tok'], t['k']
        before = next((x[1] for x in reversed(tok[:k]) if x), None)
        if before is None and li - 1 in rows:
            before = rows[li - 1]['end_s']
        after = next((x[0] for x in tok[k:] if x), None)
        if after is None and li + 1 in rows:
            after = rows[li + 1]['start_s']
        if before is None or after is None:
            continue
        base = natural_gap if (t['at_start'] or t['at_end']) else 0.15
        measured_tags.append({'line': t['line'], 'tag': t['tag'], 'gap_s': round(after - before, 2),
                              'excess_s': round(after - before - base, 2)})
        words_of_tag = [w for w in tokens_of(t['inner'], language) if len(w) > 2 and w not in EN_FUNCTION_WORDS]
        stray = [h for h, a, b, used in heard_tokens if not used and a >= before - 0.1 and b <= after + 0.1]
        if words_of_tag and sum(1 for w in words_of_tag if w in stray) * 2 >= len(words_of_tag):
            if not confirmed_for(t['line']):
                read_aloud.append({'line': t['line'], 'tag': t['tag'], 'heard': stray[:8]})
    costs = {}
    for m in measured_tags:
        costs.setdefault(m['tag'], []).append(m['excess_s'])
    costs = {k: round(statistics.median(v), 2) for k, v in costs.items()}
    tag_excess = sum(max(0.0, m['excess_s']) for m in measured_tags)
    nlines = len(rows)
    wpm = round(tot_words / (tot_speech / 60)) if tot_speech else None
    # Whisper's long pass drops a phrase now and then (measured here: ~1% of words, heard in the audio when a short
    # window is re-transcribed), so its word count runs a little low. wpm stays the references' yardstick (they are
    # measured the same way); the length forecast uses the script's own words over the same speech time.
    script_words = sum(count_words(lines[li - 1].get('text') or '') for li in rows)
    forecast_wpm = round(script_words / (tot_speech / 60), 1) if tot_speech else None
    overall_wpm = round(script_words / (tot_dur / 60), 1) if tot_dur else None
    per_line = round((tot_dur - tot_speech - tag_excess) / nlines, 3) if nlines else None
    complete = sorted(rows) == list(range(1, len(lines) + 1))
    ratio_all = (sum(p['alignment_match_ratio'] * (p['lines'][1] - p['lines'][0] + 1) for p in per_part) / nlines) if nlines else 0
    profile = pause_profile(all_words)
    # Possible repeats: three or more heard tokens matched to no script word, that repeat the words around them.
    repeats = []
    run = []
    for idx, (h, a, b, used) in enumerate(heard_tokens + [('', 0, 0, True)]):
        if not used and h:
            run.append(idx)
            continue
        if len(run) >= 3:
            seq = [heard_tokens[x][0] for x in run]
            around = [heard_tokens[x][0] for x in range(max(0, run[0] - 12), min(len(heard_tokens), run[-1] + 13))
                      if x not in run]
            if any(seq == around[x:x + len(seq)] for x in range(len(around) - len(seq) + 1)):
                repeats.append({'at_s': round(heard_tokens[run[0]][1], 2), 'heard': ' '.join(seq)})
        run = []
    # The silence after each line, read from the audio itself (av_tools.line_gaps: the quiet run around Whisper's
    # boundary; Whisper alone places a line's ends to within about 0.2 s). It is what a held silence is decided
    # against (hold-decide) and what the edit adds to (retime-shots), never an average: lines differ.
    tmpdir, joined, gap_error, audio_gaps = tempfile.mkdtemp(prefix='narration-measure-'), None, None, {}
    files = [folder / c['file'] for c in sorted(chunks, key=lambda x: x['id'])
             if c['id'] <= max(x['id'] for x in use) and (folder / c['file']).is_file()]
    try:
        av = _av()
        joined = av.concat_audio(files, Path(tmpdir) / 'narration.wav')
        g = av.line_gaps(joined, [{'index': li, 'start_s': rows[li]['start_s'], 'end_s': rows[li]['end_s']}
                                  for li in order], last_index=len(lines))
        audio_gaps = {int(x['index']): x for x in g['gaps']}
    except (RuntimeError, ValueError, OSError, ImportError, KeyError) as exc:
        gap_error = f'{type(exc).__name__}: {str(exc)[:200]}'
    for li in order:
        x = audio_gaps.get(li)
        if x:
            rows[li].update({'gap_after_s': x['gap_s'], 'gap_span_s': x['span_s'], 'gap_basis': x['basis']})
            if x.get('last_line'):
                rows[li]['gap_is_tail'] = True
            # Inside the silence: where an added silence would go (the middle of its longest quiet stretch, so a breath
            # stays with its line), how loud the voice's own silence is, and what else it holds (a breath, a click).
            for k in ('subrun_s', 'insert_at_s', 'floor_under_speech_db', 'other_material_s'):
                if x.get(k) is not None:
                    rows[li]['gap_' + k] = x[k]
    # A cue at a line's end (or start) is measured on the audio's own silence there, the basis hold-decide and the edit
    # use: Whisper's word ends drift by up to ~0.4 s, enough to hide a short pause or invent one. The usual gap it is
    # compared with is read the same way (lines without a pause cue, inside one part). The word-based value stays.
    audio_usual = [rows[li]['gap_after_s'] for li in order
                   if rows[li].get('gap_after_s') is not None and not rows[li].get('gap_is_tail')
                   and li not in pause_tag_at and li + 1 in rows and rows[li + 1]['part'] == rows[li]['part']]
    if audio_usual:
        base_audio = statistics.median(audio_usual)
        for t in tag_rows:
            if not (t['at_end'] or t['at_start']):
                continue
            g = (rows.get(t['li'] if t['at_end'] else t['li'] - 1) or {}).get('gap_after_s')
            m = next((x for x in measured_tags if x['line'] == t['line'] and x['tag'] == t['tag']), None)
            if g is None or m is None or m.get('basis') == 'audio':
                continue
            m.update({'words_gap_s': m['gap_s'], 'gap_s': round(g, 2), 'excess_s': round(g - base_audio, 2),
                      'usual_gap_s': round(base_audio, 2), 'basis': 'audio'})
        costs = {}
        for m in measured_tags:
            costs.setdefault(m['tag'], []).append(m['excess_s'])
        costs = {k: round(statistics.median(v), 2) for k, v in costs.items()}
        tag_excess = sum(max(0.0, m['excess_s']) for m in measured_tags)
        per_line = round((tot_dur - tot_speech - tag_excess) / nlines, 3) if nlines else None
    part_ends = {int(c['line_end']) for c in chunks}
    between = [float(rows[li]['gap_after_s']) for li in order if rows[li].get('gap_basis') == 'audio'
               and rows[li].get('gap_after_s') is not None and not rows[li].get('gap_is_tail') and li not in part_ends]
    natural_audio = statistics.median(between) if between else None
    # The joins: the gap between the parts against the voice's own gap between lines, the pace on each side, and
    # any words said twice across it. A join shorter than the natural gap gets a seam hold in the edit (retime-shots),
    # unless the line before it carries a planned or decided hold (that silence is decided as a whole: never stacked).
    held = {p['line'] for p in script_pause_plan(lines)[0]} | set(hold_decisions(rd, n)['decisions'])
    seams, by_index = [], {r['index']: r for r in rows.values()}
    ordered_parts = sorted(use, key=lambda x: x['id'])
    for a_c, b_c in zip(ordered_parts, ordered_parts[1:]):
        if b_c['id'] != a_c['id'] + 1:
            continue
        last, first = by_index.get(int(a_c['line_end'])), by_index.get(int(b_c['line_start']))
        if not last or not first or last['end_s'] is None or first['start_s'] is None:
            continue
        if last.get('gap_basis') == 'audio' and last.get('gap_after_s') is not None and natural_audio is not None:
            gap, natural_here = round(float(last['gap_after_s']), 3), natural_audio
        else:
            gap, natural_here = round(first['start_s'] - last['end_s'], 3), natural_gap
        planned = str(last['id']) in held
        hold = round(natural_here - gap, 2) if (not planned and natural_here - gap >= 0.08) else 0.0
        def side(lo_i, hi_i):
            rs = [by_index[x] for x in range(lo_i, hi_i + 1) if x in by_index and by_index[x]['start_s'] is not None]
            w = sum(count_words(lines[r['index'] - 1].get('text') or '') for r in rs)
            span = (rs[-1]['end_s'] - rs[0]['start_s']) if len(rs) > 1 else 0
            return round(w / (span / 60)) if span > 3 else None
        t = (last['end_s'] + first['start_s']) / 2
        before_tok = [h for h, a, b, u in heard_tokens if b <= t][-3:]
        after_tok = [h for h, a, b, u in heard_tokens if a >= t][:3]
        # the voice's level on each side of the join: the last 3 s of speech before it, the first 3 s after
        offs = {p['id']: p['offset_s'] for p in per_part}
        lv_a = _segment_loudness(folder / a_c['file'], last['end_s'] - offs.get(a_c['id'], 0.0) - 3.0, 3.0)
        lv_b = _segment_loudness(folder / b_c['file'], first['start_s'] - offs.get(b_c['id'], 0.0), 3.0)
        seams.append({'after_part': a_c['id'], 'after_line': last['id'], 'at_s': round(t, 3), 'gap_s': gap,
                      'natural_gap_s': round(natural_here, 3), 'seam_hold_s': hold,
                      'level_step_lu': round(lv_b - lv_a, 1) if lv_a is not None and lv_b is not None else None,
                      'wpm_before': side(int(a_c['line_end']) - 7, int(a_c['line_end'])),
                      'wpm_after': side(int(b_c['line_start']), int(b_c['line_start']) + 7),
                      'repeated_words': before_tok if before_tok and before_tok == after_tok else None})
    # Each beat as heard: its pace while speaking and with its pauses, how dense with numbers, next to what it asked.
    beat_rows = []
    for b in read_json(vd / 'beat-map.json').get('beats') or []:
        try:
            b0, b1 = int(b['line_start']), int(b['line_end'])
        except (KeyError, TypeError, ValueError):
            continue
        rs = [by_index[x] for x in range(b0, b1 + 1) if x in by_index and by_index[x]['start_s'] is not None]
        if len(rs) < 2:
            continue
        w = sum(count_words(lines[r['index'] - 1].get('text') or '') for r in rs)
        span = rs[-1]['end_s'] - rs[0]['start_s']
        inside = sum(max(0.0, r['end_s'] - r['start_s']) for r in rs)
        between = [y['start_s'] - x['end_s'] for x, y in zip(rs, rs[1:])]
        nums = sum(len(NUMBER_WORDS.findall(strip_tags(lines[r['index'] - 1].get('text') or ''))) for r in rs)
        beat_rows.append({'id': b.get('id'), 'start_s': round(rs[0]['start_s'], 2), 'end_s': round(rs[-1]['end_s'], 2),
                          'words': w, 'wpm_overall': round(w / (span / 60)) if span > 0 else None,
                          'wpm_inside_lines': round(w / (inside / 60)) if inside > 0 else None,
                          'longest_gap_s': round(max(between), 2) if between else None,
                          'gaps_over_0_8s': sum(1 for g in between if g >= 0.8),
                          'numbers_per_min': round(nums / (span / 60), 1) if span > 0 else None,
                          'tags': sum(1 for t in tag_rows if b0 <= t['li'] <= b1),
                          'intended': {x: b.get(x) for x in ('experience', 'narration_direction', 'pace')}})
    # Names on the pronunciation list, as Whisper heard them where they are said (a listening list, never a verdict:
    # Whisper itself mishears names).
    pron = pronunciation_facts(rd, n, lines)
    pron_heard = []
    for t in pron['terms']:
        tt = tokens_of(t['term'], language)
        for lid in pron['uses'].get(t['term']) or []:
            li = next((x for x in order if str(rows[x]['id']) == lid), None)
            if li is None or rows[li]['start_s'] is None:
                continue
            here = [h for h, a, b, u in heard_tokens if a >= rows[li]['start_s'] - 0.2 and b <= rows[li]['end_s'] + 0.2]
            hit = all(x in here for x in tt)
            close = None if hit else max(here, key=lambda h: difflib.SequenceMatcher(None, tt[0], h).ratio(), default=None)
            pron_heard.append({'term': t['term'], 'line': lid, 'at_s': rows[li]['start_s'], 'heard_as_written': hit,
                               'nearest_heard': close})
    # How the voice moves, beat by beat and on each side of every join, next to what each beat asked for and to the
    # references measured the same way (av_tools): the writing of the parts not yet recorded is where a flat stretch
    # gets fixed.
    delivery, delivery_error, cadence_usual, line_stats = None, None, {}, {}
    if not args.no_delivery:
        try:
            av = _av()
            spans = {}
            for b in beat_rows:
                spans[str(b['id'])] = (b['start_s'], b['end_s'])
            for li in order:        # every line, so a cue's line can be compared with this take's usual line
                if rows[li].get('start_s') is not None and rows[li].get('end_s') is not None:
                    spans[f'line_{li}'] = (rows[li]['start_s'], rows[li]['end_s'])
            for s in seams:
                spans[f'seam_{s["after_part"]}_before'] = (max(0.0, s['at_s'] - 20), s['at_s'])
                spans[f'seam_{s["after_part"]}_after'] = (s['at_s'], s['at_s'] + 20)
            wav = joined if joined is not None else av.concat_audio(files, Path(tmpdir) / 'narration.wav')
            delivery = av.delivery(f'video-{n:02d} narration', wav, all_words, spans=spans, segments=all_segments)
            line_stats = {int(k[5:]): v for k, v in (delivery.get('spans') or {}).items() if k.startswith('line_')}
            delivery['spans'] = {k: v for k, v in (delivery.get('spans') or {}).items() if not k.startswith('line_')}
            # How each line ends and the next begins (the facts a held silence's transition is decided on), next to
            # this voice's usual endings.
            cad = av.line_cadence(wav, [{'index': li, 'start_s': rows[li]['start_s'], 'end_s': rows[li]['end_s'],
                                         'gap_span_s': rows[li].get('gap_span_s')} for li in order])
            for li, c in (cad.get('boundaries') or {}).items():
                if int(li) in rows:
                    rows[int(li)]['cadence'] = c
            cadence_usual = cad.get('usual') or {}
            for b in read_json(vd / 'beat-map.json').get('beats') or []:
                k = str(b.get('id'))
                if k in (delivery.get('spans') or {}):
                    delivery['spans'][k]['intended'] = {x: b.get(x) for x in ('experience', 'narration_direction', 'pace')}
            for s in seams:
                bf = (delivery.get('spans') or {}).get(f'seam_{s["after_part"]}_before') or {}
                af = (delivery.get('spans') or {}).get(f'seam_{s["after_part"]}_after') or {}
                s['level_db_before'], s['level_db_after'] = bf.get('speech_level_db'), af.get('speech_level_db')
                s['pitch_range_before'], s['pitch_range_after'] = bf.get('pitch_range_st'), af.get('pitch_range_st')
            delivery['references'] = {v: (read_json(ref_av_path(rd, v)).get('summary') or {}).get('narration')
                                      for v in lock.get('reference_ids') or [] if ref_av_path(rd, v).is_file()}
            delivery['parts'] = [p['id'] for p in per_part]
            delivery['measured_at'] = now()
            write_json(folder / 'delivery.json', delivery)
        except (RuntimeError, ValueError, OSError, ImportError, KeyError) as exc:
            delivery_error = f'{type(exc).__name__}: {str(exc)[:200]}'
    shutil.rmtree(tmpdir, ignore_errors=True)
    # Each cue as it came out on this take (05): the silence a pause cue left beyond the voice's usual gap, the time a
    # delivery cue added to its own line against this voice's pace, how that line ended, and whether the next line
    # carried the change on (spill). Kept with the voice setup and the take, so takes can be compared.
    setup = {'voice_id': manifest.get('voice_id'), 'model_id': manifest.get('model_id'),
             'settings': manifest.get('voice_settings') or {}}
    def _extra(li):
        r = rows.get(li)
        if not r or r.get('start_s') is None or r.get('end_s') is None or not forecast_wpm:
            return None
        w = count_words(lines[li - 1].get('text') or '')
        return round((r['end_s'] - r['start_s']) - w * 60 / forecast_wpm, 2) if w else None
    tagged_lines = {t['li'] for t in tag_rows}
    usual_line = {}
    for key in ('speech_level_db', 'speech_rate_wpm', 'pitch_range_st'):
        vals = [v.get(key) for k, v in line_stats.items() if k not in tagged_lines and v.get(key) is not None]
        if vals:
            usual_line[key] = statistics.median(vals)
    cue_obs, cue_outcomes = [], []
    for t in tag_rows:
        li, r = t['li'], rows.get(t['li']) or {}
        m = next((x for x in measured_tags if x['line'] == t['line'] and x['tag'] == t['tag']), None)
        nxt = rows.get(li + 1) or {}
        if t.get('category') == 'pause':
            gli = li if t['at_end'] else li - 1 if t['at_start'] else None
            held = lines[gli - 1] if gli and 0 < gli <= len(lines) else {}
            planned = held.get('pause_total_s') if held.get('pause_via') == 'tag' else None
            outcome = pause_cue_outcome(planned, m['gap_s'] if m else None) or \
                {'outcome': 'performed', 'measured_s': m['gap_s'] if m else None,
                 'note': 'no whole silence planned through this cue: what it gave is decided at the holds'}
            outcome['silence_after'] = str(rows[gli]['id']) if gli in rows else None
        else:
            outcome = delivery_cue_outcome(t['inner'], line_stats.get(li), usual_line) if line_stats else \
                {'outcome': 'not_measured', 'note': 'delivery not measured (--no-delivery)'}
        cue_outcomes.append({'line': t['line'], 'tag': t['tag'], **outcome})
        cue_obs.append({'tag': t['tag'], 'category': t.get('category'), 'line': t['line'],
                        'at': 'start' if t['at_start'] else 'end' if t['at_end'] else 'inside',
                        'excess_s': m['excess_s'] if m else None, 'gap_s': m['gap_s'] if m else None,
                        'line_extra_s': _extra(li), 'end_level_db': (r.get('cadence') or {}).get('end_level_db'),
                        'next_line_extra_s': _extra(li + 1),
                        'next_end_level_db': (nxt.get('cadence') or {}).get('end_level_db'),
                        'usual_end_level_db': cadence_usual.get('end_level_db') if cadence_usual else None,
                        'outcome': cue_outcomes[-1].get('outcome'),
                        'take': prints.get(r.get('part')), **setup, 'measured_at': now()})
    # The joins: did the recording boundary change the delivery where the story goes on (not at a chapter turn)?
    chapter_first = set()
    for b in read_json(vd / 'beat-map.json').get('beats') or []:
        try:
            if b.get('chapter_start'):
                chapter_first.add(int(b['line_start']))
        except (KeyError, TypeError, ValueError):
            pass
    by_id = {str(rows[li]['id']): li for li in order}
    for sm in seams:
        li_last = by_id.get(str(sm['after_line']))
        sm['chapter_break'] = (li_last + 1) in chapter_first if li_last else False
        sm['boundary_effects'] = seam_boundary_effects((rows.get(li_last) or {}).get('cadence') or {}, cadence_usual)
    for r in rows.values():
        # each comparable token's [start, end] on the narration (None where Whisper did not hear it): the captions'
        # word times
        r['word_times'] = [None if x is None else [round(x[0], 3), round(x[1], 3)] for x in (r.pop('_tok', None) or [])]
    gaps_now = voice_gap_profile({'lines': list(rows.values())})
    out = {'video': n, 'complete': complete, 'script_sha256': script_hash(lines) if complete else None,
           'narration_file': str(folder / 'narration.wav') if complete else None, 'parts': per_part,
           'duration_s': round(tot_dur, 2), 'words': int(tot_words), 'speech_s': round(tot_speech, 2), 'wpm': wpm,
           'script_words': script_words, 'forecast_wpm': forecast_wpm, 'overall_wpm': overall_wpm,
           'natural_line_gap_median_s': round(natural_gap, 3), 'per_line_overhead_s': per_line,
           'line_gaps_from_audio': gaps_now, 'line_gaps_error': gap_error, 'cadence_usual': cadence_usual,
           'alignment_match_ratio': round(ratio_all, 3), 'tags_measured': measured_tags,
           'cue_observations': cue_obs, 'cue_outcomes': cue_outcomes, 'unheard_lines': unheard, 'rechecked_lines': rechecks,
           'tags_read_aloud': read_aloud, 'missing_runs': missing_runs,
           'pace_signals': pace_signals(beat_rows, read_json(vd / 'beat-map.json').get('beats') or [],
                                        [rows[li] for li in order], pace_context(rd, n)),
           'possible_repeats': repeats, 'seams': seams, 'beats': beat_rows, 'pronunciation_heard': pron_heard,
           'pause_profile': profile, 'lines': [rows[li] for li in order], 'measured_at': now(),
           'method': 'transcribe() + wpm_from_transcript_raw on each part, exactly as on the references; lines '
                     'aligned on comparable tokens (numbers as digits), a missed line re-heard on its own window'}
    write_json(folder / 'line-times.json', out)
    own, legacy = voice_lock(rd, n)
    vl_path = voice_lock_path(rd, n) if (own and not legacy) else rd / '60-voice' / 'voice-lock.json'
    vl = read_json(vl_path)
    settings = manifest.get('voice_settings') or {}
    recs = part_records_of(manifest)
    setups = {json.dumps([(recs.get(str(c['id'])) or {}).get(k) for k in ('voice_id', 'model_id', 'settings')],
                         sort_keys=True) for c in use}
    wrote, note = False, None
    if tot_words < CALIBRATION_MIN_WORDS:
        note = 'Under 300 words measured: too short to calibrate (short samples read fast and scatter).'
    elif len(setups) > 1:
        note = 'The measured parts were recorded with different voice setups: nothing written to the voice lock.'
    elif vl.get('voice_id') != manifest.get('voice_id') or (vl.get('settings') or {}) != settings or \
            (vl.get('model_id') or 'eleven_v4') != manifest.get('model_id'):
        note = 'The narration was recorded with another voice, model or settings than the voice lock: not written there.'
    else:
        prev = vl.get('measured') or {}
        same = (prev.get('voice_id') == manifest['voice_id'] and prev.get('model_id') == manifest['model_id']
                and (prev.get('settings') or {}) == settings)
        tag_costs = dict(prev.get('tag_costs_s') or {}) if same else {}
        tag_costs.update(costs)
        keep = {(o.get('tag'), o.get('line'), o.get('take')) for o in cue_obs}
        observations = ([o for o in prev.get('cue_observations') or []
                         if (o.get('tag'), o.get('line'), o.get('take')) not in keep] if same else []) + cue_obs
        vl['measured'] = {'voice_id': manifest['voice_id'], 'model_id': manifest['model_id'], 'settings': settings,
                          'wpm': wpm, 'words': int(tot_words), 'script_words': script_words,
                          'forecast_wpm': forecast_wpm, 'overall_wpm': overall_wpm, 'speech_s': round(tot_speech, 2),
                          'duration_s': round(tot_dur, 2), 'lines': nlines, 'per_line_overhead_s': per_line,
                          'natural_gap_s': gaps_now.get('median_s') or round(natural_gap, 3),
                          'tag_costs_s': tag_costs, 'cue_observations': observations[-120:],
                          'parts': [p['id'] for p in per_part], 'measured_at': now(),
                          'method': out['method']}
        for k in ('measured_wpm', 'measured_overhead_s', 'measured_overhead_lines', 'measured_wpm_source'):
            vl.pop(k, None)
        write_json(vl_path, vl)
        wrote = True
    warnings = []
    for sm in seams:
        if sm.get('boundary_effects') and not sm.get('chapter_break'):
            warnings.append(f"part join after {sm['after_line']} at {_mmss(sm['at_s'])} (not a chapter turn): "
                            + '; '.join(sm['boundary_effects'])
                            + '. Listen there; if the narrator concludes or restarts mid-scene, re-record with the '
                              'parts split at chapter turns (beat-map chapter_start).')
    if ratio_all < 0.9:
        warnings.append('Under 90% of the script words were matched: listen for missing or extra words, or a script edit.')
    for m in measured_tags:
        if classify_tag(m['tag'][1:-1]).get('category') == 'pause' and m['excess_s'] < 0.2:
            warnings.append(f"{m['line']} {m['tag']} made no measurable pause ({m['gap_s']} s against the usual "
                            f"{m.get('usual_gap_s', round(natural_gap, 2))} s, {m.get('basis', 'word times')}): listen "
                            "(was it read aloud?)")
    for c in cue_outcomes:
        if c.get('outcome') in ('short', 'long'):
            warnings.append(f"{c['line']} {c['tag']}: the pause came out {c['outcome']} ({c['measured_s']} s against "
                            f"{c['planned_s']} s planned, tolerance {c['tolerance_s']} s): decide it at the holds")
        elif c.get('outcome') in ('opposite', 'no_clear_change'):
            warnings.append(f"{c['line']} {c['tag']}: the line did not move as the cue asked ({c['outcome']}): listen")
    for r in repeats:
        warnings.append(f'possible repeated words at {_mmss(r["at_s"])}: "{r["heard"]}" (listen)')
    for s in seams:
        if s.get('repeated_words'):
            warnings.append(f'words heard on both sides of the join after part {s["after_part"]}: listen at {_mmss(s["at_s"])}')
        if s.get('level_step_lu') is not None and abs(float(s['level_step_lu'])) >= JOIN_LEVEL_STEP_LU:
            warnings.append(f'the voice steps {float(s["level_step_lu"]):+g} LU across the join after part {s["after_part"]} '
                            f'({_mmss(s["at_s"])}): listen (the recording is never edited; re-recording a part is the '
                            'user\'s call)')
    issues = [f'narration_line_not_heard:{x}' for x in unheard] + \
             [f'narration_tag_read_aloud:{t["line"]}:{t["tag"]}' for t in read_aloud] + \
             [f'narration_words_missing:{m["line"]}:{m["words"]}' for m in missing_runs]
    emit({'ok': not issues, 'issues': issues, 'line_times': str(folder / 'line-times.json'), 'complete': complete,
          'wpm': wpm, 'forecast_wpm': forecast_wpm, 'overall_wpm': overall_wpm, 'words': int(tot_words),
          'script_words': script_words, 'duration_s': round(tot_dur, 2), 'per_line_overhead_s': per_line,
          'natural_line_gap_median_s': round(natural_gap, 3), 'tags_measured': measured_tags, 'cue_outcomes': cue_outcomes,
          'line_gaps_from_audio': gaps_now, 'line_gaps_error': gap_error, 'cadence_usual': cadence_usual,
          'unheard_lines': unheard, 'rechecked_lines': rechecks, 'tags_read_aloud': read_aloud, 'seams': seams,
          'beats': beat_rows, 'pronunciation_heard': pron_heard, 'pause_profile': profile,
          'references': {v: {'wpm': (lock.get('per_ref_wpm') or {}).get(v), **p}
                         for v, p in ref_pause_profiles(rd, lock.get('reference_ids') or []).items()},
          'alignment_match_ratio': round(ratio_all, 3), 'voice_lock_updated': wrote, 'note': note,
          'warnings': warnings,
          'delivery': ({'file': str(folder / 'delivery.json'), 'summary': delivery.get('summary'),
                        'references': delivery.get('references'),
                        'reading': 'Pitch range and movement, loudness contrast and rate across the narration, per '
                                   'beat and on each side of every join: a beat asked to lift that measures flat is '
                                   'rewritten in the parts not yet recorded (10-creative-direction.md), never fixed in '
                                   'the audio. A calm, intimate narrator measures narrower than an energetic one: '
                                   'compare with what each beat asked for, not with a target.'}
                       if delivery else {'error': delivery_error} if delivery_error else None),
          'next': ('Listen where flagged; a line still not heard is re-recorded (tts --rerecord-parts N --reason) or '
                   'confirmed by the user (--confirm Lnnn --reason). ' if issues else '') +
                  'plan-check (real_forecast_s against the export window); holds (each planned pause next to the gap '
                  'the voice really left there) and hold-decide for every pause whose lines are recorded; when '
                  'complete: retime-shots.'},
         0 if not issues else 2)


def cmd_pace_profile(args):
    """Pace and pauses of the references (and, when measured, this video's narration) with one yardstick."""
    rd, st = run_folder(args)
    refs = normalize_refs(args.refs)
    lock = read_json(video_dir(rd, args.video) / 'length-lock.json') if args.video else {}
    if not refs:
        refs = lock.get('reference_ids') or []
    if not refs:
        error('Give --refs V001,V002, or --video NN to use that video\'s locked references.')
    out = {}
    inv = cards_inventory(rd)
    for vid in refs:
        tfile = rd / '10-media' / vid / 'transcript.txt'
        wpm = wpm_from_transcript_raw(tfile.read_text(encoding='utf-8', errors='replace')) if tfile.exists() else None
        out[vid] = {'wpm': wpm, **ref_pace_stats(rd, vid, (inv.get(vid) or {}).get('duration_s')),
                    **(ref_pause_profiles(rd, [vid]).get(vid) or {})}
    narr = None
    if args.video:
        lt = read_json(rd / '50-audio' / f'video-{int(args.video):02d}' / 'line-times.json')
        if lt:
            sc = read_json(video_dir(rd, args.video) / 'script.json').get('lines') or []
            narr = {'wpm': lt.get('wpm'), 'overall_wpm': lt.get('overall_wpm'), 'complete': lt.get('complete'),
                    **sentence_cadence([r.get('text') or '' for r in sc]), **(lt.get('pause_profile') or {}),
                    'beats': lt.get('beats')}
    emit({'ok': True, 'references': out, 'narration': narr, 'definitions': PACE_DEFINITIONS,
          'note': 'wpm / active_wpm = words over Whisper\'s speech time; overall_wpm = words over the whole span, '
                  'pauses included; pauses = silence between consecutive words (Whisper word timestamps). The same '
                  'functions for references and narration. A different pace is a fact to read, never a fault: a '
                  'slower narrator is not a duller one.'})


def _narration_source(rd, video, tmpdir):
    """The recorded narration as one file on line-times' clock: narration.wav once it is complete, else the recorded
    parts joined in order (as narration-measure joins them)."""
    n = int(video)
    folder = rd / '50-audio' / f'video-{n:02d}'
    if (folder / 'narration.wav').is_file() and read_json(folder / 'line-times.json').get('complete'):
        return folder / 'narration.wav'
    chunks = read_json(folder / 'manifest.json').get('chunks') or []
    files = [folder / c['file'] for c in sorted(chunks, key=lambda x: x['id']) if (folder / c['file']).is_file()]
    if not files:
        error('No recorded narration to preview.')
    return _av().concat_audio(files, Path(tmpdir) / 'narration.wav')


def hold_previews(rd, video, lines, lid, totals, intos='clean', outs='clean'):
    """Short local previews of one held silence at several whole lengths (the voice's own gap among them) and, when
    asked, several transitions (intos/outs: 'clean,fade'): the words around it, the silence, and, once the stills
    exist, the shot(s) on screen as the edit would cut them. A transition that cannot be done here is listed with why,
    not rendered. For the user's ears and the director's comparison; a preview shows a still without CapCut's moves,
    captions or music."""
    n = int(video)
    index = {str(r.get('id') or f'L{i + 1:03d}'): i + 1 for i, r in enumerate(lines)}
    if lid not in index:
        error('--preview names a line the script does not have.', lid)
    i = index[lid]
    lt, current, _ = line_times_state(rd, n)
    if not current:
        error('line-times.json does not describe the recorded parts: run narration-measure first.')
    rows = {int(r['index']): r for r in lt.get('lines') or []}
    g = measured_gap(rows, i, len(lines))
    if not g or g['natural_gap_s'] is None:
        error('A preview needs this line and the next recorded and measured.', lid)
    natural = float(g['natural_gap_s'])
    r = rows[i]
    span = g.get('span_s') if g.get('basis') == 'audio' else None
    at = (g.get('insert_at_s') if g.get('insert_at_s') is not None else (span[0] + span[1]) / 2) if span else \
        (r['end_s'] + (rows[i + 1]['start_s'] if i + 1 in rows else r['end_s'])) / 2
    last = i == len(lines)
    prev_r, next_r = rows.get(i - 1) or r, rows.get(i + 1)
    start = max(0.0, max(prev_r['start_s'], r['end_s'] - 15.0) - 0.3)
    end = (min(next_r['end_s'], (next_r['start_s'] or 0) + 10.0) + 0.4) if next_r else None
    wanted = sorted({round(float(x), 2) for x in str(totals or '').replace(';', ',').split(',') if x.strip()})
    if any(x <= 0 for x in wanted):
        error('--totals are whole silences in seconds, each above 0.')
    pick = lambda s, allowed: [x for x in dict.fromkeys(y.strip() for y in str(s or 'clean').split(',') if y.strip())
                               if x in allowed] or ['clean']
    intos, outs = pick(intos, TRANSITION_INTO), pick(outs, TRANSITION_OUT)
    variants, refused = [('voice-gap', natural, 0.0, 'clean', 'clean')], []
    for x in wanted:
        add = round(max(0.0, x - natural), 3)
        for ti in intos:
            for to in outs:
                if (ti, to) != ('clean', 'clean'):
                    _, problems = fade_windows(g, ti, to, last_line=last)
                    if add <= 0:
                        problems = ['nothing is added at this length: a fade would change the voice\'s own gap'] + problems
                    if problems:
                        refused.append({'variant': f'total-{x:.2f}s into-{ti} out-of-{to}', 'why': problems})
                        continue
                name = f'total-{x:.2f}s' + ('' if (ti, to) == ('clean', 'clean') else f'-into-{ti}-out-of-{to}')
                variants.append((name, x, add, ti, to))
    out_dir = rd / '70-edit' / f'video-{n:02d}' / 'hold-previews' / lid
    out_dir.mkdir(parents=True, exist_ok=True)
    shot = hold_shot(rd, n, i)
    made = []
    with tempfile.TemporaryDirectory() as tmp:
        src = _narration_source(rd, n, tmp)
        dur = probe(src)['duration_s']
        end = dur if end is None or last else min(end, dur)
        at = dur if last else at
        for label, total, add, ti, to in variants:
            wav = out_dir / f'{label}.wav'
            fades, _ = fade_windows(g, ti, to, last_line=last)
            fa = (f",afade=t=out:st={fades['into'][0] - start:.3f}:d={fades['into'][1] - fades['into'][0]:.3f}"
                  if fades.get('into') else '')
            fb = f",afade=t=in:st=0:d={fades['out_of'][1] - fades['out_of'][0]:.3f}" if fades.get('out_of') else ''
            filt = [f'[0:a]atrim=start={start:.3f}:end={at:.3f},asetpts=PTS-STARTPTS{fa}[a]',
                    f'anullsrc=r=44100:cl=stereo,atrim=duration={max(add, 0.001):.3f}[s]']
            labels = '[a][s]'
            if at < end - 0.01:
                filt.append(f'[0:a]atrim=start={at:.3f}:end={end:.3f},asetpts=PTS-STARTPTS{fb}[b]')
                labels += '[b]'
            filt.append(f'{labels}concat=n={len(labels) // 3}:v=0:a=1,aresample=44100[out]')
            run_cmd(['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', '-i', str(src), '-filter_complex',
                     ';'.join(filt), '-map', '[out]', '-ac', '2', '-c:a', 'pcm_s16le', str(wav)])
            item = {'variant': label, 'whole_silence_s': round(natural + add, 2), 'added_s': add, 'audio': str(wav),
                    'silence_centre_s': round((at - start) + add / 2, 3), 'into': ti, 'out_of': to}
            stills = []
            if shot and shot.get('still'):
                cut = (at - start) + add                  # the hold stays on the shot before the cut
                if shot.get('next_shot', {}).get('still'):
                    stills = [(shot['still'], cut), (shot['next_shot']['still'], max(0.1, (end - start) + add - cut))]
                else:
                    stills = [(shot['still'], (end - start) + add)]
            if stills:
                mp4 = out_dir / f'{label}.mp4'
                cmd = ['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y']
                for path, d in stills:
                    cmd += ['-loop', '1', '-t', f'{d:.3f}', '-i', str(path)]
                cmd += ['-i', str(wav), '-filter_complex',
                        ''.join(f'[{k}:v]scale=960:540:force_original_aspect_ratio=decrease,pad=960:540:(ow-iw)/2:(oh-ih)/2,'
                                f'setsar=1,fps=30[v{k}];' for k in range(len(stills))) +
                        ''.join(f'[v{k}]' for k in range(len(stills))) + f'concat=n={len(stills)}:v=1:a=0[v]',
                        '-map', '[v]', '-map', f'{len(stills)}:a', '-c:v', 'libx264', '-pix_fmt', 'yuv420p',
                        '-c:a', 'aac', '-b:a', '160k', '-shortest', str(mp4)]
                run_cmd(cmd)
                item['video'] = str(mp4)
            made.append(item)
    words_before = strip_tags(lines[i - 1].get('text') or '')
    words_after = strip_tags(lines[i].get('text') or '') if i < len(lines) else '(the end of the narration)'
    guide = [f'# Held silence after {lid}: listening previews', '',
             f'Before: "{words_before}"', f'After: "{words_after}"', '',
             f'The voice\'s own gap here: {natural:.2f} s ({g.get("basis")}). Each file is the same moment with a '
             'different whole silence after the line (and, where named, a different transition); nothing else differs.',
             '']
    guide += [f'- {m["variant"]}: about {m["whole_silence_s"]:.2f} s of silence'
              + ('' if (m['into'], m['out_of']) == ('clean', 'clean') else f', into {m["into"]}, out of {m["out_of"]}')
              + f' -> {m.get("video") or m["audio"]}' for m in made]
    if refused:
        guide += ['', 'Not rendered (they could not be done here without touching the voice, or would change nothing):']
        guide += [f'- {x["variant"]}: ' + '; '.join(x['why']) for x in refused]
    guide += ['', 'Listen for: does the line land, or does the silence wait for nothing? Does the voice stop the way '
              'the moment wants (a clean stop can be the point)? Does the next line come back in naturally, or too '
              'late? Would you want the voice to go on sooner?',
              'Previews show the still only: no camera moves, captions, transitions or music.' if shot and shot.get('still')
              else 'Audio only: the picture and the music for this moment do not exist yet.']
    (out_dir / 'index.md').write_text('\n'.join(guide) + '\n', encoding='utf-8')
    return {'line': lid, 'natural_gap_s': natural, 'gap_basis': g.get('basis'), 'folder': str(out_dir),
            'guide': str(out_dir / 'index.md'), 'variants': made, 'refused': refused,
            'inside_silence': {k: g.get(k) for k in ('insert_at_s', 'subrun_s', 'floor_under_speech_db', 'other_material_s')},
            'picture': bool(shot and shot.get('still')),
            'limits': 'A preview is the recorded voice with the silence set as named, over the shot\'s still when it '
                      'exists: no camera moves, captions, transitions or music. No agent here can hear it; the '
                      'user\'s ears decide what it sounds like.'}


def cmd_holds(args):
    """Every planned pause next to what the recorded voice really did there (gathers; free): the proposal, the gap the
    voice left after that line (from the audio), this voice's own range of gaps, the words around it, the shot on
    screen and its still once they exist, and the decision in force. With --preview LINE --totals a,b: short local
    previews of that moment at each whole silence, the voice's own gap among them. Nothing is decided here."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    lines = read_json(vd / 'script.json', required=True).get('lines') or []
    hf = hold_facts(rd, n, lines)
    for h in hf['holds']:
        if h.get('index'):
            sh = hold_shot(rd, n, h['index'])
            if sh:
                h['on_screen'] = sh
    plan = read_json(artifact_path(rd, n, 'edit'))
    out = {'ok': True, 'video': n, 'holds': hf['holds'], 'voice_gaps': hf['voice_gaps'],
           'endings_usual': hf['endings_usual'],
           'line_times_current': hf['line_times_current'], 'added_s': hf['added_s'],
           'undecided': hf['undecided'], 'decided_after_narration': hf['decided_narration'],
           'decided_with_picture': hf['decided_picture'],
           'edit_plan_timed_from_these_decisions': (plan.get('hold_decisions_sha256') == hold_decisions_sha(rd, n))
           if plan else None,
           'reading': 'A planned pause is a proposal. For each: does the voice\'s own gap here already give the moment '
                      'what it needs? What does the viewer see and hear while it lasts, and would they wait, or want '
                      'the voice to go on? Decide the WHOLE silence (or no hold) with hold-decide; the edit adds only '
                      'the difference with the measured gap. No quota, no formula, no length copied from a reference. '
                      'The transition: `ending` says how the line lands (the pitch of its last clear vowel against the '
                      'line, falling below zero; how long and how soft its end is after that vowel, where a creaky '
                      'landing shows; its punctuation) and how the next line starts again (its reset and lead-in), '
                      'next to this voice\'s usual (`endings_usual`). A landed line takes a silence as meant; one left '
                      'hanging (level or rising, little softening) can make a long silence sound like a dropout or a '
                      'wait for a laugh. Clean is the default; a fade is possible only on audible room tone '
                      '(`inside_silence`); the bed is often the better lever. Numbers, never a verdict: listen.',
           'next': 'hold-decide --line Lnnn --stage narration (--total S | --no-hold) [--into clean|fade] '
                   '[--out-of clean|fade] [--bed continues|enters|stops|dips|swells|none] --reason "..." for every pause '
                   'whose line and the next are recorded; after the stills exist, again with --stage picture (--bed '
                   'required).'}
    if args.preview:
        out['preview'] = hold_previews(rd, n, lines, args.preview.strip(), args.totals, args.into, args.out_of)
    emit(out)


def cmd_hold_decide(args):
    """Decide one held silence on evidence: the WHOLE silence wanted after the line (--total, the voice's own gap
    included) or none (--no-hold), at a stage: 'narration' (the voice is recorded and measured there) or 'picture'
    (the shot on screen has its still). The edit adds only the difference with the gap the voice really left; a
    decision does not touch the reviewed script, and every earlier decision is kept in the file's history."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    lines = read_json(vd / 'script.json', required=True).get('lines') or []
    index = {str(r.get('id') or f'L{i + 1:03d}'): i + 1 for i, r in enumerate(lines)}
    lid = args.line.strip()
    if lid not in index:
        error('--line names a line the script does not have.', lid)
    if (args.total is None) == (not args.no_hold):
        error('Give the whole silence wanted after the line (--total S: the voice\'s own gap included) or --no-hold.')
    if args.total is not None and args.total <= 0:
        error('--total is the whole silence in seconds, above 0 (--no-hold for none).')
    if n_words(args.reason) < MIN_NOTE_WORDS:
        error('Say why this length serves this moment (--reason): what the viewer takes in, what the picture and the '
              'sound do, why not shorter or longer.')
    i = index[lid]
    lt, current, prints = line_times_state(rd, n)
    if not current:
        error('line-times.json does not describe the recorded parts: run narration-measure on them first.')
    rows = {int(r['index']): r for r in lt.get('lines') or []}
    g = measured_gap(rows, i, len(lines))
    if not g or g['natural_gap_s'] is None:
        error('The silence after this line exists only once this line and the next are recorded and measured '
              '(narration-measure): decide it then.', lid)
    natural = float(g['natural_gap_s'])
    total = None if args.no_hold else round(float(args.total), 3)
    added = 0.0 if total is None else round(max(0.0, total - natural), 3)
    # The transition: kept clean unless this moment asks otherwise, and a fade only where it can work on the voice's
    # own quiet without touching the voice (fade_windows), and only into or out of silence that is really added.
    into, out_of, bed = args.into, args.out_of, (args.bed or None)
    if args.stage == 'picture' and not bed:
        error('With the picture, say what the bed does around this silence (--bed continues|enters|stops|dips|swells|'
              'none): the transition is the picture, the voice and the sound together.')
    fades, problems = fade_windows(g, into, out_of, last_line=(i == len(lines)))
    if (into == 'fade' or out_of == 'fade') and added <= 0:
        problems.insert(0, 'nothing is added here: a fade would change the voice\'s own natural gap, not a held silence')
    if problems:
        error('That transition cannot be done here without touching the voice or without changing nothing at all.',
              {'line': lid, 'into': into, 'out_of': out_of, 'problems': problems,
               'measured': {k: g.get(k) for k in ('natural_gap_s', 'subrun_s', 'insert_at_s', 'floor_under_speech_db')}})
    p = {x['line']: x for x in script_pause_plan(lines)[0]}.get(lid)
    rec = {'line': lid, 'index': i, 'beat': _line_beats(vd).get(i), 'stage': args.stage, 'total_s': total,
           'no_hold': total is None, 'natural_gap_s': natural, 'gap_basis': g.get('basis'),
           'gap_span_s': g.get('span_s'), 'added_s': added, 'resulting_gap_s': round(natural + added, 3),
           'outcome': ('no added silence: the voice\'s own gap' if total is None else
                       'the voice\'s own gap already gives it: nothing added' if added == 0 else
                       f'adds {added:g} s to the voice\'s {natural:g} s'),
           'reason': args.reason.strip(), 'listened': (args.listened or '').strip() or None, 'decided_at': now(),
           'parts': {k: prints.get(int(k)) for k in (g.get('parts') or {}) if k.isdigit()},
           'proposal': ({k: p[k] for k in ('form', 'seconds', 'via', 'purpose', 'picture', 'sound')} if p else None),
           'voice_gaps': voice_gap_profile(lt),
           'transition': {'into': into, 'out_of': out_of, 'bed': bed, 'fades_on_narration_clock': fades},
           'ending': {'punctuation': line_ending_mark(lines[i - 1].get('text')), **(g.get('cadence') or {})},
           'endings_usual': lt.get('cadence_usual') or {},
           'inside_silence': {k: g.get(k) for k in ('insert_at_s', 'subrun_s', 'floor_under_speech_db',
                                                    'other_material_s')}}
    if args.stage == 'picture':
        sh = hold_shot(rd, n, i)
        if not sh or not sh.get('still'):
            error('The picture stage decides with the picture: the shot on screen during this silence has no still yet.',
                  {'line': lid, 'shot': sh})
        rec['picture'] = sh
    pv = rd / '70-edit' / f'video-{n:02d}' / 'hold-previews' / lid
    if pv.is_dir():
        rec['previews'] = sorted(str(x) for x in pv.iterdir() if x.suffix in ('.wav', '.mp4'))
    data = read_json(holds_path(rd, n))
    decisions, history = data.get('decisions') or {}, data.get('history') or []
    before = decisions.get(lid)
    if before:
        history.append({**before, 'superseded_at': now()})
    decisions[lid] = rec
    write_json(holds_path(rd, n), {'video': n, 'decisions': decisions, 'history': history,
                                   'how': 'hold-decide: the whole silence after a line (the voice\'s own gap included) '
                                          'or none, decided after the narration and again with the picture; the edit '
                                          'adds only the difference with the measured gap (retime-shots).'})
    plan = read_json(artifact_path(rd, n, 'edit'))
    emit({'ok': True, 'decision': rec, 'replaced': before,
          'next': ('retime-shots: the edit plan was timed from other decisions. ' if plan and
                   plan.get('hold_decisions_sha256') != hold_decisions_sha(rd, n) else '') +
                  ('The picture stage confirms it with the shot on screen once the stills exist (--stage picture).'
                   if args.stage == 'narration' else 'Rebuild the CapCut project from the new edit plan if it changed.')})


def word_cut_s(row, text, start_word, language='en'):
    """Where a shot that starts at word `start_word` of a line cuts in (1-based, the line's words as the captions show
    them), on the narration's own clock: in the middle of the pause before that word when there is one (0.06 s or
    more), else 0.03 s before the word. None when the line has no such word or no times."""
    cap = _captions()
    gap0 = (row.get('gap_span_s') or [None])[0]
    end = max(row.get('end_s'), gap0) if gap0 is not None and row.get('end_s') is not None else row.get('end_s')
    if row.get('start_s') is None or end is None:
        return None
    ws, prob = cap.line_words(text or '', row.get('word_times'), (row.get('start_s'), end), tokens_of, strip_tags,
                              language, line_token_map)
    try:
        k = int(start_word)
    except (TypeError, ValueError):
        return None
    if prob or not 2 <= k <= len(ws) or ws[k - 1]['s'] is None or ws[k - 2]['e'] is None:
        return None
    w, before = ws[k - 1], ws[k - 2]
    gap = w['s'] - before['e']
    cut = (before['e'] + w['s']) / 2 if gap >= 0.06 else max(before['e'], w['s'] - 0.03)
    return {'cut_s': round(cut, 3), 'word': w['w'], 'word_timing': w['timing'], 'pause_before_s': round(max(gap, 0.0), 3),
            'basis': 'whisper', 'prev_word_span_s': [before['s'], before['e']], 'word_span_s': [w['s'], w['e']]}


def cmd_retime_shots(args):
    """Time every shot to the real narration: each cut falls in the silence between the last line of one shot
    and the first line of the next. Only DECIDED holds are inserted (hold-decide: a planned pause is a proposal until
    the voice is measured): each adds the difference between the whole silence decided and the gap the voice really
    left there (measured in narration.wav itself), placed in the middle of that silence so no word is touched, and
    belongs to the shot before it. The result is verified in narration-edit.wav with the same measure, and refused when
    the silence is what brings the edit up to the length. Rewrites shot-plan.json's start_s/end_s (the planned values
    kept once as planned_*), writes 70-edit/video-NN/edit-plan.json and, whenever there are holds, the narration with its
    holds (50-audio/video-NN/narration-edit.wav) -- the audio file the CapCut project uses."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    lock = read_json(vd / 'length-lock.json', required=True)
    script = read_json(vd / 'script.json', required=True)
    lines = script.get('lines') or []
    folder = rd / '50-audio' / f'video-{n:02d}'
    lt = read_json(folder / 'line-times.json', required=True)
    if not lt.get('complete') or lt.get('script_sha256') != script_hash(lines):
        error('line-times.json does not describe the whole current script: run narration-measure on the finished narration.')
    gate = audio_facts(rd, n)
    blocking = [x for x in gate['issues'] if not x.startswith('narration_plus_edit_holds')
                and x != 'narration_duration_outside_locked_tolerance']
    if blocking:
        error('The narration is not complete and matching the script yet.', blocking)
    shots_gate = shot_facts(rd, n)
    if shots_gate['issues']:
        error('The shot plan is not a complete visual argument yet (shot-check): every shot needs its beat and what '
              'NEW thing its picture gives the viewer, and every beat a picture.', shots_gate['issues'])
    dgate, dlock, _ = direction_gate(rd, n)
    dgate += list(stale_files(rd, n, ('beat-map',)).values())
    if dgate:
        error('The edit is timed and directed from the locked creative direction and its current beat map.', dgate)
    beat_dir = {str(b.get('id')): {k: b.get(k) for k in ('experience', 'visual_intent', 'sound_direction', 'pace')}
                for b in read_json(vd / 'beat-map.json').get('beats') or []}
    plan_path = rd / '60-visuals' / f'video-{n:02d}' / 'shot-plan.json'
    plan = read_json(plan_path, required=True)
    shots = plan.get('shots') or []
    index = {str(r.get('id')): i + 1 for i, r in enumerate(lines)}
    times = {r['index']: r for r in lt['lines']}
    dur = gate['duration_s']
    # Every planned pause is decided against the recorded voice before the edit is timed: its length was a proposal
    # written before any voice existed. Nothing is inserted from a pre-recording estimate.
    hf = hold_facts(rd, n, lines)
    if hf['undecided']:
        error('Every planned pause is decided against the recorded voice before the edit is timed (its length was a '
              'proposal): read `holds`, preview where it helps, then hold-decide each one (--stage narration).',
              {'undecided': hf['undecided'], 'stale': [h['line'] for h in hf['holds'] if h['status'] == 'stale']})
    decided = [h for h in hf['holds'] if h['status'].startswith('decided_')]
    nar = folder / 'narration.wav'
    gmap, av = {}, None
    if decided:
        av = _av()
        gmap = {int(x['index']): x for x in av.line_gaps(nar, [{'index': r['index'], 'start_s': r['start_s'],
                                                                'end_s': r['end_s']} for r in lt['lines']],
                                                       last_index=len(lines))['gaps']}
    holds, pauses, notes = [], [], []
    for h in decided:
        i, d = h['index'], h['decision']
        g = gmap.get(i) or {}
        natural = float(g['gap_s']) if g.get('gap_s') is not None else float(d.get('natural_gap_s') or 0)
        total_s = d.get('total_s')
        added = 0.0 if total_s is None else round(max(0.0, float(total_s) - natural), 3)
        if g.get('basis') == 'audio' and g.get('span_s'):
            # Inside the voice's own silence, in the middle of its longest quiet stretch: the end of the line (its
            # decay, a release) stays with that line, a breath before the next line stays with the next line.
            at = dur if i == len(lines) else (g['insert_at_s'] if g.get('insert_at_s') is not None else
                                              (g['span_s'][0] + g['span_s'][1]) / 2)
        else:
            at = (times[i]['end_s'] + times[i + 1]['start_s']) / 2 if i < len(lines) else dur
            notes.append(f'{h["line"]}: no clear silence found in the audio after it; the hold sits at Whisper\'s '
                         'boundary: listen there')
        if d.get('natural_gap_s') is not None and abs(float(d['natural_gap_s']) - natural) > 0.1:
            notes.append(f'{h["line"]}: the gap measured in narration.wav ({natural:.2f} s) differs from the one the '
                         f'decision read ({float(d["natural_gap_s"]):.2f} s); the decided whole silence is kept')
        tr = d.get('transition') or {}
        into, out_of = tr.get('into') or 'clean', tr.get('out_of') or 'clean'
        fades, problems = fade_windows({**g, 'insert_at_s': at}, into, out_of, last_line=(i == len(lines)))
        if problems or ((into == 'fade' or out_of == 'fade') and added <= 0):
            error(f'{h["line"]}: the decided transition no longer fits the narration as measured now: decide it again '
                  '(hold-decide).', {'into': into, 'out_of': out_of, 'problems': problems or ['nothing is added here']})
        span = g.get('span_s') or [times[i]['end_s'], times[i + 1]['start_s'] if i < len(lines) else dur]
        rec = {'after_line': h['line'], 'index': i, 'at_audio_s': round(at, 3), 'hold_s': added, 'kind': 'script',
               'purpose': (h.get('proposal') or {}).get('purpose') or d.get('reason'), 'total_s': total_s,
               'natural_gap_s': round(natural, 3), 'gap_basis': g.get('basis') or d.get('gap_basis'),
               'stage': d.get('stage'), 'decided_at': d.get('decided_at'),
               'expected_gap_s': round(natural + added, 3),
               'transition': {'into': into, 'out_of': out_of, 'bed': tr.get('bed'), 'fades': fades},
               '_span': [float(span[0]), float(span[1])],
               '_next_start': float(times[i + 1]['start_s']) if i < len(lines) else None}
        pauses.append(rec)
        if added > 0:
            holds.append(rec)
    # A join between recorded parts that came out shorter than the voice's own gap between lines (narration-measure)
    # gets back exactly the missing fraction of a second: continuity, never padding (capped at the natural gap). A join
    # whose line carries a decided pause gets none: that silence was decided as a whole.
    held_lines = {h['line'] for h in hf['holds']}
    seam_s = 0.0
    if not args.no_seam_holds:
        for s in lt.get('seams') or []:
            if float(s.get('seam_hold_s') or 0) > 0 and s.get('after_line') not in held_lines:
                holds.append({'after_line': s.get('after_line'), 'at_audio_s': round(float(s['at_s']), 3),
                              'hold_s': round(float(s['seam_hold_s']), 2), 'kind': 'seam',
                              'purpose': 'restores the voice\'s natural gap at the join between two recorded parts'})
                seam_s += round(float(s['seam_hold_s']), 2)
    holds.sort(key=lambda h: h['at_audio_s'])
    total = round(dur + sum(h['hold_s'] for h in holds), 3)
    # Where each decided pause sits on the edit's own clock: the silence from the end of the line to the next line
    # (the voice's gap plus what was added), so the bed's move (enters, stops, dips...) is placed on it exactly.
    for p in pauses:
        before = sum(h['hold_s'] for h in holds if h['at_audio_s'] < p['at_audio_s'] - 1e-6)
        own = p['hold_s']
        sp, ns = p.pop('_span'), p.pop('_next_start')
        p['times_in_edit'] = {'silence_from_s': round(sp[0] + before, 3), 'silence_to_s': round(sp[1] + before + own, 3),
                              'next_line_s': round(ns + before + own, 3) if ns is not None else None}
    # The length is reached by the narration, never by the silence added to it.
    tol0 = max(4, lock['target_length_s'] * lock.get('tolerance_export_pct', .025))
    win_lo = lock['target_length_s'] - tol0
    held_s = round(sum(h['hold_s'] for h in holds if h['kind'] == 'script'), 3)
    if dur + seam_s < win_lo <= total:
        error('The edit reaches the locked length only with the held silence: the narration ends '
              f'{win_lo - dur - seam_s:.1f} s short of the export window. The answer is the story (more substance in '
              'the parts to re-record, or an authorised length revision), never longer silences.',
              {'narration_s': dur, 'held_silence_s': held_s, 'export_window_from_s': round(win_lo, 2)})
    ranges, cursor, cut_in = [], 0, {}
    lt_rows = {int(r['index']): r for r in lt.get('lines') or []}
    language = lock.get('language') or script.get('language') or 'en'
    for k, s in enumerate(shots):
        a, b = index.get(str(s.get('line_start'))), index.get(str(s.get('line_end')))
        sw = s.get('start_word')
        if a is None or b is None or a != (cursor if sw is not None else cursor + 1) or b < a:
            error(f'Shot {s.get("id")} does not start on the line after the previous shot ends (or, with start_word, '
                  'inside the line it ends on).',
                  {'line_start': s.get('line_start'), 'line_end': s.get('line_end'), 'previous_end': cursor})
        if sw is not None:
            # the cut goes in on a word inside the line the previous shot ends on (04)
            prev_sw = shots[k - 1].get('start_word') if ranges and ranges[-1][0] == a else None
            c = word_cut_s(lt_rows.get(a) or {}, lines[a - 1].get('text') or '', sw, language)
            if c is None or (prev_sw is not None and int(sw) <= int(prev_sw)):
                error(f'Shot {s.get("id")}: start_word {sw} is not a timed word of {s.get("line_start")} after the '
                      'previous shot starts.', {'start_word': sw, 'previous_start_word': prev_sw})
            cut_in[k] = c
        ranges.append((a, b))
        cursor = b
    if cut_in and av is not None:
        # Whisper often stretches a word over the pause after it: the pause before each cut word is measured in the
        # audio itself (the same quiet-run measure as the silences between lines), and the cut goes in its middle
        pairs = []
        for j, k in enumerate(sorted(cut_in)):
            c = cut_in[k]
            pairs += [{'index': 2 * j + 1, 'start_s': c['prev_word_span_s'][0], 'end_s': c['prev_word_span_s'][1]},
                      {'index': 2 * j + 2, 'start_s': c['word_span_s'][0], 'end_s': c['word_span_s'][1]}]
        measured = {int(g['index']): g for g in av.line_gaps(nar, pairs)['gaps']}
        for j, k in enumerate(sorted(cut_in)):
            g = measured.get(2 * j + 1) or {}
            if g.get('basis') == 'audio' and g.get('span_s') and g['span_s'][1] - g['span_s'][0] >= 0.1:
                cut_in[k].update({'cut_s': round((g['span_s'][0] + g['span_s'][1]) / 2, 3), 'basis': 'audio',
                                  'pause_before_s': round(g['span_s'][1] - g['span_s'][0], 3)})
    if cursor != len(lines):
        error('The shots do not cover every script line.', {'last_line_covered': cursor, 'lines': len(lines)})
    out_shots, start = [], 0.0
    hold_at = {int(h['index']): h['at_audio_s'] for h in pauses}
    for k, (s, (a, b)) in enumerate(zip(shots, ranges)):
        if k + 1 < len(shots) and k + 1 in cut_in:
            # the next shot starts on a word inside this shot's last line: the cut goes in there
            split = cut_in[k + 1]['cut_s']
            end = split + sum(h['hold_s'] for h in holds if h['at_audio_s'] <= split + 1e-6)
        elif k + 1 < len(shots):
            # The cut sits in the silence after the shot's last line: where its hold is, when it has one (the hold stays
            # on the shot before), else in the middle of the measured silence, else at Whisper's boundary.
            g = gmap.get(b) or {}
            split = (hold_at[b] if b in hold_at else
                     (g['span_s'][0] + g['span_s'][1]) / 2 if g.get('basis') == 'audio' and g.get('span_s') else
                     (times[b]['end_s'] + times[b + 1]['start_s']) / 2)
            end = split + sum(h['hold_s'] for h in holds if h['at_audio_s'] <= split + 1e-6)
        else:
            end = total
        s.setdefault('planned_start_s', s.get('start_s'))
        s.setdefault('planned_end_s', s.get('end_s'))
        s['start_s'], s['end_s'] = round(start, 2), round(end, 2)
        length = end - start
        if length < 2.0 or length > 45.0:
            notes.append(f"{s.get('id')} now lasts {length:.1f}s (planned "
                         f"{(s['planned_end_s'] or 0) - (s['planned_start_s'] or 0):.1f}s): check it still works")
        # Each shot carries its beat's direction: what the editor's move, transition and sound serve here (09, 05).
        out_shots.append({'id': s.get('id'), 'beat_id': s.get('beat_id'), 'start_s': s['start_s'],
                          'end_s': s['end_s'], 'duration_s': round(length, 2),
                          'direction': beat_dir.get(str(s.get('beat_id'))) or {},
                          **({'cut_in': cut_in[k]} if k in cut_in else {})})
        start = end
    beat_spans = {}
    for s in out_shots:
        b = str(s['beat_id'])
        lo, hi = beat_spans.get(b, (s['start_s'], s['end_s']))
        beat_spans[b] = (min(lo, s['start_s']), max(hi, s['end_s']))
    tol = max(4, lock['target_length_s'] * lock.get('tolerance_export_pct', .025))
    edit_audio = None
    if holds:      # the CapCut project uses the narration with its holds: always written when there are any
        src, outp = folder / 'narration.wav', folder / 'narration-edit.wav'
        filt, labels, prev = [], [], 0.0
        # A decided fade works on the stretch of the voice's own quiet next to its splice: out at the end of the
        # stretch before it, in at the start of the stretch after it. Nothing else in the narration is touched.
        seg_fx = [[] for _ in range(len(holds) + 1)]
        bounds = [0.0] + [h['at_audio_s'] for h in holds]
        for j, h in enumerate(holds):
            fz = (h.get('transition') or {}).get('fades') or {}
            if fz.get('into'):
                seg_fx[j].append(f"afade=t=out:st={fz['into'][0] - bounds[j]:.3f}:d={fz['into'][1] - fz['into'][0]:.3f}")
            if fz.get('out_of'):
                seg_fx[j + 1].append(f"afade=t=in:st=0:d={fz['out_of'][1] - fz['out_of'][0]:.3f}")
        fx = lambda k: ''.join(',' + x for x in seg_fx[k])
        for j, h in enumerate(holds):
            filt.append(f"[0:a]atrim=start={prev:.3f}:end={h['at_audio_s']:.3f},asetpts=PTS-STARTPTS{fx(j)}[a{j}]")
            filt.append(f"anullsrc=r=44100:cl=stereo,atrim=duration={h['hold_s']:.3f}[s{j}]")
            labels += [f'[a{j}]', f'[s{j}]']
            prev = h['at_audio_s']
        if prev < dur - 0.01:
            filt.append(f'[0:a]atrim=start={prev:.3f},asetpts=PTS-STARTPTS{fx(len(holds))}[tail]')
            labels.append('[tail]')
        filt.append(''.join(labels) + f'concat=n={len(labels)}:v=0:a=1[out]')
        run_cmd(['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', '-i', str(src),
                 '-filter_complex', ';'.join(filt), '-map', '[out]', '-ar', '44100', '-ac', '2',
                 '-c:a', 'pcm_s16le', str(outp)])
        edit_audio = {'file': str(outp), 'duration_s': probe(outp)['duration_s']}
        # The silences as they really are in the file the project will carry, read with the yardstick that decided
        # them: the voice's own gap plus what was added, at the place decided, and nothing added anywhere else.
        if abs(edit_audio['duration_s'] - total) > 0.05:
            error('narration-edit.wav is not the narration plus the decided holds: its length differs.',
                  {'expected_s': total, 'got_s': edit_audio['duration_s']})
        script_holds = [h for h in holds if h['kind'] == 'script']
        if script_holds:
            av = av or _av()
            centres, shift = {}, 0.0
            for h in holds:
                if h['kind'] == 'script':
                    centres[h['after_line']] = h['at_audio_s'] + shift + h['hold_s'] / 2
                shift += h['hold_s']
            runs = av.silences_at(outp, [centres[h['after_line']] for h in script_holds], search_s=0.1)
            wrong = []
            for h, run in zip(script_holds, runs):
                got = round(run[1] - run[0], 3) if run else None
                expect = h['expected_gap_s'] if h.get('gap_basis') == 'audio' else h['hold_s']
                h['resulting_gap_s'] = got
                if got is None or abs(got - expect) > HOLD_VERIFY_TOL_S:
                    wrong.append({'line': h['after_line'], 'expected_s': expect, 'measured_s': got})
            if wrong:
                error('The edit\'s narration does not carry the silences that were decided (measured in '
                      'narration-edit.wav): nothing was written to the shot plan or the edit plan.', wrong)
        # The voice itself is the recording, sample for sample, everywhere outside the added silences and the decided
        # fades: no word, release or breath was moved, cut, faded or resampled.
        av = av or _av()
        excluded = [w for h in holds for w in ((h.get('transition') or {}).get('fades') or {}).values() if w]
        changed = av.voice_unchanged(src, outp, [(h['at_audio_s'], h['hold_s']) for h in holds], excluded)
        if changed:
            error('narration-edit.wav differs from the recorded narration outside its added silences and decided '
                  'fades: nothing was written to the shot plan or the edit plan.', changed)
    plan['timed_to'] = {'narration': str(folder / 'narration.wav'), 'edit_duration_s': total, 'retimed_at': now()}
    write_json(plan_path, plan)
    # The one audio file the CapCut project must carry, at 0 s, at speed 1, untrimmed (timeline-check), and that the
    # export must contain (export-check): its fingerprint ties the cut to this exact approved narration.
    nf = Path(edit_audio['file']) if edit_audio else folder / 'narration.wav'
    narration_for_edit = {'file': str(nf), 'sha256': file_sha256(nf), 'duration_s': probe(nf)['duration_s'],
                          'parts': [p.get('id') for p in lt.get('parts') or []],
                          'part_fingerprints': {str(p.get('id')): p.get('fingerprint') for p in lt.get('parts') or []}}
    edit_plan = {'video': n, 'narration_file': str(folder / 'narration.wav'), 'narration_duration_s': dur,
                 'holds': holds, 'edit_duration_s': total, 'edit_narration': edit_audio,
                 'narration_for_edit': narration_for_edit,
                 'export_window_s': [round(lock['target_length_s'] - tol, 2), round(lock['target_length_s'] + tol, 2)],
                 'within_export_window': abs(total - lock['target_length_s']) <= tol,
                 # What the editor carries out (09): the locked treatment's picture, sound and pace, and each shot's
                 # beat direction below; the revision stamps which direction this edit plan follows.
                 'direction': {'treatment': dlock.get('treatment'), 'production_rev': dlock.get('production_rev', 1),
                               **{k: chosen_treatment_of(read_json(vd / 'direction.json')).get(k) for k in
                                  ('visual_language', 'sound', 'audiovisual_relationship', 'structure_and_pace')}},
                 'shot_structure_sha256': shot_structure_sha(shots), 'script_sha256': script_hash(lines),
                 # Every decided pause and what it became (added, or nothing: the voice's own gap), and the decisions
                 # this plan was timed from (timeline-check: a later decision means a new retime).
                 'pauses': pauses, 'hold_decisions_sha256': hold_decisions_sha(rd, n), 'voice_gaps': hf['voice_gaps'],
                 'beats': [{'id': b, 'start_s': round(a, 2), 'end_s': round(z, 2), **beat_dir.get(b, {})}
                           for b, (a, z) in beat_spans.items()],
                 'shots': out_shots, 'notes': notes, 'made_at': now()}
    write_json(rd / '70-edit' / f'video-{n:02d}' / 'edit-plan.json', edit_plan)
    emit({'ok': True, 'edit_plan': str(rd / '70-edit' / f'video-{n:02d}' / 'edit-plan.json'),
          'shot_plan': str(plan_path), 'shots': len(out_shots), 'edit_duration_s': total, 'holds': holds,
          'pauses': pauses, 'within_export_window': edit_plan['within_export_window'], 'edit_narration': edit_audio,
          'narration_for_edit': narration_for_edit, 'notes': notes,
          'next': 'Put narration_for_edit.file in the CapCut project at 0 s, speed 1, untrimmed; name the project in '
                  'timeline.json (capcut_draft) so timeline-check reads the narration from CapCut itself. With the '
                  'stills made, look at each held silence with its shot (holds --preview) and confirm or change it '
                  '(hold-decide --stage picture); a changed decision is retimed before the project is rebuilt.'})


def _av():
    """The audiovisual measurements (av_tools.py, next to this file): loaded only when a command needs them, so the
    rest of the pipeline never waits on numpy/OpenCV/librosa."""
    here = str(Path(__file__).resolve().parent)
    if here not in sys.path:
        sys.path.insert(0, here)
    import av_tools
    return av_tools


INSPECT_MAX_FRAMES = 400


def inspect_dir(rd, label, a, b, rate):
    tag = 'native' if rate == 'native' else f'{float(rate):g}fps'
    return rd / '20-analysis' / 'inspect' / label / f'{a:.2f}-{b:.2f}@{tag}'


def cmd_inspect_window(args):
    """A closer look at one brief stretch of a reference (--ref) or of any video (--file, e.g. an export): every
    frame (--native) or a higher rate, each at its own timestamp on the transcript's clock, with the words said
    there and one contact sheet. For what the run's samples cannot settle (an inspect_candidate, a fast cut, a
    possibly graphic moment, an uncertain continuity), never a whole video. --remove deletes that look's frames
    afterwards (disturbing material); its index.json stays as the record that the look was taken."""
    rd, st = run_folder(args)
    a, b = parse_clock(args.start), parse_clock(args.end)
    if a is None or b is None or b <= a:
        error('--from and --to must be times (mm:ss, h:mm:ss or seconds), --to after --from')
    row, tj = None, {}
    if args.ref:
        inv = read_json(rd / '00-inventory/references.json', required=True)
        row = next((x for x in inv.get('items') or [] if x.get('id') == args.ref.strip().upper()
                    and x.get('kind') == 'video'), None)
        if not row:
            error('No such reference video in this run', args.ref)
        src, label = Path(row['source_path']), row['id']
        tj = read_json(rd / '10-media' / label / 'transcript.json')
    elif args.file:
        src = Path(args.file).expanduser().resolve()
        if not src.is_file():
            error('File not found', str(src))
        row = probe(src)
        label = 'file-' + quick_fingerprint(src)[:12]
    else:
        error('Name a reference (--ref V###) or a video file (--file)')
    rate = 'native' if args.native else float(args.fps)
    if rate != 'native' and not args.remove and float(rate) <= run_analysis_fps(st):
        error(f'A closer look samples faster than the run\'s own frames ({run_analysis_fps(st):g} fps): give --fps '
              'above it, or --native for every frame.', {'fps': rate})
    out = inspect_dir(rd, label, a, b, rate)
    if args.remove:
        idx = read_json(out / 'index.json')
        if not idx:
            error('No such closer look to remove', str(out))
        gone = 0
        for f in list((out / 'frames').glob('*.jpg')) + ([out / 'sheet.jpg'] if (out / 'sheet.jpg').is_file() else []):
            f.unlink()
            gone += 1
        idx['frames_removed_at'] = now()
        write_json(out / 'index.json', idx)
        emit({'ok': True, 'removed_files': gone, 'record_kept': str(out / 'index.json')})
        return
    duration = row.get('duration_s')
    if duration and a >= float(duration):
        error('The window starts after the video ends', {'duration_s': duration})
    if rate != 'native' and not 0 < rate <= 60:
        error('--fps must be between 0 and 60')
    per_s = float(row.get('fps') or 30) if rate == 'native' else rate
    if (b - a) * per_s > INSPECT_MAX_FRAMES:
        error(f'A closer look is for a brief stretch: this one would be about {int((b - a) * per_s)} frames (at most '
              f'{INSPECT_MAX_FRAMES}). Narrow it or lower --fps; the video as a whole stays at the run\'s rate.')
    av = _av()
    frames, origin = av.sample_frames(src, out / 'frames', fps=1.0 if rate == 'native' else rate, width=args.width,
                                      start_s=a, end_s=b, native=rate == 'native')
    words = [w for w in transcript_words(tj) if a <= w['start_s'] <= b] if tj else []
    shown = 'every frame' if rate == 'native' else f'{rate:g} fps'
    sheet = av.window_sheet([(f['t_s'], out / 'frames' / f['file']) for f in frames], out / 'sheet.jpg',
                            f'{label}  {_mmss(a)}-{_mmss(b)}  {shown}: {len(frames)} frames', words)
    before = read_json(out / 'index.json')
    earlier = (before.get('earlier') or []) + ([{'why': before.get('why'), 'made_at': before.get('made_at')}]
                                               if before.get('made_at') else [])
    write_json(out / 'index.json', {'label': label, 'source': str(src), 'from_s': a, 'to_s': b, 'rate': rate,
                                    'width': args.width, 'why': args.why, 'earlier': earlier,
                                    'clock_origin_s': origin, 'frames': frames,
                                    'words': ' '.join(str(w.get('text') or '').strip() for w in words),
                                    'sheet': sheet, 'made_at': now()})
    emit({'ok': True, 'window': str(out), 'frames': len(frames), 'sheet': sheet,
          'first_s': frames[0]['t_s'] if frames else None, 'last_s': frames[-1]['t_s'] if frames else None,
          'note': 'Look at the sheet (and the frames themselves where a detail matters). After a look at disturbing '
                  'material, remove the frames (--remove): the record stays.'})


def _segments_of(tjson, offset=0.0):
    return [(float(s['start_s']) + offset, float(s['end_s']) + offset) for s in tjson.get('segments') or []
            if s.get('start_s') is not None and s.get('end_s') is not None]


def measure_file_delivery(audio_path, transcript_path):
    """How the voice in one short file moves (a voice preview, a probe): pitch range and word-to-word movement,
    loudness contrast and register, on the references' yardstick. A short sample is indicative only. Never raises:
    a measurement that can't be made comes back as {'error': ...}."""
    try:
        av = _av()
        import tempfile
        tj = read_json(transcript_path)
        with tempfile.TemporaryDirectory() as tmp:
            wav = av.extract_audio(audio_path, Path(tmp) / 'sample.wav')
            dv = av.delivery(Path(audio_path).stem, wav, transcript_words(tj), spans={'whole': (0.0, 1e9)},
                             segments=_segments_of(tj))
        whole = (dv.get('spans') or {}).get('whole') or {}
        out = {k: whole.get(k) for k in ('pitch_range_st', 'pitch_movement_st', 'loudness_contrast_db',
                                         'speech_rate_wpm')}
        out['register_hz'] = (dv.get('summary') or {}).get('register_hz')
        return out
    except (RuntimeError, ValueError, OSError, ImportError, KeyError, TypeError) as exc:
        return {'error': f'{type(exc).__name__}: {str(exc)[:120]}'}


def export_av_path(rd, video, fingerprint):
    return rd / '70-edit' / f'video-{int(video):02d}' / 'av' / f"export-{fingerprint.split(':')[0][:10]}.json"


def cmd_av_profile(args):
    """Measured evidence of how a video works over time (av_tools.py): the references (--refs), or this video's
    export (--video NN --file). Writes the measurements and one watch sheet per minute (frames every 5 s with the
    words spoken under them) for the agents to read like an editor scrubbing a timeline."""
    rd, st = run_folder(args)
    av = _av()
    import tempfile
    results = {}
    if args.refs:
        vids = cards_inventory(rd)
        for vid in normalize_refs(args.refs):
            row = vids.get(vid)
            if not row:
                error('Unknown reference ID (or a duplicate).', vid)
            media = rd / '10-media' / vid
            fi = read_json(media / 'frame-index.json')
            frames = [(f['t_s'] if f.get('t_s') is not None else f['approx_s'], media / 'sampled-frames' / f['file'])
                      for f in fi.get('frames') or []]
            if not frames:
                error('No sampled frames for this reference: run prepare first.', vid)
            tj = read_json(media / 'transcript.json')
            words = transcript_words(tj)
            target = ref_av_path(rd, vid)
            ffps = float(fi.get('fps') or run_analysis_fps(st))
            fsampler = str(fi.get('sampler') or LEGACY_SAMPLER)
            if abs(ffps - run_analysis_fps(st)) > 1e-9:
                results.setdefault('_notes', []).append(f'{vid}: its frames were sampled at {ffps:g} fps, the run '
                                                        f'analyses at {run_analysis_fps(st):g} fps: compare its cut '
                                                        'counts only with videos sampled at the same rate')
            sig = {'fingerprint': row.get('fingerprint'), 'frames': len(frames), 'fps': ffps, 'sampler': fsampler,
                   'words': len(words), 'method': av.METHOD_VERSION, 'sheets': not args.no_sheets}
            old = read_json(target)
            if old.get('signature') == sig and not args.force:
                results[vid] = {'file': str(target), 'cached': True, 'summary': old.get('summary')}
                continue
            with tempfile.TemporaryDirectory() as tmp:
                wav = None
                if row.get('has_audio') and words:
                    try:
                        wav = av.extract_audio(row['source_path'], Path(tmp) / 'audio.wav')
                    except RuntimeError as exc:
                        results.setdefault('_notes', []).append(f'{vid}: audio not measured ({str(exc)[:120]})')
                prof = av.profile(vid, row.get('duration_s') or frames[-1][0], frames, wav, words,
                                  sheets_dir=None if args.no_sheets else target.with_suffix(''),
                                  segments=_segments_of(tj), fps=ffps, sampler=fsampler)
            tfile = media / 'transcript.txt'
            if prof['summary'].get('narration') is not None:
                prof['summary']['narration']['wpm_pipeline'] = (wpm_from_transcript_raw(
                    tfile.read_text(encoding='utf-8', errors='replace')) if tfile.exists() else None)
                prof['summary']['narration']['pause_profile'] = pause_profile(words)
            prof.update({'signature': sig, 'source': {'id': vid, 'fingerprint': row.get('fingerprint')},
                         'made_at': now()})
            write_json(target, prof)
            results[vid] = {'file': str(target), 'sheets': len(prof['sheets']), 'summary': prof['summary']}
    elif args.video and args.file:
        n = int(args.video)
        f = Path(args.file).expanduser().resolve()
        if not f.is_file():
            error('Export file not found', str(f))
        fp = quick_fingerprint(f)
        target = export_av_path(rd, n, fp)
        target.parent.mkdir(parents=True, exist_ok=True)
        meta = probe(f)
        if args.transcript:
            tj = read_json(args.transcript, required=True)
        else:
            tpath = target.with_name(target.stem + '-whisper.json')
            if not (read_json(tpath).get('status') == 'transcribed'):
                transcribe(f, tpath, args.whisper_model, args.device, args.compute_type)
            tj = read_json(tpath)
        words = transcript_words(tj)
        with tempfile.TemporaryDirectory(dir=str(target.parent)) as tmp:
            frames = av.extract_frames(f, Path(tmp) / 'frames', fps=run_analysis_fps(st))
            wav = None
            if meta.get('has_audio'):
                try:
                    wav = av.extract_audio(f, Path(tmp) / 'audio.wav')
                except RuntimeError:
                    wav = None
            prof = av.profile(f'video-{n:02d}', meta['duration_s'], frames, wav, words,
                              sheets_dir=None if args.no_sheets else target.with_suffix(''),
                              segments=_segments_of(tj), fps=run_analysis_fps(st), sampler=av.SAMPLER)
            # every shot of our own export once, for the final reviewer: a short shot between two watch-sheet frames
            # is seen there (made now, while the export's frames exist)
            prof['shot_sheets'] = ([] if args.no_sheets or not prof.get('shots') else
                                   render_shot_sheets(av, frames, prof['shots'], target.with_suffix('') / 'shots',
                                                      f'video-{n:02d}')[1])
        for s in prof['shots']:
            s.pop('keyframe', None)            # the export's frames were temporary; the sheets keep the pictures
        lock = read_json(video_dir(rd, n) / 'length-lock.json')
        prof['references'] = {v: read_json(ref_av_path(rd, v)).get('summary') for v in lock.get('reference_ids') or []
                              if ref_av_path(rd, v).is_file()}
        prof.update({'source': {'file': str(f), 'fingerprint': fp}, 'made_at': now()})
        write_json(target, prof)
        results[f'video-{n:02d}'] = {'file': str(target), 'sheets': len(prof['sheets']),
                                     'shot_sheets': len(prof.get('shot_sheets') or []), 'summary': prof['summary'],
                                     'references': prof['references']}
    else:
        error('Give --refs V001,V002 (references), or --video NN --file export.mp4 (this video\'s export).')
    emit({'ok': True, 'profiles': results,
          'reading': 'Measurements, not verdicts: what the voice, the picture and the cut do over time. Open the '
                     'sheets in order to watch the video as a storyboard with its words; compare numbers only with '
                     'videos measured the same way (10-creative-direction.md).'})


def cmd_direction_lock(args):
    """Lock the creative direction (direction.json) before the script is written: it must be complete, and its
    treatments must have had their blind comparison read with every finding answered. A video whose script came
    first can be locked only with --late "reason" (recorded and shown at every plan-check). A later change needs
    --revise "what changed and why" (kept in the lock's history).

    Every lock knows which fields changed (direction_sections). A change that alters what production must do raises
    the production revision, and the artifacts that field feeds (FIELD_EFFECTS) must be updated or explicitly
    reapproved before the stages that use them continue. Anything that already existed before the first lock was made
    without a direction and is affected the same way. Evidence, alternatives, reasons and samples are harmless: same
    revision, nothing to redo. Refining the chosen treatment needs no new blind read (it is shown at every plan-check);
    a treatment that was never in one, or one rewritten past TREATMENT_REREAD_BELOW of the vocabulary its reader saw,
    gets its own blind read first."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    df = direction_facts(rd, n)
    if df['issues']:
        error('The creative direction is not complete yet.', df['issues'])
    if not read_json(vd / 'length-lock.json'):
        error('Lock the length before the direction: the story sets it (length --mode story takes the chosen '
              'treatment\'s own size), or the user\'s own choice does (length --mode standard, or own).',
              {'story_size': df.get('story_size')})
    lockp = vd / 'direction-lock.json'
    prev = read_json(lockp)
    if prev and prev.get('direction_sha256') == df['direction_sha256']:
        rc = research_changes(rd, n, prev)
        if rc and getattr(args, 'research_rechecked', ''):
            # a corrected source or claim, re-checked where it is used: recorded, and nothing in production follows
            if n_words(args.research_rechecked) < MIN_NOTE_WORDS:
                error('Say what was re-checked, where, and what it changed (a few words at least).')
            prev['research'] = research_hashes(rd, n)
            prev['history'] = (prev.get('history') or []) + [{'at': now(), 'research_rechecked': args.research_rechecked,
                                                              'changed': rc}]
            write_json(lockp, prev)
            emit({'ok': True, 'unchanged': True, 'research_rechecked': rc, 'lock': str(lockp),
                  'production_rev': prev.get('production_rev'),
                  'note': 'Recorded. Nothing is rebuilt for a correction; a researched value that changes is a revision '
                          'of direction.json (direction-lock --revise), which reaches only the beats that carry it.'})
            return
        emit({'ok': True, 'unchanged': True, 'lock': str(lockp), 'treatment': prev.get('treatment'),
              'production_rev': prev.get('production_rev'),
              **({'research_changed': rc, 'next': research_note(rc)} if rc else {})})
        return
    d = read_json(vd / 'direction.json')
    trs = {str(t.get('id')): t for t in d.get('treatments') or [] if isinstance(t, dict)}
    chosen = str(df['chosen_treatment'])
    tr = review_state(vd, 'treatment', df['treatments_sha256'])
    if not tr['issues']:      # the latest blind read saw exactly these treatments
        reviewed = {k: treatment_text(v) for k, v in trs.items()}
    elif not prev:
        error('The treatments need their blind comparison read (review-packet --kind treatment), recorded, and '
              'every finding answered before the direction is locked.', tr['issues'])
    else:
        unsettled = [x for x in tr['issues'] if x != 'treatment_review_outdated']
        if unsettled:
            error('The latest blind read of the treatments is not settled yet: answer every finding first.', unsettled)
        reviewed = dict(prev.get('reviewed_treatments') or {})
        seen = reviewed.get(chosen)
        if seen is None:
            error('The chosen treatment was never in a blind comparison read: run review-packet --kind treatment for '
                  'the current treatments first.', {'chosen': chosen, 'compared': sorted(reviewed)})
        share = _jaccard(_content_tokens(seen), _content_tokens(treatment_text(trs.get(chosen))))
        if share < TREATMENT_REREAD_BELOW:
            error(f'The chosen treatment has been rewritten since its blind read: {share:.0%} of its vocabulary is '
                  'still what the reader saw. A rewrite this large is a new treatment: give the current treatments '
                  'their own blind read (review-packet --kind treatment), answer it, then lock again.',
                  {'treatment': chosen, 'still_the_same': round(share, 2), 'needs_at_least': TREATMENT_REREAD_BELOW})
    sections = direction_sections(d)
    script_exists = (vd / 'script.json').is_file()
    entry = {'locked_at': now(), 'direction_sha256': df['direction_sha256'],
             'treatments_sha256': df['treatments_sha256'], 'treatment': df['chosen_treatment'],
             'script_existed': script_exists, 'sections': sections, 'reviewed_treatments': reviewed,
             # the research the direction rests on, as it is now; a later correction is re-checked where it is used
             'research': (research_hashes(rd, n) if not prev or not isinstance(prev.get('research'), dict)
                          or getattr(args, 'research_rechecked', '') else prev['research'])}
    if not prev:
        if script_exists and not args.late:
            error('A script already exists: the creative direction is decided and locked BEFORE scriptwriting. For a '
                  'video whose script really came first, --late "reason" records that exception (shown at every '
                  'plan-check and in the release sheet).')
        # Whatever already exists was made without a direction: it is affected by this first one.
        required = {a: {'rev': 1, 'baseline': artifact_sha(rd, n, a)} for a in TRACKED_FILES if artifact_sha(rd, n, a)}
        required.update({m: {'rev': 1} for m in MEDIA_ARTIFACTS if media_present(rd, n, m)})
        hit = list(required)
        lock = {**entry, 'late_reason': args.late or None, 'history': [], 'production_rev': 1, 'required': required,
                'reapproved': {}, 'changed_sections': [], 'affects': hit, 'planning_rules': PLANNING_RULES}
    else:
        if not args.revise:
            error('The direction changed since it was locked. Re-lock with --revise "what changed and why".')
        old = prev.get('sections') or {}
        changed = sorted(k for k in set(old) | set(sections) if old.get(k) != sections.get(k))
        # what each change reaches: whole artifacts for most fields; for a researched value only the beats that carry
        # it, their lines and their shots (2026-11-24: no wholesale rebuild for a bounded change)
        whole = [a for a in ALL_ARTIFACTS if any(a in field_effects(k) for k in changed if not k.startswith(VALUE_KEY))]
        scope = value_change_scope(rd, n, [k[len(VALUE_KEY):] for k in changed if k.startswith(VALUE_KEY)])
        hit = [a for a in ALL_ARTIFACTS if a in whole or scope.get(a)]
        rev = prev.get('production_rev', 1)
        history = (prev.get('history') or []) + [{k: prev.get(k) for k in ('locked_at', 'direction_sha256', 'treatment',
                                                                          'production_rev')}
                                                 | {'revised_because': args.revise, 'changed_sections': changed,
                                                    **({'scoped': {a: sorted(p) for a, p in scope.items()
                                                                   if p and a not in whole}} if scope else {})}]
        lock = {**prev, **entry, 'history': history, 'changed_sections': changed, 'affects': hit}
        if hit:   # meaningful: a new revision, and each artifact it touches must follow it
            required = dict(prev.get('required') or {})
            waiting = stale_files(rd, n)          # what an earlier change still waits for (the lock on disk)
            for a in hit:
                old_req = required.get(a) or {}
                if a in whole or a not in scope:
                    required[a] = {'rev': rev + 1, **({'baseline': artifact_sha(rd, n, a)} if a in TRACKED_FILES else {})}
                elif a in waiting and 'baseline' in old_req:
                    continue          # the whole file still waits for an earlier change, which covers these parts
                else:
                    parts = dict(scope[a])
                    if a in waiting and isinstance(old_req.get('parts'), dict):
                        still = set(parts_still_waiting(rd, n, a, old_req['parts']))
                        parts = {**{p: sha for p, sha in old_req['parts'].items() if p in still}, **parts}
                    required[a] = {'rev': rev + 1, 'parts': parts}
            lock.update({'production_rev': rev + 1, 'required': required,
                         'reapproved': {k: v for k, v in (prev.get('reapproved') or {}).items() if k not in hit}})
            if int(prev.get('planning_rules') or 1) < PLANNING_RULES:
                # an older direction substantively revised: the current planning rules apply where this revision
                # reaches (its changed sections, the artifacts it sends back to work), advisory everywhere else
                mig = dict(prev.get('planning_migration') or {})
                lock['planning_migration'] = {
                    'to': PLANNING_RULES,
                    'sections': sorted(set(mig.get('sections') or []) | set(changed)),
                    'artifacts': sorted(set(mig.get('artifacts') or []) | set(hit)),
                    'history': (mig.get('history') or []) + [{'at': now(), 'revised_because': args.revise,
                                                              'sections': changed, 'artifacts': hit}]}
    write_json(lockp, lock)
    outdated = outdated_artifacts(rd, n)
    emit({'ok': True, 'lock': str(lockp), 'treatment': lock['treatment'], 'late': bool(lock.get('late_reason')),
          'production_rev': lock['production_rev'], 'changed_sections': lock.get('changed_sections'),
          'affects': hit, 'outdated_now': outdated,
          'next': ('Update or explicitly reapprove (direction-reapprove --artifact NAME --reason "...") each outdated '
                   'artifact before the stage that uses it continues.' if outdated else
                   'Beat directions and the script are written from this treatment (03, 10).')})


def cmd_direction_reapprove(args):
    """Explicit reapproval after a meaningful direction change: the director has looked and this artifact, as it is,
    still serves the locked treatment. Recorded with its reason, for this revision only, and shown at every check and
    in the release sheet. A file artifact is approved in its current content (changing it later is an update);
    stills, music or the edit plan are approved as a set for this revision (also how pictures made outside the gated
    workers, e.g. supplied by the user, are accepted)."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    lockp = vd / 'direction-lock.json'
    lock = read_json(lockp)
    if not lock:
        error('No direction lock yet: there is nothing to reapprove against.')
    if n_words(args.reason) < MIN_NOTE_WORDS:
        error('Say why this artifact still serves the locked treatment (a real reason, a few words at least).')
    rev = required_rev(lock, args.artifact) or lock.get('production_rev', 1)
    entry = {'rev': rev, 'at': now(), 'reason': args.reason}
    if args.artifact in TRACKED_FILES:
        if args.artifact not in stale_files(rd, n, (args.artifact,)):
            emit({'ok': True, 'unchanged': True, 'note': f'{args.artifact} is not outdated: nothing to reapprove.'})
            return
        entry['sha256'] = artifact_sha(rd, n, args.artifact)
    lock.setdefault('reapproved', {})[args.artifact] = entry
    write_json(lockp, lock)
    emit({'ok': True, 'artifact': args.artifact, 'for_revision': rev, 'still_outdated': outdated_artifacts(rd, n)})


def cmd_media_check(args):
    """The same check the generation workers run before they make anything (media_gate), on a job file by hand."""
    job = read_json(args.job, required=True)
    res = media_gate(job, args.kind)
    emit({k: v for k, v in res.items() if k != 'records'} | {'items': len(res['records'])}, 0 if res['ok'] else 2)


HOUSE_RULES = ('House rules the video must keep (never suggest breaking them; flag any line or picture that comes '
               'close): no holiday, religious or superstitious scene used as a story device; nothing gory (no blood, '
               'wounds, bodies or injuries shown, or described in their physical detail; saying plainly that people '
               'were hurt or died is fine); no extreme distress; no swearing; nothing indecent; every person an adult.')


def house_rules(rd, video):
    """HOUSE_RULES, plus the themes this video's reference material was cut for (its content reviews)."""
    themes = excluded_themes(rd, video)
    out = HOUSE_RULES
    gone = [th for th in themes if th.get('label') != 'restricted_theme']
    shown = [th for th in themes if th.get('label') == 'restricted_theme']
    if gone:
        out += (' Parts of the reference material were left out on purpose; nothing in this video may bring them back, '
                'in other words or other pictures either: ' +
                '; '.join(f'{th["what"]} ({"a content-safety exclusion" if th["kind"] == "safety" else "a creative exclusion"})'
                          for th in gone) + '.')
    if shown:
        out += (' These may be told, but never shown or described in their graphic form: ' +
                '; '.join(f'{th["what"]} (never shown: {", ".join(th["avoid"])})' for th in shown) + '.')
    return out

SCRIPT_BRIEF = """# Cold read: {TITLE}

You are a first-time viewer, not an editor. Below is the complete narration of a long-form YouTube video
(about {MINUTES} minutes, narrated over illustrated stills). You get only the title, the words and the silences the
writer intends, on purpose: no plan, no rationale, no earlier reader's view. Read nothing else and do not change any
file except the one you are asked to write.

Read it all the way through as someone who clicked the title. Be honest, specific and fair: say what works as
plainly as what does not. Refer to the line ids exactly as they appear below.

You are reading, not hearing. Words in [square brackets] are delivery directions the narrator will be given; they are
never spoken. Judge the personality and tone the writing implies, and the delivery the directions ask for, as
intentions: never say how the voice sounds or whether a direction works, which only the recording can show.
"(silence after this line: about N s in all)" is the whole silence the writer intends there, a proposal not yet fitted
to a recording. A pause direction next to such a silence (at the end of the line, or at the start of the next one) is
part of that same wait and never free: judge the whole wait as written, and notice where silences and pause
directions follow one another.

Think about:
1. What the video promised, and whether it delivered.
2. When you first got what the opening made you want (the experience, the answer or the result you came for), and
   what came before it: which stretches gave you something on the way (a discovery, tension, a laugh, an
   explanation that clicked, a reason to care) and which only made you wait for it. A long build is fine when it
   rewards you, and a slow, quiet passage can be exactly right: say so. Write this in "promise". Note there too the
   first line by which you knew what this video was going to give you ("clear_at"): the point where you could have
   told a friend what it is and why to watch it.
3. Would you have watched to the end? If not: the line where you would have stopped, and what would have kept you.
   If so: the weakest stretch you sat through, and what carried you past it. (What you would do, not a score.)
4. Where your attention dropped, and why: facts with no consequence for anyone, the same point made again, a list
   read aloud, a sentence pattern repeating, textbook register, explaining what you had already felt, exposition
   before you cared, background you were given before you knew why it mattered. Roughly how long each stretch felt.
   Did the length feel earned, or did any part feel like filling?
5. Following it by ear, the first time: who or what each thing is when it matters (a person and what they want, a
   place, a term, a part of a machine); what has happened and what is happening now; why each new fact matters. Where did you have to stop and work something out? Where
   did a line lean on something you were never told, or told so long before that you had lost it (at the moments
   that matter most, did you still have the name, place or fact they rest on)? Where did too many new names, numbers
   or places arrive at once? Where was something deliberately held back, and did that feel like a promise (you
   wanted to know) or like being lost? Complexity you enjoyed is not a problem: say so.
6. Where the narration suggests a cause, a prediction, a link or a certainty that its own words do not support
   (two things connected by place or theme told as if one caused or foresaw the other).
7. What feels formulaic: devices used so often they stop working (count them).
8. The strongest passages, and why they work.
9. The narrator the writing implies: personality, warmth, wit or emotion where the material invites it; or a reader
   of facts; or someone straining for drama.
10. Lines hard to follow by ear: number pile-ups, very long sentences, tangled grammar, jargon.
11. The ending: does it land and answer what the opening promised; is anything after the payoff too long or too short.
12. The intended delivery and silences: which directions serve their moment and which push the narration into
   theatre or decoration. For each intended silence: does it feel needed, or does it delay what you want to know
   next? Would you become impatient? Does it help the joke, the reveal or the feeling, or would the line land as well
   going straight on? Would it make the narrator sound unnaturally slow? Would a first-time viewer understand why it
   is there? A silence you would cut or shorten is a finding.
13. The developments that matter most in this video, up to six, in order: whatever its reward is (an event, a
   turn, a discovery, an explanation that clicks, a joke's payoff, a solution, a feeling). Keep three judgements apart
   for each, because they fail separately: what happened (could you retell it?); why it matters within this video (in
   your own words, using ONLY what the narration told you: if you know why from your own knowledge and the words never
   gave it, say so, because a first-time viewer may not know it); and whether it paid off for you. Not every video
   needs danger, a conflict or a twist: name the reward this one offers. Something held back on purpose that you want
   to learn later is not a failure: mark it "withheld".
   For each, also: what would have been different if it had not happened, or had failed, and for whom, in one plain
   sentence from the narration alone ("would_be_different"; "I could not tell" is an answer); and when the narration let
   you know why it matters: before the moment, at the moment, only afterwards, or never ("learned_when"). That something
   worked, failed or surprised someone is what happened: follow the consequence one step further, to what it changes
   and for whom. Judge as a first-time viewer who knows nothing of the subject beyond these words, and who may be
   watching in a language that is not their first: a reason carried only by an idiom, a technical word or a verdict
   given after the fact may not reach them.

Then list your findings, the most important first, each concrete enough to act on: what you noticed, what you think
causes it (likely_cause: for example "a name nobody introduced", "no consequence for anyone", "the same point again",
"too much at once", "waiting too long for the payoff"), and what it does to a viewer. Severity "major": a viewer would
likely stop watching, lose the thread or stop trusting the video there (a long sag, a confusing stretch, a
contradiction, a broken or unearned ending). "minor": polish. Report every major problem, however many there are;
group small polish points together rather than leave out anything serious.

Do not invent facts. If a fix needs a new fact, write "needs a sourced detail".

Write your answer as JSON, and nothing else, to: {OUT}
{{
  "reviewer": "fresh cold reader",
  "verdict": {{"promise": "...", "delivered": "...", "watched_to_end": "yes | no",
              "would_stop_at": "<the line id where you would have stopped, or none>", "why": "..."}},
  "promise": {{"promised": "what the opening made you want, in your words",
              "clear_at": "the first line by which you knew what this video would give you, or never",
              "first_delivered": "the line where you first got it, or never",
              "waiting": [{{"lines": "{EX_RANGE}", "felt": "anticipation | delay",
                           "why": "what this stretch gave you on the way, or why it only made you wait"}}]}},
  "strongest": [{{"lines": "{EX_RANGE}", "why": "..."}}],
  "developments": [{{"lines": "{EX_RANGE}", "what_happened": "...", "why_it_matters": "... (or: I could not tell)",
                    "would_be_different": "...", "learned_when": "before | at the moment | only afterwards | never",
                    "why_from": "the video | my own knowledge | unclear", "event": "clear | partly | unclear",
                    "significance": "clear | partly | unclear | withheld",
                    "reward": "landed | partly | missed | not the point here", "note": "..."}}],
  "findings": [{{"id": "F1", "severity": "major or minor", "lines": ["{EX_LINE}"], "problem": "...",
                 "likely_cause": "...", "viewer_impact": "...", "suggestion": "..."}}]
}}
Line ids: only ids that appear below, one id or a range such as "{EX_RANGE}" ("lines" may list several:
["L003", "{EX_RANGE}"]). "waiting" lists the stretches before the first delivery, each felt one way or the other
(it may be empty when nothing made you wait).

## The narration
"""

