def opening_path(vd):
    return vd / 'opening.json'


def opening_candidates(doc):
    return [c for c in (doc or {}).get('candidates') or [] if isinstance(c, dict)]


def opening_sha(doc):
    """The openings as a reader saw them: their words and pictures. A read counts for exactly these."""
    return canonical_sha([{k: c.get(k) for k in ('id', 'narration', 'picture')} for c in opening_candidates(doc)])


def opening_shelf(doc, direction):
    """The shelf of the opening contest: our own packagings (opening.json shelf.ours [{id, title, thumbnail}], else the
    working promise chosen with the subject) and the titles they would sit beside (shelf.others, else the titles the
    outward look found: selection.coverage.exists[].title). ([ours], [others])."""
    sh = doc.get('shelf') if isinstance((doc or {}).get('shelf'), dict) else {}

    def entry(x):
        if isinstance(x, dict):
            return {'title': str(x.get('title') or '').strip(),
                    'thumbnail': str(x.get('thumbnail') or x.get('thumbnail_idea') or '').strip()}
        return {'title': str(x or '').strip(), 'thumbnail': ''}
    ours = []
    for i, x in enumerate(sh.get('ours') or [], 1):
        e = entry(x)
        if n_words(e['title']) >= 2:
            ours.append({'id': str((x.get('id') if isinstance(x, dict) else '') or f'P{i}').strip(), **e})
    if not ours:
        sp = selection_promise(direction)
        if n_words(sp.get('working_title')) >= 2:
            ours = [{'id': 'P1', 'title': str(sp['working_title']).strip(),
                     'thumbnail': str(sp.get('thumbnail_idea') or '').strip()}]
    others = [entry(x) for x in sh.get('others') or []]
    if not any(n_words(o['title']) >= 2 for o in others):
        subj = (direction or {}).get('subject')
        sel = subj.get('selection') if isinstance(subj, dict) and isinstance(subj.get('selection'), dict) else {}
        cov = sel.get('coverage') if isinstance(sel.get('coverage'), dict) else {}
        others = [entry({'title': x.get('title')}) for x in cov.get('exists') or [] if isinstance(x, dict)]
    seen, out = {o['title'].lower() for o in ours}, []
    for o in others:
        if n_words(o['title']) >= 2 and o['title'].lower() not in seen:
            seen.add(o['title'].lower())
            out.append(o)
    return ours, out


def opening_issues(doc):
    """The contest's entries (opening.json): two to four openings written from the same material, each as the words
    heard and what is seen, with the way in it takes. Presence and shape only. (issues, warnings)."""
    cands = opening_candidates(doc)
    ids = [str(c.get('id') or '').strip() for c in cands]
    if not 2 <= len(cands) <= 4 or len(set(ids)) != len(ids) or '' in ids:
        return ['opening_contest_needs_2_to_4_openings_with_distinct_ids:candidates[{id,way_in,narration,picture}]'], []
    out, warn = [], []
    for c in cands:
        cid = c.get('id')
        if n_words(strip_tags(c.get('narration') or '')) < MIN_SAMPLE_WORDS:
            out.append(f'opening_contest_{cid}_narration_under_{MIN_SAMPLE_WORDS}_words')
        if n_words(c.get('picture')) < MIN_PICTURE_WORDS:
            out.append(f'opening_contest_{cid}_picture_missing')
        if n_words(c.get('way_in')) < 3:
            out.append(f'opening_contest_{cid}_needs_its_way_in:what_this_opening_starts_from_and_why')
    for i in range(len(cands)):
        for j in range(i + 1, len(cands)):
            sim = _jaccard(_content_tokens(cands[i].get('narration') or ''), _content_tokens(cands[j].get('narration') or ''))
            if sim >= 0.6:
                warn.append(f'openings {ids[i]} and {ids[j]} share {sim:.0%} of their vocabulary: are they two ways '
                            'into the film, or one way in reworded?')
    return out, warn


def opening_reads(vd, sha):
    """The recorded reads of exactly these openings, oldest first."""
    return [r for r, _a in review_records(vd, 'opening') if r.get('subject_sha256') == sha]


def opening_summary(reads, cands, ours):
    """What the fresh readers said of the openings, side by side, for the director's decision: who would keep watching
    which, what each opening made them want, where it lost them; and where our own titles stood on the shelf."""
    per = {str(c.get('id')): [] for c in cands}
    kept = {}
    for r in reads:
        rnd = r.get('_round') or r.get('round')
        kept.setdefault(str(r.get('keep_watching_id')), []).append(rnd)
        for cid, v in (r.get('openings') or {}).items():
            if cid in per and isinstance(v, dict):
                per[cid].append({'reader': rnd, **{k: v.get(k) for k in ('wants_to_know', 'slips_at', 'thinks_it_is',
                                                                         'like_every_other')}})
    shelf = {}
    for o in ours or []:
        rows = []
        for r in reads:
            sh = r.get('shelf') if isinstance(r.get('shelf'), dict) else {}
            entries = sh.get('entries') if isinstance(sh.get('entries'), dict) else {}
            num = next((k for k, e in entries.items() if isinstance(e, dict) and e.get('ours') == o['id']), None)
            if num is None:
                continue
            clicks = [str(x) for x in sh.get('would_click') or []]
            rows.append({'reader': r.get('_round') or r.get('round'),
                         'clicked': clicks.index(num) + 1 if num in clicks else None, 'among': len(entries),
                         'expects': (sh.get('expect') or {}).get(num),
                         'never': next((x.get('why') for x in sh.get('never') or []
                                        if isinstance(x, dict) and str(x.get('entry')) == num), None)})
        if rows:
            shelf[o['id']] = {'title': o['title'], 'readers': rows}
    return {'readers': len(reads), 'kept_watching': kept, 'openings': per, 'shelf': shelf}


def opening_state(rd, video, lines=None):
    """Where the opening contest stands (planning rules 6): the entries exist, fresh readers have read exactly these,
    and the director has decided with reasons; or one opening is the only one possible, and the file says why
    (single_opening_why). Facts beside it: who would keep watching which, whether the chosen one is a reader's pick,
    and how much of it the script's first lines still hold. {issues, warnings, facts}."""
    vd = video_dir(rd, video)
    doc = read_json(opening_path(vd))
    out = {'issues': [], 'warnings': [], 'facts': {}}
    iss, warn = out['issues'], out['warnings']
    cands = opening_candidates(doc)
    if not cands and n_words(doc.get('single_opening_why')) >= 2 * MIN_FIELD_WORDS:
        warn.append('one opening only, no contest: ' + str(doc['single_opening_why']).strip())
        out['facts'] = {'single_opening': True}
        return out
    if not cands:
        iss.append('opening_contest_missing:write_2_to_4_openings_from_the_same_material_and_let_fresh_readers_choose_'
                   '(opening.json,_opening-packet),_or_say_why_only_one_opening_is_possible_(single_opening_why)')
        return out
    c_iss, c_warn = opening_issues(doc)
    iss += c_iss
    warn += c_warn
    if c_iss:
        return out
    reads = opening_reads(vd, opening_sha(doc))
    if not reads:
        iss.append('opening_contest_not_read:opening-packet,_a_fresh_reader_for_each_packet,_then_opening-record')
        return out
    ours, _others = opening_shelf(doc, read_json(vd / 'direction.json'))
    summary = opening_summary(reads, cands, ours)
    ids = [str(c.get('id')) for c in cands]
    dec = doc.get('decision') if isinstance(doc.get('decision'), dict) else {}
    chosen = str(dec.get('opening') or '').strip()
    out['facts'] = {'readers': summary['readers'], 'kept_watching': summary['kept_watching'],
                    'chosen': chosen or None, 'shelf': summary['shelf'] or None}
    if chosen not in ids:
        iss.append('opening_contest_not_decided:opening.json_decision{opening,why,readers}')
        return out
    if n_words(dec.get('why')) < MIN_FIELD_WORDS:
        iss.append('opening_contest_decision_missing_why')
    if n_words(dec.get('readers')) < MIN_FIELD_WORDS:
        iss.append('opening_contest_decision_missing_readers:what_the_readers_said_and_what_was_done_with_it')
    if chosen not in summary['kept_watching']:
        warn.append(f'opening: the chosen opening {chosen} is not the one any reader would keep watching (they chose '
                    + ', '.join(sorted(summary['kept_watching'])) + '): the decision says why')
    if lines:
        # the script still opens the way that was read? (its first lines, over as many words as the chosen opening)
        ch = next(c for c in cands if str(c.get('id')) == chosen)
        want = _content_tokens(ch.get('narration') or '')
        size, head, got = n_words(strip_tags(ch.get('narration') or '')), [], 0
        for l in lines:
            head.append(str(l.get('text') or ''))
            got += count_words(l.get('text', ''))
            if got >= size:
                break
        share = len(want & _content_tokens(' '.join(head))) / len(want) if want else None
        out['facts']['script_keeps_chosen_opening'] = round(share, 2) if share is not None else None
        if share is not None and share < OPENING_KEPT_LOOK:
            warn.append(f'opening: {share:.0%} of the chosen opening\'s words are in the script\'s first {len(head)} '
                        'line(s). If the script now opens another way, that opening was never in front of a reader')
    return out


def cmd_opening_packet(args):
    """The opening contest: one blind packet per fresh reader. Each reader gets the same openings under its own random
    labels and order, its own stance (a newcomer, a regular of the kind, a distracted click), and the shelf of titles
    the film would sit beside, ours unmarked among them. Nothing of the plan, the direction or the director's hopes."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    doc = read_json(opening_path(vd))
    if not opening_candidates(doc):
        error('No openings to compare yet: write opening.json first.', {'file': str(opening_path(vd)),
                                                                        'shape': OPENING_SHAPE})
    c_iss, c_warn = opening_issues(doc)
    if c_iss:
        error('The openings are not ready to be read.', c_iss)
    if not read_json(vd / 'direction-lock.json'):
        error('Lock the creative direction first (direction-lock): the openings are ways into the film that was chosen.')
    d = read_json(vd / 'direction.json')
    cands = {str(c['id']): c for c in opening_candidates(doc)}
    ours, others = opening_shelf(doc, d)
    sha = opening_sha(doc)
    readers = max(1, min(int(args.readers or 2), len(OPENING_STANCES)))
    folder = vd / 'reviews'
    used = [int(m.group(1)) for p in (folder.glob('*opening-r*.json') if folder.is_dir() else [])
            for m in [re.search(r'opening-r(\d+)', p.name)] if m]
    last = max(used, default=0)
    made = []
    for k in range(1, readers + 1):
        rnd = last + k

        def mixed(key, rnd=rnd):
            return hashlib.sha256(f'{sha}:{rnd}:{key}'.encode('utf-8')).hexdigest()
        labels = {chr(65 + i): cid for i, cid in enumerate(sorted(cands, key=mixed))}
        shelf = sorted([{'ours': x['id'], 'title': x['title'], 'thumbnail': x['thumbnail']} for x in ours] +
                       [{'ours': None, 'title': x['title'], 'thumbnail': x['thumbnail']} for x in others],
                       key=lambda x: mixed(x['title']))
        entries = {str(i): x for i, x in enumerate(shelf, 1)} if len(shelf) >= 2 else {}
        iso = Path(tempfile.gettempdir()) / 'static-studio-reads' / uuid.uuid4().hex[:16]
        out_path = iso / 'findings.json'
        shelf_text = OPENING_SHELF.replace('{ENTRIES}', '\n'.join(
            f'{i}. "{x["title"]}"' + (f' (its picture: {x["thumbnail"]})' if x['thumbnail'] else '')
            for i, x in entries.items())) if entries else ''
        text = _fill(OPENING_BRIEF, STANCE=OPENING_STANCES[(k - 1) % len(OPENING_STANCES)], K=len(cands),
                     HOUSE_RULES=HOUSE_RULES, SHELF_JSON=OPENING_SHELF_JSON if entries else '', OUT=out_path)
        text = text.replace('{SHELF}', shelf_text)       # titles are the makers' own words: never run through _fill
        for lab, cid in labels.items():
            c = cands[cid]
            text += (f'\n## Opening {lab}\nWhat you hear: {strip_tags(c.get("narration") or "")}\n'
                     f'What you see: {c.get("picture")}\n')
        iso.mkdir(parents=True, exist_ok=True)
        folder.mkdir(parents=True, exist_ok=True)
        packet = iso / 'packet.md'
        packet.write_text(text, encoding='utf-8')
        (folder / f'packet-opening-r{rnd}.md').write_text(text, encoding='utf-8')
        write_json(folder / f'packet-opening-r{rnd}.json', {
            'kind': 'opening', 'round': rnd, 'video': n, 'created_at': now(), 'findings_file': str(out_path),
            'isolated_dir': str(iso), 'brief_version': BRIEF_VERSION, 'subject_sha256': sha, 'labels': labels,
            'shelf': {i: {'ours': x['ours'], 'title': x['title']} for i, x in entries.items()},
            'stance': OPENING_STANCES[(k - 1) % len(OPENING_STANCES)], 'packet': str(packet)})
        made.append({'round': rnd, 'packet': str(packet), 'findings_file': str(out_path)})
    emit({'ok': True, 'packets': made, 'openings': len(cands), 'shelf_entries': len(ours) + len(others),
          'warnings': c_warn,
          'next': 'Give each packet to its own fresh reader: opening-read (each as its own restricted process), or '
                  'spawn one agent of type static-cold-reader per packet with no other context, its whole prompt: '
                  '"Read only <packet> and follow it exactly." Never tell a reader which opening you prefer. Then '
                  'opening-record.'})


def cmd_opening_read(args):
    """Run the fresh reader of every opening packet that has no answer yet, each as its own confined process."""
    rd, st = run_folder(args)
    vd = video_dir(rd, int(args.video))
    folder = vd / 'reviews'
    done = []
    for mp in sorted(folder.glob('packet-opening-r*.json') if folder.is_dir() else []):
        meta = read_json(mp)
        findings = Path(meta.get('findings_file') or '')
        if not meta.get('isolated_dir') or (folder / f'opening-r{meta.get("round")}.json').is_file() or findings.is_file():
            continue
        packet = Path(meta.get('packet') or Path(meta['isolated_dir']) / 'packet.md')
        if not packet.is_file():
            error('A packet is gone (the temp folder was cleared): run opening-packet again.', str(packet))
        done.append({'round': meta.get('round'),
                     'seconds': run_fresh_reader(packet, Path(meta['isolated_dir']), findings, args.timeout)})
    emit({'ok': True, 'read': done, 'next': 'opening-record' if done else
          'Nothing to read: every packet has its answer (opening-record), or none was made (opening-packet).'})


def _opening_label(v, labels):
    s = str(v or '').strip().upper()
    if s in labels:
        return s
    m = re.search(r'\b([A-Z])\b', s)
    return m.group(1) if m and m.group(1) in labels else None


def _shelf_entry(v, shelf):
    """A reader's reference to a shelf entry (its number, or its title written out) as the entry's number."""
    s = str(v or '').strip()
    num = re.sub(r'\D', '', s)
    if num in shelf:
        return num
    low = s.strip('"\' ').lower()
    return next((k for k, e in shelf.items() if str(e.get('title') or '').lower() == low), None)


def opening_read_problems(raw, meta):
    """Why a reader's answer does not follow the opening packet's format (empty: it does)."""
    labels = meta.get('labels') or {}
    out = []
    if _opening_label(raw.get('keep_watching'), labels) is None:
        out.append('"keep_watching" must be one of the packet\'s labels: ' + ', '.join(labels))
    if n_words(raw.get('why')) < 4:
        out.append('"why" is not told (why you would keep watching that one)')
    ops = raw.get('openings') if isinstance(raw.get('openings'), dict) else {}
    got = {(_opening_label(k, labels) or str(k)): v for k, v in ops.items()}
    for lab in labels:
        v = got.get(lab)
        if not isinstance(v, dict) or n_words(v.get('wants_to_know')) < 1 or n_words(v.get('thinks_it_is')) < 2:
            out.append(f'openings: {lab} needs "wants_to_know" and "thinks_it_is"')
    shelf = meta.get('shelf') or {}
    if shelf:
        sh = raw.get('shelf') if isinstance(raw.get('shelf'), dict) else {}
        clicks = sh.get('would_click') if isinstance(sh.get('would_click'), list) else []
        if not clicks or any(_shelf_entry(x, shelf) is None for x in clicks):
            out.append('shelf: "would_click" must list entries of the shelf by their numbers, first choice first')
    return out


def cmd_opening_record(args):
    """Seal what each fresh reader said of the openings (their words are never edited; labels become the openings'
    own ids), and show the reads side by side. The decision is the director's, written in opening.json."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    folder = vd / 'reviews'
    doc = read_json(opening_path(vd))
    recorded, waiting = [], []
    for mp in sorted(folder.glob('packet-opening-r*.json') if folder.is_dir() else []):
        meta = read_json(mp)
        rnd = meta.get('round')
        if (folder / f'opening-r{rnd}.json').is_file():
            continue
        given = bool(args.findings) and int(getattr(args, 'round', 0) or 0) == int(rnd or -1)
        fpath = Path(args.findings).expanduser() if given else Path(meta.get('findings_file') or '')
        if not fpath.is_file():
            waiting.append(rnd)
            continue
        raw = read_json(fpath, required=True)
        problems = opening_read_problems(raw, meta)
        if problems:
            error('A reader\'s answer does not follow the packet\'s format. Ask that reader to fix the format; never '
                  'rewrite its judgement.', {'round': rnd, 'file': str(fpath), 'problems': problems})
        labels, shelf = meta['labels'], meta.get('shelf') or {}
        keep = _opening_label(raw.get('keep_watching'), labels)
        ops = {(_opening_label(k, labels) or str(k)): v for k, v in (raw.get('openings') or {}).items()}
        sh = raw.get('shelf') if isinstance(raw.get('shelf'), dict) else {}
        iso_dir = meta.get('isolated_dir')
        route = read_json(Path(iso_dir) / 'review-read.json') if iso_dir else {}
        write_json(folder / f'opening-r{rnd}-findings.json', raw)        # the reader's answer as written, kept in the run
        write_json(folder / f'opening-r{rnd}.json', {
            'kind': 'opening', 'round': rnd, 'video': n, 'subject_sha256': meta.get('subject_sha256'),
            'labels': labels, 'stance': meta.get('stance'), 'reviewer': raw.get('reviewer') or 'unstated',
            'keep_watching': keep, 'keep_watching_id': labels[keep], 'why': raw.get('why'),
            'keep_from_others': raw.get('keep_from_others'),
            'openings': {labels[lab]: ops[lab] for lab in labels if isinstance(ops.get(lab), dict)},
            'shelf': ({'entries': shelf, 'would_click': [_shelf_entry(x, shelf) for x in sh.get('would_click') or []],
                       'why': sh.get('why'),
                       'expect': {_shelf_entry(k, shelf) or str(k): v
                                  for k, v in (sh.get('expect') or {}).items()} if isinstance(sh.get('expect'), dict) else {},
                       'never': [{'entry': _shelf_entry(x.get('entry'), shelf), 'why': x.get('why')}
                                 for x in sh.get('never') or [] if isinstance(x, dict)]} if shelf else None),
            'flags': raw.get('flags') or [], 'findings_from': str(fpath), 'brief_version': meta.get('brief_version'),
            'reader_route': ('review-read: a process whose file tools were confined to its own folder' if route else
                             'an agent (static-cold-reader): Read and Write tools only, its packet outside the run; '
                             'its file access is not confined'),
            'reader_confined': bool(route), 'recorded_at': now()})
        recorded.append(rnd)
    reads = opening_reads(vd, opening_sha(doc))
    ours, _others = opening_shelf(doc, read_json(vd / 'direction.json'))
    summary = opening_summary(reads, opening_candidates(doc), ours)
    flagged = [{'reader': r.get('_round'), 'flags': r.get('flags')} for r in reads if r.get('flags')]
    emit({'ok': True, 'recorded': recorded, 'waiting_for_a_reader': waiting, 'summary': summary,
          **({'house_rule_flags': flagged} if flagged else {}),
          'next': ('Decide in opening.json -> "decision": {"opening": "<id>", "why": "...", "readers": "what the '
                   'readers said and what was done with it", "taken_from_others": "...", "package": "<our title\'s '
                   'id>"}. The readers\' accounts are evidence, not a vote: the decision is yours, and it says why. '
                   'Then write the script from the chosen opening.' if reads else
                   'No read of the current openings is on record yet.')})


AT_RX = r'\d{1,3}:\d{2}(\s*-\s*\d{1,3}:\d{2})?(\s*,\s*\d{1,3}:\d{2}(\s*-\s*\d{1,3}:\d{2})?)*'


# ---------------------------------------------------------------- what happened, why it matters, whether it paid
# The user, 2026-11-23, after watching a finished film several times: the deception was easy to follow, why it mattered
# was not, and no review had said so. Fresh readers know a great deal, so they supply the significance from their own
# knowledge. Readers now name the developments that matter most and keep three judgements apart for each (what
# happened / why it matters, from the video alone / whether it paid off); review-record turns a gap into a finding
# answered like any other. Not every video needs danger or a twist: the reward is the video's own (10 §4, 06).
BRIEF_VERSION = 7          # 7 (2026-11-26, the creative pass): no 1-10 score; the reader says whether they would
                           # have watched to the end and where they would have stopped; the treatment reader may
                           # get no fixed length (the story sets it) and says whether each one's own length is earned.
                           # 6 (2026-11-26): the script reader also notes the line by which the video's offer was clear
                           # ("clear_at"); the final reviewer gets the sound of the cut as measured facts; wording that
                           # assumed people and a story made neutral.
                           # 3: would_be_different, learned_when; 4 (audit 2026-11-23): the final reader is not told
                           # the intent, why_it_matters and likely_cause are required, key moments sealed; 5
                           # (2026-11-24, storytelling brief): the script reader also says what the opening promised,
                           # where it was first delivered and which waits gave something on the way ("promise")
DEV_EVENT = ('clear', 'partly', 'unclear')
DEV_SIGNIFICANCE = ('clear', 'partly', 'unclear', 'withheld')
DEV_REWARD = ('landed', 'partly', 'missed', 'not the point here')
DEV_FROM = ('the video', 'my own knowledge', 'unclear')
DEV_WHEN = ('before', 'at the moment', 'only afterwards', 'never')
# A reader whose own words say a development changes little has not seen why it matters, whatever its labels say (the
# audit of 2026-11-24: a reviewer called a payoff landed while writing that the event had little consequence). Only
# plain statements count; "not much in the plot, but..." is a reader weighing it, not dismissing it.
LITTLE_CONSEQUENCE = re.compile(
    r"\b(nothing( much| really| important| significant)?( would| will)? (be different|change|matter)|"
    r"not much( would| will)? (change|be different|differ)|"
    r"(little|no|hardly any|barely any|no real) (real )?(difference|consequence|consequences|impact|effect|stakes)|"
    r"would(n'?t| not) (really )?(change|matter|make (much|any|a real) difference)|"
    r"does(n'?t| not) (really )?matter|(hardly|barely) (matters|changes anything)|inconsequential|"
    r"the (story|video|film|outcome) would (be )?(the same|unchanged|no different))\b", re.I)
CONSEQUENCE_WEIGHED = re.compile(r"\b(but|except|though|although|however|yet|apart from|other than)\b", re.I)
# The director's reconciliation of each key moment: the plan's meaning against this reader's account, read in context
RECONCILE_VERDICTS = ('same', 'different_but_valid', 'gap')
# What a weak significance or payoff comes from, named when it is revised (the strongest justified fix follows the
# cause: never more exposition, effects, music or pauses by default)
SIGNIFICANCE_CAUSES = ('context', 'order', 'motivation', 'causality', 'setup', 'significance_unexplained',
                       'cognitive_load', 'visuals', 'material', 'treatment', 'other')


def _says_little_consequence(text):
    """The reader's own words when they say plainly that a development changes little, else None."""
    s = str(text or '')
    for m in LITTLE_CONSEQUENCE.finditer(s):
        rest = re.split(r'[.;!?]', s[m.end():], maxsplit=1)[0]
        head = re.split(r'[.;!?]', s[:m.start()])[-1]
        if not CONSEQUENCE_WEIGHED.search(rest) and not CONSEQUENCE_WEIGHED.search(head):
            return (head + s[m.start():m.end()] + rest).strip()[:200]
    return None


# Worst first: an answer that names two choices ("the video, partly my own knowledge") is read by the worse one, so a
# mixed answer never hides a gap (audit 2026-11-23: the first words used to decide).
_WORST_FIRST = {DEV_EVENT: ('unclear', 'partly', 'clear'),
                DEV_SIGNIFICANCE: ('unclear', 'partly', 'withheld', 'clear'),
                DEV_REWARD: ('missed', 'partly', 'landed', 'not the point here'),
                DEV_FROM: ('my own knowledge', 'unclear', 'the video'),
                DEV_WHEN: ('never', 'only afterwards', 'at the moment', 'before')}


def _choice(value, allowed):
    s = re.sub(r'\s+', ' ', str(value or '').strip().lower())
    first = next((a for a in allowed if s == a or s.startswith(a)), None)
    if first is not None and s == first:
        return first
    named = [a for a in allowed if re.search(r'(?<![a-z])' + re.escape(a) + r'(?![a-z])', s)]
    order = _WORST_FIRST.get(tuple(allowed))
    # two choices named, even after a hedge word ("partly before, partly only afterwards"): the worse one; a single
    # choice after a hedge ("mostly clear") is not a choice, and the format is asked again
    return next((a for a in order if a in named), first) if order and len(named) > 1 else first


def _at_ranges(at):
    """'05:16-06:07, 07:11' -> [(316, 367), (431, 431)] in seconds."""
    out = []
    for part in str(at or '').split(','):
        secs = [int(m) * 60 + int(s) for m, s in re.findall(r'(\d{1,3}):(\d{2})', part)]
        if secs:
            out.append((min(secs), max(secs)))
    return out


def development_problems(kind, devs, order, version=BRIEF_VERSION):
    """Why a reader's `developments` do not follow the packet's format (empty: they do)."""
    if not isinstance(devs, list) or not devs:
        return ['"developments" must name the developments that matter most in this video (at least one)']
    out = []
    for k, d in enumerate(devs, 1):
        if not isinstance(d, dict):
            out.append(f'development {k} is not an object')
            continue
        if kind == 'script':
            if not d.get('lines') or expand_lines(d.get('lines'), order) is None:
                out.append(f'development {k}: "lines" must name lines of the reviewed script (L005 or L005-L009)')
        elif not re.fullmatch(AT_RX, str(d.get('at') or '').strip()):
            out.append(f'development {k}: "at" must be mm:ss or mm:ss-mm:ss')
        if n_words(d.get('what_happened')) < 3:
            out.append(f'development {k}: "what_happened" is not told')
        keys = [('event', DEV_EVENT), ('significance', DEV_SIGNIFICANCE), ('reward', DEV_REWARD), ('why_from', DEV_FROM)]
        if int(version or 2) >= 3:
            keys.append(('learned_when', DEV_WHEN))
            if n_words(d.get('would_be_different')) < 3:
                out.append(f'development {k}: "would_be_different" is not told (or "I could not tell")')
        if int(version or 2) >= 4 and n_words(d.get('why_it_matters')) < 3:
            # a label alone cannot be weighed: the reason in the reader's own words is what the director checks
            out.append(f'development {k}: "why_it_matters" is not told (or "I could not tell")')
        for key, allowed in keys:
            if _choice(d.get(key), allowed) is None:
                out.append(f'development {k}: "{key}" must be one of: ' + ', '.join(allowed))
    return out


PROMISE_FELT = ('anticipation', 'delay')


def _line_specs(spec):
    """'L001-L004, L010' or ['L001-L004, L010'] -> ['L001-L004', 'L010'] (the parts a reader joined in one string)."""
    items = spec if isinstance(spec, list) else [spec]
    out = []
    for it in items:
        out += [p.strip() for p in re.split(r'\s*(?:[,;]|\band\b)\s*', str(it or '')) if p.strip()]
    return out


def normalize_reader_format(kind, raw, order, labels):
    """In place, a reader's harmless serialization slips put into the packet's format, its words untouched:
    several line ranges joined in one string become a list; one treatment finding naming several labels becomes one
    finding per label. Only when every part is valid (anything else stays as written and the format check names it).
    Returns what was changed: [{where, was, now}]."""
    notes = []

    def fix_lines(obj, where):
        v = obj.get('lines')
        if not v or expand_lines(v, order) is not None:
            return
        parts = _line_specs(v)
        if parts and all(expand_lines(p, order) is not None for p in parts):
            notes.append({'where': where, 'was': v, 'now': parts})
            obj['lines'] = parts
    if kind == 'script':
        for f in raw.get('findings') or []:
            if isinstance(f, dict):
                fix_lines(f, f'findings.{f.get("id")}.lines')
        for k, d in enumerate(raw.get('developments') or [], 1):
            if isinstance(d, dict):
                fix_lines(d, f'developments.{k}.lines')
        for k, d in enumerate(raw.get('strongest') or [], 1):
            if isinstance(d, dict):
                fix_lines(d, f'strongest.{k}.lines')
        p = raw.get('promise') if isinstance(raw.get('promise'), dict) else {}
        for k, w in enumerate(p.get('waiting') or [], 1):
            if isinstance(w, dict):
                fix_lines(w, f'promise.waiting.{k}.lines')
        # a line id followed by the reader's own comment ("L019 (the letters begin)"): the id is the answer, the
        # whole text stays beside it as written
        fd = str(p.get('first_delivered') or '').strip()
        if fd and fd.lower() != 'never' and expand_lines(_line_specs(fd), order) is None:
            m = re.match(r'(L\d+(?:\s*-\s*L\d+)?)(?![\w-])(.+)$', fd)
            spec = re.sub(r'\s+', '', m.group(1)) if m else ''
            if spec and m.group(2).strip() and expand_lines(spec, order) is not None:
                p['first_delivered'] = spec
                p['first_delivered_as_written'] = fd
                notes.append({'where': 'promise.first_delivered', 'was': fd, 'now': spec})
    elif kind == 'treatment' and labels:
        out = []
        for f in raw.get('findings') or []:
            labs = [x.strip().upper() for x in re.split(r'\s*(?:[,;/&]|\band\b)\s*', str((f or {}).get('treatment') or ''))
                    if x.strip()] if isinstance(f, dict) else []
            if len(labs) > 1 and all(x in labels for x in labs):
                for i, lab in enumerate(labs):
                    out.append(dict(f, treatment=lab, id=f['id'] if i == 0 else f'{f["id"]}{lab}'))
                notes.append({'where': f'findings.{f.get("id")}.treatment', 'was': f.get('treatment'),
                              'now': [f['id'] if i == 0 else f'{f["id"]}{lab}' for i, lab in enumerate(labs)]})
            else:
                out.append(f)
        raw['findings'] = out
    return notes


def promise_problems(p, order):
    """Why a script reader's "promise" does not follow the packet's format (empty: it does)."""
    if not isinstance(p, dict):
        return ['"promise" must say what the opening promised, where it was first delivered, and the waits before it']
    out = []
    if n_words(p.get('promised')) < 3:
        out.append('promise: "promised" is not told (what the opening made you want)')
    fd = str(p.get('first_delivered') or '').strip()
    if fd.lower() != 'never' and (not fd or expand_lines(_line_specs(fd), order) is None):
        out.append('promise: "first_delivered" must be a line of the script (L005 or L005-L009) or "never"')
    ca = str(p.get('clear_at') or '').strip()       # asked since brief 6; a reader's file without it is still read
    if ca and ca.lower() != 'never' and expand_lines(_line_specs(ca), order) is None:
        out.append('promise: "clear_at" must be a line of the script (L005) or "never"')
    if not isinstance(p.get('waiting'), list):
        out.append('promise: "waiting" must be a list (empty when nothing made you wait)')
    for k, w in enumerate(p.get('waiting') or [], 1):
        if not isinstance(w, dict) or expand_lines(w.get('lines'), order) is None:
            out.append(f'promise: waiting {k}: "lines" must name lines of the script')
            continue
        if _choice(w.get('felt'), PROMISE_FELT) is None:
            out.append(f'promise: waiting {k}: "felt" must be anticipation or delay')
        if n_words(w.get('why')) < 3:
            out.append(f'promise: waiting {k}: "why" is not told')
    return out


def waiting_findings(p, taken):
    """The reader's own account of waiting, as findings the director answers: a stretch felt as delay (minor), and an
    opening promise never delivered (major). A wait felt as anticipation is the build working: no finding."""
    if not isinstance(p, dict):
        return []
    out, k = [], 0

    def next_id():
        nonlocal k
        k += 1
        while f'W{k}' in taken:
            k += 1
        return f'W{k}'
    promised = str(p.get('promised') or '').strip()
    if str(p.get('first_delivered') or '').strip().lower() == 'never':
        out.append({'id': next_id(), 'severity': 'major', 'lines': [],
                    'problem': f'The reader never got what the opening promised them ("{promised}").',
                    'likely_cause': 'the promise the opening makes is not the experience the video delivers',
                    'viewer_impact': 'a viewer who came for the promise leaves without it',
                    'suggestion': ('Deliver what the opening promises, or make the opening promise what the video '
                                   'really gives; or dispute it with the reason.'),
                    'derived_from': {'promise': p}})
    for w in p.get('waiting') or []:
        if not isinstance(w, dict) or _choice(w.get('felt'), PROMISE_FELT) != 'delay':
            continue
        out.append({'id': next_id(), 'severity': 'minor', 'lines': _line_specs(w.get('lines')),
                    'problem': (f'The reader waited here for what the opening promised ("{promised}") without getting '
                                f'enough on the way (their words: "{str(w.get("why") or "").strip()}").'),
                    'likely_cause': 'a stretch that delays the promised experience instead of building toward it',
                    'viewer_impact': 'a viewer who came for the promise drifts while waiting for it',
                    'suggestion': ('Find why this stretch delays rather than builds (it comes before the viewer cares, '
                                   'repeats, holds what the viewer needs only later, or the promise could be met '
                                   'sooner and the background given through the questions it raises) and fix that '
                                   'cause: another order, another frame, a cut, stronger material; or dispute it.'),
                    'derived_from': {'waiting': w}})
    return out


def stop_findings(kind, verdict, findings, order, taken):
    """The reader's own word that they would have stopped watching, as a finding the director answers (brief 7, in
    place of a 1-10 score): a reader who would have left names where; when none of their own major findings is about
    that place, the statement is one. A reader who would have watched to the end: nothing."""
    v = verdict if isinstance(verdict, dict) else {}
    if not str(v.get('watched_to_end') or '').strip().lower().startswith('no'):
        return []
    where = str(v.get('would_stop_at') or '').strip()
    majors = [f for f in findings or [] if isinstance(f, dict) and f.get('severity') == 'major']
    k = 1
    while f'X{k}' in taken:
        k += 1
    out = {'id': f'X{k}', 'severity': 'major',
           'problem': ('The reader would have stopped watching' + (f' at {where}' if where else '')
                       + f' (their words: "{str(v.get("why") or "").strip()}").'),
           'likely_cause': 'what would have kept this reader watching is missing at that place',
           'viewer_impact': 'a viewer who leaves here never reaches what the video builds to',
           'suggestion': ('Find what makes a viewer leave there (nothing new, nothing at stake for anyone, too much '
                          'at once, a promise still unmet) and fix that cause; or dispute it with the reason.'),
           'derived_from': {'verdict': v}}
    if kind == 'script':
        mine = [x for x in re.findall(r'L\d+', where) if x in order]
        if mine and any(set(mine) & set(expand_lines(f.get('lines'), order) or []) for f in majors if f.get('lines')):
            return []
        out['lines'] = mine[:1]
    else:
        def secs(s):
            m_, s_ = s.split(':')
            return int(m_) * 60 + int(s_)
        t = re.search(r'\d{1,3}:\d{2}', where)
        out['at'] = t.group(0) if t else '00:00'
        if t:
            for f in majors:
                for a, b in re.findall(r'(\d{1,3}:\d{2})(?:\s*-\s*(\d{1,3}:\d{2}))?', str(f.get('at') or '')):
                    lo, hi = secs(a), secs(b) if b else secs(a)
                    if lo - 30 <= secs(t.group(0)) <= hi + 30:
                        return []
    return [out]


def _finding_text(f, snap, order):
    ls = expand_lines(f.get('lines'), order) if f.get('lines') else []
    return ' '.join([snap.get(x, '') for x in (ls or [])] + [str(f.get('problem') or ''), str(f.get('likely_cause') or '')])


def recurrence_candidates(prior, findings, snapshot, order):
    """Facts for the director: for each major finding of a new round, the earlier rounds' major findings closest to
    it (words shared by the lines they cite and what they say). Whether it is the same problem is the director's call
    (recurrence.recurs_of); no share of words decides it."""
    out = {}
    for f in findings:
        if not isinstance(f, dict) or f.get('severity') != 'major':
            continue
        mine = _content_tokens(_finding_text(f, snapshot, order))
        cands = []
        for prec, _ in prior:
            psnap = prec.get('subject_snapshot') or {}
            for pf in prec.get('findings') or []:
                if not isinstance(pf, dict) or pf.get('severity') != 'major':
                    continue
                ov = _jaccard(mine, _content_tokens(_finding_text(pf, psnap, list(psnap))))
                cands.append({'round': prec.get('_round'), 'id': pf.get('id'), 'shared_words': round(ov, 2),
                              'problem': str(pf.get('problem') or '')[:220]})
        out[str(f.get('id'))] = sorted(cands, key=lambda c: -c['shared_words'])[:3]
    return out


def key_moment_spans(rd, vd, n, kind, order):
    """The beat map's key moments as (beat, lo, hi): script line positions (1-based) or seconds of the cut."""
    beats = read_json(vd / 'beat-map.json').get('beats') or []
    keys = [b for b in beats if b.get('key_moment') not in (None, False) and str(b.get('key_moment')).strip()]
    out = []
    if kind == 'script':
        for b in keys:
            try:
                out.append((b, int(b['line_start']), int(b['line_end'])))
            except (KeyError, TypeError, ValueError):
                continue
        return out
    plan = read_json(rd / '70-edit' / f'video-{int(n):02d}' / 'edit-plan.json')
    spans = {}
    for s in plan.get('shots') or []:
        bid = str(s.get('beat_id'))
        lo, hi = spans.get(bid, (float(s['start_s']), float(s['end_s'])))
        spans[bid] = (min(lo, float(s['start_s'])), max(hi, float(s['end_s'])))
    return [(b, *spans[str(b.get('id'))]) for b in keys if str(b.get('id')) in spans]


def review_spans(meta, rd, vd, n, kind, order):
    """The key moments a read is weighed against: as sealed in its packet (a mark moved after the read changes
    nothing), or read now for a packet made before they were sealed."""
    sealed = (meta or {}).get('key_moment_spans')
    if isinstance(sealed, list):
        return [({'id': s.get('beat'), 'key_moment': s.get('key_moment'),
                  'significance': {'matters_because': s.get('matters_because')}}, s.get('lo'), s.get('hi'))
                for s in sealed if isinstance(s, dict)]
    return key_moment_spans(rd, vd, n, kind, order)


def _dev_overlaps(kind, d, spans, order):
    if kind == 'script':
        idx = {lid: i + 1 for i, lid in enumerate(order)}
        mine = [idx[x] for x in (expand_lines(d.get('lines'), order) or []) if x in idx]
        return [b for b, lo, hi in spans if any(lo <= c <= hi for c in mine)]
    # mm:ss names a whole second (05:16 is 316.0-317.0): a development counts for a key moment when the two share a
    # quarter of a second at least (half of a very short span), never on a boundary touch (audit 2026-11-24: +-1 s)
    rng = _at_ranges(d.get('at'))
    return [b for b, lo, hi in spans
            if any(min(c + 1.0, hi) - max(a, lo) > min(0.25, max(0.0, hi - lo) / 2) for a, c in rng)]


def development_findings(kind, devs, taken, spans=(), order=()):
    """The reader's developments where following what happened did not carry why it matters, or the payoff did not
    land, as findings answered like any other. The reader's own words are quoted, never rewritten. A development held
    back on purpose ("withheld") is not a finding: productive uncertainty stays. Why it matters arriving only after the
    moment is major where the beat map marks a key moment (`spans`, from key_moment_spans): the moment itself then
    passes without its weight (user, 2026-11-23)."""
    out, k = [], 0
    for i, d in enumerate(devs or [], 1):
        ev, sg = _choice(d.get('event'), DEV_EVENT), _choice(d.get('significance'), DEV_SIGNIFICANCE)
        rw, fr = _choice(d.get('reward'), DEV_REWARD), _choice(d.get('why_from'), DEV_FROM)
        when = _choice(d.get('learned_when'), DEV_WHEN)
        what = str(d.get('what_happened') or '').strip()
        why = str(d.get('why_it_matters') or '').strip() or 'nothing'
        diff = str(d.get('would_be_different') or '').strip()
        keys = _dev_overlaps(kind, d, spans, order) if spans else []
        # "I could not tell" what would be different, or why it matters, is not "clear" whatever the label says; the
        # derived finding then quotes those words too, so its basis is the reader's own (storytelling brief: integrity)
        told = ''
        if sg == 'clear' and re.search(r"\b(could ?not|couldn'?t|cannot|can'?t) tell\b", f'{diff} {why}', re.I):
            sg = 'partly'
            told = diff if re.search(r"\b(could ?not|couldn'?t|cannot|can'?t) tell\b", diff, re.I) else ''
        if ev == 'unclear':
            sev, cause = 'major', 'what happened is not clear here'
            prob = f'The reader could not follow what happened at a development that matters: "{what}".'
        elif sg == 'withheld':
            continue
        elif sg == 'unclear' or when == 'never':
            sev, cause = 'major', 'what it means was never established for the viewer'
            prob = (f'The reader followed what happened ("{what}") but could not tell why it matters (their words: '
                    f'"{why}").')
        elif fr == 'my own knowledge':
            sev, cause = 'major', 'the video leans on knowledge it never gives'
            prob = (f'The reader knew why this matters only from their own knowledge, not from the video: "{what}" '
                    f'matters because "{why}". A first-time viewer may not know it.')
        elif when == 'only afterwards' and keys:
            # a key moment must carry its meaning when it happens; elsewhere a setup that is clear at the time and pays
            # off later is ordinary craft (reader test D, 2026-11-23: a planted rule called back in the last line)
            sev = 'major'
            cause = 'why it matters arrives only after the moment, so the moment itself passes without its weight'
            prob = (f'The reader learned why "{what}" matters only afterwards (their words: "{why}"; without it: '
                    f'"{diff or "not told"}"). It is a key moment ({", ".join(str(b.get("id")) for b in keys)}).')
        elif sg == 'partly' or fr == 'unclear':
            # on a key moment, half a meaning is the film missing its point (reader test A, 2026-11-23: the 9 June
            # message "partly", what the Germans stood to lose "left implied until late"; the user needed it explained)
            sev = 'major' if keys else 'minor'
            cause = ('why it matters arrives only after the moment' if when == 'only afterwards' else
                     'what it means is established weakly, or too late')
            prob = (f'The reader only partly saw why this matters: "{what}" (their words: "{why}"'
                    + (f'; and on what would be different without it: "{told}"' if told else '') + ').'
                    + (f' It is a key moment ({", ".join(str(b.get("id")) for b in keys)}).' if keys else ''))
        elif ev == 'partly':
            # following only part of what happened is its own failure, apart from meaning and payoff (audit 2026-11-23)
            sev = 'major' if keys else 'minor'
            cause = 'what happened is only partly clear here'
            prob = (f'The reader only partly followed what happened: "{what}".'
                    + (f' It is a key moment ({", ".join(str(b.get("id")) for b in keys)}).' if keys else ''))
        elif rw == 'missed' or (rw == 'partly' and keys):
            # on a key moment the payoff is what the moment is for: missed is major there, half of it minor
            sev = 'major' if (rw == 'missed' and keys) else 'minor'
            cause = 'the setup or the moment itself does not pay'
            prob = (f'The reader understood "{what}" and why it matters, but the payoff '
                    + ('did not land for them.' if rw == 'missed' else 'only partly landed for them.')
                    + (f' It is a key moment ({", ".join(str(b.get("id")) for b in keys)}).' if keys else ''))
        elif rw in ('landed', 'partly', 'not the point here') and _says_little_consequence(f'{diff}. {why}'):
            # the labels say it worked; the reader's own account says it changes little: the account is the evidence
            little = _says_little_consequence(f'{diff}. {why}')
            sev = 'major' if keys else 'minor'
            cause = "why it matters did not reach the reader: their own account says it changes little"
            prob = (f'The reader marked "{what}" as clear and its payoff as {rw}, yet their own words say it changes '
                    f'little: "{little}".'
                    + (f' It is a key moment ({", ".join(str(b.get("id")) for b in keys)}).' if keys else ''))
        else:
            continue
        if cause.startswith('what happened'):
            impact = 'the viewer loses the thread at a development that matters'
            suggestion = ('Make what happens here easy to follow for a first-time viewer (who is who, what changes, in '
                          'what order), by the means that fits the cause (a clearer line, a picture that shows it, '
                          'another order, less at once); or dispute it with the reason.')
        elif cause.startswith('the setup'):
            impact = ('the moment the video is built around does not pay off' if sev == 'major'
                      else 'the moment gives less than it is there to give')
            suggestion = ('Find why the payoff does not land (its setup, its timing, what the viewer expected by then) '
                          'and strengthen that, not the noise around it; or dispute it with the reason (a reward that '
                          'is not this).')
        else:
            impact = ('the viewer can follow the events without feeling why they matter' if sev == 'major'
                      else 'the moment gives less than it is there to give')
            suggestion = ('Find what the viewer must already know for this to matter and give it before the moment, by '
                          'the means that fits the cause (one clearer line, a picture or drawing that shows the '
                          'relation, another order, a stronger setup, a different idea), without explaining the payoff '
                          'in advance; or dispute it with the reason (a mystery held on purpose, a reward that is not '
                          'this).')
        k += 1
        while f'S{k}' in taken:
            k += 1
        f = {'id': f'S{k}', 'severity': sev, 'problem': prob,
             'likely_cause': cause,
             'viewer_impact': impact,
             'suggestion': suggestion,
             'derived_from': {'development': i, **{key: d.get(key) for key in (
                 'what_happened', 'why_it_matters', 'would_be_different', 'learned_when', 'why_from', 'event',
                 'significance', 'reward', 'note')}}}
        if str(d.get('note') or '').strip():
            f['reader_note'] = str(d['note']).strip()      # the reader's own view of the cause, kept beside the computed one
        f['lines' if kind == 'script' else 'at'] = d.get('lines') if kind == 'script' else str(d.get('at')).strip()
        out.append(f)
    return out


def key_moment_findings(rd, vd, n, kind, devs, order, taken, spans=None):
    """Key moments of the beat map that the reader did not name among the developments that mattered: a check, not a
    verdict (the reader may have chosen others), answered with a reason either way."""
    spans = key_moment_spans(rd, vd, n, kind, order) if spans is None else spans
    out, k = [], 0
    for b, lo, hi in spans:
        if any(b in _dev_overlaps(kind, d, [(b, lo, hi)], order) for d in devs or []):
            continue
        k += 1
        while f'K{k}' in taken:
            k += 1
        means = (b.get('significance') or {}).get('matters_because') or 'not stated in the beat map'
        f = {'id': f'K{k}', 'severity': 'minor',
             'problem': (f'The reader did not name the key moment {b.get("id")} ("{b.get("key_moment")}") among the '
                         f'developments that mattered. It is meant to matter because: {means}.'),
             'likely_cause': 'it may not read as important to a first-time viewer, or the reader chose others',
             'viewer_impact': 'a moment the film is built around may pass without weight',
             'suggestion': ('Check from the reader\'s account whether the moment registers; revise what makes it matter, '
                            'or keep it with the reason.'),
             'derived_from': {'key_moment': b.get('id')}}
        if kind == 'script':
            try:
                f['lines'] = [f'{order[lo - 1]}-{order[hi - 1]}']
            except IndexError:
                f['lines'] = [order[0]] if order else []
        else:
            f['at'] = f'{_mmss(lo)}-{_mmss(hi)}'
        out.append(f)
    return out


def cmd_review_record(args):
    """Seal a reviewer's findings for the current round (they can no longer change without plan-check noticing) and
    start the answers file: every finding gets revised (with its lines), kept or disputed (with a reason)."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    kind = args.kind
    recs = review_records(vd, kind)
    rnd = recs[-1][0]['_round'] + 1 if recs else 1
    folder = vd / 'reviews'
    meta = read_json(folder / f'packet-{kind}-r{rnd}.json')
    if not meta:
        error(f'No packet for round {rnd}: run review-packet --kind {kind} first and give it to a fresh reviewer.')
    fpath = Path(args.findings).expanduser() if args.findings else Path(meta['findings_file'])
    # findings from anywhere but the reader's own folder are recorded as such (release-check names them)
    iso_dir = meta.get('isolated_dir')
    outside = bool(args.findings) and not (iso_dir and os.path.normcase(str(fpath.resolve())).startswith(
        os.path.normcase(str(Path(iso_dir).resolve()))))
    # how the reader was isolated, as it really was: review-read leaves its record in the reader's folder
    route = read_json(Path(iso_dir) / 'review-read.json') if iso_dir else {}
    reader_route = ('review-read: a process whose file tools were confined to its own folder' if route else
                    'an agent (static-cold-reader): Read and Write tools only, its packet outside the run; its file '
                    'access is not confined')
    raw = read_json(fpath, required=True)
    if meta.get('isolated_dir') and not args.findings:
        write_json(folder / f'{kind}-r{rnd}-findings.json', raw)     # the isolated reader's findings, kept in the run
    if not isinstance(raw.get('findings'), list):
        error('The findings file has no "findings" list.', str(fpath))
    # A harmless serialization slip (two line ranges in one string, one finding naming two treatments) is put into
    # the packet's format without a word of the reader's changed; the reader's file as written stays in the run (the
    # copy above, or a byte copy of a file given from elsewhere), and what was normalized is recorded (the user's
    # brief, 2026-11-24: never re-run a reader for a slip like that)
    fmt_notes = normalize_reader_format(kind, raw, list((meta.get('subject_snapshot') or {}).keys()),
                                        meta.get('labels') or {})
    as_written = folder / f'{kind}-r{rnd}-findings.json'
    if fmt_notes and not (meta.get('isolated_dir') and not args.findings):
        folder.mkdir(parents=True, exist_ok=True)
        as_written = folder / f'{kind}-r{rnd}-findings-as-written.json'
        shutil.copyfile(fpath, as_written)
    findings = raw.get('findings')
    # A final reviewer who wrote words around its times ("Held silences 00:29, 05:15") is not asked again and its text is
    # never edited: with --normalize-at the times alone become "at" and its own words stay in "at_original".
    normalized = []
    if kind == 'final' and getattr(args, 'normalize_at', False):
        for f in findings:
            at = str((f or {}).get('at') or '').strip() if isinstance(f, dict) else ''
            if at and not re.fullmatch(AT_RX, at):
                times = re.findall(r'\d{1,3}:\d{2}(?:\s*-\s*\d{1,3}:\d{2})?', at)
                if times:
                    f['at_original'], f['at'] = at, ', '.join(times)
                    normalized.append(str(f.get('id')))
    brief_v = int(meta.get('brief_version') or 1)
    problems, seen = [], set()
    order = list((meta.get('subject_snapshot') or {}).keys())
    for f in findings:
        fid = str(f.get('id') or '').strip() if isinstance(f, dict) else ''
        if not fid or fid in seen:
            problems.append(f'finding without a unique id: {f}')
            continue
        seen.add(fid)
        if f.get('severity') not in ('major', 'minor'):
            problems.append(f'{fid}: severity must be "major" or "minor"')
        if n_words(f.get('problem')) < 4:
            problems.append(f'{fid}: the problem is not described')
        if kind in ('script', 'final') and brief_v >= 4 and n_words(f.get('likely_cause')) < 2:
            problems.append(f'{fid}: "likely_cause" is not given (what you think causes it)')
        if kind == 'script':
            if not f.get('lines') or expand_lines(f.get('lines'), order) is None:
                problems.append(f'{fid}: "lines" must name lines of the reviewed script (L005 or L005-L009)')
        elif kind == 'treatment':
            if str(f.get('treatment') or '').strip().upper() not in (meta.get('labels') or {}):
                problems.append(f'{fid}: "treatment" must be one of the packet\'s labels')
            else:
                f['treatment_id'] = meta['labels'][str(f['treatment']).strip().upper()]
        # a recurring problem may name several moments: mm:ss or mm:ss-mm:ss, comma-separated
        elif not re.fullmatch(AT_RX, str(f.get('at') or '').strip()):
            problems.append(f'{fid}: "at" must be mm:ss or mm:ss-mm:ss (several moments comma-separated); when the '
                            'reviewer only wrote words around its times, review-record --normalize-at keeps them')
    devs = raw.get('developments')
    three_ways = kind in ('script', 'final') and brief_v >= 2
    if three_ways:
        problems += development_problems(kind, devs, order, brief_v)
    if kind == 'script' and brief_v >= 5:
        problems += promise_problems(raw.get('promise'), order)
    on_req = {}
    if kind == 'treatment' and meta.get('scope_request'):
        given = raw.get('on_request') if isinstance(raw.get('on_request'), dict) else {}
        for lab in meta.get('labels') or {}:
            said = str(given.get(lab) or given.get(lab.lower()) or '').strip()
            m_ = re.match(r'(yes|partly|no)\b', said.lower())
            if not m_:
                problems.append(f'on_request: treatment {lab} needs "yes", "partly" or "no", with why')
            else:
                on_req[lab] = (m_.group(1), said)
    if problems:
        error('The findings file does not follow the packet\'s format. Ask the reviewer to fix the format; never '
              'rewrite its judgement.', problems)
    derived = []
    if three_ways:
        taken = {str(f.get('id')) for f in findings}
        spans = review_spans(meta, rd, vd, n, kind, order)
        derived = development_findings(kind, devs, taken, spans, order)
        derived += key_moment_findings(rd, vd, n, kind, devs, order, taken | {f['id'] for f in derived}, spans)
        if kind == 'script' and brief_v >= 5:
            derived += waiting_findings(raw.get('promise'), taken | {f['id'] for f in derived})
        if brief_v >= 7:
            derived += stop_findings(kind, raw.get('verdict'), findings, order, taken | {f['id'] for f in derived})
        findings = findings + derived
    if on_req:
        # "partly" or "no" on whether a treatment is still the video that was asked for: the director answers it
        taken, q = {str(f.get('id')) for f in findings}, 0
        for lab, (word, said) in on_req.items():
            if word == 'yes':
                continue
            q += 1
            while f'Q{q}' in taken:
                q += 1
            f = {'id': f'Q{q}', 'severity': 'major' if word == 'no' else 'minor', 'treatment': lab,
                 'treatment_id': meta['labels'][lab],
                 'problem': f'Asked whether treatment {lab} is a video about what was asked for '
                            f'("{meta["scope_request"]}"), the reader answered: {said}',
                 'viewer_impact': 'the person who asked would get another video than the one they asked for',
                 'suggestion': 'bring the treatment back to the request, or answer why it still is that video',
                 'derived_from': {'on_request': lab}}
            derived.append(f)
            findings = findings + [f]
            taken.add(f['id'])
    # Each key moment's planned meaning (the beat map, the researched values it carries) beside what this reader took
    # from it, for the director to reconcile in context once the read is in (never shown to a reader).
    recon = {}
    if three_ways:
        dsub = (read_json(vd / 'direction.json').get('subject') or {})
        vals_ = {str(v.get('id')): v for v in dsub.get('value_to_carry') or [] if isinstance(v, dict)}
        beats_ = {str(b.get('id')): b for b in read_json(vd / 'beat-map.json').get('beats') or [] if isinstance(b, dict)}
        for b, lo, hi in spans:
            bid = str(b.get('id'))
            full = beats_.get(bid) or {}
            mine = [{'development': i, **{k: dv.get(k) for k in ('what_happened', 'why_it_matters', 'would_be_different',
                                                                 'learned_when', 'event', 'significance', 'reward')}}
                    for i, dv in enumerate(devs or [], 1)
                    if isinstance(dv, dict) and _dev_overlaps(kind, dv, [(b, lo, hi)], order)]
            recon[bid] = {'key_moment': b.get('key_moment'),
                          'planned': {'matters_because': (b.get('significance') or {}).get('matters_because'),
                                      'reward': (full.get('significance') or {}).get('reward'),
                                      'values': [{'id': r, 'what': vals_[r].get('what'),
                                                  'why_it_matters': vals_[r].get('why_it_matters'),
                                                  'payoff': vals_[r].get('payoff') is True}
                                                 for r in (str(x) for x in full.get('carries') or []) if r in vals_]},
                          'reader': mine, 'verdict': '', 'note': '', 'cause': '', 'answered_by': '', 'revision': ''}
    # A major problem in a later round is weighed against the earlier rounds' majors: the facts list the closest
    # (shared words of the lines and the problem), and the director says whether it recurs and, if so, what the
    # earlier revision missed (answer rules 3). The new reader never sees any of this.
    recur = {}
    if recs and kind in ('script', 'final'):
        recur = recurrence_candidates(recs, findings, meta.get('subject_snapshot') or {}, order)
        for f in findings:
            if f.get('severity') == 'major':
                f['needs_recurrence'] = True
    rec = {'kind': kind, 'round': rnd, 'video': n, 'packet': str(folder / f'packet-{kind}-r{rnd}.md'),
           'subject_sha256': meta['subject_sha256'], 'subject_snapshot': meta.get('subject_snapshot'),
           'holds_snapshot': meta.get('holds_snapshot'),
           'labels': meta.get('labels'), 'file': meta.get('file'), 'reviewer': raw.get('reviewer') or 'unstated',
           'verdict': raw.get('verdict') or {k: raw.get(k) for k in ('would_watch', 'why', 'per_treatment',
                                                                       'length_feels') if k in raw},
           'strongest': raw.get('strongest'), 'findings': findings, 'findings_sha256': canonical_sha(findings),
           'at_normalized': normalized, 'findings_from': str(fpath), 'findings_outside_reader_folder': outside,
           'reader_route': reader_route, 'reader_confined': bool(route), 'answer_rules': ANSWER_RULES,
           'developments': devs if three_ways else None, 'derived_findings': [f['id'] for f in derived],
           'recorded_at': now(),
           **({'line_matching': LINE_MATCHING} if kind == 'script' else {}),
           **({'promise': raw.get('promise')} if kind == 'script' and brief_v >= 5 else {}),
           **({'format_normalized': fmt_notes, 'findings_as_written': str(as_written)} if fmt_notes else {}),
           **({'recurrence_candidates': recur} if recur else {})}
    if on_req:
        rec['on_request'] = raw.get('on_request')
    if recon:
        rec['reconcile_moments'] = list(recon)
    write_json(folder / f'{kind}-r{rnd}.json', rec)
    ans_path = folder / f'{kind}-r{rnd}-answers.json'
    if not ans_path.exists():
        def blank(f):
            a = {'action': '', 'lines': [], 'note': ''}
            if _significance_finding(f):
                a['cause'] = ''
            if f.get('needs_recurrence'):
                a['recurrence'] = {'recurs_of': '', 'root_cause': '', 'scope': ''}
            return a
        doc = {'answers': {str(f['id']): blank(f) for f in findings},
               'how': 'action: revised (script: list the lines changed) | kept (minor only) | disputed; '
                      'kept and disputed need a reason in note. A major finding is revised or disputed. A revised '
                      'finding about what a development means or pays (S, K) names its cause: '
                      + ' | '.join(SIGNIFICANCE_CAUSES) + ' (other: say which). A major finding of a later round says '
                      'whether it recurs (recurrence.recurs_of: "none", or an earlier finding such as "r1:F1": see the '
                      'record\'s recurrence_candidates) and, when it does, what the earlier revision missed '
                      '(root_cause) and what kind of correction it needs (scope: ' + ' | '.join(RECURRENCE_SCOPES)
                      + '). Rewording does not answer a problem two readers found; a structural or treatment cause '
                      'is answered by a direction revision (direction-lock --revise), a duration cause by a length '
                      'decision the user approves. A recurring major that is disputed is closed by a decision, never '
                      'by the word alone: "decision": {"options": [{"cure": what it would do, "cost": what it costs}, '
                      '... two at least; leaving it as it is may be one], "chosen": which was taken, "blocked_by": '
                      + ' | '.join(DECISION_BLOCKS) + ' (what stands in the way of the strongest cure), "decided_by": '
                      '"director" | "user", "user_words": their own words}. When the length, narration already '
                      'recorded or the budget blocks the cure, the decision is the user\'s: put the options to them '
                      'and stop work on that finding until they answer.'}
        if recon:
            doc['reconcile'] = recon
            doc['how_reconcile'] = (
                'For each key moment: what the film planned it to mean (planned) against what this reader took from it '
                '(reader: their own words). verdict: same (they took the planned meaning) | different_but_valid (another '
                'reading the film can stand, say why) | gap (the planned meaning did not reach them). note: why, in '
                'context: a reader saying it changes little is a gap whatever its labels; a different emphasis is not. '
                'A gap names its cause (' + ' | '.join(SIGNIFICANCE_CAUSES) + ') and is answered_by one of this '
                'round\'s findings or by the revision made; it counts as a major finding (a fresh read follows).')
        write_json(ans_path, doc)
    majors = [str(f['id']) for f in findings if f.get('severity') == 'major']
    need_more = bool(majors) and rnd < REVIEW_MAX_ROUNDS[kind]
    emit({'ok': True, 'record': str(folder / f'{kind}-r{rnd}.json'), 'answers_file': str(ans_path),
          'findings': len(findings), 'major': majors,
          'next': ('Answer every finding in the answers file and make the revisions. ' +
                   (f'Major findings: after revising, a fresh round-{rnd + 1} read of the new version is required '
                    '(review-packet again, a NEW agent).' if need_more else
                    'No further read is required by the process; another one is always allowed.'))})


def cmd_shot_check(args):
    rd, st = run_folder(args)
    keep = getattr(args, 'keep', '') or ''
    if keep and n_words(keep) < MIN_NOTE_WORDS:
        error('Say why the shots of the changed beats still fit (a few words at least).')
    res = shot_facts(rd, args.video, keep=keep)
    if res['ready']:
        # what this passing check saw, beat by beat and shot by shot: a beat changed later names its own shots
        n = int(args.video)
        prev = read_json(shot_check_path(rd, n))
        hist = (prev.get('history') or []) + ([{'at': now(), 'kept': keep, 'beats': res.get('changed_beats')}]
                                              if keep and res.get('changed_beats') else [])
        script_rows = read_json(video_dir(rd, n) / 'script.json').get('lines') or []
        write_json(shot_check_path(rd, n), {
            'checked_at': now(),
            'beats': {str(b.get('id')): beat_content_sha(b, script_rows)
                      for b in read_json(video_dir(rd, n) / 'beat-map.json').get('beats') or [] if isinstance(b, dict)},
            'shots': {str(s.get('id')): part_sha(s) for s in read_json(artifact_path(rd, n, 'shot-plan')).get('shots') or []
                      if isinstance(s, dict)},
            'history': hist})
    emit(res, 0 if res['ready'] else 2)


MASTER_LOUDNESS_TOLERANCE_LU = 0.5      # what master-sound itself accepts as reached
MASTER_PEAK_TOLERANCE_DB = 0.5


def export_role(rd, video, sha, loud, issues, warnings):
    """What a file is to this video, from the master record and its own measured sound: 'master' (the recorded
    mastered file, which must still measure what its record says), 'unmastered_export' (the export that master was
    made from) or 'not_on_record'. The plain sentence goes to the lists given, so CapCut's own export is never taken
    for the deliverable (2026-11-26: a film left at -23.4 LUFS; its file was exported after the run's last record)."""
    mrec = read_json(rd / '80-deliverables' / f'video-{int(video):02d}' / 'master.json')
    il, tp = loud.get('integrated_lufs'), loud.get('true_peak_dbtp')
    said = f'{il:g} LUFS' if il is not None else 'an unmeasured loudness'
    made = mrec.get('mastered') or {}
    if made.get('sha256') == sha:
        tgt, ceil = mrec.get('target_lufs'), mrec.get('true_peak_ceiling_dbtp')
        if tgt is not None and (il is None or abs(il - float(tgt)) > MASTER_LOUDNESS_TOLERANCE_LU):
            issues.append(f'export_master_measures_{said.replace(" ", "_")}_not_its_recorded_{float(tgt):g}_LUFS')
        if ceil is not None and tp is not None and tp > float(ceil) + MASTER_PEAK_TOLERANCE_DB:
            issues.append(f'export_master_true_peak_{tp:g}_dBTP_is_over_its_ceiling_{float(ceil):g}')
        return 'master'
    if (mrec.get('export') or {}).get('sha256') == sha:
        warnings.append(f'this file is the unmastered export ({said}): the deliverable is its master, {made.get("file")}')
        return 'unmastered_export'
    if made:
        warnings.append(f'this file is not the recorded master, and not the export it was made from ({said}; the master '
                        f'was made at {mrec.get("target_lufs")} LUFS): a new export needs its own master (master-sound)')
    else:
        warnings.append(f'not mastered yet: this file measures {said}; master-sound makes the deliverable')
    return 'not_on_record'


def export_facts(rd, video, file, deep=False, sha=None):
    lock = read_json(video_dir(rd, video) / 'length-lock.json')
    if not lock:
        error('Length lock not found for video')
    issues = []
    if not audio_facts(rd, video)['ready']:
        issues.append('audio_gate_failed')
    video_file = Path(file).expanduser().resolve()
    if not video_file.is_file():
        error('Export file not found', str(video_file))
    meta = probe(video_file)
    target = lock['target_length_s']
    if not meta['has_video'] or not meta['has_audio']:
        issues.append('export_missing_picture_or_sound')
    if not meta['width'] or not meta['height'] or abs(meta['width'] / meta['height'] - 16 / 9) > 0.025:
        issues.append('export_aspect_not_16_9')
    if meta['width'] and meta['width'] < 1280:
        issues.append('export_low_resolution')
    # the run's own format, exactly: a review copy at another size is fine, but it is not the master
    fmt = read_json(rd / 'state.json').get('format') or {}
    if fmt.get('width') and fmt.get('height') and meta['width'] and \
            (int(meta['width']), int(meta['height'])) != (int(fmt['width']), int(fmt['height'])):
        issues.append(f'export_size_{meta["width"]}x{meta["height"]}_is_not_the_runs_{fmt["width"]}x{fmt["height"]}')
    if fmt.get('fps') and meta.get('fps') and abs(float(meta['fps']) - float(fmt['fps'])) > 0.05:
        issues.append(f'export_frame_rate_{meta["fps"]:g}_is_not_the_runs_{fmt["fps"]}')
    if abs(meta['duration_s'] - target) > max(4, target * lock.get('tolerance_export_pct', .025)):
        issues.append('export_duration_misses_user_locked_length')
    # The export carries the approved narration, whole, at its own speed: the edit plan's narration file found in the
    # export's sound, window by window along the film (a speed change drifts, a cut or an insert jumps, a missing
    # stretch is not found), and the level of everything else under the voice.
    warnings, narration_match = [], None
    # The file's own sound, measured on the file (never assumed from the step that should have made it), and what
    # the file is to this video: the recorded master, the export it was made from, or a file no record knows.
    sha = sha or file_sha256(video_file)
    loud = loudness_stats(video_file) if meta['has_audio'] else {}
    role = export_role(rd, video, sha, loud, issues, warnings)
    plan = read_json(rd / '70-edit' / f'video-{int(video):02d}' / 'edit-plan.json')
    nfe = plan.get('narration_for_edit') or {}
    nf = _run_file(rd, nfe['file']) if nfe.get('file') else None
    if nf and meta['has_audio']:
        if not nf.is_file():
            issues.append('export_narration_file_missing')
        else:
            try:
                av = _av()
                import tempfile
                with tempfile.TemporaryDirectory() as tmp:
                    nwav = av.extract_audio(nf, Path(tmp) / 'narration.wav')
                    # windows that tile the whole narration: a stretch muted between sparse samples would hide
                    nwin = max(12, math.ceil(float(probe(nf)['duration_s']) / 20.0) + 1)
                    m = av.narration_in_mix(av.extract_audio(video_file, Path(tmp) / 'mix.wav'), nwav, windows=nwin)
                narration_match = m
                for w in m['weak_windows']:
                    issues.append(f'export_narration_not_found_near_{_mmss(w)}')
                if m['lag_spread_s'] is not None and m['lag_spread_s'] > 0.25:
                    issues.append(f'export_narration_timing_drifts_{m["lag_spread_s"]:g}s')
                if m['median_lag_s'] is not None and abs(m['median_lag_s']) > 0.25:
                    issues.append(f'export_narration_offset_{m["median_lag_s"]:g}s')
                if m.get('bed_level_rel_speech_db') is not None and m['bed_level_rel_speech_db'] > -8:
                    warnings.append(f'the sound under the voice sits {m["bed_level_rel_speech_db"]:g} dB below the speech: '
                                    'music may mask words; listen on small speakers')
            except (RuntimeError, ValueError, OSError, ImportError) as exc:
                issues.append('export_narration_not_checked:' + f'{type(exc).__name__}: {str(exc)[:120]}')
    # The export is held to the project it was made from: the project timeline-check passed, unchanged since, and of
    # the same length as the export (a frame or two of CapCut's own rounding aside).
    project, live = None, None
    tcrec = read_json(timeline_check_path(rd, video))
    draft = read_json(rd / '70-edit' / f'video-{int(video):02d}' / 'timeline.json').get('capcut_draft')
    if draft:
        if not tcrec:
            issues.append('project_not_checked_before_export:run_timeline-check')
        else:
            try:
                live = project_snapshot(rd, video, draft)
                ch = project_changes(tcrec.get('snapshot') or {}, live)
                if ch:
                    issues.append('project_changed_since_its_timeline_check:' + '; '.join(ch[:3]))
                end = float((tcrec.get('snapshot') or {}).get('end_s') or 0)
                if end and abs(float(meta['duration_s']) - end) > 0.15:
                    issues.append(f'export_length_{meta["duration_s"]:g}s_is_not_the_checked_projects_{end:g}s')
                project = {'draft': str(draft), 'snapshot': live, 'timeline_checked_at': tcrec.get('checked_at'),
                           'timeline_snapshot_sha256': tcrec.get('snapshot_sha256')}
            except (OSError, ValueError, KeyError, TypeError) as exc:
                issues.append('capcut_project_unreadable:' + str(exc)[:120])
    diag, pictures, blanks = {}, None, None
    if deep:
        for name, filters in [('black_frames', ['-vf', 'blackdetect=d=0.6:pix_th=0.10']),
                              ('audio_silence', ['-af', 'silencedetect=noise=-48dB:d=2'])]:
            cmd = ['ffmpeg', '-hide_banner', '-nostdin', '-i', str(video_file)] + filters + ['-f', 'null', '-']
            try:
                p = subprocess.run(cmd, capture_output=True, text=True, encoding='utf-8', errors='replace', timeout=None)
                rows = [x.strip() for x in p.stderr.splitlines() if
                        ('black_start:' in x if name == 'black_frames' else 'silence_' in x)]
                diag[name] = rows[:400]
            except OSError as exc:
                diag[name] = ['scan_unavailable:' + str(exc)]
                issues.append(f'export_{name}_not_scanned:{str(exc)[:80]}')
        # A black or silent stretch is a defect unless the plan holds it: a held silence (the edit plan's pauses), or a
        # moment the director planned blank on purpose (planned-blanks.json: from_s, to_s, kind, why).
        held = [(float(p['times_in_edit']['silence_from_s']) - 0.4, float(p['times_in_edit']['silence_to_s']) + 0.4)
                for p in plan.get('pauses') or [] if isinstance((p or {}).get('times_in_edit'), dict)
                and p['times_in_edit'].get('silence_from_s') is not None]
        meant = {'black': [], 'silence': []}
        for w in read_json(planned_blanks_path(rd, video)).get('blanks') or []:
            if isinstance(w, dict) and n_words(w.get('why')) >= 4 and w.get('kind') in meant:
                meant[w['kind']].append((float(w['from_s']) - 0.1, float(w['to_s']) + 0.1))
        def covered(a, b, wins):
            return any(w0 <= a + 0.05 and b - 0.05 <= w1 for w0, w1 in wins)
        blanks = {'black': _blank_spans(diag.get('black_frames'), 'black', meta['duration_s']),
                  'silence': _blank_spans(diag.get('audio_silence'), 'silence', meta['duration_s'])}
        for a, b in blanks['black']:
            if not covered(a, b, meant['black']):
                issues.append(f'export_black_{_mmss(a)}-{_mmss(b)}_not_planned')
        for a, b in blanks['silence']:
            if not covered(a, b, meant['silence'] + held):
                issues.append(f'export_silent_{_mmss(a)}-{_mmss(b)}_not_a_planned_silence')
        # The export shows the project's picture at each shot: its frame at the shot's middle is closest to that
        # shot's still among all the project's stills (a move, an overlay or a caption changes it a little).
        if live:
            segs = [s for s in live['visual'] if float(s[3]) - float(s[2]) >= 0.6]
            try:
                rows = _av().picture_matches(video_file, [{'at_s': round(float(a) + (float(b) - float(a)) / 2, 3),
                                                           'expect': f, 'shot': sid} for sid, f, a, b in segs],
                                             sorted({s[1] for s in segs}))
                bad = [r for r in rows if r.get('verdict') == 'another']
                unseen = [r for r in rows if r.get('verdict') == 'unseen']
                pictures = {'shots_sampled': len(rows), 'found': sum(1 for r in rows if r.get('verdict') == 'found'),
                            'shows_another': bad[:20],
                            'not_readable': [{k: r.get(k) for k in ('shot', 'at_s')} for r in unseen]}
                if bad:
                    issues.append('export_shows_another_picture_than_the_project_at:' +
                                  ','.join(_mmss(r['at_s']) for r in bad[:10]))
                if unseen:
                    warnings.append(f'{len(unseen)} shot(s) could not be read in the export (a full-frame card, a dark '
                                    'frame): ' + ', '.join(f"{r.get('shot')}@{_mmss(r['at_s'])}" for r in unseen[:10]))
            except (RuntimeError, ValueError, OSError, ImportError) as exc:
                issues.append('export_pictures_not_checked:' + f'{type(exc).__name__}: {str(exc)[:120]}')
    return {'ready': not issues, 'issues': issues, 'warnings': warnings, 'file': str(video_file), 'metadata': meta,
            'target_s': target, 'difference_s': round(meta['duration_s'] - target, 2), 'diagnostic_flags': diag,
            'blank_spans': blanks, 'pictures': pictures, 'project': project, 'deep': bool(deep),
            'sha256': sha, 'loudness': loud, 'role': role,
            'narration_in_export': {k: v for k, v in (narration_match or {}).items() if k != 'windows'} or None}


def cmd_release_check(args):
    """Every recorded gate for one export: plan (direction, reviews, length), narration, shot plan, the export
    itself, and the final watch review of THIS file with every finding answered. 'ready' means the process was
    followed through; it does not measure whether the video is good."""
    rd, st = run_folder(args)
    n = int(args.video)
    vd = video_dir(rd, n)
    plan = plan_facts(rd, n)
    audio = audio_facts(rd, n)
    shots = shot_facts(rd, n)
    edit = timeline_facts(rd, n)
    exp = export_facts(rd, n, args.file, deep=False)
    fin = review_state(vd, 'final', quick_fingerprint(Path(args.file).expanduser().resolve()))
    older_plan_advisory(rd, n, fin['issues'], fin.setdefault('warnings', []))
    issues = ([f'plan:{x}' for x in plan['issues']] + [f'audio:{x}' for x in audio['issues']] +
              [f'shots:{x}' for x in shots['issues']] + [f'edit:{x}' for x in edit['issues']] +
              [f'export:{x}' for x in exp['issues']] + fin['issues'])
    # This exact file (its full sha256): deep-checked against its project, that project unchanged since, and the master.
    f = Path(args.file).expanduser().resolve()
    sha = exp['sha256']
    prov = (read_json(export_provenance_path(rd, n)).get('exports') or {}).get(sha)
    if not prov:
        issues.append('export:not_checked_as_this_exact_file:run_export-check_--deep_on_it')
    else:
        if not prov.get('deep'):
            issues.append('export:checked_without_--deep:run_export-check_--deep_on_this_file')
        if not prov.get('ready'):
            issues.append('export:its_export-check_found_issues:' + ','.join(str(x) for x in (prov.get('issues') or [])[:3]))
        snap = (prov.get('project') or {}).get('snapshot')
        draft = read_json(rd / '70-edit' / f'video-{n:02d}' / 'timeline.json').get('capcut_draft')
        if snap and draft:
            try:
                ch = project_changes(snap, project_snapshot(rd, n, draft))
                if ch:
                    issues.append('export:the_project_changed_after_this_export_was_checked:' + '; '.join(ch[:3]))
            except (OSError, ValueError, KeyError, TypeError) as exc:
                issues.append('export:capcut_project_unreadable:' + str(exc)[:120])
        elif draft:
            issues.append('export:checked_without_its_project:run_timeline-check_then_export-check_--deep')
    mrec = read_json(rd / '80-deliverables' / f'video-{n:02d}' / 'master.json')
    if not mrec:
        issues.append('export:not_mastered:run_master-sound_and_release_the_mastered_file')
    elif (mrec.get('mastered') or {}).get('sha256') != sha:
        issues.append('export:this_file_is_not_the_recorded_master' +
                      (':it_is_the_unmastered_export' if (mrec.get('export') or {}).get('sha256') == sha else ''))
    rc = research_changes(rd, n, read_json(vd / 'direction-lock.json'))
    if rc:
        issues.append('research:changed_since_the_direction_lock_and_not_rechecked:' +
                      ','.join(rc.get('sources', []) + rc.get('claims', [])))
    # Where this finished file lies outside every model on a habit a viewer feels, its reason is on record
    # (craft-choices.json): asked here for what the picture plan could not show (the mix, the export as measured).
    asked_at_plan = {str(x).split(':')[0] for x in shots['issues']}
    craft = [dp['issue'] for dp in models_beside_facts(rd, n, args.file)['departures']
             if dp['issue'] and dp['issue'].split(':')[0] not in asked_at_plan]
    craft_said = []
    older_plan_advisory(rd, n, craft, craft_said)
    issues += [f'craft:{x}' for x in craft]
    issues = list(dict.fromkeys(issues))
    warnings = list(dict.fromkeys(plan.get('warnings', []) + shots.get('warnings', []) + edit.get('warnings', []) +
                                  fin['warnings'] + craft_said))
    looks = read_json(picture_looks_path(rd, n)).get('looks') or {}
    shown = {_pkey(_run_file(rd, c.get('asset_path'))) for c in
             read_json(rd / '70-edit' / f'video-{n:02d}' / 'timeline.json').get('visual_segments') or []
             if isinstance(c, dict) and c.get('asset_path')}
    # the thumbnail is a picture the audience sees first: looked at like every other (content-review --pictures)
    thumb = Path(args.thumbnail).expanduser().resolve() if getattr(args, 'thumbnail', None) else None
    if thumb is None:
        warnings.append('no thumbnail named (--thumbnail): its picture look was not checked')
    else:
        tl_ = looks.get(_pkey(thumb))
        if not thumb.is_file():
            issues.append(f'thumbnail_not_found:{thumb}')
        elif not tl_ or tl_.get('sha256') != file_sha256(thumb):
            issues.append('thumbnail_not_content_checked:content-review_--pictures_with_the_thumbnail')
        elif tl_.get('result') != 'clean':
            issues.append('thumbnail_has_a_content_issue')
    content = {'pictures_shown': len(shown), 'pictures_looked_at_clean': sum(1 for k in shown if (looks.get(k) or {}).get('result') == 'clean'),
               'excluded_reference_themes_in_force': len(excluded_themes(rd, n)),
               'what_was_seen': 'every picture the timeline shows was looked at whole (content-looks); the export '
                                'itself only through its watch sheets (a frame every 5 s) by the final reviewer, so '
                                'drawn overlays and captions are checked by the timeline and caption checks, not '
                                'frame by frame'}
    # The sound of this exact file, measured (sound-review --file): each piece of music against the voice where it
    # plays, in the file the audience gets, and the listening sheet written. A measurement, never a verdict.
    snd = sound_review_state(rd, n, sha)
    if snd:
        issues.append('sound:' + snd)
    issues = list(dict.fromkeys(issues))
    # What a person did with this exact file, from the record alone. It never blocks: it is said, so "every check
    # passed" is not read as "someone heard it" (no agent can hear; the checks read records and measurements).
    hr = human_review_state(rd, n, sha)
    if not hr['on_record']:
        warnings.insert(0, 'no person has listened to or watched this file on record: every check here reads records '
                           'and measurements (sound-review wrote the listening sheet, the few passages worth a '
                           'person\'s ears; human-review records what they said)')
    recorded = None
    if getattr(args, 'record', False) and not issues:
        # The release on record: this file, by its full sha256, at the moment every recorded gate passed for it.
        old = read_json(release_path(rd, n))
        write_json(release_path(rd, n), {
            'video': n, 'released_at': now(), 'file': str(f), 'sha256': sha,
            'technical': {'ready': True, 'checked_at': now(), 'loudness': exp.get('loudness')},
            'final_review_rounds': fin['rounds'],
            'human_review': {'on_record': hr['on_record'], 'kinds': hr['kinds']},
            'warnings': warnings,
            'history': (old.get('history') or []) + ([{k: old.get(k) for k in ('released_at', 'file', 'sha256')}]
                                                     if old.get('sha256') else [])})
        recorded = str(release_path(rd, n))
    emit({'ready': not issues, 'release_status': 'ready' if not issues else 'blocked', 'issues': issues,
          'warnings': warnings, 'export': {k: exp[k] for k in ('file', 'metadata', 'target_s', 'difference_s')},
          'loudness': exp.get('loudness'), 'file_is': exp.get('role'),
          'human_review': {'on_record': hr['on_record'], 'kinds': hr['kinds']},
          'release_record': recorded or ('not written: pass --record once this is ready' if not issues else None),
          'final_review_rounds': fin['rounds'],
          # why each open answer of the final review is not yet an answer (a repeated major closed by the word "disputed"
          # alone, a missing note): the issue names the findings, this says what each one still needs
          **({'answers_needed': fin['answers_needed']} if fin.get('answers_needed') else {}),
          'content': content,
          'note': 'Ready means every recorded gate passed for this exact file. It does not say the video is good: '
                  'that is the director\'s and the reviewers\' judgement, recorded in their files. It does not say '
                  'a person heard or watched it either: human_review says what is on record.'},
         0 if not issues else 2)


STAGES = ('intake', 'reference_analysis_complete', 'planning', 'direction_locked', 'script_checked', 'narration_recorded',
          'narration_measured', 'stills', 'edit_checked', 'exported', 'released')


def advance_stage(rd, stage):
    """state.json's stage moves forward only (an earlier gate passing again never moves it back)."""
    st = read_json(rd / 'state.json')
    if not st or stage not in STAGES:
        return
    cur = st.get('stage')
    if cur in STAGES and STAGES.index(cur) >= STAGES.index(stage):
        return
    st['stage'] = stage
    write_json(rd / 'state.json', st)


def set_stage(rd, stage):
    """state.json's stage as the records derive it (status): it follows them both ways, so a film rebuilt after its
    release no longer reads 'released' (2026-11-26: a run said so with its last build never exported on record)."""
    st = read_json(rd / 'state.json')
    if not st or stage not in STAGES or st.get('stage') == stage:
        return
    st['stage'] = stage
    write_json(rd / 'state.json', st)


def exports_of_current_project(rd, video):
    """The exports on record that answer for the project as it stands: the one timeline-check passed last, compared
    as project_changes compares (CapCut's own frame snapping aside). An export of an earlier build stays on record and
    counts for nothing here. An export checked without a project (no CapCut draft known) is kept as it was."""
    n = int(video)
    exp = read_json(export_provenance_path(rd, n)).get('exports') or {}
    cur = read_json(timeline_check_path(rd, n)).get('snapshot')
    out = {}
    for sha, x in exp.items():
        if not isinstance(x, dict):
            continue
        snap = (x.get('project') or {}).get('snapshot')
        if cur and snap:
            try:
                if project_changes(snap, cur):
                    continue
            except (TypeError, ValueError, KeyError):
                continue
        out[sha] = x
    return out


HUMAN_REVIEW_KINDS = ('listened', 'watched', 'listened_and_watched', 'waived')


def human_review_state(rd, video, sha=None):
    """What a person did with an export, from the record alone (human-review): for the file with this sha256, or
    every entry when none is given. Never inferred from a step having run, and never written by a check."""
    rows = [r for r in read_json(human_review_path(rd, video)).get('reviews') or [] if isinstance(r, dict)]
    mine = [r for r in rows if sha is None or r.get('sha256') == sha]
    kinds = []
    for r in mine:
        for k in (['listened', 'watched'] if r.get('kind') == 'listened_and_watched' else [r.get('kind')]):
            if k and k not in kinds:
                kinds.append(k)
    return {'on_record': bool(mine), 'kinds': kinds, 'latest': mine[-1] if mine else None,
            'entries_for_other_files': len(rows) - len(mine)}


def deliverable_facts(rd, video, live=True):
    """Where one video's deliverable stands, from the records and nothing else. Each step is its own fact and none
    stands in for another: a project built and checked is not an export; an export is not its master; a master that
    passed every check is not one a person heard. `live` also reads the CapCut project as it is now, so a project
    changed after its check is said to be unchecked. Nothing is written."""
    n = int(video)
    steps = {'built': False, 'exported': False, 'mastered': False, 'verified': False, 'human_review': 'none on record'}
    out = {'state': 'not_built', 'file': None, 'steps': steps, 'stale': [], 'next': 'timeline-check on the built project'}
    tc = read_json(timeline_check_path(rd, n))
    if not tc:
        return out
    steps['built'] = True
    if live and tc.get('draft') and tc.get('snapshot'):
        try:
            ch = project_changes(tc['snapshot'], project_snapshot(rd, n, tc['draft']))
        except (OSError, ValueError, KeyError, TypeError) as exc:
            ch = None
            out['stale'].append('the CapCut project could not be read, so it was not compared with its check: '
                                + str(exc)[:100])
        if ch:
            steps['built'] = False
            out.update({'state': 'project_changed_since_its_check',
                        'next': 'timeline-check again: the project changed after it was checked ('
                                + '; '.join(ch[:2]) + ')'})
            return out
    allx = read_json(export_provenance_path(rd, n)).get('exports') or {}
    cur = exports_of_current_project(rd, n)
    good = {s: x for s, x in cur.items() if x.get('ready') and x.get('deep')}
    older = [x for s, x in allx.items() if isinstance(x, dict) and s not in cur]
    if older:
        out['stale'].append(f'{len(older)} export(s) on record belong to an earlier build of the project and count for '
                            'nothing now: ' + ', '.join(Path(str(x.get('file') or '?')).name for x in older[:4]))
    steps['exported'] = bool(good)
    if live:
        # The records stand when a checked file is moved or deleted afterwards, and the report says so: "next" would
        # otherwise send the director to a file that is not there (seen 2026-11-26 on a run whose export had been
        # checked in a folder that was later cleared).
        gone = [Path(str(x['file'])).name for x in good.values() if x.get('file') and not Path(str(x['file'])).is_file()]
        if gone:
            out['stale'].append('on record, and no longer at its path: ' + ', '.join(gone[:4]) + ' (the record '
                                'stands; a step that needs the file needs it put back, or a new export)')
    m = read_json(rd / '80-deliverables' / f'video-{n:02d}' / 'master.json')
    made = m.get('mastered') or {}
    msha = made.get('sha256')
    steps['mastered'] = bool(msha and msha in good)
    if msha and msha not in cur:
        out['stale'].append('the master on record was made from an earlier build: ' + Path(str(made.get('file') or '?')).name)
    rel = read_json(release_path(rd, n))
    steps['verified'] = bool(steps['mastered'] and rel.get('sha256') == msha and (rel.get('technical') or {}).get('ready'))
    if rel.get('sha256') and not steps['verified']:
        out['stale'].append('a release is on record for a file that is not the current master: '
                            + Path(str(rel.get('file') or '?')).name + f' ({rel.get("released_at")})')
    if steps['mastered']:
        hr = human_review_state(rd, n, msha)
        steps['human_review'] = hr['kinds'] or 'none on record'
        out['file'] = made.get('file')
    mname = Path(str(made.get('file') or '?')).name

    def short(x):                   # why a check on record does not count, in a few words
        return 'it was checked without --deep' if not x.get('deep') else \
            'its check found: ' + ', '.join(str(i) for i in (x.get('issues') or [])[:2])
    if steps['mastered']:
        pass
    elif msha and msha not in allx:
        out.update({'state': 'mastered_not_checked',
                    'next': f'export-check --deep on the mastered file ({mname}): no check of it is on record'})
    elif msha and msha in cur:
        out.update({'state': 'master_check_found_issues',
                    'next': f'the mastered file ({mname}) did not pass export-check --deep ({short(cur[msha])}): fix '
                            'that, then check the new master'})
    elif steps['exported']:
        out.update({'state': 'exported_not_mastered',
                    'next': 'master-sound on the export, then export-check --deep on the mastered file'})
    else:
        failed = [x for s, x in cur.items() if s not in good]
        out.update({'state': 'built_not_exported',
                    'next': (f'the export on record ({Path(str(failed[-1].get("file") or "?")).name}) does not count: '
                             f'{short(failed[-1])}' if failed else
                             'export the checked project from CapCut, then master-sound and export-check --deep on the '
                             'mastered file')})
    if not steps['mastered']:
        pass
    elif not steps['verified']:
        out.update({'state': 'mastered_not_released', 'next': 'sound-review --file on the mastered file, its final '
                    'watch review, then release-check --record on it'})
    else:
        out.update({'state': 'released', 'next': ('' if steps['human_review'] != 'none on record' else
                    'no person has listened or watched on record: give the user the listening sheet (sound-review '
                    'wrote it), then human-review')})
    return out


def video_stage(rd, video, plan_ready, audio, deliv=None):
    """How far one video got, from what is recorded (never a stored guess): the furthest gate passed in order. The
    last steps are read for the project as it stands (deliverable_facts): an export or a release of an earlier build
    moves nothing."""
    n = int(video)
    vd = video_dir(rd, n)
    stage = 'planning'
    if read_json(vd / 'direction-lock.json'):
        stage = 'direction_locked'
    if plan_ready and read_json(plan_check_path(rd, n)):
        stage = 'script_checked'
    man = read_json(rd / '50-audio' / f'video-{n:02d}' / 'manifest.json')
    if stage == 'script_checked' and man.get('status') == 'complete':
        stage = 'narration_recorded'
        if (rd / '50-audio' / f'video-{n:02d}' / 'line-times.json').is_file() and audio.get('ready'):
            stage = 'narration_measured'
    if stage == 'narration_measured' and read_json(artifact_path(rd, n, 'stills')).get('images'):
        stage = 'stills'
    if stage != 'stills':
        return stage
    return stage_after_stills((deliv or deliverable_facts(rd, n))['steps'])


def stage_after_stills(steps):
    """The last stages from the deliverable's steps, each needing the one before: a project built and checked, an
    export of that project that passed its deep check, and the release on record for its checked master."""
    if not steps.get('built'):
        return 'stills'
    if not steps.get('exported'):
        return 'edit_checked'
    return 'released' if steps.get('verified') else 'exported'


def cmd_status(args):
    rd, st = run_folder(args)
    inv = read_json(rd / '00-inventory/references.json')
    n = st.get('video_count', 0)
    videos = {}
    for i in range(1, n+1):
        vd = video_dir(rd, i)
        if not (vd / 'length-lock.json').exists():
            videos[str(i)] = ({'stage': 'planning', 'length': 'the story sets it: not locked yet (length --mode story '
                                                              'again, once a treatment is chosen)'}
                              if read_json(length_intent_path(vd)).get('mode') == 'story' else {'stage': 'not_locked'})
            continue
        plan = plan_facts(rd, i)
        audio = audio_facts(rd, i)
        hf = hold_facts(rd, i)
        deliv = deliverable_facts(rd, i)
        videos[str(i)] = {'target_s': read_json(vd/'length-lock.json').get('target_length_s'),
                          'stage': video_stage(rd, i, plan['ready'], audio, deliv),
                          'deliverable': deliv,
                          'plan_ready': plan['ready'], 'audio_ready': audio['ready'],
                          'holds': {'planned_or_decided': len(hf['holds']), 'provisional': hf['undecided'],
                                    'decided_after_narration': hf['decided_narration'],
                                    'decided_with_picture': hf['decided_picture'], 'added_s': hf['added_s']},
                          'creative': {**(plan.get('creative') or {}),
                                       'reviews': {k: len(review_records(vd, k)) for k in REVIEW_MAX_ROUNDS}},
                          'issues': list(dict.fromkeys(plan['issues'] + audio['issues'])),
                          'warnings': plan.get('warnings', [])}
    # The run's stage is its least advanced video's, from the recorded gates. The stored stage follows it both ways:
    # a gate that no longer holds (a project rebuilt after its release, a script changed after its check) moves it
    # back, so the stored word never claims more than the records do. --look reports and writes nothing.
    got = [v['stage'] for v in videos.values() if v.get('stage') in STAGES]
    stored = st.get('stage')
    if got:
        least = min(got, key=STAGES.index)
        if stored != least:
            if not getattr(args, 'look', False):
                set_stage(rd, least)
            st = {**st, 'stage': least}
    moved = ({'stage_was': stored, 'stage_note': 'the stored stage did not match the records: ' + (
        'corrected in state.json' if not getattr(args, 'look', False) else 'state.json left as it is (--look)')}
             if stored != st.get('stage') else {})
    emit({'ok': True, 'run': str(rd), 'stage': st.get('stage'), **moved, 'selected_niche': st.get('selected_niche'),
          'selected_niche_id': st.get('selected_niche_id'), 'niche_discovery': st.get('niche_discovery'),
          'reference_videos': len([x for x in inv.get('items', []) if x.get('kind') == 'video']),
          'videos': videos})


def sound_review_path(rd, video):
    return rd / '70-edit' / f'video-{int(video):02d}' / 'sound-review.json'


def listening_sheet_path(rd, video):
    return rd / '80-deliverables' / f'video-{int(video):02d}' / 'listening-sheet.md'


def _audio_review():
    """The sound review (audio_review.py, next to this file), loaded only when a sound command needs it."""
    here = str(Path(__file__).resolve().parent)
    if here not in sys.path:
        sys.path.insert(0, here)
    import audio_review
    return audio_review


def sound_tracks_digest(rd, video):
    """The edit's sound as the project has it (timeline.json): which files play, from when to when (to a tenth of a
    second), at which clip volume, and each file's size. A sound review answers for the build it measured: a sound
    moved, added, replaced or re-recorded asks for it again."""
    tl = read_json(rd / '70-edit' / f'video-{int(video):02d}' / 'timeline.json')
    rows = []
    for t in tl.get('audio_tracks') or []:
        if not isinstance(t, dict) or not t.get('file'):
            continue
        f = _run_file(rd, t['file'])
        rows.append([str(t.get('kind')), f.name, round(float(t.get('start_s') or 0), 1),
                     round(float(t.get('end_s') or 0), 1), round(float(1 if t.get('volume') is None else t['volume']), 3),
                     f.stat().st_size if f.is_file() else None])
    return canonical_sha(sorted(rows, key=str))


def sound_review_state(rd, video, sha=None):
    """None when the sound of the project as it stands was reviewed (sound-review) and, with sha, measured in the
    file that has this sha256; else what is missing."""
    sr = read_json(sound_review_path(rd, video))
    if not sr:
        return 'not_reviewed:run_sound-review_--file_on_this_file_(it_writes_the_listening_sheet_too)'
    if sr.get('tracks_digest') != sound_tracks_digest(rd, video):
        return 'reviewed_for_an_earlier_build_of_the_project:run_sound-review_--file_again'
    if sha and (sr.get('export') or {}).get('sha256') != sha:
        return 'not_measured_in_this_file:run_sound-review_--file_on_it'
    return None


def names_to_listen_for(heard_rows, pron):
    """The names worth a listen, from how the transcript heard each use of a name on the pronunciation list
    (voice-measure's pronunciation_heard). A use counts as recognised when it was heard as written, as written with a
    possessive s ("Qin's" comes back as "qins"), or as its planned respelling ("Zhong", planned "Jong", heard "jong"):
    in all three the voice said what the plan asked. Listed: each name with a use that was none of these, the least
    recognised first, with the first such line. Whisper's spelling is never proof of a wrong name; this only chooses
    where a person listens (found on the first real film, 2026-11-26: the plain list was filled with possessives and
    with names said exactly as planned). `nearest_heard` is the line's word most like the name; one that shares under
    half its letters with it ("a" for "Yuan") is the transcript's noise, kept under `heard` and not shown as what was
    heard."""
    letters = lambda s: re.sub(r'[\W_]', '', str(s or '').lower())
    by = {}
    for r in heard_rows:
        if not isinstance(r, dict) or not r.get('term') or not isinstance(r.get('heard_as_written'), bool):
            continue
        term = str(r['term'])
        say = (pron.get(term) or {}).get('say')
        d = by.setdefault(term, {'term': term, 'uses': 0, 'recognised': 0, 'line': None, 'nearest_heard': None,
                                 'heard': [], 'say': say})
        d['uses'] += 1
        forms = set()
        for src in (term, say):
            parts = [letters(x) for x in re.split(r'[\s\-]+', str(src or '')) if letters(x)]
            if parts:
                forms |= {parts[0], ''.join(parts)}
        ok, h = r['heard_as_written'], letters(r.get('nearest_heard'))
        if not ok and h:
            ok = h in forms or (h.endswith('s') and h[:-1] in forms)
        if ok:
            d['recognised'] += 1
            continue
        if d['line'] is None:
            near = max((difflib.SequenceMatcher(None, h, x).ratio() for x in forms), default=0.0) if h else 0.0
            d['line'], d['nearest_heard'] = str(r.get('line')), (r.get('nearest_heard') if near >= 0.5 else None)
        if r.get('nearest_heard') and r['nearest_heard'] not in d['heard']:
            d['heard'].append(r['nearest_heard'])
    return sorted((d for d in by.values() if d['recognised'] < d['uses']),
                  key=lambda d: (d['recognised'] / d['uses'], -d['uses']))


def sound_review_facts(rd, video, export_file=None):
    """Everything sound-review measures for one video, from the files the run already has: each placed sound against
    the voice (by the project's own files and, with export_file, in that finished file), where music plays at all, the
    air at the turns, the pace of the lines, the names the transcript heard differently, the silences nobody listened
    to. (facts, the lines' words, key-moment lines). Nothing is written."""
    n = int(video)
    ar = _audio_review()
    ed = rd / '70-edit' / f'video-{n:02d}'
    tracks = [t for t in read_json(ed / 'timeline.json').get('audio_tracks') or [] if isinstance(t, dict)]
    ep = read_json(ed / 'edit-plan.json')
    nrow = next((t for t in tracks if t.get('kind') == 'narration' and t.get('file')), None)
    nfile = (nrow or {}).get('file') or (ep.get('narration_for_edit') or {}).get('file')
    nfile = _run_file(rd, nfile) if nfile else None
    if not nfile or not nfile.is_file():
        error('No narration of the edit to measure against (timeline.json audio_tracks, or the edit plan\'s '
              'narration_for_edit): build and check the timeline first.')
    voice = ar.voice_profile(nfile, (nrow or {}).get('volume'))
    export, exp = None, None
    if export_file:
        export = ar.export_profile(export_file, voice)
        exp = {'file': Path(export_file).name, 'sha256': file_sha256(export_file),
               'fingerprint': quick_fingerprint(Path(export_file))}
        exp.update({'speech_db': export['speech_db'], 'duration_s': export['duration_s']} if export else
                   {'unreadable': True})
    total = max([float(t.get('end_s') or 0) for t in tracks] + [voice['duration_s']])
    between = {}
    placements = ar.placements_review(
        [{**t, 'file': _run_file(rd, t.get('file'))} for t in tracks
         if t.get('kind') != 'narration' and t.get('start_s') is not None and t.get('end_s') is not None],
        voice, export, total, between=between)
    vd = video_dir(rd, n)
    lines = read_json(vd / 'script.json').get('lines') or []
    order = [str((l or {}).get('id') or f'L{i + 1:03d}') for i, l in enumerate(lines)]
    texts = {i: strip_tags((l or {}).get('text') or '') for i, l in zip(order, lines)}
    marks = {k: v for k, v in edit_landmarks(rd, n).items() if v.get('start') is not None}
    first_lines, key_lines = {}, {}
    for k, b in enumerate(x for x in read_json(vd / 'beat-map.json').get('beats') or [] if isinstance(x, dict)):
        try:
            a, z = order[int(b['line_start']) - 1], order[int(b['line_end']) - 1]
        except (KeyError, TypeError, ValueError, IndexError):
            continue
        if k and b.get('chapter_start') is True:
            first_lines[a] = {'beat': str(b.get('id')), 'why': 'chapter'}
        if is_key_moment(b):
            first_lines.setdefault(a, {'beat': str(b.get('id')), 'why': 'key moment'})
            key_lines[z] = str(b.get('id'))
    lt = read_json(rd / '50-audio' / f'video-{n:02d}' / 'line-times.json')
    words = {str(r.get('id')): int(r.get('words') or 0) for r in lt.get('lines') or [] if isinstance(r, dict)}
    pron = {str(t.get('term')): t for t in read_json(pronunciation_path(rd, n)).get('terms') or [] if isinstance(t, dict)}
    names = names_to_listen_for(lt.get('pronunciation_heard') or [], pron)
    held = {str(h.get('after_line')): h.get('times_in_edit') or {} for h in ep.get('holds') or [] if isinstance(h, dict)}
    not_listened = []
    for lid, dc in (read_json(vd / 'holds.json').get('decisions') or {}).items():
        if not isinstance(dc, dict) or dc.get('no_hold') is True or dc.get('listened'):
            continue
        te, m = held.get(str(lid)) or {}, marks.get(str(lid)) or {}
        a, z = te.get('silence_from_s', m.get('silence_start')), te.get('silence_to_s', m.get('silence_end'))
        if a is not None and z is not None:
            not_listened.append({'line': str(lid), 'from_s': round(float(a), 2), 'to_s': round(float(z), 2),
                                 'total_s': dc.get('total_s')})
    return ({'duration_s': round(total, 2), 'narration': nfile.name, 'speech_db': voice['speech_db'], 'export': exp,
             'placements': placements, 'beds': ar.beds_by_kind(placements, total),
             'between_words': between or None, 'music_alone': ar.music_alone(placements),
             'turns': ar.turn_facts(ar.line_gaps(marks, order), first_lines), 'pace': ar.pace_facts(marks, order, words),
             'names': names, 'holds_not_listened': not_listened, 'line_marks': marks}, texts, key_lines)


def sound_rows(sr):
    """A sound review as plain rows for a reviewer who cannot hear: where music and ambience play and how far under
    the voice (by the project's own files; said where the finished file plays a passage far from that), the long
    stretches with no music, where effects fall, a sound cut off between lines. Times and levels only: no file names
    and nothing of what any sound is meant to do."""
    ar = _audio_review()
    ps = [p for p in sr.get('placements') or [] if isinstance(p, dict) and not p.get('unreadable')]

    def row(p):
        gap = ar.export_gap_words(p)
        return (f'- {ar.mmss(p["start_s"])}-{ar.mmss(p["end_s"])}: {p.get("kind")}, {p["under_voice_db"]:g} dB under '
                'the voice' + (f' ({gap})' if gap else ''))
    rows = [row(p) for p in sorted(ps, key=lambda p: p['start_s']) if p.get('kind') in ('music', 'ambience')]
    if len(rows) > 40:
        rows = rows[:40] + [f'- and {len(rows) - 40} more stretches of music or ambience']
    music = (sr.get('beds') or {}).get('music')
    if isinstance(music, dict) and ps:
        rows += ([f'- no music from {ar.mmss(a)} to {ar.mmss(b)}' for a, b in music.get('none_for_long') or []]
                 if music.get('plays') else ['- no music in this cut'])
    fx = [ar.mmss(p['start_s']) for p in sorted(ps, key=lambda p: p['start_s']) if p.get('kind') == 'sfx']
    if fx:
        rows.append('- sound effects at: ' + ', '.join(fx))
    rows += [f'- a sound stops at {ar.mmss(p["end_s"])}, cut before its end, between two lines'
             for p in ps if ar.is_cut_off(p)]
    return rows or ['- no music, ambience or effects in this cut: the voice alone']


def cmd_sound_review(args):
    """The sound of the checked project, measured from the run's own files, and the listening sheet: the few passages
    where only a person's ears can decide, each with its time in the film and one question. Run it after
    timeline-check (and again when a sound moves). It uses no model and gives no verdict; a person's answers are
    recorded with human-review --answers. --out DIR writes both files there and nothing in the run."""
    rd, st = run_folder(args)
    n = int(args.video)
    ar = _audio_review()
    f = Path(args.file).expanduser().resolve() if getattr(args, 'file', None) else None
    if f and not f.is_file():
        error('That file is not there.', {'file': str(f)})
    facts, texts, key_lines = sound_review_facts(rd, n, f)
    items = ar.listening_items(facts, texts, key_lines)
    vd = video_dir(rd, n)
    title = read_json(vd / 'blueprint.json').get('title') or \
        selection_promise(read_json(vd / 'direction.json')).get('working_title') or f'video {n}'
    name = f.name if f else 'the export of the checked project'
    rec = {'made_at': now(), 'video': n, 'tracks_digest': sound_tracks_digest(rd, n),
           **{k: v for k, v in facts.items() if k != 'line_marks'}, 'listening_items': items,
           'what_this_is': 'levels, times and counts measured from the run\'s own files. No model listened, and '
                           'nothing here says how the film sounds: that is what the listening sheet asks a person.'}
    out = Path(args.out).expanduser().resolve() if getattr(args, 'out', None) else None
    rec_path = out / 'sound-review.json' if out else sound_review_path(rd, n)
    sheet = out / 'listening-sheet.md' if out else listening_sheet_path(rd, n)
    write_json(rec_path, rec)
    sheet.parent.mkdir(parents=True, exist_ok=True)
    sheet.write_text(ar.sheet_markdown(items, str(title), name, facts), encoding='utf-8')
    write_json(sheet.with_suffix('.json'), {'video': n, 'file': name, 'how': 'fill "answer" for each item in the '
               'person\'s own words, then: human-review --answers this-file', 'items': [
                   {k: i.get(k) for k in ('id', 'kind', 'where', 'question', 'measured', 'answer')} for i in items]})
    ps = [p for p in facts['placements'] if not p.get('unreadable')]
    music = [p for p in ps if p.get('kind') == 'music']
    look = [f'{p["file"]} stops at {ar.mmss(p["end_s"])} before its file ends, still sounding, between two lines'
            for p in ps if ar.is_cut_off(p)]
    covered = [p for p in ps if p.get('cut_while_sounding') and not p.get('end_between_lines')
               and not p.get('ends_with_the_film')]
    if covered:
        look.append(f'{len(covered)} sound(s) stop before their files end, still sounding, with a line over the cut: '
                    + ', '.join(f'{p["file"]} at {ar.mmss(p["end_s"])}' for p in covered[:8])
                    + (f' and {len(covered) - 8} more' if len(covered) > 8 else ''))
    look += [f'{p["file"]} could not be read' for p in facts['placements'] if p.get('unreadable')]
    measured = [p['in_export'] for p in ps if p.get('in_export')]
    look += [f'{p["file"]} at {ar.mmss(p["start_s"])}: {f.name} plays this passage '
             f'{abs(p["in_export"]["differs_db"]):g} dB {"louder" if p["in_export"]["differs_db"] < 0 else "quieter"} '
             f'against the voice than the project\'s sounds there ask for together '
             f'({p["in_export"]["under_voice_db"]:g} dB under the voice where they ask for '
             f'{p["in_export"]["project_asks_db"]:g}): a level the project\'s read-back does not carry (a volume move, '
             'a muted track), or another build'
             for p in ps if abs((p.get('in_export') or {}).get('differs_db') or 0) >= ar.EXPORT_DIFFERS_DB]
    if (facts.get('export') or {}).get('unreadable'):
        look.append(f'{f.name} has no sound this could read against the narration: is it the export of this project?')
    if not f:
        look += [f'{p["file"]} plays at clip volume {p["clip_volume"]:g}: its level is set in the project, not in its '
                 'file, and only the finished file shows what plays (sound-review --file)'
                 for p in facts['placements'] if p.get('clip_volume') is not None]
    # Where music is heard with no voice over it, and how much it comes up there: a film whose music never rises where
    # nobody speaks has one level for the whole of it (the audit of 2026-11-26: a closing theme at room-tone level).
    alone = facts.get('music_alone')
    if alone and alone.get('seconds') and alone.get('rises_when_alone_db') is not None:
        lg = alone.get('longest')
        span = f', never for longer than {lg[1] - lg[0]:.1f} s at a time (at {_mmss(lg[0])})' if lg else ''
        look.append(f'music is heard with no voice over it for {alone["seconds"]:g} s in all{span}; there it plays at '
                    f'most {max(0.0, alone["rises_when_alone_db"]):g} dB above its level under the words. Is there a '
                    'moment where the music is meant to be heard, and does the voice leave it room? (a held silence the '
                    'music carries, music that enters before the words or plays on after the last; bed-levels then '
                    'lifts the bed there)')
    # The mix beside the film's models, by the project's own files and in the finished file when it is measured
    beside = models_beside_facts(rd, n, f, sound=facts.get('between_words'))
    heard = [r for r in beside['rows'] if r['measure'] not in PICTURE_MEASURES]
    look += [dp['said'] for dp in beside['departures'] if dp['measure'] not in PICTURE_MEASURES]
    emit({'ok': True, 'video': n, 'record': str(rec_path), 'listening_sheet': str(sheet),
          'measured_in': f.name if f else 'the project\'s own files only (no finished file given: --file)',
          'listening_items': len(items), 'listening_minutes': round(sum(i['to_s'] - i['from_s'] for i in items) / 60, 1),
          'voice_speech_db': facts['speech_db'], 'sounds_placed': len(facts['placements']),
          'music_under_voice_db': ({'quietest': max(p['under_voice_db'] for p in music),
                                    'least_quiet': min(p['under_voice_db'] for p in music)} if music else None),
          'music_share_of_runtime': facts['beds']['music']['share_of_runtime'],
          'no_music_for_long': facts['beds']['music']['none_for_long'],
          'ambience_share_of_runtime': facts['beds']['ambience']['share_of_runtime'],
          'music_heard_alone': alone, 'sound_between_the_words': facts.get('between_words'),
          'beside_the_models': {'models': beside['models'], 'rows': heard, 'notes': beside['notes']},
          'craft_choices_asked': [dp['issue'] for dp in beside['departures'] if dp['issue']
                                  and dp['measure'] not in PICTURE_MEASURES],
          'file_against_project': ({'passages_measured': len(measured),
                                    'largest_difference_db': max(abs(x['differs_db']) for x in measured)}
                                   if measured else None),
          'ordinary_gap_s': facts['turns']['ordinary_gap_s'],
          'turns': [{k: t.get(k) for k in ('beat', 'why', 'next', 'at_s', 'gap_s')} for t in facts['turns']['turns']],
          'names_heard_differently': [x['term'] for x in facts['names']],
          'holds_not_listened': len(facts['holds_not_listened']), 'look_at': look,
          'next': 'Read look_at and the turns as places to examine, never as faults. Give the user the listening sheet '
                  'with the export: it is short on purpose. Record what they say with human-review (--answers for the '
                  'filled sheet). A listen is offered, never required; no check here stands in for one.'})


def cmd_deliverable(args):
    """Which file is the deliverable, and what stands between the project and it. With --file: what that file is to
    this video (the recorded master, the export it was made from, an export of an earlier build, or a file no record
    knows), with its own measured loudness. Reads only: nothing is written to the run."""
    rd, st = run_folder(args)
    n = int(args.video)
    d = deliverable_facts(rd, n)
    out = {'ok': True, 'video': n, **d}
    if args.file:
        f = Path(args.file).expanduser().resolve()
        if not f.is_file():
            error('File not found', str(f))
        sha, loud, said = file_sha256(f), loudness_stats(f), []
        role = export_role(rd, n, sha, loud, said, said)
        allx = read_json(export_provenance_path(rd, n)).get('exports') or {}
        out['this_file'] = {
            'file': str(f), 'sha256': sha, 'duration_s': probe(f).get('duration_s'), 'loudness': loud, 'is': role,
            'has_an_export_check': sha in allx,
            'of_the_project_as_it_stands': (sha in exports_of_current_project(rd, n)) if sha in allx else None,
            'checked_project_length_s': (read_json(timeline_check_path(rd, n)).get('snapshot') or {}).get('end_s'),
            'is_the_deliverable': bool(d['steps']['verified'] and read_json(release_path(rd, n)).get('sha256') == sha),
            'said': said}
    emit(out)


def cmd_human_review(args):
    """Record what a person did with one export, in their own words: listened, watched, both, or their word that they
    will not (waived). No agent can hear a film or watch it play; this is the only record that says a person did.
    --answers carries the filled listening sheet (its item ids to what the person said)."""
    rd, st = run_folder(args)
    n = int(args.video)
    f = Path(args.file).expanduser().resolve()
    if not f.is_file():
        error('File not found', str(f))
    if n_words(args.user_words) < 3:
        error('--user-words carries what the person said, in their own words (a few words at least). Never write it '
              'for them: no entry is better than an invented one.')
    answers = read_json(Path(args.answers), required=True) if args.answers else None
    sha = file_sha256(f)
    p = human_review_path(rd, n)
    rec = read_json(p) or {'video': n, 'reviews': []}
    rec.setdefault('reviews', []).append({
        'at': now(), 'file': str(f), 'sha256': sha, 'kind': args.kind, 'user_words': args.user_words.strip(),
        **({'answers': answers} if answers else {}), **({'sheet': str(args.sheet)} if args.sheet else {})})
    write_json(p, rec)
    emit({'ok': True, 'record': str(p), 'file': str(f), 'kind': args.kind, 'entries': len(rec['reviews']),
          'deliverable': deliverable_facts(rd, n)})


def main():
    # PC adapter: Windows pipes default to cp1252, so a reference name with a character outside it (s-cedilla, an emoji) made the
    # JSON output fail after the work was done; Claude Code sets PYTHONIOENCODING, a plain terminal does not.
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding='utf-8')
        except (AttributeError, ValueError, OSError):
            pass
    ap = argparse.ArgumentParser(description='Static-only long-form YouTube reference-to-video integrity toolkit')
    sub = ap.add_subparsers(dest='cmd', required=True)
    p = sub.add_parser('doctor'); p.add_argument('--whisper', action='store_true',
                                                 help='load Whisper medium on the GPU and run it once')
    p.add_argument('--file', help='with --whisper: also transcribe this file (nothing is written to a run)')
    p.set_defaults(func=cmd_doctor)
    p = sub.add_parser('init'); p.add_argument('--references', required=True); p.add_argument('--workspace')
    p.add_argument('--slug', default='story')
    p.add_argument('--fps', type=float, default=ANALYSIS_FPS, help='Reference analysis frames per second (2 by default; '
                   'kept by the run)')
    p.add_argument('--min-longform', type=int, default=DEFAULT_MIN_LONGFORM); p.set_defaults(func=cmd_init)
    p = sub.add_parser('clone'); p.add_argument('--from-run', required=True); p.add_argument('--workspace'); p.add_argument('--slug', default='clone'); p.set_defaults(func=cmd_clone)
    p = sub.add_parser('scan'); p.add_argument('--run', required=True); p.set_defaults(func=cmd_scan)
    p = sub.add_parser('prepare'); p.add_argument('--run', required=True); p.add_argument('--ids')
    p.add_argument('--fps', type=float); p.add_argument('--width', type=int, default=960)
    # Whisper medium on the GPU: the CUDA 12 runtime is installed for this interpreter (cuda_runtime_setup finds it).
    add_whisper_args(p); p.add_argument('--full-fps', action='store_true')
    p.add_argument('--skip-whisper', action='store_true'); p.add_argument('--dry-run', action='store_true')
    p.add_argument('--reason', default='', help='--skip-whisper: why this reference goes without its words')
    p.set_defaults(func=cmd_prepare)
    p = sub.add_parser('cohorts'); p.add_argument('--run', required=True); p.set_defaults(func=cmd_cohorts)
    p = sub.add_parser('analysis-plan', help='Split the reference analysis between agents by reading work alone (never '
                       'by subject): batches, one brief and one to-do file per agent')
